    private static final java.util.concurrent.ConcurrentHashMap<String, SmbVideoProxy> ACTIVE_SMB_VIDEO_PROXIES = new java.util.concurrent.ConcurrentHashMap<>();

    static void registerSmbVideoProxy(String url, SmbVideoProxy proxy) {
        if (url == null || proxy == null) return;
        SmbVideoProxy previous = ACTIVE_SMB_VIDEO_PROXIES.put(url, proxy);
        if (previous != null && previous != proxy) previous.stop();
    }

    static void stopSmbVideoProxy(String url) {
        if (url == null) return;
        SmbVideoProxy proxy = ACTIVE_SMB_VIDEO_PROXIES.get(url);
        if (proxy != null) proxy.stop();
    }

    private static void releaseSmbVideoForDeletion(String path) throws Exception {
        String target = comparableSmbPath(path);
        for (SmbVideoProxy proxy : ACTIVE_SMB_VIDEO_PROXIES.values()) {
            if (!target.equals(comparableSmbPath(proxy.source.getPath()))) continue;
            proxy.stop();
            proxy.awaitStopped();
        }
    }
