    private static final class FileClipboard {
        final File local;
        final jcifs.smb.SmbFile smb;
        final jcifs.CIFSContext context;
        final String shizukuPath;
        final boolean shizukuDirectory;
        FileClipboard(File local) { this.local = local; this.smb = null; this.context = null; this.shizukuPath = null; this.shizukuDirectory = false; }
        FileClipboard(jcifs.smb.SmbFile smb, jcifs.CIFSContext context) { this.local = null; this.smb = smb; this.context = context; this.shizukuPath = null; this.shizukuDirectory = false; }
        FileClipboard(String shizukuPath, boolean directory) { this.local = null; this.smb = null; this.context = null; this.shizukuPath = shizukuPath; this.shizukuDirectory = directory; }
        String name() { return local != null ? local.getName() : smb != null ? smb.getName().replaceAll("/+$", "") : shizukuPath == null ? "fichier" : new File(shizukuPath).getName(); }
    }
    private static final class SmbEntryMetadata {
        final String name;
        final boolean directory;
        final boolean videosFolder;
        final long modified;
        final long size;
        SmbEntryMetadata(String name, boolean directory, boolean videosFolder, long modified, long size) {
            this.name = name;
            this.directory = directory;
            this.videosFolder = videosFolder;
            this.modified = modified;
            this.size = size;
        }
    }
    private static final class SmbPhotoSource {
        final jcifs.smb.SmbFile file;
        final String name;
        final String key;
        volatile boolean visible;
        SmbPhotoSource(jcifs.smb.SmbFile file, SmbEntryMetadata metadata) {
            this.file = file;
            name = metadata.name;
            key = file.getPath() + "|" + metadata.size + "|" + metadata.modified;
        }
    }
    private static final class LocalPhotoSource {
        final File file;
        final String key;
        volatile boolean visible;
        LocalPhotoSource(File file, String key) { this.file = file; this.key = key; }
    }
    private boolean sameClipboard(FileClipboard left, FileClipboard right) { if (left == null || right == null) return false; if (left.local != null || right.local != null) return left.local != null && right.local != null && left.local.equals(right.local); if (left.smb != null || right.smb != null) return left.smb != null && right.smb != null && left.smb.getPath().equals(right.smb.getPath()); return left.shizukuPath != null && left.shizukuPath.equals(right.shizukuPath); }
    private void showMultiSelectionStatus(String message, int duration) { if (multiSelectionToast != null) multiSelectionToast.cancel(); multiSelectionToast = Toast.makeText(this, message, duration); multiSelectionToast.show(); }
    private void beginMultiSelection(FileClipboard item) { multiSelection.clear(); multiSelection.add(item); multiSelectMode = true; refreshMultiSelectionIndicators(); showMultiSelectionStatus("Sélection multiple : cliquez pour cocher, appui long sur un élément coché pour les actions", Toast.LENGTH_LONG); }
    private void toggleMultiSelection(FileClipboard item, View row) {
        // Do not walk the entire Activity view tree for every click. On a NAS
        // grid that tree also contains the header, background and every tile;
        // only the tile just toggled can have changed state.
        for (int i = 0; i < multiSelection.size(); i++) {
            if (!sameClipboard(multiSelection.get(i), item)) continue;
            multiSelection.remove(i);
            updateMultiSelectionBadge(row);
            showMultiSelectionStatus(multiSelection.size() + " sélectionné(s)", Toast.LENGTH_SHORT);
            return;
        }
        multiSelection.add(item);
        updateMultiSelectionBadge(row);
        showMultiSelectionStatus(multiSelection.size() + " sélectionné(s)", Toast.LENGTH_SHORT);
    }
    private boolean selectedForMulti(FileClipboard item) { for (FileClipboard candidate : multiSelection) if (sameClipboard(candidate, item)) return true; return false; }
    private void attachMultiSelectionBadge(FrameLayout container, FileClipboard item) { TextView badge = text("✓", 18, Color.rgb(93, 182, 27)); badge.setGravity(Gravity.CENTER); GradientDrawable background = new GradientDrawable(); background.setColor(Color.WHITE); background.setCornerRadius(dp(3)); background.setStroke(dp(1), Color.rgb(205, 216, 234)); badge.setBackground(background); badge.setVisibility(multiSelectMode ? View.VISIBLE : View.INVISIBLE); FrameLayout.LayoutParams params = new FrameLayout.LayoutParams(dp(23), dp(23), Gravity.TOP | Gravity.RIGHT); params.setMargins(0, dp(5), dp(5), 0); container.addView(badge, params); container.setTag(MULTI_ITEM_TAG, item); container.setTag(MULTI_BADGE_TAG, badge); updateMultiSelectionBadge(container); }
    private void updateMultiSelectionBadge(View view) { Object item = view.getTag(MULTI_ITEM_TAG), badge = view.getTag(MULTI_BADGE_TAG); if (item instanceof FileClipboard && badge instanceof TextView) { ((TextView) badge).setVisibility(multiSelectMode ? View.VISIBLE : View.INVISIBLE); ((TextView) badge).setTextColor(selectedForMulti((FileClipboard) item) ? Color.rgb(93, 182, 27) : Color.TRANSPARENT); } }
    private void refreshMultiSelectionIndicators() { View root = getWindow().getDecorView(); refreshMultiSelectionIndicators(root); }
    private void refreshMultiSelectionIndicators(View view) { updateMultiSelectionBadge(view); if (view instanceof ViewGroup) for (int i = 0; i < ((ViewGroup) view).getChildCount(); i++) refreshMultiSelectionIndicators(((ViewGroup) view).getChildAt(i)); }
    private ArrayList<FileClipboard> clipboardItems() { ArrayList<FileClipboard> result = new ArrayList<>(); if (!multiClipboard.isEmpty()) result.addAll(multiClipboard); else if (fileClipboard != null) result.add(fileClipboard); return result; }
    private boolean hasClipboardItems() { return !multiClipboard.isEmpty() || fileClipboard != null; }
    private void clearClipboard() { fileClipboard = null; multiClipboard.clear(); clipboardCut = false; }
