    private static final class WeatherSnapshot {
        final String city;
        final String currentTemperature;
        final String currentCondition;
        final String[] forecastDays;
        final String[] forecastTemperatures;
        final String[] forecastConditions;

        WeatherSnapshot(String city, String currentTemperature, String currentCondition,
                String[] forecastDays, String[] forecastTemperatures, String[] forecastConditions) {
            this.city = city;
            this.currentTemperature = currentTemperature;
            this.currentCondition = currentCondition;
            this.forecastDays = forecastDays;
            this.forecastTemperatures = forecastTemperatures;
            this.forecastConditions = forecastConditions;
        }

        boolean sameAs(WeatherSnapshot other) {
            return other != null
                    && java.util.Objects.equals(city, other.city)
                    && java.util.Objects.equals(currentTemperature, other.currentTemperature)
                    && java.util.Objects.equals(currentCondition, other.currentCondition)
                    && java.util.Arrays.equals(forecastDays, other.forecastDays)
                    && java.util.Arrays.equals(forecastTemperatures, other.forecastTemperatures)
                    && java.util.Arrays.equals(forecastConditions, other.forecastConditions);
        }
    }
    private static final class WeatherWidgetViews {
        final View root;
        final ImageView icon;
        final TextView label;
        final TextView currentTemperature;
        final ImageView[] forecastIcons;
        final TextView[] forecastDays;
        final TextView[] forecastTemperatures;
        WeatherWidgetViews(View root, ImageView icon, TextView label, TextView currentTemperature, ImageView[] forecastIcons, TextView[] forecastDays, TextView[] forecastTemperatures) {
            this.root = root;
            this.icon = icon;
            this.label = label;
            this.currentTemperature = currentTemperature;
            this.forecastIcons = forecastIcons;
            this.forecastDays = forecastDays;
            this.forecastTemperatures = forecastTemperatures;
        }
    }
    private int dp(float value) { return (int) (value * getResources().getDisplayMetrics().density + .5f); }
    private int safeEdgeInset() {
        int screenSize = Math.min(getResources().getDisplayMetrics().widthPixels, getResources().getDisplayMetrics().heightPixels);
        int safe = Math.round(screenSize * 0.05f);
        return Math.max(dp(24), Math.min(dp(48), safe));
    }
    private int safeBottomInset() {
        int screenSize = getResources().getDisplayMetrics().heightPixels;
        int safe = Math.round(screenSize * 0.05f);
        return Math.max(dp(27), Math.min(dp(48), safe));
    }

    @Override public void onCreate(Bundle state) {
        android.os.Trace.beginSection("JojoHome/activity-create");
        try {
            super.onCreate(state);
        } finally {
            android.os.Trace.endSection();
        }
        com.jojotv.home.iptv.IptvCompanionRuntime.bindHome(this);
        // Reattach the Fire OS Home detector after an APK update or a manual
        // launch. The preference is intentionally idempotent and Fire TV-only.
        FireOsHomeButtonService.startIfEnabled(this);
        Shizuku.addRequestPermissionResultListener((requestCode, grantResult) -> { if (requestCode == ShizukuFiles.PERMISSION_REQUEST_CODE) runOnUiThread(() -> {
            if (grantResult == PackageManager.PERMISSION_GRANTED) {
                if (pendingShizukuPath != null) {
                    String path = pendingShizukuPath;
                    pendingShizukuPath = null;
                    replaceScreen(createShizukuBrowser(path));
                } else if (activeScreen != null) {
                    View test = activeScreen.findViewWithTag("shizuku_startup_test");
                    if (test instanceof TextView) {
                        setSettingValue((TextView) test, "Configurer et tester Shizuku", ShizukuFiles.startupStatus());
                    }
                }
            } else Toast.makeText(this, "Autorisation Shizuku refusée", Toast.LENGTH_LONG).show();
        }); });
        migrateWeatherSettingsToDeviceKeys();
        restoreCachedWeather();
        homePrefs().registerOnSharedPreferenceChangeListener(nasAutoSyncListener);
        homePrefs().registerOnSharedPreferenceChangeListener(notificationResumeItemsListener);
        homeResumeSettingsPending = !homePrefs().getString("nas_token", "").isEmpty();
        hideSystemBars();
        registerVpnNetworkCallback();
        android.os.Trace.beginSection("JojoHome/create-home");
        try {
            goHome();
        } finally {
            android.os.Trace.endSection();
        }
        hideFireOsBootCoverAfterHomeCreated();
        getWindow().getDecorView().postDelayed(this::retryWeatherIfMissing, 600L);
        getWindow().getDecorView().postDelayed(this::retryWeatherIfMissing, 2_000L);
        scheduleVpnHeaderRefresh();
        Runnable finishHomeSetup = () -> {
            setupWatchNextIntegration();
            setupJojoBridgeObserver();
            consumeConfirmedJojoHomeRestoreOnLaunch();
            restoreHomeSettingsFromNas(false);
        };
        // Publish the Home frame before provider registration and NAS startup
        // on Android TV as well as Fire OS.
        View decor = getWindow().getDecorView();
        decor.postOnAnimation(() -> decor.post(() -> {
            if (!isFinishing() && !isDestroyed()) finishHomeSetup.run();
        }));
    }
    @Override protected void onResume() {
        super.onResume();
        homeActivityResumed = true;
        IptvStore.observeHomeChanges(iptvHomeChangeObserver);
        // Refresh retained badges from memory before drawing the return frame.
        refreshVisiblePlaybackBadges();
        if (activePhotoSlideshow != null) activePhotoSlideshow.setActive(hasWindowFocus());
        FireOsHomeButtonService.onHomeVisibilityChanged(true);
        refreshHomeHeaderAccount();
        refreshActiveWeatherWidget();
        for (HorizontalScrollView scroll : new ArrayList<>(continueWatchingCarouselAdvancers.keySet())) {
            if (scroll.isAttachedToWindow()) scheduleContinueWatchingAutoScroll(scroll, HOME_HERO_AUTO_ADVANCE_MS);
        }
        View focused = getCurrentFocus();
        HorizontalScrollView focusedScroll = continueWatchingScroll(focused);
        if (focusedScroll != null && !continueWatchingCarouselAdvancers.containsKey(focusedScroll)) {
            wireContinueWatchingAutoScroll(focused);
        }
        final long resumeGeneration = ++homeResumeGeneration;
        View decor = getWindow().getDecorView();
        // Run refreshes after this frame's traversal so the retained content
        // is drawn before services, providers or resume updates can delay it.
        decor.postOnAnimation(() -> decor.post(() -> {
            if (homeActivityResumed && resumeGeneration == homeResumeGeneration
                    && !isFinishing() && !isDestroyed()) refreshHomeAfterResume();
        }));
    }
    private void refreshHomeAfterResume() {
        ShizukuFiles.startIfEnabled(getApplicationContext());
        nasAutoSyncHandler.removeCallbacks(iptvSyncRefreshRunnable);
        nasAutoSyncHandler.post(iptvSyncRefreshRunnable);
        startHomeWatchProgressObserver();
        pendingResumeDismissals.retainAll(homePrefs().getStringSet(
                JOJOTV_HOME_HIDDEN_RESUME_KEYS, Collections.emptySet()));
        boolean rebuildHomeAfterReturn = homeWasVisibleBeforePause;
        homeWasVisibleBeforePause = false;
        setupWatchNextIntegration();
        setupJojoBridgeObserver();
        scheduleVpnHeaderRefresh();
        refreshHeaderDateTime();
        requestNotificationResumeFallbackRefresh();
        headerTimeRefreshHandler.removeCallbacks(headerTimeRefreshRunnable);
        headerTimeRefreshHandler.postDelayed(headerTimeRefreshRunnable, 1000L);
        boolean resumeRefreshPending = homePrefs().getBoolean("nas_home_pending", false);
        if (resumeRefreshPending) {
            syncHomeSettingsToNas();
            // A player exit writes the new Freebox resume before this Activity
            // returns. The cached global rail may still contain the previous
            // list, which made the card appear only after the delayed refresh.
            // Keep the last known rail visible while the new provider/NAS
            // snapshot is loaded. Clearing it here caused a long empty rail
            // followed by a delayed rebuild and focus loss.
        }
        nasAutoSyncHandler.removeCallbacks(nasAutoRestoreRunnable);
        nasAutoSyncHandler.postDelayed(nasAutoRestoreRunnable, 700L);
        if (activeScreen == null) reconcileUninstalledFavoriteTiles();
        scheduleJojoHomeResumeRefresh(0L);
        boolean smartTubeResumePublished = publishPendingSmartTubeResume();
        boolean refreshHomeAfterReturn = resumeRefreshPending || smartTubeResumePublished || rebuildHomeAfterReturn;
        if (rebuildHomeAfterReturn && activeScreen == null) {
            // Make the previous Home hierarchy interactive immediately. The
            // data refresh is coalesced below so returning from a player or an
            // application cannot repeatedly destroy the focused view.
            restoreHomeFocusIfNeeded();
        }
        if (refreshHomeAfterReturn && activeScreen == null) {
            // Playback writes refresh Continue Watching. Keep the Freebox
            // rail attached so its asynchronous SMB scan cannot steal focus.
            scheduleHomeReturnRefresh(false, 120L);
        }
        // The SMB share can be changed from another computer while Jojo Home
        // remains suspended or in the background.  Do not rely on the local
        // cache or on the resume-pending flag: reconcile Freebox/Vidéos on
        // every return to the Home activity so additions and deletions made
        // outside the app become visible without a process restart.
        if (activeScreen == null) {
            homeReturnRefreshHandler.removeCallbacks(freeboxHomePollRunnable);
            homeReturnRefreshHandler.postDelayed(freeboxHomePollRunnable, 10_000L);
        }
        // Rebuild the Home focus tree at most once when returning from an
        // external player. Two successive goHome() calls could leave focus on
        // Search or in the external player window.
        if (rebuildHomeAfterReturn && activeScreen == null && currentHomePage == null) goHome();
        if (!pendingMediaStoreDelete && pendingLocalDelete != null) {
            boolean legacyWriteGranted = Build.VERSION.SDK_INT > 29
                    || checkSelfPermission(Manifest.permission.WRITE_EXTERNAL_STORAGE) == PackageManager.PERMISSION_GRANTED;
            boolean modernWriteGranted = Build.VERSION.SDK_INT < 30 || hasSharedStorageAccess();
            if (legacyWriteGranted && modernWriteGranted) {
                File target = pendingLocalDelete;
                pendingLocalDelete = null;
                deleteLocal(target);
            }
        }
        // SmartTube updates Android TV PreviewPrograms, not WatchNextPrograms.
        // Returning from its player must therefore reload the actual Home rail.
        if (rebuildHomeAfterReturn && activeScreen == null) {
            scheduleWatchNextRefresh();
        }
        maybeShowInstalledAppOverlay();
        schedulePendingHomeDpadRefresh();
    }

    @Override protected void onNewIntent(Intent intent) {
        super.onNewIntent(intent);
        setIntent(intent);
        if (intent != null && Intent.ACTION_MAIN.equals(intent.getAction()) &&
                (intent.hasCategory(Intent.CATEGORY_HOME)
                        || intent.hasCategory(Intent.CATEGORY_LEANBACK_LAUNCHER)
                        || intent.hasCategory(Intent.CATEGORY_LAUNCHER))) {
            publishPendingSmartTubeResume();
            goHome();
            hideFireOsBootCoverAfterHomeCreated();
        }
    }

    private void hideFireOsBootCoverAfterHomeCreated() {
        if (!fireTvHomeRedirectEnabled() || !FireOsHomeOverlayService.isSupportedDevice()) return;
        getWindow().getDecorView().postDelayed(
                () -> FireOsHomeOverlayService.hideBootCover(this), 120L);
    }
    @Override public void onWindowFocusChanged(boolean hasFocus) {
        super.onWindowFocusChanged(hasFocus);
        if (activePhotoSlideshow != null) activePhotoSlideshow.setActive(hasFocus && homeActivityResumed);
        android.util.Log.i("JojoHomeFreeboxTrace", "HOME_WINDOW_FOCUS at=" + android.os.SystemClock.elapsedRealtime() + " hasFocus=" + hasFocus);
        if (!hasFocus) {
            releaseRemotePress();
            suppressedRemotePressView = null;
            finishHomeDpadNavigation();
            return;
        }
        hideSystemBars();
        restoreHomeFocusIfNeeded();
        schedulePendingHomeDpadRefresh();
        if (fireTvHomeRedirectEnabled() && FireOsHomeOverlayService.isSupportedDevice()) {
            // Fire OS 6 can suppress ViewTreeObserver's draw callback while
            // the system overlay is present. Window focus is the reliable
            // signal that Jojo Home's surface has been accepted.
            getWindow().getDecorView().postDelayed(
                    () -> FireOsHomeOverlayService.hideBootCover(this), 60L);
        }
    }
    @Override protected void onPause() {
        homeActivityResumed = false;
        IptvStore.removeHomeChangeObserver(iptvHomeChangeObserver);
        nasAutoSyncHandler.removeCallbacks(iptvHomeChangedRefresh);
        if (activePhotoSlideshow != null) activePhotoSlideshow.setActive(false);
        homeResumeQueryGeneration++;
        homeResumeQueryExecutor.getQueue().clear();
        FireOsHomeButtonService.onHomeVisibilityChanged(false);
        nasAutoSyncHandler.removeCallbacks(iptvSyncRefreshRunnable);
        // An attached Home view can remain behind the player. Stop its Hero
        // before it allocates another full-size image during playback.
        for (HorizontalScrollView scroll : new ArrayList<>(continueWatchingAutoScrolls.keySet())) {
            cancelContinueWatchingAutoScroll(scroll, true);
        }
        homeResumeGeneration++;
        stopHomeWatchProgressObserver();
        releaseRemotePress();
        suppressedRemotePressView = null;
        homeFocusGeneration++;
        homeWasVisibleBeforePause = activeScreen == null;
        rememberHomeFocus();
        finishHomeDpadNavigation();
        super.onPause();
        homeReturnRefreshHandler.removeCallbacks(freeboxHomePollRunnable);
        weatherRefreshHandler.removeCallbacks(weatherAutoRefreshRunnable);
        headerTimeRefreshHandler.removeCallbacks(headerTimeRefreshRunnable);
        jojoResumeRefreshHandler.removeCallbacks(jojoResumeRefreshRunnable);
        if (homePrefs().getBoolean("nas_home_pending", false)) syncHomeSettingsToNas();
    }
    @Override protected void onDestroy() {
        if (activePhotoSlideshow != null) {
            activePhotoSlideshow.setActive(false);
            activePhotoSlideshow = null;
        }
        com.jojotv.home.iptv.IptvCompanionRuntime.unbindHome(this);
        smbDurationWork.shutdownNow();
        synchronized (smbDurationRequests) { smbDurationRequests.clear(); }
        homeFocusGeneration++;
        if (homeWatchProgressBridge != null) {
            homeWatchProgressBridge.close();
            homeWatchProgressBridge = null;
        }
        resumeMutationExecutor.shutdown();
        homeResumeQueryExecutor.shutdownNow();
        homeAccountExecutor.shutdown();
        homeAccountSelectionExecutor.shutdown();
        onlineAppIconSearchExecutor.shutdownNow();
        homeSuggestionArtworkExecutor.shutdownNow();
        smbPhotoThumbnailExecutor.shutdownNow();
        photoViewerExecutor.shutdownNow();
        photoCarouselPreviewExecutor.shutdownNow();
        smbPhotoBitmapCache.evictAll();
        smbPhotoMetadata.evictAll();
        ++weatherGeneration;
        cancelWeatherLocationRequest();
        watchNextRefreshHandler.removeCallbacks(watchNextRefreshRunnable);
        weatherRefreshHandler.removeCallbacks(weatherAutoRefreshRunnable);
        headerTimeRefreshHandler.removeCallbacksAndMessages(null);
        vpnHeaderRefreshHandler.removeCallbacksAndMessages(null);
        nasAutoSyncHandler.removeCallbacksAndMessages(null);
        jojoResumeRefreshHandler.removeCallbacksAndMessages(null);
        homeReturnRefreshHandler.removeCallbacksAndMessages(null);
        unregisterVpnNetworkCallback();
        homePrefs().unregisterOnSharedPreferenceChangeListener(nasAutoSyncListener);
        homePrefs().unregisterOnSharedPreferenceChangeListener(notificationResumeItemsListener);
        notificationResumeRefreshHandler.removeCallbacksAndMessages(null);
        if (watchNextObserverRegistered) getContentResolver().unregisterContentObserver(watchNextContentObserver);
        if (jojoBridgeObserverRegistered) getContentResolver().unregisterContentObserver(jojoBridgeContentObserver);
        artworkLoadExecutor.shutdownNow();
        cachedArtworkLoadExecutor.shutdownNow();
        super.onDestroy();
    }

    private void startHomeWatchProgressObserver() {
        try {
            if (homeWatchProgressBridge == null) homeWatchProgressBridge = HomeWatchProgressBridge.create(this);
            int activeProfileId = homeWatchProgressBridge.activeProfileId();
            if (watchProgressSnapshotProfileId != activeProfileId) {
                watchProgressSnapshotProfileId = activeProfileId;
                watchProgressContinueSnapshot = Collections.emptyList();
                if (homeActivityResumed && activeScreen == null) refreshHomeResumeSectionInPlace();
            }
            homeWatchProgressBridge.start((profileId, progress) -> {
                if (isFinishing() || isDestroyed()) return;
                List<WatchProgress> snapshot = Collections.unmodifiableList(new ArrayList<>(progress));
                boolean profileChanged = watchProgressSnapshotProfileId != profileId;
                boolean changed = profileChanged || !watchProgressContinueSnapshot.equals(snapshot);
                long previousLatest = watchProgressContinueSnapshot.isEmpty() ? 0L
                        : watchProgressContinueSnapshot.get(0).getLastWatched();
                watchProgressSnapshotProfileId = profileId;
                watchProgressContinueSnapshot = snapshot;
                if (changed && homeActivityResumed) {
                    refreshVisiblePlaybackBadges();
                    if (activeScreen != null && activeScreen == homeCategoryPageView
                            && !"videos".equals(homeCategoryPageCategory))
                        refreshActiveHomeCategoryPage();
                    else if (activeScreen != null && activeScreen.getTag(SERIES_PAGE_REFRESH_TAG) instanceof Runnable)
                        ((Runnable) activeScreen.getTag(SERIES_PAGE_REFRESH_TAG)).run();
                }
                if (!snapshot.isEmpty() && snapshot.get(0).getLastWatched() > previousLatest) {
                    List<JojoProgram> playable = watchProgressHomePrograms();
                    if (!playable.isEmpty()) pendingSyncedHeroKey = resumeProgramKey(playable.get(0));
                }
                if (changed && homeActivityResumed && activeScreen == null) {
                    notificationResumeRefreshHandler.removeCallbacks(notificationResumeHomeRefreshRunnable);
                    if (profileChanged) refreshHomeResumeSectionInPlace();
                    else notificationResumeRefreshHandler.postDelayed(notificationResumeHomeRefreshRunnable, 120L);
                }
            });
        } catch (Exception error) {
            android.util.Log.w("JojoHomeResume", "Watch progress observer could not start", error);
        }
    }

    private void stopHomeWatchProgressObserver() {
        if (homeWatchProgressBridge != null) homeWatchProgressBridge.stop();
    }

