    private long homeVideoArtworkRevision;
    private final Runnable homeVideoArtworkRefreshRunnable = () -> {
        if (isDestroyed() || !MainActivity.this.homeActivityResumed) return;
        for (Map.Entry<ImageView, String> entry : new ArrayList<>(homeVideosFileArtworkViews.entrySet())) {
            ImageView image = entry.getKey();
            if (image == null || !image.isAttachedToWindow()) continue;
            String selected = homeVideosFileArtwork(entry.getValue());
            if (!selected.isEmpty()) loadArtwork(image, selected);
        }
        for (Map.Entry<ImageView, String> entry : new ArrayList<>(homeVideosFileHeroArtworkViews.entrySet())) {
            ImageView image = entry.getKey();
            if (image == null || !image.isAttachedToWindow()) continue;
            String selected = homeVideosFileHeroArtwork(entry.getValue(), null);
            if (!selected.isEmpty()) loadArtwork(image, selected);
        }
        refreshVisibleHomeVideoHeroMetadata(activeScreen == null ? currentHomeResumesView : activeScreen);
        refreshEmptyHomeSuggestions();
        if (activeScreen == null) refreshHomeResumeSectionInPlace();
    };
