    private final android.content.SharedPreferences.OnSharedPreferenceChangeListener notificationResumeItemsListener =
            (preferences, key) -> {
                if (com.jojotv.home.progresspilot.AccountSettingsRouting.isHomeArtworkPreference(key)) {
                    homeVideoArtworkRevision++;
                    homeArtworkRefreshPending = true;
                    notificationResumeRefreshHandler.removeCallbacks(homeVideoArtworkRefreshRunnable);
                    notificationResumeRefreshHandler.postDelayed(homeVideoArtworkRefreshRunnable, 120L);
                    return;
                }
                if (key != null && key.startsWith("tmdb_title_logo_original_v" + HomeMediaRules.TITLE_LOGO_POLICY_VERSION + "_")) {
                    homeTitleLogoRefreshPending = true;
                    if (MainActivity.this.homeActivityResumed && activeScreen == null) {
                        notificationResumeRefreshHandler.removeCallbacks(notificationResumeHomeRefreshRunnable);
                        notificationResumeRefreshHandler.postDelayed(notificationResumeHomeRefreshRunnable, 120L);
                    }
                    return;
                }
                if (key != null && key.startsWith("video_player_metadata_")) {
                    // The player's background save can finish after the return frame.
                    if (MainActivity.this.homeActivityResumed) refreshVisibleHomeVideoHeroMetadata(
                            activeScreen == null ? currentHomeResumesView : activeScreen);
                    return;
                }
                if (FILE_VIDEO_RESUMES.equals(key) || (key != null && key.startsWith("video_resume_"))) {
                    // File progress is also saved asynchronously after the player closes.
                    if (MainActivity.this.homeActivityResumed) refreshVisiblePlaybackBadges();
                    return;
                }
                if (!NotificationResumeListenerService.ITEMS_KEY.equals(key)
                        && !com.jojotv.home.progresspilot.AccountSettingsRouting.NETFLIX_CHANGED.equals(key)
                        && (key == null || (!key.startsWith(SHARED_EXTERNAL_RESUME_PREFIX)
                            && !key.startsWith(SHARED_EXTERNAL_ARTWORK_PREFIX)
                            && !com.jojotv.home.progresspilot.AccountSettingsRouting.isResumeMaskPreference(key)))) return;
                notificationResumeRefreshHandler.removeCallbacks(notificationResumeHomeRefreshRunnable);
                notificationResumeRefreshHandler.postDelayed(notificationResumeHomeRefreshRunnable, 120L);
            };
