    // WireGuard can already be connected while Android is still republishing
    // the VPN transport after the launcher process starts.  A callback alone
    // is not sufficient in that race: its first delivery can precede the Home
    // header's attachment, leaving the icon hidden until the VPN app is opened.
    private final Handler vpnHeaderRefreshHandler = new Handler(Looper.getMainLooper());
    private final Runnable vpnHeaderRefreshRunnable = () -> {
        refreshVpnHeader();
        if (!isVpnActive()) scheduleNextVpnStartupRefresh();
    };
    private final ConnectivityManager.NetworkCallback vpnNetworkCallback = new ConnectivityManager.NetworkCallback() {
        @Override public void onAvailable(Network network) { scheduleVpnHeaderRefresh(); }
        @Override public void onLost(Network network) { scheduleVpnHeaderRefresh(); }
        @Override public void onCapabilitiesChanged(Network network, NetworkCapabilities capabilities) { scheduleVpnHeaderRefresh(); }
    };
    // Some Fire OS builds do not dispatch a transport-VPN callback until the
    // WireGuard UI is resumed.  The default-network callback still arrives
    // when WireGuard makes the tunnel the route, letting the actual VPN check
    // below see the newly published network.
    private final ConnectivityManager.NetworkCallback defaultNetworkCallback = new ConnectivityManager.NetworkCallback() {
        @Override public void onAvailable(Network network) {
            scheduleVpnHeaderRefresh();
            scheduleHomeResumeRefreshWhenNetworkAvailable();
        }
        @Override public void onLost(Network network) { scheduleVpnHeaderRefresh(); }
        @Override public void onCapabilitiesChanged(Network network, NetworkCapabilities capabilities) {
            scheduleVpnHeaderRefresh();
            scheduleHomeResumeRefreshWhenNetworkAvailable();
        }
    };
    private void scheduleHomeResumeRefreshWhenNetworkAvailable() {
        jojoResumeRefreshHandler.post(() -> {
            if (homeActivityResumed) scheduleJojoHomeResumeRefresh(0L);
        });
    }
    private void trackPopup(PopupWindow popup) {
        rememberHomeFocus();
        PopupWindow previous = activePopup;
        activePopup = null;
        if (previous != null && previous.isShowing()) previous.dismiss();
        activePopup = popup;
        popup.setOnDismissListener(() -> {
            if (activePopup == popup) activePopup = null;
            dismissTransientMarquee();
            restoreHomeFocusIfNeeded();
        });
    }
    private void showPopupCenteredOnScreen(PopupWindow popup) {
        // Affiche un popup au centre de l'écran, sans clipping aux bords
        int screenWidth = getResources().getDisplayMetrics().widthPixels;
        int screenHeight = getResources().getDisplayMetrics().heightPixels;
        int popupWidth = popup.getWidth() > 0 ? popup.getWidth() : 300;
        int popupHeight = popup.getHeight() > 0 ? popup.getHeight() : 200;
        int x = Math.max(dp(12), (screenWidth - popupWidth) / 2);
        int y = Math.max(dp(12), Math.min(screenHeight - popupHeight - dp(60), (screenHeight - popupHeight) / 2));
        popup.showAtLocation(getWindow().getDecorView(), Gravity.NO_GRAVITY, x, y);
    }
    /** Settings choice lists belong in a stable left-hand overlay, never above or below their card. */
    private void showPopupLeftCenteredOnScreen(PopupWindow popup) {
        int screenHeight = getResources().getDisplayMetrics().heightPixels;
        int popupHeight = popup.getHeight() > 0 ? popup.getHeight() : dp(200);
        int x = dp(40);
        int y = Math.max(dp(12), (screenHeight - popupHeight) / 2);
        popup.showAtLocation(getWindow().getDecorView(), Gravity.NO_GRAVITY, x, y);
    }
    private void showPopupBelow(PopupWindow popup, View anchor) {
        showPopupBelow(popup, anchor, 0, dp(4));
    }
    private void showPopupBelow(PopupWindow popup, View anchor, int xOffset, int yOffset) {
        popup.setClippingEnabled(false);
        int[] location = new int[2];
        anchor.getLocationOnScreen(location);
        int screenWidth = getResources().getDisplayMetrics().widthPixels;
        int screenHeight = getResources().getDisplayMetrics().heightPixels;
        int popupWidth = popup.getWidth();
        int popupHeight = popup.getHeight();
        if (popupWidth <= 0 || popupHeight <= 0) {
            popup.getContentView().measure(View.MeasureSpec.makeMeasureSpec(screenWidth, View.MeasureSpec.AT_MOST), View.MeasureSpec.makeMeasureSpec(screenHeight, View.MeasureSpec.AT_MOST));
            popupWidth = popup.getContentView().getMeasuredWidth();
            popupHeight = popup.getContentView().getMeasuredHeight();
        }
        int x = location[0] + xOffset;
        int y = location[1] + anchor.getHeight() + yOffset;
        if (x + popupWidth > screenWidth - dp(12)) x = screenWidth - popupWidth - dp(12);
        if (x < dp(12)) x = dp(12);
        if (y + popupHeight > screenHeight - dp(40)) {
            y = location[1] - popupHeight - yOffset;
        }
        if (y < dp(12)) y = dp(12);
        popup.showAtLocation(getWindow().getDecorView(), Gravity.NO_GRAVITY, x, y);
    }

    /** Position a settings choice list beside its card without covering it. */
    private void showChoicePopupBesideAnchor(PopupWindow popup, View anchor) {
        popup.setClippingEnabled(false);
        int[] location = new int[2];
        anchor.getLocationOnScreen(location);
        int screenWidth = getResources().getDisplayMetrics().widthPixels;
        int screenHeight = getResources().getDisplayMetrics().heightPixels;
        int popupWidth = popup.getWidth() > 0 ? popup.getWidth() : dp(280);
        int popupHeight = popup.getHeight() > 0 ? popup.getHeight() : dp(200);
        int gap = dp(12);
        int x = location[0] + anchor.getWidth() + gap;
        if (x + popupWidth > screenWidth - dp(12)) {
            x = location[0] - popupWidth - gap;
        }
        if (Boolean.TRUE.equals(anchor.getTag(SETTINGS_SURFACE_TAG))) {
            x = location[0] + Math.max(0, anchor.getWidth() - popupWidth - dp(12));
        }
        x = Math.max(dp(12), Math.min(x, screenWidth - popupWidth - dp(12)));
        int y = location[1];
        if (y + popupHeight > screenHeight - dp(12)) {
            y = screenHeight - popupHeight - dp(12);
        }
        y = Math.max(dp(12), y);
        popup.showAtLocation(getWindow().getDecorView(), Gravity.NO_GRAVITY, x, y);
    }

    private void showTransientMarquee(String text) {
        dismissTransientMarquee();
        TextView tv = new TextView(this);
        tv.setText(text);
        tv.setTextColor(Color.WHITE);
        tv.setTextSize(18);
        tv.setSingleLine(true);
        tv.setEllipsize(TextUtils.TruncateAt.MARQUEE);
        tv.setMarqueeRepeatLimit(-1);
        tv.setSelected(true);
        int pad = dp(12);
        tv.setPadding(pad, dp(6), pad, dp(6));
        tv.setBackground(lightMenuBg());
        marqueePopup = new PopupWindow(tv, ViewGroup.LayoutParams.WRAP_CONTENT, dp(40), false);
        marqueePopup.setOutsideTouchable(true);
        marqueePopup.setTouchable(false);
        marqueePopup.setClippingEnabled(false);
        int y = safeEdgeInset();
        marqueePopup.showAtLocation(getWindow().getDecorView(), Gravity.TOP | Gravity.CENTER_HORIZONTAL, 0, y);
        tv.postDelayed(this::dismissTransientMarquee, 2200);
    }

    private void dismissTransientMarquee() {
        if (marqueePopup != null) {
            try { marqueePopup.dismiss(); } catch (Exception ignored) {}
            marqueePopup = null;
        }
    }
    private void registerVpnNetworkCallback() {
        if (Build.VERSION.SDK_INT < 24 || vpnNetworkCallbackRegistered) return;
        ConnectivityManager connectivity = (ConnectivityManager) getSystemService(CONNECTIVITY_SERVICE);
        if (connectivity == null) return;
        try {
            android.net.NetworkRequest request = new android.net.NetworkRequest.Builder()
                    .addTransportType(NetworkCapabilities.TRANSPORT_VPN)
                    .build();
            connectivity.registerNetworkCallback(request, vpnNetworkCallback);
            vpnNetworkCallbackRegistered = true;
        } catch (Exception ignored) { }
        try {
            connectivity.registerDefaultNetworkCallback(defaultNetworkCallback);
            defaultNetworkCallbackRegistered = true;
        } catch (Exception ignored) { }
    }
    private void unregisterVpnNetworkCallback() {
        ConnectivityManager connectivity = (ConnectivityManager) getSystemService(CONNECTIVITY_SERVICE);
        if (vpnNetworkCallbackRegistered) try { if (connectivity != null) connectivity.unregisterNetworkCallback(vpnNetworkCallback); } catch (Exception ignored) { }
        if (defaultNetworkCallbackRegistered) try { if (connectivity != null) connectivity.unregisterNetworkCallback(defaultNetworkCallback); } catch (Exception ignored) { }
        vpnNetworkCallbackRegistered = false;
        defaultNetworkCallbackRegistered = false;
    }
    private void refreshVpnHeader() {
        runOnUiThread(() -> {
            refreshNetworkHeader();
            retryWeatherIfMissing();
            boolean active = isVpnActive();
            if (activeVpnHeaderCommand != null) {
                boolean showVpn = VpnHeaderRules.showsVpn(active);
                boolean wasFocused = activeVpnHeaderCommand.hasFocus();
                activeVpnHeaderCommand.setVisibility(showVpn ? View.VISIBLE : View.GONE);
                View badge = activeVpnHeaderCommand.findViewWithTag("vpn_badge");
                if (badge != null) {
                    badge.setVisibility(showVpn ? View.VISIBLE : View.GONE);
                    if (showVpn) badge.setBackground(networkBadgeBg(2));
                }
                if (!showVpn && wasFocused && currentTopBarHeader != null) {
                    View focusTarget = currentTopBarHeader.findViewWithTag("search");
                    if (focusTarget == null || focusTarget.getVisibility() != View.VISIBLE) {
                        focusTarget = currentTopBarHeader.findViewWithTag("apps");
                    }
                    if (focusTarget != null && focusTarget.getVisibility() == View.VISIBLE) {
                        focusTarget.requestFocus();
                    }
                }
            }
            if (currentTopBarHeader != null && currentTopBarHeader.getTag() instanceof LinearLayout) {
                LinearLayout bar = (LinearLayout) currentTopBarHeader.getTag();
                layoutTopBarItems(bar);
                wireTopBarHorizontalFocus(bar);
            }
        });
    }

    /** Retry only an initial/failed load after the network becomes usable. */
    private void retryWeatherIfMissing() {
        if (cachedWeather != null || weatherRequestInFlight || !weatherWidgetEnabled()) return;
        WeatherWidgetViews weather = activeWeatherWidget;
        if (weather == null || !weather.root.isAttachedToWindow()) return;
        refreshWeather(weather.icon, weather.label, weather.currentTemperature,
                weather.forecastIcons, weather.forecastDays, weather.forecastTemperatures);
    }
    private void refreshNetworkHeader() {
        if (networkHeaderIcon == null || networkHeaderBadge == null) return;
        int state = networkState();
        boolean focused = networkHeaderCommand != null && networkHeaderCommand.isFocused();
        networkHeaderIcon.setImageResource(focused ? networkIconFocusedResource() : networkIconResource());
        networkHeaderBadge.setText(state == 2 ? "✓" : state == 1 ? "!" : "×");
        networkHeaderBadge.setContentDescription(state == 2
                ? "Connexion Internet disponible"
                : state == 1 ? "Réseau sans accès Internet" : "Réseau indisponible");
        networkHeaderBadge.setBackground(networkBadgeBg(state));
    }
    private void scheduleVpnHeaderRefresh() {
        vpnHeaderRefreshHandler.removeCallbacks(vpnHeaderRefreshRunnable);
        vpnStartupRefreshAttempt = 0;
        refreshVpnHeader();
        scheduleNextVpnStartupRefresh();
    }
    private void scheduleNextVpnStartupRefresh() {
        final long[] delays = new long[] { 250L, 1_200L, 3_000L, 6_000L, 10_000L, 20_000L, 30_000L };
        if (vpnStartupRefreshAttempt >= delays.length) return;
        long delay = delays[vpnStartupRefreshAttempt++];
        vpnHeaderRefreshHandler.postDelayed(vpnHeaderRefreshRunnable, delay);
    }
