    private void openScreen(View page) {
        finishPageNavigationRestore();
        homeFocusGeneration++;
        rememberHomeFocus();
        if (activeScreen != null) {
            storePageFocus(activeScreen);
            screenBackStack.add(activeScreen);
        } else if (currentHomeShell != null && currentHomeShell.isAttachedToWindow()) {
            // Home is represented by activeScreen == null. Keep its focused
            // tile in the same back-stack contract as internal screens so
            // returning from an SMB folder restores the originating video
            // card instead of defaulting to the first Applications tile.
            storePageFocus(currentHomeShell);
            screenBackStack.add(currentHomeShell);
        }
        activeScreen = page;
        renderScreen(page);
    }
    private void replaceScreen(View page) { finishPageNavigationRestore(); homeFocusGeneration++; activeScreen = page; renderScreen(page); }
    private void renderScreen(View page) {
        activeSharedCategoryNavigation = null;
        // Les écrans conservés dans l'historique peuvent encore appartenir à l'ancien shell.
        // Les détacher avant de les réafficher évite un crash au Retour, qui faisait basculer la TV sur HDMI.
        if (page.getParent() instanceof ViewGroup) ((ViewGroup) page.getParent()).removeView(page);
        // The shared bottom bar already reserves its own height outside the page.
        if (shouldShowSharedCategoryBottomBar(page) && page.getPaddingBottom() != 0) {
            page.setPadding(page.getPaddingLeft(), page.getPaddingTop(), page.getPaddingRight(), 0);
        }
        if (page instanceof FrameLayout) {
            if (page == currentHomeShell) {
                dynamicBackgroundHost = currentHomeShell;
                dynamicBackgroundLayer = homeDynamicBackgroundLayer;
                focusedResumeArtworkBackground = homeFocusedArtworkBackground;
                resetHomeDynamicBackground();
                setContentView(page);
                return;
            }
            if (!shouldShowSharedCategoryBottomBar(page)) {
                setContentView(page);
                return;
            }
            LinearLayout screenHost = new LinearLayout(this);
            screenHost.setOrientation(LinearLayout.VERTICAL);
            screenHost.setBackgroundColor(homeBackgroundColor());
            screenHost.setClipChildren(false);
            screenHost.setClipToPadding(false);
            FrameLayout pageViewport = new FrameLayout(this);
            pageViewport.setClipChildren(false);
            pageViewport.setClipToPadding(false);
            pageViewport.addView(page, new FrameLayout.LayoutParams(-1, -1));
            screenHost.addView(pageViewport, new LinearLayout.LayoutParams(-1, 0, 1f));
            screenHost.addView(createSharedCategoryBottomBar(),
                    new LinearLayout.LayoutParams(-1, homeCategoryBottomBarHeight()));
            setContentView(screenHost);
            return;
        }
        FrameLayout shell = new FrameLayout(this);
        shell.setBackgroundColor(homeBackgroundColor());
        // Internal screens use the same enlarged focus treatment as Home.  The
        // shell and its page must therefore not crop a header icon while it is
        // focused (Home already had this protection, internal pages did not).
        shell.setClipChildren(false);
        shell.setClipToPadding(false);
        if (page instanceof ViewGroup) {
            ((ViewGroup) page).setClipChildren(false);
            ((ViewGroup) page).setClipToPadding(false);
        }
        applyPersonalWallpaper(shell); installDynamicBackgroundLayer(shell);
        page.setBackgroundColor(Color.TRANSPARENT);
        if (!shouldShowSharedCategoryBottomBar(page)) {
            shell.addView(page, new FrameLayout.LayoutParams(-1, -1));
        } else {
            LinearLayout screenHost = new LinearLayout(this);
            screenHost.setOrientation(LinearLayout.VERTICAL);
            screenHost.setClipChildren(false);
            screenHost.setClipToPadding(false);
            FrameLayout pageViewport = new FrameLayout(this);
            pageViewport.setClipChildren(false);
            pageViewport.setClipToPadding(false);
            pageViewport.addView(page, new FrameLayout.LayoutParams(-1, -1));
            screenHost.addView(pageViewport, new LinearLayout.LayoutParams(-1, 0, 1f));
            screenHost.addView(createSharedCategoryBottomBar(),
                    new LinearLayout.LayoutParams(-1, homeCategoryBottomBarHeight()));
            shell.addView(screenHost, new FrameLayout.LayoutParams(-1, -1));
        }
        setContentView(shell);
    }

    private boolean shouldShowSharedCategoryBottomBar(View page) {
        return page != currentHomeShell && !homeCategoryPages.containsKey(page)
                && !homeBottomBarHiddenPages.containsKey(page);
    }

    private int homeCategoryBottomBarHeight() {
        return dp(HOME_HEADER_HEIGHT_DP);
    }

    private View createSharedCategoryBottomBar() {
        FrameLayout bottomBar = new FrameLayout(this);
        bottomBar.setBackgroundColor(homeBackgroundColor());
        bottomBar.setClipChildren(false);
        bottomBar.setClipToPadding(false);
        GridLayout navigation = (GridLayout) createHomeCategoryGrid(false);
        activeSharedCategoryNavigation = navigation;
        navigation.setTag("cyclic_horizontal_card_row");
        for (View card : immediateFocusableChildren(navigation)) {
            if (card.getId() == View.NO_ID) card.setId(View.generateViewId());
            card.setNextFocusDownId(card.getId());
        }
        bottomBar.addView(navigation, new FrameLayout.LayoutParams(-1, homeCategoryBottomBarHeight(), Gravity.CENTER));
        return bottomBar;
    }

    private boolean routeDownToSharedCategoryNavigation() {
        // Let the last control escape a page even when it belongs to a cyclic focus group.
        GridLayout navigation = activeSharedCategoryNavigation;
        if (navigation == null || !navigation.isAttachedToWindow() || activeScreen == null
                || (activePopup != null && activePopup.isShowing())) return false;
        View focused = getCurrentFocus();
        if (focused == null || !isHomeDescendant(focused, activeScreen)) return false;

        int[] focusedLocation = new int[2];
        int[] navigationLocation = new int[2];
        focused.getLocationOnScreen(focusedLocation);
        navigation.getLocationOnScreen(navigationLocation);
        View next = focused.focusSearch(View.FOCUS_DOWN);
        if (next != null && next != focused && isHomeDescendant(next, activeScreen)) {
            int[] nextLocation = new int[2];
            next.getLocationOnScreen(nextLocation);
            // Keep moving through the page while a lower control exists.
            // A self-link or a cyclic wrap upwards marks its bottom edge,
            // regardless of the empty space before the shared navigation.
            if (HomeMediaRules.isLowerFocusRow(focusedLocation[1], focused.getHeight(),
                    nextLocation[1], next.getHeight())) return false;
        }

        // An explicit self-link/cycle can hide controls in a later group or
        // scroll row. Reach those before leaving the page for its bottom bar.
        View lowerControl = null;
        long bestDistance = Long.MAX_VALUE;
        int centerX = focusedLocation[0] + focused.getWidth() / 2;
        int[] candidateLocation = new int[2];
        for (View candidate : activeScreen.getFocusables(View.FOCUS_DOWN)) {
            if (candidate == focused || !candidate.isShown() || !candidate.isEnabled()
                    || isHomeDescendant(focused, candidate)
                    || candidate instanceof ScrollView || candidate instanceof HorizontalScrollView) continue;
            candidate.getLocationOnScreen(candidateLocation);
            if (!HomeMediaRules.isLowerFocusRow(focusedLocation[1], focused.getHeight(),
                    candidateLocation[1], candidate.getHeight())) continue;
            int distanceY = candidateLocation[1] + candidate.getHeight() / 2
                    - focusedLocation[1] - focused.getHeight() / 2;
            long distance = distanceY * (long) getResources().getDisplayMetrics().widthPixels
                    + Math.abs(candidateLocation[0] + candidate.getWidth() / 2 - centerX);
            if (distance < bestDistance) {
                bestDistance = distance;
                lowerControl = candidate;
            }
        }
        if (lowerControl != null) return lowerControl.requestFocus();

        List<View> cards = immediateFocusableChildren(navigation);
        if (cards.isEmpty() || navigation.getWidth() <= 0) return false;
        int relativeX = centerX - navigationLocation[0];
        int column = Math.max(0, Math.min(cards.size() - 1,
                relativeX * cards.size() / navigation.getWidth()));
        if (focused.getId() == View.NO_ID) focused.setId(View.generateViewId());
        for (View card : cards) card.setNextFocusUpId(focused.getId());
        return cards.get(column).requestFocus();
    }
    private void goBackScreen() {
        finishPageNavigationRestore();
        final long navigation = ++homeFocusGeneration;
        // L''accueil est la racine : Retour y revient toujours mais ne quitte jamais l''application.
        if (screenBackStack.isEmpty()) { if (activeScreen != null) goHome(); return; }
        activeScreen = screenBackStack.remove(screenBackStack.size() - 1);
        if (activeScreen.getTag(APP_ICON_MANAGER_TAG) != null) pendingAppIconPackage = null;
        final View returnedPage = activeScreen;
        final boolean returningToCachedHome = returnedPage == currentHomeShell;
        final long returnedGeneration = homeRenderGeneration;
        if (returningToCachedHome) activeScreen = null;
        if (returningToCachedHome && homeVisualSettingsDirty) {
            homeVisualSettingsDirty = false;
            screenBackStack.clear();
            closeSearchOverlayForHomeFocus();
            android.util.Log.i("JojoHome", "HOME_SETTINGS_REBUILD on navigation back");
            setContentView(createHome());
            scheduleJojoHomeResumeRefresh(0L);
            schedulePendingHomeDpadRefresh();
            return;
        }
        restoringNavigationPage = returnedPage;
        for (PageScrollPosition position : savedPageScrollPositions(returnedPage)) position.setSmoothScrolling(false);
        renderScreen(returnedPage);
        if (returningToCachedHome) restoreHomeFocusIfNeeded();
        final android.view.ViewTreeObserver returnedObserver = returnedPage.getViewTreeObserver();
        returnedObserver.addOnPreDrawListener(new android.view.ViewTreeObserver.OnPreDrawListener() {
            @Override public boolean onPreDraw() {
                android.view.ViewTreeObserver observer = returnedObserver.isAlive()
                        ? returnedObserver : returnedPage.getViewTreeObserver();
                if (observer.isAlive()) observer.removeOnPreDrawListener(this);
                if (navigation != homeFocusGeneration || !returnedPage.isAttachedToWindow()) {
                    if (navigation == homeFocusGeneration && restoringNavigationPage == returnedPage) finishPageNavigationRestore();
                    return true;
                }
                // A shortcut can put a fully built Home view in the back stack.
                // Its weather widget was previously reused without a new request.
                if (returningToCachedHome) {
                    scheduleJojoHomeResumeRefresh(0L);
                    // The contents of Freebox/Vidéos may have changed while an
                    // internal folder page was open. Re-enumerate SMB instead of
                    // rendering only the last local cache snapshot.
                    scheduleHomeReturnRefresh(true, 120L);
                }
                View focus = savedPageFocus(returnedPage);
                if (!returningToCachedHome && focus != null && focus.isFocusable()) {
                    // Folder -> category is an internal return, not a new page.
                    // Keep the exact originating tile focused instead of sending
                    // DPAD focus to the first item in the rebuilt category grid.
                    focus.requestFocus();
                } else if (returningToCachedHome && returnedGeneration == homeRenderGeneration && focus != null && focus.isFocusable() && !isSearchHeader(focus)) {
                    requestHomeFocus(focus, "navigation-back-home");
                } else if (returningToCachedHome && returnedGeneration == homeRenderGeneration) {
                    requestHomeFocus(resolveHomeFocusTarget(), "navigation-back-home-resolve");
                } else {
                    focusFirstBrowserEntry(returnedPage);
                }
                if (returningToCachedHome) {
                    // Restoring a Videos card fires its focus listener, which can
                    // immediately republish the artwork used on the folder page.
                    // Clear that one stale background after the focus transaction.
                    resetHomeDynamicBackground();
                }
                // Focus listeners and Android's layout can reveal a different
                // part of a rail. Restore both axes only after that work finishes.
                for (PageScrollPosition position : savedPageScrollPositions(returnedPage)) {
                    if (isHomeDescendant(position.view, returnedPage)) position.view.scrollTo(position.x, position.y);
                }
                finishPageNavigationRestore();
                return true;
            }
        });
    }
    private void goHome() {
        finishPageNavigationRestore();
        StackTraceElement[] navigationTrace = Thread.currentThread().getStackTrace();
        String navigationCaller = navigationTrace.length > 2 ? navigationTrace[2].toString() : "unknown";
        String navigationParent = navigationTrace.length > 3 ? navigationTrace[3].toString() : "unknown";
        String navigationFolder = activeScreen == null ? "" : freeboxFolderPageUrls.get(activeScreen);
        android.util.Log.i("JojoHomeNavigationTrace", "GO_HOME at="
                + android.os.SystemClock.elapsedRealtime()
                + " page=" + (activeScreen == null ? "home" : activeScreen.getClass().getSimpleName())
                + " folder=" + navigationFolder + " caller=" + navigationCaller
                + " parent=" + navigationParent);
        homeFocusGeneration++;
        // Reuse the cached Home tree when returning from an internal screen or
        // an external player. Rebuilding it delayed focus and briefly exposed
        // a black surface while Continue Watching loaded again.
        if (currentHomeShell != null && !homeVisualSettingsDirty
                && (activeScreen == null || pendingFocusPackage == null)) {
            if (activeScreen != null) pendingAppIconPackage = null;
            closeSearchOverlayForHomeFocus();
            screenBackStack.clear();
            activeScreen = null;
            if (currentHomeShell.isAttachedToWindow()) {
                resetHomeDynamicBackground();
            } else {
                renderScreen(currentHomeShell);
            }
            if (pendingFocusPackage != null) {
                refreshHomeApplicationsInPlace(pendingFocusPackage);
            }
            restoreHomeFocusIfNeeded();
            scheduleJojoHomeResumeRefresh(0L);
            scheduleHomeReturnRefresh(true, 120L);
            return;
        }
        pendingAppIconPackage = null;
        closeSearchOverlayForHomeFocus();
        screenBackStack.clear();
        activeScreen = null;
        homeVisualSettingsDirty = false;
        setContentView(createHome());
        scheduleJojoHomeResumeRefresh(0L);
        schedulePendingHomeDpadRefresh();
    }

    private void onHomeHeaderClick() {
        if (activeScreen == null && currentHomeShell != null && currentHomeShell.isAttachedToWindow()) {
            // On the Home screen, Accueil is also an explicit refresh command.
            // Refresh the asynchronous rails in place so focus and layout stay
            // where the user left them.
            refreshHomeResumeSectionInPlace();
            refreshHomeVideosFromNetworkInPlace();
            scheduleJojoHomeResumeRefresh(0L);
            return;
        }
        goHome();
    }

    private void refreshHomeVideosFromNetworkInPlace() {
        if (currentHomePage == null || !currentHomePage.isAttachedToWindow()) return;
        View oldSection = currentHomeSectionViews.get("videos");
        View oldSpacer = currentHomeSectionSpacers.get("videos");
        if (oldSection == null || oldSpacer == null) return;
        String focusedVideoKey = oldSection instanceof ViewGroup ? focusedTag((ViewGroup) oldSection) : null;
        int index = currentHomePage.indexOfChild(oldSection);
        if (index < 0) return;
        LinearLayout.LayoutParams oldParams = (LinearLayout.LayoutParams) oldSection.getLayoutParams();
        LinearLayout.LayoutParams sectionParams = new LinearLayout.LayoutParams(oldParams.width, oldParams.height);
        sectionParams.topMargin = oldParams.topMargin;
        sectionParams.bottomMargin = oldParams.bottomMargin;
        sectionParams.leftMargin = oldParams.leftMargin;
        sectionParams.rightMargin = oldParams.rightMargin;
        LinearLayout.LayoutParams spacerParams = (LinearLayout.LayoutParams) oldSpacer.getLayoutParams();
        final long navigation = homeFocusGeneration;
        final long renderGeneration = homeRenderGeneration;
        currentHomePage.removeView(oldSection);
        currentHomePage.removeView(oldSpacer);
        View replacement = freeboxVideosSection();
        currentHomeSectionViews.put("videos", replacement);
        currentHomePage.addView(replacement, index, sectionParams);
        currentHomePage.addView(oldSpacer, index + 1, spacerParams);
        replacement.post(() -> {
            if (replacement != currentHomeSectionViews.get("videos")
                    || activeScreen != null || navigation != homeFocusGeneration
                    || renderGeneration != homeRenderGeneration
                    || !replacement.isAttachedToWindow()) return;
            if (replacement instanceof ViewGroup) restoreFocusByTag((ViewGroup) replacement, focusedVideoKey);
            wireHomeHeaderDpad(currentHomeHeaderView, currentHomeAppsView, currentHomeFilesView, currentHomeResumesView);
            wireHomeSectionVerticalDpad();
        });
    }

    /**
     * Refresh only the Applications rail after a favorite is added. Reusing
     * the Home shell avoids the old full-screen rebuild, but it also means a
     * newly selected app must be inserted explicitly into the attached rail.
     */
    private void refreshHomeApplicationsInPlace(String focusPackage) {
        if (currentHomeAppsView == null || !currentHomeAppsView.isAttachedToWindow()) return;
        ViewParent parent = currentHomeAppsView.getParent();
        if (!(parent instanceof ViewGroup)) return;
        ViewGroup appsSection = (ViewGroup) parent;
        int index = appsSection.indexOfChild(currentHomeAppsView);
        if (index < 0) return;

        android.view.ViewGroup.LayoutParams layoutParams = currentHomeAppsView.getLayoutParams();
        LinearLayout replacement = appRows();
        currentHomeAppsView = replacement;
        appsSection.removeViewAt(index);
        appsSection.addView(replacement, index, layoutParams);
        if (currentHomeHeaderView != null) {
            wireHomeHeaderDpad(currentHomeHeaderView, replacement, currentHomeFilesView, currentHomeResumesView);
        }

        // appRows() schedules the focus restoration itself; this second pass
        // wins over the PopupWindow dismiss callback when the picker closes.
        if (focusPackage != null) {
            final long navigation = homeFocusGeneration;
            final long renderGeneration = homeRenderGeneration;
            replacement.postDelayed(() -> {
                if (replacement != currentHomeAppsView || activeScreen != null
                        || navigation != homeFocusGeneration
                        || renderGeneration != homeRenderGeneration
                        || !replacement.isAttachedToWindow()) return;
                View currentFocus = getCurrentFocus();
                if (isValidHomeFocus(currentFocus) && !isSearchHeader(currentFocus)) return;
                View target = replacement.findViewWithTag(focusPackage);
                if (target != null) target.requestFocus();
            }, 80L);
        }
    }
    private void scheduleJojoHomeResumeRefresh(long delayMs) {
        jojoResumeRefreshHandler.removeCallbacks(jojoResumeRefreshRunnable);
        if (homeActivityResumed && activeScreen == null && !homePrefs().getString("nas_token", "").isEmpty()) {
            jojoResumeRefreshHandler.postDelayed(jojoResumeRefreshRunnable, Math.max(0L, delayMs));
        }
    }
    private static final String READ_TV_LISTINGS_PERMISSION = "android.permission.READ_TV_LISTINGS";
    private final Handler watchNextRefreshHandler = new Handler(Looper.getMainLooper());
    private final Handler homeReturnRefreshHandler = new Handler(Looper.getMainLooper());
    private boolean homeContentRefreshPending;
    private final java.util.concurrent.atomic.AtomicBoolean watchNextReadInFlight = new java.util.concurrent.atomic.AtomicBoolean(false);
    private String lastWatchNextSnapshotKey;
    private boolean homeWasVisibleBeforePause;
    private long freeboxHomeRefreshGeneration;
    private boolean homeReturnRefreshIncludesVideos;
    private final Runnable freeboxHomePollRunnable = new Runnable() {
        @Override public void run() {
            if (isDestroyed() || activeScreen != null || currentHomePage == null
                    || !currentHomePage.isAttachedToWindow()) return;
            // This timer exists only to reconcile additions/deletions in
            // Freebox/Vidéos.  Scheduling a full Home return refresh here
            // also rebuilt the Continue Watching Hero every 10 seconds,
            // which briefly removed its asynchronously resolved genre.
            if (homeDpadNavigationActive) {
                homeRefreshPendingAfterDpad = true;
                homeReturnRefreshIncludesVideos = true;
            } else {
                refreshHomeVideosFromNetworkInPlace();
            }
            homeReturnRefreshHandler.postDelayed(this, 10_000L);
        }
    };
    private final Runnable homeReturnRefreshRunnable = () -> {
        if (homeDpadNavigationActive) {
            homeRefreshPendingAfterDpad = true;
            return;
        }
        if (homeRefreshPendingAfterDpad && !canApplyHomeDpadRefresh()) return;
        boolean refreshVideos = homeReturnRefreshIncludesVideos;
        homeReturnRefreshIncludesVideos = false;
        homeRefreshPendingAfterDpad = false;
        if (activeScreen != null || currentHomePage == null || !currentHomePage.isAttachedToWindow()) return;
        refreshHomeResumeSectionInPlace();
        if (refreshVideos && !isHomeDescendant(getCurrentFocus(), currentHomeSectionViews.get("videos"))) {
            refreshHomeVideosFromNetworkInPlace();
        }
        scheduleJojoHomeResumeRefresh(0L);
        homeReturnRefreshHandler.removeCallbacks(freeboxHomePollRunnable);
        homeReturnRefreshHandler.postDelayed(freeboxHomePollRunnable, 10_000L);
    };
    private final Runnable watchNextRefreshRunnable = () -> {
        if (!hasTvListingsAccess()) {
            homeContentRefreshPending = false;
            return;
        }
        if (!watchNextReadInFlight.compareAndSet(false, true)) return;
        try {
            resumeMutationExecutor.execute(() -> {
                String snapshotKey = watchNextSnapshotKey();
                runOnUiThread(() -> {
                    watchNextReadInFlight.set(false);
                    if (snapshotKey == null) return;
                    boolean changed = !snapshotKey.equals(lastWatchNextSnapshotKey);
                    lastWatchNextSnapshotKey = snapshotKey;
                    homeContentRefreshPending = changed;
                    if (changed && activeScreen == null) refreshHomeResumeSectionInPlace();
                });
            });
        } catch (java.util.concurrent.RejectedExecutionException ignored) {
            watchNextReadInFlight.set(false);
        }
        // Never rebuild the Home view from a provider callback. Android TV
        // providers may rewrite engagement fields while the user is moving
        // through the Applications row; rebuilding here destroys the focused
        // tile and sends D-pad focus back to the first application.
    };
    private final ContentObserver watchNextContentObserver = new ContentObserver(watchNextRefreshHandler) {
        @Override public void onChange(boolean selfChange) { scheduleWatchNextRefresh(); }
        @Override public void onChange(boolean selfChange, Uri uri) { scheduleWatchNextRefresh(); }
    };
    private boolean watchNextObserverRegistered;
    private final ContentObserver jojoBridgeContentObserver = new ContentObserver(jojoResumeRefreshHandler) {
        @Override public void onChange(boolean selfChange) { refreshJojoProgramsAfterBridgeChange(); }
        @Override public void onChange(boolean selfChange, Uri uri) { refreshJojoProgramsAfterBridgeChange(); }
    };
    private boolean jojoBridgeObserverRegistered;
    private final Runnable bridgeFollowUpRefreshRunnable = this::refreshJojoProgramsFromNasAsync;
    private void refreshJojoProgramsAfterBridgeChange() {
        if (activeScreen != null) return;
        // Do not rebuild the Home view from a bridge notification while the
        // user is navigating it: replacing the focused view makes Android's
        // fallback focus search jump to the first header item (Rechercher).
        // The async row refresh below updates the data without replacing the
        // surrounding Home hierarchy.
        refreshHomeResumeSectionInPlace();
        refreshJojoProgramsFromNasAsync();
        jojoResumeRefreshHandler.removeCallbacks(bridgeFollowUpRefreshRunnable);
        jojoResumeRefreshHandler.postDelayed(bridgeFollowUpRefreshRunnable, 1_500L);
    }
    private void setupJojoBridgeObserver() {
        if (jojoBridgeObserverRegistered) return;
        try {
            for (String authority : new String[]{"com.jojo.tv.homebridge", "com.jojo.tv.debug.homebridge"}) {
                if (getPackageManager().resolveContentProvider(authority, 0) == null) continue;
                getContentResolver().registerContentObserver(Uri.parse("content://" + authority), true, jojoBridgeContentObserver);
                jojoBridgeObserverRegistered = true;
            }
        } catch (Exception ignored) { }
    }
    private boolean hasTvListingsAccess() { return Build.VERSION.SDK_INT >= 26 && checkSelfPermission(READ_TV_LISTINGS_PERMISSION) == PackageManager.PERMISSION_GRANTED; }
    private void setupWatchNextIntegration() {
        if (!WatchNextRules.shouldObserve(Build.VERSION.SDK_INT, hasTvListingsAccess())) {
            requestTvListingsAccessIfNeeded();
            return;
        }
        if (!watchNextObserverRegistered) {
            // Watch Next is the only source that represents an actual resume
            // state. PreviewPrograms and Channels are also rewritten by
            // SmartTube for subscriptions/recommendations; observing them
            // rebuilt the whole Home screen on every provider update and made
            // the Continue Watching row visibly refresh/flicker.
            getContentResolver().registerContentObserver(TvContract.WatchNextPrograms.CONTENT_URI, true, watchNextContentObserver);
            watchNextObserverRegistered = true;
        }
    }
    private void requestTvListingsAccessIfNeeded() {
        if (Build.VERSION.SDK_INT >= 26 && SystemContinueWatching.shouldRequestPermission(hasTvListingsAccess(), homePrefs().getBoolean(TV_LISTINGS_PERMISSION_ASKED, false))) {
            homePrefs().edit().putBoolean(TV_LISTINGS_PERMISSION_ASKED, true).apply();
            startActivityForResult(new Intent(this, TvListingsPermissionActivity.class), REQUEST_TV_LISTINGS);
        }
    }
    private void requestTvListingsAccessNow() {
        if (Build.VERSION.SDK_INT < 23 || hasTvListingsAccess()) {
            setupWatchNextIntegration();
            Toast.makeText(this, "Accès reprises Android TV déjà autorisé", Toast.LENGTH_SHORT).show();
            return;
        }
        homePrefs().edit().remove(TV_LISTINGS_PERMISSION_ASKED).apply();
        startActivityForResult(new Intent(this, TvListingsPermissionActivity.class), REQUEST_TV_LISTINGS);
    }
    private void requestNotificationResumeFallbackRefresh() {
        if (!NotificationResumeListenerService.isAccessGranted(this)) return;
        try {
            Intent refresh = new Intent(this, NotificationResumeListenerService.class)
                    .setAction(NotificationResumeListenerService.ACTION_REFRESH);
            startService(refresh);
            android.util.Log.i("JojoHomeResume", "fallback refresh requested on Home resume");
        } catch (Exception error) {
            android.util.Log.i("JojoHomeResume", "fallback refresh unavailable: " + error.getClass().getSimpleName());
        }
    }
    private String tvListingsAccessStatus() { return hasTvListingsAccess() ? "Autorisé" : "À autoriser"; }
    private void scheduleWatchNextRefresh() {
        watchNextRefreshHandler.removeCallbacks(watchNextRefreshRunnable);
        watchNextRefreshHandler.postDelayed(watchNextRefreshRunnable, WatchNextRules.refreshDelayMillis());
    }
    private String watchNextSnapshotKey() {
        PublishedResumeSnapshot observed = readSystemContinueWatchingSnapshot();
        if (!observed.available) return null;
        StringBuilder snapshot = new StringBuilder();
        for (JojoProgram program : observed.programs) {
            for (String value : new String[]{program.sourcePackage, program.title, program.description,
                    program.intentUri, program.artwork, String.valueOf(program.duration), String.valueOf(program.position),
                    program.seasonNumber, program.episodeNumber}) snapshot.append(value).append('\u001f');
            snapshot.append('\u001e');
        }
        return snapshot.toString();
    }
    private void hideSystemBars() {
        // The platform InsetsController is not ready during Activity.onCreate on
        // some Android TV firmwares.  The legacy flags are supported on all our
        // target devices and avoid a startup crash before the decor is attached.
        getWindow().getDecorView().setSystemUiVisibility(
            View.SYSTEM_UI_FLAG_FULLSCREEN | View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY |
            View.SYSTEM_UI_FLAG_HIDE_NAVIGATION | View.SYSTEM_UI_FLAG_LAYOUT_FULLSCREEN |
            View.SYSTEM_UI_FLAG_LAYOUT_HIDE_NAVIGATION | View.SYSTEM_UI_FLAG_LAYOUT_STABLE
        );
        // On Android 11+, Fire OS may recreate its navigation bar after the
        // legacy flags.  Only ask the InsetsController once the decor is
        // attached: calling PhoneWindow#getInsetsController from onCreate
        // crashes on the Philips Android TV firmware.
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.R) {
            View decor = getWindow().getDecorView();
            decor.post(() -> {
                if (!decor.isAttachedToWindow()) return;
                WindowInsetsController controller = decor.getWindowInsetsController();
                if (controller != null) {
                    controller.hide(WindowInsets.Type.systemBars());
                    controller.setSystemBarsBehavior(WindowInsetsController.BEHAVIOR_SHOW_TRANSIENT_BARS_BY_SWIPE);
                }
            });
        }
    }

    private boolean dynamicWallpaperEnabled() { return homePrefs().getBoolean("dynamic_wallpaper", false); }
    private String dynamicWallpaperMode() { return homePrefs().getString("dynamic_wallpaper_mode", "glow"); }
    private boolean dynamicSolidColorEnabled() { return dynamicWallpaperEnabled() && "solid".equals(dynamicWallpaperMode()); }
    private boolean dynamicGlowEnabled() { return dynamicWallpaperEnabled() && "glow".equals(dynamicWallpaperMode()); }
    private String dynamicWallpaperLabel() {
        if (!dynamicWallpaperEnabled()) return "Désactivé";
        if (dynamicSolidColorEnabled()) return "Couleur immersive";
        if (dynamicGlowEnabled()) return "Lueur douce";
        return "Dégradé cinéma";
    }
    private void setDynamicWallpaperEnabled(boolean enabled) { homePrefs().edit().putBoolean("dynamic_wallpaper", enabled).putString("dynamic_wallpaper_mode", "glow").apply(); if (!enabled) clearDynamicBackground(); }
    private void setDynamicWallpaperMode(String mode) { homePrefs().edit().putBoolean("dynamic_wallpaper", true).putString("dynamic_wallpaper_mode", mode).apply(); }
    private void setDynamicSolidColorEnabled(boolean enabled) { homePrefs().edit().putBoolean("dynamic_wallpaper", enabled).putString("dynamic_wallpaper_mode", "solid").apply(); }
    private int dynamicFallbackColor() { return homeBackgroundColor(); }
    private GradientDrawable dynamicBackgroundDrawable(int color) {
        if (dynamicGlowEnabled()) {
            GradientDrawable glow = new GradientDrawable(GradientDrawable.Orientation.TL_BR, new int[] { withAlpha(color, 150), Color.TRANSPARENT });
            glow.setGradientType(GradientDrawable.RADIAL_GRADIENT);
            glow.setGradientCenter(.38f, .20f);
            glow.setGradientRadius(dp(820));
            return glow;
        }
        return new GradientDrawable(GradientDrawable.Orientation.TL_BR, dynamicSolidColorEnabled() ? new int[] { color, color } : new int[] { color, Color.BLACK });
    }
    private int withAlpha(int color, int alpha) { return Color.argb(alpha, Color.red(color), Color.green(color), Color.blue(color)); }
    private void installDynamicBackgroundLayer(FrameLayout host) { dynamicBackgroundHost = host; dynamicBackgroundLayer = new View(this); dynamicBackgroundColor = dynamicFallbackColor(); if (dynamicWallpaperEnabled()) dynamicBackgroundLayer.setBackground(dynamicBackgroundDrawable(dynamicBackgroundColor)); else dynamicBackgroundLayer.setBackgroundColor(Color.TRANSPARENT); host.addView(dynamicBackgroundLayer, new FrameLayout.LayoutParams(-1, -1)); focusedResumeArtworkBackground = new ImageView(this); focusedResumeArtworkBackground.setScaleType(ImageView.ScaleType.CENTER_CROP); focusedResumeArtworkBackground.setColorFilter(Color.argb(132, 0, 0, 0), android.graphics.PorterDuff.Mode.SRC_ATOP); focusedResumeArtworkBackground.setAlpha(0f); host.addView(focusedResumeArtworkBackground, new FrameLayout.LayoutParams(-1, -1)); }
    private void clearDynamicBackground() { dynamicBackgroundGeneration++; if (dynamicBackgroundLayer != null) { dynamicBackgroundLayer.animate().cancel(); dynamicBackgroundLayer.setBackgroundColor(Color.TRANSPARENT); dynamicBackgroundLayer.setAlpha(1f); } dynamicBackgroundColor = dynamicFallbackColor(); }
    private void resetHomeDynamicBackground() {
        clearDynamicBackground();
        if (focusedResumeArtworkBackground != null) {
            focusedResumeArtworkBackground.animate().cancel();
            focusedResumeArtworkBackground.setAlpha(0f);
            focusedResumeArtworkBackground.setImageDrawable(null);
        }
    }
    private void clearFocusedResumeArtwork() {
        if (focusedResumeArtworkBackground == null) return;
        focusedResumeArtworkBackground.animate().cancel();
        focusedResumeArtworkBackground.setAlpha(0f);
        focusedResumeArtworkBackground.setImageDrawable(null);
    }
    private void showFocusedResumeArtwork(ImageView artwork) {
        if (artwork == null || artwork.getDrawable() == null || focusedResumeArtworkBackground == null
                || !artwork.isAttachedToWindow() || dynamicBackgroundHost == null
                || artwork.getRootView() != dynamicBackgroundHost.getRootView()) return;
        // Never share a Drawable with the small card: a Drawable has one set of
        // bounds, so the card could resize the fullscreen background to its own
        // thumbnail dimensions during focus/layout updates.
        android.graphics.drawable.Drawable backgroundArtwork = copyDrawableForBackground(artwork.getDrawable());
        if (backgroundArtwork == null) return;
        focusedResumeArtworkBackground.setImageDrawable(backgroundArtwork);
        focusedResumeArtworkBackground.animate().alpha(.62f).setDuration(220).start();
    }
    private void hideFocusedResumeArtworkWhenLeavingRows() { View focused = getCurrentFocus(); View cursor = focused; View videosSection = currentHomeSectionViews.get("videos"); while (cursor != null) { if (cursor == currentHomeResumesView || cursor == videosSection || currentExternalRows.containsValue(cursor) || "folder_episode_row".equals(cursor.getTag())) return; cursor = cursor.getParent() instanceof View ? (View) cursor.getParent() : null; } if (focusedResumeArtworkBackground != null) focusedResumeArtworkBackground.animate().alpha(0f).setDuration(180).start(); }
    private int darkenDynamicColor(int color) { float[] hsv = new float[3]; Color.colorToHSV(color, hsv); hsv[1] = Math.min(0.90f, Math.max(0.38f, hsv[1] * 1.08f)); hsv[2] = Math.min(0.46f, Math.max(0.14f, hsv[2] * 0.48f)); return Color.HSVToColor(hsv); }
    private int solidDynamicColor(int color) { float[] hsv = new float[3]; Color.colorToHSV(color, hsv); hsv[1] = Math.min(0.96f, Math.max(0.55f, hsv[1] * 1.08f)); hsv[2] = Math.min(0.78f, Math.max(0.42f, hsv[2] * .92f)); return Color.HSVToColor(hsv); }
    private int paletteAccent(androidx.palette.graphics.Palette palette) { int fallback = palette.getVibrantColor(palette.getLightVibrantColor(palette.getMutedColor(Color.rgb(18, 18, 18)))); int selected = fallback; float best = -1f; for (androidx.palette.graphics.Palette.Swatch swatch : palette.getSwatches()) { float[] hsv = new float[3]; Color.colorToHSV(swatch.getRgb(), hsv); if (hsv[1] < .22f || hsv[2] < .18f) continue; float score = hsv[1] * 2.4f + hsv[2] * .7f + Math.min(.55f, swatch.getPopulation() / 12000f); if (score > best) { best = score; selected = swatch.getRgb(); } } return selected; }
    private android.graphics.drawable.Drawable copyDrawableForBackground(android.graphics.drawable.Drawable drawable) {
        if (drawable == null) return null;
        try {
            android.graphics.drawable.Drawable.ConstantState state = drawable.getConstantState();
            if (state != null) return state.newDrawable(getResources()).mutate();
            android.graphics.Bitmap snapshot = bitmapFromDrawable(drawable);
            return snapshot == null ? null : new android.graphics.drawable.BitmapDrawable(getResources(), snapshot);
        } catch (Exception ignored) { return null; }
    }
    private android.graphics.Bitmap bitmapFromDrawable(android.graphics.drawable.Drawable drawable) { if (drawable == null) return null; try { int width = drawable.getIntrinsicWidth() > 0 ? Math.min(drawable.getIntrinsicWidth(), 480) : 320, height = drawable.getIntrinsicHeight() > 0 ? Math.min(drawable.getIntrinsicHeight(), 480) : 180; android.graphics.Bitmap bitmap = android.graphics.Bitmap.createBitmap(Math.max(1, width), Math.max(1, height), android.graphics.Bitmap.Config.ARGB_8888); android.graphics.Canvas canvas = new android.graphics.Canvas(bitmap); android.graphics.Rect originalBounds = drawable.copyBounds(); drawable.setBounds(0, 0, canvas.getWidth(), canvas.getHeight()); drawable.draw(canvas); drawable.setBounds(originalBounds); return bitmap; } catch (Exception ignored) { return null; } }
    private void updateDynamicBackground(android.graphics.drawable.Drawable drawable) {
        if (!dynamicWallpaperEnabled() || dynamicBackgroundLayer == null) return;
        final View layer = dynamicBackgroundLayer;
        final long generation = ++dynamicBackgroundGeneration;
        // Palette already samples on its worker. Avoid allocating and drawing a copy on each key press.
        Bitmap bitmap = drawable instanceof BitmapDrawable ? ((BitmapDrawable) drawable).getBitmap()
                : bitmapFromDrawable(drawable);
        if (bitmap == null || bitmap.isRecycled()) { animateDynamicBackground(dynamicFallbackColor()); return; }
        Integer cachedAccent = artworkPaletteCache.get(bitmap);
        if (cachedAccent != null) {
            animateDynamicBackground(dynamicSolidColorEnabled() || dynamicGlowEnabled()
                    ? solidDynamicColor(cachedAccent) : darkenDynamicColor(cachedAccent));
            return;
        }
        androidx.palette.graphics.Palette.from(bitmap).generate(palette -> {
            int accent = paletteAccent(palette);
            artworkPaletteCache.put(bitmap, accent);
            if (generation != dynamicBackgroundGeneration || layer != dynamicBackgroundLayer || !layer.isAttachedToWindow()) return;
            animateDynamicBackground(dynamicSolidColorEnabled() || dynamicGlowEnabled()
                    ? solidDynamicColor(accent) : darkenDynamicColor(accent));
        });
    }
    private void updateDynamicBackground(ImageView image) { updateDynamicBackground(image == null ? null : image.getDrawable()); }
    private boolean isFireOsDevice() {
        // Détecte si on est sur Fire OS (Fire Stick, Fire Tablet, etc.) d'Amazon
        if (Build.MANUFACTURER != null && Build.MANUFACTURER.toLowerCase(Locale.ROOT).contains("amazon")) return true;
        String device = Build.DEVICE;
        return device != null && (device.contains("AFTM") || device.contains("AFTB") || device.contains("AFT"));
    }
    private android.graphics.drawable.Drawable officialCanalPlusBanner() {
        final int width = 320, height = 180;
        android.graphics.Bitmap bitmap = android.graphics.Bitmap.createBitmap(width, height, android.graphics.Bitmap.Config.ARGB_8888);
        android.graphics.Canvas canvas = new android.graphics.Canvas(bitmap);
        canvas.drawColor(Color.BLACK);
        android.graphics.Paint paint = new android.graphics.Paint(android.graphics.Paint.ANTI_ALIAS_FLAG | android.graphics.Paint.SUBPIXEL_TEXT_FLAG);
        paint.setColor(Color.WHITE);
        paint.setTypeface(android.graphics.Typeface.create("sans-serif", android.graphics.Typeface.BOLD));
        paint.setTextSize(76f);
        paint.setTextAlign(android.graphics.Paint.Align.CENTER);
        android.graphics.Paint.FontMetrics metrics = paint.getFontMetrics();
        canvas.drawText("CANAL+", width / 2f, height / 2f - (metrics.ascent + metrics.descent) / 2f, paint);
        return new BitmapDrawable(getResources(), bitmap);
    }
    private void animateDynamicBackground(int targetColor) { if (!dynamicWallpaperEnabled() || dynamicBackgroundLayer == null) return; final View layer = dynamicBackgroundLayer; final long generation = dynamicBackgroundGeneration; int start = dynamicBackgroundColor; android.animation.ValueAnimator animator = android.animation.ValueAnimator.ofObject(new android.animation.ArgbEvaluator(), start, targetColor); animator.setDuration(400); animator.addUpdateListener(value -> { if (generation == dynamicBackgroundGeneration && layer == dynamicBackgroundLayer && layer.isAttachedToWindow()) { int color = (Integer) value.getAnimatedValue(); layer.setBackground(dynamicBackgroundDrawable(color)); } }); animator.start(); dynamicBackgroundColor = targetColor; }

    private boolean openHomeRowMoveDrawer(View tile) {
        // createHome() can also be reached from an in-app screen (for example
        // immediately after adding a shortcut). The focused tile itself proves
        // that we are on the home surface, so do not reject that valid case.
        if (currentHomeShell == null || !(tile.getTag(HOME_ROW_MOVE_KEY_TAG) instanceof String)) return false;
        final String key = (String) tile.getTag(HOME_ROW_MOVE_KEY_TAG);
        final FrameLayout drawer = new FrameLayout(this);
        drawer.setClipChildren(false);
        drawer.setClipToPadding(false);
        drawer.setBackgroundColor(Color.TRANSPARENT);
        LinearLayout moveContent = new LinearLayout(this);
        moveContent.setOrientation(LinearLayout.VERTICAL);
        moveContent.setGravity(Gravity.CENTER_HORIZONTAL);
        ImageView move = new ImageView(this);
        move.setImageResource(R.drawable.ic_home_row_move);
        move.setContentDescription("Déplacer la ligne");
        move.setScaleType(ImageView.ScaleType.CENTER_INSIDE);
        move.setFocusable(true);
        move.setBackgroundColor(Color.TRANSPARENT);
        TextView moveLabel = text("Déplacer", 9, Color.WHITE);
        moveLabel.setGravity(Gravity.CENTER);
        moveLabel.setSingleLine(true);
        moveContent.addView(move, new LinearLayout.LayoutParams(dp(38), dp(38)));
        moveContent.addView(moveLabel, new LinearLayout.LayoutParams(-1, dp(15)));
        drawer.addView(moveContent, new FrameLayout.LayoutParams(-1, -1, Gravity.TOP | Gravity.CENTER_HORIZONTAL));
        final boolean[] moveArmed = {false};
        move.setOnFocusChangeListener((v, focused) -> {
            move.setAlpha(focused ? 1f : .82f);
            moveLabel.setTextColor(focused ? Color.WHITE : muted);
        });
        move.setOnClickListener(v -> { moveArmed[0] = true; Toast.makeText(this, "Utilisez ↑ ou ↓ pour déplacer la ligne", Toast.LENGTH_SHORT).show(); });
        move.setOnKeyListener((v, keyCode, event) -> {
            if (event.getAction() != KeyEvent.ACTION_DOWN) return false;
            if (event.getRepeatCount() != 0) return true;
            if (keyCode == KeyEvent.KEYCODE_DPAD_CENTER || keyCode == KeyEvent.KEYCODE_ENTER) { move.performClick(); return true; }
            if (keyCode == KeyEvent.KEYCODE_DPAD_RIGHT || keyCode == KeyEvent.KEYCODE_BACK) { currentHomeShell.removeView(drawer); tile.requestFocus(); return true; }
            if (keyCode == KeyEvent.KEYCODE_DPAD_UP || keyCode == KeyEvent.KEYCODE_DPAD_DOWN) {
                if (!moveArmed[0]) {
                    currentHomeShell.removeView(drawer);
                    tile.requestFocus();
                    int targetId = keyCode == KeyEvent.KEYCODE_DPAD_UP
                            ? tile.getNextFocusUpId() : tile.getNextFocusDownId();
                    View target = targetId == View.NO_ID ? null : tile.getRootView().findViewById(targetId);
                    if (target != null && target.isFocusable()) target.requestFocus();
                    return true;
                }
                moveHomeSection(key, keyCode == KeyEvent.KEYCODE_DPAD_UP ? -1 : 1);
                return true;
            }
            return true;
        });
        // Align with the visible artwork/icon, never with the caption that sits
        // below it. This is shared by application tiles and resume cards.
        final View anchor = tile instanceof ViewGroup && ((ViewGroup) tile).getChildCount() > 0
                ? ((ViewGroup) tile).getChildAt(0) : tile;
        final View row = tile.getParent() instanceof View ? (View) tile.getParent() : tile;
        int[] shellLocation = new int[2];
        currentHomeShell.getLocationOnScreen(shellLocation);
        int size = dp(64);
        int circleCenterOffset = dp(24);
        drawer.setTag(HOME_ROW_MOVE_CIRCLE_CENTER_TAG, circleCenterOffset);
        FrameLayout.LayoutParams drawerParams = new FrameLayout.LayoutParams(size, dp(66), Gravity.LEFT | Gravity.TOP);
        // Reserve a real gutter next to the cards, while preserving the title.
        final float originalRowTranslationX = row.getTranslationX();
        row.setTranslationX(originalRowTranslationX + size + dp(8));
        drawer.addOnAttachStateChangeListener(new View.OnAttachStateChangeListener() {
            @Override public void onViewAttachedToWindow(View view) { }
            @Override public void onViewDetachedFromWindow(View view) {
                row.setTranslationX(originalRowTranslationX);
                if (activeHomeRowMoveDrawer == drawer) {
                    activeHomeRowMoveDrawer = null;
                    activeHomeRowMoveTile = null;
                }
            }
        });
        drawerParams.leftMargin = dp(8);
        // Use the transformed, visible bounds rather than the layout height:
        // focused cards scale while the handle receives focus.  This keeps the
        // handle's centre exactly aligned with the visible artwork, not its
        // caption or its unscaled layout box.
        android.graphics.Rect artworkBounds = new android.graphics.Rect();
        anchor.getGlobalVisibleRect(artworkBounds);
        drawerParams.topMargin = Math.max(dp(8), artworkBounds.centerY() - shellLocation[1] - circleCenterOffset);
        // The source card is still shrinking when its move handle receives
        // focus. Keep the handle transparent for that very short transition,
        // otherwise the later exact-centering pass is seen as a small slide.
        drawer.setAlpha(0f);
        currentHomeShell.addView(drawer, drawerParams);
        activeHomeRowMoveDrawer = drawer;
        activeHomeRowMoveTile = tile;
        drawer.bringToFront();
        move.requestFocus();
        // The card's focus scale animation finishes after the handle gains
        // focus. Re-read the visible bounds once settled so it remains
        // pixel-centred on both app banners and resume thumbnails.
        drawer.postDelayed(() -> {
            if (!drawer.isAttachedToWindow() || !anchor.isAttachedToWindow()) return;
            android.graphics.Rect settledBounds = new android.graphics.Rect();
            anchor.getGlobalVisibleRect(settledBounds);
            FrameLayout.LayoutParams settledParams = (FrameLayout.LayoutParams) drawer.getLayoutParams();
            int settledTop = Math.max(dp(8), settledBounds.centerY() - shellLocation[1] - circleCenterOffset);
            if (settledParams.topMargin != settledTop) {
                settledParams.topMargin = settledTop;
                drawer.setLayoutParams(settledParams);
            }
            drawer.animate().alpha(1f).setDuration(80).start();
        }, 150);
        return true;
    }

    /** Keeps the move handle aligned after an in-place section reorder. */
    private void repositionActiveHomeRowMoveDrawer() {
        if (activeHomeRowMoveDrawer == null || activeHomeRowMoveTile == null
                || currentHomeShell == null || !activeHomeRowMoveDrawer.isAttachedToWindow()) return;
        View anchor = activeHomeRowMoveTile instanceof ViewGroup
                && ((ViewGroup) activeHomeRowMoveTile).getChildCount() > 0
                ? ((ViewGroup) activeHomeRowMoveTile).getChildAt(0) : activeHomeRowMoveTile;
        android.graphics.Rect bounds = new android.graphics.Rect();
        anchor.getGlobalVisibleRect(bounds);
        int[] shellLocation = new int[2];
        currentHomeShell.getLocationOnScreen(shellLocation);
        FrameLayout.LayoutParams params = (FrameLayout.LayoutParams) activeHomeRowMoveDrawer.getLayoutParams();
        Object offset = activeHomeRowMoveDrawer.getTag(HOME_ROW_MOVE_CIRCLE_CENTER_TAG);
        int circleCenterOffset = offset instanceof Integer ? (Integer) offset : params.height / 2;
        params.topMargin = Math.max(dp(8), bounds.centerY() - shellLocation[1] - circleCenterOffset);
        activeHomeRowMoveDrawer.setLayoutParams(params);
    }

    /**
     * Registers the first tile of any home section with the common row-move
     * system. New horizontal sections must use this instead of a local tag.
     */
    private void registerHomeRowMoveTrigger(View tile, String sectionKey) {
        if (tile != null) tile.setTag(HOME_ROW_MOVE_KEY_TAG, sectionKey);
    }

    private boolean handleHomeRowMoveKey(View tile, int keyCode, KeyEvent event) {
        return event.getAction() == KeyEvent.ACTION_DOWN && event.getRepeatCount() == 0
                && keyCode == KeyEvent.KEYCODE_DPAD_LEFT
                && openHomeRowMoveDrawer(tile);
    }

    private List<String> homeSectionOrder(boolean shortcuts, boolean resumes) {
        ArrayList<String> available = new ArrayList<>();
        if (shortcuts) available.add("shortcuts");
        available.add("apps");
        if (resumes) available.add("resumes");
        String[] externalSections = new String[] { "movies", "series", "live" };
        String saved = homePrefs().getString(HOME_SECTION_ORDER, "");
        if (saved.isEmpty()) {
            if (shortcuts && !homeFileShortcutsBeforeApps()) { available.remove("shortcuts"); available.add("shortcuts"); }
            if (resumes && continueWatchingBeforeApps()) { available.remove("resumes"); available.add(0, "resumes"); }
            available.addAll(java.util.Arrays.asList(externalSections));
            return available;
        }
        ArrayList<String> ordered = new ArrayList<>();
        for (String key : saved.split("\\|")) if (available.contains(key) || java.util.Arrays.asList(externalSections).contains(key)) {
            if (!ordered.contains(key)) ordered.add(key);
        }
        for (String key : available) if (!ordered.contains(key)) ordered.add(key);
        int insertAt = ordered.size();
        for (String key : externalSections) if (!ordered.contains(key)) ordered.add(insertAt++, key);
        return ordered;
    }

    private boolean isTiviMatePackage(String packageName) {
        if (packageName == null) return false;
        String normalized = packageName.toLowerCase(Locale.ROOT);
        return normalized.equals("ar.tvplayer.tv") || normalized.contains("tivimate");
    }

    private boolean isIptvProgram(JojoProgram program) {
        return program != null && ("external-playback".equals(program.sourcePackage)
                || "external-playback-series-episode".equals(program.sourcePackage)
                || isTiviMatePackage(program.sourcePackage));
    }

    private View externalPlaybackSection(String category) {
        LinearLayout section = new LinearLayout(this);
        section.setOrientation(LinearLayout.VERTICAL);
        addHomeSectionTitle(section, category, homeSectionSettingsLabel(category), HOME_TITLE_TO_CARD_GAP_DP);
        LinearLayout rows = new LinearLayout(this);
        rows.setOrientation(LinearLayout.VERTICAL);
        rows.setClipChildren(false);
        currentExternalRows.put(category, rows);
        section.addView(rows, new LinearLayout.LayoutParams(-1, dp(continueWatchingRowHeightDp() * homeSectionRows(category))));
        List<JSONObject> items = ExternalPlaybackStore.list(this, category);
        homeCategoryFavoriteSnapshots.put(category, new ArrayList<>(items));
        section.setVisibility(items.isEmpty() ? View.GONE : View.VISIBLE);
        return section;
    }

    private void preloadHomeCategoryFavoriteSnapshots() {
        if (homeCategoryFavoriteSnapshotsPreloadStarted) return;
        homeCategoryFavoriteSnapshotsPreloadStarted = true;
        new Thread(() -> {
            Map<String, List<JSONObject>> snapshots = new LinkedHashMap<>();
            for (String category : new String[]{"movies", "series", "live"}) {
                snapshots.put(category, com.jojotv.home.iptv.IptvStore.applyHomeFavoriteProgress(
                        this, ExternalPlaybackStore.list(this, category)));
            }
            runOnUiThread(() -> {
                if (isFinishing() || isDestroyed()) return;
                for (Map.Entry<String, List<JSONObject>> entry : snapshots.entrySet()) {
                    List<JSONObject> current = homeCategoryFavoriteSnapshots.get(entry.getKey());
                    if (current == null || current.isEmpty()) {
                        homeCategoryFavoriteSnapshots.put(entry.getKey(), new ArrayList<>(entry.getValue()));
                    }
                }
                refreshEmptyHomeSuggestions();
            });
        }, "JojoHomeCategoryFavorites").start();
    }

    private void preloadHomeCategoryVideos() {
        if (homeCategoryVideosPreloadStarted) return;
        homeCategoryVideosPreloadStarted = true;
        startHomeCategoryVideosLoad();
    }

    private java.util.concurrent.FutureTask<List<JojoProgram>> startHomeCategoryVideosLoad() {
        synchronized (homeCategoryVideosLoadLock) {
            if (homeCategoryVideosLoad == null || homeCategoryVideosLoad.isDone()) {
                homeCategoryVideosLoad = new java.util.concurrent.FutureTask<>(this::findFreeboxHomeVideos);
                new Thread(homeCategoryVideosLoad, "JojoHomeCategoryVideos").start();
            }
            return homeCategoryVideosLoad;
        }
    }

    private List<JojoProgram> loadHomeCategoryVideos() {
        try {
            return startHomeCategoryVideosLoad().get();
        } catch (InterruptedException error) {
            Thread.currentThread().interrupt();
            return cachedFreeboxHomeVideos();
        } catch (Exception error) {
            return cachedFreeboxHomeVideos();
        }
    }

    private void openExternalPlayback(JSONObject item, boolean showSeriesDetails, boolean startFromBeginning) {
        openExternalPlayback(item, showSeriesDetails, startFromBeginning, null);
    }
    private void openExternalPlayback(JSONObject item, boolean showSeriesDetails, boolean startFromBeginning,
                                      String playerPackage) {
        if (item == null || !item.has("id")) return;
        if ("jojo-iptv".equals(item.optString("favoriteSource"))) {
            if ("series".equals(item.optString("category")) && (showSeriesDetails
                    || item.optInt("season", 0) <= 0 || item.optInt("episode", 0) <= 0))
                openScreen(createTiviMateSeriesPage(item, playerPackage));
            else openHomeIptvPlayback(item, startFromBeginning, playerPackage);
            return;
        }
        if (showSeriesDetails && "series".equals(item.optString("category"))
                && "tivimate-stalker".equals(item.optString("favoriteSource"))) {
            openScreen(createTiviMateSeriesPage(item, playerPackage));
            return;
        }
        String id = item.optString("id");
        if (id.equals(pendingExternalLaunchId)) return;
        pendingExternalLaunchId = id;
        final int launchGeneration = externalLaunchGeneration.incrementAndGet();
        final View originScreen = activeScreen;
        final long navigation = homeFocusGeneration;
        android.util.Log.i("TiviMateFavoriteImport", "PLAYBACK_LINK_REQUEST at="
                + android.os.SystemClock.elapsedRealtime() + " category=" + item.optString("category"));
        TiviMateFavoriteImporter.refreshPlaybackLink(this, item, resolved -> {
            if (externalLaunchGeneration.get() == launchGeneration) pendingExternalLaunchId = "";
            // Popup dismissal can briefly leave window focus on the menu. The
            // resumed page and navigation generation own this explicit launch.
            if (isFinishing() || isDestroyed() || activeScreen != originScreen
                    || homeFocusGeneration != navigation || externalLaunchGeneration.get() != launchGeneration
                    || !homeActivityResumed) return;
            JSONObject playable = ExternalPlaybackStore.supportedUrl(resolved.optString("url"))
                    ? resolved : item;
            if (!ExternalPlaybackStore.supportedUrl(playable.optString("url"))) {
                Toast.makeText(this, "Lien IPTV indisponible", Toast.LENGTH_SHORT).show();
                return;
            }
            // A cached link is still valid when the portal refresh is
            // temporarily unavailable. Keep the provider episode identity so
            // the resume remains attached to the same SxxExx record.
            Intent player = ExternalPlaybackStore.playerIntent(this, playable);
            if (playerPackage != null) player.putExtra(NuvioPlayerActivity.EXTRA_PLAYER_PACKAGE, playerPackage);
            attachPlayerReturnContext(player, originScreen);
            String titleLogo = existingExternalPlaybackTitleLogo(playable);
            if (ExternalPlaybackStore.supportedUrl(titleLogo)) {
                player.putExtra(NuvioPlayerActivity.EXTRA_TITLE_LOGO, titleLogo);
            }
            if (startFromBeginning) player.putExtra("startFromBeginning", true);
            attachExternalPlayerPresentation(player, playable);
            startActivityForResult(player, REQUEST_NUVIO_PLAYER);
        });
    }

    private long homeIptvUnlockedUntil;

    private void openHomeIptvPlayback(JSONObject item, boolean startFromBeginning, String playerPackage) {
        final String id = item.optString("id");
        if (id.equals(pendingExternalLaunchId)) return;
        pendingExternalLaunchId = id;
        final int generation = externalLaunchGeneration.incrementAndGet();
        final View originScreen = activeScreen;
        final long navigation = homeFocusGeneration;
        new Thread(() -> {
            boolean loaded = false;
            try {
                new com.jojotv.home.iptv.IptvStore(getApplicationContext()).load();
                loaded = true;
            } catch (Exception error) {
                android.util.Log.w("JojoHomeIptv", "Playback library unavailable: " + error.getClass().getSimpleName());
            }
            final boolean ready = loaded;
            runOnUiThread(() -> {
                if (externalLaunchGeneration.get() == generation) pendingExternalLaunchId = "";
                if (isFinishing() || isDestroyed() || activeScreen != originScreen
                        || homeFocusGeneration != navigation || externalLaunchGeneration.get() != generation || !homeActivityResumed) return;
                if (!ready) { Toast.makeText(this, "Bibliothèque IPTV indisponible", Toast.LENGTH_SHORT).show(); return; }
                openHomeIptvPlaybackAfterLoad(item, startFromBeginning, playerPackage);
            });
        }, "JojoHomeIptvAccess").start();
    }

    private void openHomeIptvPlaybackAfterLoad(JSONObject item, boolean startFromBeginning, String playerPackage) {
        if (!com.jojotv.home.iptv.IptvStore.homePlaybackAllowed(this, null, item.optString("id"))
                && android.os.SystemClock.elapsedRealtime() >= homeIptvUnlockedUntil) {
            EditText pin = new EditText(this);
            pin.setInputType(android.text.InputType.TYPE_CLASS_NUMBER | android.text.InputType.TYPE_NUMBER_VARIATION_PASSWORD);
            pin.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(8)});
            AlertDialog dialog = new AlertDialog.Builder(this).setTitle("Code PIN IPTV").setView(pin)
                    .setNegativeButton("Annuler", null).setPositiveButton("Valider", null).create();
            dialog.setOnShowListener(ignored -> dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(view -> {
                if (!com.jojotv.home.iptv.IptvStore.homePlaybackAllowed(this, pin.getText().toString(), item.optString("id"))) {
                    pin.setError("Code PIN incorrect"); return;
                }
                long remember = com.jojotv.home.iptv.IptvStore.homePinRememberMillis();
                homeIptvUnlockedUntil = remember == Long.MAX_VALUE ? Long.MAX_VALUE
                        : android.os.SystemClock.elapsedRealtime() + remember;
                dialog.dismiss();
                prepareHomeIptvPlayback(item, startFromBeginning, playerPackage);
            }));
            dialog.show(); pin.requestFocus();
            return;
        }
        prepareHomeIptvPlayback(item, startFromBeginning, playerPackage);
    }

    private void prepareHomeIptvPlayback(JSONObject item, boolean startFromBeginning, String playerPackage) {
        final String id = item.optString("id");
        if (id.equals(pendingExternalLaunchId)) return;
        pendingExternalLaunchId = id;
        final int generation = externalLaunchGeneration.incrementAndGet();
        final View originScreen = activeScreen;
        final long navigation = homeFocusGeneration;
        new Thread(() -> {
            Intent prepared;
            try { prepared = com.jojotv.home.iptv.IptvStore.homePlayerIntent(getApplicationContext(), id,
                    startFromBeginning, playerPackage, item.optInt("season"), item.optInt("episode")); }
            catch (Exception ignored) { prepared = null; }
            final Intent player = prepared;
            runOnUiThread(() -> {
                if (externalLaunchGeneration.get() == generation) pendingExternalLaunchId = "";
                if (isFinishing() || isDestroyed() || activeScreen != originScreen
                        || homeFocusGeneration != navigation || externalLaunchGeneration.get() != generation || !homeActivityResumed) return;
                if (player == null) { Toast.makeText(this, "Lien IPTV indisponible", Toast.LENGTH_SHORT).show(); return; }
                player.putExtra(NuvioPlayerActivity.EXTRA_PLAYER_ACCENT, playerAccentColor(this));
                attachPlayerReturnContext(player, originScreen);
                String titleLogo = existingExternalPlaybackTitleLogo(item);
                if (ExternalPlaybackStore.supportedUrl(titleLogo)) player.putExtra(NuvioPlayerActivity.EXTRA_TITLE_LOGO, titleLogo);
                attachExternalPlayerPresentation(player, item);
                startActivityForResult(player, REQUEST_NUVIO_PLAYER);
                resumeMutationExecutor.execute(() -> {
                    try { com.jojotv.home.iptv.IptvStore.recordHomePlayback(getApplicationContext(), id,
                            player.getStringExtra(NuvioPlayerActivity.EXTRA_IPTV_ACCOUNT_ID)); }
                    catch (Exception ignored) { }
                });
            });
        }, "JojoHomeIptvPlayback").start();
    }

    private void attachPlayerReturnContext(Intent player, View originScreen) {
        if (player == null) return;
        playerReturnScreen = originScreen;
        playerReturnFocusView = originScreen == null ? null : originScreen.findFocus();
        Object focusTag = playerReturnFocusView == null ? null : playerReturnFocusView.getTag();
        playerReturnFocusKey = focusTag instanceof String ? (String) focusTag : null;
        // A next SMB episode can be launched while the previous card still has focus.
        String contentId = player.getStringExtra(NuvioPlayerActivity.EXTRA_CONTENT_ID);
        if (contentId != null && contentId.startsWith("freebox:smb:")) {
            playerReturnFocusKey = FILE_VIDEO_RESUME_SOURCE + "|"
                    + com.nuvio.tv.data.freebox.FreeboxMediaDisplayKt.freeboxPathFromContentId(contentId);
        }
        pendingPlayerFocusScreen = null;
        playerReturnSeason = -1;
        playerReturnEpisode = -1;
        if (originScreen == null) return;
        String folderUrl = freeboxFolderPageUrls.get(originScreen);
        if (!TextUtils.isEmpty(folderUrl)) {
            player.putExtra(NuvioPlayerActivity.EXTRA_RETURN_FOLDER_URL, folderUrl);
            return;
        }
        String seriesId = tiviMateSeriesPageIds.get(originScreen);
        if (!TextUtils.isEmpty(seriesId)) {
            player.putExtra(NuvioPlayerActivity.EXTRA_RETURN_SERIES_ID, seriesId);
            return;
        }
        String category = homeCategoryPages.get(originScreen);
        if (!TextUtils.isEmpty(category)) {
            player.putExtra(NuvioPlayerActivity.EXTRA_RETURN_HOME_CATEGORY, category);
        }
    }

    private View createTiviMateSeriesPage(JSONObject favorite) {
        return createTiviMateSeriesPage(favorite, null);
    }
    private View createTiviMateSeriesPage(JSONObject favorite, String playerPackage) {
        String rawTitle = favorite.optString("title", "Série");
        String synopsisText = externalPlaybackSynopsis(favorite);
        String title = displayIptvTitle(SystemContinueWatching.displayTitle(rawTitle, synopsisText),
                favorite.optString("season", null), favorite.optString("episode", null));
        String seriesHeroArtwork = selectedExternalFavoriteHeroArtwork(favorite);
        if (seriesHeroArtwork.isEmpty()) seriesHeroArtwork = externalPlaybackArtwork(favorite);
        String seriesThumbnailArtwork = selectedExternalFavoriteArtwork(favorite);
        // Extend the episode-folder Hero by 40 dp over the fixed season selector.
        int heroHeight = dp(359) + dp(40);
        JojoProgram seriesProgram = new JojoProgram("external-playback", title,
                synopsisText, seriesHeroArtwork, favorite.optString("id", ""),
                favorite.optLong("duration"), favorite.optLong("position"), null, null,
                favorite.optBoolean("watched", false));
        LinearLayout page = pickerPage(title, "");
        homeBottomBarHiddenPages.put(page, Boolean.TRUE);
        tiviMateSeriesPageIds.put(page, favorite.optString("id", ""));
        // This provider-backed page uses the same immersive Hero as an
        // original folder page. Hide the generic picker chrome so the Hero
        // remains the single title, artwork and synopsis block.
        if (page.getChildAt(0) != null) page.getChildAt(0).setVisibility(View.GONE);
        if (page.getChildAt(1) != null) page.getChildAt(1).setVisibility(View.GONE);
        if (page.getChildAt(3) != null) page.getChildAt(3).setVisibility(View.GONE);
        if (page.getChildAt(4) != null) page.getChildAt(4).setVisibility(View.GONE);
        if (page.getChildAt(5) != null) page.getChildAt(5).setVisibility(View.GONE);
        page.setPadding(safeEdgeInset(), 0, safeEdgeInset(), videosCategoryBottomPaddingPx(35));
        page.setClipChildren(false);
        page.setClipToPadding(false);
        ViewGroup titleRow = page.getChildAt(2) instanceof ViewGroup
                ? (ViewGroup) page.getChildAt(2) : null;
        if (titleRow != null) titleRow.setVisibility(View.GONE);
        LinearLayout content = (LinearLayout) page.getTag();
        content.setClipChildren(false);
        content.setClipToPadding(false);
        ScrollView detailScroll = new ScrollView(this);
        detailScroll.setVerticalScrollBarEnabled(false);
        detailScroll.setFillViewport(true);
        detailScroll.setClipChildren(false);
        detailScroll.setClipToPadding(false);
        LinearLayout seriesContent = new LinearLayout(this);
        seriesContent.setOrientation(LinearLayout.VERTICAL);
        seriesContent.setClipChildren(false);
        seriesContent.setClipToPadding(false);
        detailScroll.addView(seriesContent, new ScrollView.LayoutParams(-1, -2));
        content.addView(detailScroll, new LinearLayout.LayoutParams(-1, -1));
        FrameLayout hero = new FrameLayout(this);
        hero.setBackgroundColor(Color.BLACK);
        hero.setFocusable(false);
        hero.setClickable(false);
        hero.setDescendantFocusability(ViewGroup.FOCUS_BLOCK_DESCENDANTS);
        hero.setTag(CATEGORY_HERO_PROGRAM_TAG, seriesProgram);
        hero.setTag(CATEGORY_HERO_ITEM_TAG, favorite);
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) hero.setDefaultFocusHighlightEnabled(false);
        hero.setClipChildren(true);
        hero.setClipToPadding(true);
        ImageView backdrop = new HeroArtworkImageView(this, false,
                HERO_HORIZONTAL_FADE_END_FRACTION, 5f);
        backdrop.setTag("home_category_hero_artwork");
        backdrop.setScaleType(ImageView.ScaleType.CENTER_CROP);
        hero.addView(backdrop, new FrameLayout.LayoutParams(
                heroArtworkWidth(), -1, Gravity.RIGHT));
        if (ExternalPlaybackStore.supportedUrl(seriesHeroArtwork)) loadArtwork(backdrop, seriesHeroArtwork);
        View edgeFade = new View(this);
        edgeFade.setBackground(homeHeroEdgeFade(false));
        hero.addView(edgeFade, new FrameLayout.LayoutParams(-1, -1));

        LinearLayout editorial = new LinearLayout(this);
        editorial.setOrientation(LinearLayout.VERTICAL);
        editorial.setClipChildren(false);
        editorial.setClipToPadding(false);
        editorial.setPadding(0, dp(18), dp(12), 0);
        int editorialWidth = Math.min(dp(530),
                Math.round(getResources().getDisplayMetrics().widthPixels * .50f));
        hero.addView(editorial, new FrameLayout.LayoutParams(
                editorialWidth, -1, Gravity.LEFT));
        FrameLayout titleSlot = new FrameLayout(this);
        titleSlot.setClipChildren(false);
        titleSlot.setClipToPadding(false);
        TextView heroTitle = text(title, 31, Color.WHITE);
        heroTitle.setTypeface(null, Typeface.BOLD);
        int fallbackTitleWidth = Math.max(dp(1), editorialWidth
                - editorial.getPaddingRight() - dp(21));
        heroTitle.setText(splitHomeHeroFallbackTitle(title, fallbackTitleWidth, heroTitle.getPaint()));
        heroTitle.setSingleLine(false);
        heroTitle.setMaxLines(2);
        heroTitle.setIncludeFontPadding(false);
        heroTitle.setEllipsize(TextUtils.TruncateAt.END);
        heroTitle.setHorizontallyScrolling(false);
        heroTitle.setGravity(Gravity.TOP | Gravity.LEFT);
        titleSlot.addView(heroTitle, new FrameLayout.LayoutParams(
                FrameLayout.LayoutParams.MATCH_PARENT, FrameLayout.LayoutParams.MATCH_PARENT));
        ImageView titleLogo = folderTitleLogoView();
        titleLogo.setVisibility(View.GONE);
        prepareTitleLogoFallback(titleLogo, heroTitle);
        titleSlot.addView(titleLogo, new FrameLayout.LayoutParams(dp(380), -1, Gravity.LEFT));
        int titleSlotWidth = Math.max(dp(380),
                getResources().getDisplayMetrics().widthPixels - dp(21) - dp(16));
        LinearLayout.LayoutParams titleParams = new LinearLayout.LayoutParams(titleSlotWidth, dp(76));
        titleParams.leftMargin = dp(21);
        editorial.addView(titleSlot, titleParams);
        loadIptvSeriesTitleLogo(favorite, title, titleLogo);

        String year = favorite.optString("year", "").trim();
        String genres = heroGenres(favorite);
        ArrayList<String> metadataParts = new ArrayList<>();
        if (!genres.isEmpty()) metadataParts.add(genres);
        if (!year.isEmpty()) metadataParts.add(year.length() >= 4 ? year.substring(0, 4) : year);
        int runtimeMinutes = externalHeroRuntimeMinutes(favorite);
        String runtime = formatHeroRuntime(runtimeMinutes);
        if (!runtime.isEmpty()) metadataParts.add(runtime);
        TextView metadata = text(TextUtils.join("  •  ", metadataParts), 15, Color.WHITE);
        metadata.setTranslationY(dp(5));
        metadata.setAlpha(.82f);
        metadata.setSingleLine(true);
        metadata.setEllipsize(TextUtils.TruncateAt.END);
        LinearLayout.LayoutParams metadataParams = new LinearLayout.LayoutParams(-1, dp(30));
        metadataParams.topMargin = dp(5);
        metadataParams.leftMargin = dp(21);
        editorial.addView(metadata, metadataParams);
        TextView credits = text("", 13, Color.WHITE);
        credits.setAlpha(.84f);
        credits.setMaxLines(2);
        credits.setEllipsize(TextUtils.TruncateAt.END);
        LinearLayout.LayoutParams creditsParams = new LinearLayout.LayoutParams(-1, dp(36));
        creditsParams.leftMargin = dp(21);
        editorial.addView(credits, creditsParams);
        applyProviderHeroCredits(credits, favorite);

        TextView synopsis = text(synopsisText, 15, Color.WHITE);
        synopsis.setAlpha(.90f);
        synopsis.setMaxLines(8);
        synopsis.setEllipsize(TextUtils.TruncateAt.END);
        LinearLayout.LayoutParams synopsisParams = new LinearLayout.LayoutParams(
                Math.round((editorialWidth - editorial.getPaddingRight() - dp(21)) * .70f), dp(150));
        synopsisParams.leftMargin = dp(21);
        addSeriesSynopsisWithStatus(editorial, synopsis, synopsisParams, favorite);
        final FolderMetadata[] seriesInfo = { null };
        final JSONObject[] seriesItem = { favorite };
        final JSONObject[] providerSeriesDetails = { null };
        final JSONObject[] focusedEpisode = { null };
        final Runnable[] loadAnnouncedEpisodes = { null };
        final java.util.Map<TextView, JSONObject> episodeDateBadges = new java.util.LinkedHashMap<>();
        final int[] rememberedSeasonNumber = { -1 };
        final Runnable[] refreshSeasonStatus = { null };
        refreshSeasonStatus[0] = () -> {
            TextView badge = hero.findViewWithTag("home_category_hero_series_status");
            int seasonCount = Math.max(providerSeriesSeasonCount(providerSeriesDetails[0]),
                    Math.max(providerSeriesSeasonCount(seriesItem[0]), seriesInfo[0] == null ? 0 : seriesInfo[0].seasonCount));
            String status = "TERMINÉ".equals(providerSeriesStatusLabel(seriesItem[0])) ? "TERMINÉ" : "";
            if (seriesInfo[0] != null) {
                status = seriesInfo[0].seriesBroadcastCalendar == null
                        ? ("TERMINÉ".equals(seriesInfo[0].seriesStatus) ? "TERMINÉ" : status)
                        : seriesSeasonCalendarStatus(seriesInfo[0].seriesBroadcastCalendar);
            }
            updateSeriesStatusBadge(badge, status, seasonCount);
        };
        refreshSeasonStatus[0].run();
        java.util.function.Consumer<FolderMetadata> applySeriesInfo = details -> {
            seriesInfo[0] = details;
            details.seasonCount = Math.max(details.seasonCount, Math.max(providerSeriesSeasonCount(seriesItem[0]),
                    providerSeriesSeasonCount(providerSeriesDetails[0])));
            refreshSeasonStatus[0].run();
            if (focusedEpisode[0] != null)
                loadTiviMateEpisodeInfo(metadata, details, seriesItem[0], focusedEpisode[0]);
            if (loadAnnouncedEpisodes[0] != null) loadAnnouncedEpisodes[0].run();
        };
        loadExternalInfoMetadata(hero, "series", seriesProgram, favorite,
                titleLogo, metadata, credits, synopsis, applySeriesInfo);

        LinearLayout.LayoutParams heroParams = new LinearLayout.LayoutParams(-1, heroHeight);
        heroParams.leftMargin = -safeEdgeInset();
        heroParams.rightMargin = -safeEdgeInset();
        heroParams.bottomMargin = -dp(40);
        seriesContent.addView(hero, heroParams);
        HorizontalScrollView seasonScroll = new HorizontalScrollView(this);
        seasonScroll.setHorizontalScrollBarEnabled(false);
        LinearLayout seasonRow = new LinearLayout(this);
        seasonRow.setTag(FOLDER_MEDIA_ROW_TAG, "seasons");
        seasonRow.setClipChildren(false);
        seasonRow.setClipToPadding(false);
        seasonRow.addView(text("Chargement…", 16, muted), new LinearLayout.LayoutParams(dp(220), dp(58)));
        seasonScroll.addView(seasonRow);
        LinearLayout.LayoutParams seasonParams = new LinearLayout.LayoutParams(-1, dp(60));
        // Lift the season selector and episode rail another 15 dp so the
        // episode thumbnails stay fully visible at the bottom of the screen.
        seasonParams.topMargin = dp(5) - dp(30);
        seriesContent.addView(seasonScroll, seasonParams);
        // Move only the visible selector; episode-rail fitting must not absorb this offset.
        seasonScroll.setTranslationY(dp(40));

        HorizontalScrollView episodeScroll = new HorizontalScrollView(this);
        episodeScroll.setHorizontalScrollBarEnabled(false);
        episodeScroll.setClipChildren(false);
        episodeScroll.setClipToPadding(false);
        episodeScroll.setTranslationY(dp(18));
        LinearLayout episodeRow = new LinearLayout(this);
        episodeRow.setTag(FOLDER_MEDIA_ROW_TAG, "episodes");
        episodeRow.setClipChildren(false);
        episodeRow.setClipToPadding(false);
        episodeRow.addView(text("Chargement des épisodes…", 16, muted),
                new LinearLayout.LayoutParams(dp(320), dp(30)));
        episodeScroll.addView(episodeRow);
        LinearLayout.LayoutParams episodeParams = new LinearLayout.LayoutParams(
                -1, dp(36));
        episodeParams.topMargin = dp(20);
        seriesContent.addView(episodeScroll, episodeParams);
        episodeScroll.post(() -> positionTiviMateSeriesEpisodeRail(seriesContent, detailScroll,
                hero, heroParams, seasonParams, episodeScroll, episodeParams, dp(30)));

        Runnable refreshProviderHeader = () -> {
            if (!page.isAttachedToWindow() || activeScreen != page) return;
            JSONObject refreshed = ExternalPlaybackStore.get(this, favorite.optString("id", ""));
            if (refreshed.has("id")) {
                seriesItem[0] = refreshed;
                metadata.setText(homeCategoryHeroMetadata("series", seriesProgram, refreshed));
                applyProviderHeroCredits(credits, refreshed);
                String refreshedSynopsis = externalPlaybackSynopsis(refreshed);
                if (!refreshedSynopsis.isEmpty()) synopsis.setText(shortenContinueWatchingHeroSynopsis(refreshedSynopsis));
                refreshSeasonStatus[0].run();
                loadIptvSeriesTitleLogo(refreshed, title, titleLogo);
                loadExternalInfoMetadata(hero, "series", seriesProgram, refreshed,
                        titleLogo, metadata, credits, synopsis, applySeriesInfo);
            }
        };
        final boolean[] seriesEpisodesRendered = { false };
        java.util.function.Consumer<JSONObject> renderSeriesDetails = details -> {
            if (!page.isAttachedToWindow() || activeScreen != page) return;
            boolean returningFromPlayer = pendingPlayerFocusScreen == page;
            boolean restoreEpisodeFocus = returningFromPlayer || episodeRow.hasFocus();
            if (returningFromPlayer && playerReturnSeason > 0) rememberedSeasonNumber[0] = playerReturnSeason;
            String focusedCoordinate = focusedEpisode[0] == null ? ""
                    : focusedEpisode[0].optInt("season") + ":" + focusedEpisode[0].optInt("episode");
            if (returningFromPlayer && playerReturnSeason > 0 && playerReturnEpisode > 0)
                focusedCoordinate = playerReturnSeason + ":" + playerReturnEpisode;
            boolean restoreSeasonFocus = seasonRow.hasFocus();
            int previousScrollX = episodeScroll.getScrollX();
            java.util.Map<String, View> episodeTiles = new java.util.HashMap<>();
            JSONArray seasons = details.optJSONArray("seasons");
            if ((seasons == null || seasons.length() == 0) && seriesEpisodesRendered[0]) {
                restorePlayerReturnFocus(page, null);
                return;
            }
            refreshSeasonStatus[0].run();
            seasonRow.removeAllViews();
            episodeRow.removeAllViews();
            episodeDateBadges.clear();
            if (seasons == null || seasons.length() == 0) {
                seasonRow.addView(text("Saisons indisponibles chez le fournisseur.", 16, muted),
                        new LinearLayout.LayoutParams(dp(520), dp(58)));
                episodeRow.addView(text("Aucun épisode disponible.", 16, muted),
                        new LinearLayout.LayoutParams(dp(360), dp(30)));
                positionTiviMateSeriesEpisodeRail(seriesContent, detailScroll, hero, heroParams,
                        seasonParams, episodeScroll, episodeParams, dp(30));
                return;
            }
            final Runnable[] renderSelectedSeason = new Runnable[1];
            final int[] selectedSeason = { 0 };
            for (int index = 0; index < seasons.length(); index++) {
                JSONObject season = seasons.optJSONObject(index);
                if (season != null && season.optInt("number") == rememberedSeasonNumber[0]) selectedSeason[0] = index;
            }
            renderSelectedSeason[0] = () -> {
                episodeRow.removeAllViews();
                episodeDateBadges.clear();
                episodeTiles.clear();
                JSONObject season = seasons.optJSONObject(selectedSeason[0]);
                rememberedSeasonNumber[0] = season == null ? selectedSeason[0] + 1 : season.optInt("number", selectedSeason[0] + 1);
                refreshSeasonStatus[0].run();
                JSONArray episodes = season == null ? null : season.optJSONArray("episodes");
                if (episodes == null || episodes.length() == 0) {
                    episodeRow.addView(text("Aucun épisode disponible.", 16, muted),
                            new LinearLayout.LayoutParams(dp(360), dp(30)));
                    positionTiviMateSeriesEpisodeRail(seriesContent, detailScroll, hero, heroParams,
                            seasonParams, episodeScroll, episodeParams, dp(30));
                    return;
                }
                int episodeThumbnailWidth = Math.round(
                        dp(continueWatchingTileWidthDp()) * SERIES_EPISODE_THUMBNAIL_SCALE);
                int maxEpisodeContentHeightPx = 0;
                for (int index = 0; index < episodes.length(); index++) {
                    JSONObject episode = episodes.optJSONObject(index);
                    if (episode == null) continue;
                    int seasonNumber = episode.optInt("season", selectedSeason[0] + 1);
                    int episodeNumber = episode.optInt("episode", index + 1);
                    String airDate = seriesEpisodeAirDate(episode);
                    String label = String.format(Locale.ROOT, "S%02dE%02d", seasonNumber, episodeNumber);
                    String dateLabel = HomeMediaRules.seriesEpisodeDateBadge(airDate, java.time.LocalDate.now());
                    String episodeArtwork = externalPlaybackArtwork(episode);
                    // Keep manual choices, then use the episode image before the series fallback.
                    JojoProgram program = new JojoProgram("external-playback-series-episode", label,
                            externalPlaybackSynopsis(episode),
                            selectedSeriesEpisodeArtwork(episode,
                                    episodeArtwork.isEmpty() ? seriesThumbnailArtwork : episodeArtwork),
                            episode.optString("id"), episode.optLong("duration"), episode.optLong("position"),
                            String.valueOf(seasonNumber), String.valueOf(episodeNumber),
                            episode.optBoolean("watched", false));
                    // The episode rail is landscape independently of the
                    // Series-wide thumbnail setting; share this with its picker.
                    final boolean portraitEpisodeArtwork = false;
                    View tile = jojoProgramTile(program, false, portraitEpisodeArtwork);
                    View.OnFocusChangeListener previousFocus = tile.getOnFocusChangeListener();
                    tile.setOnFocusChangeListener((view, focused) -> {
                        if (previousFocus != null) previousFocus.onFocusChange(view, focused);
                        if (focused) {
                            focusedEpisode[0] = episode;
                            loadTiviMateEpisodeInfo(metadata, seriesInfo[0], seriesItem[0], episode);
                        }
                    });
                    View thumbnail = tile.findViewWithTag("jojo_program_tile_artwork_frame");
                    View statusHost = tile.findViewWithTag("series_episode_status_host");
                    if (statusHost instanceof FrameLayout && HomeMediaRules.episodeAirDate(airDate) != null) {
                        TextView dateBadge = text(dateLabel, 9, contrastingFolderThemeTextColor());
                        dateBadge.setTag("series_episode_air_date");
                        dateBadge.setTypeface(null, Typeface.BOLD);
                        dateBadge.setGravity(Gravity.CENTER); dateBadge.setSingleLine(true);
                        dateBadge.setPadding(dp(5), 0, dp(5), 0);
                        dateBadge.setBackground(episodeStatusBadgeBg(false));
                        dateBadge.setContentDescription("Diffusion prévue le " + dateLabel);
                        dateBadge.setVisibility(dateLabel.isEmpty() ? View.GONE : View.VISIBLE);
                        FrameLayout.LayoutParams badgeParams = new FrameLayout.LayoutParams(-2, dp(22), Gravity.TOP | Gravity.RIGHT);
                        badgeParams.setMargins(0, dp(5), dp(5), 0);
                        ((FrameLayout) statusHost).addView(dateBadge, badgeParams);
                        episodeDateBadges.put(dateBadge, episode);
                    }
                    if (thumbnail != null
                            && thumbnail.getLayoutParams() instanceof LinearLayout.LayoutParams) {
                        LinearLayout.LayoutParams artworkParams =
                                (LinearLayout.LayoutParams) thumbnail.getLayoutParams();
                        int fullArtworkHeight = artworkParams.height;
                        int scaledArtworkHeight = Math.round(
                                fullArtworkHeight * SERIES_EPISODE_THUMBNAIL_SCALE);
                        int topInset = dp(2);
                        artworkParams.width = episodeThumbnailWidth;
                        artworkParams.height = scaledArtworkHeight;
                        artworkParams.bottomMargin += topInset;
                        thumbnail.setScaleX(1f);
                        thumbnail.setScaleY(1f);
                        thumbnail.setTranslationY(topInset);
                        // Keep the card's layout slot equal to the visible image height
                        // so the episode text begins directly beneath the scaled artwork.
                        thumbnail.setLayoutParams(artworkParams);
                    }
                    tile.setTranslationY(dp(5));
                    if (tile instanceof ViewGroup) {
                        ViewGroup episodeTile = (ViewGroup) tile;
                        boolean firstEpisodeLabel = true;
                        for (int childIndex = 0; childIndex < episodeTile.getChildCount(); childIndex++) {
                            View child = episodeTile.getChildAt(childIndex);
                            if (child instanceof TextView) {
                                child.setTranslationY(dp(1));
                                if (firstEpisodeLabel) {
                                    TextView episodeTitleView = (TextView) child;
                                    episodeTitleView.setPadding(episodeTitleView.getPaddingLeft(), 0,
                                            episodeTitleView.getPaddingRight(), episodeTitleView.getPaddingBottom());
                                    episodeTitleView.setText(label);
                                    firstEpisodeLabel = false;
                                }
                            }
                        }
                    }
                    tile.setId(View.generateViewId());
                    tile.setOnClickListener(v -> {
                        if (episode.optBoolean("scheduledEpisode"))
                            Toast.makeText(this, "Épisode pas encore disponible chez le fournisseur IPTV", Toast.LENGTH_LONG).show();
                        else openExternalPlayback(episode, false, false, playerPackage);
                    });
                    tile.setOnLongClickListener(v -> {
                        String tileKey = String.valueOf(tile.getTag());
                        showSeriesEpisodeMenu(episode, tile, title, portraitEpisodeArtwork, hero, (preview, artworkUrl) -> {
                            if (!page.isAttachedToWindow() || activeScreen != page) return;
                            int scrollX = episodeScroll.getScrollX();
                            episodeRow.removeAllViews();
                            renderSelectedSeason[0].run();
                            episodeScroll.post(() -> {
                                episodeScroll.scrollTo(scrollX, 0);
                                for (int childIndex = 0; childIndex < episodeRow.getChildCount(); childIndex++) {
                                    View refreshedTile = episodeRow.getChildAt(childIndex);
                                    if (tileKey.equals(String.valueOf(refreshedTile.getTag()))) {
                                        showSelectedArtwork(resolveArtworkView(refreshedTile), preview, artworkUrl);
                                        refreshedTile.requestFocus();
                                        break;
                                    }
                                }
                            });
                        });
                        return true;
                    });
                    int tileContentHeightPx = tiviMateEpisodeTileVisibleHeightPx(tile);
                    maxEpisodeContentHeightPx = Math.max(maxEpisodeContentHeightPx, tileContentHeightPx);
                    episodeRow.addView(tile, new LinearLayout.LayoutParams(episodeThumbnailWidth,
                            tileContentHeightPx) {{ rightMargin = dp(13); }});
                    episodeTiles.put(seasonNumber + ":" + episodeNumber, tile);
                }
                wireCyclicHorizontalCardRowDpad(episodeRow);
                positionTiviMateSeriesEpisodeRail(seriesContent, detailScroll, hero, heroParams,
                        seasonParams, episodeScroll, episodeParams, maxEpisodeContentHeightPx);
                View firstEpisode = episodeRow.getChildAt(0);
                View selectedSeasonButton = seasonRow.getChildAt(selectedSeason[0]);
                if (firstEpisode != null && selectedSeasonButton != null) {
                    for (int index = 0; index < seasonRow.getChildCount(); index++) {
                        seasonRow.getChildAt(index).setNextFocusDownId(firstEpisode.getId());
                    }
                    for (int index = 0; index < episodeRow.getChildCount(); index++) {
                        View episode = episodeRow.getChildAt(index);
                        if (episode.isFocusable()) {
                            episode.setNextFocusUpId(selectedSeasonButton.getId());
                            episode.setNextFocusDownId(episode.getId());
                        }
                    }
                }
            };
            for (int index = 0; index < seasons.length(); index++) {
                JSONObject season = seasons.optJSONObject(index);
                int number = season == null ? index + 1 : season.optInt("number", index + 1);
                TextView button = text("Saison " + number, 16, white);
                button.setId(View.generateViewId());
                button.setFocusable(true);
                button.setNextFocusUpId(button.getId());
                button.setGravity(Gravity.CENTER);
                button.setPadding(dp(18), 0, dp(18), 0);
                final int seasonIndex = index;
                button.setOnClickListener(v -> {
                    selectedSeason[0] = seasonIndex;
                    renderSelectedSeason[0].run();
                });
                button.setBackground(folderPaletteControlBg(false, 10));
                button.setOnFocusChangeListener((v, focused) -> {
                    v.setBackground(folderPaletteControlBg(focused, 10));
                    button.setTextColor(focused ? contrastingFolderThemeTextColor() : white);
                });
                seasonRow.addView(button, new LinearLayout.LayoutParams(dp(150), dp(50)) {{ rightMargin = dp(12); }});
            }
            wireCyclicHorizontalCardRowDpad(seasonRow);
            renderSelectedSeason[0].run();
            View seasonButton = seasonRow.getChildAt(selectedSeason[0]);
            View episodeTile = episodeTiles.get(focusedCoordinate);
            if (restoreEpisodeFocus && episodeTile != null) {
                if (returningFromPlayer) restorePlayerReturnFocus(page, episodeTile);
                else {
                    episodeTile.requestFocus();
                    episodeScroll.post(() -> episodeScroll.scrollTo(previousScrollX, 0));
                }
            } else if (returningFromPlayer) {
                if (!restorePlayerReturnFocus(page, null))
                    restorePlayerReturnFocus(page, episodeRow.getChildAt(0));
            } else if (seasonButton != null && (!seriesEpisodesRendered[0] || restoreSeasonFocus || page.findFocus() == null)) seasonButton.requestFocus();
            seriesEpisodesRendered[0] = true;
        };
        final int[] announcedRequestId = { 0 };
        final int[] announcedRequestVersion = { 0 };
        loadAnnouncedEpisodes[0] = () -> {
            if (providerSeriesDetails[0] == null || seriesInfo[0] == null
                    || !"tv".equals(seriesInfo[0].tmdbMediaType) || seriesInfo[0].tmdbId <= 0) return;
            int tmdbId = seriesInfo[0].tmdbId;
            if (announcedRequestId[0] == tmdbId) return;
            announcedRequestId[0] = tmdbId;
            int version = ++announcedRequestVersion[0];
            int preferredSeason = rememberedSeasonNumber[0];
            JSONObject providerDetails = providerSeriesDetails[0];
            String cacheKey = "iptv_announced_episodes_v2_" + tmdbId;
            android.content.SharedPreferences cache = getSharedPreferences("home_hero_editorial_cache", MODE_PRIVATE);
            java.util.function.Consumer<JSONObject> applyAnnouncements = announced -> {
                if (version != announcedRequestVersion[0] || !page.isAttachedToWindow() || activeScreen != page || seriesInfo[0] == null
                        || seriesInfo[0].tmdbId != tmdbId) return;
                seriesInfo[0].seasonCount = Math.max(seriesInfo[0].seasonCount, announced.optInt("seasonCount"));
                refreshSeasonStatus[0].run();
                try { renderSeriesDetails.accept(mergeAnnouncedSeriesDetails(providerDetails, announced, seriesItem[0], tmdbId)); }
                catch (org.json.JSONException ignored) { }
            };
            try {
                String cached = cache.getString(cacheKey, "");
                if (!cached.isEmpty()) applyAnnouncements.accept(new JSONObject(cached));
            } catch (org.json.JSONException ignored) { }
            new Thread(() -> {
                try {
                    fetchAnnouncedSeriesEpisodes(tmdbId, providerDetails, preferredSeason, announced -> {
                        cache.edit().putString(cacheKey, announced.toString()).apply();
                        runOnUiThread(() -> applyAnnouncements.accept(announced));
                    });
                } catch (Exception error) {
                    android.util.Log.w("JojoHomeSeriesEpisodes", "Announcements unavailable: " + error.getClass().getSimpleName());
                }
            }, "JojoHomeAnnouncedEpisodes").start();
        };
        scheduleSeriesEpisodeDateBadges(page, episodeDateBadges, refreshSeasonStatus[0]);
        Runnable reloadSeriesDetails = () -> ExternalPlaybackStore.loadProviderSeriesDetails(this,
                favorite.optString("id", ""), details -> {
            if (!page.isAttachedToWindow() || activeScreen != page) return;
            providerSeriesDetails[0] = details;
            renderSeriesDetails.accept(details);
            refreshProviderHeader.run();
            loadAnnouncedEpisodes[0].run();
        }, refreshProviderHeader);
        page.setTag(SERIES_PAGE_REFRESH_TAG, (Runnable) () -> {
            if (activeScreen != page) return;
            announcedRequestId[0] = 0;
            reloadSeriesDetails.run();
        });
        reloadSeriesDetails.run();
        return page;
    }

    private String seriesEpisodeAirDate(JSONObject episode) {
        return firstExternalValue(episode, "airDate", "air_date", "released", "release_date", "releaseDate");
    }

    private int[] latestProviderSeriesEpisode(JSONObject details) {
        int[] latest = { 0, 0 };
        JSONArray seasons = details.optJSONArray("seasons");
        if (seasons == null) return latest;
        for (int index = 0; index < seasons.length(); index++) {
            JSONObject season = seasons.optJSONObject(index);
            JSONArray episodes = season == null ? null : season.optJSONArray("episodes");
            if (episodes == null) continue;
            for (int item = 0; item < episodes.length(); item++) {
                JSONObject episode = episodes.optJSONObject(item);
                if (episode == null) continue;
                int seasonNumber = episode.optInt("season", season.optInt("number"));
                int episodeNumber = episode.optInt("episode");
                if (seasonNumber > latest[0] || (seasonNumber == latest[0] && episodeNumber > latest[1])) {
                    latest[0] = seasonNumber;
                    latest[1] = episodeNumber;
                }
            }
        }
        return latest;
    }

    private void fetchAnnouncedSeriesEpisodes(int tmdbId, JSONObject providerDetails, int preferredSeason,
            java.util.function.Consumer<JSONObject> publish) throws Exception {
        String query = "?api_key=" + java.net.URLEncoder.encode(BuildConfig.TMDB_API_KEY, "UTF-8") + "&language=fr-FR";
        String seriesUrl = "https://api.themoviedb.org/3/tv/" + tmdbId;
        JSONObject details = fetchJson(seriesUrl + query);
        boolean ongoing = HomeMediaRules.ongoingSeries(details.optString("status"), details.optBoolean("in_production"));
        JSONArray result = new JSONArray();
        JSONArray seasons = details.optJSONArray("seasons");
        int firstSeason = Math.max(1, latestProviderSeriesEpisode(providerDetails)[0]);
        java.util.Set<Integer> providerSeasonNumbers = new java.util.HashSet<>();
        JSONArray providerSeasons = providerDetails.optJSONArray("seasons");
        if (providerSeasons != null) for (int index = 0; index < providerSeasons.length(); index++) {
            JSONObject season = providerSeasons.optJSONObject(index);
            if (season != null) providerSeasonNumbers.add(season.optInt("number", index + 1));
        }
        java.util.Set<Integer> requestedSeasons = new java.util.LinkedHashSet<>();
        if (providerSeasonNumbers.contains(preferredSeason)) requestedSeasons.add(preferredSeason);
        if (seasons != null) {
            for (int index = 0; index < seasons.length(); index++) {
                JSONObject season = seasons.optJSONObject(index);
                if (season == null) continue;
                int number = season.optInt("season_number");
                if (season.optInt("episode_count") > 0 && (providerSeasonNumbers.contains(number)
                        || ongoing && number >= firstSeason)) requestedSeasons.add(number);
            }
        }
        JSONObject payload = new JSONObject().put("ongoing", ongoing).put("seasons", result)
                .put("seasonCount", details.optInt("number_of_seasons"))
                .put("seriesStatus", HomeMediaRules.seriesStatusLabel(details.optString("status"),
                        details.optBoolean("in_production")));
        for (int number : requestedSeasons) {
            JSONObject seasonDetails = fetchJson(seriesUrl + "/season/" + number + query);
            JSONArray episodes = seasonDetails.optJSONArray("episodes");
            if (episodes != null) result.put(new JSONObject().put("number", number).put("episodes", episodes));
            // Publish the visible season first, without waiting for every other season.
            publish.accept(new JSONObject(payload.toString()));
        }
        if (requestedSeasons.isEmpty()) publish.accept(payload);
    }

    private JSONObject mergeAnnouncedSeriesDetails(JSONObject providerDetails, JSONObject announced,
            JSONObject series, int tmdbId) throws org.json.JSONException {
        JSONObject merged = new JSONObject(providerDetails.toString());
        int[] latest = latestProviderSeriesEpisode(providerDetails);
        java.util.Map<Integer, JSONObject> seasonsByNumber = new java.util.TreeMap<>();
        java.util.Map<String, java.util.List<JSONObject>> providerEpisodes = new java.util.HashMap<>();
        java.util.Map<String, java.util.Set<String>> artworkEpisodes = new java.util.HashMap<>();
        JSONArray providerSeasons = merged.optJSONArray("seasons");
        if (providerSeasons != null) for (int index = 0; index < providerSeasons.length(); index++) {
            JSONObject season = providerSeasons.optJSONObject(index);
            if (season == null) continue;
            int number = season.optInt("number", index + 1);
            seasonsByNumber.put(number, season);
            JSONArray episodes = season.optJSONArray("episodes");
            if (episodes == null) continue;
            for (int item = 0; item < episodes.length(); item++) {
                JSONObject episode = episodes.optJSONObject(item);
                if (episode == null) continue;
                String coordinate = episode.optInt("season", number) + ":" + episode.optInt("episode", item + 1);
                providerEpisodes.computeIfAbsent(coordinate, key -> new ArrayList<>()).add(episode);
                String artwork = externalPlaybackArtwork(episode);
                if (!artwork.isEmpty()) artworkEpisodes.computeIfAbsent(artwork, key -> new java.util.HashSet<>()).add(coordinate);
            }
        }
        JSONArray announcedSeasons = announced.optJSONArray("seasons");
        java.time.LocalDate today = java.time.LocalDate.now();
        if (announcedSeasons != null) for (int index = 0; index < announcedSeasons.length(); index++) {
            JSONObject season = announcedSeasons.optJSONObject(index);
            JSONArray episodes = season == null ? null : season.optJSONArray("episodes");
            if (episodes == null) continue;
            int seasonNumber = season.optInt("number");
            for (int item = 0; item < episodes.length(); item++) {
                JSONObject official = episodes.optJSONObject(item);
                if (official == null) continue;
                int episodeNumber = official.optInt("episode_number");
                String airDate = official.optString("air_date", "");
                String coordinate = seasonNumber + ":" + episodeNumber;
                java.util.List<JSONObject> available = providerEpisodes.get(coordinate);
                if (available != null) {
                    for (JSONObject episode : available) {
                        if (HomeMediaRules.episodeAirDate(seriesEpisodeAirDate(episode)) == null
                                && HomeMediaRules.episodeAirDate(airDate) != null) episode.put("airDate", airDate);
                        String providerArtwork = externalPlaybackArtwork(episode);
                        java.util.Set<String> coordinates = artworkEpisodes.get(providerArtwork);
                        boolean genericArtwork = providerArtwork.equals(externalPlaybackArtwork(series))
                                || providerArtwork.equals(series.optString("backdrop"))
                                || coordinates != null && coordinates.size() > 1;
                        String artwork = HomeMediaRules.seriesEpisodeArtwork(providerArtwork, genericArtwork,
                                official.optString("still_path"));
                        if (!artwork.isEmpty()) episode.put("artwork", artwork);
                    }
                    continue;
                }
                if (!announced.optBoolean("ongoing") || !HomeMediaRules.announcedSeriesEpisode(
                        seasonNumber, episodeNumber, airDate, latest[0], latest[1], today)) continue;
                JSONObject targetSeason = seasonsByNumber.get(seasonNumber);
                if (targetSeason == null) {
                    targetSeason = new JSONObject().put("number", seasonNumber).put("episodes", new JSONArray());
                    seasonsByNumber.put(seasonNumber, targetSeason);
                }
                String still = official.optString("still_path", "");
                String artwork = still.startsWith("/") ? "https://image.tmdb.org/t/p/w780" + still
                        : firstExternalValue(series, "backdrop", "artwork", "poster");
                JSONObject episode = new JSONObject()
                        .put("id", "announced:" + series.optString("id") + ":" + coordinate)
                        .put("title", series.optString("title")).put("episodeTitle", official.optString("name"))
                        .put("season", seasonNumber).put("episode", episodeNumber).put("airDate", airDate)
                        .put("description", official.optString("overview")).put("artwork", artwork)
                        .put("runtimeMinutes", official.optInt("runtime")).put("tmdbId", tmdbId)
                        .put("scheduledEpisode", true);
                for (String field : new String[]{"favoriteSource", "stalkerSource", "stalkerProviderAccount", "stalkerSeriesId"}) {
                    if (series.has(field)) episode.put(field, series.opt(field));
                }
                if ("jojo-iptv".equals(series.optString("favoriteSource"))) episode.put("iptvSeriesId", series.optString("id"));
                JSONArray targetEpisodes = targetSeason.optJSONArray("episodes");
                if (targetEpisodes == null) targetSeason.put("episodes", targetEpisodes = new JSONArray());
                targetEpisodes.put(episode);
                providerEpisodes.put(coordinate, java.util.Collections.singletonList(episode));
            }
        }
        JSONArray seasons = new JSONArray();
        for (JSONObject season : seasonsByNumber.values()) {
            JSONArray episodes = season.optJSONArray("episodes");
            ArrayList<JSONObject> sorted = new ArrayList<>();
            if (episodes != null) for (int index = 0; index < episodes.length(); index++) {
                JSONObject episode = episodes.optJSONObject(index);
                if (episode != null) sorted.add(episode);
            }
            sorted.sort(java.util.Comparator.comparingInt(episode -> episode.optInt("episode")));
            JSONArray ordered = new JSONArray();
            for (JSONObject episode : sorted) ordered.put(episode);
            season.put("episodes", ordered);
            seasons.put(season);
        }
        return merged.put("seasons", seasons);
    }

    private String seriesSeasonCalendarStatus(JSONObject season) {
        JSONArray episodes = season.optJSONArray("episodes");
        if (episodes == null || season.optInt("episode_count") <= 0) return "";
        java.util.Map<Integer, String> dates = new java.util.TreeMap<>();
        int lastEpisode = 0;
        for (int index = 0; index < episodes.length(); index++) {
            JSONObject episode = episodes.optJSONObject(index);
            if (episode == null) continue;
            int number = episode.optInt("episode_number");
            if (number <= 0) continue;
            dates.put(number, episode.optString("air_date", ""));
            lastEpisode = Math.max(lastEpisode, number);
        }
        int expectedEpisodes = Math.max(lastEpisode, season.optInt("episode_count"));
        return HomeMediaRules.seasonStatusLabel(expectedEpisodes, dates.values(), java.time.LocalDate.now());
    }

    private void scheduleSeriesEpisodeDateBadges(View page, java.util.Map<TextView, JSONObject> badges,
                                                Runnable refreshSeasonStatus) {
        Runnable refresh = new Runnable() {
            @Override public void run() {
                if (!page.isAttachedToWindow()) return;
                java.time.LocalDate today = java.time.LocalDate.now();
                for (java.util.Map.Entry<TextView, JSONObject> entry : badges.entrySet()) {
                    JSONObject episode = entry.getValue();
                    String date = HomeMediaRules.seriesEpisodeDateBadge(seriesEpisodeAirDate(episode), today);
                    entry.getKey().setText(date);
                    entry.getKey().setContentDescription("Diffusion prévue le " + date);
                    entry.getKey().setVisibility(date.isEmpty() ? View.GONE : View.VISIBLE);
                }
                refreshSeasonStatus.run();
                long delay = java.time.Duration.between(java.time.Instant.now(), today.plusDays(1)
                        .atStartOfDay(java.time.ZoneId.systemDefault()).toInstant()).toMillis();
                page.postDelayed(this, Math.max(1000L, delay));
            }
        };
        page.addOnAttachStateChangeListener(new View.OnAttachStateChangeListener() {
            @Override public void onViewAttachedToWindow(View view) { view.post(refresh); }
            @Override public void onViewDetachedFromWindow(View view) { view.removeCallbacks(refresh); }
        });
    }

    private int tiviMateEpisodeTileVisibleHeightPx(View tile) {
        if (!(tile instanceof ViewGroup)) return 0;
        int childTop = 0;
        int visibleBottom = 0;
        ViewGroup card = (ViewGroup) tile;
        for (int index = 0; index < card.getChildCount(); index++) {
            View child = card.getChildAt(index);
            if (child.getVisibility() == View.GONE) continue;
            ViewGroup.LayoutParams params = child.getLayoutParams();
            int childHeight = params != null && params.height > 0
                    ? params.height : child.getMeasuredHeight();
            int topMargin = params instanceof ViewGroup.MarginLayoutParams
                    ? ((ViewGroup.MarginLayoutParams) params).topMargin : 0;
            int bottomMargin = params instanceof ViewGroup.MarginLayoutParams
                    ? ((ViewGroup.MarginLayoutParams) params).bottomMargin : 0;
            childTop += topMargin;
            visibleBottom = Math.max(visibleBottom, childTop + childHeight
                    + Math.round(child.getTranslationY()));
            childTop += childHeight + bottomMargin;
        }
        return Math.max(0, visibleBottom + Math.round(tile.getTranslationY()));
    }

    private void positionTiviMateSeriesEpisodeRail(
            LinearLayout seriesContent, ScrollView detailScroll,
            FrameLayout hero, LinearLayout.LayoutParams heroParams,
            LinearLayout.LayoutParams seasonParams,
            HorizontalScrollView episodeScroll, LinearLayout.LayoutParams episodeParams,
            int visibleContentHeightPx) {
        if (visibleContentHeightPx <= 0) return;
        episodeParams.height = visibleContentHeightPx + dp(6);
        int viewportHeight = detailScroll.getHeight();
        if (viewportHeight > 0) {
            int minimumSeasonGap = dp(20);
            int fixedSeasonHeight = seasonParams.topMargin + seasonParams.height;
            int availableSeasonGap = viewportHeight - heroParams.height - heroParams.bottomMargin
                    - fixedSeasonHeight - episodeParams.height;
            if (availableSeasonGap < minimumSeasonGap) {
                // Fit the rows by overlapping the Hero, without shrinking its artwork.
                int heroLayoutHeight = Math.max(dp(190), heroParams.height + heroParams.bottomMargin
                        - (minimumSeasonGap - availableSeasonGap));
                int bottomMargin = heroLayoutHeight - heroParams.height;
                if (bottomMargin != heroParams.bottomMargin) {
                    heroParams.bottomMargin = bottomMargin;
                    hero.setLayoutParams(heroParams);
                }
                availableSeasonGap = viewportHeight - heroParams.height - heroParams.bottomMargin
                        - fixedSeasonHeight - episodeParams.height;
            }
            episodeParams.topMargin = Math.max(0, availableSeasonGap);
        }
        episodeScroll.setLayoutParams(episodeParams);
        detailScroll.post(() -> {
            if (!detailScroll.isAttachedToWindow()) return;
            int bottomScroll = Math.max(0, seriesContent.getHeight() - detailScroll.getHeight());
            if (detailScroll.getScrollY() != bottomScroll) detailScroll.scrollTo(0, bottomScroll);
        });
    }

    private interface ResumeArtworkSelectionRefresh {
        void refresh(ImageView preview, String artworkUrl);
    }

    private void showSeriesEpisodeMenu(JSONObject episode, View anchor, String seriesTitle,
                                       boolean portraitArtwork, View categoryHeroAnchor,
                                       ResumeArtworkSelectionRefresh refreshEpisodeRow) {
        LinearLayout menu = new LinearLayout(this);
        menu.setOrientation(LinearLayout.VERTICAL);
        menu.setBackground(lightMenuBg());
        PopupWindow popup = new PopupWindow(menu, dp(310), -2, true);
        popup.setBackgroundDrawable(lightMenuBg());
        popup.setOutsideTouchable(true);
        popup.setElevation(dp(12));
        trackPopup(popup);
        View watched = popupRow(R.drawable.ic_refresh, "Marquer comme vu");
        boolean scheduledEpisode = episode.optBoolean("scheduledEpisode");
        if (!scheduledEpisode) menu.addView(watched);
        View unwatched = popupRow(R.drawable.ic_reset_arrow, "Marquer comme non vu");
        if (!scheduledEpisode) menu.addView(unwatched);
        View restart = popupRow(R.drawable.ic_reset_arrow, "Reprendre depuis le début");
        if (!scheduledEpisode) menu.addView(restart);
        View artwork = popupRow(R.drawable.ic_menu_wallpaper, "Changer de vignette");
        menu.addView(artwork);
        if (categoryHeroAnchor != null) {
            View heroArtwork = popupRow(R.drawable.ic_menu_wallpaper, "Changer la vignette du Hero");
            menu.addView(heroArtwork);
            heroArtwork.setOnClickListener(v -> {
                popup.dismiss();
                chooseCategoryHeroArtwork(null, categoryHeroAnchor, anchor);
            });
        }
        if (!scheduledEpisode) addOpenWithMenuRow(menu, popup, "Séries",
                playerPackage -> openExternalPlayback(episode, false, false, playerPackage));
        finalizePopupMenu(menu);
        watched.setOnClickListener(v -> {
            popup.dismiss();
            markSeriesEpisodeWatched(episode, anchor);
        });
        unwatched.setOnClickListener(v -> {
            popup.dismiss();
            setSeriesEpisodeWatched(episode, anchor, false);
        });
        restart.setOnClickListener(v -> {
            popup.dismiss();
            resetSeriesEpisodeAndPlay(episode, anchor);
        });
        artwork.setOnClickListener(v -> {
            popup.dismiss();
            String id = episode == null ? "" : episode.optString("id", "").trim();
            String episodeTitle = episode == null ? "" : episode.optString("episodeTitle", "").trim();
            if (episodeTitle.isEmpty() && episode != null) {
                episodeTitle = episode.optString("title", "").trim();
            }
            if (episodeTitle.isEmpty()) episodeTitle = seriesTitle;
            JojoProgram episodeProgram = new JojoProgram("external-playback-series-episode",
                    "S" + episode.optInt("season") + "E" + episode.optInt("episode"),
                    externalPlaybackSynopsis(episode), selectedSeriesEpisodeArtwork(episode, ""),
                    id, episode.optLong("duration"), episode.optLong("position"), null, null,
                    episode.optBoolean("watched", false));
            JojoProgram artworkProgram = new JojoProgram(episodeProgram.sourcePackage, episodeTitle,
                    episodeProgram.description, episodeProgram.artwork, episodeProgram.intentUri,
                    episodeProgram.duration, episodeProgram.position, null, null,
                    episodeProgram.watched);
            showResumeArtworkPicker(artworkProgram, anchor, false, portraitArtwork, refreshEpisodeRow, episode);
        });
        showPopupBelow(popup, anchor, 0, dp(4));
        if (scheduledEpisode) artwork.requestFocus(); else watched.requestFocus();
    }

    private void markSeriesEpisodeWatched(JSONObject episode, View tile) {
        setSeriesEpisodeWatched(episode, tile, true);
    }

    private void setSeriesEpisodeWatched(JSONObject episode, View tile, boolean watched) {
        if (episode == null) return;
        try { episode.put("watched", watched); }
        catch (Exception ignored) { }
        if (watched) showEpisodeWatchedBadge(tile); else clearEpisodeStatusBadge(tile);
        String id = episode.optString("id", "");
        if ("jojo-iptv".equals(episode.optString("favoriteSource"))) {
            resumeMutationExecutor.execute(() -> {
                try { com.jojotv.home.iptv.IptvStore.setHomeEpisodeWatched(getApplicationContext(), id, watched); }
                catch (Exception ignored) {
                    runOnUiThread(() -> {
                        try { episode.put("watched", !watched); } catch (Exception ignoredJson) { }
                        if (watched) clearEpisodeStatusBadge(tile); else showEpisodeWatchedBadge(tile);
                        Toast.makeText(this, "Impossible de modifier l’état de l’épisode", Toast.LENGTH_SHORT).show();
                    });
                }
            });
            return;
        }
        JSONObject stored = ExternalPlaybackStore.get(this, id);
        if (ExternalPlaybackStore.supportedUrl(stored.optString("url"))) {
            try {
                stored.put("watched", watched);
                if (!watched) stored.put("position", 0L).put("started", false);
                ExternalPlaybackStore.save(this, stored);
            } catch (Exception ignored) { }
            return;
        }
        TiviMateFavoriteImporter.refreshPlaybackLink(this, episode, resolved -> {
            String resolvedId = resolved.optString("id", "");
            if (!resolvedId.equals(id) || !ExternalPlaybackStore.supportedUrl(resolved.optString("url"))) {
                try { episode.put("watched", !watched); }
                catch (Exception ignored) { }
                if (watched) clearEpisodeStatusBadge(tile); else showEpisodeWatchedBadge(tile);
                Toast.makeText(this, watched ? "Impossible d’enregistrer l’épisode comme vu"
                        : "Impossible d’enregistrer l’épisode comme non vu", Toast.LENGTH_SHORT).show();
                return;
            }
            try {
                resolved.put("watched", watched);
                if (!watched) resolved.put("position", 0L).put("started", false);
                ExternalPlaybackStore.save(this, resolved);
            } catch (Exception ignored) { }
        });
    }

    private void resetSeriesEpisodeAndPlay(JSONObject episode, View tile) {
        if (episode == null) return;
        if ("jojo-iptv".equals(episode.optString("favoriteSource"))) {
            clearEpisodeStatusBadge(tile);
            openExternalPlayback(episode, false, true);
            return;
        }
        String id = episode.optString("id", "");
        JSONObject stored = ExternalPlaybackStore.get(this, id);
        if (ExternalPlaybackStore.supportedUrl(stored.optString("url"))) {
            resetSeriesEpisodeProgress(episode, tile, stored);
            openExternalPlayback(episode, false, true);
            return;
        }
        TiviMateFavoriteImporter.refreshPlaybackLink(this, episode, resolved -> {
            if (!id.equals(resolved.optString("id"))
                    || !ExternalPlaybackStore.supportedUrl(resolved.optString("url"))) {
                Toast.makeText(this, "Impossible de reprendre l’épisode", Toast.LENGTH_SHORT).show();
                return;
            }
            resetSeriesEpisodeProgress(episode, tile, resolved);
            openExternalPlayback(episode, false, true);
        });
    }

    private void resetSeriesEpisodeProgress(JSONObject episode, View tile, JSONObject stored) {
        try {
            episode.put("position", 0L).put("watched", false);
            stored.put("position", 0L).put("duration", Math.max(0L, episode.optLong("duration")))
                    .put("started", false).put("watched", false);
            ExternalPlaybackStore.save(this, stored);
        } catch (Exception ignored) { }
        clearEpisodeStatusBadge(tile);
    }

    private String selectedSeriesEpisodeArtwork(JSONObject episode, String fallback) {
        String groupIdentity = externalPlaybackEpisodeGroupThumbnailIdentity(episode);
        if (!groupIdentity.isEmpty()) {
            String selected = selectedExternalArtwork(externalThumbnailArtworkKey(groupIdentity));
            if (ExternalPlaybackStore.supportedUrl(selected)) return selected;
        }
        String episodeIdentity = externalPlaybackEpisodeThumbnailIdentity(episode);
        if (!episodeIdentity.isEmpty()) {
            String selected = selectedExternalArtwork(externalThumbnailArtworkKey(episodeIdentity));
            if (ExternalPlaybackStore.supportedUrl(selected)) return selected;
        }
        String id = episode == null ? "" : episode.optString("id", "").trim();
        if (!id.isEmpty()) {
            String selected = selectedExternalArtwork(externalThumbnailArtworkKey("external-playback|" + id));
            if (ExternalPlaybackStore.supportedUrl(selected)) return selected;
        }
        // Older Stalker versions shared one choice across the episode folder.
        // Native IPTV used the series tile's key, which must stay independent.
        String seriesIdentity = externalPlaybackSeriesThumbnailIdentity(episode);
        if (episode != null && !"jojo-iptv".equals(episode.optString("favoriteSource"))
                && !seriesIdentity.isEmpty()) {
            String selected = selectedExternalArtwork(externalThumbnailArtworkKey(seriesIdentity));
            if (ExternalPlaybackStore.supportedUrl(selected)) return selected;
        }
        return fallback == null ? "" : fallback;
    }

    private String externalPlaybackEpisodeGroupThumbnailIdentity(JSONObject episode) {
        String seriesIdentity = externalPlaybackSeriesThumbnailIdentity(episode);
        return seriesIdentity.isEmpty() ? "" : seriesIdentity + "|episodes";
    }

    private String externalPlaybackEpisodeThumbnailIdentity(JSONObject episode) {
        if (episode == null) return "";
        String seriesIdentity = externalPlaybackSeriesThumbnailIdentity(episode);
        int season = episode.optInt("season"), number = episode.optInt("episode");
        if (!seriesIdentity.isEmpty() && season > 0 && number > 0) {
            return seriesIdentity + "|season:" + season + "|episode:" + number;
        }
        String id = episode.optString("id", "").trim();
        return id.isEmpty() ? "" : "external-playback|" + id;
    }

    private String externalPlaybackSeriesThumbnailIdentity(JSONObject episode) {
        if (episode == null) return "";
        if ("jojo-iptv".equals(episode.optString("favoriteSource"))) {
            String seriesId = episode.optString("iptvSeriesId", "");
            return seriesId.isEmpty() ? "" : "external-playback|" + seriesId;
        }
        String source = episode.optString("stalkerSource", "").trim();
        String account = episode.optString("stalkerProviderAccount", "").trim();
        String seriesId = episode.optString("stalkerSeriesId", "").trim();
        if (source.isEmpty() || seriesId.isEmpty()) return "";
        return "external-playback-series|" + source + "|" + account + "|" + seriesId;
    }

    private String selectedExternalFavoriteArtwork(JSONObject item) {
        if (item == null) return "";
        String id = item.optString("id", "").trim();
        if (!id.isEmpty()) {
            String key = "external-playback|" + id;
            String selected = selectedExternalArtwork(externalThumbnailArtworkKey(key));
            if (ExternalPlaybackStore.supportedUrl(selected)) return selected;
        }
        return externalPlaybackArtwork(item);
    }

    private String selectedExternalFavoriteHeroArtwork(JSONObject item) {
        if (item == null) return "";
        String id = item.optString("id", "").trim();
        if (id.isEmpty()) return "";
        String selected = selectedExternalArtwork(externalHeroArtworkKey("external-playback|" + id));
        return ExternalPlaybackStore.supportedUrl(selected) ? selected : "";
    }

    public static String externalThumbnailArtworkKey(String resumeKey) {
        return "external_thumbnail_artwork_"
                + Integer.toUnsignedString((resumeKey == null ? "" : resumeKey).hashCode(), 16);
    }

    public static String externalHeroArtworkKey(String resumeKey) {
        return "external_hero_artwork_"
                + Integer.toUnsignedString((resumeKey == null ? "" : resumeKey).hashCode(), 16);
    }

    private boolean isExternalArtworkSelectionKey(String key) {
        return key != null && (key.startsWith("external_thumbnail_artwork_")
                || key.startsWith("external_hero_artwork_"));
    }

    private android.content.SharedPreferences externalArtworkSelections() {
        return getSharedPreferences("external_artwork_selections", MODE_PRIVATE);
    }

    private String selectedExternalArtwork(String key) {
        return selectedExternalArtwork(this, key);
    }

    public static String selectedExternalArtwork(Context context, String key) {
        try {
            JSONObject choice = new JSONObject(context.getSharedPreferences("external_artwork_selections", MODE_PRIVATE).getString(key, "{}"));
            if (choice.optBoolean("manualArtwork")) {
                return choice.optBoolean("deleted") ? "" : choice.optString("value", "").trim();
            }
        } catch (org.json.JSONException error) {
            android.util.Log.e("JojoHomeSync", "Cannot read manual artwork selection", error);
        }
        return context.getSharedPreferences("home_settings", MODE_PRIVATE).getString(key, "").trim();
    }

    private void mergeManualExternalArtworkSelections(JSONObject incoming) throws org.json.JSONException {
        android.content.SharedPreferences.Editor editor = externalArtworkSelections().edit();
        Set<String> keys = new HashSet<>(externalArtworkSelections().getAll().keySet());
        java.util.Iterator<String> incomingKeys = incoming.keys();
        while (incomingKeys.hasNext()) {
            String key = incomingKeys.next();
            if (isExternalArtworkSelectionKey(key)) keys.add(key);
        }
        for (String key : keys) {
            JSONObject local = new JSONObject(externalArtworkSelections().getString(key, "{}"));
            JSONObject remote = incoming.optJSONObject(key);
            boolean localManual = local.optBoolean("manualArtwork");
            boolean remoteManual = remote != null && remote.optBoolean("manualArtwork");
            // Generic settings snapshots are not manual artwork edits. Only a
            // newer explicit selection from another device may replace this one.
            if (localManual && (!remoteManual || ExternalPlaybackStore.compareRevisions(
                    local.optLong("changedAt"), local.optString("writer"),
                    remote.optLong("changedAt"), remote.optString("writer")) >= 0)) {
                incoming.put(key, local);
            } else if (remoteManual) {
                if (remote.optBoolean("deleted") || ExternalPlaybackStore.supportedUrl(remote.optString("value"))) {
                    editor.putString(key, remote.toString());
                } else if (localManual) incoming.put(key, local);
            }
        }
        editor.apply();
    }

    private String externalHeroArtworkIdentity(JojoProgram program, JSONObject item) {
        JSONObject favorite = externalPlaybackHeroFavorite(item);
        String id = favorite.optString("id", "").trim();
        if (id.isEmpty() && item != null) id = item.optString("id", "").trim();
        return id.isEmpty() ? resumeDismissKey(program) : "external-playback|" + id;
    }

    private void loadIptvSeriesTitleLogo(JSONObject favorite, String title, ImageView image) {
        String sourceTitle = firstExternalValue(favorite, "originalTitle", "original_title", "original_name", "title");
        String seriesTitle = cleanIptvTitle(sourceTitle);
        if (seriesTitle == null || seriesTitle.trim().isEmpty()) seriesTitle = cleanIptvTitle(title);
        if (seriesTitle != null) {
            seriesTitle = seriesTitle.replaceFirst("(?i)\\s+s\\s*\\d{1,2}\\s*$", "").trim();
        }
        loadIptvTitleLogo(favorite, seriesTitle, "series", null, image);
    }

    private void loadHomeCategoryHeroTitleLogo(String category, String title,
                                                JSONObject item, JojoProgram program, ImageView image) {
        // Videos can be backed by a folder or a local programme, so use the
        // same fallback lookup as Films and Séries, keeping an existing
        // provider logo first. Live channels only use their explicit
        // provider logo; a channel name must not be guessed as a TV series.
        if ("movies".equals(category) || "series".equals(category) || "videos".equals(category)) {
            loadIptvTitleLogo(item, title, category, program, image);
        } else {
            String explicit = explicitTitleLogoUrl(item);
            if (ExternalPlaybackStore.supportedUrl(explicit)) loadArtwork(image, explicit);
            else notifyArtworkLoadFailure(image);
        }
    }

    private String explicitTitleLogoUrl(JSONObject item) {
        if (item == null) return "";
        for (String field : new String[]{"titleLogo", "title_logo", "logoUrl", "logo_url", "logo"}) {
            String value = item.optString(field, "").trim();
            if (ExternalPlaybackStore.supportedUrl(value)) return value;
        }
        return "";
    }

    private String iptvTitleLogoCacheKey(String category, String title, String expectedYear) {
        return "original-title-v" + HomeMediaRules.TITLE_LOGO_POLICY_VERSION + "|" + category + "|"
                + normalizeTmdbArtworkText(title == null ? "" : title)
                + "|" + expectedYear;
    }

    private String cachedExternalIdentityTitleLogo(JSONObject item) {
        if (item == null) return "";
        String category = item.optString("category", "");
        if ("live".equals(category)) return "";
        String type = item.optString("tmdbMediaType", item.optString("mediaType", ""));
        if (!("movie".equals(type) || "tv".equals(type) || "series".equals(type))) {
            type = "movies".equals(category) ? "movie" : "series".equals(category) ? "tv" : "";
        }
        return cachedTmdbTitleLogoUrl(type, item.optInt("tmdbId", item.optInt("tmdb_id", 0)));
    }

    private String cachedIptvTitleLogoUrl(String cacheKey) {
        String cached = resolvedTitleLogoUrls.get(cacheKey);
        if (!ExternalPlaybackStore.supportedUrl(cached)) {
            cached = getSharedPreferences("home_hero_editorial_cache", MODE_PRIVATE)
                    .getString("logo|" + cacheKey, "");
        }
        if (isUsableTitleLogoUrl(cached)) {
            resolvedTitleLogoUrls.put(cacheKey, cached);
            return cached;
        }
        return "";
    }

    private String existingExternalPlaybackTitleLogo(JSONObject item) {
        if (item == null) return "";
        String category = item.optString("category", "").trim().toLowerCase(Locale.ROOT);
        String explicit = explicitTitleLogoUrl(item);
        if ("live".equals(category)) return explicit;
        if (!"movies".equals(category) && !"series".equals(category) && !"videos".equals(category)) return "";

        JSONObject source = item;
        boolean seriesEpisode = "series".equals(category)
                && (item.optInt("season", 0) > 0 || item.optInt("episode", 0) > 0
                || !item.optString("episodeTitle", "").trim().isEmpty());
        if (seriesEpisode) source = homeHeroEditorialSource(item, true);
        String sourceExplicit = explicitTitleLogoUrl(source);
        if (!sourceExplicit.isEmpty()) explicit = sourceExplicit;
        if (!explicit.isEmpty()) return explicit;
        String identityLogo = cachedExternalIdentityTitleLogo(source);
        if (identityLogo.isEmpty()) identityLogo = cachedExternalIdentityTitleLogo(item);
        if (!identityLogo.isEmpty()) return identityLogo;
        if ((source != null && source.optInt("tmdbId", source.optInt("tmdb_id", 0)) > 0)
                || item.optInt("tmdbId", item.optInt("tmdb_id", 0)) > 0) return explicit;

        String sourceTitle = source == null ? "" : source.optString("title", "").trim();
        String title = "series".equals(category) ? cleanIptvTitle(sourceTitle)
                : "videos".equals(category) ? videoArtworkSearchTitle(sourceTitle, null) : sourceTitle;
        String rawTitle = item.optString("title", sourceTitle);
        java.util.regex.Matcher yearMatcher = java.util.regex.Pattern.compile("(?:19|20)\\d{2}")
                .matcher(rawTitle == null ? "" : rawTitle);
        String expectedYear = yearMatcher.find() ? yearMatcher.group() : "";
        String logo = cachedIptvTitleLogoUrl(iptvTitleLogoCacheKey(category, title, expectedYear));
        if (ExternalPlaybackStore.supportedUrl(logo)) return logo;

        if ("series".equals(category) && !sourceTitle.isEmpty() && !sourceTitle.equals(title)) {
            logo = cachedIptvTitleLogoUrl(iptvTitleLogoCacheKey(category, sourceTitle, expectedYear));
            if (ExternalPlaybackStore.supportedUrl(logo)) return logo;
        }
        String originalTitle = item.optString("title", "").trim();
        if (!originalTitle.isEmpty() && !originalTitle.equals(sourceTitle)) {
            String originalSearchTitle = "series".equals(category) ? originalTitle
                    : "videos".equals(category) ? videoArtworkSearchTitle(originalTitle, null) : originalTitle;
            logo = cachedIptvTitleLogoUrl(iptvTitleLogoCacheKey(category, originalSearchTitle, expectedYear));
            if (ExternalPlaybackStore.supportedUrl(logo)) return logo;
            if ("series".equals(category)) {
                logo = cachedIptvTitleLogoUrl(iptvTitleLogoCacheKey(category,
                        cleanIptvTitle(originalTitle), expectedYear));
            }
        }
        return ExternalPlaybackStore.supportedUrl(logo) ? logo : explicit;
    }

    private void loadIptvTitleLogo(JSONObject favorite, String title, String category,
                                   JojoProgram program, ImageView image) {
        String rawTitle = program == null ? title : program.title;
        java.util.regex.Matcher yearMatcher = java.util.regex.Pattern.compile("(?:19|20)\\d{2}")
                .matcher(rawTitle == null ? "" : rawTitle);
        String expectedYear = yearMatcher.find() ? yearMatcher.group() : "";
        String logoCacheKey = iptvTitleLogoCacheKey(category, title, expectedYear);
        image.setTag(CATEGORY_VIDEO_METADATA_REQUEST_TAG, logoCacheKey);
        String explicit = explicitTitleLogoUrl(favorite);
        if (!explicit.isEmpty()) {
            loadArtwork(image, explicit);
            return;
        }
        String cachedLogo = cachedExternalIdentityTitleLogo(favorite);
        boolean knownIdentity = favorite != null && favorite.optInt("tmdbId", favorite.optInt("tmdb_id", 0)) > 0;
        if (cachedLogo.isEmpty() && !knownIdentity) cachedLogo = cachedIptvTitleLogoUrl(logoCacheKey);
        if (cachedLogo.isEmpty() && !knownIdentity) cachedLogo = OfficialProgrammeLogoResolver.cached(
                this, rawTitle, 0, "movies".equals(category) ? "movie" : "tv");
        if (ExternalPlaybackStore.supportedUrl(cachedLogo)) {
            resolvedTitleLogoUrls.put(logoCacheKey, cachedLogo);
            loadArtwork(image, cachedLogo);
            return;
        }
        Object lookup = beginTitleLogoLookup(image);
        if (BuildConfig.TMDB_API_KEY == null || BuildConfig.TMDB_API_KEY.trim().isEmpty()) {
            finishTitleLogoLookup(image, lookup);
            return;
        }
        new Thread(() -> {
            try {
                int knownId = favorite == null ? 0 : favorite.optInt("tmdbId", favorite.optInt("tmdb_id", 0));
                String knownType = "movies".equals(category) ? "movie" : "series".equals(category) ? "tv" : "";
                if (knownId > 0 && !knownType.isEmpty()) {
                    JSONObject details = fetchJson("https://api.themoviedb.org/3/" + knownType + "/" + knownId
                            + "?api_key=" + java.net.URLEncoder.encode(BuildConfig.TMDB_API_KEY, "UTF-8")
                            + "&language=fr-FR&append_to_response=images&include_image_language=fr,en,null");
                    String logo = selectTmdbTitleLogo(details, knownType, knownId);
                    if (!logo.isEmpty()) {
                        resolvedTitleLogoUrls.put(logoCacheKey, logo);
                        getSharedPreferences("home_hero_editorial_cache", MODE_PRIVATE).edit()
                                .putString("logo|" + logoCacheKey, logo).apply();
                        runOnUiThread(() -> {
                            if (logoCacheKey.equals(image.getTag(CATEGORY_VIDEO_METADATA_REQUEST_TAG))) loadArtwork(image, logo);
                        });
                    } else requestOfficialIptvTitleLogo(title, knownId, knownType, logoCacheKey, image);
                    return;
                }
                String query = videoArtworkSearchTitle(title, null);
                if (query == null || query.trim().isEmpty()) return;
                if ("videos".equals(category) && program != null) {
                    // The poster/backdrop lookup may already have established
                    // the precise TMDB identity of this Freebox video.
                    try {
                        JSONObject artworkMatch = new JSONObject(homePrefs().getString(
                                videoArtworkCacheKey(program.title), "{}"));
                        int artworkId = artworkMatch.optInt("tmdbId", 0);
                        String artworkType = artworkMatch.optString("tmdbMediaType", "");
                        String matchedTitle = artworkMatch.optString("matchedTitle", "");
                        if (artworkId > 0 && ("movie".equals(artworkType) || "tv".equals(artworkType))
                                && normalizeTmdbArtworkText(query).equals(normalizeTmdbArtworkText(matchedTitle))) {
                            JSONObject details = fetchJson("https://api.themoviedb.org/3/" + artworkType + "/" + artworkId
                                    + "?api_key=" + java.net.URLEncoder.encode(BuildConfig.TMDB_API_KEY, "UTF-8")
                                    + "&language=fr-FR&append_to_response=images&include_image_language=fr,en,null");
                            String date = details.optString("release_date", details.optString("first_air_date", ""));
                            int runtime = details.optInt("runtime", 0);
                            JSONArray runtimes = details.optJSONArray("episode_run_time");
                            if (runtime <= 0 && runtimes != null && runtimes.length() > 0)
                                runtime = runtimes.optInt(0, 0);
                            int durationMinutes = program.duration <= 0L ? 0 : Math.round(program.duration / 60_000f);
                            boolean validYear = expectedYear.isEmpty() || date.length() < 4
                                    || expectedYear.equals(date.substring(0, 4));
                            boolean validDuration = durationMinutes <= 0
                                    || (runtime > 0 && Math.abs(runtime - durationMinutes) <= 8);
                            if (validYear && validDuration) {
                                String knownLogo = selectTmdbTitleLogo(details, artworkType, artworkId);
                                if (!knownLogo.isEmpty()) {
                                    resolvedTitleLogoUrls.put(logoCacheKey, knownLogo);
                                    getSharedPreferences("home_hero_editorial_cache", MODE_PRIVATE).edit()
                                            .putString("logo|" + logoCacheKey, knownLogo).apply();
                                    runOnUiThread(() -> {
                                        if (logoCacheKey.equals(image.getTag(CATEGORY_VIDEO_METADATA_REQUEST_TAG))) loadArtwork(image, knownLogo);
                                    });
                                } else requestOfficialIptvTitleLogo(title, artworkId, artworkType, logoCacheKey, image);
                                return;
                            }
                        }
                    } catch (Exception ignored) { /* Fall back to an exact title search. */ }
                }
                // Freebox/Vidéos contains both films and series. Searching
                // only /tv made valid movie logos invisible in this Hero.
                String searchType = "videos".equals(category) ? "multi"
                        : "movies".equals(category) ? "movie" : "tv";
                String endpoint = "https://api.themoviedb.org/3/search/" + searchType + "?api_key="
                        + java.net.URLEncoder.encode(BuildConfig.TMDB_API_KEY, "UTF-8")
                        + "&language=fr-FR&query=" + java.net.URLEncoder.encode(query, "UTF-8");
                JSONArray results = fetchJson(endpoint).optJSONArray("results");
                if (results == null) return;
                JSONObject match = null;
                JSONObject matchedDetails = null;
                String mediaType = "movies".equals(category) ? "movie" : "tv";
                String normalizedQuery = normalizeTmdbArtworkText(query);
                ArrayList<JSONObject> videoMatches = new ArrayList<>();
                for (int i = 0; i < results.length(); i++) {
                    JSONObject candidate = results.optJSONObject(i);
                    if (candidate == null) continue;
                    String candidateType = "videos".equals(category)
                            ? candidate.optString("media_type", "") : mediaType;
                    if (!("movie".equals(candidateType) || "tv".equals(candidateType))) continue;
                    String candidateTitle = "movie".equals(candidateType)
                            ? candidate.optString("title", candidate.optString("original_title", ""))
                            : candidate.optString("name", candidate.optString("original_name", ""));
                    String originalTitle = "movie".equals(candidateType)
                            ? candidate.optString("original_title", "") : candidate.optString("original_name", "");
                    boolean exact = normalizedQuery.equals(normalizeTmdbArtworkText(candidateTitle))
                            || normalizedQuery.equals(normalizeTmdbArtworkText(originalTitle));
                    if ("videos".equals(category) && !exact) continue;
                    if (!"videos".equals(category) && !exact
                            && !tmdbArtworkTitleMatches(title, query, candidateTitle)) continue;
                    String date = candidate.optString("release_date", candidate.optString("first_air_date", ""));
                    if ("videos".equals(category) && !expectedYear.isEmpty()
                            && date.length() >= 4 && !expectedYear.equals(date.substring(0, 4))) continue;
                    if ("videos".equals(category)) {
                        videoMatches.add(candidate);
                        continue;
                    }
                    match = candidate;
                    mediaType = candidateType;
                    break;
                }
                if ("videos".equals(category)) {
                    int durationMinutes = program == null || program.duration <= 0L ? 0
                            : Math.round(program.duration / 60_000f);
                    if (videoMatches.size() > 1 && durationMinutes <= 0) return;
                    for (JSONObject candidate : videoMatches) {
                        String type = candidate.optString("media_type", "");
                        int candidateId = candidate.optInt("id", 0);
                        if (candidateId <= 0) continue;
                        JSONObject details = fetchJson("https://api.themoviedb.org/3/" + type + "/" + candidateId
                                + "?api_key=" + java.net.URLEncoder.encode(BuildConfig.TMDB_API_KEY, "UTF-8")
                                + "&language=fr-FR&append_to_response=images&include_image_language=fr,en,null");
                        int runtime = details.optInt("runtime", 0);
                        JSONArray runtimes = details.optJSONArray("episode_run_time");
                        if (runtime <= 0 && runtimes != null && runtimes.length() > 0)
                            runtime = runtimes.optInt(0, 0);
                        if (durationMinutes > 0 && (runtime <= 0 || Math.abs(runtime - durationMinutes) > 8))
                            continue;
                        if (match != null) return; // still ambiguous
                        match = candidate;
                        matchedDetails = details;
                    }
                    if (match != null) mediaType = match.optString("media_type", "");
                }
                if (match == null) {
                    requestOfficialIptvTitleLogo(query, 0, "movies".equals(category) ? "movie" : "tv", logoCacheKey, image);
                    return;
                }
                int id = match.optInt("id", 0);
                if (id <= 0) return;
                String originalLanguage = match.optString("original_language", "");
                JSONObject images = matchedDetails == null
                        ? fetchJson("https://api.themoviedb.org/3/" + mediaType + "/" + id
                                + "/images?api_key=" + java.net.URLEncoder.encode(BuildConfig.TMDB_API_KEY, "UTF-8")
                                + "&include_image_language=" + java.net.URLEncoder.encode(
                                tmdbTitleLogoLanguages(originalLanguage), "UTF-8"))
                        : matchedDetails.optJSONObject("images");
                if (images == null) return;
                String logo = matchedDetails == null
                        ? selectFolderTitleLogo(images.optJSONArray("logos"), originalLanguage)
                        : selectTmdbTitleLogo(matchedDetails, mediaType, id);
                if (logo.isEmpty()) {
                    requestOfficialIptvTitleLogo(query, id, mediaType, logoCacheKey, image);
                    return;
                }
                OnlineAppIconLoader.rememberTitleLogo(this, mediaType, id, logo);
                resolvedTitleLogoUrls.put(logoCacheKey, logo);
                getSharedPreferences("home_hero_editorial_cache", MODE_PRIVATE).edit()
                        .putString("logo|" + logoCacheKey, logo).apply();
                runOnUiThread(() -> {
                    // Home Heroes are rendered with activeScreen == null. Do
                    // not discard a valid title logo while the new Hero view
                    // is still being attached during a carousel rebind.
                    if (logoCacheKey.equals(image.getTag(CATEGORY_VIDEO_METADATA_REQUEST_TAG))) loadArtwork(image, logo);
                });
            } catch (Exception ignored) { }
            finally { runOnUiThread(() -> finishTitleLogoLookup(image, lookup)); }
        }, "JojoHomeIptvTitleLogo").start();
    }

    private void requestOfficialIptvTitleLogo(String title, int id, String type, String key, ImageView image) {
        runOnUiThread(() -> {
            if (isDestroyed() || !key.equals(image.getTag(CATEGORY_VIDEO_METADATA_REQUEST_TAG))) return;
            Object lookup = beginTitleLogoLookup(image);
            OfficialProgrammeLogoResolver.resolve(this, title, id, type, logo -> {
                if (!logo.isEmpty()) {
                    resolvedTitleLogoUrls.put(key, logo);
                    getSharedPreferences("home_hero_editorial_cache", MODE_PRIVATE).edit().putString("logo|" + key, logo).apply();
                    if (!isDestroyed() && key.equals(image.getTag(CATEGORY_VIDEO_METADATA_REQUEST_TAG))) loadArtwork(image, logo);
                }
                finishTitleLogoLookup(image, lookup);
            });
        });
    }

    private List<JojoProgram> externalPlaybackContinuePrograms() {
        return externalPlaybackContinueSnapshot;
    }

    /** Reads and normalizes the external store; called from the Home query worker. */
    private List<JojoProgram> loadExternalPlaybackContinuePrograms() {
        LinkedHashMap<String, JSONObject> logicalItems = new LinkedHashMap<>();
        for (String category : new String[]{"movies", "series", "live", "unknown"}) {
            for (JSONObject item : ExternalPlaybackStore.listAll(this, category, false)) {
                String logicalKey = ExternalPlaybackStore.continueWatchingKey(item);
                JSONObject previous = logicalItems.get(logicalKey);
                if (previous == null || ExternalPlaybackStore.preferForContinueWatching(item, previous)) {
                    logicalItems.put(logicalKey, item);
                }
            }
        }
        ArrayList<JSONObject> ordered = new ArrayList<>(logicalItems.values());
        ordered.sort((left, right) -> Long.compare(left.optLong("updatedAt"), right.optLong("updatedAt")));
        ArrayList<JojoProgram> result = new ArrayList<>();
        for (JSONObject item : ordered) {
            int season = item.optInt("season", 0), episode = item.optInt("episode", 0);
            String providerSynopsis = externalPlaybackSynopsis(item);
            result.add(new JojoProgram("external-playback", item.optString("title"),
                    providerSynopsis, externalPlaybackArtwork(item),
                    item.optString("id"), item.optLong("duration"), item.optLong("position"),
                    season > 0 ? String.valueOf(season) : null,
                    episode > 0 ? String.valueOf(episode) : null));
        }
        return keepContinueWatchingInsertionOrder(result);
    }

    private void refreshSyncedIptvHome() {
        if (!homeActivityResumed || isDestroyed() || isFinishing() || homeDpadNavigationActive) return;
        final long accountRevision = IptvStore.homeAccountsRevision();
        boolean accountChanged = accountRevision != displayedIptvAccountRevision;
        if (accountChanged) {
            boolean loaded = displayedIptvAccountRevision >= 0L;
            displayedIptvAccountRevision = accountRevision;
            if (loaded) refreshHomeHeaderAccount();
        }
        final long revision = IptvStore.homeFavoritesRevision();
        final long artworkRevision = IptvStore.homeArtworkRevision();
        if ((revision == displayedIptvFavoriteRevision && accountRevision == displayedIptvFavoriteAccountRevision
                && artworkRevision == displayedIptvArtworkRevision)
                || iptvHomeRefreshInFlight || homeAccountExecutor.isShutdown()) return;
        iptvHomeRefreshInFlight = true;
        final int generation = homeAccountChangeGeneration;
        // Parse metadata and read cloud progress away from the D-pad/UI thread.
        homeAccountExecutor.execute(() -> {
            Map<String, List<JSONObject>> snapshots = new LinkedHashMap<>();
            try {
                for (String category : new String[]{"movies", "series", "live"}) {
                    List<JSONObject> items = IptvStore.applyHomeFavoriteProgress(
                            this, ExternalPlaybackStore.list(this, category));
                    for (JSONObject item : items) {
                        item.put("selectedThumbnailArtwork", selectedExternalFavoriteArtwork(item));
                        item.put("selectedHeroArtwork", selectedExternalFavoriteHeroArtwork(item));
                    }
                    snapshots.put(category, items);
                }
            } catch (Exception ignored) {
                runOnUiThread(() -> iptvHomeRefreshInFlight = false);
                return;
            }
            runOnUiThread(() -> {
                iptvHomeRefreshInFlight = false;
                if (!homeActivityResumed || isDestroyed() || isFinishing() || homeDpadNavigationActive
                        || generation != homeAccountChangeGeneration || revision != IptvStore.homeFavoritesRevision()
                        || accountRevision != IptvStore.homeAccountsRevision()
                        || artworkRevision != IptvStore.homeArtworkRevision()) {
                    if (homeActivityResumed && !homeDpadNavigationActive) iptvHomeChangeObserver.run();
                    return;
                }
                Set<String> changed = new HashSet<>();
                for (Map.Entry<String, List<JSONObject>> entry : snapshots.entrySet()) {
                    List<JSONObject> previous = homeCategoryFavoriteSnapshots.get(entry.getKey());
                    if (previous == null || !previous.toString().equals(entry.getValue().toString())) {
                        homeCategoryFavoriteSnapshots.put(entry.getKey(), entry.getValue());
                        changed.add(entry.getKey());
                    }
                }
                displayedIptvFavoriteRevision = revision;
                displayedIptvFavoriteAccountRevision = accountRevision;
                boolean artworkChanged = displayedIptvArtworkRevision >= 0L && displayedIptvArtworkRevision != artworkRevision;
                displayedIptvArtworkRevision = artworkRevision;
                if (artworkChanged) {
                    homeArtworkRefreshPending = true;
                    refreshHomeResumeSectionInPlace();
                }
                if (changed.isEmpty()) return;
                renderExternalPlaybackRows(changed);
                if (currentHomePage != null && currentHomePage.isAttachedToWindow()) refreshEmptyHomeSuggestions();
                if (changed.contains(homeCategoryPageCategory)) refreshActiveHomeCategoryPage();
            });
        });
    }

    private void renderExternalPlaybackRows() {
        renderExternalPlaybackRows(null);
    }

    private void renderExternalPlaybackRows(Set<String> changedCategories) {
        if (homeDpadNavigationActive) {
            homeRefreshPendingAfterDpad = true;
            return;
        }
        for (Map.Entry<String, LinearLayout> entry : currentExternalRows.entrySet()) {
            String category = entry.getKey();
            if (changedCategories != null && !changedCategories.contains(category)) continue;
            LinearLayout rows = entry.getValue();
            if (changedCategories != null && !rows.isAttachedToWindow()) continue;
            List<JSONObject> items = changedCategories == null ? ExternalPlaybackStore.list(this, category)
                    : new ArrayList<>(homeCategoryFavoriteSnapshots.getOrDefault(category, Collections.emptyList()));
            items.removeIf(item -> isExternalRemovalPending(item.optString("id")));
            homeCategoryFavoriteSnapshots.put(category, new ArrayList<>(items));
            if (changedCategories == null) refreshEmptyHomeSuggestions();
            String snapshot = items.toString();
            if (snapshot.equals(rows.getTag())) continue;
            rows.setTag(snapshot);
            View previousFocus = rows.findFocus();
            Object previousTag = previousFocus == null ? null : previousFocus.getTag();
            int previousIndex = previousFocus != null && previousFocus.getParent() instanceof ViewGroup
                    ? ((ViewGroup) previousFocus.getParent()).indexOfChild(previousFocus) : 0;
            rows.removeAllViews();
            int count = Math.min(continueWatchingCardLimit(), items.size());
            int rowCount = Math.min(homeSectionRows(category), Math.max(1, count));
            int perRow = Math.max(1, (int) Math.ceil(count / (double) rowCount));
            LinearLayout firstRow = null;
            for (int rowIndex = 0; rowIndex < rowCount; rowIndex++) {
                HorizontalScrollView scroll = new HorizontalScrollView(this);
                scroll.setHorizontalScrollBarEnabled(false);
                scroll.setClipChildren(false);
                scroll.setClipToPadding(false);
                scroll.setPadding(0, dp(6), 0, dp(6));
                LinearLayout row = new LinearLayout(this);
                row.setClipChildren(false);
                // IPTV favorite rails (Films, Séries, TV) use the normal
                // horizontal-row behavior. Only the actual Continue Watching
                // rail receives the carousel tag in wireResumeRowsDpad().
                row.setTag("external_playback_row");
                if (firstRow == null) firstRow = row;
                int start = rowIndex * perRow;
                int end = Math.min(count, start + perRow);
                for (int index = start; index < end; index++) {
                    JSONObject item = items.get(index);
                    String artworkUrl = "live".equals(category)
                            ? liveChannelArtwork(item, false)
                            : selectedExternalFavoriteArtwork(item);
                    String itemTitle = "live".equals(category)
                            ? item.optString("title")
                            : displayIptvTitle(item.optString("title"),
                            item.optString("season", null), item.optString("episode", null));
                    JojoProgram program = new JojoProgram("external-playback", itemTitle, "", artworkUrl, item.optString("id"),
                            item.optLong("duration"), item.optLong("position"),
                            "series".equals(category) ? item.optString("season", null) : null,
                            "series".equals(category) ? item.optString("episode", null) : null,
                            item.optBoolean("watched", false));
                    View tile = jojoProgramTile(program);
                    tile.setOnClickListener(v -> {
                        rememberHomeFocus();
                        openExternalPlayback(ExternalPlaybackStore.get(this, item.optString("id")), true, false);
                    });
                    tile.setOnLongClickListener(v -> { showContinueWatchingMenu(program, tile, true); return true; });
                    row.addView(tile, new LinearLayout.LayoutParams(dp(continueWatchingTileWidthDp()), dp(continueWatchingCardHeightDp())) {{ rightMargin = dp(18); }});
                }
                scroll.addView(row);
                rows.addView(scroll, new LinearLayout.LayoutParams(-1, dp(continueWatchingRowHeightDp())));
                wireHorizontalCardRowDpad(row);
            }
            ViewGroup.LayoutParams rowParams = rows.getLayoutParams();
            if (rowParams != null) {
                rowParams.height = dp(continueWatchingRowHeightDp() * rowCount);
                rows.setLayoutParams(rowParams);
            }
            setHomeSectionVisible(category, !items.isEmpty());
            if (previousFocus != null && firstRow != null && firstRow.getChildCount() > 0) {
                View target = previousTag == null ? null : rows.findViewWithTag(previousTag);
                if (target == null) target = firstRow.getChildAt(Math.min(previousIndex, firstRow.getChildCount() - 1));
                target.requestFocus();
            }
        }
        wireHomeSectionVerticalDpad();
    }

    private void moveHomeSection(String key, int direction) {
        List<String> order = homeSectionOrder(currentHomeFilesView != null, ContentPresentationRules.showsContinueWatching(continueWatchingEnabled()));
        int index = order.indexOf(key), target = index + direction;
        if (index < 0 || target < 0 || target >= order.size()) return;
        Collections.swap(order, index, target);
        homePrefs().edit().putString(HOME_SECTION_ORDER, joinOrder(order)).apply();
        // Reorder the already-rendered section containers. Rebuilding Home on
        // every remote press reloaded weather, artwork and resume data, which
        // made row movement visibly laggy.
        if (currentHomePage == null || !currentHomePage.isAttachedToWindow()) {
            goHome();
            return;
        }
        for (String section : order) {
            View sectionView = currentHomeSectionViews.get(section);
            View spacer = currentHomeSectionSpacers.get(section);
            if (sectionView != null) currentHomePage.removeView(sectionView);
            if (spacer != null) currentHomePage.removeView(spacer);
        }
        for (String section : order) {
            View sectionView = currentHomeSectionViews.get(section);
            View spacer = currentHomeSectionSpacers.get(section);
            if (sectionView != null) currentHomePage.addView(sectionView, sectionView.getLayoutParams());
            if (spacer != null) currentHomePage.addView(spacer, spacer.getLayoutParams());
        }
        currentHomePage.post(() -> {
            // Rebuild the vertical focus graph after reparenting the sections.
            // Otherwise a row moved to the end keeps its former Down target.
            if (currentHomeHeaderView != null && currentHomeAppsView != null) {
                wireHomeHeaderDpad(currentHomeHeaderView, currentHomeAppsView,
                        currentHomeFilesView, currentHomeResumesView);
            }
            wireHomeSectionVerticalDpad();
            repositionActiveHomeRowMoveDrawer();
        });
    }

    private View createHome() {
        homeRenderGeneration++;
        activeHomeGridCategory = null;
        useHomeTextPalette();
        FrameLayout shell = new FrameLayout(this); shell.setBackgroundColor(homeBackgroundColor()); applyPersonalWallpaper(shell); installDynamicBackgroundLayer(shell);
        currentHomeShell = shell;
        homeDynamicBackgroundLayer = dynamicBackgroundLayer;
        homeFocusedArtworkBackground = focusedResumeArtworkBackground;
        shell.getViewTreeObserver().addOnGlobalFocusChangeListener((oldFocus, newFocus) -> {
            android.util.Log.i("JojoHomeFreeboxTrace", "HOME_FOCUS_CHANGE at=" + android.os.SystemClock.elapsedRealtime()
                    + " screen=" + (activeScreen == null ? "home" : activeScreen.getClass().getSimpleName())
                    + " navigation=" + homeFocusGeneration
                    + " old=" + focusDebugName(oldFocus) + " new=" + focusDebugName(newFocus));
            // Search choices are hosted in a separate PopupWindow. If a Home
            // card receives focus, close that window immediately; otherwise
            // Android can render the expanded Search state and the card focus
            // at the same time.
            if (newFocus != null && !isSearchHeader(newFocus)
                    && activeSearchPopup != null && activeSearchPopup.isShowing()) {
                closeSearchOverlayForHomeFocus();
            }
        });
        boolean gridHome = homeGridMode();
        if (gridHome && continueWatchingModernHero()) {
            FrameLayout artworkHost = new FrameLayout(this);
            artworkHost.setTag(HOME_HERO_BACKGROUND_TAG);
            artworkHost.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO_HIDE_DESCENDANTS);
            shell.addView(artworkHost, new FrameLayout.LayoutParams(-1, -1));
        }
        if (gridHome) {
            preloadHomeCategoryFavoriteSnapshots();
            preloadHomeCategoryVideos();
        }
        LinearLayout page = new LinearLayout(this);
        page.setOrientation(LinearLayout.VERTICAL);
        int inset = safeEdgeInset();
        page.setPadding(inset, inset, inset, gridHome ? 0 : inset);
        page.setClipChildren(false);
        page.setClipToPadding(false);
        page.setBackgroundColor(Color.TRANSPARENT);

        View homeHeader;
        android.os.Trace.beginSection("JojoHome/header");
        try {
            homeHeader = topBar(HOME_HEADER_HEIGHT_DP);
        } finally {
            android.os.Trace.endSection();
        }
        homeHeader.setTranslationY(dp(HOME_HEADER_BASE_TRANSLATION_DP
                + HOME_HEADER_HOME_SCREEN_LOWER_DP));
        currentHomeHeaderView = homeHeader;
        currentHomeAppsView = null;
        currentHomeFilesView = null;
        currentHomeResumesView = null;
        currentHomeCategoryGrid = null;
        currentExternalRows.clear();
        currentHomeSectionTitles.clear();
        currentHomeSectionViews.clear();
        currentHomeSectionSpacers.clear();
        currentHomePage = page;
        LinearLayout.LayoutParams homeHeaderParams =
                new LinearLayout.LayoutParams(-1, dp(HOME_HEADER_HEIGHT_DP));
        if (gridHome) {
            // The header is translated upward into the safe-area inset. Pull
            // the following content up by the same amount so the Hero starts
            // exactly at the visible bottom edge of the shared header.
            homeHeaderParams.bottomMargin = dp(HOME_HEADER_BASE_TRANSLATION_DP
                    + HOME_HEADER_HOME_SCREEN_LOWER_DP);
        }
        page.addView(homeHeader, homeHeaderParams);
        page.addView(space(HOME_CONTENT_TOP_SPACING_DP));
        View homeFiles = createHomeFileShortcuts();
        currentHomeFilesView = homeFiles;
        boolean appsInHeaderMenu = appsOpenFromHeader();
        LinearLayout apps = appsInHeaderMenu ? new LinearLayout(this) : appRows();
        currentHomeAppsView = apps;
        View resumes;
        android.os.Trace.beginSection("JojoHome/resumes");
        try {
            resumes = contentRows();
        } finally {
            android.os.Trace.endSection();
        }
        currentHomeResumesView = resumes;
        // The four category buttons now open dedicated immersive pages. In
        // grid mode their former Home rails stay permanently hidden, so
        // constructing every thumbnail here only delays the first interactive
        // frame by several seconds and allocates hundreds of unused Views.
        wireHomeHeaderDpad(homeHeader, apps, homeFiles, resumes);
        if (!appsInHeaderMenu && homeFiles != null && homeSectionBeforeApps("shortcuts")) wireHomeFileShortcutsLeft(apps, homeFiles);
        // Keep the application rail centered inside its column. The previous
        // left translation made every app icon appear offset from the column.
        if (!appsInHeaderMenu) apps.setTranslationX(0);
        LinearLayout.LayoutParams appRowParams = new LinearLayout.LayoutParams(-1, dp(appRowHeight() * homeRows() + (homeRows() - 1) * 10));
        appRowParams.rightMargin = -dp(48);
        boolean showResumes = ContentPresentationRules.showsContinueWatching(continueWatchingEnabled());
        LinearLayout appsSection = new LinearLayout(this);
        appsSection.setOrientation(LinearLayout.VERTICAL);
        appsSection.setClipChildren(false);
        appsSection.setClipToPadding(false);
        addHomeSectionTitle(appsSection, "apps", "Applications", HOME_TITLE_TO_CARD_GAP_DP - HOME_APPS_CONTENT_TOP_INSET_DP);
        appsSection.addView(apps, appRowParams);
        View homeCategoryGrid = gridHome ? createHomeCategoryGrid(continueWatchingModernHero()) : null;
        currentHomeCategoryGrid = homeCategoryGrid instanceof GridLayout
                ? (GridLayout) homeCategoryGrid : null;
        List<String> orderedHomeSections = homeSectionOrder(homeFiles != null, showResumes);
        if (gridHome && showResumes && orderedHomeSections.remove("resumes")) {
            // The Hero is the last scrollable Home module so it can meet the
            // fixed folder navigation without another section below it.
            orderedHomeSections.add("resumes");
        }
        for (String section : orderedHomeSections) {
            View sectionView = null;
            if ("shortcuts".equals(section) && homeFiles != null) sectionView = homeFiles;
            if ("apps".equals(section) && !appsInHeaderMenu) sectionView = appsSection;
            if ("resumes".equals(section) && showResumes) sectionView = resumes;
            if (!gridHome && ExternalPlaybackStore.categoryValid(section)) sectionView = externalPlaybackSection(section);
            if (sectionView == null) continue;
            if (gridHome && ExternalPlaybackStore.categoryValid(section)) {
                sectionView.setVisibility(View.GONE);
                // In grid mode the category cards are the section labels. Do
                // not leave the hidden rail header in the selected category's
                // detail area when showHomeGridCategory() makes it visible.
                if (sectionView instanceof ViewGroup) {
                    ViewGroup sectionGroup = (ViewGroup) sectionView;
                    if (sectionGroup.getChildCount() > 0) sectionGroup.getChildAt(0).setVisibility(View.GONE);
                    if (sectionGroup.getChildCount() > 1) sectionGroup.getChildAt(1).setVisibility(View.GONE);
                }
            }
            // Keep the outer rhythm independent from the section type or its
            // position. Per-rail translations made the visible gap change
            // whenever sections were reordered.
            LinearLayout.LayoutParams sectionParams = new LinearLayout.LayoutParams(-1, -2);
            sectionParams.topMargin = 0;
            if ("resumes".equals(section)) {
                if (gridHome && continueWatchingModernHero()) {
                    // Keep a visible size on the first ScrollView measure;
                    // the measured Home viewport below replaces it with the
                    // exact remaining height.
                    sectionParams.height = dp(continueWatchingHeroHeightDp());
                } else {
                    sectionParams.topMargin -= dp(HOME_CONTINUE_WATCHING_RAISE_DP);
                    if (gridHome) sectionParams.topMargin -= dp(12);
                }
            }
            page.addView(sectionView, sectionParams);
            // Compact shared gap: each section keeps its own internal
            // padding, so the outer separation only needs 8 dp.
            // The Applications rail has a tighter hand-off to the next Home
            // section so Continue Watching stays visible without wasting
            // vertical space below the app cards.
            int baseSectionGap = gridHome && "resumes".equals(section)
                    ? 0 : (("apps".equals(section) || "resumes".equals(section)) ? 4 : 8);
            View spacer = space(baseSectionGap);
            page.addView(spacer);
            currentHomeSectionViews.put(section, sectionView);
            currentHomeSectionSpacers.put(section, spacer);
            spacer.setVisibility(sectionView.getVisibility());
            // The category navigation is mounted below the ScrollView as a
            // fixed bottom bar. It must not participate in the page scroll.
        }
        renderExternalPlaybackRows();
        // In header-menu mode the Applications rail is absent. Rewire once
        // all remaining sections are known so DPAD_DOWN cannot target a
        // detached or invisible app tile.
        wireHomeHeaderDpad(homeHeader, apps, homeFiles, resumes);
        if (gridHome && homeCategoryGrid instanceof GridLayout) {
            wireHomeCategoryGridDpad((GridLayout) homeCategoryGrid, resumes);
        }
        final long creationFocusGeneration = homeFocusGeneration;
        page.post(() -> {
            if (creationFocusGeneration != homeFocusGeneration || currentHomeShell != shell
                    || activeScreen != null || !shell.isAttachedToWindow() || pendingFocusPackage != null) return;
            View current = shell.findFocus();
            if (current != null && isValidHomeFocus(current) && !isSearchHeader(current)) return;
            View target = resolveHomeFocusTarget();
            if (target != null) requestHomeFocus(target, "home-create-restore");
            else requestHomeFocus(firstHomeFocusableChild(apps), "home-create-first-interactive");
        });
        // The home screen owns the vertical scroll.  Continue Watching rows remain
        // horizontal only, so moving between sections scrolls the whole page instead
        // of sliding the resume block inside a fixed viewport.
        ScrollView homeScroll = new ScrollView(this) {
            @Override public boolean requestChildRectangleOnScreen(View child, android.graphics.Rect rectangle, boolean immediate) {
                // Grid Home is a fixed screen: focus reveal must not shift the Hero.
                if (gridHome) return false;
                View focused = findFocus();
                boolean focusInApplications = isHomeDescendant(focused, currentHomeAppsView)
                        || isHomeDescendant(child, currentHomeAppsView);
                if (focusInApplications) {
                    // Android's default focus reveal scrolls the whole Home
                    // vertically while quickly moving across app tiles. The
                    // Applications section must stay anchored below its title;
                    // its own HorizontalScrollView handles left/right reveal.
                    int y = getScrollY();
                    boolean handled = super.requestChildRectangleOnScreen(child, rectangle, immediate);
                    if (getScrollY() != y) scrollTo(getScrollX(), y);
                    return handled;
                }
                return super.requestChildRectangleOnScreen(child, rectangle, immediate);
            }

            @Override public void scrollTo(int x, int y) {
                super.scrollTo(x, gridHome ? 0 : y);
            }

            @Override public boolean executeKeyEvent(android.view.KeyEvent event) {
                return !gridHome && super.executeKeyEvent(event);
            }
        };
        currentHomeScroll = homeScroll;
        homeScroll.setFillViewport(true);
        homeScroll.setVerticalScrollBarEnabled(false);
        if (gridHome) homeScroll.setOverScrollMode(View.OVER_SCROLL_NEVER);
        homeScroll.setClipChildren(false);
        homeScroll.setClipToPadding(false);
        homeScroll.addView(page, new ScrollView.LayoutParams(-1, -2));
        int bottomBarHeight = gridHome ? homeCategoryBottomBarHeight() : 0;
        FrameLayout.LayoutParams homeScrollParams = new FrameLayout.LayoutParams(-1, -1);
        homeScrollParams.bottomMargin = bottomBarHeight;
        shell.addView(homeScroll, homeScrollParams);
        if (gridHome && homeCategoryGrid instanceof GridLayout) {
            FrameLayout bottomBar = new FrameLayout(this);
            bottomBar.setBackgroundColor(continueWatchingModernHero() ? Color.TRANSPARENT : homeBackgroundColor());
            bottomBar.setClipChildren(false);
            bottomBar.setClipToPadding(false);
            bottomBar.addView(homeCategoryGrid, new FrameLayout.LayoutParams(-1, bottomBarHeight,
                    Gravity.CENTER));
            shell.addView(bottomBar, new FrameLayout.LayoutParams(-1, bottomBarHeight,
                    Gravity.BOTTOM));
            if (continueWatchingModernHero()) configureHomeBars(shell, homeHeader, bottomBar);
        }
        if (gridHome && continueWatchingModernHero()) {
            shell.getViewTreeObserver().addOnGlobalLayoutListener(() -> {
                if (currentHomeShell != shell || currentHomePage != page
                        || !shell.isAttachedToWindow() || homeScroll.getHeight() <= 0) return;
                // Resume refreshes replace this section; never keep the detached first View.
                View resumesSection = currentHomeSectionViews.get("resumes");
                if (resumesSection == null || resumesSection.getParent() != page) return;
                LinearLayout.LayoutParams resumesParams =
                        (LinearLayout.LayoutParams) resumesSection.getLayoutParams();
                int occupiedHeight = page.getPaddingTop() + page.getPaddingBottom();
                for (int index = 0; index < page.getChildCount(); index++) {
                    View child = page.getChildAt(index);
                    if (child == resumesSection || child.getVisibility() == View.GONE) continue;
                    LinearLayout.LayoutParams childParams =
                            (LinearLayout.LayoutParams) child.getLayoutParams();
                    occupiedHeight += child.getMeasuredHeight()
                            + childParams.topMargin + childParams.bottomMargin;
                }
                int availableHeight = Math.max(dp(1), homeScroll.getHeight()
                        - occupiedHeight - resumesParams.topMargin - resumesParams.bottomMargin);
                if (resumesParams.height != availableHeight || resumesParams.weight != 0f) {
                    resumesParams.height = availableHeight;
                    resumesParams.weight = 0f;
                    resumesSection.setLayoutParams(resumesParams);
                }
            });
        }
        shell.getViewTreeObserver().addOnGlobalFocusChangeListener((oldFocus, newFocus) -> {
            if (newFocus == null || currentHomeScroll != homeScroll) return;
            if (currentHomeSuggestionsInteraction != null) currentHomeSuggestionsInteraction.accept(false);
            boolean returnedToTop = isHomeDescendant(newFocus, currentHomeHeaderView)
                    || isHomeDescendant(newFocus, currentHomeFilesView)
                    || isHomeDescendant(newFocus, currentHomeAppsView);
            if (returnedToTop) homeScroll.post(() -> homeScroll.scrollTo(0, 0));
        });
        return shell;
    }

    private boolean homeGridMode() {
        return true;
    }

    private void wireHomeCategoryGridDpad(GridLayout grid, View resumes) {
        List<View> cards = immediateFocusableChildren(grid);
        if (cards.isEmpty()) return;
        // Fire TV can consume LEFT/RIGHT on the GridLayout before the
        // individual card's nextFocus ids are consulted. Let the activity
        // boundary resolve the same cyclic row explicitly.
        grid.setTag("cyclic_horizontal_card_row");
        int columns = Math.max(1, grid.getColumnCount());
        List<View> headerControls = currentHomeHeaderView != null
                && currentHomeHeaderView.getTag() instanceof LinearLayout
                ? immediateFocusableChildren((LinearLayout) currentHomeHeaderView.getTag())
                : Collections.emptyList();
        List<List<View>> resumeRows = resumes instanceof ViewGroup
                ? findHorizontalRowFocusableChildren((ViewGroup) resumes) : Collections.emptyList();
        List<View> lastResumeRow = resumeRows.isEmpty()
                ? Collections.emptyList() : resumeRows.get(resumeRows.size() - 1);
        for (int index = 0; index < cards.size(); index++) {
            View card = cards.get(index);
            if (card.getId() == View.NO_ID) card.setId(View.generateViewId());
            View left = cards.get((index - 1 + cards.size()) % cards.size());
            View right = cards.get((index + 1) % cards.size());
            if (left.getId() == View.NO_ID) left.setId(View.generateViewId());
            if (right.getId() == View.NO_ID) right.setId(View.generateViewId());
            card.setNextFocusLeftId(left.getId());
            card.setNextFocusRightId(right.getId());
            int up = index - columns;
            int down = index + columns;
            View upTarget = up >= 0 ? cards.get(up)
                    : (!lastResumeRow.isEmpty() ? alignedTarget(lastResumeRow, index)
                    : (headerControls.isEmpty() ? card : alignedTarget(headerControls, index)));
            card.setNextFocusUpId(upTarget.getId());
            card.setNextFocusDownId((down < cards.size() ? cards.get(down) : card).getId());
            card.setOnKeyListener((view, keyCode, event) -> {
                if (keyCode != KeyEvent.KEYCODE_DPAD_UP
                        || event.getAction() != KeyEvent.ACTION_DOWN
                        || event.getRepeatCount() != 0) return false;
                if (currentHomeResumesView != null
                        && currentHomeResumesView.findViewWithTag("home_empty_suggestions") != null) {
                    View suggestion = currentHomeResumesView.findViewById(view.getNextFocusUpId());
                    if (suggestion != null && suggestion.isShown()) return suggestion.requestFocus();
                }
                View heroTarget = currentHomeResumesView instanceof ViewGroup
                        && currentHomeResumesView.isShown()
                        ? firstFocusableChild((ViewGroup) currentHomeResumesView) : null;
                return heroTarget != null && heroTarget.isShown() && heroTarget.requestFocus();
            });
        }
        if (!headerControls.isEmpty()) {
            List<View> entryRow = resumes instanceof ViewGroup
                    && resumes.findViewWithTag("home_empty_suggestions") != null && !resumeRows.isEmpty()
                    ? resumeRows.get(0) : lastResumeRow;
            for (int index = 0; index < headerControls.size(); index++) {
                View control = headerControls.get(index);
                View downTarget = entryRow.isEmpty()
                        ? alignedTarget(cards, index) : alignedTarget(entryRow, index);
                if (downTarget.getId() == View.NO_ID) downTarget.setId(View.generateViewId());
                control.setNextFocusDownId(downTarget.getId());
            }
        }
        if (!lastResumeRow.isEmpty()) {
            for (int index = 0; index < lastResumeRow.size(); index++) {
                View resumeCard = lastResumeRow.get(index);
                View downTarget = alignedTarget(cards, index);
                if (downTarget.getId() == View.NO_ID) downTarget.setId(View.generateViewId());
                resumeCard.setNextFocusDownId(downTarget.getId());
            }
        }
    }

    private void setHomeCategoryIcon(ImageView icon, int resource) {
        icon.setImageResource(resource);
        if (resource == R.drawable.ic_home_category_live_signal) {
            loadArtwork(icon, nasBaseUrl() + "/api/ui-icons/home_category_live_tv_v1.png");
        }
    }

    private int homeBarsChoice() {
        return HomeChromeRules.homeBarsChoice(homePrefs().getString(HomeChromeRules.HOME_BARS_STYLE, "transparent"));
    }

    private int homeHeroChoice() {
        return HomeChromeRules.homeHeroChoice(homePrefs().getString(HomeChromeRules.HOME_HERO_STYLE, "current"));
    }

    private void configureHomeBars(FrameLayout shell, View header, View bottomBar) {
        int choice = homeBarsChoice();
        if (choice == 0) return;
        FrameLayout artworkHost = shell.findViewWithTag(HOME_HERO_BACKGROUND_TAG);
        final boolean blackBars = choice == 1;
        ImageView topBackdrop = new ImageView(this);
        ImageView bottomBackdrop = new ImageView(this);
        for (ImageView bar : new ImageView[] { topBackdrop, bottomBackdrop }) {
            bar.setScaleType(ImageView.ScaleType.MATRIX);
            bar.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);
            bar.setBackgroundColor(blackBars ? Color.BLACK : Color.rgb(28, 38, 52));
            if (!blackBars) bar.setForeground(new android.graphics.drawable.ColorDrawable(Color.argb(105, 28, 38, 52)));
        }
        int backdropIndex = shell.indexOfChild(artworkHost) + 1;
        shell.addView(topBackdrop, backdropIndex, new FrameLayout.LayoutParams(-1, dp(HOME_HEADER_HEIGHT_DP), Gravity.TOP));
        if (blackBars) {
            bottomBar.setBackgroundColor(Color.BLACK);
        } else {
            shell.addView(bottomBackdrop, backdropIndex + 1, new FrameLayout.LayoutParams(-1, homeCategoryBottomBarHeight(), Gravity.BOTTOM));
            artworkHost.setForeground(new GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM,
                    new int[] { Color.TRANSPARENT, Color.TRANSPARENT, Color.TRANSPARENT,
                            Color.argb(45, 0, 0, 0), Color.argb(150, 0, 0, 0) }));
        }
        final Bitmap[] lastSource = { null };
        final int[] lastSize = { 0, 0 };
        final ImageView.ScaleType[] lastScaleType = { null };
        final int[] revision = { 0 };
        final int[] shellPosition = new int[2], headerPosition = new int[2];
        shell.getViewTreeObserver().addOnPreDrawListener(() -> {
            if (isDestroyed() || currentHomeShell != shell || !shell.isAttachedToWindow()) return true;
            shell.getLocationInWindow(shellPosition);
            header.getLocationInWindow(headerPosition);
            int headerBottom = Math.max(0, headerPosition[1] + header.getHeight() - shellPosition[1]);
            if (topBackdrop.getLayoutParams().height != headerBottom) {
                topBackdrop.getLayoutParams().height = headerBottom;
                topBackdrop.requestLayout();
            }
            if (blackBars) {
                FrameLayout.LayoutParams params = (FrameLayout.LayoutParams) artworkHost.getLayoutParams();
                if (params.topMargin != headerBottom || params.bottomMargin != bottomBar.getHeight()) {
                    params.topMargin = headerBottom; params.bottomMargin = bottomBar.getHeight();
                    artworkHost.setLayoutParams(params);
                    return false;
                }
                return true;
            }
            for (ImageView bar : new ImageView[] { topBackdrop, bottomBackdrop }) {
                if (bar.getDrawable() == null) continue;
                android.graphics.Matrix matrix = new android.graphics.Matrix();
                matrix.setScale(shell.getWidth() / (float) bar.getDrawable().getIntrinsicWidth(),
                        shell.getHeight() / (float) bar.getDrawable().getIntrinsicHeight());
                matrix.postTranslate(0, bar == bottomBackdrop ? -shell.getHeight() + bottomBar.getHeight() : 0);
                bar.setImageMatrix(matrix);
            }
            ImageView artwork = artworkHost.getChildCount() == 0 ? null : (ImageView) artworkHost.getChildAt(0);
            Bitmap source = artwork != null && artwork.getDrawable() instanceof BitmapDrawable
                    ? ((BitmapDrawable) artwork.getDrawable()).getBitmap() : null;
            if (source == lastSource[0] && lastSize[0] == shell.getWidth() && lastSize[1] == shell.getHeight()
                    && lastScaleType[0] == (artwork == null ? null : artwork.getScaleType())) return true;
            lastSource[0] = source; lastSize[0] = shell.getWidth(); lastSize[1] = shell.getHeight();
            lastScaleType[0] = artwork == null ? null : artwork.getScaleType();
            final int request = ++revision[0];
            if (source == null || artworkHost.getWidth() <= 0 || artworkHost.getHeight() <= 0) {
                topBackdrop.setImageDrawable(null); bottomBackdrop.setImageDrawable(null);
                return true;
            }
            int width = 256;
            int height = Math.max(1, Math.round(width * artworkHost.getHeight() / (float) artworkHost.getWidth()));
            Bitmap snapshot = Bitmap.createBitmap(width, height, Bitmap.Config.ARGB_8888);
            android.graphics.Canvas canvas = new android.graphics.Canvas(snapshot);
            canvas.scale(width / (float) artworkHost.getWidth(), height / (float) artworkHost.getHeight());
            artworkHost.draw(canvas);
            cachedArtworkLoadExecutor.execute(() -> {
                Bitmap blurred = new com.nuvio.tv.ui.util.BlurTransformation(4).blur(snapshot);
                if (blurred != snapshot) snapshot.recycle();
                runOnUiThread(() -> {
                    if (isDestroyed() || currentHomeShell != shell || revision[0] != request) {
                        blurred.recycle();
                        return;
                    }
                    topBackdrop.setImageBitmap(blurred); bottomBackdrop.setImageBitmap(blurred);
                });
            });
            return true;
        });
    }

    private View createHomeCategoryGrid(boolean transparentButtons) {
        GridLayout grid = new GridLayout(this);
        // Keep the category shortcuts 10dp closer to the content above them
        // without changing the spacing of the other Home rails.
        grid.setTranslationY(0);
        grid.setAlignmentMode(GridLayout.ALIGN_BOUNDS);
        grid.setUseDefaultMargins(false);
        grid.setClipChildren(false);
        grid.setClipToPadding(false);
        grid.setPadding(0, 0, 0, 0);
        int widthDp = getResources().getDisplayMetrics().widthPixels / Math.max(1, getResources().getDisplayMetrics().densityDpi / 160);
        int columns = 4;
        grid.setColumnCount(columns);
        grid.setRowCount(1);
        grid.setBackgroundColor(Color.TRANSPARENT);
        int barHeight = homeCategoryBottomBarHeight();
        int contentHeight = Math.max(dp(1), barHeight - dp(17));
        Object[][] categories = {
                { "videos", R.drawable.ic_home_category_clapper, "Vidéos", 42 },
                { "movies", R.drawable.ic_home_category_film_reel, "Films", 42 },
                { "series", R.drawable.ic_home_category_series_bottom, "Séries", 45 },
                { "live", R.drawable.ic_home_category_live_signal, "TV", 44 }
        };
        for (Object[] category : categories) {
            ImageView icon = new ImageView(this);
            icon.setScaleType(ImageView.ScaleType.CENTER_INSIDE);
            icon.setBackgroundColor(Color.TRANSPARENT);
            setHomeCategoryIcon(icon, (Integer) category[1]);
            icon.setColorFilter(white, android.graphics.PorterDuff.Mode.SRC_IN);
            FrameLayout iconSlot = new FrameLayout(this);
            // The source images have different transparent margins. Normalize
            // their visible glyphs to about 36dp with the same 52dp slot width.
            int iconSize = Math.min(dp((Integer) category[3]), contentHeight);
            iconSlot.addView(icon, new FrameLayout.LayoutParams(iconSize, iconSize, Gravity.CENTER));
            TextView label = text((String) category[2], 18, white);
            label.setGravity(Gravity.CENTER_VERTICAL);
            label.setSingleLine(true);
            label.setTypeface(Typeface.create("sans-serif-medium", Typeface.NORMAL));
            LinearLayout card = new LinearLayout(this);
            card.setOrientation(LinearLayout.VERTICAL);
            card.setGravity(Gravity.CENTER);
            card.setPadding(dp(18), dp(4), dp(18), dp(4));
            card.setFocusable(true);
            card.setBackground(transparentButtons ? null : homeCategoryCardBg(false));
            LinearLayout itemContent = new LinearLayout(this);
            itemContent.setGravity(Gravity.CENTER);
            itemContent.addView(iconSlot, new LinearLayout.LayoutParams(dp(52), contentHeight));
            LinearLayout.LayoutParams labelParams = new LinearLayout.LayoutParams(-2, contentHeight);
            labelParams.leftMargin = dp(14);
            itemContent.addView(label, labelParams);
            card.addView(itemContent, new LinearLayout.LayoutParams(-1, contentHeight));
            View indicator = new View(this);
            indicator.setBackgroundColor(homeBottomNavigationAccent());
            // The bottom navigation no longer uses an underline for the
            // focused folder; keep the item spacing without drawing a line.
            indicator.setVisibility(View.GONE);
            LinearLayout.LayoutParams indicatorParams = new LinearLayout.LayoutParams(dp(120), dp(3));
            indicatorParams.gravity = Gravity.CENTER_HORIZONTAL;
            card.addView(indicator, indicatorParams);
            card.setContentDescription((String) category[2]);
            card.setOnFocusChangeListener((view, focused) -> {
                view.setBackground(transparentButtons ? null : homeCategoryCardBg(focused));
                int focusColor = focused ? (transparentButtons ? themeColor(4) : homeBottomNavigationAccent()) : white;
                if (focused && !transparentButtons && homeCategoryBackgroundIndex() == folderThemeIndex()) {
                    focusColor = contrastingFolderThemeTextColor();
                } else if (focused && !transparentButtons && androidx.core.graphics.ColorUtils.calculateContrast(
                        focusColor, homeCategoryBackgroundColor()) < 3.0) {
                    focusColor = contrastingThemeTextColor(homeCategoryBackgroundColor());
                }
                icon.setColorFilter(focusColor, android.graphics.PorterDuff.Mode.SRC_IN);
                label.setTextColor(focusColor);
                indicator.setVisibility(View.GONE);
                view.animate().cancel();
                view.animate().scaleX(focused ? 1.03f : 1f).scaleY(focused ? 1.03f : 1f)
                        .setDuration(180L).start();
                view.setTranslationZ(focused ? dp(14) : 0f);
            });
            card.setOnClickListener(view -> openHomeCategoryPage((String) category[0]));
            GridLayout.LayoutParams params = new GridLayout.LayoutParams();
            params.width = 0; params.height = Math.max(dp(1), barHeight - dp(8));
            params.columnSpec = GridLayout.spec(GridLayout.UNDEFINED, 1f);
            params.setMargins(dp(8), dp(4), dp(8), dp(4));
            grid.addView(card, params);
        }
        return grid;
    }

    private GradientDrawable homeCategoryCardBg(boolean focused) {
        GradientDrawable background = new GradientDrawable();
        int configuredIndex = homeCategoryBackgroundIndex();
        int configuredColor = configuredIndex >= 0 ? themeColor(configuredIndex) : Color.TRANSPARENT;
        int color = configuredIndex >= 0
                ? withAlpha(configuredColor, focused ? 235 : 145)
                : focused ? Color.rgb(0x20, 0x28, 0x3A) : Color.TRANSPARENT;
        background.setColor(color);
        background.setCornerRadius(dp(4));
        return background;
    }

    private int homeCategoryBackgroundIndex() {
        int index = homePrefs().getInt("home_category_background_theme", -1);
        return index >= 0 && index < themeColorChoices().length ? index : -1;
    }

    private String homeCategoryBackgroundLabel() {
        int index = homeCategoryBackgroundIndex();
        return index >= 0 ? themeColorChoices()[index] : "Par défaut";
    }

    private String[] homeCategoryBackgroundChoices() {
        String[] colors = themeColorChoices();
        String[] choices = java.util.Arrays.copyOf(colors, colors.length + 1);
        choices[colors.length] = "Par défaut";
        return choices;
    }

    private int homeCategoryBackgroundChoiceIndex() {
        int index = homeCategoryBackgroundIndex();
        return index >= 0 ? index : themeColorChoices().length;
    }

    private int homeCategoryBackgroundColor() {
        int index = homeCategoryBackgroundIndex();
        return index >= 0 ? themeColor(index) : Color.rgb(0x20, 0x28, 0x3A);
    }

    private int homeBottomNavigationAccent() {
        return folderThemeColor();
    }

    private String homeCategoryTitle(String category) {
        if ("movies".equals(category)) return "Films";
        if ("series".equals(category)) return "Séries";
        if ("live".equals(category)) return "TV";
        return "Vidéos";
    }

    private void openHomeCategoryPage(String category) {
        homeCategoryPageCategory = category;
        homeCategoryPageView = createHomeCategoryPage(category);
        homeCategoryPages.put(homeCategoryPageView, category);
        openScreen(homeCategoryPageView);
        if (homeCategoryGridRebuild != null) homeCategoryGridRebuild.run();
    }

    private boolean isTopLevelHomeMediaCategoryPage() {
        if (activeScreen == null) return false;
        String category = homeCategoryPages.get(activeScreen);
        return "videos".equals(category) || "movies".equals(category)
                || "series".equals(category) || "live".equals(category);
    }

    private void refreshActiveHomeCategoryPage() {
        if (activeScreen == null || activeScreen != homeCategoryPageView
                || homeCategoryPageCategory == null || homeCategoryGridRebuild == null) return;
        homeCategoryGridRebuild.run();
    }

    /** Dedicated category screen used by the Home shortcut grid. */
    private View createHomeCategoryPage(String category) {
        if ("live".equals(category)) return createLiveChannelGridPage();
        final long openedAt = android.os.SystemClock.elapsedRealtime();
        final boolean[] firstItemsReported = { false };
        String title = homeCategoryTitle(category);
        final int thumbnailVerticalOffsetDp = 35;
        LinearLayout page = pickerPage(title, "");
        // Category pages use an immersive hero and their own content rail.
        // Keep the generic picker chrome hidden so the artwork reaches the
        // top safe area without duplicating the category title.
        page.setBackgroundColor(Color.BLACK);
        for (int index = 0; index <= 5; index++) {
            if (page.getChildAt(index) != null) page.getChildAt(index).setVisibility(View.GONE);
        }
        LinearLayout content = (LinearLayout) page.getTag();
        content.setClipChildren(false);
        content.setClipToPadding(false);

        FrameLayout hero = new FrameLayout(this);
        hero.setId(View.generateViewId());
        hero.setFocusable(false);
        hero.setDescendantFocusability(ViewGroup.FOCUS_BLOCK_DESCENDANTS);
        hero.setClickable(false);
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) hero.setDefaultFocusHighlightEnabled(false);
        hero.setClipChildren(true);
        hero.setClipToPadding(true);
        hero.setBackgroundColor(Color.BLACK);
        // The hero and the category grid share one bounded viewport. Keeping
        // the grid below the hero prevents Android TV's focus reveal from
        // translating cards into the hero area on some devices.
        final boolean categoryPortraitArtwork = homeCategoryThumbnailPortrait("videos");
        final int episodeArtworkHeightDp = Math.round((continueWatchingTileHeightDp() + 4) * .6f);
        final int categoryArtworkHeightDp = Math.round((categoryPortraitArtwork
                ? 240 : continueWatchingTileHeightDp() + 4) * .75f);
        final int categoryTileHeightDp = !categoryPortraitArtwork
                ? Math.max(categoryArtworkHeightDp, episodeArtworkHeightDp + 28)
                : categoryArtworkHeightDp;
        int bottomPadding = Math.max(safeBottomInset(), dp(48)) - dp(thumbnailVerticalOffsetDp);
        int extraCardHeight = dp(categoryTileHeightDp - categoryArtworkHeightDp);
        bottomPadding -= Math.min(extraCardHeight, Math.max(0, bottomPadding - safeBottomInset()));
        page.setPadding(0, 0, 0, bottomPadding);
        // Keep only the clearance needed by the 1.04x focus zoom; the page
        // keeps its remaining bottom clearance for TV overscan.
        final int gridBottomPaddingDp = 6;
        // Let the Hero's bottom fade meet the thumbnail rail without a blank band.
        final int thumbnailTopGap = 0;
        final int categoryHeroExtension = dp("movies".equals(category) ? 20
                : "videos".equals(category) || "series".equals(category) ? 10 : 0);
        final int categoryHeroHeight = dp(categoryPortraitArtwork ? 291 : 339) + categoryHeroExtension;
        FrameLayout categoryViewport = new FrameLayout(this);
        categoryViewport.setClipChildren(false);
        categoryViewport.setClipToPadding(false);
        categoryViewport.addView(hero, new FrameLayout.LayoutParams(-1, categoryHeroHeight, Gravity.TOP));
        HorizontalScrollView scroll = new HorizontalScrollView(this);
        scroll.setHorizontalScrollBarEnabled(false);
        scroll.setVerticalScrollBarEnabled(false);
        scroll.setFillViewport(false);
        // Let the thumbnail rail use the same full-width viewport as the hero.
        // A small inset leaves room for focus effects on the first and last cards.
        scroll.setPadding(dp(12), 0, dp(12), 0);
        scroll.setClipChildren(false);
        scroll.setClipToPadding(false);
        GridLayout grid = new GridLayout(this);
        grid.setAlignmentMode(GridLayout.ALIGN_BOUNDS);
        grid.setUseDefaultMargins(false);
        grid.setColumnCount(1);
        grid.setRowCount(1);
        grid.setPadding(0, 0, 0, dp(gridBottomPaddingDp));
        grid.setClipChildren(false);
        grid.setClipToPadding(false);
        scroll.addView(grid, new HorizontalScrollView.LayoutParams(-2, -2));
        FrameLayout.LayoutParams scrollParams = new FrameLayout.LayoutParams(-1, -1, Gravity.TOP);
        scrollParams.topMargin = categoryHeroHeight - categoryHeroExtension + thumbnailTopGap;
        categoryViewport.addView(scroll, scrollParams);
        content.addView(categoryViewport, new LinearLayout.LayoutParams(-1, 0, 1f));
        categoryViewport.post(() -> {
            int availableHeight = categoryViewport.getHeight();
            int reservedHeight = dp(categoryTileHeightDp + gridBottomPaddingDp) + thumbnailTopGap;
            int heroHeight = Math.max(dp(190), availableHeight - reservedHeight);
            FrameLayout.LayoutParams heroParams = (FrameLayout.LayoutParams) hero.getLayoutParams();
            heroParams.height = heroHeight + categoryHeroExtension;
            hero.setLayoutParams(heroParams);
            ImageView currentArtwork = hero.findViewWithTag("home_category_hero_artwork");
            if (currentArtwork != null) {
                FrameLayout.LayoutParams artworkParams =
                        (FrameLayout.LayoutParams) currentArtwork.getLayoutParams();
                artworkParams.width = heroArtworkWidth();
                currentArtwork.setLayoutParams(artworkParams);
            }
            scrollParams.topMargin = heroHeight + thumbnailTopGap;
            scroll.setLayoutParams(scrollParams);
        });

        final JojoProgram[] selectedProgram = { null };
        final JSONObject[] selectedItem = { null };
        final ArrayList<JojoProgram> categoryHeroPrograms = new ArrayList<>();
        final ArrayList<JSONObject> categoryHeroItems = new ArrayList<>();
        final Set<String> inProgressSeriesFolders = new HashSet<>();
        final int[] categoryHeroIndex = { 0 };
        final Runnable focusSelectedCategoryThumbnail = () -> {
            if (activeScreen != page || homeCategoryPageView != page || !page.isAttachedToWindow()) return;
            if (activePopup != null || grid.getChildCount() == 0) return;
            int selectedIndex = Math.max(0, Math.min(categoryHeroIndex[0], grid.getChildCount() - 1));
            View selectedTile = grid.getChildAt(selectedIndex);
            if (selectedTile != null) selectedTile.requestFocus();
        };
        final Runnable[] syncHeroDownFocus = new Runnable[1];
        syncHeroDownFocus[0] = () -> {
            int selectedIndex = Math.max(0, Math.min(categoryHeroIndex[0], grid.getChildCount() - 1));
            if (grid.getChildCount() == 0) return;
            View selectedTile = grid.getChildAt(selectedIndex);
            if (selectedTile.getId() == View.NO_ID) selectedTile.setId(View.generateViewId());
            hero.setNextFocusDownId(selectedTile.getId());
        };
        final Runnable[] bindSelected = new Runnable[1];
        bindSelected[0] = () -> {
            if (categoryHeroPrograms.isEmpty()) {
                selectedProgram[0] = null;
                selectedItem[0] = null;
            } else {
                int index = Math.max(0, Math.min(categoryHeroIndex[0], categoryHeroPrograms.size() - 1));
                categoryHeroIndex[0] = index;
                selectedProgram[0] = categoryHeroPrograms.get(index);
                selectedItem[0] = categoryHeroItems.get(index);
            }
            bindHomeCategoryHero(hero, category, selectedProgram[0], selectedItem[0]);
            if (categoryHeroPrograms.isEmpty()) return;
            // Keep downward navigation from the Hero linked to the selected thumbnail.
            syncHeroDownFocus[0].run();
        };
        HomeMediaRules.FocusUpdate focusHeroUpdate = new HomeMediaRules.FocusUpdate(
                () -> activeScreen == page && homeCategoryPageView == page && page.isAttachedToWindow(),
                () -> {
                    if (hero.getTag(CATEGORY_HERO_PROGRAM_TAG) != selectedProgram[0]) bindSelected[0].run();
                }, hero::postOnAnimation);

        Runnable sortVideoTiles = () -> {
            if (!"videos".equals(category) || activeScreen != page || homeCategoryPageView != page
                    || !page.isAttachedToWindow() || grid.getChildCount() != categoryHeroPrograms.size()) return;
            List<JojoProgram> previousOrder = new ArrayList<>(categoryHeroPrograms);
            sortFreeboxHomeVideos(categoryHeroPrograms);
            cacheFreeboxHomeVideoDurations(categoryHeroPrograms);
            int selectedIndex = categoryHeroPrograms.indexOf(selectedProgram[0]);
            if (selectedIndex >= 0) categoryHeroIndex[0] = selectedIndex;
            if (previousOrder.equals(categoryHeroPrograms)) return;
            // Move the existing views so artwork and D-pad focus stay with the file.
            for (int index = 0; index < categoryHeroPrograms.size(); index++) {
                View tile = grid.findViewWithTag(resumeDismissKey(categoryHeroPrograms.get(index)));
                if (tile == null) continue;
                GridLayout.LayoutParams params = (GridLayout.LayoutParams) tile.getLayoutParams();
                params.rowSpec = GridLayout.spec(0);
                params.columnSpec = GridLayout.spec(index);
                tile.setLayoutParams(params);
                grid.bringChildToFront(tile);
            }
            wireCategoryPageGrid(grid, hero);
            syncHeroDownFocus[0].run();
            View focused = getCurrentFocus();
            if (focused != null && grid.hasFocus()) grid.post(() -> {
                if (focused == getCurrentFocus()) revealContinueWatchingCard(scroll, focused, 140L);
            });
        };

        final int[] rebuildGeneration = { 0 };
        final int[] tileRenderGeneration = { 0 };
        homeCategoryVideoRemoval = deleted -> {
            if (!"videos".equals(category) || activeScreen != page) return;
            String deletedPath = comparableSmbPath(deleted.intentUri);
            boolean removed = false;
            for (int index = categoryHeroPrograms.size() - 1; index >= 0; index--) {
                if (!deletedPath.equals(comparableSmbPath(categoryHeroPrograms.get(index).intentUri))) continue;
                categoryHeroPrograms.remove(index);
                categoryHeroItems.remove(index);
                removed = true;
                if (index < categoryHeroIndex[0]) categoryHeroIndex[0]--;
            }
            if (!removed) return;
            tileRenderGeneration[0]++;
            // GridLayout keeps the inferred column indices after a deletion.
            // Reindex remaining children before shrinking its column count.
            for (int index = 0; index < grid.getChildCount(); index++) {
                View tile = grid.getChildAt(index);
                GridLayout.LayoutParams params = (GridLayout.LayoutParams) tile.getLayoutParams();
                params.rowSpec = GridLayout.spec(0);
                params.columnSpec = GridLayout.spec(index);
                tile.setLayoutParams(params);
            }
            grid.setColumnCount(Math.max(1, Math.max(grid.getChildCount(), categoryHeroPrograms.size())));
            bindSelected[0].run();
            if (!categoryHeroPrograms.isEmpty()) focusSelectedCategoryThumbnail.run();
            if (grid.getChildCount() < categoryHeroPrograms.size() && homeCategoryGridRebuild != null)
                homeCategoryGridRebuild.run();
        };
        Runnable rebuild = () -> {
            final String selectedPathAtRebuild = selectedProgram[0] == null
                    || selectedProgram[0].intentUri == null
                    ? "" : selectedProgram[0].intentUri;
            final int selectedIndexAtRebuild = categoryHeroIndex[0];
            final boolean keepExistingTiles = activeScreen == page && grid.getChildCount() > 0;
            final int generation = ++rebuildGeneration[0];
            if (!keepExistingTiles) {
                grid.removeAllViews();
                categoryHeroPrograms.clear();
                categoryHeroItems.clear();
                categoryHeroIndex[0] = 0;
                selectedProgram[0] = null;
                selectedItem[0] = null;
                hero.removeAllViews();
                TextView loading = text("Chargement…", 22, muted);
                loading.setGravity(Gravity.CENTER);
                hero.addView(loading, new FrameLayout.LayoutParams(-1, -1));
            }

            final boolean portraitArtwork = categoryPortraitArtwork;
            final int tileWidth = dp(Math.round((portraitArtwork ? 160 : 210) * .75f));
            final int tileHeight = dp(categoryTileHeightDp);
            final int episodeTileWidth = dp(Math.round(freeboxVideosTileWidthDp() * .6f));
            final int episodeTileHeight = dp(episodeArtworkHeightDp);
            final int episodeCardHeight = episodeTileHeight + dp(28);
            final int[] renderedTileCount = { 0 };
            final Runnable[] appendTiles = new Runnable[1];
            appendTiles[0] = () -> {
                if (generation != rebuildGeneration[0] || homeCategoryPageView != page) return;
                final int renderToken = ++tileRenderGeneration[0];
                final boolean[] focusRestored = { false };
                HomeMediaRules.renderInBatches(categoryHeroPrograms.size(),
                        () -> generation == rebuildGeneration[0] && renderToken == tileRenderGeneration[0]
                                && homeCategoryPageView == page && page.isAttachedToWindow(), itemIndex -> {
                    final JSONObject item = categoryHeroItems.get(itemIndex);
                    final JojoProgram program = categoryHeroPrograms.get(itemIndex);
                    boolean landscapeFolder = !portraitArtwork
                            && FREEBOX_FOLDER_SOURCE.equals(program.sourcePackage);
                    View tile = jojoProgramTile(program, item == null, portraitArtwork,
                            true, landscapeFolder ? .6f : .75f, landscapeFolder, true);
                    String seriesFolderKey = FREEBOX_FOLDER_SOURCE.equals(program.sourcePackage)
                            ? comparableSmbPath(program.intentUri) : program.intentUri;
                    if ("series".equals(category) && isThumbnailInProgress(program)) clearEpisodeStatusBadge(tile);
                    if (("series".equals(category) && item != null
                            && isSeriesItemInProgress(item, HomeWatchProgressBridge.currentProfileId(this)))
                            || inProgressSeriesFolders.contains(seriesFolderKey)) {
                        showSeriesFolderInProgressBadge(tile);
                    }
                    if (FREEBOX_FOLDER_SOURCE.equals(program.sourcePackage))
                        tile.setTag(CATEGORY_FOLDER_METADATA_REFRESH_TAG, (Runnable) () -> {
                            if (selectedProgram[0] == program) bindSelected[0].run();
                        });
                    else if (FILE_VIDEO_RESUME_SOURCE.equals(program.sourcePackage))
                        tile.setTag(CATEGORY_VIDEO_METADATA_REFRESH_TAG, (Runnable) () -> {
                            sortVideoTiles.run();
                            if (selectedProgram[0] == program) bindSelected[0].run();
                        });
                    View.OnFocusChangeListener tileFocus = tile.getOnFocusChangeListener();
                    tile.setOnFocusChangeListener((view, focused) -> {
                        if (tileFocus != null) tileFocus.onFocusChange(view, focused);
                        if (focused) {
                            int currentIndex = categoryHeroPrograms.indexOf(program);
                            if (currentIndex < 0) return;
                            categoryHeroIndex[0] = currentIndex;
                            selectedProgram[0] = program;
                            selectedItem[0] = item;
                            if (view.getId() == View.NO_ID) view.setId(View.generateViewId());
                            hero.setNextFocusDownId(view.getId());
                            focusHeroUpdate.run();
                        }
                    });
                    if (item != null) {
                        tile.setOnClickListener(view -> openExternalPlayback(
                                ExternalPlaybackStore.get(this, item.optString("id", "")), true, false));
                    }
                    tile.setOnLongClickListener(view -> {
                        if (FREEBOX_FOLDER_SOURCE.equals(program.sourcePackage)) {
                            showFreeboxFolderHomeMenu(program, tile, false, hero);
                        } else {
                            showContinueWatchingMenu(program, tile, item != null, false, hero);
                        }
                        return true;
                    });
                    GridLayout.LayoutParams tileParams = new GridLayout.LayoutParams();
                    tileParams.width = landscapeFolder ? episodeTileWidth : tileWidth;
                    tileParams.height = landscapeFolder ? episodeCardHeight : tileHeight;
                    tileParams.setMargins(dp(9), 0, dp(9), 0);
                    grid.addView(tile, tileParams);
                    renderedTileCount[0]++;
                }, grid::postOnAnimation, () -> {
                    // Wait only for the current view batch, never for all duration probes.
                    sortVideoTiles.run();
                    if (!firstItemsReported[0] && grid.getChildCount() > 0) {
                        firstItemsReported[0] = true;
                        android.util.Log.i("JojoHomeFolders", "CATEGORY_FIRST_ITEMS category=" + category
                                + " elapsedMs=" + (android.os.SystemClock.elapsedRealtime() - openedAt));
                    }
                    wireCategoryPageGrid(grid, hero);
                    if (grid.getChildCount() > 0) {
                        int selectedIndex = Math.max(0, Math.min(categoryHeroIndex[0], grid.getChildCount() - 1));
                        View selectedTile = grid.getChildAt(selectedIndex);
                        if (selectedTile.getId() == View.NO_ID) selectedTile.setId(View.generateViewId());
                        hero.setNextFocusDownId(selectedTile.getId());
                    }
                    if (pendingPlayerFocusScreen == page) {
                        focusRestored[0] = restorePlayerReturnFocus(page, null);
                        if (!focusRestored[0] && grid.getChildCount() == categoryHeroPrograms.size())
                            focusRestored[0] = restorePlayerReturnFocus(page, grid.getChildAt(
                                    Math.min(categoryHeroIndex[0], grid.getChildCount() - 1)));
                    } else if (!focusRestored[0] && categoryHeroIndex[0] < grid.getChildCount()
                            && (renderedTileCount[0] <= 6 || page.hasFocus())) {
                        focusRestored[0] = true;
                        focusSelectedCategoryThumbnail.run();
                    }
                });
            };

            if (!keepExistingTiles && !"videos".equals(category)) {
                List<JSONObject> cachedFavorites = homeCategoryFavoriteSnapshots.get(category);
                if (cachedFavorites != null) {
                    for (JSONObject item : cachedFavorites) {
                        if (isExternalRemovalPending(item.optString("id"))) continue;
                        categoryHeroItems.add(item);
                        categoryHeroPrograms.add(homeCategoryExternalProgram(category, item));
                    }
                    grid.setColumnCount(Math.max(1, categoryHeroPrograms.size()));
                    grid.setRowCount(1);
                    bindSelected[0].run();
                    final int snapshotToken = tileRenderGeneration[0];
                    page.post(() -> {
                        if (snapshotToken == tileRenderGeneration[0]) appendTiles[0].run();
                    });
                }
            }

            if (!keepExistingTiles && "videos".equals(category)) {
                List<JojoProgram> cachedVideos = cachedFreeboxHomeVideos();
                if (!cachedVideos.isEmpty()) {
                    categoryHeroPrograms.addAll(cachedVideos);
                    for (int index = 0; index < cachedVideos.size(); index++) categoryHeroItems.add(null);
                    grid.setColumnCount(Math.max(1, categoryHeroPrograms.size()));
                    grid.setRowCount(1);
                    bindSelected[0].run();
                    final int snapshotToken = tileRenderGeneration[0];
                    page.post(() -> {
                        if (snapshotToken == tileRenderGeneration[0]) appendTiles[0].run();
                    });
                }
            }

            new Thread(() -> {
                // Re-enumerate Freebox/Vidéos whenever this page opens (or is
                // revisited), so NAS-side additions and deletions replace the
                // last local snapshot instead of being hidden by it.
                // Reuse the already enumerated Home cache for the first paint.
                // SMB enumeration can take several seconds on Fire OS; the
                // category must not replace its Hero with "Chargement…" when
                // the same videos are already available locally.
                // The Videos destination must represent the current SMB folder,
                // not the reduced Home rail snapshot.  Re-enumerate Freebox/Vidéos
                // when the page opens so newly added folders/files appear
                // immediately and previously resumed files are not hidden.
                final List<JojoProgram> videoPrograms = "videos".equals(category)
                        ? new ArrayList<>(loadHomeCategoryVideos()) : Collections.emptyList();
                final List<JSONObject> externalItems = "videos".equals(category)
                        ? Collections.emptyList() : new ArrayList<>(com.jojotv.home.iptv.IptvStore.applyHomeFavoriteProgress(
                                this, ExternalPlaybackStore.list(this, category)));
                final int progressProfileId = HomeWatchProgressBridge.currentProfileId(this);
                final Set<String> loadedInProgressSeriesFolders =
                        inProgressSeriesFolderKeys(category, externalItems, progressProfileId);
                runOnUiThread(() -> {
                    if (generation != rebuildGeneration[0] || homeCategoryPageView != page) return;
                    inProgressSeriesFolders.clear();
                    if (progressProfileId == HomeWatchProgressBridge.currentProfileId(this))
                        inProgressSeriesFolders.addAll(loadedInProgressSeriesFolders);
                    if ("videos".equals(category)) videoPrograms.removeIf(program ->
                            isHomeVideoHidden(program.intentUri) || FILE_VIDEO_RESUME_SOURCE.equals(program.sourcePackage)
                                    && hasDeletedFreeboxPath(program.intentUri));
                    if (!"videos".equals(category)) {
                        // A listing may have started before the Home removal was saved.
                        externalItems.removeIf(item -> isExternalRemovalPending(item.optString("id")));
                        homeCategoryFavoriteSnapshots.put(category, new ArrayList<>(externalItems));
                    }
                    final int total = "videos".equals(category) ? videoPrograms.size() : externalItems.size();
                    String previouslySelectedPath = selectedProgram[0] == null
                            || selectedProgram[0].intentUri == null
                            ? selectedPathAtRebuild : selectedProgram[0].intentUri;
                    int previouslySelectedIndex = selectedProgram[0] == null
                            ? selectedIndexAtRebuild : categoryHeroIndex[0];
                    tileRenderGeneration[0]++;
                    grid.removeAllViews();
                    renderedTileCount[0] = 0;
                    categoryHeroPrograms.clear();
                    categoryHeroItems.clear();
                    for (int heroIndex = 0; heroIndex < total; heroIndex++) {
                        JSONObject heroItem = "videos".equals(category) ? null : externalItems.get(heroIndex);
                        JojoProgram heroProgram;
                        if (heroItem == null) {
                            heroProgram = videoPrograms.get(heroIndex);
                        } else {
                            heroProgram = homeCategoryExternalProgram(category, heroItem);
                        }
                        categoryHeroItems.add(heroItem);
                        categoryHeroPrograms.add(heroProgram);
                    }
                    grid.setColumnCount(Math.max(1, total));
                    grid.setRowCount(1);
                    if (total > 0) {
                        // Bind the first item as soon as the data list arrives.
                        // Building the thumbnail views and requesting D-pad focus
                        // can be deferred by Android TV; neither must block the
                        // Hero from leaving its loading state.
                        categoryHeroIndex[0] = Math.max(0, Math.min(previouslySelectedIndex, total - 1));
                        if (!previouslySelectedPath.isEmpty()) {
                            for (int matchIndex = 0; matchIndex < categoryHeroPrograms.size(); matchIndex++) {
                                if (previouslySelectedPath.equals(categoryHeroPrograms.get(matchIndex).intentUri)) {
                                    categoryHeroIndex[0] = matchIndex;
                                    break;
                                }
                            }
                        }
                        selectedProgram[0] = categoryHeroPrograms.get(0);
                        selectedProgram[0] = categoryHeroPrograms.get(categoryHeroIndex[0]);
                        selectedItem[0] = categoryHeroItems.get(categoryHeroIndex[0]);
                        bindSelected[0].run();
                    }
                    if (total == 0) {
                        bindSelected[0].run();
                    } else {
                        appendTiles[0].run();
                    }
                });
            }, "JojoHomeCategoryData").start();
        };
        homeCategoryGridRebuild = rebuild;
        return page;
    }

    private View createLiveChannelGridPage() {
        LinearLayout page = pickerPage("TV", "");
        for (int index = 0; index <= 5; index++) {
            if (page.getChildAt(index) != null) page.getChildAt(index).setVisibility(View.GONE);
        }
        page.setPadding(0, 0, 0, safeBottomInset());
        LinearLayout content = (LinearLayout) page.getTag();
        FrameLayout viewport = new FrameLayout(this);
        ScrollView scroll = new ScrollView(this);
        scroll.setFocusable(false);
        scroll.setVerticalScrollBarEnabled(false);
        scroll.setPadding(dp(14), dp(18), dp(14), dp(18));
        scroll.setClipToPadding(false);
        GridLayout grid = new GridLayout(this);
        grid.setAlignmentMode(GridLayout.ALIGN_BOUNDS);
        grid.setUseDefaultMargins(false);
        grid.setClipChildren(false);
        grid.setClipToPadding(false);
        scroll.addView(grid, new ScrollView.LayoutParams(-1, -2));
        viewport.addView(scroll, new FrameLayout.LayoutParams(-1, -1));
        content.addView(viewport, new LinearLayout.LayoutParams(-1, 0, 1f));
        TextView status = text("Chargement…", 22, muted);
        status.setGravity(Gravity.CENTER);
        viewport.addView(status, new FrameLayout.LayoutParams(-1, -1));

        ArrayList<JSONObject> channels = new ArrayList<>();
        final JSONObject[] selected = { null };
        final int[] generation = { 0 };
        final int[] finishingKey = { KeyEvent.KEYCODE_UNKNOWN };
        movingLiveChannelGrid = false;
        Runnable layoutGrid = () -> {
            int width = viewport.getWidth() > 0 ? viewport.getWidth()
                    : getResources().getDisplayMetrics().widthPixels;
            int availableWidth = Math.max(dp(1), width - dp(28));
            int columns = Math.max(1, availableWidth / dp(174));
            List<View> tiles = new ArrayList<>();
            for (int index = 0; index < grid.getChildCount(); index++) tiles.add(grid.getChildAt(index));
            View focused = grid.findFocus();
            grid.removeAllViews();
            grid.setColumnCount(columns);
            grid.setRowCount(Math.max(1, (tiles.size() + columns - 1) / columns));
            for (int index = 0; index < tiles.size(); index++) {
                View tile = tiles.get(index);
                if (tile.getId() == View.NO_ID) tile.setId(View.generateViewId());
                GridLayout.LayoutParams params = new GridLayout.LayoutParams(
                        GridLayout.spec(index / columns), GridLayout.spec(index % columns));
                params.width = availableWidth / columns - dp(16);
                params.height = -2;
                params.setMargins(dp(8), dp(8), dp(8), dp(8));
                grid.addView(tile, params);
            }
            if (focused != null) focused.requestFocus();
        };
        Runnable updateMoveAppearance = () -> {
            for (int index = 0; index < grid.getChildCount(); index++) {
                View tile = grid.getChildAt(index);
                boolean selectedTile = selected[0] != null
                        && resumeDismissKey(homeCategoryExternalProgram("live", selected[0])).equals(tile.getTag());
                tile.setAlpha(movingLiveChannelGrid && !selectedTile ? .45f : 1f);
            }
        };
        finishLiveChannelGridMove = () -> {
            movingLiveChannelGrid = false;
            updateMoveAppearance.run();
        };
        beginLiveChannelGridMove = anchor -> {
            if (activeScreen != page) return;
            for (int index = 0; index < grid.getChildCount(); index++) {
                View tile = grid.getChildAt(index);
                if (!java.util.Objects.equals(anchor.getTag(), tile.getTag())) continue;
                tile.requestFocus();
                movingLiveChannelGrid = true;
                updateMoveAppearance.run();
                Toast.makeText(this, "Flèches : déplacer · OK ou Retour : terminer", Toast.LENGTH_LONG).show();
                break;
            }
        };
        liveChannelGridKeys = (view, keyCode, event) -> {
            if (activeScreen != page || (activePopup != null && activePopup.isShowing())) return false;
            if (keyCode == finishingKey[0]) {
                // Consume the release too, so finishing a move cannot also open the channel or leave the page.
                if (event.getAction() == KeyEvent.ACTION_UP) finishingKey[0] = KeyEvent.KEYCODE_UNKNOWN;
                return true;
            }
            boolean direction = keyCode == KeyEvent.KEYCODE_DPAD_LEFT || keyCode == KeyEvent.KEYCODE_DPAD_RIGHT
                    || keyCode == KeyEvent.KEYCODE_DPAD_UP || keyCode == KeyEvent.KEYCODE_DPAD_DOWN;
            boolean finish = keyCode == KeyEvent.KEYCODE_DPAD_CENTER || keyCode == KeyEvent.KEYCODE_ENTER
                    || keyCode == KeyEvent.KEYCODE_NUMPAD_ENTER || keyCode == KeyEvent.KEYCODE_BACK
                    || keyCode == KeyEvent.KEYCODE_ESCAPE || keyCode == KeyEvent.KEYCODE_BUTTON_B;
            if (movingLiveChannelGrid && finish) {
                if (event.getAction() == KeyEvent.ACTION_DOWN && event.getRepeatCount() == 0) {
                    finishingKey[0] = keyCode;
                    finishLiveChannelGridMove.run();
                }
                return true;
            }
            int index = grid.indexOfChild(getCurrentFocus());
            if (!direction || index < 0) return false;
            if (event.getAction() == KeyEvent.ACTION_UP) finishHomeDpadNavigation();
            if (event.getAction() != KeyEvent.ACTION_DOWN || event.getRepeatCount() != 0) return true;
            homeDpadNavigationActive = true;
            int target = HomeMediaRules.liveGridNeighbor(index, grid.getChildCount(), grid.getColumnCount(),
                    keyCode == KeyEvent.KEYCODE_DPAD_LEFT ? -1 : keyCode == KeyEvent.KEYCODE_DPAD_RIGHT ? 1 : 0,
                    keyCode == KeyEvent.KEYCODE_DPAD_UP ? -1 : keyCode == KeyEvent.KEYCODE_DPAD_DOWN ? 1 : 0);
            if (movingLiveChannelGrid && target != index) {
                JSONObject channel = channels.remove(index);
                channels.add(target, channel);
                View tile = grid.getChildAt(index);
                grid.removeView(tile);
                grid.addView(tile, target);
                homePrefs().edit().putString("live_channel_grid_order",
                        jsonArray(channels.stream().map(item -> item.optString("id")).collect(java.util.stream.Collectors.toList())).toString()).apply();
                homeCategoryFavoriteSnapshots.put("live", new ArrayList<>(channels));
                layoutGrid.run();
                tile.requestFocus();
            } else grid.getChildAt(target).requestFocus();
            return true;
        };
        java.util.function.Consumer<List<JSONObject>> render = loaded -> {
            String selectedId = selected[0] == null ? "" : selected[0].optString("id");
            channels.clear();
            channels.addAll(loaded);
            List<String> savedIds;
            try { savedIds = jsonList(new JSONArray(homePrefs().getString("live_channel_grid_order", "[]"))); }
            catch (org.json.JSONException ignored) { savedIds = Collections.emptyList(); }
            List<String> order = HomeMediaRules.liveChannelOrder(
                    channels.stream().map(item -> item.optString("id")).collect(java.util.stream.Collectors.toList()), savedIds);
            Map<String, Integer> ranks = new HashMap<>();
            for (int index = 0; index < order.size(); index++) ranks.put(order.get(index), index);
            channels.sort(java.util.Comparator.comparingInt(item -> ranks.getOrDefault(item.optString("id"), Integer.MAX_VALUE)));
            homeCategoryFavoriteSnapshots.put("live", new ArrayList<>(channels));
            grid.removeAllViews();
            selected[0] = null;
            View selectedTile = null;
            for (JSONObject item : channels) {
                JojoProgram program = homeCategoryExternalProgram("live", item);
                LinearLayout tile = (LinearLayout) jojoProgramTile(program, false, false, true, .75f, true, true);
                tile.getChildAt(0).setLayoutParams(new LinearLayout.LayoutParams(-1, dp(100)));
                TextView label = (TextView) tile.getChildAt(1);
                label.setText(HomeMediaRules.liveChannelDisplayName(program.title));
                label.setGravity(Gravity.CENTER);
                label.setTextColor(Color.WHITE);
                label.setShadowLayer(dp(2), 0, dp(1), Color.BLACK);
                ImageView logo = resolveArtworkView(tile);
                if (logo != null) logo.setBackgroundColor(Color.TRANSPARENT);
                View.OnFocusChangeListener focus = tile.getOnFocusChangeListener();
                tile.setOnFocusChangeListener((view, focused) -> {
                    if (focus != null) focus.onFocusChange(view, focused);
                    if (!focused) return;
                    selected[0] = item;
                });
                tile.setOnClickListener(view -> openExternalPlayback(
                        ExternalPlaybackStore.get(this, item.optString("id")), true, false));
                tile.setOnLongClickListener(view -> {
                    showContinueWatchingMenu(program, tile, true, false);
                    return true;
                });
                grid.addView(tile);
                if (selectedTile == null || selectedId.equals(item.optString("id"))) {
                    selectedTile = tile;
                    selected[0] = item;
                }
            }
            status.setText("Aucune chaîne dans TV");
            status.setVisibility(channels.isEmpty() ? View.VISIBLE : View.GONE);
            layoutGrid.run();
            if (selectedTile != null) {
                if (activePopup == null || !activePopup.isShowing()) selectedTile.requestFocus();
            } else {
                movingLiveChannelGrid = false;
            }
            updateMoveAppearance.run();
        };
        viewport.addOnLayoutChangeListener((view, left, top, right, bottom, oldLeft, oldTop, oldRight, oldBottom) -> {
            if (right - left != oldRight - oldLeft) layoutGrid.run();
        });
        homeCategoryVideoRemoval = null;
        homeCategoryGridRebuild = () -> {
            int token = ++generation[0];
            List<JSONObject> cached = homeCategoryFavoriteSnapshots.getOrDefault("live", Collections.emptyList());
            if (grid.getChildCount() == 0 && !cached.isEmpty()) render.accept(new ArrayList<>(cached));
            new Thread(() -> {
                List<JSONObject> loaded = ExternalPlaybackStore.list(this, "live");
                runOnUiThread(() -> {
                    if (token == generation[0] && homeCategoryPageView == page) render.accept(loaded);
                });
            }, "JojoHomeLiveGrid").start();
        };
        return page;
    }

    private JojoProgram homeCategoryExternalProgram(String category, JSONObject item) {
        boolean currentProfileProgress = !item.has("progressProfileId")
                || item.optInt("progressProfileId") == HomeWatchProgressBridge.currentProfileId(this);
        String artworkUrl = "live".equals(category)
                ? liveChannelArtwork(item, true)
                : selectedExternalFavoriteHeroArtwork(item);
        if (artworkUrl.isEmpty() && !"live".equals(category)) {
            artworkUrl = externalPlaybackArtwork(item);
        }
        String itemTitle = "live".equals(category)
                ? item.optString("title", "")
                : displayIptvTitle(item.optString("title", ""),
                item.optString("season", null), item.optString("episode", null));
        return new JojoProgram("external-playback", itemTitle, "", artworkUrl,
                item.optString("id", ""), currentProfileProgress ? item.optLong("duration") : 0L,
                currentProfileProgress ? item.optLong("position") : 0L,
                "series".equals(category) ? item.optString("season", null) : null,
                "series".equals(category) ? item.optString("episode", null) : null,
                currentProfileProgress && item.optBoolean("watched", false));
    }

    private void bindHomeCategoryHero(FrameLayout hero, String category,
                                      JojoProgram program, JSONObject item) {
        bindHomeCategoryHero(hero, category, program, item, true);
    }

    private void bindHomeCategoryHero(FrameLayout hero, String category,
                                      JojoProgram program, JSONObject item,
                                      boolean loadFolderMetadata) {
        hero.setTag(CATEGORY_HERO_PROGRAM_TAG, program);
        hero.setTag(CATEGORY_HERO_ITEM_TAG, item);
        hero.removeAllViews();
        if (program == null) {
            TextView empty = text("Aucun contenu dans " + homeCategoryTitle(category), 22, muted);
            empty.setGravity(Gravity.CENTER);
            hero.addView(empty, new FrameLayout.LayoutParams(-1, -1));
            return;
        }

        // Match the Home hero: the artwork itself fades into the dark editorial
        // side, with no pale layer over the image.
        HeroArtworkImageView artwork = new HeroArtworkImageView(this, false,
                HERO_HORIZONTAL_FADE_END_FRACTION, 5f);
        artwork.landscapeOnly = "movies".equals(category) || "series".equals(category);
        artwork.setTag("home_category_hero_artwork");
        artwork.setTag(CATEGORY_HERO_PROGRAM_TAG, program);
        // Movie and series heroes wait for a landscape instead of flashing the card's poster.
        artwork.setScaleType(ImageView.ScaleType.FIT_CENTER);
        artwork.setBackgroundColor(Color.TRANSPARENT);
        int artworkWidth = heroArtworkWidth();
        hero.addView(artwork, new FrameLayout.LayoutParams(artworkWidth, -1, Gravity.RIGHT));
        loadHomeCategoryHeroArtwork(artwork, category, program, item);

        View edgeFade = new View(this);
        edgeFade.setBackground(homeHeroEdgeFade(false));
        hero.addView(edgeFade, new FrameLayout.LayoutParams(-1, -1));

        LinearLayout editorial = new LinearLayout(this);
        editorial.setOrientation(LinearLayout.VERTICAL);
        editorial.setGravity(Gravity.TOP);
        editorial.setClipChildren(false);
        editorial.setClipToPadding(false);
        // Let the flexible spacer absorb synopsis-height changes without
        // shifting the editorial content.
        editorial.setPadding(0, dp(18), dp(12), 0);
        FrameLayout.LayoutParams editorialParams = new FrameLayout.LayoutParams(
                Math.min(dp(530), Math.round(getResources().getDisplayMetrics().widthPixels * .50f)),
                -1, Gravity.LEFT);
        hero.addView(editorial, editorialParams);

        String displayTitle = homeCategoryHeroTitle(category, program);
        // The first thumbnail begins after the rail's 12 dp inset and 9 dp card margin.
        int editorialLeftInset = dp(21);
        FrameLayout titleSlot = new FrameLayout(this);
        titleSlot.setClipChildren(false);
        titleSlot.setClipToPadding(false);
        TextView title = text(displayTitle, 31, Color.WHITE);
        title.setTag("home_category_hero_title");
        title.setTypeface(null, Typeface.BOLD);
        int fallbackTitleWidth = Math.max(dp(1), editorialParams.width
                - editorial.getPaddingRight() - editorialLeftInset);
        title.setText(splitHomeHeroFallbackTitle(displayTitle, fallbackTitleWidth, title.getPaint()));
        title.setSingleLine(false);
        title.setMaxLines(2);
        title.setIncludeFontPadding(false);
        title.setEllipsize(TextUtils.TruncateAt.END);
        title.setHorizontallyScrolling(false);
        title.setGravity(Gravity.TOP | Gravity.LEFT);
        titleSlot.addView(title, new FrameLayout.LayoutParams(
                FrameLayout.LayoutParams.MATCH_PARENT, FrameLayout.LayoutParams.MATCH_PARENT));
        ImageView titleLogo = folderTitleLogoView();
        titleLogo.setVisibility(View.GONE);
        prepareTitleLogoFallback(titleLogo, title);
        titleSlot.addView(titleLogo, new FrameLayout.LayoutParams(dp(380), -1, Gravity.LEFT));
        int titleSlotWidth = Math.max(dp(380),
                getResources().getDisplayMetrics().widthPixels - editorialLeftInset - dp(16));
        LinearLayout.LayoutParams titleParams = new LinearLayout.LayoutParams(titleSlotWidth, dp(76));
        titleParams.leftMargin = editorialLeftInset;
        editorial.addView(titleSlot, titleParams);
        boolean freeboxVideo = FILE_VIDEO_RESUME_SOURCE.equals(program.sourcePackage);
        if (!FREEBOX_FOLDER_SOURCE.equals(program.sourcePackage) && !freeboxVideo) {
            loadHomeCategoryHeroTitleLogo(category, displayTitle, item, program, titleLogo);
        }

        TextView metadata = text(freeboxVideo
                ? formatHeroRuntime(HomeMediaRules.playbackRuntimeMinutes(program.duration))
                : homeCategoryHeroMetadata(category, program, item), 15, Color.WHITE);
        metadata.setTag("home_category_hero_metadata");
        metadata.setTranslationY(dp(5));
        metadata.setAlpha(.82f);
        metadata.setSingleLine(true);
        metadata.setEllipsize(TextUtils.TruncateAt.END);
        LinearLayout.LayoutParams metadataParams = new LinearLayout.LayoutParams(-1, dp(30));
        metadataParams.topMargin = dp(5);
        metadataParams.leftMargin = editorialLeftInset;
        editorial.addView(metadata, metadataParams);

        TextView credits = text("", 13, Color.WHITE);
        credits.setTag("home_category_hero_credits");
        credits.setAlpha(.84f);
        credits.setMaxLines(2);
        credits.setEllipsize(TextUtils.TruncateAt.END);
        credits.setVisibility(View.GONE);
        LinearLayout.LayoutParams creditsParams = new LinearLayout.LayoutParams(-1, dp(36));
        creditsParams.leftMargin = editorialLeftInset;
        editorial.addView(credits, creditsParams);
        if (!freeboxVideo && !FREEBOX_FOLDER_SOURCE.equals(program.sourcePackage)) {
            applyProviderHeroCredits(credits, item);
        }

        TextView synopsis = text(freeboxVideo ? ""
                : homeCategoryHeroSynopsis(category, program, item), 15, Color.WHITE);
        synopsis.setTag("home_category_hero_synopsis");
        synopsis.setAlpha(.90f);
        synopsis.setMaxLines(8);
        synopsis.setEllipsize(TextUtils.TruncateAt.END);
        int synopsisWidth = Math.round((editorialParams.width - editorial.getPaddingRight()
                - editorialLeftInset) * .70f);
        LinearLayout.LayoutParams synopsisParams = new LinearLayout.LayoutParams(
                synopsisWidth, dp(150));
        synopsisParams.leftMargin = editorialLeftInset;
        if ("series".equals(category) && !FREEBOX_FOLDER_SOURCE.equals(program.sourcePackage)) {
            addSeriesSynopsisWithStatus(editorial, synopsis, synopsisParams, item);
        } else editorial.addView(synopsis, synopsisParams);
        if (!freeboxVideo) useMediumSynopsisWhenClipped(synopsis, heroMediumSynopsis(item));
        if (FREEBOX_FOLDER_SOURCE.equals(program.sourcePackage)) {
            Runnable refreshFolderMetadata = () -> loadHomeCategoryFolderMetadata(hero, program,
                    title, titleLogo, metadata, credits, synopsis, artwork);
            hero.setTag(CATEGORY_FOLDER_METADATA_REFRESH_TAG, refreshFolderMetadata);
            if (loadFolderMetadata) refreshFolderMetadata.run();
        } else if (freeboxVideo) {
            hero.setTag(CATEGORY_VIDEO_METADATA_REFRESH_TAG, (Runnable) () ->
                    loadHomeCategoryVideoFileMetadata(hero, program, title, titleLogo,
                            metadata, credits, synopsis));
            loadHomeCategoryVideoFileMetadata(hero, program, title, titleLogo,
                    metadata, credits, synopsis);
        } else if ("movies".equals(category) || "series".equals(category)) {
            loadExternalInfoMetadata(hero, category, program, item,
                    titleLogo, metadata, credits, synopsis);
            if (item != null && !item.optString("id", "").isEmpty()
                    && (heroGenres(item).isEmpty() || externalHeroRuntimeMinutes(item) <= 0
                    || TextUtils.isEmpty(synopsis.getText()) || credits.getVisibility() == View.GONE
                    || existingExternalPlaybackTitleLogo(item).isEmpty())) {
                Object infoRequest = hero.getTag(CATEGORY_VIDEO_METADATA_REQUEST_TAG);
                ExternalPlaybackStore.enrichProviderMetadata(this, item.optString("id"), () -> {
                    JSONObject refreshed = ExternalPlaybackStore.get(this, item.optString("id"));
                    runOnUiThread(() -> {
                        if (!hero.isAttachedToWindow() || !refreshed.has("id")
                                || hero.getTag(CATEGORY_VIDEO_METADATA_REQUEST_TAG) != infoRequest) return;
                        metadata.setText(homeCategoryHeroMetadata(category, program, refreshed));
                        applyProviderHeroCredits(credits, refreshed);
                        String refreshedSynopsis = homeCategoryHeroSynopsis(category, program, refreshed);
                        if (!refreshedSynopsis.isEmpty()) synopsis.setText(refreshedSynopsis);
                        loadExternalInfoMetadata(hero, category, program, refreshed,
                                titleLogo, metadata, credits, synopsis);
                    });
                });
            }
        } else if (TextUtils.isEmpty(synopsis.getText())) {
            loadContinueWatchingHeroSynopsis(synopsis, program);
        }
        editorial.addView(new View(this), new LinearLayout.LayoutParams(-1, 0, 1f));

        hero.setContentDescription(displayTitle);
    }

    /** Shares the folder Hero's rendering with the native IPTV catalogue. */
    public static ImageView folderHeroArtworkView(Context context) {
        HeroArtworkImageView artwork = new HeroArtworkImageView(context, false, HERO_HORIZONTAL_FADE_END_FRACTION, 5f);
        artwork.landscapeOnly = true;
        return artwork;
    }

    public static android.graphics.drawable.Drawable folderHeroEdgeFade(Context context, int backgroundColor) {
        int extension = Math.round(HOME_HERO_VERTICAL_EXTENSION_DP
                * context.getResources().getDisplayMetrics().density);
        return new HomeHeroEdgeFadeDrawable(backgroundColor, extension, false, 0);
    }

    private int heroArtworkWidth() {
        return Math.round(getResources().getDisplayMetrics().widthPixels
                * HERO_ARTWORK_WIDTH_FRACTION);
    }

    private int videosCategoryBottomPaddingPx() {
        return videosCategoryBottomPaddingPx(40);
    }

    private int videosCategoryBottomPaddingPx(int thumbnailVerticalOffsetDp) {
        boolean portrait = homeCategoryThumbnailPortrait("videos");
        int artworkHeightDp = Math.round((portrait ? 240 : continueWatchingTileHeightDp() + 4) * .75f);
        int episodeHeightDp = Math.round((continueWatchingTileHeightDp() + 4) * .6f);
        int tileHeightDp = portrait ? artworkHeightDp : Math.max(artworkHeightDp, episodeHeightDp + 28);
        int bottomPadding = Math.max(safeBottomInset(), dp(48)) - dp(thumbnailVerticalOffsetDp);
        int extraCardHeight = dp(tileHeightDp - artworkHeightDp);
        bottomPadding -= Math.min(extraCardHeight, Math.max(0, bottomPadding - safeBottomInset()));
        return bottomPadding;
    }

    private int videosCategoryHeroHeight(int pageHeightPx) {
        return videosCategoryHeroHeight(pageHeightPx, 40, 50);
    }

    private int videosCategoryHeroHeight(int pageHeightPx, int thumbnailVerticalOffsetDp,
                                         int thumbnailGapDp) {
        boolean portrait = homeCategoryThumbnailPortrait("videos");
        int artworkHeightDp = Math.round((portrait ? 240 : continueWatchingTileHeightDp() + 4) * .75f);
        int episodeHeightDp = Math.round((continueWatchingTileHeightDp() + 4) * .6f);
        int tileHeightDp = portrait ? artworkHeightDp : Math.max(artworkHeightDp, episodeHeightDp + 28);
        return Math.max(dp(190), pageHeightPx - videosCategoryBottomPaddingPx(thumbnailVerticalOffsetDp)
                - dp(tileHeightDp + 6) - dp(thumbnailGapDp));
    }

    private GradientDrawable cinematicHeroScrim() {
        return new GradientDrawable(GradientDrawable.Orientation.LEFT_RIGHT,
                new int[] { Color.BLACK, Color.BLACK, Color.argb(220, 0, 0, 0),
                        Color.argb(88, 0, 0, 0), Color.TRANSPARENT });
    }

