    private void loadHomeCategoryHeroArtwork(ImageView artwork, String category,
                                             JojoProgram program, JSONObject item) {
        homeVideosFileHeroArtworkViews.remove(artwork);
        // Restore this Hero's own artwork choice before consulting provider
        // or fallback artwork; the folder tile has a separate preference.
        String selected = "";
        if ("live".equals(category)) {
            selected = liveChannelArtwork(item, true);
        } else if (item != null) {
            selected = selectedExternalFavoriteHeroArtwork(item);
        } else if (FREEBOX_FOLDER_SOURCE.equals(program.sourcePackage)) {
            selected = smbFolderHeroArtwork(program.intentUri);
        }
        if (ExternalPlaybackStore.supportedUrl(selected)) {
            loadArtwork(artwork, selected);
            return;
        }
        if (item != null && "external-playback".equals(program.sourcePackage)
                && ("movies".equals(category) || "series".equals(category))) {
            String backdrop = firstExternalValue(item, "backdrop", "backdrop_url", "backdropUrl");
            if (ExternalPlaybackStore.supportedUrl(backdrop)) loadArtwork(artwork, backdrop);
            // The matching metadata request supplies the official backdrop.
            // Do not reuse a resume cache that may contain a portrait poster.
            return;
        }
        // Share the Home hero's provider/backdrop resolution order.
        loadContinueWatchingHeroArtwork(artwork, program);
    }

    /**
     * Folder cards are not playback records, so enrich their editorial hero once
     * from the same metadata source used by the folder detail page.  The current
     * card remains the identity: a late answer is ignored if focus moved on.
     */
    private void loadHomeCategoryFolderMetadata(FrameLayout hero, JojoProgram program,
                                                TextView title, ImageView titleLogo,
                                                TextView metadata, TextView credits,
                                                TextView synopsis,
                                                ImageView artwork) {
        final String key = program.intentUri == null || program.intentUri.isEmpty()
                ? program.title : program.intentUri;
        final String heroKey = "category_folder_hero:" + key + ":" + System.nanoTime();
        hero.setTag(CATEGORY_FOLDER_METADATA_REQUEST_TAG, heroKey);
        artworkLoadRequests.put(titleLogo, new Object());
        titleLogo.setTag(OFFICIAL_TITLE_LOGO_REQUEST_TAG, new Object());
        titleLogo.setImageDrawable(null);
        prepareTitleLogoFallback(titleLogo, title);
        setHomeHeroFallbackTitle(title, program.title);
        metadata.setText("");
        credits.setText("");
        credits.setVisibility(View.GONE);
        synopsis.setText("");
        FolderMetadata cached = folderHeroMetadataCache.get(key);
        JSONObject selected = selectedSmbFolderArtworkMetadata(key);
        if (cached != null && selected.optInt("tmdbId", 0) > 0
                && (cached.tmdbId != selected.optInt("tmdbId", 0)
                || !selected.optString("mediaType", "").equals(cached.tmdbMediaType))) cached = null;
        if (cached == null) cached = cachedFreeboxFolderMetadata(key);
        if (cached != null) {
            applyHomeCategoryFolderMetadata(hero, heroKey, key, cached, title, titleLogo,
                    metadata, credits, synopsis, artwork);
            loadMissingFolderHeroTitleLogo(hero, heroKey, key, cached, title, titleLogo);
            if (cached.genres != null && !cached.genres.isEmpty()
                    && cached.date != null && !cached.date.isEmpty()
                    && cached.runtime != null && !cached.runtime.isEmpty()
                    && cached.overview != null && !cached.overview.isEmpty()
                    && cached.logo != null && !cached.logo.isEmpty()
                    && cached.creditsLoaded) return;
        }
        new Thread(() -> {
            FolderMetadata details = findFreeboxFolderMetadata(program.intentUri, program.title);
            runOnUiThread(() -> {
                if (!heroKey.equals(hero.getTag(CATEGORY_FOLDER_METADATA_REQUEST_TAG))) return;
                if (details == null) {
                    loadOfficialProgrammeTitleLogo(null, program.title, title, titleLogo);
                    return;
                }
                folderHeroMetadataCache.put(key, details);
                saveSmbFolderMetadata(key, details);
                applyHomeCategoryFolderMetadata(hero, heroKey, key, details, title, titleLogo,
                        metadata, credits, synopsis, artwork);
                loadMissingFolderHeroTitleLogo(hero, heroKey, key, details, title, titleLogo);
            });
        }, "JojoHomeCategoryFolderHero").start();
    }

    private void loadMissingFolderHeroTitleLogo(FrameLayout hero, String heroKey, String folderPath,
                                                FolderMetadata details, TextView title,
                                                ImageView titleLogo) {
        if (details == null || (details.logo != null && !details.logo.isEmpty()) || details.tmdbId <= 0
                || details.tmdbMediaType == null || details.tmdbMediaType.isEmpty()) return;
        Object lookup = beginTitleLogoLookup(titleLogo);
        new Thread(() -> {
            String logo = findFolderTitleLogoFallback(details);
            runOnUiThread(() -> {
                if (!logo.isEmpty() && heroKey.equals(hero.getTag(CATEGORY_FOLDER_METADATA_REQUEST_TAG))) {
                    details.logo = logo;
                    saveSmbFolderMetadata(folderPath, details);
                    rememberTitleLogoFallback(titleLogo, title);
                    loadArtwork(titleLogo, logo);
                }
                finishTitleLogoLookup(titleLogo, lookup);
            });
        }, "JojoHomeCategoryHeroTitleLogo").start();
    }

    private void applyHomeCategoryFolderMetadata(FrameLayout hero, String heroKey, String folderPath,
                                                   FolderMetadata details, TextView title,
                                                  ImageView titleLogo, TextView metadata,
                                                  TextView credits, TextView synopsis,
                                                  ImageView artwork) {
        if (!heroKey.equals(hero.getTag(CATEGORY_FOLDER_METADATA_REQUEST_TAG)) || details == null) return;
        String detailTitle = details.title == null ? "" : details.title;
        String detailDate = details.date == null ? "" : details.date;
        String detailGenres = details.genres == null ? "" : details.genres;
        String detailRuntime = details.runtime == null ? "" : details.runtime;
        String detailOverview = details.overview == null ? "" : details.overview;
        String detailBackdrop = details.backdrop == null ? "" : details.backdrop;
        String detailLogo = details.logo == null ? "" : details.logo;
        if (!detailTitle.isEmpty()) setHomeHeroFallbackTitle(title, detailTitle);
        ArrayList<String> values = new ArrayList<>();
        if (!detailGenres.isEmpty()) values.add(detailGenres);
        if (!detailDate.isEmpty()) values.add(detailDate);
        if (!detailRuntime.isEmpty()) values.add(detailRuntime);
        metadata.setText(TextUtils.join("  •  ", values));
        String creditText = formatHomeCategoryHeroCredits(details);
        credits.setText(creditText);
        credits.setVisibility(creditText.isEmpty() ? View.GONE : View.VISIBLE);
        if (!detailOverview.isEmpty()) synopsis.setText(shortenContinueWatchingHeroSynopsis(detailOverview));
        if (!detailBackdrop.isEmpty()) loadArtwork(artwork, detailBackdrop);
        String selectedHeroArtwork = smbFolderHeroArtwork(folderPath);
        if (selectedHeroArtwork != null && !selectedHeroArtwork.isEmpty()) loadArtwork(artwork, selectedHeroArtwork);
        if (!detailLogo.isEmpty()) {
            rememberTitleLogoFallback(titleLogo, title);
            loadArtwork(titleLogo, detailLogo);
        }
        loadOfficialProgrammeTitleLogo(details, detailTitle, title, titleLogo);
    }

    private void loadHomeCategoryVideoFileMetadata(FrameLayout hero, JojoProgram program,
                                                    TextView title, ImageView titleLogo,
                                                    TextView metadata, TextView credits,
                                                    TextView synopsis) {
        artworkLoadRequests.put(titleLogo, new Object());
        titleLogo.setTag(OFFICIAL_TITLE_LOGO_REQUEST_TAG, new Object());
        titleLogo.setImageDrawable(null);
        prepareTitleLogoFallback(titleLogo, title);
        setHomeHeroFallbackTitle(title, homeCategoryHeroTitle("videos", program));
        synopsis.setText("");
        credits.setText("");
        credits.setVisibility(View.GONE);
        metadata.setText(formatHeroRuntime(HomeMediaRules.playbackRuntimeMinutes(program.duration)));
        String path = program.intentUri == null ? "" : program.intentUri;
        String heroKey = "category_video_hero:" + path + ":" + System.nanoTime();
        hero.setTag(CATEGORY_VIDEO_METADATA_REQUEST_TAG, heroKey);
        hero.setTag(CATEGORY_VIDEO_METADATA_REFRESH_TAG, (Runnable) () ->
                loadHomeCategoryVideoFileMetadata(hero, program, title, titleLogo, metadata, credits, synopsis));
        String selectedHero = homeVideosFileHeroArtwork(path, program.title);
        String selectedThumbnail = homeVideosFileArtwork(path, program.title);
        JSONObject selectedMetadata = selectedFreeboxVideoArtworkMetadata(program, selectedHero,
                selectedThumbnail);
        String chosenArtwork = firstExternalValue(selectedMetadata, "artworkUrl", "poster", "backdrop");
        final String artworkIdentity = !chosenArtwork.isEmpty() ? chosenArtwork
                : selectedThumbnail.isEmpty() ? selectedHero : selectedThumbnail;
        int selectedTmdbId = selectedMetadata.optInt("tmdbId", 0);
        String selectedTmdbType = selectedMetadata.optString("mediaType", "");
        FolderMetadata savedPlayerDetails = cachedHomeVideoPlayerMetadata(program, selectedMetadata);
        String programmeLogo = OfficialProgrammeLogoResolver.cached(this,
                videoArtworkSearchTitle(program.title, null), selectedTmdbId, selectedTmdbType);
        if (!programmeLogo.isEmpty()) {
            if (savedPlayerDetails == null) {
                savedPlayerDetails = new FolderMetadata();
                savedPlayerDetails.overview = savedPlayerDetails.genres = savedPlayerDetails.director = "";
                savedPlayerDetails.date = savedPlayerDetails.runtime = "";
            }
            if (!isUsableTitleLogoUrl(savedPlayerDetails.logo)) savedPlayerDetails.logo = programmeLogo;
        }
        final FolderMetadata playerDetails = savedPlayerDetails;
        if (playerDetails != null) applyHomeCategoryVideoFileMetadata(playerDetails, program.duration,
                path, title, titleLogo, metadata, credits, synopsis);
        String cacheKey = "freebox_video_hero_metadata_" + Integer.toUnsignedString(path.hashCode(), 16);
        final FolderMetadata[] cachedDetails = new FolderMetadata[1];
        try {
            JSONObject cached = new JSONObject(homePrefs().getString(cacheKey, "{}"));
            if (cached.optInt("identityPolicyVersion", 0) == FREEBOX_VIDEO_METADATA_POLICY_VERSION
                    && program.title.equals(cached.optString("sourceTitle", ""))
                    && artworkIdentity.equals(cached.optString("artworkIdentity", ""))
                    && "fr-FR".equals(cached.optString("metadataLanguage", ""))) {
                FolderMetadata saved = new FolderMetadata();
                saved.tmdbId = cached.optInt("tmdbId", 0);
                saved.tmdbMediaType = cached.optString("mediaType", "");
                saved.title = cached.optString("title", "");
                saved.originalLanguage = cached.optString("originalLanguage", "");
                saved.genres = cached.optString("genres", "");
                saved.date = cached.optString("date", "");
                saved.overview = cached.optString("overview", "");
                saved.runtime = cached.optString("runtime", "");
                saved.logo = cached.optInt("titleLogoPolicyVersion", 0) == TITLE_LOGO_POLICY_VERSION
                        ? cached.optString("logo", "") : "";
                if (!isUsableTitleLogoUrl(saved.logo)) saved.logo = "";
                saved.director = cached.optString("director", "");
                saved.creditsLoaded = cached.optBoolean("creditsLoaded", false) && HomeMediaRules.currentTmdbPeoplePolicy(
                        saved.tmdbMediaType, cached.optInt("peoplePolicyVersion", 0));
                JSONArray savedArtworkPaths = cached.optJSONArray("artworkPaths");
                if (savedArtworkPaths != null) for (int i = 0; i < savedArtworkPaths.length(); i++) {
                    saved.artworkPaths.add(savedArtworkPaths.optString(i, ""));
                }
                restoreFolderCast(saved, cached);
                if (saved.tmdbId > 0 && (selectedTmdbId <= 0 || (saved.tmdbId == selectedTmdbId
                        && selectedTmdbType.equals(saved.tmdbMediaType)))
                        && HomeMediaRules.freeboxMetadataMatches(saved.tmdbMediaType,
                        HomeMediaRules.titleYear(program.title), saved.date,
                        program.duration > 0 ? Math.round(program.duration / 60_000f) : 0,
                        HomeMediaRules.heroRuntimeMinutes(saved.runtime), !artworkIdentity.isEmpty(),
                        HomeMediaRules.artworkMatches(artworkIdentity, saved.artworkPaths), selectedTmdbId > 0)) {
                    cachedDetails[0] = saved;
                    applyHomeCategoryVideoFileMetadata(mergeHomeVideoHeroMetadata(saved, playerDetails), program.duration,
                            path, title, titleLogo, metadata, credits, synopsis);
                }
            }
        } catch (Exception ignored) { }
        if (playerDetails != null && isUsableTitleLogoUrl(playerDetails.logo) && !playerDetails.overview.isEmpty()
                && !playerDetails.genres.isEmpty() && !playerDetails.director.isEmpty()) return;
        if (cachedDetails[0] != null && HomeMediaRules.playbackRuntimeMinutes(program.duration) > 0
                && cachedDetails[0].genres != null && !cachedDetails[0].genres.isEmpty()
                && cachedDetails[0].date != null && !cachedDetails[0].date.isEmpty()
                && cachedDetails[0].overview != null && !cachedDetails[0].overview.isEmpty()
                && cachedDetails[0].logo != null && !cachedDetails[0].logo.isEmpty()
                && cachedDetails[0].creditsLoaded) return;
        final String selectedHeroArtwork = selectedHero;
        new Thread(() -> {
            long duration = program.duration;
            if (duration <= 0 && path.startsWith("smb://")) try {
                String user = homePrefs().getString("smb_user", "");
                String password = homePrefs().getString("smb_password", "");
                duration = cachedSmbVideoDurationMs(new jcifs.smb.SmbFile(path, smbContext(user, password)));
            } catch (Exception ignored) { }
            final long fileDuration = duration;
            FolderMetadata details = findFreeboxVideoFileMetadata(program, fileDuration,
                    selectedHeroArtwork, artworkIdentity);
            final FolderMetadata fallback = cachedDetails[0] != null
                    && HomeMediaRules.freeboxMetadataMatches(cachedDetails[0].tmdbMediaType,
                    HomeMediaRules.titleYear(program.title), cachedDetails[0].date,
                    fileDuration > 0 ? Math.round(fileDuration / 60_000f) : 0,
                    HomeMediaRules.heroRuntimeMinutes(cachedDetails[0].runtime), !artworkIdentity.isEmpty(),
                    HomeMediaRules.artworkMatches(artworkIdentity, cachedDetails[0].artworkPaths), false)
                    ? cachedDetails[0] : null;
            if (details != null) try {
                homePrefs().edit().putString(cacheKey, new JSONObject()
                        .put("identityPolicyVersion", FREEBOX_VIDEO_METADATA_POLICY_VERSION)
                        .put("sourceTitle", program.title)
                        .put("artworkIdentity", artworkIdentity)
                        .put("artworkPaths", new JSONArray(details.artworkPaths))
                        .put("tmdbId", details.tmdbId)
                        .put("mediaType", details.tmdbMediaType)
                        .put("title", details.title)
                        .put("originalLanguage", details.originalLanguage == null ? "" : details.originalLanguage)
                        .put("genres", details.genres == null ? "" : details.genres)
                        .put("date", details.date == null ? "" : details.date)
                        .put("overview", details.overview == null ? "" : details.overview)
                        .put("metadataLanguage", "fr-FR")
                        .put("runtime", details.runtime == null ? "" : details.runtime)
                        .put("logo", details.logo == null ? "" : details.logo)
                        .put("titleLogoPolicyVersion", TITLE_LOGO_POLICY_VERSION)
                        .put("actors", folderCastNames(details.cast))
                        .put("castDetails", folderCastDetails(details.cast))
                        .put("peoplePolicyVersion", HomeMediaRules.TMDB_PEOPLE_POLICY_VERSION)
                        .put("director", details.director == null ? "" : details.director)
                        .put("creditsLoaded", details.creditsLoaded).toString()).apply();
            } catch (Exception ignored) { }
            if (details == null && fallback == null) homePrefs().edit().remove(cacheKey).apply();
            final FolderMetadata displayDetails = mergeHomeVideoHeroMetadata(
                    details != null ? details : fallback, playerDetails);
            runOnUiThread(() -> {
                if (!heroKey.equals(hero.getTag(CATEGORY_VIDEO_METADATA_REQUEST_TAG))) return;
                if (displayDetails != null) applyHomeCategoryVideoFileMetadata(displayDetails, fileDuration,
                        path, title, titleLogo, metadata, credits, synopsis);
                else {
                    setHomeHeroFallbackTitle(title, homeCategoryHeroTitle("videos", program));
                    artworkLoadRequests.put(titleLogo, new Object());
                    titleLogo.setImageDrawable(null);
                    prepareTitleLogoFallback(titleLogo, title);
                    synopsis.setText("");
                    credits.setText("");
                    credits.setVisibility(View.GONE);
                    metadata.setText(formatHeroRuntime(HomeMediaRules.playbackRuntimeMinutes(fileDuration)));
                }
                if (displayDetails == null || displayDetails.tmdbId <= 0) loadOfficialProgrammeTitleLogo(
                        displayDetails, videoArtworkSearchTitle(program.title, null), title, titleLogo);
            });
        }, "JojoHomeCategoryVideoMetadata").start();
    }

    private boolean refreshVisibleHomeVideoHeroMetadata(View view) {
        if (view == null) return false;
        Object request = view.getTag(CATEGORY_VIDEO_METADATA_REQUEST_TAG);
        Object refresh = view.getTag(CATEGORY_VIDEO_METADATA_REFRESH_TAG);
        if (request instanceof String && ((String) request).startsWith("category_video_hero:")
                && refresh instanceof Runnable) {
            ((Runnable) refresh).run();
            return true;
        }
        if (view instanceof ViewGroup) for (int i = 0; i < ((ViewGroup) view).getChildCount(); i++) {
            if (refreshVisibleHomeVideoHeroMetadata(((ViewGroup) view).getChildAt(i))) return true;
        }
        return false;
    }

    private FolderMetadata cachedHomeVideoPlayerMetadata(JojoProgram program, JSONObject selectedMetadata) {
        String path = program.intentUri == null ? "" : program.intentUri.replaceFirst("^file://", "");
        if (path.isEmpty()) return null;
        try {
            JSONObject saved = new JSONObject(homePrefs().getString("video_player_metadata_"
                    + Integer.toUnsignedString(path.hashCode(), 16), "{}"));
            if (!path.equals(saved.optString("sourcePath", ""))
                    || !homePrefs().getString(freeboxResumeSignatureKey(path), "")
                    .equals(saved.optString("fileSignature", ""))) return null;
            // A newer manual TMDB choice must supersede the previous player session.
            int selectedId = selectedMetadata.optInt("tmdbId", 0);
            if (selectedId > 0 && (selectedId != saved.optInt("tmdbId", 0)
                    || !selectedMetadata.optString("mediaType", "").equals(saved.optString("mediaType", ""))
                    || selectedMetadata.optLong("selectedAt", 0L) > saved.optLong("playbackStartedAt", 0L))) return null;
            FolderMetadata details = new FolderMetadata();
            details.tmdbId = saved.optInt("tmdbId", 0);
            details.tmdbMediaType = saved.optString("mediaType", "");
            details.logo = saved.optInt("titleLogoPolicyVersion", 0) == TITLE_LOGO_POLICY_VERSION
                    ? saved.optString("logo", "").trim() : "";
            if (!isUsableTitleLogoUrl(details.logo)) details.logo = "";
            details.overview = saved.optString("overview", "").trim();
            details.genres = TextUtils.join(", ", jsonList(saved.optJSONArray("genres")));
            details.director = TextUtils.join(", ", jsonList(saved.optJSONArray("director")));
            details.date = saved.optString("year", "");
            details.runtime = formatHeroRuntime(saved.optInt("runtimeMinutes", 0));
            restoreFolderCast(details, saved);
            return details.logo.isEmpty() && details.overview.isEmpty() && details.genres.isEmpty() && details.director.isEmpty()
                    ? null : details;
        } catch (Exception ignored) { return null; }
    }

    private FolderMetadata mergeHomeVideoHeroMetadata(FolderMetadata details, FolderMetadata playerDetails) {
        if (playerDetails == null) return details;
        if (details == null) return playerDetails;
        FolderMetadata merged = new FolderMetadata();
        merged.tmdbId = details.tmdbId;
        merged.tmdbMediaType = details.tmdbMediaType;
        merged.title = details.title;
        merged.backdrop = details.backdrop;
        merged.logo = isUsableTitleLogoUrl(details.logo) ? details.logo : playerDetails.logo;
        merged.genres = playerDetails.genres.isEmpty() ? details.genres : playerDetails.genres;
        merged.date = playerDetails.date.isEmpty() ? details.date : playerDetails.date;
        merged.runtime = playerDetails.runtime.isEmpty() ? details.runtime : playerDetails.runtime;
        merged.overview = playerDetails.overview.isEmpty() ? details.overview : playerDetails.overview;
        merged.director = playerDetails.director.isEmpty() ? details.director : playerDetails.director;
        merged.cast.addAll(hasPresenterCredits(details) || playerDetails.cast.isEmpty() ? details.cast : playerDetails.cast);
        return merged;
    }

    private void applyHomeCategoryVideoFileMetadata(FolderMetadata details, long duration,
                                                    String path, TextView title, ImageView titleLogo,
                                                    TextView metadata, TextView credits,
                                                    TextView synopsis) {
        String sourcePath = path.replaceFirst("^file://", "");
        if (details.tmdbId > 0) folderHeroMetadataCache.put("file|" + sourcePath + "|"
                + homePrefs().getString(freeboxResumeSignatureKey(sourcePath), ""), details);
        if (details.title != null && !details.title.isEmpty()) {
            setHomeHeroFallbackTitle(title, details.title);
        }
        if (isUsableTitleLogoUrl(details.logo)) {
            rememberTitleLogoFallback(titleLogo, title);
            loadArtwork(titleLogo, details.logo);
        }
        titleLogo.setTag(OFFICIAL_TITLE_LOGO_REQUEST_TAG, new Object());
        if (details.tmdbId > 0) loadOfficialProgrammeTitleLogo(details, title.getText().toString(), title, titleLogo);
        ArrayList<String> values = new ArrayList<>();
        if (details.genres != null && !details.genres.isEmpty()) values.add(details.genres);
        if (details.date != null && !details.date.isEmpty()) values.add(details.date);
        int runtimeMinutes = HomeMediaRules.playbackRuntimeMinutes(duration);
        if (runtimeMinutes > 0) values.add(formatHeroRuntime(runtimeMinutes));
        else if (details.runtime != null && !details.runtime.isEmpty()) values.add(details.runtime);
        metadata.setText(joinWithBullet(values));
        String creditText = formatHomeCategoryHeroCredits(details);
        credits.setText(creditText);
        credits.setVisibility(creditText.isEmpty() ? View.GONE : View.VISIBLE);
        synopsis.setText(details.overview == null ? ""
                : shortenContinueWatchingHeroSynopsis(details.overview));
    }

    private JSONArray folderCastNames(List<FolderCastMember> cast) {
        JSONArray names = new JSONArray();
        if (cast != null) for (FolderCastMember member : cast) {
            if (member != null && member.name != null && !member.name.trim().isEmpty()) {
                names.put(member.name.trim());
            }
        }
        return names;
    }

    private void addSeriesSynopsisWithStatus(LinearLayout editorial, TextView synopsis,
            LinearLayout.LayoutParams params, JSONObject item) {
        LinearLayout block = new LinearLayout(this);
        block.setOrientation(LinearLayout.VERTICAL);
        block.addView(synopsis, new LinearLayout.LayoutParams(-1, -2));
        TextView badge = text("", 14, Color.WHITE);
        badge.setTag("home_category_hero_series_status");
        badge.setSingleLine(true);
        badge.setIncludeFontPadding(false);
        badge.setGravity(Gravity.CENTER);
        badge.setPadding(dp(8), dp(3), dp(8), dp(3));
        GradientDrawable background = new GradientDrawable();
        background.setColor(withAlpha(Color.BLACK, 32));
        background.setCornerRadius(dp(6));
        background.setStroke(dp(1), withAlpha(Color.WHITE, 100));
        badge.setBackground(background);
        LinearLayout.LayoutParams badgeParams = new LinearLayout.LayoutParams(-2, dp(26));
        badgeParams.topMargin = dp(8);
        block.addView(badge, badgeParams);
        editorial.addView(block, params);
        String status = providerSeriesStatusLabel(item);
        updateSeriesStatusBadge(badge, "TERMINÉ".equals(status) ? status : "", providerSeriesSeasonCount(item));
    }

    private String providerSeriesStatusLabel(JSONObject item) {
        return HomeMediaRules.seriesStatusLabel(firstExternalValue(item, "seriesStatus", "series_status", "status"),
                item != null && item.optBoolean("in_production", item.optBoolean("inProduction")));
    }

    private int providerSeriesSeasonCount(JSONObject item) {
        if (item == null) return 0;
        int count = 0;
        for (String key : new String[] { "number_of_seasons", "seasonCount", "season_count", "seasons_count", "seasons" })
            count = Math.max(count, item.optInt(key));
        JSONArray seasons = item.optJSONArray("seasons");
        java.util.Set<Integer> numbers = new java.util.HashSet<>();
        if (seasons != null) for (int index = 0; index < seasons.length(); index++) {
            JSONObject season = seasons.optJSONObject(index);
            if (season == null) continue;
            int number = season.optInt("number", season.optInt("season_number", index + 1));
            if (number > 0) numbers.add(number);
        }
        return Math.max(count, numbers.size());
    }

    private void updateSeriesStatusBadge(TextView badge, String label, int seasonCount) {
        if (badge == null) return;
        String value = label == null ? "" : label;
        android.text.SpannableString text = new android.text.SpannableString(HomeMediaRules.seriesStatusBadgeText(value, seasonCount));
        int separator = text.toString().indexOf('│');
        if (separator >= 0) {
            text.setSpan(new android.text.style.ForegroundColorSpan(withAlpha(Color.WHITE, 140)),
                    separator, separator + 1, android.text.Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);
        }
        badge.setText(text);
        badge.setContentDescription(text.toString());
        badge.setVisibility(value.isEmpty() ? View.GONE : View.VISIBLE);
        TextView synopsis = (TextView) ((LinearLayout) badge.getParent()).getChildAt(0);
        int availableHeight = dp(150 - 26 - 8) - synopsis.getCompoundPaddingTop() - synopsis.getCompoundPaddingBottom();
        synopsis.setMaxLines(value.isEmpty() ? 8 : Math.max(1, Math.min(8, availableHeight / Math.max(1, synopsis.getLineHeight()))));
    }

    private JSONObject seriesBroadcastSeason(JSONObject series) {
        JSONArray seasons = series.optJSONArray("seasons");
        if (seasons == null) return null;
        JSONObject lastEpisode = series.optJSONObject("last_episode_to_air");
        int lastAiredSeason = lastEpisode == null ? 0 : lastEpisode.optInt("season_number");
        JSONObject started = null, upcoming = null;
        java.time.LocalDate today = java.time.LocalDate.now();
        for (int index = 0; index < seasons.length(); index++) {
            JSONObject season = seasons.optJSONObject(index);
            if (season == null || season.optInt("season_number") <= 0) continue;
            int number = season.optInt("season_number");
            java.time.LocalDate date = HomeMediaRules.episodeAirDate(season.optString("air_date"));
            if (number == lastAiredSeason || (date != null && !date.isAfter(today))) {
                if (started == null || number > started.optInt("season_number")) started = season;
            } else if (upcoming == null || number < upcoming.optInt("season_number")) upcoming = season;
        }
        return started == null ? upcoming : started;
    }

    private void loadSeriesBroadcastStatus(FrameLayout hero, FolderMetadata details, int seasonCount) {
        TextView badge = hero.findViewWithTag("home_category_hero_series_status");
        if (badge == null || details == null || details.tmdbId <= 0 || !"tv".equals(details.tmdbMediaType)) return;
        Object request = hero.getTag(CATEGORY_VIDEO_METADATA_REQUEST_TAG);
        badge.setTag(CATEGORY_VIDEO_METADATA_REQUEST_TAG, details);
        android.content.SharedPreferences cache = getSharedPreferences("home_hero_editorial_cache", MODE_PRIVATE);
        // The series header describes the latest started season, independently
        // of the selected episode season and of the show's renewal status.
        String key = "iptv_series_broadcast_calendar_" + details.tmdbId;
        java.util.function.Consumer<JSONObject> apply = calendar -> {
            if (!hero.isAttachedToWindow() || hero.getTag(CATEGORY_VIDEO_METADATA_REQUEST_TAG) != request
                    || badge.getTag(CATEGORY_VIDEO_METADATA_REQUEST_TAG) != details) return;
            details.seriesBroadcastCalendar = calendar;
            if (calendar != null) {
                details.seriesStatus = seriesSeasonCalendarStatus(calendar);
                details.seasonCount = Math.max(details.seasonCount, calendar.optInt("seasonCount"));
            } else if (!"TERMINÉ".equals(details.seriesStatus)) details.seriesStatus = "";
            updateSeriesStatusBadge(badge, details.seriesStatus, Math.max(seasonCount, details.seasonCount));
        };
        apply.accept(details.seriesBroadcastCalendar);
        try {
            String cached = cache.getString(key, "");
            if (!cached.isEmpty()) apply.accept(new JSONObject(cached));
        } catch (org.json.JSONException ignored) { }
        new Thread(() -> {
            try {
                String query = "?api_key=" + java.net.URLEncoder.encode(BuildConfig.TMDB_API_KEY, "UTF-8") + "&language=fr-FR";
                String seriesUrl = "https://api.themoviedb.org/3/tv/" + details.tmdbId;
                JSONObject series = fetchJson(seriesUrl + query);
                JSONObject season = seriesBroadcastSeason(series);
                if (season == null) return;
                JSONObject calendar = fetchJson(seriesUrl + "/season/" + season.optInt("season_number") + query);
                // Keep the official count: missing dates must not imply completion.
                calendar.put("episode_count", season.optInt("episode_count"));
                calendar.put("seasonCount", series.optInt("number_of_seasons"));
                cache.edit().putString(key, calendar.toString()).apply();
                runOnUiThread(() -> apply.accept(calendar));
            } catch (Exception error) {
                android.util.Log.w("JojoHomeSeriesEpisodes", "Series broadcast calendar unavailable: " + error.getClass().getSimpleName());
            }
        }, "JojoHomeSeriesCalendar").start();
    }

    private void loadExternalInfoMetadata(FrameLayout hero, String category, JojoProgram program,
                                           JSONObject item, ImageView titleLogo, TextView metadata,
                                           TextView credits, TextView synopsis) {
        loadExternalInfoMetadata(hero, category, program, item, titleLogo, metadata, credits, synopsis, null);
    }

    private void loadExternalInfoMetadata(FrameLayout hero, String category, JojoProgram program,
                                           JSONObject item, ImageView titleLogo, TextView metadata,
                                           TextView credits, TextView synopsis,
                                           java.util.function.Consumer<FolderMetadata> completion) {
        if (program == null || !("movies".equals(category) || "series".equals(category))
                || BuildConfig.TMDB_API_KEY == null || BuildConfig.TMDB_API_KEY.trim().isEmpty()) return;
        String mediaType = "series".equals(category) ? "tv" : "movie";
        List<String> queries = externalInfoSearchTitles(item, program.title, "series".equals(category));
        String expectedYear = firstExternalValue(item, "year", "release_year", "releaseYear");
        java.util.regex.Matcher year = java.util.regex.Pattern.compile("(?:19|20)\\d{2}")
                .matcher(expectedYear.isEmpty() ? program.title : expectedYear);
        final String yearHint = year.find() ? year.group() : "";
        int knownId = item == null ? 0 : item.optInt("tmdbId", item.optInt("tmdb_id", 0));
        if (knownId <= 0 && queries.isEmpty()) return;
        String identity = mediaType + "|" + knownId + "|" + TextUtils.join("|", queries) + "|" + yearHint;
        String cacheKey = "info-fr-v3|" + identity;
        Object request = new Object();
        hero.setTag(CATEGORY_VIDEO_METADATA_REQUEST_TAG, request);
        java.util.function.Consumer<FolderMetadata> apply = details -> {
            if (details == null || !hero.isAttachedToWindow()
                    || hero.getTag(CATEGORY_VIDEO_METADATA_REQUEST_TAG) != request) return;
            ArrayList<String> values = new ArrayList<>();
            if (details.genres != null && !details.genres.isEmpty()) values.add(details.genres);
            else if (!heroGenres(item).isEmpty()) values.add(heroGenres(item));
            if (details.date != null && !details.date.isEmpty()) values.add(details.date);
            else if (!yearHint.isEmpty()) values.add(yearHint);
            int runtime = externalHeroRuntimeMinutes(item);
            if (runtime <= 0 && program.duration >= 60_000L)
                runtime = Math.max(1, Math.round(program.duration / 60_000f));
            if (runtime > 0) values.add(formatHeroRuntime(runtime));
            else if (details.runtime != null && !details.runtime.isEmpty()) values.add(details.runtime);
            metadata.setText(joinWithBullet(values));
            List<String> actors = parseHeroCreditNames(firstExternalValue(item,
                    "actors", "cast", "actor", "stars", "castMembers", "cast_members"));
            if (hasPresenterCredits(details) || actors.isEmpty() || containsHebrew(TextUtils.join(", ", actors))) {
                actors = new ArrayList<>();
                for (FolderCastMember member : details.cast) actors.add(member.name);
            }
            String director = TextUtils.join(", ", parseHeroCreditNames(
                    firstExternalValue(item, "director", "directors")));
            if (director.isEmpty() || containsHebrew(director)) director = details.director;
            String creditText = formatHomeHeroCredits(actors, director, hasPresenterCredits(details));
            credits.setText(creditText);
            credits.setVisibility(creditText.isEmpty() ? View.GONE : View.VISIBLE);
            if ((TextUtils.isEmpty(synopsis.getText()) || containsHebrew(synopsis.getText().toString()))
                    && details.overview != null && !details.overview.isEmpty())
                synopsis.setText(shortenContinueWatchingHeroSynopsis(details.overview));
            if ("series".equals(category)) {
                loadSeriesBroadcastStatus(hero, details, Math.max(details.seasonCount, providerSeriesSeasonCount(item)));
            }
            if (isUsableTitleLogoUrl(details.logo) && explicitTitleLogoUrl(item).isEmpty())
                loadArtwork(titleLogo, details.logo);
            ImageView categoryArtwork = hero.findViewWithTag("home_category_hero_artwork");
            // Use the same identified movie/series for the landscape background
            // and its editorial metadata, while preserving a manual Hero choice.
            if (categoryArtwork != null && selectedExternalFavoriteHeroArtwork(item).isEmpty()
                    && ExternalPlaybackStore.supportedUrl(details.backdrop)) {
                loadArtwork(categoryArtwork, details.backdrop);
            }
            if (completion != null) completion.accept(details);
        };
        FolderMetadata cached = folderHeroMetadataCache.get(cacheKey);
        if (cached != null) {
            hero.post(() -> apply.accept(cached));
            if (!TextUtils.isEmpty(cached.genres) && !TextUtils.isEmpty(cached.runtime) && cached.creditsLoaded) return;
        }
        new Thread(() -> {
            try {
                int id = knownId;
                if (id <= 0) id = findExternalInfoTmdbId(queries, mediaType, yearHint);
                if (id <= 0) return;
                FolderMetadata details = fetchFreeboxTmdbMetadata(id, mediaType, program.title);
                folderHeroMetadataCache.put(cacheKey, details);
                if (ExternalPlaybackStore.supportedUrl(details.backdrop)) homePrefs().edit()
                        .putString("home_suggestion_landscape_v1|" + identity, details.backdrop).apply();
                runOnUiThread(() -> hero.post(() -> apply.accept(details)));
            } catch (Exception error) {
                android.util.Log.w("JojoHomeInfoMetadata", "Metadata unavailable: " + error.getClass().getSimpleName());
            }
        }, "JojoHomeInfoMetadata").start();
    }

    private List<String> externalInfoSearchTitles(JSONObject item, String fallbackTitle, boolean series) {
        java.util.LinkedHashSet<String> queries = new java.util.LinkedHashSet<>();
        for (String field : new String[]{"originalTitle", "original_title", "original_name", "providerTitle", "title", ""}) {
            String raw = field.isEmpty() ? fallbackTitle : firstExternalValue(item, field);
            if (raw == null || raw.trim().isEmpty()) continue;
            String cleaned = cleanIptvTitle(raw);
            if (series) cleaned = cleaned.replaceFirst(
                    "(?iu)\\s*(?:[-–—|:]\\s*)?(?:[\\[(]\\s*)?(?:s|saison|season)\\s*\\d{1,2}(?:\\s*[\\])])?\\s*$", "").trim();
            // Providers can combine localized and original names in one label,
            // e.g. "Sur écoute | The Wire". Search each identity separately.
            for (String query : HomeMediaRules.providerArtworkSearchTitles(cleaned)) {
                if (query != null && !query.trim().isEmpty()) queries.add(query.trim());
            }
        }
        return new ArrayList<>(queries);
    }

    private int findExternalInfoTmdbId(List<String> queries, String mediaType, String yearHint) throws Exception {
        return findExternalInfoTmdbId(queries, mediaType, yearHint, false);
    }

    private int findExternalInfoTmdbId(List<String> queries, String mediaType, String yearHint,
            boolean matchTranslations) throws Exception {
        return findExternalInfoTmdbId(queries, mediaType, yearHint, matchTranslations, null);
    }

    private int findExternalInfoTmdbId(List<String> queries, String mediaType, String yearHint,
            boolean matchTranslations, java.util.Set<Integer> candidates) throws Exception {
        java.util.LinkedHashSet<Integer> qualifiedMatches = new java.util.LinkedHashSet<>();
        java.util.LinkedHashSet<Integer> qualifiedYearMatches = new java.util.LinkedHashSet<>();
        java.util.Map<Integer, JSONObject> translations = new java.util.HashMap<>();
        for (String query : queries) {
            JSONArray results = fetchJson("https://api.themoviedb.org/3/search/" + mediaType
                    + "?api_key=" + java.net.URLEncoder.encode(BuildConfig.TMDB_API_KEY, "UTF-8")
                    + "&language=fr-FR&include_adult=false&query="
                    + java.net.URLEncoder.encode(query, "UTF-8")).optJSONArray("results");
            String expected = normalizeTmdbArtworkText(query);
            java.util.LinkedHashSet<Integer> matches = new java.util.LinkedHashSet<>();
            java.util.LinkedHashSet<Integer> yearMatches = new java.util.LinkedHashSet<>();
            if (results != null) for (int index = 0; index < results.length(); index++) {
                JSONObject candidate = results.optJSONObject(index);
                if (candidate == null) continue;
                String candidateTitle = candidate.optString("title", candidate.optString("name", ""));
                String originalTitle = candidate.optString("original_title", candidate.optString("original_name", ""));
                boolean exact = expected.equals(normalizeTmdbArtworkText(candidateTitle))
                        || expected.equals(normalizeTmdbArtworkText(originalTitle));
                boolean qualified = "tv".equals(mediaType) && !exact
                        && (tmdbArtworkTitleMatches(query, query, candidateTitle)
                        || tmdbArtworkTitleMatches(query, query, originalTitle));
                int id = candidate.optInt("id", 0);
                if (id <= 0) continue;
                if (!exact && !qualified) continue;
                String date = candidate.optString("release_date", candidate.optString("first_air_date", ""));
                boolean sameYear = !yearHint.isEmpty() && date.startsWith(yearHint);
                if ("movie".equals(mediaType) && !yearHint.isEmpty() && !sameYear) continue;
                if (candidates != null) candidates.add(id);
                if (exact) {
                    matches.add(id);
                    if (sameYear) yearMatches.add(id);
                } else {
                    qualifiedMatches.add(id);
                    if (sameYear) qualifiedYearMatches.add(id);
                }
            }
            // Netflix publishes localized titles which may only appear in TMDB translations.
            if (matchTranslations && results != null
                    && (matches.isEmpty() || ("tv".equals(mediaType) && candidates != null))) {
                for (int index = 0; index < Math.min(5, results.length()); index++) {
                    JSONObject candidate = results.optJSONObject(index);
                    int id = candidate == null ? 0 : candidate.optInt("id", 0);
                    if (id <= 0) continue;
                    if (matches.contains(id) || qualifiedMatches.contains(id)) continue;
                    String date = candidate.optString("release_date", candidate.optString("first_air_date", ""));
                    boolean sameYear = !yearHint.isEmpty() && date.startsWith(yearHint);
                    if ("movie".equals(mediaType) && !yearHint.isEmpty() && !sameYear) continue;
                    JSONObject translated = translations.get(id);
                    if (translated == null) {
                        translated = fetchJson("https://api.themoviedb.org/3/" + mediaType + "/" + id
                                + "/translations?api_key=" + java.net.URLEncoder.encode(BuildConfig.TMDB_API_KEY, "UTF-8"));
                        translations.put(id, translated);
                    }
                    JSONArray names = translated.optJSONArray("translations");
                    if (names != null) for (int i = 0; i < names.length(); i++) {
                        JSONObject translation = names.optJSONObject(i);
                        JSONObject data = translation == null ? null : translation.optJSONObject("data");
                        if (data == null || !expected.equals(normalizeTmdbArtworkText(
                                data.optString("title", data.optString("name", ""))))) continue;
                        matches.add(id);
                        if (candidates != null) candidates.add(id);
                        if (sameYear) yearMatches.add(id);
                        break;
                    }
                }
            }
            // A provider's TV year may describe a later season, rather than
            // the series premiere. Use it to distinguish homonyms only.
            if (matches.size() == 1) return matches.iterator().next();
            if (yearMatches.size() == 1) return yearMatches.iterator().next();
            if (matches.size() > 1) return 0;
        }
        // Match the logo resolver's provider qualifiers ("Paris Has Fallen"
        // -> "Has Fallen"), only after all exact titles and without choosing
        // arbitrarily between several series.
        if (qualifiedMatches.size() == 1) return qualifiedMatches.iterator().next();
        if (qualifiedYearMatches.size() == 1) return qualifiedYearMatches.iterator().next();
        return 0;
    }

    private void loadTiviMateEpisodeInfo(TextView metadata, FolderMetadata details,
                                         JSONObject series, JSONObject episode) {
        ArrayList<String> parts = new ArrayList<>();
        String genres = details != null && details.genres != null && !details.genres.isEmpty()
                ? details.genres : heroGenres(episode);
        if (genres.isEmpty()) genres = heroGenres(series);
        if (!genres.isEmpty()) parts.add(genres);
        String year = details != null && details.date != null && !details.date.isEmpty()
                ? details.date : firstExternalValue(series, "year", "release_year", "releaseYear");
        if (!year.isEmpty()) parts.add(year.length() >= 4 ? year.substring(0, 4) : year);
        int runtime = externalHeroRuntimeMinutes(episode);
        String requestKey = details == null || episode == null ? ""
                : "episode-runtime|" + details.tmdbId + "|" + episode.optInt("season") + "|" + episode.optInt("episode");
        android.content.SharedPreferences cache = getSharedPreferences("home_hero_editorial_cache", MODE_PRIVATE);
        if (runtime <= 0 && !requestKey.isEmpty()) runtime = cache.getInt(requestKey, 0);
        if (runtime > 0) parts.add(formatHeroRuntime(runtime));
        metadata.setText(joinWithBullet(parts));
        metadata.setTag(requestKey);
        if (runtime > 0 || details == null || details.tmdbId <= 0 || episode == null
                || episode.optInt("season") <= 0 || episode.optInt("episode") <= 0) return;
        new Thread(() -> {
            try {
                JSONObject value = fetchJson("https://api.themoviedb.org/3/tv/" + details.tmdbId
                        + "/season/" + episode.optInt("season") + "/episode/" + episode.optInt("episode")
                        + "?api_key=" + java.net.URLEncoder.encode(BuildConfig.TMDB_API_KEY, "UTF-8")
                        + "&language=fr-FR");
                int episodeRuntime = value.optInt("runtime", 0);
                if (episodeRuntime <= 0) return;
                cache.edit().putInt(requestKey, episodeRuntime).apply();
                runOnUiThread(() -> {
                    if (!metadata.isAttachedToWindow() || !requestKey.equals(metadata.getTag())) return;
                    loadTiviMateEpisodeInfo(metadata, details, series, episode);
                });
            } catch (Exception ignored) { }
        }, "JojoHomeEpisodeInfo").start();
    }

    private String formatHomeCategoryHeroCredits(FolderMetadata details) {
        if (details == null) return "";
        ArrayList<String> actors = new ArrayList<>();
        for (FolderCastMember member : details.cast) {
            if (member == null || member.name == null || member.name.trim().isEmpty()) continue;
            actors.add(member.name.trim());
        }
        return formatHomeHeroCredits(actors, details.director, hasPresenterCredits(details));
    }

    private void applyProviderHeroCredits(TextView view, JSONObject item) {
        if (view == null) return;
        List<String> actors = parseHeroCreditNames(firstExternalValue(item,
                "actors", "cast", "actor", "stars", "castMembers", "cast_members"));
        String director = TextUtils.join(", ", parseHeroCreditNames(
                firstExternalValue(item, "director", "directors")));
        String value = formatHomeHeroCredits(actors, director);
        view.setText(value);
        view.setVisibility(value.isEmpty() ? View.GONE : View.VISIBLE);
    }

    private void loadTiviMateHeroCreditsFallback(TextView view, String title, String year) {
        String providerCredits = view == null || view.getText() == null
                ? "" : view.getText().toString();
        if (!containsHebrew(providerCredits) || BuildConfig.TMDB_API_KEY == null
                || BuildConfig.TMDB_API_KEY.trim().isEmpty()) return;
        String query = videoArtworkSearchTitle(title, null);
        if (query == null || query.trim().isEmpty()) return;
        String normalizedQuery = normalizeTmdbArtworkText(query);
        String expectedYear = year == null ? "" : year.replaceAll("[^0-9]", "");
        String cacheKey = "credits|tv|v" + HomeMediaRules.TMDB_PEOPLE_POLICY_VERSION + "|" + normalizedQuery + "|" + expectedYear;
        String requestTag = "tmdb_series_credits|" + cacheKey;
        android.content.SharedPreferences cache = getSharedPreferences(
                "home_hero_editorial_cache", MODE_PRIVATE);
        view.setTag(requestTag);
        String cached = cache.getString(cacheKey, "");
        if (!cached.isEmpty() && !containsHebrew(cached)) {
            view.setText(cached);
            view.setVisibility(View.VISIBLE);
            return;
        }

        new Thread(() -> {
            try {
                String encodedKey = java.net.URLEncoder.encode(BuildConfig.TMDB_API_KEY, "UTF-8");
                String searchUrl = "https://api.themoviedb.org/3/search/tv?api_key=" + encodedKey
                        + "&language=fr-FR&include_adult=false&query="
                        + java.net.URLEncoder.encode(query, "UTF-8");
                JSONArray results = fetchJson(searchUrl).optJSONArray("results");
                if (results == null) return;
                JSONObject match = null;
                boolean matchingYearFound = false;
                for (int index = 0; index < results.length(); index++) {
                    JSONObject candidate = results.optJSONObject(index);
                    if (candidate == null) continue;
                    String candidateTitle = candidate.optString("name",
                            candidate.optString("original_name", ""));
                    String originalTitle = candidate.optString("original_name", "");
                    if (!normalizedQuery.equals(normalizeTmdbArtworkText(candidateTitle))
                            && !normalizedQuery.equals(normalizeTmdbArtworkText(originalTitle))) continue;
                    String firstAirDate = candidate.optString("first_air_date", "");
                    boolean yearMatches = expectedYear.isEmpty() || (firstAirDate.length() >= 4
                            && expectedYear.equals(firstAirDate.substring(0, 4)));
                    if (match == null || (!matchingYearFound && yearMatches)) {
                        match = candidate;
                        matchingYearFound = yearMatches;
                    }
                }
                if (match == null) return;
                int tmdbId = match.optInt("id", 0);
                if (tmdbId <= 0) return;
                JSONObject credits = fetchJson("https://api.themoviedb.org/3/tv/" + tmdbId
                        + "/aggregate_credits?api_key=" + encodedKey + "&language=en-US");
                ArrayList<String> actors = new ArrayList<>();
                List<FolderCastMember> people = tmdbPeople("tv", credits);
                for (FolderCastMember person : people) actors.add(person.name);
                String director = "";
                JSONArray crew = credits.optJSONArray("crew");
                if (crew != null) for (int index = 0; index < crew.length(); index++) {
                    JSONObject person = crew.optJSONObject(index);
                    if (person == null) continue;
                    JSONArray jobs = person.optJSONArray("jobs");
                    boolean isDirector = false;
                    if (jobs != null) for (int jobIndex = 0; jobIndex < jobs.length(); jobIndex++) {
                        JSONObject job = jobs.optJSONObject(jobIndex);
                        if (job != null && "Director".equalsIgnoreCase(job.optString("job", ""))) {
                            isDirector = true;
                            break;
                        }
                    }
                    if (!isDirector && !"Director".equalsIgnoreCase(person.optString("job", ""))) continue;
                    director = person.optString("name", "").trim();
                    if (!director.isEmpty()) break;
                }
                String resolved = formatHomeHeroCredits(actors, director,
                        people.stream().anyMatch(person -> HomeMediaRules.isTmdbPresenter(person.character)));
                if (resolved.isEmpty() || containsHebrew(resolved)) return;
                cache.edit().putString(cacheKey, resolved).apply();
                runOnUiThread(() -> {
                    if (requestTag.equals(view.getTag()) && view.getText() != null
                            && containsHebrew(view.getText().toString())) {
                        view.setText(resolved);
                        view.setVisibility(View.VISIBLE);
                    }
                });
            } catch (Exception ignored) { }
        }, "JojoHomeTmdbSeriesCredits").start();
    }

    private boolean containsHebrew(String value) {
        if (value == null) return false;
        for (int index = 0; index < value.length(); index++) {
            char character = value.charAt(index);
            if ((character >= '\u0590' && character <= '\u05FF')
                    || (character >= '\uFB1D' && character <= '\uFB4F')) return true;
        }
        return false;
    }

    private List<String> parseHeroCreditNames(String raw) {
        ArrayList<String> names = new ArrayList<>();
        if (raw == null || raw.trim().isEmpty()) return names;
        String value = raw.trim();
        if (value.startsWith("[")) try {
            JSONArray array = new JSONArray(value);
            for (int i = 0; i < array.length(); i++) {
                Object entry = array.opt(i);
                if (entry instanceof JSONObject) {
                    JSONObject person = (JSONObject) entry;
                    addHeroCreditNames(names, firstExternalValue(person, "name", "actor", "full_name"));
                } else if (entry != null) addHeroCreditNames(names, String.valueOf(entry));
            }
            return names;
        } catch (Exception ignored) { }
        if (value.startsWith("{")) try {
            JSONObject person = new JSONObject(value);
            addHeroCreditNames(names, firstExternalValue(person, "name", "actor", "full_name"));
            if (!names.isEmpty()) return names;
        } catch (Exception ignored) { }
        addHeroCreditNames(names, value);
        return names;
    }

    private void addHeroCreditNames(List<String> names, String value) {
        value = HomeMediaRules.mediaMetadataText(value);
        if (value.isEmpty()) return;
        for (String name : value.split("[,;|\\n]+")) {
            String clean = HomeMediaRules.mediaMetadataText(name);
            if (!clean.isEmpty() && !names.contains(clean)) names.add(clean);
        }
    }

    private String formatHomeHeroCredits(List<String> actors, String director) {
        return formatHomeHeroCredits(actors, director, false);
    }

    private String formatHomeHeroCredits(List<String> actors, String director, boolean presenters) {
        ArrayList<String> lines = new ArrayList<>();
        ArrayList<String> visibleActors = new ArrayList<>();
        if (actors != null) for (String actor : actors) {
            if (actor == null || actor.trim().isEmpty()) continue;
            visibleActors.add(actor.trim());
            if (visibleActors.size() == 3) break;
        }
        if (!visibleActors.isEmpty()) {
            String actorLine = (presenters ? "Pr\u00e9sentation : " : "Acteurs : ") + TextUtils.join(", ", visibleActors);
            if (actors != null && actors.size() > visibleActors.size()) actorLine += "…";
            lines.add(actorLine);
        }
        if (director != null && !director.trim().isEmpty()) {
            lines.add("Réalisateur : " + director.trim());
        }
        return TextUtils.join("\n", lines);
    }

    private void loadContinueWatchingHeroCredits(FrameLayout hero, TextView credits,
                                                  JojoProgram program, JSONObject metadata,
                                                  boolean seriesResume) {
        applyProviderHeroCredits(credits, metadata);
        if (!isExternalPlaybackResumeSource(program.sourcePackage)) return;
        String current = credits.getText() == null ? "" : credits.getText().toString();
        if (current.contains("Acteurs :") && current.contains("Réalisateur :")) return;
        Object heroKey = hero.getTag();
        String requestKey = "continue_hero_credits|" + resumeDismissKey(program);
        credits.setTag(requestKey);
        TiviMateFavoriteImporter.enrichPlaybackMetadata(this, program.intentUri, () -> {
            JSONObject playback = externalResumeItem(program);
            JSONObject editorial = homeHeroEditorialSource(playback, seriesResume);
            String resolved = formatHomeHeroCredits(
                    parseHeroCreditNames(firstExternalValue(editorial,
                            "actors", "cast", "actor", "stars", "castMembers", "cast_members")),
                    TextUtils.join(", ", parseHeroCreditNames(
                            firstExternalValue(editorial, "director", "directors"))));
            runOnUiThread(() -> {
                if (!resolved.isEmpty() && credits.isAttachedToWindow()
                        && heroKey == hero.getTag() && requestKey.equals(credits.getTag())) {
                    credits.setText(resolved);
                    credits.setVisibility(View.VISIBLE);
                }
            });
        });
    }

    /** A cloud resume may arrive before this TV has the catalogue's full fiche. */
    private void loadContinueWatchingIptvMetadata(FrameLayout hero, JojoProgram program,
            JSONObject item, boolean seriesResume, ImageView titleLogo, TextView metadata,
            TextView credits, TextView synopsis) {
        if (program.intentUri == null || !program.intentUri.startsWith("iptv:")) return;
        String category = seriesResume ? "series" : "movies";
        loadExternalInfoMetadata(hero, category, program, item, titleLogo, metadata, credits, synopsis);
        if (item == null || item.optString("id").isEmpty()
                || !heroGenres(item).isEmpty() && externalHeroRuntimeMinutes(item) > 0
                && !firstExternalValue(item, "year", "release_year", "releaseYear").isEmpty()
                && !TextUtils.isEmpty(synopsis.getText()) && credits.getVisibility() == View.VISIBLE) return;
        Object binding = hero.getTag();
        Object request = hero.getTag(CATEGORY_VIDEO_METADATA_REQUEST_TAG);
        String previous = item.toString();
        ExternalPlaybackStore.enrichProviderMetadata(this, item.optString("id"), () -> hero.post(() -> {
            if (isDestroyed() || !hero.isAttachedToWindow() || hero.getTag() != binding
                    || hero.getTag(CATEGORY_VIDEO_METADATA_REQUEST_TAG) != request) return;
            JSONObject refreshed = homeHeroEditorialSource(externalResumeItem(program), seriesResume);
            if (!refreshed.has("id") || previous.equals(refreshed.toString())) return;
            metadata.setText(homeCategoryHeroMetadata(category, program, refreshed));
            applyProviderHeroCredits(credits, refreshed);
            String overview = homeCategoryHeroSynopsis(category, program, refreshed);
            if (!overview.isEmpty()) synopsis.setText(shortenContinueWatchingHeroSynopsis(overview));
            loadExternalInfoMetadata(hero, category, program, refreshed,
                    titleLogo, metadata, credits, synopsis);
        }));
    }

    private void loadNetflixContinueWatchingMetadata(FrameLayout hero, JojoProgram program,
            JSONObject provider, TextView title, ImageView titleLogo, ImageView artwork,
            TextView metadata, TextView credits,
            TextView synopsis, TextView episodeBadge, String episodeCode) {
        if (!"netflix".equals(SystemContinueWatching.sharedResumeProvider(program.sourcePackage))) return;
        String hint = SystemContinueWatching.netflixResumeMediaType(program.title, program.description,
                program.seasonNumber, program.episodeNumber);
        String episodeTitle = SystemContinueWatching.netflixResumeEpisodeTitle(program.title, program.description);
        List<String> queries = externalInfoSearchTitles(provider, program.title, "tv".equals(hint));
        java.util.regex.Matcher year = java.util.regex.Pattern.compile("(?:19|20)\\d{2}")
                .matcher(firstExternalValue(provider, "year", "release_year", "releaseYear"));
        String yearHint = year.find() ? year.group() : "";
        int runtimeHint = program.duration >= 60_000L ? Math.round(program.duration / 60_000f)
                : externalHeroRuntimeMinutes(provider);
        String cacheKey = "netflix-info-v4|" + hint + "|" + TextUtils.join("|", queries) + "|" + yearHint
                + "|" + runtimeHint + "|" + String.valueOf(program.seasonNumber)
                + "|" + String.valueOf(program.episodeNumber) + "|" + normalizeTmdbArtworkText(episodeTitle);
        String episodeCacheKey = cacheKey + "|episode";
        String requestKey = cacheKey;
        String heroKey = resumeDismissKey(program);
        java.util.function.Consumer<FolderMetadata> apply = details -> hero.post(() -> {
            if (isDestroyed() || !heroKey.equals(hero.getTag()) || !metadata.isAttachedToWindow()) return;
            if (details != null && !TextUtils.isEmpty(details.title)) title.setText(details.title);
            // Notification images include Netflix's resume caption and progress track.
            // Use the identified programme's backdrop, keeping an explicit user choice.
            if (details != null && ExternalPlaybackStore.supportedUrl(details.backdrop)
                    && homePrefs().getString("resume_artwork_"
                        + Integer.toUnsignedString(heroKey.hashCode(), 16), "").isEmpty())
                loadArtwork(artwork, details.backdrop);
            ArrayList<String> values = new ArrayList<>();
            String genres = details == null ? "" : details.genres;
            if (TextUtils.isEmpty(genres)) genres = heroGenres(provider);
            if (!TextUtils.isEmpty(genres)) values.add(genres);
            String date = details == null ? "" : details.date;
            if (TextUtils.isEmpty(date)) date = yearHint;
            if (!TextUtils.isEmpty(date)) values.add(date);
            // Netflix's duration belongs to this episode; the series metadata may
            // instead contain the runtime of the most recently broadcast episode.
            String tmdbRuntime = runtimeHint > 0 ? formatHeroRuntime(runtimeHint)
                    : details == null ? "" : details.runtime;
            if (!TextUtils.isEmpty(tmdbRuntime)) values.add(tmdbRuntime);
            else {
                int runtime = externalHeroRuntimeMinutes(provider);
                if (runtime <= 0 && program.duration >= 60_000L) runtime = Math.round(program.duration / 60_000f);
                if (runtime > 0) values.add(formatHeroRuntime(runtime));
            }
            metadata.setText(joinWithBullet(values));
            List<String> actors = new ArrayList<>();
            if (details != null) for (FolderCastMember member : details.cast) actors.add(member.name);
            if (actors.isEmpty()) actors = parseHeroCreditNames(firstExternalValue(provider,
                    "actors", "cast", "actor", "stars", "castMembers", "cast_members"));
            String director = details == null ? "" : details.director;
            if (TextUtils.isEmpty(director)) director = TextUtils.join(", ",
                    parseHeroCreditNames(firstExternalValue(provider, "director", "directors")));
            String creditText = formatHomeHeroCredits(actors, director);
            credits.setText(creditText);
            credits.setVisibility(creditText.isEmpty() ? View.GONE : View.VISIBLE);
            String overview = details == null ? "" : details.overview;
            if (TextUtils.isEmpty(overview)) overview = preferredHomeHeroSynopsis(provider, program);
            if (!TextUtils.isEmpty(overview)) synopsis.setText(shortenContinueWatchingHeroSynopsis(overview));
            String logo = details == null ? "" : details.logo;
            if (!isUsableTitleLogoUrl(logo)) logo = explicitTitleLogoUrl(provider);
            if (ExternalPlaybackStore.supportedUrl(logo))
                loadArtwork(titleLogo, SystemContinueWatching.netflixTitleLogoUrl(logo));
            else notifyArtworkLoadFailure(titleLogo);
            if (episodeBadge != null) {
                if (details != null && "tv".equals(details.tmdbMediaType)) {
                    loadNetflixHeroEpisodeBadge(hero, heroKey, episodeBadge, details, episodeCode,
                            episodeTitle, program.seasonNumber, episodeCacheKey);
                } else if (details != null || episodeCode.isEmpty()) {
                    episodeBadge.setVisibility(View.GONE);
                }
            }
        });
        if (queries.isEmpty() || BuildConfig.TMDB_API_KEY == null || BuildConfig.TMDB_API_KEY.trim().isEmpty()) {
            apply.accept(null);
            return;
        }
        FolderMetadata cached = folderHeroMetadataCache.get(cacheKey);
        if (cached != null) { apply.accept(cached); return; }
        List<java.util.function.Consumer<FolderMetadata>> pending = netflixHeroMetadataRequests.get(requestKey);
        if (pending != null) { pending.add(apply); return; }
        pending = new ArrayList<>();
        pending.add(apply);
        netflixHeroMetadataRequests.put(requestKey, pending);
        artworkLoadExecutor.execute(() -> {
            FolderMetadata details = folderHeroMetadataCache.get(cacheKey);
            try {
                if (details == null) {
                    FolderMetadata tvDetails = findNetflixTmdbSeries(queries, yearHint, program,
                            episodeTitle, episodeCacheKey);
                    int tvId = tvDetails == null ? 0 : tvDetails.tmdbId;
                    if (tvDetails != null && ("tv".equals(hint) || !episodeTitle.isEmpty())) details = tvDetails;
                    if (details == null && !"tv".equals(hint)) {
                        int movieId = findExternalInfoTmdbId(queries, "movie", yearHint, true);
                        FolderMetadata movieDetails = movieId > 0
                                ? fetchFreeboxTmdbMetadata(movieId, "movie", program.title, true) : null;
                        if (movieDetails != null && !SystemContinueWatching.netflixMovieMetadataMatches(hint,
                                episodeTitle, yearHint, runtimeHint, movieDetails.date,
                                HomeMediaRules.heroRuntimeMinutes(movieDetails.runtime))) movieId = 0;
                        String type = SystemContinueWatching.resolvedResumeMediaType(hint, movieId, tvId);
                        if ("tv".equals(type)) details = tvDetails;
                        else if ("movie".equals(type)) details = movieDetails;
                    }
                    // Keep the full title eligible for films before treating a comma
                    // as a series/episode separator. Both parts must match the same series.
                    if (details == null) details = findNetflixCombinedTitleSeries(program, yearHint, episodeCacheKey);
                    if (details != null) folderHeroMetadataCache.put(cacheKey, details);
                }
            } catch (Exception error) {
                android.util.Log.w("JojoHomeNetflixMetadata", "Metadata unavailable: " + error.getClass().getSimpleName());
            } finally {
                FolderMetadata result = details;
                runOnUiThread(() -> {
                    List<java.util.function.Consumer<FolderMetadata>> callbacks = netflixHeroMetadataRequests.remove(requestKey);
                    if (callbacks != null) for (java.util.function.Consumer<FolderMetadata> callback : callbacks)
                        callback.accept(result);
                });
            }
        });
    }

    private FolderMetadata findNetflixTmdbSeries(List<String> queries, String yearHint, JojoProgram program,
            String episodeTitle, String episodeCacheKey) throws Exception {
        java.util.Set<Integer> candidates = new java.util.LinkedHashSet<>();
        int id = findExternalInfoTmdbId(queries, "tv", yearHint, true, candidates);
        if (episodeTitle.isEmpty()) return id > 0
                ? fetchFreeboxTmdbMetadata(id, "tv", program.title, true) : null;
        FolderMetadata selected = null;
        String selectedCode = "";
        for (int candidateId : candidates) {
            FolderMetadata candidate = fetchFreeboxTmdbMetadata(candidateId, "tv", program.title, true);
            String code = findNetflixTmdbEpisodeCode(candidate, episodeTitle, program.seasonNumber);
            if (code.isEmpty()) continue;
            if (selected != null) return null;
            selected = candidate;
            selectedCode = code;
        }
        if (selected != null) netflixHeroEpisodeCodeCache.put(episodeCacheKey, selectedCode);
        return selected;
    }

    private FolderMetadata findNetflixCombinedTitleSeries(JojoProgram program, String yearHint,
            String episodeCacheKey) throws Exception {
        FolderMetadata selected = null;
        String selectedCode = "";
        for (java.util.Map.Entry<String, String> title : SystemContinueWatching
                .netflixSeriesEpisodeCandidates(program.title).entrySet()) {
            java.util.Set<Integer> candidates = new java.util.LinkedHashSet<>();
            findExternalInfoTmdbId(externalInfoSearchTitles(null, title.getKey(), true),
                    "tv", yearHint, true, candidates);
            for (int id : candidates) {
                FolderMetadata details = fetchFreeboxTmdbMetadata(id, "tv", title.getKey(), true);
                String code = findNetflixTmdbEpisodeCode(details, title.getValue(), program.seasonNumber);
                if (code.isEmpty()) continue;
                if (selected != null && (selected.tmdbId != id || !selectedCode.equals(code))) return null;
                selected = details;
                selectedCode = code;
            }
        }
        if (selected != null) netflixHeroEpisodeCodeCache.put(episodeCacheKey, selectedCode);
        return selected;
    }

    private boolean isCompleteNetflixEpisodeCode(String code) {
        return code != null && code.matches("(?i)^S\\d{2,}E\\d{2,}$");
    }

    private void loadNetflixHeroEpisodeBadge(FrameLayout hero, String heroKey, TextView badge,
            FolderMetadata details, String episodeCode, String episodeTitle, String seasonNumber,
            String episodeCacheKey) {
        if (badge == null) return;
        if (details == null || !"tv".equals(details.tmdbMediaType)) {
            badge.setVisibility(View.GONE);
            return;
        }
        if (isCompleteNetflixEpisodeCode(episodeCode)) {
            badge.setText(episodeCode);
            badge.setVisibility(View.VISIBLE);
            // Published counters describe playback; a TMDB title match must not replace them.
            return;
        }
        java.util.function.Consumer<String> publish = value -> hero.post(() -> {
            if (isDestroyed() || !heroKey.equals(hero.getTag()) || !badge.isAttachedToWindow()) return;
            String code = TextUtils.isEmpty(value) ? episodeCode : value;
            if (TextUtils.isEmpty(code)) badge.setVisibility(View.GONE);
            else {
                badge.setText(code);
                badge.setVisibility(View.VISIBLE);
            }
        });
        String cached = netflixHeroEpisodeCodeCache.get(episodeCacheKey);
        if (cached != null) { publish.accept(cached); return; }
        if (episodeTitle == null || episodeTitle.trim().isEmpty()) { publish.accept(""); return; }
        List<java.util.function.Consumer<String>> pending = netflixHeroEpisodeCodeRequests.get(episodeCacheKey);
        if (pending != null) { pending.add(publish); return; }
        pending = new ArrayList<>();
        pending.add(publish);
        netflixHeroEpisodeCodeRequests.put(episodeCacheKey, pending);
        artworkLoadExecutor.execute(() -> {
            String code = "";
            try { code = findNetflixTmdbEpisodeCode(details, episodeTitle, seasonNumber); }
            catch (Exception error) {
                android.util.Log.w("JojoHomeNetflixMetadata", "Episode unavailable: " + error.getClass().getSimpleName());
            }
            netflixHeroEpisodeCodeCache.put(episodeCacheKey, code);
            String result = code;
            runOnUiThread(() -> {
                List<java.util.function.Consumer<String>> callbacks = netflixHeroEpisodeCodeRequests.remove(episodeCacheKey);
                if (callbacks != null) for (java.util.function.Consumer<String> callback : callbacks)
                    callback.accept(result);
            });
        });
    }

    private String findNetflixTmdbEpisodeCode(FolderMetadata details, String episodeTitle,
                                               String preferredSeason) throws Exception {
        if (details == null || details.tmdbId <= 0 || !"tv".equals(details.tmdbMediaType)
                || episodeTitle == null || episodeTitle.trim().isEmpty()) return "";
        String expected = normalizeTmdbArtworkText(episodeTitle);
        if (expected.isEmpty()) return "";
        ArrayList<Integer> seasons = new ArrayList<>();
        java.util.regex.Matcher seasonMatcher = java.util.regex.Pattern.compile("\\d+")
                .matcher(preferredSeason == null ? "" : preferredSeason);
        if (seasonMatcher.find()) {
            int season = Integer.parseInt(seasonMatcher.group());
            if (season > 0) seasons.add(season);
        }
        if (seasons.isEmpty()) seasons.addAll(details.seasonNumbers);
        if (seasons.isEmpty()) for (int season = 1; season <= details.seasonCount; season++) seasons.add(season);
        if (seasons.isEmpty()) return "";
        String query = "?api_key=" + java.net.URLEncoder.encode(BuildConfig.TMDB_API_KEY, "UTF-8")
                + "&language=fr-FR";
        LinkedHashSet<String> matches = new LinkedHashSet<>();
        for (int season : seasons) {
            JSONObject data = fetchJson("https://api.themoviedb.org/3/tv/" + details.tmdbId
                    + "/season/" + season + query);
            JSONArray episodes = data.optJSONArray("episodes");
            if (episodes == null) continue;
            for (int index = 0; index < episodes.length(); index++) {
                JSONObject episode = episodes.optJSONObject(index);
                if (episode == null || !expected.equals(normalizeTmdbArtworkText(episode.optString("name", "")))) continue;
                int number = episode.optInt("episode_number");
                if (number > 0) matches.add(seasonEpisodeCode(String.valueOf(season), String.valueOf(number)));
            }
        }
        return matches.size() == 1 ? matches.iterator().next() : "";
    }

    private JSONObject selectedFreeboxVideoArtworkMetadata(JojoProgram program,
                                                              String heroArtwork, String thumbnailArtwork) {
        JSONObject heroChoice = selectedFreeboxArtworkMetadata(heroArtwork,
                "resume_artwork_metadata_" + Integer.toUnsignedString(resumeDismissKey(program).hashCode(), 16),
                homeVideosProgrammeArtworkKey(program.intentUri, program.title, true) + "_metadata");
        JSONObject thumbnailChoice = selectedFreeboxArtworkMetadata(thumbnailArtwork,
                homeVideosFileArtworkMetadataKey(program.intentUri),
                homeVideosEpisodeArtworkMetadataKey(program.intentUri),
                homeVideosFileArtworkLogicalKey(program.intentUri, program.title) + "_metadata",
                homeVideosProgrammeArtworkKey(program.intentUri, program.title, false) + "_metadata");
        return thumbnailChoice.optInt("tmdbId", 0) > 0
                && (heroChoice.optInt("tmdbId", 0) <= 0
                || thumbnailChoice.optLong("selectedAt", 0L) > heroChoice.optLong("selectedAt", 0L))
                ? thumbnailChoice : heroChoice;
    }

    private JSONObject selectedFreeboxArtworkMetadata(String artwork, String... keys) {
        if (artwork == null || artwork.isEmpty()) return new JSONObject();
        ArrayList<String> records = new ArrayList<>();
        for (String key : keys) if (!key.isEmpty()) records.add(homePrefs().getString(key, "{}"));
        // Older recordings shared the chosen image without its metadata. Recover
        // only an explicit choice for that exact URL, never a title-only cache.
        for (java.util.Map.Entry<String, ?> entry : homePrefs().getAll().entrySet()) {
            if ((entry.getKey().startsWith("home_videos_file_artwork_metadata_")
                    || entry.getKey().startsWith("resume_artwork_metadata_"))
                    && entry.getValue() instanceof String) records.add((String) entry.getValue());
        }
        JSONObject best = new JSONObject();
        for (String record : records) try {
            JSONObject choice = new JSONObject(record);
            String type = choice.optString("mediaType", choice.optString("tmdbMediaType", ""));
            if (choice.optInt("tmdbId", 0) <= 0 || !("movie".equals(type) || "tv".equals(type))) continue;
            if (!artwork.equals(choice.optString("artworkUrl", ""))
                    && !artwork.equals(choice.optString("poster", ""))
                    && !artwork.equals(choice.optString("backdrop", ""))) continue;
            if (best.optInt("tmdbId", 0) <= 0
                    || choice.optLong("selectedAt", 0L) > best.optLong("selectedAt", 0L)) {
                choice.put("mediaType", type);
                best = choice;
            }
        } catch (Exception ignored) { }
        return best;
    }

    private FolderMetadata findFreeboxVideoFileMetadata(JojoProgram program, long duration,
                                                        String selectedHero, String selectedArtwork) {
        if (BuildConfig.TMDB_API_KEY == null || BuildConfig.TMDB_API_KEY.trim().isEmpty()) return null;
        String path = program.intentUri == null ? "" : program.intentUri;
        try {
            String expectedYear = HomeMediaRules.titleYear(program.title);
            int durationMinutes = duration > 0 ? Math.max(1, Math.round(duration / 60_000f)) : 0;
            String selectedThumbnail = homeVideosFileArtwork(path, program.title);
            JSONObject selected = selectedFreeboxVideoArtworkMetadata(program, selectedHero,
                    selectedThumbnail);
            int selectedId = selected.optInt("tmdbId", 0);
            String selectedType = selected.optString("mediaType", "");
            if (selectedId > 0 && ("movie".equals(selectedType) || "tv".equals(selectedType))) {
                FolderMetadata details = fetchFreeboxTmdbMetadata(selectedId, selectedType, program.title);
                if (HomeMediaRules.freeboxMetadataMatches(selectedType, expectedYear, details.date,
                        durationMinutes, HomeMediaRules.heroRuntimeMinutes(details.runtime), !selectedArtwork.isEmpty(),
                        HomeMediaRules.artworkMatches(selectedArtwork, details.artworkPaths), true)) {
                    return enrichFreeboxVideoEpisode(details, program.title);
                }
            }
            String parent = smbParentFolderPath(path);
            JSONObject selectedFolder = selectedSmbFolderArtworkMetadata(parent);
            if (selectedFolder.optInt("tmdbId", 0) > 0
                    && "tv".equals(selectedFolder.optString("mediaType", ""))) {
                FolderMetadata details = fetchFreeboxTmdbMetadata(
                        selectedFolder.optInt("tmdbId", 0), "tv", program.title);
                // A folder choice can describe a different programme in a mixed recordings folder.
                if (freeboxVideoMetadataTitleMatches(program.title, parent, details.title)
                        && HomeMediaRules.freeboxMetadataMatches("tv", expectedYear, details.date,
                        durationMinutes, HomeMediaRules.heroRuntimeMinutes(details.runtime), !selectedArtwork.isEmpty(),
                        HomeMediaRules.artworkMatches(selectedArtwork, details.artworkPaths), false)) {
                    return enrichFreeboxVideoEpisode(details, program.title);
                }
            }
            String searchTitle = videoArtworkSearchTitle(program.title, parent);
            if (searchTitle.isEmpty()) return null;
            FolderMetadata best = null;
            int bestScore = Integer.MIN_VALUE;
            boolean ambiguous = false;
            int inspected = 0;
            for (String query : videoArtworkSearchTitles(program.title, parent)) {
                String endpoint = "https://api.themoviedb.org/3/search/multi?api_key="
                        + java.net.URLEncoder.encode(BuildConfig.TMDB_API_KEY, "UTF-8")
                        + "&language=fr-FR&include_adult=false&query="
                        + java.net.URLEncoder.encode(query, "UTF-8");
                JSONArray results = fetchJson(endpoint).optJSONArray("results");
                if (results == null) continue;
                for (int index = 0; index < results.length() && inspected < 8; index++) {
                    JSONObject candidate = results.optJSONObject(index);
                    if (candidate == null) continue;
                    String type = candidate.optString("media_type", "");
                    if (!("movie".equals(type) || "tv".equals(type))) continue;
                    String candidateTitle = candidate.optString("title", candidate.optString("name", ""));
                    String originalTitle = candidate.optString("original_title", candidate.optString("original_name", ""));
                    boolean exact = normalizeTmdbArtworkText(searchTitle).equals(normalizeTmdbArtworkText(candidateTitle))
                            || normalizeTmdbArtworkText(searchTitle).equals(normalizeTmdbArtworkText(originalTitle));
                    if (!freeboxVideoMetadataTitleMatches(program.title, parent, candidateTitle)
                            && !freeboxVideoMetadataTitleMatches(program.title, parent, originalTitle)) continue;
                    int id = candidate.optInt("id", 0);
                    if (id <= 0) continue;
                    inspected++;
                    FolderMetadata details;
                    try { details = fetchFreeboxTmdbMetadata(id, type, program.title); }
                    catch (Exception ignored) { continue; }
                    int tmdbRuntime = HomeMediaRules.heroRuntimeMinutes(details.runtime);
                    boolean selectedImageMatches = HomeMediaRules.artworkMatches(selectedArtwork, details.artworkPaths);
                    if (!HomeMediaRules.freeboxMetadataMatches(type, expectedYear, details.date,
                            durationMinutes, tmdbRuntime, !selectedArtwork.isEmpty(),
                            selectedImageMatches, false)) continue;
                    int score = exact ? 100 : 40;
                    if (!expectedYear.isEmpty() && details.date != null && !details.date.isEmpty())
                        score += expectedYear.equals(details.date) ? 25 : -15;
                    if (durationMinutes > 0 && tmdbRuntime > 0)
                        score += Math.max(0, 20 - Math.abs(tmdbRuntime - durationMinutes));
                    if (selectedImageMatches) score += 200;
                    if (score > bestScore) {
                        best = details;
                        bestScore = score;
                        ambiguous = false;
                    } else if (score == bestScore && best != null && best.tmdbId != details.tmdbId) {
                        ambiguous = true;
                    }
                }
            }
            return ambiguous || best == null ? null : enrichFreeboxVideoEpisode(best, program.title);
        } catch (Exception error) {
            android.util.Log.w("JojoHomeTmdb", "Métadonnées vidéo Freebox indisponibles", error);
            return null;
        }
    }

    private boolean freeboxVideoMetadataTitleMatches(String fileName, String parent, String candidateTitle) {
        String normalizedCandidate = normalizeTmdbArtworkText(candidateTitle);
        for (String title : videoArtworkSearchTitles(fileName, parent)) {
            if (HomeMediaRules.freeboxMetadataTitleMatches(normalizeTmdbArtworkText(title), normalizedCandidate)) return true;
        }
        return false;
    }

    private FolderMetadata enrichFreeboxVideoEpisode(FolderMetadata details, String fileName) {
        if (details == null) return null;
        if ("tv".equals(details.tmdbMediaType)) try {
            java.util.regex.Matcher episode = java.util.regex.Pattern.compile(
                    "(?i)\\bs(\\d{1,2})\\s*e(\\d{1,3})\\b").matcher(fileName);
            if (episode.find()) {
                JSONObject episodeInfo = fetchJson("https://api.themoviedb.org/3/tv/" + details.tmdbId
                        + "/season/" + Integer.parseInt(episode.group(1))
                        + "/episode/" + Integer.parseInt(episode.group(2))
                        + "?api_key=" + java.net.URLEncoder.encode(BuildConfig.TMDB_API_KEY, "UTF-8")
                        + "&language=fr-FR");
                String episodeOverview = episodeInfo.optString("overview", "").trim();
                if (!episodeOverview.isEmpty()) details.overview = episodeOverview;
            }
        } catch (Exception ignored) { }
        if (details.logo == null || details.logo.isEmpty()) details.logo = findFolderTitleLogoFallback(details);
        return details;
    }

    private String homeCategoryHeroTitle(String category, JojoProgram program) {
        String value = SystemContinueWatching.displayTitle(program.title, program.description);
        if ("videos".equals(category)) return displayVideoTitle(value);
        if ("movies".equals(category) || "series".equals(category)) {
            return displayIptvTitle(value, program.seasonNumber, program.episodeNumber);
        }
        return value;
    }

    private String homeCategoryHeroMetadata(String category, JojoProgram program, JSONObject item) {
        ArrayList<String> values = new ArrayList<>();
        if ("live".equals(category)) {
            String genres = heroGenres(item);
            if (!genres.isEmpty()) values.add(genres);
            String year = firstExternalValue(item, "year", "release_year", "releaseYear").replaceAll("[^0-9]", "");
            if (year.length() >= 4) values.add(year.substring(0, 4));
            int runtimeMinutes = externalHeroRuntimeMinutes(item);
            if (runtimeMinutes <= 0 && program != null && program.duration >= 60_000L) {
                runtimeMinutes = Math.max(1, Math.round(program.duration / 60_000f));
            }
            String runtime = formatHeroRuntime(runtimeMinutes);
            if (!runtime.isEmpty()) values.add(runtime);
            return TextUtils.join("  •  ", values);
        }
        String year = firstExternalValue(item, "year", "release_year", "releaseYear").replaceAll("[^0-9]", "");
        String genres = heroGenres(item);
        if (!genres.isEmpty()) values.add(genres);
        if (year.length() >= 4) values.add(year.substring(0, 4));
        int runtimeMinutes = externalHeroRuntimeMinutes(item);
        if (runtimeMinutes <= 0 && program.duration >= 60_000L) {
            runtimeMinutes = Math.max(1, Math.round(program.duration / 60_000f));
        }
        String runtime = formatHeroRuntime(runtimeMinutes);
        if (!runtime.isEmpty()) values.add(runtime);
        return TextUtils.join("  •  ", values);
    }

    private String formatHeroRuntime(int runtimeMinutes) {
        if (runtimeMinutes <= 0) return "";
        return runtimeMinutes >= 60
                ? (runtimeMinutes / 60) + "h" + String.format(Locale.ROOT, "%02d", runtimeMinutes % 60)
                : runtimeMinutes + " min";
    }

    private int externalHeroRuntimeMinutes(JSONObject item) {
        if (item == null) return 0;
        String providerRuntime = item.optString("providerRuntime", "");
        Object rawDuration = item.opt("duration");
        if (providerRuntime.isEmpty() && rawDuration instanceof String
                && !((String) rawDuration).trim().matches("[+-]?\\d+(?:\\.\\d+)?"))
            providerRuntime = (String) rawDuration;
        return HomeMediaRules.externalRuntimeMinutes(item.optLong("duration", 0L),
                item.optInt("runtimeMinutes", 0), providerRuntime);
    }

    private String heroGenres(JSONObject item) {
        String value = firstExternalValue(item, "genres", "genre", "genreNames", "genre_name", "category_name", "categoryName");
        if (value.isEmpty() || !value.startsWith("[")) return value;
        try {
            JSONArray array = new JSONArray(value);
            ArrayList<String> names = new ArrayList<>();
            for (int i = 0; i < array.length(); i++) {
                Object entry = array.opt(i);
                String name = entry instanceof JSONObject
                        ? ((JSONObject) entry).optString("name", "").trim()
                        : String.valueOf(entry).trim();
                if (!name.isEmpty()) names.add(name);
            }
            return TextUtils.join(" • ", names);
        } catch (Exception ignored) {
            return value;
        }
    }

    /**
     * Provider records do not consistently expose genres. Resolve them from
     * the exact TMDB result when the card has only year/runtime metadata.
     * This is display-only: the provider record and its synchronization state
     * are never overwritten.
     */
    private void loadHeroGenreFallback(TextView metadata, String title, String mediaType,
                                       String year, JSONObject item) {
        if (metadata == null || !heroGenres(item).isEmpty()
                || BuildConfig.TMDB_API_KEY == null || BuildConfig.TMDB_API_KEY.trim().isEmpty()) return;
        final String query = videoArtworkSearchTitle(title, null);
        if (query == null || query.trim().isEmpty()) return;
        final String expectedYear = year == null ? "" : year.replaceAll("[^0-9]", "");
        final String genreCacheKey = "genres|" + mediaType + "|"
                + normalizeTmdbArtworkText(query) + "|" + expectedYear;
        String cachedGenres = getSharedPreferences("home_hero_editorial_cache", MODE_PRIVATE)
                .getString(genreCacheKey, "");
        if (!cachedGenres.isEmpty()) {
            String existing = metadata.getText() == null ? "" : metadata.getText().toString().trim();
            metadata.setText(existing.isEmpty() ? cachedGenres : cachedGenres + "  •  " + existing);
            return;
        }
        new Thread(() -> {
            try {
                String searchType = "multi".equals(mediaType) ? "multi" : mediaType;
                String endpoint = "https://api.themoviedb.org/3/search/" + searchType + "?api_key="
                        + java.net.URLEncoder.encode(BuildConfig.TMDB_API_KEY, "UTF-8")
                        + "&language=fr-FR&include_adult=false&query="
                        + java.net.URLEncoder.encode(query, "UTF-8");
                JSONArray results = fetchJson(endpoint).optJSONArray("results");
                if (results == null) return;
                JSONObject match = null;
                String resolvedType = "";
                for (int index = 0; index < results.length(); index++) {
                    JSONObject candidate = results.optJSONObject(index);
                    if (candidate == null) continue;
                    String candidateType = "multi".equals(searchType)
                            ? candidate.optString("media_type", "") : searchType;
                    if (!("movie".equals(candidateType) || "tv".equals(candidateType))) continue;
                    String candidateTitle = "movie".equals(candidateType)
                            ? candidate.optString("title", candidate.optString("original_title", ""))
                            : candidate.optString("name", candidate.optString("original_name", ""));
                    if (!normalizeTmdbArtworkText(candidateTitle).equals(normalizeTmdbArtworkText(query))
                            && !tmdbArtworkTitleMatches(title, query, candidateTitle)) continue;
                    String candidateDate = candidate.optString("release_date",
                            candidate.optString("first_air_date", ""));
                    // IPTV years are frequently the broadcast/import year and
                    // can differ from TMDB's first-air/release year. Keep the
                    // title match even when that auxiliary field is wrong.
                    // Prefer a matching year when one is available, but do not
                    // discard the only valid TMDB result because of it.
                    if (match == null || (!expectedYear.isEmpty()
                            && candidateDate.length() >= 4
                            && expectedYear.equals(candidateDate.substring(0, 4)))) {
                        match = candidate;
                        resolvedType = candidateType;
                    }
                    if (!expectedYear.isEmpty() && candidateDate.length() >= 4
                            && expectedYear.equals(candidateDate.substring(0, 4))) break;
                }
                if (match == null || resolvedType.isEmpty()) return;
                int tmdbId = match.optInt("id", 0);
                if (tmdbId <= 0) return;
                JSONObject details = fetchJson("https://api.themoviedb.org/3/" + resolvedType + "/" + tmdbId
                        + "?api_key=" + java.net.URLEncoder.encode(BuildConfig.TMDB_API_KEY, "UTF-8")
                        + "&language=fr-FR");
                JSONArray genres = details.optJSONArray("genres");
                if (genres == null) return;
                ArrayList<String> names = new ArrayList<>();
                for (int index = 0; index < genres.length(); index++) {
                    String name = genres.optJSONObject(index) == null ? ""
                            : genres.optJSONObject(index).optString("name", "").trim();
                    if (!name.isEmpty()) names.add(name);
                }
                if (names.isEmpty()) return;
                final String resolvedGenres = TextUtils.join(" • ", names);
                getSharedPreferences("home_hero_editorial_cache", MODE_PRIVATE).edit()
                        .putString(genreCacheKey, resolvedGenres).apply();
                runOnUiThread(() -> {
                    // The Hero is often built just before openScreen() attaches
                    // it. Do not lose the asynchronous genre solely because the
                    // network answer arrived during that small window.
                    if (!heroGenres(item).isEmpty()) return;
                    String existing = metadata.getText() == null ? "" : metadata.getText().toString().trim();
                    metadata.setText(existing.isEmpty() ? resolvedGenres
                            : resolvedGenres + "  •  " + existing);
                });
            } catch (Exception ignored) { }
        }, "JojoHomeHeroGenres").start();
    }

    private String homeCategoryHeroSynopsis(String category, JojoProgram program, JSONObject item) {
        if ("live".equals(category)) {
            String current = firstExternalValue(item, "currentProgram", "current_program", "programme", "program", "description");
            String next = firstExternalValue(item, "nextProgram", "next_program", "programmeSuivant", "next");
            if (!next.isEmpty()) return (current.isEmpty() ? "Programme actuel indisponible" : current)
                    + "\nÀ suivre : " + next;
            return current.isEmpty() ? "Programme actuel indisponible" : current;
        }
        return preferredHomeHeroSynopsis(item, program);
    }

    private String preferredHomeHeroSynopsis(JSONObject item, JojoProgram program) {
        String value = item == null ? "" : cleanHeroSynopsis(heroShortSynopsis(item), program);
        if (value.isEmpty() && item != null) {
            value = cleanHeroSynopsis(heroShortSynopsis(externalPlaybackHeroFavorite(item)), program);
        }
        // Android TV's short_description is often the concise version missing
        // from the imported provider record, so use it before a full overview.
        if (value.isEmpty() && program != null) value = cleanHeroSynopsis(program.description, program);
        if (value.isEmpty() && item != null) value = cleanHeroSynopsis(heroMediumSynopsis(item), program);
        if (value.isEmpty() && item != null) value = cleanHeroSynopsis(externalPlaybackHeroSynopsis(item), program);
        if (value.isEmpty()) value = cleanHeroSynopsis(continueWatchingHeroSynopsis(program), program);
        return shortenContinueWatchingHeroSynopsis(value);
    }

    private String firstExternalValue(JSONObject item, String... fields) {
        if (item == null) return "";
        for (String field : fields) {
            String value = HomeMediaRules.mediaMetadataText(item.optString(field, ""));
            if (!value.isEmpty()) return value;
        }
        return "";
    }

    private void wireHomeCategoryPageGrid(List<LinearLayout> rows, View hero) {
        if (hero.getId() == View.NO_ID) hero.setId(View.generateViewId());
        for (int rowIndex = 0; rowIndex < rows.size(); rowIndex++) {
            LinearLayout row = rows.get(rowIndex);
            List<View> current = immediateFocusableChildren(row);
            List<View> above = rowIndex > 0 ? immediateFocusableChildren(rows.get(rowIndex - 1)) : Collections.emptyList();
            List<View> below = rowIndex + 1 < rows.size()
                    ? immediateFocusableChildren(rows.get(rowIndex + 1)) : Collections.emptyList();
            for (int index = 0; index < current.size(); index++) {
                View tile = current.get(index);
                if (tile.getId() == View.NO_ID) tile.setId(View.generateViewId());
                View left = index > 0 ? current.get(index - 1) : tile;
                View right = index + 1 < current.size() ? current.get(index + 1) : tile;
                if (left.getId() == View.NO_ID) left.setId(View.generateViewId());
                if (right.getId() == View.NO_ID) right.setId(View.generateViewId());
                tile.setNextFocusLeftId(left.getId());
                tile.setNextFocusRightId(right.getId());
                View up = above.isEmpty() ? hero : alignedTarget(above, index);
                View down = below.isEmpty() ? tile : alignedTarget(below, index);
                if (up.getId() == View.NO_ID) up.setId(View.generateViewId());
                if (down.getId() == View.NO_ID) down.setId(View.generateViewId());
                tile.setNextFocusUpId(up.getId());
                tile.setNextFocusDownId(down.getId());
            }
        }
    }

    private void wireCategoryPageGrid(GridLayout grid, View hero) {
        if (grid == null || hero == null) return;
        if (hero.getId() == View.NO_ID) hero.setId(View.generateViewId());
        // Category pages are one horizontal cyclic rail (Vidéos, Films,
        // Séries and IPTV/Live). Mark the real container so Fire TV cannot
        // stop at either edge before nextFocusLeft/Right is evaluated.
        grid.setTag("cyclic_horizontal_card_row");
        grid.setTag(FOLDER_MEDIA_ROW_TAG, "thumbnails");
        List<View> tiles = immediateFocusableChildren(grid);
        int columns = Math.max(1, grid.getColumnCount());
        for (int index = 0; index < tiles.size(); index++) {
            View tile = tiles.get(index);
            if (tile.getId() == View.NO_ID) tile.setId(View.generateViewId());
            int column = index % columns;
            boolean singleRow = tiles.size() > 1 && columns >= tiles.size();
            View left = singleRow
                    ? tiles.get((index + tiles.size() - 1) % tiles.size())
                    : column > 0 ? tiles.get(index - 1) : tile;
            View right = singleRow
                    ? tiles.get((index + 1) % tiles.size())
                    : column + 1 < columns && index + 1 < tiles.size()
                    ? tiles.get(index + 1) : tile;
            tile.setNextFocusLeftId(left.getId());
            tile.setNextFocusRightId(right.getId());
            tile.setNextFocusUpId(tile.getId());
            tile.setNextFocusDownId(tile.getId());
        }
    }
    private ViewGroup folderMediaRow(View focused) {
        if (focused == null || activeScreen == null || !isHomeDescendant(focused, activeScreen)) return null;
        View current = focused;
        while (current != null) {
            if (current instanceof ViewGroup && current.getTag(FOLDER_MEDIA_ROW_TAG) instanceof String) return (ViewGroup) current;
            if (current == activeScreen) break;
            current = current.getParent() instanceof View ? (View) current.getParent() : null;
        }
        return null;
    }
    private boolean handleFolderMediaVerticalDpad(KeyEvent event) {
        if (event == null || (event.getKeyCode() != KeyEvent.KEYCODE_DPAD_UP
                && event.getKeyCode() != KeyEvent.KEYCODE_DPAD_DOWN)
                || (activePopup != null && activePopup.isShowing())) return false;
        View focused = getCurrentFocus();
        ViewGroup row = folderMediaRow(focused);
        if (row == null) return false;
        // Consume releases and repeats too, so ScrollView never scrolls the
        // page after the activity has kept focus inside its media rails.
        if (event.getAction() != KeyEvent.ACTION_DOWN || event.getRepeatCount() != 0) return true;
        String targetRow = "seasons".equals(row.getTag(FOLDER_MEDIA_ROW_TAG))
                && event.getKeyCode() == KeyEvent.KEYCODE_DPAD_DOWN ? "episodes"
                : "episodes".equals(row.getTag(FOLDER_MEDIA_ROW_TAG))
                && event.getKeyCode() == KeyEvent.KEYCODE_DPAD_UP ? "seasons" : "";
        if (targetRow.isEmpty()) return true;
        View tile = focused;
        while (tile.getParent() instanceof View && tile.getParent() != row) tile = (View) tile.getParent();
        int targetId = event.getKeyCode() == KeyEvent.KEYCODE_DPAD_UP
                ? tile.getNextFocusUpId() : tile.getNextFocusDownId();
        View target = targetId == View.NO_ID ? null : activeScreen.findViewById(targetId);
        ViewGroup destination = folderMediaRow(target);
        if (destination != null && targetRow.equals(destination.getTag(FOLDER_MEDIA_ROW_TAG))
                && target.isFocusable() && target.isShown()) target.requestFocus();
        return true;
    }

    private int settingsAccentColor() {
        return Color.rgb(255, 224, 0);
    }

    private void showHomeGridCategory(String category) {
        activeHomeGridCategory = category;
        for (String key : new String[] { "videos", "movies", "series", "live" }) {
            View section = currentHomeSectionViews.get(key);
            View spacer = currentHomeSectionSpacers.get(key);
            boolean selected = key.equals(category);
            if (section != null) section.setVisibility(selected ? View.VISIBLE : View.GONE);
            if (spacer != null) spacer.setVisibility(selected ? View.VISIBLE : View.GONE);
        }
        View section = currentHomeSectionViews.get(category);
        if (section != null) section.post(() -> {
            section.requestRectangleOnScreen(new android.graphics.Rect(0, 0, section.getWidth(), section.getHeight()), true);
            View target = section instanceof ViewGroup ? firstFocusableChild((ViewGroup) section) : null;
            if (target != null) target.requestFocus();
        });
    }

    private boolean isHomeDescendant(View child, View ancestor) {
        if (child == null || ancestor == null) return false;
        View current = child;
        while (current != null) {
            if (current == ancestor) return true;
            current = current.getParent() instanceof View ? (View) current.getParent() : null;
        }
        return false;
    }

    private boolean isContinueWatchingFocus(View focused) {
        if (focused == null) return false;
        if (isHomeDescendant(focused, currentHomeResumesView)) return true;
        for (View rows : currentExternalRows.values()) {
            if (isHomeDescendant(focused, rows)) return true;
        }
        return false;
    }

    private boolean isFocusedExternalPlaybackRow() {
        View focused = getCurrentFocus();
        for (View rows : currentExternalRows.values()) {
            if (isHomeDescendant(focused, rows)) return true;
        }
        return false;
    }

    /**
     * Replacing the resume section while any Home control owns focus makes
     * Android TV run focus search against a detached hierarchy.  The fallback
     * is usually the first header item (Accueil). Defer background refreshes
     * until focus has left the Home tree; the visible Hero is then stable.
     */
    private boolean shouldDeferHomeContentRefresh() {
        if (homeDpadNavigationActive) return true;
        View focused = getCurrentFocus();
        return currentHomeShell != null && focused != null
                && isHomeDescendant(focused, currentHomeShell);
    }

    private View topBar() {
        return topBar(HOME_HEADER_HEIGHT_DP);
    }

    private View topBar(int headerHeightDp) {
        // Navigation stays on the left while settings and status form a group
        // anchored on the right of the same header row.
        // The fixed VPN slot is placed after Apps and collapses while disconnected.
        boolean vpnActive = isVpnActive();
        final int headerHeight = dp(headerHeightDp);
        FrameLayout header = new FrameLayout(this);
        header.setTranslationY(dp(HOME_HEADER_BASE_TRANSLATION_DP));
        header.setClipToPadding(false);
        header.setClipChildren(false);
        int headerVerticalPadding = dp(headerHeightDp < 82 ? 4 : 8);
        LinearLayout bar = new LinearLayout(this); bar.setGravity(Gravity.CENTER_VERTICAL); bar.setClipChildren(false); bar.setClipToPadding(false); bar.setPadding(dp(8), headerVerticalPadding, dp(8), headerVerticalPadding);
        renderedHeaderItems.clear();
        currentTopBarHeader = header;
        boolean firstItem = true;
        boolean rightGroupStarted = false;
        for (String key : topBarItemOrder()) {
            if (hiddenTopBarItems().contains(key)) continue;
            boolean visibleRightItem = "weather".equals(key) && weatherWidgetEnabled();
            if (visibleRightItem && !rightGroupStarted) {
                View groupSpacer = new View(this);
                groupSpacer.setTag("header_group_spacer");
                bar.addView(groupSpacer, new LinearLayout.LayoutParams(0, dp(HOME_HEADER_ITEM_HEIGHT_DP), 1f));
                rightGroupStarted = true;
            }
            if (!firstItem) addHeaderGap(bar, vpnActive);
            firstItem = false;
            switch (key) {
                case "weather": {
                    if (weatherWidgetEnabled()) { View weather = weatherWidget(); bar.addView(configureTopBarItem(weather, "weather", v -> openScreen(createWeatherSettingsPage()))); }
                    break;
                }
                case "servers": {
                    View servers = headerCommand(R.drawable.ic_view_list, "Serveurs", v -> showServersOverlay(v));
                    bar.addView(configureTopBarItem(servers, "servers", null));
                    break;
                }
                case "apps": {
                    // The source Play Store asset has transparent margins.  Keep
                    // the same 46 dp command box as the other header items, but
                    // enlarge only the glyph so its visible size matches
                    // Serveurs, Réseau and Sources.
                    View apps = headerCommand(R.drawable.ic_apps_store, "Apps", v -> {
                        if (appsOpenFromHeader()) showHeaderAppsMenu(v);
                        else openScreen(createAllAppsPage());
                    }, 1.8f);
                    bar.addView(configureTopBarItem(apps, "apps", null));
                    View vpn = vpnCommand();
                    vpn.setTag("vpn");
                    vpn.setVisibility(VpnHeaderRules.showsVpn(vpnActive) ? View.VISIBLE : View.GONE);
                    activeVpnHeaderCommand = vpn;
                    bar.addView(vpn);
                    break;
                }
                case "home": {
                    // Reuse the standard header icon colours and focus effect.
                    // The home asset has more transparent padding than the
                    // other header glyphs; this scale brings its visible mark
                    // to the same size as the standard 27 dp icon box.
                    View home = headerCommand(R.drawable.jojo_home_icon_install_transparent, "Accueil", v -> onHomeHeaderClick(), 1.5f);
                    bar.addView(configureTopBarItem(home, "home", null));
                    break;
                }
                case "network": {
                    View network = networkIcon(); bar.addView(configureTopBarItem(network, "network", v -> openNetworkSettings())); break;
                }
                case "sources": {
                    View sources = headerCommand(R.drawable.ic_sources, "Sources", v -> openSystemSources()); bar.addView(configureTopBarItem(sources, "sources", null)); break;
                }
                case "search": {
                    View search = searchCommand(); bar.addView(configureTopBarItem(search, "search", null)); break;
                }
                case "settings": {
                    View settings = headerCommand(R.drawable.ic_settings, "Paramètres", this::showSettingsOverlay); bar.addView(configureTopBarItem(settings, "settings", null)); break;
                }
                case "profile": {
                    View profile = profileCommand(); bar.addView(configureTopBarItem(profile, "profile", null)); break;
                }
            }
        }
        if (HomeChromeRules.showsDateTimeInEveryHeader()) {
            if (!rightGroupStarted) {
                View groupSpacer = new View(this);
                groupSpacer.setTag("header_group_spacer");
                bar.addView(groupSpacer, new LinearLayout.LayoutParams(0, dp(HOME_HEADER_ITEM_HEIGHT_DP), 1f));
            }
            LinearLayout dateTime = new LinearLayout(this); dateTime.setOrientation(LinearLayout.VERTICAL); dateTime.setGravity(Gravity.CENTER);
            TextView clock = text(new SimpleDateFormat(HomeChromeRules.clockPattern(), Locale.FRENCH).format(new Date()), 20, Color.WHITE); clock.setGravity(Gravity.CENTER); clock.setSingleLine(true);
            clock.setTranslationY(-dp(HEADER_TEXT_ROW_RAISE_DP - 2));
            TextView date = text(headerDateLabel(), 13, Color.WHITE); date.setGravity(Gravity.CENTER); date.setSingleLine(true);
            date.setTranslationY(-dp(6));
            headerDateText = date;
            headerClockText = clock;
            date.setTag("header-date");
            clock.setTag("header-clock");
            refreshHeaderDateTime();
            // Match the compact TV clock treatment: time above, short date below.
            dateTime.addView(clock, new LinearLayout.LayoutParams(-1, dp(34)));
            dateTime.addView(date, new LinearLayout.LayoutParams(-1, dp(26)));
            dateTime.setFocusable(true);
            dateTime.setFocusableInTouchMode(true);
            dateTime.setContentDescription("Ouvrir le calendrier");
            dateTime.setOnClickListener(v -> showCalendarOverlay());
            dateTime.setOnFocusChangeListener((v, focused) -> {
                date.setTextColor(focused ? folderThemeColor() : Color.WHITE);
                clock.setTextColor(focused ? folderThemeColor() : Color.WHITE);
                dateTime.setScaleX(focused ? 1.06f : 1f);
                dateTime.setScaleY(focused ? 1.06f : 1f);
            });
            bar.addView(dateTime, new LinearLayout.LayoutParams(headerDateTimeWidth(date, clock), dp(HOME_HEADER_ITEM_HEIGHT_DP)));
        }
        layoutTopBarItems(bar);
        // Make top-bar navigation cyclic: wire left/right focus to wrap around.
        wireTopBarHorizontalFocus(bar);
        header.addView(bar, new FrameLayout.LayoutParams(-1, headerHeight));
        // A header can be hosted by the home shell or by a padded internal
        // page.  Recalculate once its real width is known so the first and
        // last controls never overflow or get cropped by that page.
        header.post(() -> {
            if (header.isAttachedToWindow()) {
                layoutTopBarItems(bar);
                wireTopBarHorizontalFocus(bar);
            }
        });
        // Bring the chrome closer to the upper edge without moving the page
        // content below it (section headings and rails keep their spacing).
        header.setTranslationY(dp(HOME_HEADER_BASE_TRANSLATION_DP));
        header.setTag(bar);
        header.setLayoutParams(new LinearLayout.LayoutParams(-1, headerHeight)); return header;
    }

    private void showHeaderAppsMenu(View anchor) {
        LinearLayout panel = new LinearLayout(this);
        panel.setOrientation(LinearLayout.VERTICAL);
        // Keep this launcher compact: it is an icon strip, not a second app
        // manager.  The inset leaves room for the normal focus enlargement.
        // Narrow the panel itself while keeping each app banner's size intact.
        panel.setPadding(dp(4), dp(14), dp(4), dp(14));
        panel.setBackground(headerAppsMenuBg());

        HeaderAppsScrollView scroll = new HeaderAppsScrollView(this);
        scroll.setVerticalScrollBarEnabled(false);
        scroll.setClipChildren(false);
        scroll.setClipToPadding(false);
        LinearLayout rows = new LinearLayout(this);
        rows.setOrientation(LinearLayout.VERTICAL);
        rows.setClipChildren(false);
        rows.setClipToPadding(false);

        final int tileWidth = headerAppsMenuTileWidth();
        final int tileHeight = Math.round(tileWidth * 9f / 16f);
        final int popupWidth = Math.round((tileWidth + dp(48)) * HEADER_APPS_MENU_WIDTH_SCALE);
        int[] anchorLocation = new int[2];
        anchor.getLocationOnScreen(anchorLocation);
        int popupHeight = Math.min(dp(520), Math.max(dp(1),
                getResources().getDisplayMetrics().heightPixels
                        - anchorLocation[1] - anchor.getHeight() - dp(44)));
        PopupWindow popup = new PopupWindow(panel, popupWidth, popupHeight, true);
        popup.setBackgroundDrawable(headerAppsMenuBg());
        popup.setOutsideTouchable(true);
        popup.setElevation(dp(14));
        trackPopup(popup);

        renderedAppRows.clear();
        renderedAppRows.add(rows);
        final View[] pendingHeaderFocus = { null };
        popup.setOnDismissListener(() -> {
            if (activePopup == popup) activePopup = null;
            dismissTransientMarquee();
            renderedAppRows.remove(rows);
            if (movingPackageName != null) movingPackageName = null;
            View target = pendingHeaderFocus[0];
            pendingHeaderFocus[0] = null;
            if (target != null && target.isAttachedToWindow()) target.post(target::requestFocus);
            else restoreHomeFocusIfNeeded();
        });
        // Give the column the full popup width so each tile's
        // CENTER_HORIZONTAL gravity is calculated against the whole panel,
        // rather than against a wrap-content column anchored on the left.
        scroll.setFillViewport(true);
        scroll.addView(rows, new ScrollView.LayoutParams(-1, -2));
        panel.addView(scroll, new LinearLayout.LayoutParams(-1, 0, 1f));
        showPopupBelow(popup, anchor, (anchor.getWidth() - popupWidth) / 2, dp(4));
        // Resolve only the persisted favorites. The previous implementation
        // rescanned every installed application before adding the first tile,
        // leaving this already-open column visibly empty for several seconds.
        LinkedHashMap<String, View> appTiles = new LinkedHashMap<>();
        View iptvTile = headerIptvMenuTile(tileWidth, tileHeight);
        wireHeaderPopupHorizontalExit(iptvTile, anchor, popup, pendingHeaderFocus);
        iptvTile.setId(View.generateViewId());
        iptvTile.setOnClickListener(v -> {
            popup.dismiss();
            openIptvModule();
        });
        LinearLayout.LayoutParams iptvParams = new LinearLayout.LayoutParams(tileWidth, tileHeight);
        iptvParams.gravity = Gravity.CENTER_HORIZONTAL;
        iptvParams.bottomMargin = -dp(3);
        iptvTile.setLayoutParams(iptvParams);
        appTiles.put("native_iptv", iptvTile);
        List<android.content.pm.ResolveInfo> available = orderedFavoriteAppsFast();
        for (android.content.pm.ResolveInfo info : available) {
            if (info == null || info.activityInfo == null) continue;
            View tile = headerAppMenuTile(info, tileWidth, tileHeight);
            wireHeaderPopupHorizontalExit(tile, anchor, popup, pendingHeaderFocus);
            tile.setId(View.generateViewId());
            String packageName = info.activityInfo.packageName;
            String appLabel = homeAppLabel(info);
            tile.setOnClickListener(v -> {
                popup.dismiss();
                openPackage(packageName, appLabel);
            });
            tile.setOnLongClickListener(v -> {
                // Reuse the normal app-management menu: the same menu can
                // remove or add the application to favorites and keeps the
                // installed app available in the picker.
                showAppMenu(info, v, popup);
                return true;
            });
            LinearLayout.LayoutParams tileParams = new LinearLayout.LayoutParams(tileWidth, tileHeight);
            tileParams.gravity = Gravity.CENTER_HORIZONTAL;
            tileParams.bottomMargin = -dp(3);
            tile.setLayoutParams(tileParams);
            appTiles.put(packageName, tile);
        }
        List<String> appKeys = new ArrayList<>(appOrder());
        if (!appKeys.contains("native_iptv")) appKeys.add(0, "native_iptv");
        for (String key : appKeys) {
            View tile = appTiles.remove(key);
            if (tile != null) rows.addView(tile);
        }
        for (View tile : appTiles.values()) rows.addView(tile);
        View addTile = appAddTile(true, anchor, popup, pendingHeaderFocus);
        addTile.setId(View.generateViewId());
        // The header tile also contains its caption. Give it the caption
        // height; otherwise the popup clips the text below the plus icon.
        LinearLayout.LayoutParams addParams = new LinearLayout.LayoutParams(
                tileWidth, tileHeight + dp(26));
        addParams.gravity = Gravity.CENTER_HORIZONTAL;
        addParams.bottomMargin = dp(4);
        rows.addView(addTile, addParams);
        addTile.setOnClickListener(v -> {
            // The header popup is still the active popup at this point. Open
            // the existing favorite-app picker only after dismissing it so
            // the picker is not rejected as a nested popup.
            popup.dismiss();
            pendingManagerFocusPackage = null;
            pendingAddFavorite = true;
            openScreen(createAddFavoritePage());
        });
        scroll.wireFocus();
        focusFirst(rows);
    }

    private View headerAppMenuTile(android.content.pm.ResolveInfo info, int tileWidth, int tileHeight) {
        ImageView icon = new AppIconImageView(this);
        android.graphics.drawable.Drawable activityBanner = info.activityInfo.loadBanner(getPackageManager());
        android.graphics.drawable.Drawable applicationBanner = info.activityInfo.applicationInfo.loadBanner(getPackageManager());
        boolean officialCanalPlus = AppTileRules.usesOfficialCanalPlusBanner(info.activityInfo.packageName);
        android.graphics.drawable.Drawable banner = officialCanalPlus ? officialCanalPlusBanner()
                : (AppTileRules.usesApplicationBannerBeforeActivityBanner() && applicationBanner != null
                ? applicationBanner : activityBanner);
        android.graphics.drawable.Drawable custom = appIconDrawable(info.activityInfo.packageName);
        String onlineIconId = onlineAppIconId(info.activityInfo.packageName);
        boolean smartTube = isSmartTube(info.activityInfo.packageName);
        boolean centeredFallbackIcon = AppTileRules.usesCenteredFallbackIcon(banner != null, custom != null || !onlineIconId.isEmpty());
        android.graphics.drawable.Drawable source = custom != null ? custom
                : (smartTube ? info.loadIcon(getPackageManager())
                : (banner != null ? banner : info.loadIcon(getPackageManager())));
        boolean recenteredBanner = AppTileRules.requiresRecenteredBanner(info.activityInfo.packageName);
        int fallbackTileColor = (centeredFallbackIcon || recenteredBanner)
                ? AppTileRules.fallbackTileColor(info.activityInfo.packageName) : Color.TRANSPARENT;
        icon.setImageDrawable(source);
        if (!onlineIconId.isEmpty()) OnlineAppIconLoader.load(icon, onlineIconId);
        icon.setScaleType(ImageView.ScaleType.CENTER_INSIDE);
        // Every app artwork gets the same 16:9 viewport. Extra per-app inset
        // values made fallback icons (especially SmartTube) visibly smaller.
        icon.setPadding(0, 0, 0, 0);
        icon.setBackground(!onlineIconId.isEmpty() ? onlineAppIconBackground()
                : (smartTube ? smartTubeBg() : (fallbackTileColor != Color.TRANSPARENT
                ? new android.graphics.drawable.ColorDrawable(fallbackTileColor)
                : new android.graphics.drawable.ColorDrawable(Color.TRANSPARENT))));
        return headerAppMenuTile(icon, info.activityInfo.packageName, homeAppLabel(info), tileWidth, tileHeight);
    }

