    private View headerAppMenuTile(ImageView icon, String itemKey, String label, int tileWidth, int tileHeight) {
        FrameLayout tile = new FrameLayout(this);
        tile.setFocusable(true);
        tile.setClipChildren(false);
        tile.setClipToPadding(false);
        FrameLayout stage = new FrameLayout(this);
        stage.setBackgroundColor(Color.TRANSPARENT);
        stage.setClipChildren(true);
        stage.setClipToPadding(true);
        FrameLayout iconFrame = new FrameLayout(this);
        iconFrame.setClipChildren(true);
        iconFrame.setClipToPadding(true);
        stage.addView(iconFrame, new FrameLayout.LayoutParams(
                Math.round(tileWidth * .8f), Math.round(tileHeight * .8f), Gravity.CENTER));
        iconFrame.addView(icon, new FrameLayout.LayoutParams(-1, -1));
        tile.addView(stage, new FrameLayout.LayoutParams(-1, -1));
        tile.setScaleX(1f);
        tile.setScaleY(1f);
        tile.setOnFocusChangeListener((view, focused) -> {
            float focusedScale = headerAppsMenuFocusScale();
            tile.animate().cancel();
            tile.animate().withLayer().scaleX(focused ? focusedScale : 1f)
                    .scaleY(focused ? focusedScale : 1f).setDuration(120).start();
        });
        tile.setTag(itemKey);
        tile.setContentDescription(label);
        return tile;
    }

    private void wireHeaderPopupHorizontalExit(View row, View headerAnchor,
                                              PopupWindow popup, View[] pendingHeaderFocus) {
        row.setOnKeyListener((view, keyCode, event) ->
                handleHeaderPopupHorizontalExit(headerAnchor, popup, pendingHeaderFocus, keyCode, event));
    }

    private boolean handleHeaderPopupHorizontalExit(View headerAnchor, PopupWindow popup,
                                                    View[] pendingHeaderFocus, int keyCode,
                                                    KeyEvent event) {
        if (movingPackageName != null && event.getAction() == KeyEvent.ACTION_DOWN) {
            if (event.getRepeatCount() != 0) return true;
            if (keyCode == KeyEvent.KEYCODE_DPAD_UP) { moveApp(-1); return true; }
            if (keyCode == KeyEvent.KEYCODE_DPAD_DOWN) { moveApp(1); return true; }
            if (keyCode == KeyEvent.KEYCODE_DPAD_LEFT || keyCode == KeyEvent.KEYCODE_DPAD_RIGHT) return true;
            if (keyCode == KeyEvent.KEYCODE_DPAD_CENTER || keyCode == KeyEvent.KEYCODE_ENTER
                    || keyCode == KeyEvent.KEYCODE_BACK) {
                finishAppMove();
                return true;
            }
        }
        if (event.getAction() != KeyEvent.ACTION_DOWN || event.getRepeatCount() != 0
                || (keyCode != KeyEvent.KEYCODE_DPAD_LEFT && keyCode != KeyEvent.KEYCODE_DPAD_RIGHT)) {
            return false;
        }
        ViewParent anchorParent = headerAnchor.getParent();
        if (!(anchorParent instanceof LinearLayout)) return false;
        List<View> headerItems = immediateFocusableChildren((LinearLayout) anchorParent);
        int currentIndex = headerItems.indexOf(headerAnchor);
        if (currentIndex < 0 || headerItems.size() < 2) return false;
        int direction = keyCode == KeyEvent.KEYCODE_DPAD_LEFT ? -1 : 1;
        int targetIndex = (currentIndex + direction + headerItems.size()) % headerItems.size();
        View target = headerItems.get(targetIndex);
        if (target == null || target == headerAnchor) return false;
        pendingHeaderFocus[0] = target;
        popup.dismiss();
        target.post(() -> {
            if (target.isAttachedToWindow() && !target.hasFocus()) target.requestFocus();
        });
        return true;
    }

    private int headerAppsMenuTileWidth() {
        return Math.min(dp(160), dp(iconTileWidth()));
    }

    private void wireTopBarHorizontalFocus(LinearLayout bar) {
        List<View> focusableItems = immediateFocusableChildren(bar);
        if (focusableItems.size() > 1) {
            for (int i = 0; i < focusableItems.size(); i++) {
                View v = focusableItems.get(i);
                if (v.getId() == View.NO_ID) v.setId(View.generateViewId());
            }
            for (int i = 0; i < focusableItems.size(); i++) {
                View v = focusableItems.get(i);
                int leftIndex = (i == 0) ? (focusableItems.size() - 1) : (i - 1);
                int rightIndex = (i == focusableItems.size() - 1) ? 0 : (i + 1);
                v.setNextFocusLeftId(focusableItems.get(leftIndex).getId());
                v.setNextFocusRightId(focusableItems.get(rightIndex).getId());
            }
        }
    }

    private View configureTopBarItem(View item, String key, View.OnClickListener click) {
        item.setTag(key);
        if (click != null) item.setOnClickListener(click);
        item.setOnLongClickListener(v -> { showTopBarItemMenu(key, v); return true; });
        renderedHeaderItems.add(item);
        return item;
    }

    private static final class CalendarEvent {
        final long id; final String title; final String location; final long start; final long end; final int color;
        CalendarEvent(long id, String title, String location, long start, long end, int color) { this.id = id; this.title = title; this.location = location; this.start = start; this.end = end; this.color = color; }
    }
    private String calendarDayKey(java.util.Calendar day) { return new SimpleDateFormat("yyyy-MM-dd", Locale.US).format(day.getTime()); }
    private ArrayList<CalendarEvent> readCalendarEvents(long start, long end) {
        ArrayList<CalendarEvent> result = new ArrayList<>();
        if (Build.VERSION.SDK_INT >= 23 && checkSelfPermission(Manifest.permission.READ_CALENDAR) != PackageManager.PERMISSION_GRANTED) return result;
        String[] projection = { "_id", "title", "eventLocation", "dtstart", "dtend", "allDay", "eventColor" };
        try (android.database.Cursor cursor = getContentResolver().query(android.provider.CalendarContract.Events.CONTENT_URI, projection, "dtstart < ? AND (dtend IS NULL OR dtend >= ?)", new String[] { String.valueOf(end), String.valueOf(start) }, "dtstart ASC")) {
            if (cursor == null) return result;
            int idIndex = cursor.getColumnIndex("_id"), titleIndex = cursor.getColumnIndex("title"), locationIndex = cursor.getColumnIndex("eventLocation");
            int startIndex = cursor.getColumnIndex("dtstart"), endIndex = cursor.getColumnIndex("dtend"), colorIndex = cursor.getColumnIndex("eventColor");
            while (cursor.moveToNext()) {
                long eventStart = cursor.getLong(startIndex), eventEnd = endIndex >= 0 && !cursor.isNull(endIndex) ? cursor.getLong(endIndex) : eventStart + 3_600_000L;
                result.add(new CalendarEvent(cursor.getLong(idIndex), cursor.getString(titleIndex), locationIndex >= 0 ? cursor.getString(locationIndex) : "", eventStart, eventEnd, colorIndex >= 0 && !cursor.isNull(colorIndex) ? cursor.getInt(colorIndex) : Color.rgb(93, 180, 255)));
            }
        } catch (Exception ignored) { }
        return result;
    }
    private java.util.Map<String, String> frenchHolidays(int year) {
        java.util.Map<String, String> holidays = new java.util.HashMap<>();
        String[] fixed = { "01-01|Jour de l’An", "05-01|Fête du Travail", "05-08|Victoire 1945", "07-14|Fête nationale", "08-15|Assomption", "11-01|Toussaint", "11-11|Armistice", "12-25|Noël" };
        for (String value : fixed) { String[] parts = value.split("\\|", 2); holidays.put(year + "-" + parts[0], parts[1]); }
        java.util.Calendar easter = java.util.Calendar.getInstance(); easter.clear(); easter.set(year, java.util.Calendar.MARCH, 1); int day = easter.getActualMaximum(java.util.Calendar.DAY_OF_MONTH); easter.set(java.util.Calendar.MARCH, day); int a = year % 19, b = year / 100, c = year % 100, d = b / 4, e = b % 4, f = (b + 8) / 25, g = (b - f + 1) / 3, h = (19 * a + b - d - g + 15) % 30, i = c / 4, k = c % 4, l = (32 + 2 * e + 2 * i - h - k) % 7, m = (a + 11 * h + 22 * l) / 451, month = (h + l - 7 * m + 114) / 31, date = (h + l - 7 * m + 114) % 31 + 1; easter.set(year, month - 1, date);
        java.util.Calendar holiday = (java.util.Calendar) easter.clone(); holiday.add(java.util.Calendar.DAY_OF_MONTH, 1); holidays.put(calendarDayKey(holiday), "Lundi de Pâques"); holiday = (java.util.Calendar) easter.clone(); holiday.add(java.util.Calendar.DAY_OF_MONTH, 39); holidays.put(calendarDayKey(holiday), "Ascension"); holiday = (java.util.Calendar) easter.clone(); holiday.add(java.util.Calendar.DAY_OF_MONTH, 50); holidays.put(calendarDayKey(holiday), "Lundi de Pentecôte");
        return holidays;
    }
    private String calendarDurationLabel(CalendarEvent event) { long minutes = Math.max(0L, (event.end - event.start) / 60_000L); if (minutes < 60L) return minutes + " min"; long hours = minutes / 60L; long rest = minutes % 60L; return rest == 0L ? hours + " h" : hours + " h " + rest; }
    private String calendarEventLabel(CalendarEvent event) { String time = new SimpleDateFormat("HH:mm", Locale.FRANCE).format(new Date(event.start)); String detail = event.location == null || event.location.trim().isEmpty() ? "" : " · " + event.location.trim(); return time + "  " + (event.title == null || event.title.trim().isEmpty() ? "Événement" : event.title.trim()) + " (" + calendarDurationLabel(event) + ")" + detail; }
    private String calendarCountdown(CalendarEvent event) { long minutes = Math.max(0L, (event.start - System.currentTimeMillis()) / 60_000L); if (minutes < 60L) return "Dans " + minutes + " min"; long hours = minutes / 60L; long rest = minutes % 60L; return rest == 0L ? "Dans " + hours + " h" : "Dans " + hours + " h " + rest; }
    private void openCalendarEvent(CalendarEvent event) { try { startActivity(new Intent(Intent.ACTION_VIEW, ContentUris.withAppendedId(android.provider.CalendarContract.Events.CONTENT_URI, event.id))); } catch (Exception ignored) { Toast.makeText(this, "Événement indisponible", Toast.LENGTH_SHORT).show(); } }
    /** Opens Android's event editor already positioned on the chosen calendar day. */
    private void addCalendarEvent(java.util.Calendar day) {
        java.util.Calendar start = (java.util.Calendar) day.clone();
        start.set(java.util.Calendar.SECOND, 0);
        start.set(java.util.Calendar.MILLISECOND, 0);
        java.util.Calendar now = java.util.Calendar.getInstance(Locale.FRANCE);
        boolean isToday = calendarDayKey(start).equals(calendarDayKey(now));
        if (isToday) {
            start.set(java.util.Calendar.HOUR_OF_DAY, now.get(java.util.Calendar.HOUR_OF_DAY));
            start.set(java.util.Calendar.MINUTE, now.get(java.util.Calendar.MINUTE));
            start.add(java.util.Calendar.MINUTE, 30 - start.get(java.util.Calendar.MINUTE) % 30);
        } else {
            start.set(java.util.Calendar.HOUR_OF_DAY, 9);
            start.set(java.util.Calendar.MINUTE, 0);
        }
        java.util.Calendar end = (java.util.Calendar) start.clone();
        end.add(java.util.Calendar.HOUR_OF_DAY, 1);
        try {
            Intent intent = new Intent(Intent.ACTION_INSERT, android.provider.CalendarContract.Events.CONTENT_URI)
                    .putExtra(android.provider.CalendarContract.EXTRA_EVENT_BEGIN_TIME, start.getTimeInMillis())
                    .putExtra(android.provider.CalendarContract.EXTRA_EVENT_END_TIME, end.getTimeInMillis());
            startActivity(intent);
        } catch (Exception ignored) {
            Toast.makeText(this, "Aucune application de calendrier ne permet d’ajouter un événement", Toast.LENGTH_LONG).show();
        }
    }
    private void scheduleCalendarReminders(List<CalendarEvent> events) {
        if (Build.VERSION.SDK_INT >= 33 && checkSelfPermission("android.permission.POST_NOTIFICATIONS") != PackageManager.PERMISSION_GRANTED) return;
        android.app.AlarmManager alarms = (android.app.AlarmManager) getSystemService(ALARM_SERVICE); if (alarms == null) return;
        long now = System.currentTimeMillis();
        for (CalendarEvent event : events) {
            long trigger = event.start - 10L * 60L * 1000L;
            if (trigger <= now || trigger > now + 31L * 24L * 60L * 60L * 1000L) continue;
            Intent reminder = new Intent(this, CalendarReminderReceiver.class).putExtra("event_id", (int) event.id).putExtra("title", event.title).putExtra("location", event.location);
            PendingIntent pending = PendingIntent.getBroadcast(this, (int) event.id, reminder, PendingIntent.FLAG_UPDATE_CURRENT | PendingIntent.FLAG_IMMUTABLE);
            alarms.setAndAllowWhileIdle(android.app.AlarmManager.RTC_WAKEUP, trigger, pending);
        }
    }

