    private View searchCommand() {
        LinearLayout command = new LinearLayout(this);
        command.setOrientation(LinearLayout.VERTICAL);
        command.setGravity(Gravity.CENTER);
        command.setContentDescription("Rechercher");
        command.setFocusable(true);
        command.setClipChildren(false);
        command.setClipToPadding(false);
        command.setPadding(dp(4), 0, dp(4), 0);

        FrameLayout iconContainer = new FrameLayout(this);
        iconContainer.setClipToPadding(false);
        iconContainer.setClipChildren(false);
        iconContainer.setBackground(topBarIconBg(false));
        ImageView icon = new ImageView(this);
        icon.setTag("header_icon");
        icon.setImageResource(R.drawable.ic_header_search);
        icon.setAlpha(1f);
        icon.setColorFilter(Color.WHITE, android.graphics.PorterDuff.Mode.SRC_IN);
        // Keep the original visual weight and focus behavior; only the
        // Assistant mark becomes a conventional search loupe.
        iconContainer.addView(icon, new FrameLayout.LayoutParams(dp(27), dp(27), Gravity.CENTER));

        TextView label = text("Rechercher", 9, muted);
        label.setGravity(Gravity.CENTER_VERTICAL);
        label.setSingleLine(true);
        LinearLayout content = new LinearLayout(this);
        content.setGravity(Gravity.CENTER_VERTICAL);
        content.setClipChildren(false);
        content.setClipToPadding(false);
        content.addView(iconContainer, new LinearLayout.LayoutParams(dp(46), dp(46)));
        LinearLayout.LayoutParams labelParams = new LinearLayout.LayoutParams(headerLabelWidth("Rechercher"), dp(46));
        labelParams.leftMargin = dp(2);
        content.addView(label, labelParams);
        command.addView(content, new LinearLayout.LayoutParams(-2, dp(46)));
        command.addView(headerFocusIndicator(), headerFocusIndicatorParams("Rechercher"));
        // Search is handled entirely by Jojo Home. Do not open the Android TV
        // Assistant choices (microphone/keyboard) from the header.
        command.setOnClickListener(v -> openTextSearch());
        command.setOnFocusChangeListener((v, focused) -> {
            iconContainer.setBackground(topBarIconBg(focused));
            command.animate().scaleX(focused ? 1.14f : 1f).scaleY(focused ? 1.14f : 1f).setDuration(120).start();
            label.setTextColor(focused ? folderThemeColor() : muted);
            label.setTypeface(null, focused ? 1 : 0);
            updateHeaderFocusIndicator(command, focused);
        icon.setAlpha(1f);
        icon.setColorFilter(focused ? folderThemeColor() : Color.WHITE, android.graphics.PorterDuff.Mode.SRC_IN);
        });
        command.setLayoutParams(new LinearLayout.LayoutParams(
                dp(46) + dp(6) + headerLabelWidth("Rechercher"), dp(HOME_HEADER_ITEM_HEIGHT_DP)));
        return command;
    }

