    private android.graphics.drawable.Drawable topBarIconBg(boolean focused) {
        GradientDrawable d = new GradientDrawable();
        d.setShape(GradientDrawable.OVAL);
        if (focused) {
            d.setColor(Color.WHITE);
            d.setStroke(dp(1), Color.argb(160, 200, 200, 255));
        } else {
            d.setColor(Color.TRANSPARENT);
        }
        // The command itself still occupies the common 46 dp header column,
        // but the focus disc is inset so it no longer touches the text row.
        return new InsetDrawable(d, dp(3));
    }

