    private List<String> defaultTopBarItems() {
        List<String> list = new ArrayList<>();
        list.add("home");
        list.add("profile");
        list.add("settings");
        list.add("apps");
        list.add("search");
        list.add("weather");
        return list;
    }

    private List<String> topBarItemOrder() {
        String serialized = homePrefs().getString("top_bar_order", "");
        // Migrate the former built-in order once so existing installations
        // receive the new left group and weather/date block placement.
        if ("home|apps|search|weather|settings|profile".equals(serialized)) serialized = "";
        if (serialized.isEmpty()) return defaultTopBarItems();
        List<String> result = new ArrayList<>();
        for (String key : serialized.split("\\|")) {
            String migrated = "storage".equals(key) || "nas".equals(key) ? "servers" : key;
            if (!result.contains(migrated)) result.add(migrated);
        }
        for (String key : defaultTopBarItems()) if (!result.contains(key)) result.add(key);
        // IPTV now lives in the Apps column, including for restored orders.
        result.remove("iptv");
        result.remove("iptv2");
        // These device actions now live in the Parameters menu. Remove them
        // from persisted orders too, so a synced legacy order cannot restore
        // the old crowded header.
        result.remove("servers");
        result.remove("network");
        result.remove("vpn");
        result.remove("sources");
        int searchIndex = result.indexOf("search");
        int weatherIndex = result.indexOf("weather");
        if (searchIndex >= 0 && weatherIndex >= 0 && weatherIndex < searchIndex) {
            result.remove(searchIndex);
            result.add(weatherIndex, "search");
        }
        // Keep the requested navigation order at the start of the header.
        // Weather is the first status control after the flexible spacer, so it
        // is rendered directly before the date/time block.
        result.remove("home");
        result.remove("profile");
        result.remove("settings");
        result.remove("apps");
        result.remove("iptv");
        result.remove("search");
        result.remove("weather");
        result.add(0, "home");
        result.add(1, "profile");
        result.add(2, "settings");
        result.add(3, "apps");
        result.add(4, "search");
        result.add(5, "weather");
        return result;
    }

    private void saveTopBarItemOrder(List<String> order) {
        homePrefs().edit().putString("top_bar_order", joinOrder(order)).apply();
    }

    private Set<String> hiddenTopBarItems() {
        Set<String> hidden = new HashSet<>(homePrefs().getStringSet("hidden_top_bar_items", new HashSet<>()));
        if (hidden.contains("storage") || hidden.contains("nas")) hidden.add("servers");
        // VPN is a permanent shortcut; it must not disappear when an older
        // saved header configuration contains it in the hidden set.
        hidden.remove("vpn");
        return hidden;
    }

    private void saveHiddenTopBarItems(Set<String> hidden) {
        homePrefs().edit().putStringSet("hidden_top_bar_items", hidden).apply();
    }

    private void showTopBarItemMenu(String key, View anchor) {
        LinearLayout menu = new LinearLayout(this); menu.setOrientation(LinearLayout.VERTICAL); menu.setPadding(0, 0, 0, 0); menu.setBackground(lightMenuBg());
        PopupWindow popup = new PopupWindow(menu, dp(264), -2, true); popup.setBackgroundDrawable(lightMenuBg()); popup.setOutsideTouchable(true); popup.setElevation(dp(12)); trackPopup(popup);
        View open = popupRow(R.drawable.ic_menu_open, "Ouvrir");
        View move = popupRow(R.drawable.ic_menu_move, "Déplacer");
        View remove = popupRow(R.drawable.ic_menu_delete, "Supprimer");
        menu.addView(open); menu.addView(move); menu.addView(remove);
        finalizePopupMenu(menu);
        open.setOnClickListener(v -> { popup.dismiss(); openTopBarItem(key, anchor); });
        move.setOnClickListener(v -> { popup.dismiss(); beginTopBarMove(key); });
        remove.setOnClickListener(v -> { popup.dismiss(); Set<String> hidden = hiddenTopBarItems(); hidden.add(key); saveHiddenTopBarItems(hidden); refreshTopBarHeader(); });
        showPopupBelow(popup, anchor, -dp(14), dp(6)); open.requestFocus();
    }

    private void openTopBarItem(String key, View anchor) {
        switch (key) {
            case "iptv": openIptvModule(); break;
            case "search": openTextSearch(); break;
            case "weather": openScreen(createWeatherSettingsPage()); break;
            case "home": goHome(); break;
            case "servers": showServersOverlay(anchor); break;
            case "network": openNetworkSettings(); break;
            case "vpn": openActiveVpnProvider(); break;
            case "sources": openSystemSources(); break;
            case "settings": showSettingsOverlay(anchor); break;
            case "profile": showProfileOverlay(anchor); break;
        }
    }

