    private void showServersOverlay(View anchor) {
        LinearLayout menu = new LinearLayout(this);
        menu.setOrientation(LinearLayout.VERTICAL);
        menu.setPadding(dp(12), dp(10), dp(12), dp(10));
        menu.setClipChildren(false);
        menu.setClipToPadding(false);
        menu.setBackground(settingsOverlayBg());
        ScrollView scroll = new ScrollView(this);
        scroll.setFocusable(false);
        scroll.addView(menu, new ScrollView.LayoutParams(-1, -2));
        PopupWindow popup = new PopupWindow(scroll, -2, -2, true);
        popup.setBackgroundDrawable(settingsOverlayBg());
        popup.setOutsideTouchable(true);
        popup.setElevation(dp(18));
        trackPopup(popup);

        View local = settingsOverlayRow(R.drawable.ic_view_list, "Local", localStorageFreeLabel());
        List<View> rows = new ArrayList<>();
        rows.add(local);
        List<SmbConnectionConfig> connections = smbConnections();
        if (connections.isEmpty()) {
            View nas = settingsOverlayRow(R.drawable.ic_view_list, "NAS", "Non configuré");
            nas.setOnClickListener(v -> { popup.dismiss(); openScreen(createSmbSetup()); });
            rows.add(nas);
        } else {
            for (SmbConnectionConfig connection : connections) {
                View server = settingsOverlayRow(R.drawable.ic_view_list, connection.displayLabel(), smbStatusLabel(connection));
                TextView capacity = (TextView) ((LinearLayout) ((LinearLayout) server).getChildAt(1)).getChildAt(1);
                capacity.post(() -> refreshSmbStatus(capacity, connection));
                server.setOnClickListener(v -> { popup.dismiss(); openSmbConnectionBrowser(connection); });
                rows.add(server);
            }
        }
        View add = settingsOverlayRow(R.drawable.ic_menu_upload, "Ajouter un serveur", "Ajouter un partage réseau SMB");
        rows.add(add);
        int widestRow = 0;
        for (View row : rows) {
            LinearLayout copy = (LinearLayout) ((LinearLayout) row).getChildAt(1);
            TextView title = (TextView) copy.getChildAt(0);
            TextView detail = (TextView) copy.getChildAt(1);
            title.setEllipsize(TextUtils.TruncateAt.END);
            int textWidth = (int) Math.ceil(Math.max(
                    title.getPaint().measureText(title.getText().toString()),
                    detail.getPaint().measureText(detail.getText().toString())));
            int rowWidth = dp(90) + textWidth; // Icon, internal padding and 8 dp after the text.
            widestRow = Math.max(widestRow, rowWidth);
        }
        widestRow = Math.min(widestRow, Math.min(dp(520), getResources().getDisplayMetrics().widthPixels - dp(48)));
        for (View row : rows) {
            row.setId(View.generateViewId());
            menu.addView(row, new LinearLayout.LayoutParams(widestRow, dp(66)));
        }
        popup.setWidth(widestRow + dp(24)); // 12 dp menu padding on each side.
        int[] anchorLocation = new int[2];
        anchor.getLocationOnScreen(anchorLocation);
        int availableHeight = Math.max(dp(66), getResources().getDisplayMetrics().heightPixels
                - anchorLocation[1] - anchor.getHeight() - dp(48));
        popup.setHeight(Math.min(dp(20) + rows.size() * dp(66), Math.min(dp(445), availableHeight)));
        wireCyclicVerticalFocus(rows.toArray(new View[0]));
        local.setOnClickListener(v -> { popup.dismiss(); openScreen(createLocalBrowser(null)); });
        add.setOnClickListener(v -> { popup.dismiss(); openScreen(createSmbConnectionsPage()); });
        showPopupBelow(popup, anchor, -dp(14), dp(6));
        local.requestFocus();
    }

    private void beginTopBarMove(String key) {
        movingHeaderItemKey = key;
        applyTopBarMovePresentation();
    }

    private void finishTopBarMove() {
        if (movingHeaderItemKey == null) return;
        String confirmedKey = movingHeaderItemKey;
        movingHeaderItemKey = null;
        applyTopBarMovePresentation();
        if (currentTopBarHeader != null) {
            View target = findTopBarItemByKey(currentTopBarHeader, confirmedKey);
            if (target != null) target.requestFocus();
        }
    }

    private void applyTopBarMovePresentation() {
        if (currentTopBarHeader == null) return;
        LinearLayout bar = (LinearLayout) currentTopBarHeader.getTag(); if (bar == null) return;
        for (int i = 0; i < bar.getChildCount(); i++) {
            View child = bar.getChildAt(i);
            Object tag = child.getTag();
            boolean moving = tag instanceof String && tag.equals(movingHeaderItemKey);
            float targetAlpha = moving ? 1f : (movingHeaderItemKey == null ? 1f : .5f);
            float targetScale = moving ? 1.12f : 1f;
            child.animate().alpha(targetAlpha).scaleX(targetScale).scaleY(targetScale).setDuration(120).start();
        }
    }

    private void moveTopBarItem(int delta) {
        if (movingHeaderItemKey == null || currentTopBarHeader == null) return;
        LinearLayout bar = (LinearLayout) currentTopBarHeader.getTag();
        if (bar == null || bar.getChildCount() < 2) return;
        List<View> visibleViews = new ArrayList<>();
        List<String> visibleKeys = new ArrayList<>();
        for (int i = 0; i < bar.getChildCount(); i++) {
            View child = bar.getChildAt(i);
            if (child.getTag() instanceof String) {
                visibleViews.add(child);
                visibleKeys.add((String) child.getTag());
            }
        }
        int fromIndex = visibleKeys.indexOf(movingHeaderItemKey);
        if (fromIndex < 0) return;
        int targetIndex = fromIndex + delta;
        if (targetIndex < 0 || targetIndex >= visibleKeys.size()) return;
        if (fromIndex == targetIndex) return;
        View movingView = visibleViews.get(fromIndex);
        View replacementView = visibleViews.get(targetIndex);
        int fromChildIndex = bar.indexOfChild(movingView);
        int toChildIndex = bar.indexOfChild(replacementView);
        if (fromChildIndex < 0 || toChildIndex < 0) return;
        bar.removeViewAt(fromChildIndex);
        if (fromChildIndex < toChildIndex) toChildIndex--;
        bar.addView(movingView, toChildIndex);
        Collections.swap(visibleKeys, fromIndex, targetIndex);
        List<String> order = topBarItemOrder();
        Set<String> hidden = hiddenTopBarItems();
        List<String> rebuiltOrder = new ArrayList<>();
        Iterator<String> visibleIterator = visibleKeys.iterator();
        for (String key : order) {
            if (hidden.contains(key)) rebuiltOrder.add(key);
            else rebuiltOrder.add(visibleIterator.next());
        }
        saveTopBarItemOrder(rebuiltOrder);
        applyTopBarMovePresentation();
        movingView.requestFocus();
    }

    private void refreshTopBarHeader() {
        if (currentTopBarHeader == null) return;
        rememberHomeFocus();
        String focusKey = lastHomeFocusKey;
        ViewGroup parent = (ViewGroup) currentTopBarHeader.getParent();
        if (parent == null) return;
        int index = parent.indexOfChild(currentTopBarHeader);
        ViewGroup.LayoutParams headerParams = currentTopBarHeader.getLayoutParams();
        parent.removeView(currentTopBarHeader);
        View newHeader = topBar();
        currentTopBarHeader = (FrameLayout) newHeader;
        parent.addView(newHeader, index, headerParams);
        if (movingHeaderItemKey != null) {
            View target = findTopBarItemByKey(newHeader, movingHeaderItemKey);
            if (target != null) target.requestFocus();
        } else if (focusKey != null) {
            View target = findTopBarItemByKey(newHeader, focusKey);
            if (target != null) {
                lastHomeFocus = target;
                target.post(target::requestFocus);
            }
        }
    }

    private View findTopBarItemByKey(View root, String key) {
        if (root == null) return null;
        if (key.equals(root.getTag())) return root;
        if (root instanceof ViewGroup) {
            ViewGroup group = (ViewGroup) root;
            for (int i = 0; i < group.getChildCount(); i++) {
                View result = findTopBarItemByKey(group.getChildAt(i), key);
                if (result != null) return result;
            }
        }
        return null;
    }

    private String topBarItemTitle(String key) {
        switch (key) {
            case "iptv": return "IPTV";
            case "search": return "Rechercher";
            case "weather": return "Météo";
            case "home": return "Accueil";
            case "apps": return "Apps";
            case "storage": return "Stockage";
            case "nas": return "NAS";
            case "network": return "Réseau";
            case "vpn": return "VPN";
            case "sources": return "Sources";
            case "settings": return "Paramètres";
            case "profile": return "Compte";
            default: return "Élément";
        }
    }

    private View createHomeHeaderSettingsPage() {
        LinearLayout options = new LinearLayout(this); options.setOrientation(LinearLayout.VERTICAL);
        for (String key : defaultTopBarItems()) {
            boolean hidden = hiddenTopBarItems().contains(key);
            TextView row = selectedSettingsRow(topBarItemTitle(key), hidden ? "Masqué" : "Visible", v -> {
                Set<String> hiddenItems = hiddenTopBarItems();
                if (hidden) hiddenItems.remove(key); else hiddenItems.add(key);
                saveHiddenTopBarItems(hiddenItems);
                replaceScreen(createHomeHeaderSettingsPage());
            });
            row.setTag("topbar_setting_" + key);
            options.addView(row, new LinearLayout.LayoutParams(dp(520), dp(72)));
        }
        TextView resetTopBar = settingsRow("Réinitialiser la barre du haut", "", v -> showTopBarResetConfirm());
        resetTopBar.setSingleLine(true);
        resetTopBar.setGravity(Gravity.CENTER);
        resetTopBar.setMinHeight(dp(72));
        options.addView(resetTopBar, new LinearLayout.LayoutParams(dp(520), dp(72)));
        // removed: "Teinter icônes" option (handled as fixed behavior)
        return createSettingsOptionsPage("Barre du haut", options, true);
    }

    // tint header icons on focus setting removed

    private void wireHomeHeaderDpad(View header, LinearLayout apps, View homeFiles, View resumes) {
        if (!(header.getTag() instanceof LinearLayout)) return;
        // Both sections are wrapped in non-focusable layout containers. Resolve
        // the real horizontal rails instead of assuming the first child is the
        // HorizontalScrollView itself.
        List<View> appTopRowTargets = findFirstHorizontalRowFocusableChildren(apps);
        List<View> headerControls = immediateFocusableChildren((LinearLayout) header.getTag());
        if (headerControls.isEmpty()) return;
        List<View> homeFilesTargets = homeFiles instanceof ViewGroup
                ? findFirstHorizontalRowFocusableChildren((ViewGroup) homeFiles)
                : new ArrayList<>();
        List<View> resumeTargets = resumes instanceof ViewGroup ? findFirstHorizontalRowFocusableChildren((ViewGroup) resumes) : new ArrayList<>();

        if (appTopRowTargets.isEmpty()) {
            List<View> firstVisibleTargets = new ArrayList<>();
            for (String section : homeSectionOrder(homeFiles != null, !resumeTargets.isEmpty())) {
                List<View> candidate = "shortcuts".equals(section) ? homeFilesTargets
                        : "resumes".equals(section) ? resumeTargets
                        : currentHomeSectionViews.get(section) instanceof ViewGroup
                                ? findFirstHorizontalRowFocusableChildren((ViewGroup) currentHomeSectionViews.get(section))
                                : new ArrayList<>();
                if (!candidate.isEmpty()) { firstVisibleTargets = candidate; break; }
            }
            if (firstVisibleTargets.isEmpty()) return;
            for (int index = 0; index < headerControls.size(); index++) {
                View control = headerControls.get(index);
                View left = headerControls.get(index == 0 ? headerControls.size() - 1 : index - 1);
                View right = headerControls.get(index == headerControls.size() - 1 ? 0 : index + 1);
                View alignedDown = alignedTarget(firstVisibleTargets, index);
                if (control.getId() == View.NO_ID) control.setId(View.generateViewId());
                if (left.getId() == View.NO_ID) left.setId(View.generateViewId());
                if (right.getId() == View.NO_ID) right.setId(View.generateViewId());
                if (alignedDown.getId() == View.NO_ID) alignedDown.setId(View.generateViewId());
                control.setNextFocusLeftId(left.getId());
                control.setNextFocusRightId(right.getId());
                control.setNextFocusDownId(alignedDown.getId());
            }
            for (int index = 0; index < firstVisibleTargets.size(); index++) {
                View target = firstVisibleTargets.get(index);
                View alignedUp = alignedTarget(headerControls, index);
                if (target.getId() == View.NO_ID) target.setId(View.generateViewId());
                if (alignedUp.getId() == View.NO_ID) alignedUp.setId(View.generateViewId());
                target.setNextFocusUpId(alignedUp.getId());
            }
            return;
        }
        View firstApp = appTopRowTargets.get(0);
        if (firstApp.getId() == View.NO_ID) firstApp.setId(View.generateViewId());

        List<View> downTargets;
        if (!homeFilesTargets.isEmpty() && homeSectionBeforeApps("shortcuts")) {
            downTargets = homeFilesTargets;
        } else {
            downTargets = appTopRowTargets;
            // Applications can be moved below the other Home sections. Use
            // the actual first visible section instead of always dropping
            // from the header into Applications.
            for (String section : homeSectionOrder(homeFiles != null, !resumeTargets.isEmpty())) {
                List<View> candidate = "apps".equals(section) ? appTopRowTargets
                        : "resumes".equals(section) ? resumeTargets
                        : currentHomeSectionViews.get(section) instanceof ViewGroup
                                ? findFirstHorizontalRowFocusableChildren((ViewGroup) currentHomeSectionViews.get(section))
                                : new ArrayList<>();
                if (!candidate.isEmpty()) { downTargets = candidate; break; }
            }
        }
        if (downTargets.isEmpty()) {
            downTargets = new ArrayList<>();
            downTargets.add(firstApp);
        }

        for (int index = 0; index < headerControls.size(); index++) {
            View control = headerControls.get(index);
            if (control.getId() == View.NO_ID) control.setId(View.generateViewId());
            // Preserve the cyclic top-bar route after wiring vertical access
            // to the home rows: first ← last and last → first.
            View left = headerControls.get(index == 0 ? headerControls.size() - 1 : index - 1);
            View right = headerControls.get(index == headerControls.size() - 1 ? 0 : index + 1);
            if (left.getId() == View.NO_ID) left.setId(View.generateViewId());
            if (right.getId() == View.NO_ID) right.setId(View.generateViewId());
            View alignedDown = alignedTarget(downTargets, index);
            if (alignedDown.getId() == View.NO_ID) alignedDown.setId(View.generateViewId());
            control.setNextFocusLeftId(left.getId());
            control.setNextFocusRightId(right.getId());
            control.setNextFocusDownId(alignedDown.getId());
        }

        List<View> aboveTargets;
        if (!homeFilesTargets.isEmpty() && homeSectionBeforeApps("shortcuts")) {
            aboveTargets = homeFilesTargets;
        } else if (!resumeTargets.isEmpty() && homeSectionBeforeApps("resumes")) {
            aboveTargets = resumeTargets;
        } else {
            aboveTargets = headerControls;
        }

        for (int index = 0; index < appTopRowTargets.size(); index++) {
            View tile = appTopRowTargets.get(index);
            if (tile.getId() == View.NO_ID) tile.setId(View.generateViewId());
            View alignedUp = alignedTarget(aboveTargets, index);
            if (alignedUp.getId() == View.NO_ID) alignedUp.setId(View.generateViewId());
            tile.setNextFocusUpId(alignedUp.getId());
        }
        if (!homeFilesTargets.isEmpty() && homeSectionBeforeApps("shortcuts")) {
            for (int index = 0; index < homeFilesTargets.size(); index++) {
                View shortcut = homeFilesTargets.get(index);
                View alignedApp = alignedTarget(appTopRowTargets, index);
                if (shortcut == null || alignedApp == null) continue;
                if (shortcut.getId() == View.NO_ID) shortcut.setId(View.generateViewId());
                if (alignedApp.getId() == View.NO_ID) alignedApp.setId(View.generateViewId());
                shortcut.setNextFocusDownId(alignedApp.getId());
            }
        }
        List<String> sectionOrder = homeSectionOrder(homeFiles != null, !resumeTargets.isEmpty());
        int appsIndex = sectionOrder.indexOf("apps");
        int resumesIndex = sectionOrder.indexOf("resumes");
        if (!resumeTargets.isEmpty() && appsIndex >= 0 && resumesIndex == appsIndex + 1) {
            List<View> appBottomRowTargets = renderedAppRows.isEmpty()
                    ? appTopRowTargets
                    : immediateFocusableChildren(renderedAppRows.get(renderedAppRows.size() - 1));
            for (int index = 0; index < appBottomRowTargets.size(); index++) {
                View tile = appBottomRowTargets.get(index);
                View alignedDown = alignedTarget(resumeTargets, index);
                if (tile.getId() == View.NO_ID) tile.setId(View.generateViewId());
                if (alignedDown.getId() == View.NO_ID) alignedDown.setId(View.generateViewId());
                tile.setNextFocusDownId(alignedDown.getId());
            }
        }
        if (!resumeTargets.isEmpty() && resumesIndex >= 0 && appsIndex == resumesIndex + 1) {
            for (int index = 0; index < resumeTargets.size(); index++) {
                View resume = resumeTargets.get(index);
                if (resume.getId() == View.NO_ID) resume.setId(View.generateViewId());
                View alignedApp = alignedTarget(appTopRowTargets, index);
                if (alignedApp != null && alignedApp.getId() == View.NO_ID) alignedApp.setId(View.generateViewId());
                if (alignedApp != null) resume.setNextFocusUpId(alignedApp.getId());
            }
        }
    }
    private void wireHomeFileShortcutsLeft(LinearLayout apps, View homeFiles) {
        if (apps == null || homeFiles == null || !(homeFiles instanceof ViewGroup)) return;
        List<View> appTargets = findFirstHorizontalRowFocusableChildren(apps);
        List<View> shortcutTargets = findFirstHorizontalRowFocusableChildren((ViewGroup) homeFiles);
        if (appTargets.isEmpty() || shortcutTargets.isEmpty()) return;
        View firstApp = appTargets.get(0);
        View firstShortcut = shortcutTargets.get(0);
        if (firstApp.getId() == View.NO_ID) firstApp.setId(View.generateViewId());
        if (firstShortcut.getId() == View.NO_ID) firstShortcut.setId(View.generateViewId());
        firstApp.setNextFocusLeftId(firstShortcut.getId());
        if (firstShortcut.getNextFocusRightId() == View.NO_ID) firstShortcut.setNextFocusRightId(firstApp.getId());
    }
    private View firstFocusableChild(ViewGroup root) {
        if (root == null) return null;
        for (int index = 0; index < root.getChildCount(); index++) {
            View child = root.getChildAt(index);
            if (child == null) continue;
            if (child.isFocusable()) return child;
            if (child instanceof ViewGroup) {
                View nested = firstFocusableChild((ViewGroup) child);
                if (nested != null) return nested;
            }
        }
        return null;
    }

    private boolean isValidHomeFocus(View candidate) {
        if (candidate == null || !candidate.isFocusable()) return false;
        if (candidate instanceof ScrollView || candidate instanceof HorizontalScrollView) return false;
        return !(candidate instanceof ViewGroup) || candidate.isClickable();
    }

    private View firstHomeFocusableChild(ViewGroup root) {
        if (root == null) return null;
        for (int index = 0; index < root.getChildCount(); index++) {
            View child = root.getChildAt(index);
            if (child == null || !child.isShown()) continue;
            if (isValidHomeFocus(child)) return child;
            if (child instanceof ViewGroup) {
                View nested = firstHomeFocusableChild((ViewGroup) child);
                if (nested != null) return nested;
            }
        }
        return null;
    }

    private boolean hasVisibleResumeCard(View root) {
        if (root == null || root.getVisibility() != View.VISIBLE) return false;
        if (root.isFocusable() && root.getTag() instanceof String
                && !((String) root.getTag()).isEmpty()) return true;
        if (root instanceof ViewGroup) {
            ViewGroup group = (ViewGroup) root;
            for (int index = 0; index < group.getChildCount(); index++) {
                if (hasVisibleResumeCard(group.getChildAt(index))) return true;
            }
        }
        return false;
    }

    private List<View> immediateFocusableChildren(ViewGroup root) {
        ArrayList<View> result = new ArrayList<>();
        if (root == null) return result;
        for (int index = 0; index < root.getChildCount(); index++) {
            View child = root.getChildAt(index);
            if (child != null && child.isFocusable() && child.getVisibility() == View.VISIBLE) {
                result.add(child);
            }
        }
        return result;
    }

    private List<View> findFirstHorizontalRowFocusableChildren(ViewGroup root) {
        if (root == null) return new ArrayList<>();
        if ("home_suggestions_row".equals(root.getTag())) {
            return homeSuggestionRowVisible(root) ? immediateFocusableChildren(root) : new ArrayList<>();
        }
        if (root instanceof HorizontalScrollView) {
            View suggestions = root.findViewWithTag("home_empty_suggestions");
            if (suggestions instanceof ViewGroup) return findFirstHorizontalRowFocusableChildren((ViewGroup) suggestions);
            View child = ((HorizontalScrollView) root).getChildAt(0);
            if (child instanceof ViewGroup) {
                List<View> row = immediateFocusableChildren((ViewGroup) child);
                if (row.isEmpty()) row = continueWatchingHeroTargets((ViewGroup) child);
                if (!row.isEmpty()) return row;
            }
        }
        for (int index = 0; index < root.getChildCount(); index++) {
            View child = root.getChildAt(index);
            if (child instanceof ViewGroup) {
                List<View> row = findFirstHorizontalRowFocusableChildren((ViewGroup) child);
                if (!row.isEmpty()) return row;
            }
        }
        return new ArrayList<>();
    }

    private List<List<View>> findHorizontalRowFocusableChildren(ViewGroup root) {
        ArrayList<List<View>> result = new ArrayList<>();
        collectHorizontalRowFocusableChildren(root, result);
        return result;
    }

    private void collectHorizontalRowFocusableChildren(ViewGroup root, List<List<View>> result) {
        if (root == null) return;
        if ("home_suggestions_row".equals(root.getTag())) {
            if (homeSuggestionRowVisible(root)) {
                List<View> row = immediateFocusableChildren(root);
                if (!row.isEmpty()) result.add(row);
            }
            return;
        }
        if (root instanceof HorizontalScrollView) {
            View suggestions = root.findViewWithTag("home_empty_suggestions");
            if (suggestions instanceof ViewGroup) {
                collectHorizontalRowFocusableChildren((ViewGroup) suggestions, result);
                return;
            }
            View child = ((HorizontalScrollView) root).getChildAt(0);
            if (child instanceof ViewGroup) {
                List<View> row = immediateFocusableChildren((ViewGroup) child);
                if (row.isEmpty()) row = continueWatchingHeroTargets((ViewGroup) child);
                if (!row.isEmpty()) result.add(row);
            }
            return;
        }
        for (int index = 0; index < root.getChildCount(); index++) {
            View child = root.getChildAt(index);
            if (child instanceof ViewGroup) collectHorizontalRowFocusableChildren((ViewGroup) child, result);
        }
    }

    private List<View> continueWatchingHeroTargets(ViewGroup row) {
        ArrayList<View> targets = new ArrayList<>();
        if (row == null) return targets;
        for (int index = 0; index < row.getChildCount(); index++) {
            View child = row.getChildAt(index);
            if (!(child instanceof ViewGroup)
                    || !Boolean.TRUE.equals(child.getTag(CONTINUE_WATCHING_HERO_TAG))) continue;
            View target = firstFocusableChild((ViewGroup) child);
            if (target != null) targets.add(target);
        }
        return targets;
    }

    private View alignedTarget(List<View> targets, int index) {
        if (targets == null || targets.isEmpty()) return null;
        int safe = Math.min(Math.max(0, index), targets.size() - 1);
        return targets.get(safe);
    }

    private boolean restoreHomeVerticalFocus(int keyCode) {
        if (currentHomePage == null || currentHomeShell == null || activePopup != null) return false;
        View focused = getCurrentFocus();
        if (focused == null) return false;
        // Suggestions have several rows with their own explicit vertical links.
        if (focused.getParent() instanceof View
                && "home_suggestions_row".equals(((View) focused.getParent()).getTag())) return false;
        List<String> order = homeSectionOrder(currentHomeFilesView != null,
                ContentPresentationRules.showsContinueWatching(continueWatchingEnabled()));
        String sourceSection = null;
        List<List<View>> sourceRows = null;
        int sourceRow = -1, sourceIndex = -1;
        for (String section : order) {
            if (!"apps".equals(section) && !"resumes".equals(section) && !"videos".equals(section)
                    && !ExternalPlaybackStore.categoryValid(section)) continue;
            View sectionView = currentHomeSectionViews.get(section);
            if (!(sectionView instanceof ViewGroup) || !isHomeDescendant(focused, sectionView)) continue;
            sourceRows = findHorizontalRowFocusableChildren((ViewGroup) sectionView);
            for (int rowIndex = 0; rowIndex < sourceRows.size(); rowIndex++) {
                List<View> row = sourceRows.get(rowIndex);
                for (int itemIndex = 0; itemIndex < row.size(); itemIndex++) {
                    if (isHomeDescendant(focused, row.get(itemIndex))) {
                        sourceSection = section;
                        sourceRow = rowIndex;
                        sourceIndex = itemIndex;
                        break;
                    }
                }
                if (sourceSection != null) break;
            }
            if (sourceSection != null) break;
        }
        if (sourceSection == null || sourceRows == null) return false;
        homeLastFocusPositions.put(sourceSection, new int[]{sourceRow, sourceIndex});

        int sourceSectionIndex = order.indexOf(sourceSection);
        int destinationSectionIndex = keyCode == KeyEvent.KEYCODE_DPAD_UP
                ? sourceSectionIndex - 1 : sourceSectionIndex + 1;
        while (destinationSectionIndex >= 0 && destinationSectionIndex < order.size()) {
            String candidateSection = order.get(destinationSectionIndex);
            if (("apps".equals(candidateSection) || "resumes".equals(candidateSection) || "videos".equals(candidateSection)
                    || ExternalPlaybackStore.categoryValid(candidateSection))) {
                View destinationView = currentHomeSectionViews.get(candidateSection);
                if (destinationView instanceof ViewGroup && destinationView.getVisibility() == View.VISIBLE) {
                    List<List<View>> destinationRows = findHorizontalRowFocusableChildren((ViewGroup) destinationView);
                    if (!destinationRows.isEmpty()) {
                        int[] remembered = homeLastFocusPositions.get(candidateSection);
                        int targetRow = remembered == null
                                ? (keyCode == KeyEvent.KEYCODE_DPAD_UP ? destinationRows.size() - 1 : 0)
                                : Math.min(Math.max(0, remembered[0]), destinationRows.size() - 1);
                        List<View> targetItems = destinationRows.get(targetRow);
                        if (!targetItems.isEmpty()) {
                            int targetIndex = remembered == null ? sourceIndex
                                    : Math.min(Math.max(0, remembered[1]), targetItems.size() - 1);
                            View target = targetItems.get(Math.min(targetIndex, targetItems.size() - 1));
                            homeLastFocusPositions.put(candidateSection, new int[]{targetRow, targetIndex});
                            target.requestFocus();
                            revealResumeCard(target);
                            return true;
                        }
                    }
                }
            }
            destinationSectionIndex += keyCode == KeyEvent.KEYCODE_DPAD_UP ? -1 : 1;
        }
        return false;
    }

    /** Explicitly joins the visible Home sections vertically. */
    private void wireHomeSectionVerticalDpad() {
        if (currentHomePage == null) return;
        List<String> order = homeSectionOrder(currentHomeFilesView != null,
                ContentPresentationRules.showsContinueWatching(continueWatchingEnabled()));
        ArrayList<List<View>> firstTargets = new ArrayList<>();
        ArrayList<List<View>> lastTargets = new ArrayList<>();
        for (String section : order) {
            View view = currentHomeSectionViews.get(section);
            List<List<View>> rows = view instanceof ViewGroup && view.getVisibility() == View.VISIBLE
                    ? findHorizontalRowFocusableChildren((ViewGroup) view) : new ArrayList<>();
            firstTargets.add(rows.isEmpty() ? Collections.emptyList() : rows.get(0));
            lastTargets.add(rows.isEmpty() ? Collections.emptyList() : rows.get(rows.size() - 1));
        }
        for (int sectionIndex = 0; sectionIndex < firstTargets.size(); sectionIndex++) {
            List<View> first = firstTargets.get(sectionIndex), last = lastTargets.get(sectionIndex);
            if (first.isEmpty()) continue;
            List<View> above = null, below = null;
            for (int index = sectionIndex - 1; index >= 0; index--) {
                if (!lastTargets.get(index).isEmpty()) { above = lastTargets.get(index); break; }
            }
            for (int index = sectionIndex + 1; index < firstTargets.size(); index++) {
                if (!firstTargets.get(index).isEmpty()) { below = firstTargets.get(index); break; }
            }
            for (int itemIndex = 0; itemIndex < first.size(); itemIndex++) {
                View item = first.get(itemIndex);
                if (item.getId() == View.NO_ID) item.setId(View.generateViewId());
                if (above != null) {
                    View target = alignedTarget(above, itemIndex);
                    if (target.getId() == View.NO_ID) target.setId(View.generateViewId());
                    item.setNextFocusUpId(target.getId());
                } else if (item.getNextFocusUpId() == View.NO_ID) {
                    // Keep an explicit header-to-first-row route when one was
                    // wired by wireHomeHeaderDpad. Without this guard Android
                    // falls back to geometric search and often selects
                    // Rechercher.
                    item.setNextFocusUpId(item.getId());
                }
            }
            for (int itemIndex = 0; itemIndex < last.size(); itemIndex++) {
                View item = last.get(itemIndex);
                if (item.getId() == View.NO_ID) item.setId(View.generateViewId());
                if (below != null) {
                    // Crossing into the next Home section always starts at
                    // its first tile. Keeping the same horizontal index made
                    // Continue Watching land in the middle of Vidéos.
                    View target = below.get(0);
                    if (target.getId() == View.NO_ID) target.setId(View.generateViewId());
                    item.setNextFocusDownId(target.getId());
                } else if (item.getNextFocusDownId() == View.NO_ID) {
                    // At the bottom of Home, trap Down on the current card
                    // instead of letting geometric focus escape the rail.
                    item.setNextFocusDownId(item.getId());
                }
            }
        }
    }

    private View topBarWithDateTime() {
        return topBar();
    }
    private void addHeaderGap(LinearLayout bar, boolean vpnActive) { /* spacing handled via left margins on header items */ }

    /**
     * Android TV expands Search on focus: the Assistant mark and its label give
     * way to the microphone and keyboard actions.  Keeping it in a transparent
     * focusable popup lets the two actions use the normal TV D-pad navigation
     * without moving the rest of the header.
     */
    private void showSearchOverlay(View anchor) {
        if (activePopup != null && activePopup.isShowing()) return;

        LinearLayout choices = new LinearLayout(this);
        choices.setGravity(Gravity.TOP | Gravity.CENTER_HORIZONTAL);
        choices.setOrientation(LinearLayout.HORIZONTAL);
        choices.setPadding(dp(4), dp(2), dp(4), 0);
        choices.setClipChildren(false);
        choices.setClipToPadding(false);

        // The expanded controls live only in the free space before Weather;
        // the rest of the header remains visible and perfectly stationary.
        // This is a compact header expansion, not a large home overlay.  It
        // deliberately occupies only the Search slot so Weather and the other
        // header controls keep their normal positions.
        PopupWindow popup = new PopupWindow(choices, dp(92), dp(76), true);
        popup.setBackgroundDrawable(new android.graphics.drawable.ColorDrawable(Color.TRANSPARENT));
        popup.setOutsideTouchable(true);
        popup.setElevation(0);

        PopupWindow previous = activePopup;
        activePopup = popup;
        activeSearchAnchor = anchor;
        activeSearchPopup = popup;
        if (previous != null && previous.isShowing()) previous.dismiss();
        // Back or an outside dismissal returns to the compact Search command.
        final boolean[] returnToSearch = { true };
        final boolean[] launchingAction = { false };
        final View rightHeaderItem = adjacentTopBarItem(anchor, 1);
        popup.setOnDismissListener(() -> {
            if (activePopup == popup) activePopup = null;
            if (activeSearchPopup == popup) activeSearchPopup = null;
            anchor.setAlpha(1f);
            searchOverlayDismissed = true;
            if (returnToSearch[0] && !launchingAction[0] && !suppressSearchReturnFocus) {
                suppressNextSearchFocusExpansion = true;
                anchor.post(() -> {
                    anchor.requestFocus();
                    // Some Android TV builds do not emit a second focus
                    // callback when the anchor was already focused.
                    anchor.post(() -> suppressNextSearchFocusExpansion = false);
                });
            }
            suppressSearchReturnFocus = false;
        });

        View voice = headerSearchChoice(R.drawable.ic_google_assistant_micro, "Cliquer pour\nparler", true);
        View keyboard = headerSearchChoice(R.drawable.ic_keyboard, "Saisir du\ntexte", false);
        choices.addView(voice, new LinearLayout.LayoutParams(0, -1, 1f));
        choices.addView(keyboard, new LinearLayout.LayoutParams(0, -1, 1f));

        voice.setOnClickListener(v -> { launchingAction[0] = true; popup.dismiss(); startVoiceSearch(); });
        keyboard.setOnClickListener(v -> { launchingAction[0] = true; popup.dismiss(); openTextSearch(); });
        voice.setOnKeyListener((v, keyCode, event) -> {
            if (event.getAction() != KeyEvent.ACTION_DOWN) return false;
            if (keyCode == KeyEvent.KEYCODE_DPAD_DOWN) {
                return leaveSearchOverlayForHomeApps(popup, launchingAction);
            }
            if (keyCode == KeyEvent.KEYCODE_DPAD_LEFT) {
                returnToSearch[0] = true;
                popup.dismiss();
                return true;
            }
            return false;
        });
        keyboard.setOnKeyListener((v, keyCode, event) -> {
            if (event.getAction() != KeyEvent.ACTION_DOWN) return false;
            if (keyCode == KeyEvent.KEYCODE_DPAD_DOWN) {
                return leaveSearchOverlayForHomeApps(popup, launchingAction);
            }
            if (keyCode == KeyEvent.KEYCODE_DPAD_RIGHT) {
                View next = rightHeaderItem;
                if (next == null && anchor.getNextFocusRightId() != View.NO_ID) {
                    next = anchor.getRootView().findViewById(anchor.getNextFocusRightId());
                }
                if (next != null) {
                    launchingAction[0] = true;
                    popup.dismiss();
                    next.post(next::requestFocus);
                    return true;
                }
                // Do not swallow the key if the visible header has no
                // resolvable target; Android can then apply its normal focus
                // search instead of leaving the user trapped in the popup.
                return false;
            }
            return false;
        });

        // Hide the compact command while its two Android-TV choices occupy this area.
        anchor.setAlpha(0f);
        // The header is translated upward and can be hosted in different
        // containers depending on the page.  A fixed screen y-position put
        // Search's mic/keyboard above the actual header rhythm.  Anchor the
        // popup to the real Search slot instead, so its icon row and label row
        // are exactly level with Weather and the other top-bar commands.
        int[] searchLocation = new int[2];
        anchor.getLocationOnScreen(searchLocation);
        int popupX = Math.max(dp(4), searchLocation[0] - dp(20));
        popup.showAtLocation(getWindow().getDecorView(), Gravity.TOP | Gravity.LEFT,
                popupX, searchLocation[1]);
        voice.requestFocus();
    }

    private boolean isSearchHeader(View view) {
        return view != null && "search".equals(view.getTag());
    }

    /** Closes the separate Search popup without sending focus back to Search. */
    private void closeSearchOverlayForHomeFocus() {
        PopupWindow popup = activeSearchPopup;
        if (popup != null && popup.isShowing()) {
            suppressSearchReturnFocus = true;
            popup.dismiss();
        }
        activeSearchPopup = null;
        activeSearchAnchor = null;
        if (currentHomeHeaderView != null) {
            View search = currentHomeHeaderView.findViewWithTag("search");
            if (search != null) {
                search.animate().cancel();
                search.setAlpha(1f);
                search.setScaleX(1f);
                search.setScaleY(1f);
            }
        }
    }

    /** The search choices are a popup, outside the normal home focus tree. */
    private boolean leaveSearchOverlayForHomeApps(PopupWindow popup, boolean[] launchingAction) {
        if (currentHomeAppsView == null) return false;
        List<View> applications = findFirstHorizontalRowFocusableChildren(currentHomeAppsView);
        if (applications.isEmpty()) return false;
        View firstApplication = applications.get(0);
        launchingAction[0] = true;
        popup.dismiss();
        firstApplication.post(firstApplication::requestFocus);
        return true;
    }

