    private View adjacentTopBarItem(View current, int direction) {
        if (current == null) return null;
        LinearLayout visibleBar = null;
        if (current.getParent() instanceof LinearLayout) {
            visibleBar = (LinearLayout) current.getParent();
        }
        if (visibleBar == null && currentTopBarHeader != null
                && currentTopBarHeader.getTag() instanceof LinearLayout) {
            visibleBar = (LinearLayout) currentTopBarHeader.getTag();
        }
        if (visibleBar == null) return null;
        List<View> items = immediateFocusableChildren(visibleBar);
        int index = items.indexOf(current);
        if (index < 0 || items.size() < 2) return null;
        return items.get((index + direction + items.size()) % items.size());
    }
