        status.addView(iconContainer, new LinearLayout.LayoutParams(dp(46), dp(46)));
        // Storage is deliberately presented on one compact line. It keeps the
        // top bar shallower while retaining the exact free/total information.
        LinearLayout detailsLine = new LinearLayout(this);
        detailsLine.setOrientation(LinearLayout.HORIZONTAL);
        detailsLine.setGravity(Gravity.CENTER);
