    private String smbStatusLabel() {
        List<SmbConnectionConfig> connections = smbConnections();
        if (connections.isEmpty()) return "Non configuré";
        return smbStatusLabel(connections.get(0));
    }
    private String smbCapacityCacheKey(SmbConnectionConfig connection) {
        return "nas_smb_capacity_" + SmbConnectionConfig.syncKey(connection);
    }
    private String smbStatusLabel(SmbConnectionConfig connection) {
        String key = smbCapacityCacheKey(connection);
        long free = homePrefs().getLong(key + "_free", -1L), total = homePrefs().getLong(key + "_total", -1L);
        SmbConnectionConfig primary = defaultSmbConnection();
        if (free < 0 && primary != null && SmbConnectionConfig.syncKey(primary).equals(SmbConnectionConfig.syncKey(connection))) {
            free = homePrefs().getLong("smb_free", -1L);
            total = homePrefs().getLong("smb_total", -1L);
        }
        return free >= 0 ? compactStorageCapacityLabel(free, total) : "Calcul de l’espace…";
    }
    private jcifs.CIFSContext smbContext(String user, String password) throws Exception {
        return smbContext(user, password, 60000);
    }

    private jcifs.CIFSContext smbBrowserContext(String user, String password) throws Exception {
        return smbContext(user, password, 8000);
    }

    private jcifs.CIFSContext smbContext(String user, String password, int timeoutMs) throws Exception {
        SmbConnectionConfig.ensureCryptoProvider();
        java.util.Properties properties = new java.util.Properties(); properties.setProperty("jcifs.smb.client.minVersion", "SMB202"); properties.setProperty("jcifs.smb.client.maxVersion", "SMB311"); properties.setProperty("jcifs.smb.client.responseTimeout", String.valueOf(timeoutMs)); properties.setProperty("jcifs.smb.client.soTimeout", String.valueOf(timeoutMs)); properties.setProperty("jcifs.smb.client.connTimeout", String.valueOf(timeoutMs));
        // SmbFileInputStream is unbuffered. Larger negotiated SMB packets are
        // especially useful for APKs, which otherwise arrive in 32 KiB reads.
        properties.setProperty("jcifs.smb.client.rcv_buf_size", "262144");
        properties.setProperty("jcifs.smb.client.snd_buf_size", "262144");
        properties.setProperty("jcifs.smb.client.tcpNoDelay", "true");
        jcifs.CIFSContext base = new jcifs.context.BaseContext(new jcifs.config.PropertyConfiguration(properties));
        return user.isEmpty() ? base : base.withCredentials(SmbConnectionConfig.authenticatorFor(user, password));
    }
    private long[] readSmbCapacity(jcifs.smb.SmbFile folder) throws Exception {
        long[] capacity = smbCapacity(folder);
        if (capacity[0] > 0) return capacity;
        for (jcifs.smb.SmbFile entry : folder.listFiles()) if (entry.isDirectory()) { capacity = smbCapacity(entry); if (capacity[0] > 0) return capacity; }
        return capacity;
    }
    private void refreshSmbStatus(TextView value, SmbConnectionConfig connection) {
        if (isDestroyed() || !value.isAttachedToWindow()) return;
        String key = smbCapacityCacheKey(connection);
        long checkedAt = homePrefs().getLong(key + "_checked_at", 0L);
        long age = System.currentTimeMillis() - checkedAt;
        if (checkedAt > 0L && age >= 0L && age < 30000L) return;
        smbDurationWork.execute(() -> {
            if (isDestroyed() || !value.isAttachedToWindow()) return;
            try (jcifs.smb.SmbFile folder = new jcifs.smb.SmbFile(connection.browserUrl(), smbBrowserContext(connection.user, connection.password))) {
                long[] capacity = readSmbCapacity(folder);
                if (capacity[0] >= 0L) {
                    android.content.SharedPreferences.Editor editor = homePrefs().edit()
                            .putLong(key + "_free", capacity[0]).putLong(key + "_total", capacity[1])
                            .putLong(key + "_checked_at", System.currentTimeMillis());
                    SmbConnectionConfig primary = defaultSmbConnection();
                    if (primary != null && primary.matches(connection.browserUrl(), connection.user, connection.password)) {
                        editor.putLong("smb_free", capacity[0]).putLong("smb_total", capacity[1]);
                    }
                    editor.apply();
                }
                runOnUiThread(() -> { if (value.isAttachedToWindow()) value.setText(compactStorageCapacityLabel(capacity[0], capacity[1])); });
            } catch (Exception error) {
                runOnUiThread(() -> { if (value.isAttachedToWindow()) value.setText("Hors ligne"); });
            }
        });
    }
    private int networkIconResource() {
        ConnectivityManager connectivity = (ConnectivityManager) getSystemService(CONNECTIVITY_SERVICE); if (connectivity == null) return R.drawable.ic_network_off;
        Network network = connectivity.getActiveNetwork(); NetworkCapabilities capabilities = network == null ? null : connectivity.getNetworkCapabilities(network);
        if (capabilities == null || !capabilities.hasCapability(NetworkCapabilities.NET_CAPABILITY_VALIDATED)) return R.drawable.ic_network_off;
        // Fire OS can expose Wi-Fi as the active/default network while the
        // physical Ethernet transport remains available in getAllNetworks().
        // Prefer Ethernet for the header whenever it is actually connected.
        boolean ethernet = capabilities.hasTransport(NetworkCapabilities.TRANSPORT_ETHERNET);
        boolean wifi = capabilities.hasTransport(NetworkCapabilities.TRANSPORT_WIFI);
        for (Network candidate : connectivity.getAllNetworks()) {
            NetworkCapabilities candidateCapabilities = connectivity.getNetworkCapabilities(candidate);
            if (candidateCapabilities == null) continue;
            if (candidateCapabilities.hasTransport(NetworkCapabilities.TRANSPORT_ETHERNET)) ethernet = true;
            if (candidateCapabilities.hasTransport(NetworkCapabilities.TRANSPORT_WIFI)) wifi = true;
        }
        if (ethernet) return R.drawable.ic_ethernet;
        if (wifi) return R.drawable.ic_wifi;
        return R.drawable.ic_ethernet;
    }
    private int networkIconFocusedResource() {
        int res = networkIconResource();
        if (res == R.drawable.ic_ethernet) return R.drawable.ic_ethernet_focused;
        if (res == R.drawable.ic_wifi) return R.drawable.ic_wifi_focused;
        return R.drawable.ic_network_off_focused;
    }
    private int networkState() { ConnectivityManager connectivity = (ConnectivityManager) getSystemService(CONNECTIVITY_SERVICE); if (connectivity == null) return 0; Network network = connectivity.getActiveNetwork(); NetworkCapabilities capabilities = network == null ? null : connectivity.getNetworkCapabilities(network); if (capabilities == null) return 0; return capabilities.hasCapability(NetworkCapabilities.NET_CAPABILITY_VALIDATED) ? 2 : 1; }
    private boolean isVpnActive() {
        ConnectivityManager connectivity = (ConnectivityManager) getSystemService(CONNECTIVITY_SERVICE);
        if (connectivity == null) return false;
        for (Network network : connectivity.getAllNetworks()) {
            NetworkCapabilities capabilities = connectivity.getNetworkCapabilities(network);
            if (capabilities != null && capabilities.hasTransport(NetworkCapabilities.TRANSPORT_VPN)) return true;
        }
        return false;
    }
    private void openActiveVpnProvider() {
        List<android.content.pm.ResolveInfo> candidates = getPackageManager().queryIntentServices(new Intent("android.net.VpnService"), PackageManager.MATCH_ALL);
        LinkedHashMap<String, Intent> launchable = new LinkedHashMap<>();
        for (android.content.pm.ResolveInfo candidate : candidates) if (candidate.serviceInfo != null) { Intent launch = getPackageManager().getLaunchIntentForPackage(candidate.serviceInfo.packageName); if (launch != null) launchable.putIfAbsent(candidate.serviceInfo.packageName, launch); }
        if (VpnHeaderRules.shouldLaunchProvider(launchable.size())) { startActivity(launchable.values().iterator().next()); return; }
        openVpnSettings();
    }
    private void openVpnSettings() { try { startActivity(new Intent(Settings.ACTION_VPN_SETTINGS)); } catch (Exception error) { openNetworkSettings(); } }
    private void openNetworkSettings() { try { startActivity(new Intent(Settings.ACTION_WIFI_SETTINGS)); } catch (Exception error) { startActivity(new Intent(Settings.ACTION_SETTINGS)); } }
    private void showSettingsOverlay(View anchor) {
        LinearLayout menu = new LinearLayout(this); menu.setOrientation(LinearLayout.VERTICAL); menu.setPadding(dp(14), dp(10), dp(14), dp(16)); menu.setClipChildren(false); menu.setClipToPadding(false);
        TextView heading = text("PARAMÈTRES", 12, SettingsPresentation.secondaryTextColor()); heading.setTypeface(null, 1); heading.setLetterSpacing(.10f); heading.setPadding(dp(14), 0, 0, dp(5)); menu.addView(heading, new LinearLayout.LayoutParams(-1, dp(23)));
        ScrollView scroll = new ScrollView(this);
        scroll.setVerticalScrollBarEnabled(false);
        scroll.setFillViewport(true);
        scroll.setBackground(settingsOverlayBg());
        scroll.setClipToOutline(true);
        scroll.addView(menu, new ScrollView.LayoutParams(-1, -2));
        int popupWidth = dp(418);
        View servers = settingsOverlayRow(R.drawable.ic_view_list, "Serveurs", "Local et dossiers réseau SMB");
        View network = settingsOverlayRow(networkIconResource(), "Réseau", "Wi-Fi, Ethernet et connexion Internet", true);
        View sources = settingsOverlayRow(R.drawable.ic_sources, "Sources", "Choisir une entrée TV");
        View androidSettings = settingsOverlayRow(R.drawable.ic_settings, isFireOsDevice() ? "Paramètres Fire TV" : "Paramètres Android TV", "Réseau, image, son et préférences système");
        View homeSettings = settingsOverlayRow(R.drawable.ic_settings, "Paramètres de l’application", "Personnaliser Jojo Home");
        View updates = settingsOverlayRow(R.drawable.ic_refresh, "Vérifier les mises à jour", "Rechercher une nouvelle version sur la Freebox");
        int[] anchorLocation = new int[2];
        anchor.getLocationOnScreen(anchorLocation);
        int availableHeight = Math.max(dp(1), getResources().getDisplayMetrics().heightPixels
                - anchorLocation[1] - anchor.getHeight() - dp(44));
        View[] rows = { servers, network, sources, androidSettings, homeSettings, updates };
        int rowHeight = Math.max(dp(52), Math.min(dp(58),
                (availableHeight - menu.getPaddingTop() - menu.getPaddingBottom() - dp(23)) / rows.length));
        for (View row : rows) menu.addView(row, new LinearLayout.LayoutParams(-1, rowHeight));
        menu.measure(
                View.MeasureSpec.makeMeasureSpec(popupWidth, View.MeasureSpec.EXACTLY),
                View.MeasureSpec.makeMeasureSpec(0, View.MeasureSpec.UNSPECIFIED));
        int popupHeight = Math.min(menu.getMeasuredHeight(), availableHeight);
        PopupWindow popup = new PopupWindow(scroll, popupWidth, popupHeight, true); popup.setBackgroundDrawable(settingsOverlayBg()); popup.setOutsideTouchable(true); popup.setElevation(dp(18)); trackPopup(popup);
        final View[] pendingHeaderFocus = { null };
        popup.setOnDismissListener(() -> {
            if (activePopup == popup) activePopup = null;
            dismissTransientMarquee();
            View target = pendingHeaderFocus[0];
            pendingHeaderFocus[0] = null;
            if (target != null && target.isAttachedToWindow()) target.post(target::requestFocus);
            else restoreHomeFocusIfNeeded();
        });
        servers.setOnClickListener(v -> { popup.dismiss(); showServersOverlay(anchor); });
        network.setOnClickListener(v -> { popup.dismiss(); openNetworkSettings(); });
        sources.setOnClickListener(v -> { popup.dismiss(); openSystemSources(); });
        androidSettings.setOnClickListener(v -> { popup.dismiss(); openAndroidTvSettings(); });
        homeSettings.setOnClickListener(v -> { popup.dismiss(); openScreen(createAppSettingsPage()); });
        updates.setOnClickListener(v -> { popup.dismiss(); checkForJojoHomeUpdate(v); });
        wireCyclicVerticalFocus(servers, network, sources, androidSettings, homeSettings, updates);
        for (View row : rows) {
            wireHeaderPopupHorizontalExit(row, anchor, popup, pendingHeaderFocus);
        }
        showPopupBelow(popup, anchor, (anchor.getWidth() - popupWidth) / 2, dp(4)); servers.requestFocus();
    }
    private void refreshHeaderDateTime() {
        View root = getWindow().getDecorView();
        TextView visibleDate = root.findViewWithTag("header-date");
        TextView visibleClock = root.findViewWithTag("header-clock");
        if (visibleDate != null) headerDateText = visibleDate;
        if (visibleClock != null) headerClockText = visibleClock;
        if (headerDateText != null) {
            String date = headerDateLabel();
            if (!TextUtils.equals(headerDateText.getText(), date)) headerDateText.setText(date);
        }
        if (headerClockText != null) {
            String clock = new SimpleDateFormat(HomeChromeRules.clockPattern(), Locale.FRENCH).format(new Date());
            if (!TextUtils.equals(headerClockText.getText(), clock)) headerClockText.setText(clock);
        }
    }
    private String headerDateLabel() {
        String value = new SimpleDateFormat("EEE d MMM", Locale.FRENCH).format(new Date());
        return value.isEmpty() ? value : Character.toUpperCase(value.charAt(0)) + value.substring(1);
    }
    private void showProfileOverlay(View anchor) {
        IptvStore store = homeAccountStore();
        LinearLayout menu = new LinearLayout(this);
        menu.setOrientation(LinearLayout.VERTICAL);
        menu.setPadding(dp(14), dp(12), dp(14), dp(12));
        menu.setBackground(settingsOverlayBg());
        TextView heading = text("COMPTES", 12, Color.rgb(169, 193, 237));
        heading.setTypeface(null, Typeface.BOLD);
        heading.setLetterSpacing(.10f);
        heading.setPadding(dp(14), 0, 0, dp(5));
        menu.addView(heading, new LinearLayout.LayoutParams(-1, dp(25)));
        LinearLayout rows = new LinearLayout(this);
        rows.setOrientation(LinearLayout.VERTICAL);
        menu.addView(rows, new LinearLayout.LayoutParams(-1, -2));
        TextView status = text("Chargement des comptes…", 14, Color.rgb(178, 201, 238));
        rows.addView(status, new LinearLayout.LayoutParams(-1, dp(36)));
        View add = settingsOverlayRow(R.drawable.ic_menu_home_add, "Ajouter un compte", "Nom et avatar dans les paramètres JojoHome");
        add.setId(View.generateViewId());
        menu.addView(add, new LinearLayout.LayoutParams(-1, dp(66)));
        ScrollView scroll = new ScrollView(this);
        scroll.setVerticalScrollBarEnabled(false);
        scroll.addView(menu, new ScrollView.LayoutParams(-1, -2));
        int popupWidth = dp(418);
        int[] anchorLocation = new int[2];
        anchor.getLocationOnScreen(anchorLocation);
        int availableHeight = Math.max(dp(1), getResources().getDisplayMetrics().heightPixels
                - anchorLocation[1] - anchor.getHeight() - dp(44));
        PopupWindow popup = new PopupWindow(scroll, popupWidth, Math.min(dp(151), availableHeight), true);
        popup.setBackgroundDrawable(settingsOverlayBg());
        popup.setOutsideTouchable(true);
        popup.setElevation(dp(18));
        trackPopup(popup);
        final View[] pendingHeaderFocus = { null };
        popup.setOnDismissListener(() -> {
            if (activePopup == popup) activePopup = null;
            dismissTransientMarquee();
            View target = pendingHeaderFocus[0] == null ? anchor : pendingHeaderFocus[0];
            finishHomeDpadNavigation();
            if (target.isAttachedToWindow()) target.post(target::requestFocus);
            else restoreHomeFocusIfNeeded();
        });
        add.setOnClickListener(v -> {
            popup.dismiss();
            pendingSettingsFocus = "account_add";
            if (isHomeAccountSettingsPage(activeScreen)) replaceScreen(createAccountSettingsPage(true));
            else openScreen(createAccountSettingsPage(true));
        });
        wireHeaderPopupHorizontalExit(add, anchor, popup, pendingHeaderFocus);
        showPopupBelow(popup, anchor, (anchor.getWidth() - popupWidth) / 2, dp(4));
        add.requestFocus();
        Runnable renderAccounts = () -> {
            if (isDestroyed() || !popup.isShowing()) return;
            rows.removeAllViews();
            ArrayList<View> focusable = new ArrayList<>();
            View initialFocus = add;
            for (IptvAccount account : homeHeaderAccounts) {
                boolean chosen = homeHeaderAccount != null && account.getId().equals(homeHeaderAccount.getId());
                LinearLayout row = homeAccountSettingsRow(store, account, homeHeaderAccountAvatars, chosen ? "Compte actif" : "", null);
                row.setId(View.generateViewId());
                row.setPadding(dp(14), dp(6), dp(14), dp(6));
                TextView copy = (TextView) row.getChildAt(1);
                styleSettingsText(copy, row);
                row.setOnFocusChangeListener((view, focused) -> {
                    row.setBackground(focused ? folderPaletteControlBg(true, 10) : new GradientDrawable());
                    styleSettingsText(copy, row);
                });
                row.setOnClickListener(v -> selectHomeAccount(store, account.getId(),
                        popup, this::refreshActiveHomeAccountSettingsPage));
                rows.addView(row, new LinearLayout.LayoutParams(-1, dp(66)));
                focusable.add(row);
                wireHeaderPopupHorizontalExit(row, anchor, popup, pendingHeaderFocus);
                if (chosen) initialFocus = row;
            }
            if (homeHeaderAccounts.isEmpty()) {
                status.setText("Aucun compte créé");
                rows.addView(status, new LinearLayout.LayoutParams(-1, dp(36)));
            }
            focusable.add(add);
            wireCyclicVerticalFocus(focusable.toArray(new View[0]));
            menu.measure(View.MeasureSpec.makeMeasureSpec(popupWidth, View.MeasureSpec.EXACTLY),
                    View.MeasureSpec.makeMeasureSpec(0, View.MeasureSpec.UNSPECIFIED));
            popup.update(popupWidth, Math.min(dp(445), Math.min(menu.getMeasuredHeight(), availableHeight)));
            initialFocus.requestFocus();
        };
        if (homeHeaderAccountLoaded) {
            renderAccounts.run();
            return;
        }
        final int accountGeneration = homeAccountChangeGeneration;
        homeAccountExecutor.execute(() -> {
            try {
                store.load();
                List<IptvAccount> accounts = store.accounts();
                IptvAccount selected = store.selectedAccount();
                List<IptvAvatar> avatars = store.cachedAvatars();
                runOnUiThread(() -> {
                    if (isDestroyed() || accountGeneration != homeAccountChangeGeneration) return;
                    updateHomeHeaderAccount(accounts, selected, avatars);
                    renderAccounts.run();
                });
            } catch (Exception error) {
                runOnUiThread(() -> {
                    if (isDestroyed() || !popup.isShowing()) return;
                    status.setText("Impossible de charger les comptes");
                    Toast.makeText(this, error.getMessage(), Toast.LENGTH_LONG).show();
                });
            }
        });
    }
    private View overlayRow(String title, String subtitle) { TextView row = text(title + "\n" + subtitle, 16, white); row.setGravity(Gravity.CENTER_VERTICAL); row.setPadding(dp(20), 0, dp(16), 0); row.setFocusable(true); row.setOnFocusChangeListener((v, focused) -> v.setBackground(focused ? settingsOverlayFocusBg() : new GradientDrawable())); return row; }
    private Drawable settingsOverlayNetworkIcon(boolean focused) {
        int resource = networkIconResource();
        if (focused) {
            Drawable icon = getDrawable(networkIconFocusedResource());
            if (icon == null || resource != R.drawable.ic_ethernet) return icon;
            Drawable ethernetDetails = getDrawable(R.drawable.ic_ethernet_details);
            if (ethernetDetails == null) return icon;
            ethernetDetails = ethernetDetails.mutate();
            ethernetDetails.setColorFilter(folderThemeColor(), PorterDuff.Mode.SRC_IN);
            return new LayerDrawable(new Drawable[]{icon.mutate(), ethernetDetails});
        }

        Drawable icon = getDrawable(resource);
        if (icon == null) return null;
        icon = icon.mutate();
        icon.setColorFilter(folderThemeColor(), PorterDuff.Mode.SRC_IN);
        if (resource != R.drawable.ic_ethernet) return icon;

        Drawable ethernetDetails = getDrawable(R.drawable.ic_ethernet_details);
        if (ethernetDetails == null) return icon;
        return new LayerDrawable(new Drawable[]{icon, ethernetDetails.mutate()});
    }
    private View settingsOverlayRow(int iconId, String title, String subtitle) {
        return settingsOverlayRow(iconId, title, subtitle, false);
    }
    private View settingsOverlayRow(int iconId, String title, String subtitle, boolean networkStatusIcon) {
        LinearLayout row = new LinearLayout(this); row.setGravity(Gravity.CENTER_VERTICAL); row.setPadding(dp(14), 0, dp(14), 0); row.setFocusable(true);
        ImageView icon = new ImageView(this); icon.setImageResource(iconId); icon.setPadding(dp(7), dp(7), dp(7), dp(7));
        final int initialNetworkState = networkStatusIcon ? networkState() : 0;
        final TextView networkBadge = networkStatusIcon
                ? text(initialNetworkState == 2 ? "✓" : initialNetworkState == 1 ? "!" : "×", 10, Color.WHITE)
                : null;
        if (networkStatusIcon) {
            icon.setImageDrawable(settingsOverlayNetworkIcon(false));
            FrameLayout iconFrame = new FrameLayout(this);
            iconFrame.setClipChildren(false);
            iconFrame.setClipToPadding(false);
            iconFrame.addView(icon, new FrameLayout.LayoutParams(-1, -1));
            networkBadge.setTypeface(null, Typeface.BOLD);
            networkBadge.setGravity(Gravity.CENTER);
            networkBadge.setBackground(networkBadgeBg(initialNetworkState));
            FrameLayout.LayoutParams badgeParams = new FrameLayout.LayoutParams(dp(15), dp(15), Gravity.RIGHT | Gravity.BOTTOM);
            iconFrame.addView(networkBadge, badgeParams);
            row.addView(iconFrame, new LinearLayout.LayoutParams(dp(42), dp(42)));
        } else {
            try { icon.setColorFilter(folderThemeColor()); } catch (Exception ignored) {}
            row.addView(icon, new LinearLayout.LayoutParams(dp(42), dp(42)));
        }
        LinearLayout copy = new LinearLayout(this); copy.setOrientation(LinearLayout.VERTICAL); copy.setGravity(Gravity.CENTER_VERTICAL); copy.setPadding(dp(12), 0, 0, 0);
        TextView label = text(title, 17, SettingsPresentation.textColor()); label.setTypeface(null, 1); label.setSingleLine(true); copy.addView(label);
        TextView detail = text(subtitle, 13, SettingsPresentation.secondaryTextColor()); detail.setSingleLine(true); detail.setEllipsize(TextUtils.TruncateAt.END); copy.addView(detail);
        row.addView(copy, new LinearLayout.LayoutParams(0, -1, 1f));
        row.setOnFocusChangeListener((v, focused) -> {
            row.setBackground(focused ? folderPaletteControlBg(true, 10) : new GradientDrawable());
            int foreground = focused ? contrastingFolderThemeTextColor() : SettingsPresentation.textColor();
            if (networkStatusIcon) {
                icon.setImageDrawable(settingsOverlayNetworkIcon(focused));
                int state = networkState();
                networkBadge.setText(state == 2 ? "✓" : state == 1 ? "!" : "×");
                networkBadge.setContentDescription(state == 2
                        ? "Connexion Internet disponible"
                        : state == 1 ? "Réseau sans accès Internet" : "Réseau indisponible");
                networkBadge.setBackground(networkBadgeBg(state));
            } else {
                icon.setColorFilter(focused ? foreground : folderThemeColor());
            }
            label.setTextColor(foreground);
            detail.setTextColor(focused ? foreground : SettingsPresentation.secondaryTextColor());
        });
        return row;
    }
    private View weatherWidget() {
        LinearLayout weather = new LinearLayout(this);
        weather.setOrientation(LinearLayout.HORIZONTAL);
        weather.setGravity(Gravity.CENTER);
        weather.setPadding(0, 0, 0, 0);
        weather.setFocusable(true);
        weather.setContentDescription("Météo locale");
        weather.setClipChildren(false);
        weather.setClipToPadding(false);

        ImageView icon = new ImageView(this);
        icon.setImageResource(R.drawable.ic_weather_cloud);
        desaturateWeatherIcon(icon);
        icon.setAlpha(1f);
        // Keep the weather glyph in the same 27 dp visual box as the other
        // header icons; the temperature keeps its own adjacent width.
        weather.addView(icon, new LinearLayout.LayoutParams(dp(27), dp(27)));

        // The existing refresh pipeline keeps the city here, even though the
        // compact header intentionally renders only icon plus temperature.
        TextView label = text("Météo locale…", 13, muted);
        TextView currentTemperature = text("--°", 13, Color.WHITE);
        currentTemperature.setGravity(Gravity.CENTER);
        currentTemperature.setSingleLine(true);
        currentTemperature.setPadding(0, 0, 0, 0);
        LinearLayout.LayoutParams temperatureParams = new LinearLayout.LayoutParams(dp(38), dp(32));
        temperatureParams.leftMargin = dp(3);
        weather.addView(currentTemperature, temperatureParams);
        WeatherWidgetViews views = new WeatherWidgetViews(weather, icon, label, currentTemperature,
                new ImageView[0], new TextView[0], new TextView[0]);
        activeWeatherWidget = views;
        weather.setLayoutParams(new LinearLayout.LayoutParams(dp(73), dp(HOME_HEADER_ITEM_HEIGHT_DP)));
        weather.setOnFocusChangeListener((v, focused) -> {
            weather.animate().scaleX(focused ? 1.06f : 1f).scaleY(focused ? 1.06f : 1f).setDuration(120).start();
            icon.setColorFilter(focused ? folderThemeColor() : Color.WHITE,
                    android.graphics.PorterDuff.Mode.SRC_IN);
            currentTemperature.setTextColor(focused ? folderThemeColor() : muted);
        });
        weather.setOnClickListener(v -> openScreen(createWeatherSettingsPage()));
        if (cachedWeather != null) applyWeatherSnapshot(views, cachedWeather);
        refreshWeather(icon, label, currentTemperature, new ImageView[0], new TextView[0], new TextView[0]);
        weather.post(this::scheduleWeatherAutoRefresh);
        return weather;
    }
    private void desaturateWeatherIcon(ImageView icon) {
        if (icon == null) return;
        icon.setColorFilter(Color.WHITE, android.graphics.PorterDuff.Mode.SRC_IN);
    }
    private void refreshActiveWeatherWidget() {
        WeatherWidgetViews weather = activeWeatherWidget;
        if (weather == null || !weather.root.isAttachedToWindow() || !weatherWidgetEnabled()) return;
        refreshWeather(weather.icon, weather.label, weather.currentTemperature, weather.forecastIcons, weather.forecastDays, weather.forecastTemperatures);
        scheduleWeatherAutoRefresh();
    }
    private void scheduleWeatherAutoRefresh() {
        weatherRefreshHandler.removeCallbacks(weatherAutoRefreshRunnable);
        WeatherWidgetViews weather = activeWeatherWidget;
        if (weather != null && weather.root.isAttachedToWindow() && weatherWidgetEnabled()) weatherRefreshHandler.postDelayed(weatherAutoRefreshRunnable, WEATHER_AUTO_REFRESH_DELAY_MS);
    }
    private void setForecastVisibility(TextView[] forecastDays, boolean visible) {
        if (forecastDays == null) return;
        for (TextView day : forecastDays) {
            if (day == null) continue;
            View parent = day.getParent() instanceof View ? (View) day.getParent() : null;
            if (parent != null) parent.setVisibility(visible ? View.VISIBLE : View.GONE);
        }
    }
    private void applyWeatherSnapshot(WeatherWidgetViews weather, WeatherSnapshot snapshot) {
        if (weather == null || snapshot == null) return;
        weather.icon.setImageResource(weatherIconRes(snapshot.currentCondition));
        weather.label.setText(snapshot.city);
        weather.currentTemperature.setText(snapshot.currentTemperature);
        weather.root.setContentDescription("Météo locale : " + snapshot.currentTemperature);
        for (int index = 0; index < Math.min(3, weather.forecastDays.length); index++) {
            boolean visible = index < snapshot.forecastDays.length && snapshot.forecastDays[index] != null;
            View parent = weather.forecastDays[index].getParent() instanceof View ? (View) weather.forecastDays[index].getParent() : null;
            if (parent != null) parent.setVisibility(visible ? View.VISIBLE : View.GONE);
            if (!visible) continue;
            weather.forecastDays[index].setText(snapshot.forecastDays[index]);
            weather.forecastTemperatures[index].setText(snapshot.forecastTemperatures[index]);
            desaturateWeatherIcon(weather.forecastIcons[index]);
            weather.forecastIcons[index].setImageResource(weatherIconRes(snapshot.forecastConditions[index]));
        }
    }
    private String weatherCacheContext() {
        return weatherLocationModeForSuffix(weatherDeviceSuffix()) + "|" + weatherManualCity();
    }
    private void restoreCachedWeather() {
        try {
            JSONObject saved = new JSONObject(getSharedPreferences("weather_widget_cache", MODE_PRIVATE)
                    .getString("snapshot", "{}"));
            if (!weatherCacheContext().equals(saved.optString("context"))
                    || saved.optString("temperature").isEmpty() || saved.optString("condition").isEmpty()) return;
            String[][] forecasts = new String[3][3];
            String[] keys = { "days", "temperatures", "conditions" };
            for (int field = 0; field < keys.length; field++) {
                JSONArray values = saved.optJSONArray(keys[field]);
                if (values != null) for (int day = 0; day < 3; day++) forecasts[field][day] = values.optString(day, null);
            }
            cachedWeather = new WeatherSnapshot(saved.optString("city", "Ma position"),
                    saved.getString("temperature"), saved.getString("condition"),
                    forecasts[0], forecasts[1], forecasts[2]);
        } catch (org.json.JSONException ignored) { }
    }
    private void publishWeatherSnapshot(WeatherSnapshot snapshot) {
        weatherRequestInFlight = false;
        boolean changed = cachedWeather == null || !cachedWeather.sameAs(snapshot);
        cachedWeather = snapshot;
        try {
            JSONObject saved = new JSONObject().put("context", weatherCacheContext())
                    .put("city", snapshot.city).put("temperature", snapshot.currentTemperature)
                    .put("condition", snapshot.currentCondition)
                    .put("days", new JSONArray(java.util.Arrays.asList(snapshot.forecastDays)))
                    .put("temperatures", new JSONArray(java.util.Arrays.asList(snapshot.forecastTemperatures)))
                    .put("conditions", new JSONArray(java.util.Arrays.asList(snapshot.forecastConditions)));
            // Weather data stays local; the existing NAS settings store only the user's weather choices.
            getSharedPreferences("weather_widget_cache", MODE_PRIVATE).edit().putString("snapshot", saved.toString()).apply();
        } catch (org.json.JSONException ignored) { }
        if (weatherPositionStatus != null) setSettingValue(weatherPositionStatus, "Actualiser ma position", "Météo actualisée");
        if (changed) applyWeatherSnapshot(activeWeatherWidget, snapshot);
    }
    private void refreshWeather(ImageView icon, TextView label, TextView currentTemperature, ImageView[] forecastIcons, TextView[] forecastDays, TextView[] forecastTemperatures) {
        if (weatherRequestInFlight) return;
        ++weatherGeneration;
        weatherRequestInFlight = true;
        String manualCity = weatherManualCity();
        if (!weatherUsesCurrentLocation() && !manualCity.isEmpty()) {
            loadWeatherForCity(manualCity, icon, label, currentTemperature, forecastIcons, forecastDays, forecastTemperatures);
            return;
        }
        LocationManager manager = (LocationManager) getSystemService(LOCATION_SERVICE); Location location = null;
        if (checkSelfPermission(Manifest.permission.ACCESS_COARSE_LOCATION) == PackageManager.PERMISSION_GRANTED) try { location = manager.getLastKnownLocation(LocationManager.NETWORK_PROVIDER); if (location == null) location = manager.getLastKnownLocation(LocationManager.GPS_PROVIDER); } catch (Exception ignored) { }
        if (refreshedWeatherLocation != null) location = refreshedWeatherLocation;
        if (location != null && android.os.SystemClock.elapsedRealtimeNanos() - location.getElapsedRealtimeNanos() < 600_000_000_000L) { loadWeather(location.getLatitude(), location.getLongitude(), "", icon, label, currentTemperature, forecastIcons, forecastDays, forecastTemperatures); return; }
        if (refreshedWeatherLocation != null) { refreshWeatherFromCurrentPosition(); return; }
        loadWeatherFromNetwork(icon, label, currentTemperature, forecastIcons, forecastDays, forecastTemperatures);
    }
    private void loadWeatherFromNetwork(ImageView icon, TextView label, TextView currentTemperature, ImageView[] forecastIcons, TextView[] forecastDays, TextView[] forecastTemperatures) { final int generation = weatherGeneration; new Thread(() -> { try { JSONObject area; try { area = fetchJson("https://ipwho.is/"); if (!area.optBoolean("success", true)) throw new java.io.IOException(); } catch (Exception first) { area = fetchJson("https://ipapi.co/json/"); } double latitude = area.getDouble("latitude"), longitude = area.getDouble("longitude"); String city = area.optString("city", "Ma position"); runOnUiThread(() -> { if (generation != weatherGeneration || isDestroyed()) return; loadWeather(latitude, longitude, city, icon, label, currentTemperature, forecastIcons, forecastDays, forecastTemperatures); }); } catch (Exception error) { runOnUiThread(() -> { if (generation != weatherGeneration || isDestroyed()) return; weatherRequestInFlight = false; if (cachedWeather == null && activeWeatherWidget != null) { activeWeatherWidget.label.setText("Météo indisponible"); activeWeatherWidget.currentTemperature.setText("--°"); setForecastVisibility(activeWeatherWidget.forecastDays, false); weatherRefreshHandler.postDelayed(this::retryWeatherIfMissing, WEATHER_RETRY_DELAY_MS); } }); } }).start(); }
    private JSONObject fetchJson(String address) throws java.io.IOException, org.json.JSONException { java.net.HttpURLConnection connection = (java.net.HttpURLConnection) new java.net.URL(address).openConnection(); connection.setConnectTimeout(7000); connection.setReadTimeout(7000); connection.setRequestProperty("User-Agent", "JojoHome/1.0"); java.io.BufferedReader reader = new java.io.BufferedReader(new java.io.InputStreamReader(connection.getInputStream())); StringBuilder json = new StringBuilder(); String line; while ((line = reader.readLine()) != null) json.append(line); reader.close(); connection.disconnect(); return new JSONObject(json.toString()); }
    private void loadWeather(double latitude, double longitude, String knownCity, ImageView icon, TextView label, TextView currentTemperature, ImageView[] forecastIcons, TextView[] forecastDays, TextView[] forecastTemperatures) { final int generation = weatherGeneration; new Thread(() -> { try {
            if (BuildConfig.VISUAL_CROSSING_API_KEY.isEmpty()) throw new java.io.IOException("Clé Visual Crossing manquante");
            String city = knownCity.isEmpty() ? "Ma position" : knownCity;
            String address = latitude + "," + longitude;
            JSONObject response = fetchJson("https://weather.visualcrossing.com/VisualCrossingWebServices/rest/services/timeline/" + address + "/next4days?unitGroup=metric&include=current,days&contentType=json&key=" + java.net.URLEncoder.encode(BuildConfig.VISUAL_CROSSING_API_KEY, "UTF-8"));
            JSONObject current = response.getJSONObject("currentConditions"); org.json.JSONArray days = response.getJSONArray("days");
            String condition = current.optString("icon", "cloudy");
            String result = city == null || city.isEmpty() ? "Ma position" : city;
            String currentTemperatureValue = Math.round(current.optDouble("temp", current.optDouble("feelslike", 0d))) + "°";
            String[] forecastDayValues = new String[3];
            String[] forecastTemperatureValues = new String[3];
            String[] forecastConditionValues = new String[3];
            for (int index = 0; index < 3; index++) try {
                JSONObject dayValue = days.getJSONObject(index + 1);
                String day = new SimpleDateFormat("EEE", Locale.FRENCH).format(new SimpleDateFormat("yyyy-MM-dd", Locale.US).parse(dayValue.getString("datetime")));
                forecastDayValues[index] = day.substring(0, 1).toUpperCase(Locale.FRENCH) + day.substring(1);
                forecastTemperatureValues[index] = Math.round(dayValue.getDouble("tempmax")) + "°";
                forecastConditionValues[index] = dayValue.optString("icon", "cloudy");
            } catch (Exception ignored) { }
            WeatherSnapshot snapshot = new WeatherSnapshot(result, currentTemperatureValue, condition, forecastDayValues, forecastTemperatureValues, forecastConditionValues);
            runOnUiThread(() -> { if (generation != weatherGeneration || isDestroyed()) return;
                publishWeatherSnapshot(snapshot);
            });
            // Resolving a locality must not hold up the current temperature and forecast.
            if (knownCity.isEmpty()) {
                String resolvedCity = cityAt(latitude, longitude);
                if (resolvedCity != null && !resolvedCity.isEmpty() && !resolvedCity.equals(result)) {
                    WeatherSnapshot located = new WeatherSnapshot(resolvedCity, currentTemperatureValue,
                            condition, forecastDayValues, forecastTemperatureValues, forecastConditionValues);
                    runOnUiThread(() -> {
                        if (generation != weatherGeneration || isDestroyed() || cachedWeather != snapshot) return;
                        publishWeatherSnapshot(located);
                    });
                }
            }
         } catch (Exception error) { runOnUiThread(() -> { if (generation != weatherGeneration || isDestroyed()) return; weatherRequestInFlight = false; if (cachedWeather == null && activeWeatherWidget != null) { activeWeatherWidget.label.setText("Météo indisponible"); activeWeatherWidget.currentTemperature.setText("--°"); setForecastVisibility(activeWeatherWidget.forecastDays, false); } }); } }).start(); }
    private void loadWeatherForCity(String requestedCity, ImageView icon, TextView label, TextView currentTemperature, ImageView[] forecastIcons, TextView[] forecastDays, TextView[] forecastTemperatures) { final int generation = weatherGeneration; new Thread(() -> { try {
            if (BuildConfig.VISUAL_CROSSING_API_KEY.isEmpty()) throw new java.io.IOException("Clé Visual Crossing manquante");
            String city = requestedCity == null ? "" : requestedCity.trim();
            if (city.isEmpty()) throw new java.io.IOException("Ville manquante");
            String address = java.net.URLEncoder.encode(city, "UTF-8").replace("+", "%20");
            JSONObject response = fetchJson("https://weather.visualcrossing.com/VisualCrossingWebServices/rest/services/timeline/" + address + "/next4days?unitGroup=metric&include=current,days&contentType=json&key=" + java.net.URLEncoder.encode(BuildConfig.VISUAL_CROSSING_API_KEY, "UTF-8"));
            JSONObject current = response.getJSONObject("currentConditions"); org.json.JSONArray days = response.getJSONArray("days");
            String condition = current.optString("icon", "cloudy");
            String currentTemperatureValue = Math.round(current.optDouble("temp", current.optDouble("feelslike", 0d))) + "°";
            String[] forecastDayValues = new String[3];
            String[] forecastTemperatureValues = new String[3];
            String[] forecastConditionValues = new String[3];
            for (int index = 0; index < 3; index++) try {
                JSONObject dayValue = days.getJSONObject(index + 1);
                String day = new SimpleDateFormat("EEE", Locale.FRENCH).format(new SimpleDateFormat("yyyy-MM-dd", Locale.US).parse(dayValue.getString("datetime")));
                forecastDayValues[index] = day.substring(0, 1).toUpperCase(Locale.FRENCH) + day.substring(1);
                forecastTemperatureValues[index] = Math.round(dayValue.getDouble("tempmax")) + "°";
                forecastConditionValues[index] = dayValue.optString("icon", "cloudy");
            } catch (Exception ignored) { }
            WeatherSnapshot snapshot = new WeatherSnapshot(city, currentTemperatureValue, condition, forecastDayValues, forecastTemperatureValues, forecastConditionValues);
            runOnUiThread(() -> { if (generation != weatherGeneration || isDestroyed()) return;
                publishWeatherSnapshot(snapshot);
            });
        } catch (Exception error) { runOnUiThread(() -> { if (generation != weatherGeneration || isDestroyed()) return; weatherRequestInFlight = false; if (cachedWeather == null && activeWeatherWidget != null) { activeWeatherWidget.label.setText("Ville introuvable"); activeWeatherWidget.currentTemperature.setText("--°"); setForecastVisibility(activeWeatherWidget.forecastDays, false); weatherRefreshHandler.postDelayed(this::retryWeatherIfMissing, WEATHER_RETRY_DELAY_MS); } }); } }).start(); }
    private String cityAt(double latitude, double longitude) { try { List<Address> places = new Geocoder(this, Locale.FRENCH).getFromLocation(latitude, longitude, 1); if (places != null && !places.isEmpty()) return places.get(0).getLocality(); } catch (Exception ignored) { } return "Ma position"; }
    private int weatherIconRes(String condition) { if ("clear-day".equals(condition)) return R.drawable.ic_weather_sun; if ("clear-night".equals(condition)) return R.drawable.ic_weather_moon; if ("partly-cloudy-night".equals(condition)) return R.drawable.ic_weather_partly_cloudy_night; if (condition.contains("partly-cloudy")) return R.drawable.ic_weather_partly_cloudy; if (condition.contains("snow") || condition.contains("sleet")) return R.drawable.ic_weather_snow; if (condition.contains("thunder")) return R.drawable.ic_weather_storm; if (condition.contains("fog")) return R.drawable.ic_weather_fog; if (condition.contains("rain") || condition.contains("showers")) return R.drawable.ic_weather_rain; return R.drawable.ic_weather_cloud; }

