    private void startVoiceSearch() {
        try { Intent speech = new Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH); speech.putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL, RecognizerIntent.LANGUAGE_MODEL_FREE_FORM); speech.putExtra(RecognizerIntent.EXTRA_PROMPT, "Dites le nom d’une application"); startActivityForResult(speech, 400); }
        catch (Exception ignored) { Toast.makeText(this, "La recherche vocale n’est pas disponible", Toast.LENGTH_SHORT).show(); }
    }
    private void openTextSearch() {
        LinearLayout page = new LinearLayout(this); page.setOrientation(LinearLayout.VERTICAL); page.setGravity(Gravity.CENTER); page.setPadding(dp(160), 0, dp(160), 0); page.setBackgroundColor(Color.rgb(15, 28, 61));
        TextView title = text("Rechercher dans Jojo Home", 26, white); page.addView(title); page.addView(space(20));
        EditText field = new EditText(this); field.setTextColor(white); field.setTextSize(22); field.setSingleLine(true); field.setImeOptions(android.view.inputmethod.EditorInfo.IME_ACTION_SEARCH); field.setHint("Application, vidéo ou dossier"); field.setHintTextColor(muted); field.setBackgroundColor(Color.rgb(38, 57, 104)); field.setPadding(dp(20), 0, dp(20), 0); page.addView(field, new LinearLayout.LayoutParams(-1, dp(65)));
        LinearLayout history = new LinearLayout(this); history.setOrientation(LinearLayout.VERTICAL); history.setPadding(0, dp(14), 0, dp(4)); page.addView(history, new LinearLayout.LayoutParams(-1, -2));
        LinearLayout results = new LinearLayout(this);
        results.setOrientation(LinearLayout.VERTICAL);
        results.setClipChildren(false);
        results.setClipToPadding(false);
        page.addView(results, new LinearLayout.LayoutParams(-1, 0, 1f));
        final Runnable[] runSearch = new Runnable[1];
        Runnable refreshHistory = () -> {
            history.removeAllViews();
            List<String> recent = searchHistory();
            if (recent.isEmpty()) return;
            TextView recentTitle = text("Recherches récentes", 16, muted);
            history.addView(recentTitle, new LinearLayout.LayoutParams(-1, dp(34)));
            LinearLayout recentRows = new LinearLayout(this); recentRows.setGravity(Gravity.CENTER_VERTICAL);
            for (String query : recent) {
                TextView item = text(query, 15, white); item.setGravity(Gravity.CENTER); item.setFocusable(true); item.setSingleLine(true); item.setEllipsize(TextUtils.TruncateAt.END); item.setPadding(dp(14), 0, dp(14), 0); item.setBackground(cardBg());
                item.setOnFocusChangeListener((v, focused) -> item.setBackground(focused ? roundedMenuFocusBg() : cardBg()));
                item.setOnClickListener(v -> { field.setText(query); field.setSelection(field.length()); field.requestFocus(); runSearch[0].run(); });
                recentRows.addView(item, new LinearLayout.LayoutParams(dp(150), dp(46)));
                recentRows.addView(spaceWidth(8));
            }
            history.addView(recentRows, new LinearLayout.LayoutParams(-1, dp(50)));
        };
        runSearch[0] = () -> {
            String enteredQuery = field.getText().toString().trim();
            String query = enteredQuery.toLowerCase(Locale.ROOT);
            results.removeAllViews();
            if (query.isEmpty()) {
                results.addView(text("Saisissez un nom puis validez avec Entrée.", 16, muted),
                        new LinearLayout.LayoutParams(-1, dp(54)));
                return;
            }
            rememberSearchQuery(enteredQuery);
            refreshHistory.run();
            results.addView(text("Recherche en cours…", 16, muted),
                    new LinearLayout.LayoutParams(-1, dp(54)));
            new Thread(() -> {
                ArrayList<android.content.pm.ResolveInfo> matches = new ArrayList<>();
                for (android.content.pm.ResolveInfo info : allLaunchableApps()) {
                    if (info == null || info.activityInfo == null
                            || info.activityInfo.packageName.equals(getPackageName())) continue;
                    String label = homeAppLabel(info).toLowerCase(Locale.ROOT);
                    if (label.contains(query) || info.activityInfo.packageName.toLowerCase(Locale.ROOT).contains(query)) {
                        matches.add(info);
                    }
                }
                ArrayList<HomeSearchMediaResult> mediaMatches = searchExternalMedia(query);
                runOnUiThread(() -> {
                    if (activeScreen != page) return;
                    results.removeAllViews();
                    renderSearchResultGroups(results, matches, mediaMatches);
                    results.addView(text("Recherche des dossiers et vidéos SMB…", 16, muted), new LinearLayout.LayoutParams(-1, dp(42)));
                    focusFirst(results);
                });
                new Thread(() -> {
                    ArrayList<HomeSearchMediaResult> smbMatches = searchHomeMedia(query);
                    runOnUiThread(() -> {
                        if (activeScreen != page) return;
                        removeSearchStatus(results);
                        if (!smbMatches.isEmpty()) {
                            results.addView(text("Vidéos et dossiers", 16, muted), new LinearLayout.LayoutParams(-1, dp(42)));
                            for (HomeSearchMediaResult result : smbMatches) results.addView(homeSearchMediaResultRow(result), new LinearLayout.LayoutParams(-1, dp(68)));
                        } else if (matches.isEmpty() && mediaMatches.isEmpty()) {
                            results.addView(text("Aucun résultat trouvé.", 16, muted), new LinearLayout.LayoutParams(-1, dp(54)));
                        }
                    });
                }, "JojoSmbSearch").start();
            }, "JojoTextSearch").start();
        };
        field.setOnEditorActionListener((view, actionId, event) -> {
            boolean enter = event != null && event.getKeyCode() == KeyEvent.KEYCODE_ENTER
                    && event.getAction() == KeyEvent.ACTION_DOWN;
            if (actionId == android.view.inputmethod.EditorInfo.IME_ACTION_SEARCH || enter) {
                ((InputMethodManager) getSystemService(Context.INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(field.getWindowToken(), 0);
                runSearch[0].run();
                return true;
            }
            return false;
        });
        field.setOnKeyListener((view, keyCode, event) -> {
            if (event.getAction() == KeyEvent.ACTION_DOWN
                    && (keyCode == KeyEvent.KEYCODE_DPAD_CENTER || keyCode == KeyEvent.KEYCODE_ENTER)) {
                runSearch[0].run();
                return true;
            }
            return false;
        });
        refreshHistory.run();
        openScreen(page); field.requestFocus(); field.post(() -> ((InputMethodManager) getSystemService(Context.INPUT_METHOD_SERVICE)).showSoftInput(field, InputMethodManager.SHOW_IMPLICIT));
    }

    private List<String> searchHistory() {
        String raw = getSharedPreferences(SEARCH_HISTORY_PREFS, MODE_PRIVATE).getString(SEARCH_HISTORY_KEY, "");
        ArrayList<String> result = new ArrayList<>();
        if (raw == null || raw.trim().isEmpty()) return result;
        for (String value : raw.split("\\u001f", -1)) if (!value.trim().isEmpty() && !result.contains(value.trim())) result.add(value.trim());
        return result;
    }

    private void rememberSearchQuery(String query) {
        String normalized = query == null ? "" : query.trim();
        if (normalized.isEmpty()) return;
        ArrayList<String> values = new ArrayList<>(); values.add(normalized);
        for (String value : searchHistory()) if (!value.equalsIgnoreCase(normalized)) values.add(value);
        if (values.size() > SEARCH_HISTORY_LIMIT) values.subList(SEARCH_HISTORY_LIMIT, values.size()).clear();
        getSharedPreferences(SEARCH_HISTORY_PREFS, MODE_PRIVATE).edit().putString(SEARCH_HISTORY_KEY, TextUtils.join("\u001f", values)).apply();
    }

    private void renderSearchResultGroups(LinearLayout results, ArrayList<android.content.pm.ResolveInfo> matches, ArrayList<HomeSearchMediaResult> mediaMatches) {
        if (!matches.isEmpty()) {
            results.addView(text("Applications", 16, muted), new LinearLayout.LayoutParams(-1, dp(42)));
            for (android.content.pm.ResolveInfo info : matches) results.addView(appSearchResultRow(info), new LinearLayout.LayoutParams(-1, dp(68)));
        }
        if (!mediaMatches.isEmpty()) {
            results.addView(text("Films, séries et TV", 16, muted), new LinearLayout.LayoutParams(-1, dp(42)));
            for (HomeSearchMediaResult result : mediaMatches) results.addView(homeSearchMediaResultRow(result), new LinearLayout.LayoutParams(-1, dp(68)));
        }
    }

    private void removeSearchStatus(LinearLayout results) {
        int last = results.getChildCount() - 1;
        if (last >= 0 && results.getChildAt(last) instanceof TextView
                && ((TextView) results.getChildAt(last)).getText().toString().startsWith("Recherche des dossiers")) results.removeViewAt(last);
    }

    private static final class HomeSearchMediaResult {
        final String title;
        final String subtitle;
        final String smbPath;
        final String smbUser;
        final String smbPassword;
        final boolean directory;
        final JSONObject externalItem;
        final String externalCategory;

        HomeSearchMediaResult(String title, String subtitle, String smbPath,
                              String smbUser, String smbPassword, boolean directory) {
            this.title = title;
            this.subtitle = subtitle;
            this.smbPath = smbPath;
            this.smbUser = smbUser;
            this.smbPassword = smbPassword;
            this.directory = directory;
            this.externalItem = null;
            this.externalCategory = "";
        }

        HomeSearchMediaResult(String title, String subtitle, JSONObject externalItem,
                              String externalCategory) {
            this.title = title;
            this.subtitle = subtitle;
            this.smbPath = "";
            this.smbUser = "";
            this.smbPassword = "";
            this.directory = false;
            this.externalItem = externalItem;
            this.externalCategory = externalCategory;
        }
    }

    private ArrayList<HomeSearchMediaResult> searchHomeMedia(String query) {
        ArrayList<HomeSearchMediaResult> results = new ArrayList<>();
        String normalizedQuery = query == null ? "" : query.trim().toLowerCase(Locale.ROOT);
        if (normalizedQuery.isEmpty()) return results;

        SmbConnectionConfig connection = defaultSmbConnection();
        if (connection != null && !connection.server.isEmpty()) {
            try {
                jcifs.CIFSContext context = smbContext(connection.user, connection.password, 8000);
                java.util.ArrayDeque<jcifs.smb.SmbFile> folders = new java.util.ArrayDeque<>();
                java.util.ArrayDeque<Integer> depths = new java.util.ArrayDeque<>();
                java.util.HashSet<String> visited = new java.util.HashSet<>();
                String root = connection.browserUrl();
                folders.add(new jcifs.smb.SmbFile(root, context));
                depths.add(0);
                while (!folders.isEmpty() && results.size() < 100) {
                    jcifs.smb.SmbFile folder = folders.removeFirst();
                    int depth = depths.removeFirst();
                    String folderPath = folder.getPath();
                    String visitKey = comparableSmbPath(folderPath);
                    if (!visited.add(visitKey) || depth > 8) continue;
                    jcifs.smb.SmbFile[] children;
                    try { children = folder.listFiles(); } catch (Exception ignored) { continue; }
                    for (jcifs.smb.SmbFile child : children) {
                        if (results.size() >= 100) break;
                        String name = cleanFileName(child.getName());
                        if (name.isEmpty()) continue;
                        boolean directory;
                        try { directory = child.isDirectory(); } catch (Exception ignored) { continue; }
                        if (name.toLowerCase(Locale.ROOT).contains(normalizedQuery)) {
                            results.add(new HomeSearchMediaResult(
                                    name,
                                    directory ? "Dossier SMB" : "Vidéo · " + cleanFileName(folder.getName()),
                                    child.getPath(), connection.user, connection.password, directory));
                        }
                        if (directory && depth < 8) {
                            folders.addLast(child);
                            depths.addLast(depth + 1);
                        }
                    }
                }
            } catch (Exception ignored) { }
        }

        return results;
    }

    private ArrayList<HomeSearchMediaResult> searchExternalMedia(String query) {
        ArrayList<HomeSearchMediaResult> results = new ArrayList<>();
        String normalizedQuery = query == null ? "" : query.trim().toLowerCase(Locale.ROOT);
        if (normalizedQuery.isEmpty()) return results;
        for (String category : new String[]{"movies", "series", "live"}) {
            for (JSONObject item : ExternalPlaybackStore.list(this, category)) {
                String title = item.optString("title", "").trim();
                if (!title.isEmpty() && title.toLowerCase(Locale.ROOT).contains(normalizedQuery)) {
                    results.add(new HomeSearchMediaResult(title,
                            externalSearchCategoryLabel(category), item, category));
                }
                if (results.size() >= 150) return results;
            }
        }
        return results;
    }

    private String externalSearchCategoryLabel(String category) {
        if ("movies".equals(category)) return "Film";
        if ("series".equals(category)) return "Série";
        if ("live".equals(category)) return "TV";
        return "Média";
    }

