    private View spaceWidth(int width) { View view = new View(this); view.setLayoutParams(new LinearLayout.LayoutParams(dp(width), 1)); return view; }
    private LinearLayout appRows() {
        renderedAppRows.clear();
        List<android.content.pm.ResolveInfo> visible = orderedFavoriteApps();
        LinearLayout area = new LinearLayout(this); area.setOrientation(LinearLayout.VERTICAL); area.setClipChildren(false); area.setClipToPadding(false); area.setPadding(dp(24), dp(4), dp(24), dp(4));

        int rows = homeRows();
        int columns = Math.max(1, (int) Math.ceil((visible.size() + 1) / (double) rows));
        ArrayList<View> tiles = new ArrayList<>();
        for (android.content.pm.ResolveInfo info : visible) {
            View tile = appTile(info); tile.setId(View.generateViewId()); tiles.add(tile);
        }
        View addTile = appAddTile(); addTile.setId(View.generateViewId()); tiles.add(addTile);

        int tileIndex = 0;
        for (int rowIndex = 0; rowIndex < rows; rowIndex++) {
            GridLayout grid = new GridLayout(this);
            grid.setRowCount(1);
            grid.setColumnCount(columns);
            grid.setClipChildren(false);
            grid.setClipToPadding(false);

            for (int columnIndex = 0; columnIndex < columns && tileIndex < tiles.size(); columnIndex++, tileIndex++) {
                View tile = tiles.get(tileIndex);
                if (tileIndex == 0) registerHomeRowMoveTrigger(tile, "apps");
                GridLayout.LayoutParams params = new GridLayout.LayoutParams();
                params.rowSpec = GridLayout.spec(0);
                params.columnSpec = GridLayout.spec(columnIndex);
                params.width = dp(iconTileWidth());
                params.height = dp(iconTileHeight());
                // Tighter resting layout; focused cards still draw above their
                // neighbours because the grid and scroll container do not clip.
                params.setMargins(dp(1), dp(4), dp(1), dp(4));
                grid.addView(tile, params);
            }

            renderedAppRows.add(grid);
            wireAppRowDpad(grid);

            FrameLayout rowContainer = new FrameLayout(this);
            rowContainer.setClipChildren(false);
            rowContainer.setClipToPadding(false);

            // no external handle for row move; tiles handle focus directly

            HorizontalScrollView scroll = new HorizontalScrollView(this);
            scroll.setHorizontalScrollBarEnabled(false);
            scroll.setClipToPadding(false);
            scroll.setClipChildren(false);
            scroll.addView(grid);
            rowContainer.addView(scroll, new FrameLayout.LayoutParams(-1, dp(appRowHeight())));

            LinearLayout.LayoutParams rowParams = new LinearLayout.LayoutParams(-1, dp(appRowHeight()));
            if (rowIndex > 0) rowParams.topMargin = dp(10);
            area.addView(rowContainer, rowParams);
        }

        if (pendingFocusPackage != null) {
            String targetPackage = pendingFocusPackage;
            area.post(() -> { View target = area.findViewWithTag(targetPackage); pendingFocusPackage = null; if (target != null) target.requestFocus(); else focusFirst(area); });
        }

        wireRenderedAppHorizontalDpad();

        return area;
    }

    private boolean appsOpenFromHeader() { return true; }
    private String appsOpenModeLabel() { return "Icône Apps du header"; }

    private List<android.content.pm.ResolveInfo> orderedFavoriteApps() {
        Set<String> hidden = hiddenApps();
        Set<String> favorites = favoriteApps();
        LinkedHashMap<String, android.content.pm.ResolveInfo> byPackage = new LinkedHashMap<>();
        for (android.content.pm.ResolveInfo info : allLaunchableApps()) {
            String packageName = info.activityInfo.packageName;
            if (favorites.contains(packageName) && !hidden.contains(packageName)) {
                byPackage.put(packageName, info);
            }
        }
        ArrayList<android.content.pm.ResolveInfo> ordered = new ArrayList<>();
        for (String packageName : appOrder()) {
            android.content.pm.ResolveInfo info = byPackage.remove(packageName);
            if (info != null) ordered.add(info);
        }
        ordered.addAll(byPackage.values());
        return ordered;
    }

    /** Fast header-menu lookup: resolve only packages already marked favorite. */
    private List<android.content.pm.ResolveInfo> orderedFavoriteAppsFast() {
        PackageManager pm = getPackageManager();
        Set<String> hidden = hiddenApps();
        Set<String> favorites = favoriteApps();
        java.util.LinkedHashSet<String> packageOrder = new java.util.LinkedHashSet<>(appOrder());
        packageOrder.addAll(favorites);
        ArrayList<android.content.pm.ResolveInfo> result = new ArrayList<>();
        for (String packageName : packageOrder) {
            if (packageName == null || packageName.isEmpty()
                    || hidden.contains(packageName) || !favorites.contains(packageName)) continue;
            Intent launch = pm.getLeanbackLaunchIntentForPackage(packageName);
            if (launch == null) launch = pm.getLaunchIntentForPackage(packageName);
            android.content.pm.ResolveInfo info = launch == null ? null : pm.resolveActivity(launch, 0);
            if (info == null || info.activityInfo == null
                    || !packageName.equals(info.activityInfo.packageName)) {
                // Some TV apps are discoverable through their launcher category,
                // although PackageManager cannot produce a package launch intent.
                info = queryFavoriteLauncherActivity(pm, packageName,
                        Intent.CATEGORY_LEANBACK_LAUNCHER);
                if (info == null) {
                    info = queryFavoriteLauncherActivity(pm, packageName,
                            Intent.CATEGORY_LAUNCHER);
                }
            }
            if (info != null && info.activityInfo != null
                    && packageName.equals(info.activityInfo.packageName)) result.add(info);
        }
        return result;
    }

    private android.content.pm.ResolveInfo queryFavoriteLauncherActivity(
            PackageManager pm, String packageName, String category) {
        Intent query = new Intent(Intent.ACTION_MAIN).addCategory(category).setPackage(packageName);
        for (android.content.pm.ResolveInfo info : pm.queryIntentActivities(query, 0)) {
            if (info != null && info.activityInfo != null
                    && packageName.equals(info.activityInfo.packageName)) return info;
        }
        return null;
    }


    private android.graphics.drawable.Drawable appTileStageBackground(
            String onlineIconId, boolean smartTube, int fallbackTileColor) {
        GradientDrawable background;
        if (!onlineIconId.isEmpty()) background = onlineAppIconBackground();
        else if (smartTube) background = smartTubeBg();
        else {
            background = new GradientDrawable();
            background.setColor(fallbackTileColor);
        }
        return background;
    }

    private View appTile(final android.content.pm.ResolveInfo info) {
        return appTile(info, false);
    }

    private View appTile(final android.content.pm.ResolveInfo info, boolean alwaysShowLabel) {
        LinearLayout card = new LinearLayout(this); card.setOrientation(LinearLayout.VERTICAL); card.setGravity(Gravity.CENTER);
        card.setPadding(0, 0, 0, 0); card.setFocusable(true); card.setClipChildren(false); card.setClipToPadding(false);
        String appLabel = homeAppLabel(info);
        ImageView icon = new AppIconImageView(this); android.graphics.drawable.Drawable activityBanner = info.activityInfo.loadBanner(getPackageManager()); android.graphics.drawable.Drawable applicationBanner = info.activityInfo.applicationInfo.loadBanner(getPackageManager()); boolean isOfficialCanalPlus = AppTileRules.usesOfficialCanalPlusBanner(info.activityInfo.packageName); android.graphics.drawable.Drawable banner = isOfficialCanalPlus ? officialCanalPlusBanner() : (AppTileRules.usesApplicationBannerBeforeActivityBanner() && applicationBanner != null ? applicationBanner : activityBanner);
        android.graphics.drawable.Drawable customIcon = appIconDrawable(info.activityInfo.packageName); String onlineIconId = onlineAppIconId(info.activityInfo.packageName); boolean smartTube = isSmartTube(info.activityInfo.packageName); boolean centeredFallbackIcon = AppTileRules.usesCenteredFallbackIcon(banner != null, customIcon != null || !onlineIconId.isEmpty());
        android.graphics.drawable.Drawable rawSource = customIcon != null ? customIcon : (smartTube ? info.loadIcon(getPackageManager()) : (banner != null ? banner : info.loadIcon(getPackageManager())));
        boolean recenteredBanner = AppTileRules.requiresRecenteredBanner(info.activityInfo.packageName);
        int fallbackTileColor = (centeredFallbackIcon || recenteredBanner) ? AppTileRules.fallbackTileColor(info.activityInfo.packageName) : Color.TRANSPARENT;
        final android.graphics.drawable.Drawable source = rawSource;
        icon.setImageDrawable(source); if (!onlineIconId.isEmpty()) OnlineAppIconLoader.load(icon, onlineIconId); icon.setScaleType(ImageView.ScaleType.CENTER_INSIDE); icon.setPadding(0, 0, 0, 0); icon.setBackground(appTileStageBackground(onlineIconId, smartTube, fallbackTileColor));
        FrameLayout iconStage = new FrameLayout(this); iconStage.setClipChildren(true); iconStage.setClipToPadding(true); iconStage.setPadding(0, 0, 0, 0); iconStage.addView(icon, new FrameLayout.LayoutParams(-1, -1));
        card.addView(iconStage, new LinearLayout.LayoutParams(-1, dp(appBannerHeight())));
        String labelsMode = alwaysShowLabel ? "always" : appLabelsMode();
        boolean labelsAlways = "always".equals(labelsMode);
        boolean labelsNever = "never".equals(labelsMode);
        TextView name = text(appLabel, 12, white); name.setGravity(Gravity.CENTER); name.setSingleLine(true); name.setEllipsize(TextUtils.TruncateAt.END); name.setAlpha(labelsNever ? 0f : AppPresentationRules.labelAlpha(labelsAlways, false)); name.setTranslationY(labelsAlways ? 0f : -dp(4));
        card.addView(name, new LinearLayout.LayoutParams(-1, dp(26)));
        // Start tiles at unfocused scale
        card.setScaleX(unfocusedScaleX());
        card.setScaleY(unfocusedScaleY());
        card.setOnFocusChangeListener((v, focused) -> {
            icon.setBackground(appTileStageBackground(onlineIconId, smartTube, fallbackTileColor));
            boolean moving = info.activityInfo.packageName.equals(movingPackageName);
            float scaleX = moving ? 1.18f : unfocusedScaleX();
            float scaleY = moving ? 1.18f : unfocusedScaleY();
            card.animate().alpha(moving ? 1f : (movingPackageName == null ? 1f : .38f)).scaleX(scaleX).scaleY(scaleY).setDuration(120).start();
            float iconScaleX = focused && !moving ? appFocusScaleX() : 1f;
            float iconScaleY = focused && !moving ? appFocusScaleY() : 1f;
            // Scale the common mask and the artwork together on focus.
            iconStage.animate().scaleX(iconScaleX).scaleY(iconScaleY).setDuration(120).start();
            // Keep the enlarged banner above its neighbours without changing the
            // GridLayout child order: bringToFront() would break its scrolling.
            card.setElevation(focused && !moving ? dp(20) : 0);
            iconStage.setElevation(AppTileRules.elevatesTransparentStageOnFocus() && focused && !moving ? dp(14) : 0);
            name.animate().alpha(labelsNever ? 0f : AppPresentationRules.labelAlpha(labelsAlways, focused)).translationY(labelsAlways || (!labelsNever && focused) ? 0f : -dp(4)).setDuration(160).start();
            if (focused) { revealAppTile(v); updateDynamicBackground(source); }
        });
        final boolean addingFavorite = pendingAddFavorite;
        card.setOnClickListener(v -> {
            String packageName = info.activityInfo.packageName;
            if (addingFavorite) {
                // Explicitly adding an app must make it visible in the Apps column.
                try {
                    Set<String> favorites = favoriteApps();
                    if (favorites.contains(packageName)) {
                        Toast.makeText(this, "Application déjà présente dans les favoris", Toast.LENGTH_SHORT).show();
                        return;
                    }
                    favorites.add(packageName);
                    saveFavoriteApps(favorites);
                    Set<String> hidden = hiddenApps();
                    if (hidden.remove(packageName))
                        homePrefs().edit().putStringSet("hidden_apps", hidden).apply();
                    List<String> order = appOrder();
                    if (!order.contains(packageName)) {
                        order.add(packageName);
                        homePrefs().edit().putString(appOrderKey(), joinOrder(order)).apply();
                    }
                } catch (Exception ignored) {}
                Toast.makeText(this, "Application ajoutée aux favoris", Toast.LENGTH_SHORT).show();
                return;
            }
            openPackage(packageName, appLabel);
        });
        card.setOnLongClickListener(v -> { if (activePopup == null || !activePopup.isShowing()) showAppMenu(info, card); return true; });
        card.setTag(info.activityInfo.packageName);
        final boolean[] contextMenuOpened = {false};
        card.setOnKeyListener((v, keyCode, event) -> {
            if (movingPackageName != null && event.getAction() == KeyEvent.ACTION_DOWN) {
                if (event.getRepeatCount() != 0) return true;
                if (keyCode == KeyEvent.KEYCODE_DPAD_LEFT) { moveApp(-1); return true; }
                if (keyCode == KeyEvent.KEYCODE_DPAD_RIGHT) { moveApp(1); return true; }
                if (keyCode == KeyEvent.KEYCODE_DPAD_CENTER || keyCode == KeyEvent.KEYCODE_ENTER) { finishAppMove(); return true; }
            }
            if (handleHomeRowMoveKey(v, keyCode, event)) return true;
            if (event.getAction() == KeyEvent.ACTION_DOWN && event.getRepeatCount() == 0
                    && keyCode == KeyEvent.KEYCODE_DPAD_UP) {
                View target = homeAppUpTarget(v);
                if (target != null && target != v) {
                    target.post(target::requestFocus);
                    return true;
                }
            }
            if (event.getAction() == KeyEvent.ACTION_DOWN && event.getRepeatCount() == 0
                    && keyCode == KeyEvent.KEYCODE_DPAD_DOWN) {
                // Only try to jump down to the home "resumes" row when the
                // active screen is the home screen (activeScreen == null).
                if (activeScreen == null) {
                    View target = firstFocusableChild((ViewGroup) currentHomeResumesView);
                    if (target != null && target != v) {
                        target.post(target::requestFocus);
                        return true;
                    }
                }
            }
            if (AppUninstallRules.opensContextMenuOnDpadLongPress(event.getAction(), keyCode, event.getRepeatCount())) {
                if (!contextMenuOpened[0]) {
                    contextMenuOpened[0] = true;
                    showAppMenu(info, card);
                }
                return true;
            }
            if (contextMenuOpened[0] && event.getAction() == KeyEvent.ACTION_UP && (keyCode == KeyEvent.KEYCODE_DPAD_CENTER || keyCode == KeyEvent.KEYCODE_ENTER)) {
                contextMenuOpened[0] = false;
                return true;
            }
            return keepHorizontalFocus(v, keyCode, event);
        });
        return card;
    }

    private View homeAppUpTarget(View origin) {
        if (origin == null || activeScreen != null) return null;
        int upId = origin.getNextFocusUpId();
        if (upId != View.NO_ID) {
            View target = origin.getRootView() != null ? origin.getRootView().findViewById(upId) : null;
            if (target != null && target != origin) return target;
        }
        if (currentHomeHeaderView == null) return null;
        Object headerTag = currentHomeHeaderView.getTag();
        if (!(headerTag instanceof LinearLayout)) return null;
        LinearLayout bar = (LinearLayout) headerTag;
        for (int index = 0; index < bar.getChildCount(); index++) {
            View child = bar.getChildAt(index);
            if (child != null && child.isFocusable() && child.getVisibility() == View.VISIBLE) {
                return child;
            }
        }
        return null;
    }

    private View appAddTile() { return appAddTile(false); }

    private View appAddTile(boolean headerMenuStyle) {
        return appAddTile(headerMenuStyle, null, null, null);
    }

    private View appAddTile(boolean headerMenuStyle, View headerAnchor, PopupWindow popup,
                            View[] pendingHeaderFocus) {
        LinearLayout card = new LinearLayout(this);
        card.setOrientation(LinearLayout.VERTICAL);
        card.setGravity(Gravity.CENTER);
        card.setFocusable(true);
        card.setClipChildren(false);
        card.setClipToPadding(false);

        FrameLayout iconStage = new FrameLayout(this);
        iconStage.setBackground(settingsCardBg(false));
        iconStage.setClipChildren(true);
        iconStage.setClipToPadding(true);
        iconStage.setLayerType(View.LAYER_TYPE_HARDWARE, null);
        iconStage.setOutlineProvider(new ViewOutlineProvider() {
            @Override public void getOutline(View view, Outline outline) {
                outline.setRoundRect(0, 0, view.getWidth(), view.getHeight(),
                        dp(headerMenuStyle ? 7 : SettingsPresentation.cardCornerRadiusDp()));
            }
        });
        iconStage.setClipToOutline(true);

        TextView plus = text("+", 42, Color.WHITE);
        plus.setGravity(Gravity.CENTER);
        plus.setTypeface(null, Typeface.BOLD);
        plus.setSingleLine(true);
        plus.setPadding(0, 0, 0, 0);
        iconStage.addView(plus, new FrameLayout.LayoutParams(-1, -1));
        final View focusBorder;
        if (!headerMenuStyle) {
            focusBorder = new View(this);
            focusBorder.setBackground(appFocusBorder());
            focusBorder.setAlpha(0f);
            iconStage.addView(focusBorder, new FrameLayout.LayoutParams(-1, -1));
        } else {
            focusBorder = null;
        }

        int stageWidth = headerMenuStyle ? Math.round(headerAppsMenuTileWidth() * .8f) : dp(iconTileWidth());
        int stageHeight = headerMenuStyle
                ? Math.round(Math.round(headerAppsMenuTileWidth() * 9f / 16f) * .8f)
                : dp(appBannerHeight());
        LinearLayout.LayoutParams iconStageParams = new LinearLayout.LayoutParams(stageWidth, stageHeight);
        iconStageParams.gravity = Gravity.CENTER_HORIZONTAL;
        card.addView(iconStage, iconStageParams);
        TextView labelStub = text("Ajouter une application aux favoris", 12, Color.WHITE);
        labelStub.setGravity(Gravity.CENTER);
        labelStub.setSingleLine(true);
        labelStub.setEllipsize(TextUtils.TruncateAt.MARQUEE);
        labelStub.setHorizontallyScrolling(true);
        labelStub.setMarqueeRepeatLimit(-1);
        labelStub.setSelected(false);
        card.addView(labelStub, new LinearLayout.LayoutParams(-1, dp(26)));

        card.setOnFocusChangeListener((v, focused) -> {
            if (!headerMenuStyle) iconStage.setBackground(focused ? settingsCardBg(true) : settingsCardBg(false));
            labelStub.setSelected(focused);
            float focusScale = headerMenuStyle ? headerAppsMenuFocusScale() : appFocusScaleX();
            if (headerMenuStyle) card.animate().cancel();
            android.view.ViewPropertyAnimator animator = card.animate();
            if (headerMenuStyle) animator.withLayer();
            animator.scaleX(focused ? focusScale : 1f).scaleY(focused ? focusScale : 1f).setDuration(120).start();
            if (focusBorder != null) focusBorder.animate().alpha(focused ? 1f : 0f).setDuration(100).start();
            if (focused) revealAppTile(v);
        });
        card.setOnClickListener(v -> openAndroidTvAddAppLink(card));
        card.setOnKeyListener((v, keyCode, event) -> {
            if (headerMenuStyle && popup != null
                    && handleHeaderPopupHorizontalExit(headerAnchor, popup, pendingHeaderFocus,
                    keyCode, event)) return true;
            if (!headerMenuStyle && event.getAction() == KeyEvent.ACTION_DOWN
                    && keyCode == KeyEvent.KEYCODE_DPAD_UP) {
                View target = homeAppUpTarget(v);
                if (target != null && target != v) {
                    target.post(target::requestFocus);
                    return true;
                }
            }
            if (!headerMenuStyle && event.getAction() == KeyEvent.ACTION_DOWN
                    && keyCode == KeyEvent.KEYCODE_DPAD_DOWN) {
                if (activeScreen == null) {
                    View target = firstFocusableChild((ViewGroup) currentHomeResumesView);
                    if (target != null && target != v) {
                        target.post(target::requestFocus);
                        return true;
                    }
                }
            }
            return false;
        });
        card.setContentDescription("Ajouter une application");
        return card;
    }

    /**
     * Never leave the horizontal direction to Android's geometric focus search:
     * scaled cards inside a scrolling row can otherwise lose Left/Right focus in
     * the middle of the application rail on Fire TV.
     */
    private void wireAppRowDpad(ViewGroup row) {
        wireAppRowDpad(row, View.NO_ID);
    }
    private void wireAppRowDpad(ViewGroup row, int leftShortcutId) {
        if (row == null || row.getChildCount() == 0) return;
        for (int index = 0; index < row.getChildCount(); index++) {
            View tile = row.getChildAt(index);
            if (tile.getId() == View.NO_ID) tile.setId(View.generateViewId());
        }
        if (row instanceof GridLayout) {
            GridLayout grid = (GridLayout) row;
            int columns = Math.max(1, grid.getColumnCount());
            int total = grid.getChildCount();
            int rowCount = grid.getRowCount();
            if (rowCount <= 0) rowCount = (total + columns - 1) / columns;
            for (int index = 0; index < total; index++) {
                View tile = grid.getChildAt(index);
                int rowIndex = index / columns;
                int colIndex = index % columns;
                View left = grid.getChildAt(colIndex > 0 ? index - 1 : index);
                View right = grid.getChildAt(index + 1 < total ? index + 1 : index);
                View up = index - columns >= 0 ? grid.getChildAt(index - columns) : tile;
                if (up == tile && rowIndex > 0) {
                    int aboveRowStart = (rowIndex - 1) * columns;
                    int aboveRowCount = Math.min(columns, total - aboveRowStart);
                    up = grid.getChildAt(aboveRowStart + Math.min(colIndex, aboveRowCount - 1));
                }
                View down = index + columns < total ? grid.getChildAt(index + columns) : tile;
                if (down == tile && rowIndex < rowCount - 1) {
                    int belowRowStart = (rowIndex + 1) * columns;
                    int belowRowCount = Math.min(columns, total - belowRowStart);
                    if (belowRowCount > 0) down = grid.getChildAt(belowRowStart + Math.min(colIndex, belowRowCount - 1));
                }
                if (left.getId() == View.NO_ID) left.setId(View.generateViewId());
                if (right.getId() == View.NO_ID) right.setId(View.generateViewId());
                if (colIndex == 0 && leftShortcutId != View.NO_ID) {
                    tile.setNextFocusLeftId(leftShortcutId);
                } else {
                    tile.setNextFocusLeftId(left.getId());
                }
                tile.setNextFocusRightId(right.getId());
                if (rowCount > 1) {
                    if (up.getId() == View.NO_ID) up.setId(View.generateViewId());
                    if (down.getId() == View.NO_ID) down.setId(View.generateViewId());
                    tile.setNextFocusUpId(up.getId());
                    tile.setNextFocusDownId(down.getId());
                } else {
                    tile.setNextFocusUpId(View.NO_ID);
                    tile.setNextFocusDownId(View.NO_ID);
                }
            }
            return;
        }
        for (int index = 0; index < row.getChildCount(); index++) {
            View tile = row.getChildAt(index);
            View left = row.getChildAt(Math.max(0, index - 1));
            View right = row.getChildAt(Math.min(row.getChildCount() - 1, index + 1));
            tile.setNextFocusLeftId(left.getId());
            tile.setNextFocusRightId(right.getId());
        }
    }
    private void revealAppTile(View card) {
        if (isHomeDescendant(card, restoringNavigationPage)) return;
        View parent = (View) card.getParent();
        while (parent != null && !(parent instanceof HorizontalScrollView)) parent = parent.getParent() instanceof View ? (View) parent.getParent() : null;
        if (!(parent instanceof HorizontalScrollView)) return;
        HorizontalScrollView scroll = (HorizontalScrollView) parent;
        Runnable previous = pendingRailReveals.remove(scroll);
        if (previous != null) scroll.removeCallbacks(previous);
        long now = android.os.SystemClock.uptimeMillis();
        Long previousFocusAt = lastRailFocusAt.put(scroll, now);
        boolean rapidNavigation = previousFocusAt != null && now - previousFocusAt < 250L;
        Runnable reveal = () -> {
            pendingRailReveals.remove(scroll);
            int left = card.getLeft(), right = card.getRight();
            int target = scroll.getScrollX();
            if (left < target + dp(18)) target = left - dp(18);
            if (right > scroll.getScrollX() + scroll.getWidth() - dp(38)) target = right - scroll.getWidth() + dp(38);
            target = Math.max(0, target);
            if (target == scroll.getScrollX()) return;
            // A single move keeps the pleasant short animation.  Holding a
            // direction jumps to the newest focus immediately, preventing a
            // queue of stale smoothScrollTo animations.
            if (rapidNavigation) scroll.scrollTo(target, 0);
            else scroll.smoothScrollTo(target, 0);
        };
        pendingRailReveals.put(scroll, reveal);
        scroll.post(reveal);
    }
    private void storePageFocus(View page) {
        if (page == null) return;
        View focused = page.findFocus();
        page.setTag(BROWSER_FOCUS_TAG, (focused != null && focused.isFocusable()) ? focused : null);
        ArrayList<PageScrollPosition> positions = new ArrayList<>();
        collectPageScrollPositions(page, positions);
        page.setTag(BROWSER_SCROLL_TAG, positions);
    }
    private View restoringNavigationPage;
    private static final class PageScrollPosition {
        final View view;
        final int x, y;
        final boolean smoothScrolling;
        PageScrollPosition(View view) {
            this.view = view;
            x = view.getScrollX();
            y = view.getScrollY();
            smoothScrolling = view instanceof HorizontalScrollView
                    ? ((HorizontalScrollView) view).isSmoothScrollingEnabled()
                    : ((ScrollView) view).isSmoothScrollingEnabled();
        }
        void setSmoothScrolling(boolean enabled) {
            if (view instanceof HorizontalScrollView) ((HorizontalScrollView) view).setSmoothScrollingEnabled(enabled);
            else ((ScrollView) view).setSmoothScrollingEnabled(enabled);
        }
    }
    private void collectPageScrollPositions(View view, ArrayList<PageScrollPosition> positions) {
        if (view instanceof ScrollView || view instanceof HorizontalScrollView) {
            if (view instanceof HorizontalScrollView) {
                HorizontalScrollView rail = (HorizontalScrollView) view;
                Runnable reveal = pendingRailReveals.remove(rail);
                if (reveal != null) rail.removeCallbacks(reveal);
                android.animation.ValueAnimator animation = continueWatchingScrollAnimations.remove(rail);
                if (animation != null) animation.cancel();
            }
            positions.add(new PageScrollPosition(view));
        }
        if (view instanceof ViewGroup) {
            ViewGroup group = (ViewGroup) view;
            for (int index = 0; index < group.getChildCount(); index++) collectPageScrollPositions(group.getChildAt(index), positions);
        }
    }
    @SuppressWarnings("unchecked")
    private List<PageScrollPosition> savedPageScrollPositions(View page) {
        Object saved = page == null ? null : page.getTag(BROWSER_SCROLL_TAG);
        return saved instanceof List ? (List<PageScrollPosition>) saved : Collections.emptyList();
    }
    private void finishPageNavigationRestore() {
        if (restoringNavigationPage == null) return;
        for (PageScrollPosition position : savedPageScrollPositions(restoringNavigationPage)) position.setSmoothScrolling(position.smoothScrolling);
        restoringNavigationPage = null;
    }
    private View savedPageFocus(View page) {
        Object saved = page.getTag(BROWSER_FOCUS_TAG);
        if (!(saved instanceof View)) return null;
        View focus = (View) saved;
        if (!isHomeDescendant(focus, page) && focus.getTag() instanceof String) {
            focus = page.findViewWithTag(focus.getTag());
        }
        return focus != null && isHomeDescendant(focus, page) && focus.isFocusable() && focus.isShown() ? focus : null;
    }

    private void rememberHomeFocus() {
        if (activeScreen != null || currentHomeShell == null
                || !currentHomeShell.isAttachedToWindow()) return;
        View focused = currentHomeShell.findFocus();
        if (isValidHomeFocus(focused) && !isSearchHeader(focused)) {
            lastHomeFocus = focused;
            Object tag = focused.getTag();
            lastHomeFocusKey = tag instanceof String ? (String) tag : null;
            // The modern Continue Watching Hero owns the stable resume key;
            // recover it from the nearest focused ancestor when Android gives
            // focus to one of its internal children.
            if (lastHomeFocusKey == null && isHomeDescendant(focused, currentHomeResumesView)) {
                View ancestor = focused;
                while (ancestor != null && ancestor != currentHomeResumesView) {
                    Object ancestorTag = ancestor.getTag();
                    if (ancestorTag instanceof String && !((String) ancestorTag).isEmpty()) {
                        lastHomeFocusKey = (String) ancestorTag;
                        break;
                    }
                    ancestor = ancestor.getParent() instanceof View
                            ? (View) ancestor.getParent() : null;
                }
            }
            currentHomeShell.setTag(BROWSER_FOCUS_TAG, focused);
        }
    }

    private View resolveHomeFocusTarget() {
        View candidate = lastHomeFocus;
        if (isValidHomeFocus(candidate) && !isSearchHeader(candidate) && candidate.isAttachedToWindow() && candidate.isShown()) return candidate;
        if (currentHomeShell != null && lastHomeFocusKey != null) {
            candidate = currentHomeShell.findViewWithTag(lastHomeFocusKey);
            if (isValidHomeFocus(candidate) && !isSearchHeader(candidate) && candidate.isShown()) return candidate;
        }
        if (currentHomeShell != null) {
            Object saved = currentHomeShell.getTag(BROWSER_FOCUS_TAG);
            if (saved instanceof View) {
                candidate = (View) saved;
                if (isValidHomeFocus(candidate) && !isSearchHeader(candidate) && candidate.isAttachedToWindow() && candidate.isShown()) return candidate;
            }
        }
        View fallback = currentHomeAppsView != null && currentHomeAppsView.isShown() ? firstHomeFocusableChild(currentHomeAppsView) : null;
        if (fallback == null && currentHomeResumesView instanceof ViewGroup && currentHomeResumesView.isShown()) fallback = firstHomeFocusableChild((ViewGroup) currentHomeResumesView);
        if (fallback == null) {
            for (View item : renderedHeaderItems) {
                if (item.isShown() && isValidHomeFocus(item) && !isSearchHeader(item)) { fallback = item; break; }
            }
        }
        return fallback;
    }

    private void restoreHomeFocusIfNeeded() {
        if (activeScreen != null || currentHomeShell == null
                || !currentHomeShell.isAttachedToWindow()) return;
        if (activePopup != null && activePopup.isShowing()) return;
        View current = currentHomeShell.findFocus();
        // Search is now an ordinary header command. Keep its focus when the
        // Apps popup closes after a right D-pad move.
        if (current != null && isValidHomeFocus(current)
                && current.isAttachedToWindow() && current.isShown()) return;
        if (current == null) closeSearchOverlayForHomeFocus();
        View candidate = resolveHomeFocusTarget();
        if (!isValidHomeFocus(candidate) || !candidate.isAttachedToWindow()) return;
        View target = candidate;
        FrameLayout expectedShell = currentHomeShell;
        long expectedGeneration = homeRenderGeneration;
        long expectedFocusGeneration = homeFocusGeneration;
        if (requestHomeFocus(target, "home-return-restore")) return;
        target.postOnAnimation(() -> {
            if (expectedFocusGeneration != homeFocusGeneration || expectedGeneration != homeRenderGeneration || expectedShell != currentHomeShell) return;
            if (activeScreen == null && expectedShell.isAttachedToWindow()
                    && (expectedShell.findFocus() == null
                    || !isValidHomeFocus(expectedShell.findFocus()))) {
                requestHomeFocus(target, "home-return-restore");
            }
        });
    }

    private HorizontalScrollView continueRow() {
        HorizontalScrollView scroll = new HorizontalScrollView(this); scroll.setHorizontalScrollBarEnabled(false);
        LinearLayout row = new LinearLayout(this);
        TextView loading = text("Chargement des reprises JojoTV…", 16, muted); loading.setGravity(Gravity.CENTER_VERTICAL); row.addView(loading, new LinearLayout.LayoutParams(dp(300), dp(180)));
        new Thread(() -> {
            List<JojoProgram> programs = findJojoPrograms();
            runOnUiThread(() -> {
                row.removeAllViews();
                if (programs.isEmpty()) {
                    TextView empty = text("Aucune reprise JojoTV. Ouvrez JojoTV, lancez une vidéo puis revenez à l’accueil.", 16, muted);
                    empty.setGravity(Gravity.CENTER_VERTICAL); empty.setFocusable(true); empty.setOnClickListener(v -> openJojoTv()); row.addView(empty, new LinearLayout.LayoutParams(dp(430), dp(180)));
                } else for (JojoProgram program : programs) row.addView(jojoProgramTile(program), new LinearLayout.LayoutParams(dp(160), dp(220)) {{ rightMargin = dp(18); }});
            });
        }).start();
        scroll.addView(row); return scroll;
    }
    private View freeboxVideosSection() {
        final long refreshGeneration = ++freeboxHomeRefreshGeneration;
        LinearLayout section = new LinearLayout(this);
        section.setOrientation(LinearLayout.VERTICAL);
        LinearLayout rows = new LinearLayout(this);
        rows.setOrientation(LinearLayout.VERTICAL);
        rows.setClipChildren(false);
        rows.setClipToPadding(false);
        List<JojoProgram> cachedVideos = cachedFreeboxHomeVideos();
        // Do not reserve a visible Home row while the asynchronous Freebox
        // lookup is empty. The section becomes visible as soon as one video
        // is available.
        section.setVisibility(cachedVideos.isEmpty() ? View.GONE : View.VISIBLE);
        if (cachedVideos.isEmpty()) rows.addView(text("Chargement des vidéos Freebox…", 16, muted), new LinearLayout.LayoutParams(dp(300), dp(180)));
        else renderFreeboxVideoTiles(rows, cachedVideos);
        addHomeSectionTitle(section, "videos", "Vidéos", HOME_TITLE_TO_CARD_GAP_DP);
        section.addView(rows, new LinearLayout.LayoutParams(-1, dp(freeboxVideosCardHeightDp() * homeSectionRows("videos") + 12)));
        // Keep the existing Hero snapshot so a newly discovered remote resume
        // can be compared after the SMB refresh, without rebuilding the Hero
        // on every periodic Videos poll.
        final Set<String> previousHomeResumeKeys = new HashSet<>();
        for (JojoProgram program : cachedContinueWatchingHomePrograms()) {
            if (program != null && FILE_VIDEO_RESUME_SOURCE.equals(program.sourcePackage)) {
                previousHomeResumeKeys.add(resumeDismissKey(program));
            }
        }
        new Thread(() -> {
            List<JojoProgram> videos = findFreeboxHomeVideos();
            // Restore the dedicated SMB secret before giving up on a fresh Firestick.
            if (videos.isEmpty() && nasDataSyncEnabled() && !homePrefs().getString("nas_token", "").isEmpty()) {
                restoreHomeSmbSecretFromNas();
                videos = findFreeboxHomeVideos();
            }
            final List<JojoProgram> resolvedVideos = videos;
            runOnUiThread(() -> {
                if (refreshGeneration != freeboxHomeRefreshGeneration
                        || !section.isAttachedToWindow()
                        || currentHomeSectionViews.get("videos") != section) return;
                String focusedVideoKey = focusedTag(rows);
                if (resolvedVideos.isEmpty()) {
                    rows.removeAllViews();
                    section.setVisibility(View.GONE);
                    setHomeSectionVisible("videos", false);
                    if (currentHomeHeaderView != null && currentHomeAppsView != null)
                        wireHomeHeaderDpad(currentHomeHeaderView, currentHomeAppsView, currentHomeFilesView, currentHomeResumesView);
                    wireHomeSectionVerticalDpad();
                    return;
                }
                cacheFreeboxHomeVideos(resolvedVideos);
                boolean newHomeResume = false;
                for (JojoProgram program : cachedContinueWatchingHomePrograms()) {
                    if (program != null && FILE_VIDEO_RESUME_SOURCE.equals(program.sourcePackage)
                            && SystemContinueWatching.hasProgress(program.duration, program.position)
                            && !previousHomeResumeKeys.contains(resumeDismissKey(program))) {
                        newHomeResume = true;
                        break;
                    }
                }
                setHomeSectionVisible("videos", true);
                renderFreeboxVideoTiles(rows, resolvedVideos);
                restoreFocusByTag(rows, focusedVideoKey);
                if (currentHomeHeaderView != null && currentHomeAppsView != null)
                    wireHomeHeaderDpad(currentHomeHeaderView, currentHomeAppsView, currentHomeFilesView, currentHomeResumesView);
                wireHomeSectionVerticalDpad();
                // The cards have just been replaced.  Reapply the graph after
                // the HorizontalScrollView has attached the new row so a
                // later focus search cannot fall back to Continue Watching.
                rows.post(() -> {
                    wireHomeSectionVerticalDpad();
                });
                // The SMB/Videos source is also a Continue Watching source.
                // Refresh that rail only when this scan introduced a new
                // started file, so a routine poll cannot cause Hero flicker.
                if (newHomeResume) refreshHomeResumeSectionInPlace();
            });
        }, "JojoHomeFreeboxVideos").start();
        return section;
    }
    private void renderFreeboxVideoTiles(LinearLayout rows, List<JojoProgram> videos) {
        String focusedVideoKey = focusedTag(rows);
        rows.removeAllViews();
        List<JojoProgram> visibleVideos = visibleFreeboxHomeVideos(videos);
        int count = visibleVideos.size();
        int rowCount = Math.min(homeSectionRows("videos"), Math.max(1, count));
        int perRow = Math.max(1, (int) Math.ceil(count / (double) rowCount));
        for (int rowIndex = 0; rowIndex < rowCount; rowIndex++) {
            HorizontalScrollView scroll = new HorizontalScrollView(this);
            scroll.setHorizontalScrollBarEnabled(false);
            LinearLayout row = new LinearLayout(this);
            row.setClipChildren(false);
            row.setClipToPadding(false);
            int start = rowIndex * perRow;
            int end = Math.min(count, start + perRow);
            for (int index = start; index < end; index++) {
                View tile = jojoProgramTile(visibleVideos.get(index), true);
                if (rowIndex == 0 && index == 0) registerHomeRowMoveTrigger(tile, "videos");
                row.addView(tile, new LinearLayout.LayoutParams(dp(freeboxVideosTileWidthDp()), dp(freeboxVideosCardHeightDp())) {{ rightMargin = dp(18); }});
            }
            scroll.addView(row);
            rows.addView(scroll, new LinearLayout.LayoutParams(-1, dp(freeboxVideosCardHeightDp() + 4)));
            wireHorizontalCardRowDpad(row);
        }
        wireHomeSectionVerticalDpad();
        restoreFocusByTag(rows, focusedVideoKey);
    }

    /** Keeps Left/Right inside the Videos rail instead of using geometric focus search. */
    private void wireHorizontalCardRowDpad(ViewGroup row) {
        wireHorizontalCardRowDpad(row, false);
    }

    private void wireCyclicHorizontalCardRowDpad(ViewGroup row) {
        row.setTag("cyclic_horizontal_card_row");
        wireHorizontalCardRowDpad(row, true);
    }

    /**
     * Some Fire TV builds let the horizontal container consume LEFT at its
     * beginning before the focused card's listener or nextFocusLeftId runs.
     * Resolve cyclic folder rows at the activity boundary so both directions
     * use the same explicit target.
     */
    private boolean handleCyclicHorizontalRowDpad(KeyEvent event) {
        if (event == null || event.getAction() != KeyEvent.ACTION_DOWN || event.getRepeatCount() != 0
                || (event.getKeyCode() != KeyEvent.KEYCODE_DPAD_LEFT
                && event.getKeyCode() != KeyEvent.KEYCODE_DPAD_RIGHT)) return false;
        View focused = getCurrentFocus();
        View current = focused;
        while (current != null) {
            if (current instanceof ViewGroup
                    && "cyclic_horizontal_card_row".equals(current.getTag())) {
                ViewGroup row = (ViewGroup) current;
                View child = focused;
                while (child != null && child.getParent() != row) {
                    ViewParent parent = child.getParent();
                    child = parent instanceof View ? (View) parent : null;
                }
                int index = row.indexOfChild(child);
                if (index < 0) return false;
                int count = row.getChildCount();
                if (count < 2) return true;
                int targetIndex = event.getKeyCode() == KeyEvent.KEYCODE_DPAD_LEFT
                        ? (index + count - 1) % count
                        : (index + 1) % count;
                View target = row.getChildAt(targetIndex);
                if (target != null && target.isFocusable()) {
                    target.requestFocus();
                    return true;
                }
                return true;
            }
            ViewParent parent = current.getParent();
            current = parent instanceof View ? (View) parent : null;
        }
        return false;
    }

    private boolean handleTaggedCyclicCardDpad(View card, int keyCode, KeyEvent event) {
        if (card == null || event == null || event.getAction() != KeyEvent.ACTION_DOWN
                || event.getRepeatCount() != 0
                || (keyCode != KeyEvent.KEYCODE_DPAD_LEFT && keyCode != KeyEvent.KEYCODE_DPAD_RIGHT)) return false;
        View current = card;
        while (current != null && !(current.getParent() instanceof ViewGroup
                && "cyclic_horizontal_card_row".equals(((View) current.getParent()).getTag()))) {
            ViewParent parent = current.getParent();
            current = parent instanceof View ? (View) parent : null;
        }
        if (current == null || !(current.getParent() instanceof ViewGroup)) return false;
        ViewGroup row = (ViewGroup) current.getParent();
        int index = row.indexOfChild(current);
        if (index < 0 || row.getChildCount() < 2) return true;
        int count = row.getChildCount();
        int targetIndex = keyCode == KeyEvent.KEYCODE_DPAD_LEFT
                ? (index + count - 1) % count : (index + 1) % count;
        View target = row.getChildAt(targetIndex);
        if (target != null && target.isFocusable()) {
            target.post(target::requestFocus);
        }
        return true;
    }

    private void wireHorizontalCardRowDpad(ViewGroup row, boolean cyclic) {
        if (row == null || row.getChildCount() == 0) return;
        for (int index = 0; index < row.getChildCount(); index++) {
            View tile = row.getChildAt(index);
            if (tile == null || !tile.isFocusable()) continue;
            if (tile.getId() == View.NO_ID) tile.setId(View.generateViewId());
            int last = row.getChildCount() - 1;
            View left = row.getChildAt(cyclic ? (index + last) % (last + 1) : Math.max(0, index - 1));
            View right = row.getChildAt(cyclic ? (index + 1) % (last + 1) : Math.min(last, index + 1));
            if (left != null && left.isFocusable()) {
                if (left.getId() == View.NO_ID) left.setId(View.generateViewId());
                tile.setNextFocusLeftId(left.getId());
            }
            if (right != null && right.isFocusable()) {
                if (right.getId() == View.NO_ID) right.setId(View.generateViewId());
                tile.setNextFocusRightId(right.getId());
            }
            if ("thumbnails".equals(row.getTag(FOLDER_MEDIA_ROW_TAG))) {
                tile.setNextFocusUpId(tile.getId());
                tile.setNextFocusDownId(tile.getId());
            }
        }
    }

    /**
     * Continue Watching has a small, interruptible carousel. Focus controls
     * manual D-pad navigation. The Home Hero pauses while it owns focus and
     * keeps rotating while another Home rail is focused.
     */
    private void wireContinueWatchingAutoScroll(View card) {
        HorizontalScrollView scroll = continueWatchingScroll(card);
        if (scroll == null) return;
        ViewGroup row = scroll.getChildCount() == 0 || !(scroll.getChildAt(0) instanceof ViewGroup)
                ? null : (ViewGroup) scroll.getChildAt(0);
        if (row == null || row.getChildCount() == 0) return;
        if (row.getChildCount() < 2) {
            // A single Hero must remain completely static: no delayed
            // transition and no stale carousel callback from a previous bind.
            cancelContinueWatchingAutoScroll(scroll, true);
            continueWatchingCarouselAdvancers.remove(scroll);
            return;
        }
        for (int index = 0; index < row.getChildCount(); index++) {
            View tile = row.getChildAt(index);
            if (tile != null && tile.getId() == View.NO_ID) tile.setId(View.generateViewId());
        }
        scheduleContinueWatchingAutoScroll(scroll, 5000L);
    }

    private HorizontalScrollView continueWatchingScroll(View view) {
        View current = view;
        while (current != null) {
            if (current instanceof HorizontalScrollView) {
                HorizontalScrollView scroll = (HorizontalScrollView) current;
                View child = scroll.getChildCount() == 0 ? null : scroll.getChildAt(0);
                return child != null && "continue_watching_row".equals(child.getTag()) ? scroll : null;
            }
            ViewParent parent = current.getParent();
            current = parent instanceof View ? (View) parent : null;
        }
        return null;
    }

    private void continueWatchingTileFocusChanged(View tile, boolean focused) {
        HorizontalScrollView scroll = continueWatchingScroll(tile);
        if (scroll == null) return;
        if (focused) scheduleContinueWatchingAutoScroll(scroll, 5000L);
        else cancelContinueWatchingAutoScroll(scroll, false);
    }

    private boolean handleContinueWatchingDpad(View tile, int keyCode, KeyEvent event) {
        if (event.getAction() != KeyEvent.ACTION_DOWN || event.getRepeatCount() != 0
                || (keyCode != KeyEvent.KEYCODE_DPAD_LEFT && keyCode != KeyEvent.KEYCODE_DPAD_RIGHT)) return false;
        HorizontalScrollView scroll = continueWatchingScroll(tile);
        if (scroll == null || !(scroll.getChildAt(0) instanceof ViewGroup)) return false;
        ViewGroup row = (ViewGroup) scroll.getChildAt(0);
        int index = row.indexOfChild(tile);
        if (index < 0) return false;
        cancelContinueWatchingAutoScroll(scroll, true);
        int count = row.getChildCount();
        int targetIndex = keyCode == KeyEvent.KEYCODE_DPAD_LEFT
                ? (index - 1 + count) % count
                : (index + 1) % count;
        View target = row.getChildAt(targetIndex);
        if (target == null || !target.isFocusable()) return true;
        target.requestFocus();
        revealContinueWatchingCard(scroll, target, 250L);
        scheduleContinueWatchingAutoScroll(scroll, 6000L);
        return true;
    }

    private void scheduleContinueWatchingAutoScroll(HorizontalScrollView scroll, long delayMs) {
        if (scroll == null) return;
        Runnable previous = continueWatchingAutoScrolls.remove(scroll);
        if (previous != null) scroll.removeCallbacks(previous);
        if (continueWatchingCarouselAdvancers.containsKey(scroll) && scroll.hasFocus()) return;
        Runnable next = () -> autoAdvanceContinueWatching(scroll);
        continueWatchingAutoScrolls.put(scroll, next);
        scroll.postDelayed(next, delayMs);
    }

    private void cancelContinueWatchingAutoScroll(HorizontalScrollView scroll, boolean cancelAnimation) {
        if (scroll == null) return;
        Runnable pending = continueWatchingAutoScrolls.remove(scroll);
        if (pending != null) scroll.removeCallbacks(pending);
        if (cancelAnimation) {
            android.animation.ValueAnimator animation = continueWatchingScrollAnimations.remove(scroll);
            if (animation != null) animation.cancel();
        }
    }

    private void autoAdvanceContinueWatching(HorizontalScrollView scroll) {
        continueWatchingAutoScrolls.remove(scroll);
        if (!homeActivityResumed || !scroll.isAttachedToWindow()) return;
        if (activePopup != null && activePopup.isShowing()) {
            scheduleContinueWatchingAutoScroll(scroll, continueWatchingCarouselAdvancers.containsKey(scroll)
                    ? HOME_HERO_AUTO_ADVANCE_MS : 5000L);
            return;
        }
        Runnable carouselAdvancer = continueWatchingCarouselAdvancers.get(scroll);
        if (carouselAdvancer != null) {
            if (!scroll.isAttachedToWindow() || scroll.hasFocus()) return;
            // The Hero is rebuilt without taking focus when another Home rail
            // is selected. The focused control therefore remains untouched
            // while the visual carousel advances in the background.
            carouselAdvancer.run();
            scheduleContinueWatchingAutoScroll(scroll, HOME_HERO_AUTO_ADVANCE_MS);
            return;
        }
        if (!scroll.isAttachedToWindow() || !(scroll.getChildAt(0) instanceof ViewGroup)) return;
        ViewGroup row = (ViewGroup) scroll.getChildAt(0);
        View focused = row.findFocus();
        if (focused == null || !focused.isFocusable() || row.getChildCount() < 2) {
            scheduleContinueWatchingAutoScroll(scroll, 5000L);
            return;
        }
        int index = row.indexOfChild(focused);
        if (index < 0) return;
        View target = row.getChildAt((index + 1) % row.getChildCount());
        if (target == null || !target.isFocusable()) return;
        target.requestFocus();
        revealContinueWatchingCard(scroll, target, 500L);
        scheduleContinueWatchingAutoScroll(scroll, 5000L);
    }

    private void revealContinueWatchingCard(HorizontalScrollView scroll, View target, long durationMs) {
        if (scroll == null || target == null) return;
        if (isHomeDescendant(target, restoringNavigationPage)) return;
        int left = target.getLeft();
        int right = target.getRight();
        int viewportLeft = scroll.getScrollX();
        int viewportRight = viewportLeft + scroll.getWidth();
        int targetScroll = viewportLeft;
        if (left < viewportLeft) targetScroll = left;
        else if (right > viewportRight) targetScroll = right - scroll.getWidth();
        int maxScroll = Math.max(0, scroll.getChildAt(0).getWidth() - scroll.getWidth());
        targetScroll = Math.max(0, Math.min(maxScroll, targetScroll));
        android.animation.ValueAnimator previous = continueWatchingScrollAnimations.remove(scroll);
        if (previous != null) previous.cancel();
        if (targetScroll == scroll.getScrollX()) return;
        android.animation.ValueAnimator animation = android.animation.ValueAnimator.ofInt(scroll.getScrollX(), targetScroll);
        animation.setDuration(durationMs);
        animation.addUpdateListener(value -> scroll.scrollTo((Integer) value.getAnimatedValue(), 0));
        animation.addListener(new android.animation.AnimatorListenerAdapter() {
            @Override public void onAnimationEnd(android.animation.Animator animator) {
                if (continueWatchingScrollAnimations.get(scroll) == animator) continueWatchingScrollAnimations.remove(scroll);
            }
            @Override public void onAnimationCancel(android.animation.Animator animator) {
                if (continueWatchingScrollAnimations.get(scroll) == animator) continueWatchingScrollAnimations.remove(scroll);
            }
        });
        continueWatchingScrollAnimations.put(scroll, animation);
        animation.start();
    }
    private List<JojoProgram> visibleFreeboxHomeVideos(List<JojoProgram> videos) {
        ArrayList<JojoProgram> visible = new ArrayList<>();
        Set<String> startedPaths = new HashSet<>();
        // Use both stores that feed Continue Watching. The durable progress
        // list may outlive a dismissed/stale card, while the Home cache knows
        // what was actually published on the current device.
        for (JojoProgram resume : findFileVideoResumePrograms()) {
            if (resume != null && !isResumeDismissed(resume) && resume.intentUri != null) {
                startedPaths.add(comparableSmbPath(resume.intentUri));
            }
        }
        for (JojoProgram resume : cachedContinueWatchingHomePrograms()) {
            if (resume != null && FILE_VIDEO_RESUME_SOURCE.equals(resume.sourcePackage)
                    && !isResumeDismissed(resume) && resume.intentUri != null
                    && resume.position >= 1000L) {
                startedPaths.add(comparableSmbPath(resume.intentUri));
            }
        }
        for (JojoProgram video : videos) {
            if (isHomeVideoHidden(video.intentUri)) continue;
            if (FREEBOX_FOLDER_SOURCE.equals(video.sourcePackage)
                    || !startedPaths.contains(comparableSmbPath(video.intentUri))) {
                visible.add(video);
            }
        }
        return visible;
    }
    private boolean isDirectFreeboxVideosChild(String path) {
        if (path == null || !path.startsWith("smb://")) return false;
        String trimmed = path.replaceAll("/+$", "");
        int separator = trimmed.lastIndexOf('/');
        return separator > "smb://".length()
                && isVideosFolderPath(trimmed.substring(0, separator));
    }
    private List<JojoProgram> cachedFreeboxHomeVideos() {
        ArrayList<JojoProgram> result = new ArrayList<>();
        try {
            JSONArray cached = new JSONArray(homePrefs().getString(FREEBOX_HOME_VIDEOS_CACHE, "[]"));
            for (int index = 0; index < cached.length(); index++) {
                JSONObject item = cached.optJSONObject(index);
                if (item == null) continue;
                String path = item.optString("path", "");
                String title = item.optString("title", "");
                if (isDirectFreeboxVideosChild(path) && !title.isEmpty() && !isHomeVideoHidden(path)) {
                    String source = item.optString("source", FILE_VIDEO_RESUME_SOURCE);
                    boolean cloud = HomeWatchProgressBridge.isCloud(this);
                    WatchProgress progress = cloud ? cloudSnapshotProgress(path) : null;
                    long duration = progress != null && progress.getDuration() > 0L
                            ? progress.getDuration() : item.optLong("duration", -1L);
                    long position = cloud ? (progress == null ? 0L : progress.getPosition())
                            : homePrefs().getLong("video_resume_" + path, item.optLong("position", 0L));
                    boolean completed = progress != null && progress.isCompleted(
                            WatchProgress.completionThreshold(progress.getContentType(), progress.getEpisode()));
                    result.add(new JojoProgram(source, title, "", "", path, duration, position, "", "", completed));
                }
            }
        } catch (Exception ignored) { }
        sortFreeboxHomeVideos(result);
        return result;
    }
    private boolean isHomeVideoHidden(String path) {
        return HomeMediaRules.hiddenHomeVideo(path, homePrefs().getStringSet(
                JOJOTV_HOME_HIDDEN_RESUME_KEYS, Collections.emptySet()));
    }
    private void restoreHiddenHomeVideo(String selectedKey) {
        Set<String> hidden = new HashSet<>(homePrefs().getStringSet(
                JOJOTV_HOME_HIDDEN_RESUME_KEYS, Collections.emptySet()));
        Set<String> restored = HomeMediaRules.homeVideoListRestorationKeys(selectedKey, hidden);
        if (restored.isEmpty()) return;
        long restoredAt = System.currentTimeMillis();
        // The hidden list is shared: a removal made by another profile or device
        // must not hide this video again when an older NAS snapshot is merged.
        for (Map.Entry<String, ?> entry : homePrefs().getAll().entrySet()) {
            String key = entry.getKey();
            String prefix = key.startsWith(HomeWatchProgressBridge.REMOVAL_PREFIX)
                    ? HomeWatchProgressBridge.REMOVAL_PREFIX
                    : key.startsWith(HomeWatchProgressBridge.RESTORATION_PREFIX)
                    ? HomeWatchProgressBridge.RESTORATION_PREFIX : "";
            if (prefix.isEmpty() || !(entry.getValue() instanceof Number)) continue;
            int separator = key.indexOf('_', prefix.length());
            if (separator >= 0 && restored.contains(key.substring(separator + 1))) {
                restoredAt = Math.max(restoredAt, ((Number) entry.getValue()).longValue() + 1L);
            }
        }
        hidden.removeAll(restored);
        int profileId = HomeWatchProgressBridge.currentProfileId(this);
        android.content.SharedPreferences.Editor editor = homePrefs().edit()
                .putStringSet(JOJOTV_HOME_HIDDEN_RESUME_KEYS, hidden)
                .remove(CONTINUE_WATCHING_HOME_CACHE).putBoolean("nas_home_pending", true);
        for (String key : restored) {
            editor.putLong(HomeWatchProgressBridge.RESTORATION_PREFIX + profileId + "_" + key, restoredAt);
            pendingResumeDismissals.remove(key);
        }
        editor.apply();
        for (String key : restored) recordHomeSettingChange(
                HomeWatchProgressBridge.RESTORATION_PREFIX + profileId + "_" + key);
        recordHomeSettingChange(JOJOTV_HOME_HIDDEN_RESUME_KEYS);
        String path = HomeMediaRules.homeVideoListPath(selectedKey);
        String name = Uri.decode(path.replaceAll("/+$", ""));
        name = name.substring(name.lastIndexOf('/') + 1);
        if (isDirectFreeboxVideosChild(path)) restoreFreeboxVideoInHomeCache(new JojoProgram(
                path.endsWith("/") ? FREEBOX_FOLDER_SOURCE : FILE_VIDEO_RESUME_SOURCE,
                name, "", "", path, -1L, 0L));
        freeboxFolderSnapshots.clear();
        homeVisualSettingsDirty = true;
        refreshHomeVideosSectionInPlace(true);
        Toast.makeText(this, "Vidéo réaffichée dans Vidéos", Toast.LENGTH_SHORT).show();
    }
    private void removeVideoFromHomeLists(JojoProgram program, View card) {
        if (program == null || program.intentUri == null || program.intentUri.isEmpty()) return;
        String listKey = HomeMediaRules.homeVideoListDismissalKey(program.intentUri);
        Set<String> hidden = new HashSet<>(homePrefs().getStringSet(
                JOJOTV_HOME_HIDDEN_RESUME_KEYS, Collections.emptySet()));
        hidden.add(listKey);
        String removedKey = HomeWatchProgressBridge.REMOVAL_PREFIX
                + (watchProgressSnapshotProfileId > 0 ? watchProgressSnapshotProfileId : 1) + "_" + listKey;
        String restoredKey = HomeWatchProgressBridge.RESTORATION_PREFIX
                + (watchProgressSnapshotProfileId > 0 ? watchProgressSnapshotProfileId : 1) + "_" + listKey;
        long removedAt = Math.max(System.currentTimeMillis(), homePrefs().getLong(restoredKey, 0L) + 1L);
        homePrefs().edit().putStringSet(JOJOTV_HOME_HIDDEN_RESUME_KEYS, hidden)
                .putLong(removedKey, removedAt)
                .remove(CONTINUE_WATCHING_HOME_CACHE).putBoolean("nas_home_pending", true).apply();
        recordHomeSettingChange(removedKey);
        recordHomeSettingChange(JOJOTV_HOME_HIDDEN_RESUME_KEYS);
        dismissResumeLocally(program);
        if (FILE_VIDEO_RESUME_SOURCE.equals(program.sourcePackage)) clearVideoResume(program.intentUri);
        removeFreeboxHomeVideoFromCache(program.intentUri);
        cacheContinueWatchingHomePrograms(cachedContinueWatchingHomePrograms());
        removeDeletedFreeboxHomeCards(program);
        removeResumeCards(program, card);
        String folderUrl = activeScreen == null ? null : freeboxFolderPageUrls.get(activeScreen);
        if (!TextUtils.isEmpty(folderUrl)) {
            SmbConnectionConfig connection = smbConnectionForPath(folderUrl);
            replaceScreen(createFreeboxFolderMediaPage(folderUrl, connection.user, connection.password));
        }
        refreshHomeResumeSectionInPlace();
        refreshHomeVideosSectionInPlace();
        Toast.makeText(this, "Vidéo retirée de Vidéos et de l’accueil", Toast.LENGTH_SHORT).show();
    }
    private void cacheFreeboxHomeVideos(List<JojoProgram> videos) {
        try {
            boolean cloud = HomeWatchProgressBridge.isCloud(this);
            JSONArray cached = new JSONArray();
            for (JojoProgram video : videos) {
                JSONObject item = new JSONObject().put("source", video.sourcePackage).put("path", video.intentUri)
                        .put("title", video.title).put("duration", video.duration);
                // Discovery is local in every mode; cloud playback positions remain in the progress bridge.
                if (!cloud) item.put("position", video.position);
                cached.put(item);
            }
            synchronized (homeCategoryVideosLoadLock) {
                homePrefs().edit().putString(FREEBOX_HOME_VIDEOS_CACHE, cached.toString()).apply();
            }
            runOnUiThread(this::refreshEmptyHomeSuggestions);
        } catch (Exception ignored) { }
    }
    private void cacheFreeboxHomeVideoDurations(List<JojoProgram> videos) {
        Map<String, Long> durations = new HashMap<>();
        for (JojoProgram video : videos) if (video.duration > 0L)
            durations.put(comparableSmbPath(video.intentUri), video.duration);
        if (durations.isEmpty()) return;
        try {
            boolean changed = false;
            synchronized (homeCategoryVideosLoadLock) {
                JSONArray cached = new JSONArray(homePrefs().getString(FREEBOX_HOME_VIDEOS_CACHE, "[]"));
                // Metadata from an older visible page must not replace the latest folder inventory.
                for (int index = 0; index < cached.length(); index++) {
                    JSONObject item = cached.optJSONObject(index);
                    if (item == null) continue;
                    Long duration = durations.get(comparableSmbPath(item.optString("path", "")));
                    if (duration == null || item.optLong("duration", -1L) == duration) continue;
                    item.put("duration", duration);
                    changed = true;
                }
                if (changed) homePrefs().edit().putString(FREEBOX_HOME_VIDEOS_CACHE, cached.toString()).apply();
            }
            if (changed) runOnUiThread(this::refreshEmptyHomeSuggestions);
        } catch (Exception ignored) { }
    }
    private void restoreFreeboxVideoInHomeCache(JojoProgram program) {
        if (program == null || program.intentUri == null || program.intentUri.isEmpty()) return;
        try {
            boolean cloud = HomeWatchProgressBridge.isCloud(this);
            synchronized (homeCategoryVideosLoadLock) {
                JSONArray stored = new JSONArray(homePrefs().getString(FREEBOX_HOME_VIDEOS_CACHE, "[]"));
                JSONArray updated = new JSONArray();
                boolean found = false;
                for (int index = 0; index < stored.length(); index++) {
                    JSONObject item = stored.optJSONObject(index);
                    if (item == null) continue;
                    if (program.intentUri.equals(item.optString("path", ""))) {
                        item.put("source", program.sourcePackage)
                                .put("title", program.title)
                                .put("duration", program.duration);
                        if (!cloud) item.put("position", 0L);
                        else item.remove("position");
                        found = true;
                    }
                    updated.put(item);
                }
                if (!found) {
                    JSONObject item = new JSONObject()
                            .put("source", program.sourcePackage)
                            .put("path", program.intentUri)
                            .put("title", program.title)
                            .put("duration", program.duration);
                    if (!cloud) item.put("position", 0L);
                    updated.put(item);
                }
                homePrefs().edit().putString(FREEBOX_HOME_VIDEOS_CACHE, updated.toString()).apply();
            }
            runOnUiThread(this::refreshEmptyHomeSuggestions);
        } catch (Exception ignored) { }
    }
    private void removeFreeboxHomeVideoFromCache(String path) {
        if (path == null || path.isEmpty()) return;
        try {
            synchronized (homeCategoryVideosLoadLock) {
                JSONArray cached = new JSONArray(homePrefs().getString(FREEBOX_HOME_VIDEOS_CACHE, "[]"));
                JSONArray retained = new JSONArray();
                for (int index = 0; index < cached.length(); index++) {
                    JSONObject item = cached.optJSONObject(index);
                    if (item != null && !comparableSmbPath(path).equals(comparableSmbPath(item.optString("path", "")))) retained.put(item);
                }
                homePrefs().edit().putString(FREEBOX_HOME_VIDEOS_CACHE, retained.toString()).apply();
            }
        } catch (Exception ignored) { }
    }
    private void resetFreeboxHomeVideoCachePosition(String path) {
        if (path == null || path.isEmpty()) return;
        try {
            synchronized (homeCategoryVideosLoadLock) {
                JSONArray cached = new JSONArray(homePrefs().getString(FREEBOX_HOME_VIDEOS_CACHE, "[]"));
                JSONArray updated = new JSONArray();
                for (int index = 0; index < cached.length(); index++) {
                    JSONObject item = cached.optJSONObject(index);
                    if (item != null && path.equals(item.optString("path", ""))) {
                        item.put("position", 0L);
                    }
                    if (item != null) updated.put(item);
                }
                homePrefs().edit().putString(FREEBOX_HOME_VIDEOS_CACHE, updated.toString()).apply();
            }
        } catch (Exception ignored) { }
    }

    private void removeDeletedFreeboxHomeCards(JojoProgram program) {
        if (program == null) return;
        String key = resumeDismissKey(program);
        if (continueWatchingModernHero()) {
            // The Hero keeps its own program list; its root is not a focusable card.
            applyHomeHeroSnapshot(cachedContinueWatchingHomePrograms());
        } else {
            View resumeCard = findFocusableHomeCardByKey(currentHomeResumesView, key);
            if (resumeCard != null) removeResumeCards(program, resumeCard);
        }
        removeHomeCardsByKey(currentHomeSectionViews.get("videos"), key);
        removeHomeCardsByKey(activeScreen, key);
        if (homeCategoryVideoRemoval != null) homeCategoryVideoRemoval.accept(program);
    }

    private void onSmbVideoDeleted(String path, String signature) {
        rememberDeletedFreeboxPath(path, signature);
        runOnUiThread(() -> {
            // Preserve the other sources while clearing this file's resume caches.
            List<JojoProgram> remaining = cachedContinueWatchingHomePrograms();
            JojoProgram program = new JojoProgram(FILE_VIDEO_RESUME_SOURCE,
                    cleanFileName(path), "", "", path, -1L, -1L);
            clearVideoResume(path);
            dismissResumeLocally(program);
            removeFreeboxHomeVideoFromCache(path);
            cacheContinueWatchingHomePrograms(remaining);
            removeDeletedFreeboxHomeCards(program);
        });
    }

    private View findFocusableHomeCardByKey(View root, String key) {
        if (root == null || key == null) return null;
        if (root.isFocusable() && key.equals(root.getTag())) return root;
        if (root instanceof ViewGroup) {
            ViewGroup group = (ViewGroup) root;
            for (int index = 0; index < group.getChildCount(); index++) {
                View match = findFocusableHomeCardByKey(group.getChildAt(index), key);
                if (match != null) return match;
            }
        }
        return null;
    }

    private void removeHomeCardsByKey(View root, String key) {
        if (root == null || key == null) return;
        ArrayList<View> matches = new ArrayList<>();
        collectResumeCardsWithKey(root, key, matches);
        for (View match : matches) {
            if (!(match.getParent() instanceof ViewGroup)) continue;
            ViewGroup row = (ViewGroup) match.getParent();
            int index = row.indexOfChild(match);
            View next = index + 1 < row.getChildCount() ? row.getChildAt(index + 1)
                    : index > 0 ? row.getChildAt(index - 1) : null;
            boolean restoreFocus = match.hasFocus();
            row.removeView(match);
            if ("folder_episode_row".equals(row.getTag())) {
                wireCyclicHorizontalCardRowDpad(row);
                View artwork = root.findViewWithTag("home_category_hero_artwork");
                View hero = artwork != null && artwork.getParent() instanceof View
                        ? (View) artwork.getParent() : null;
                if (hero != null) {
                    View first = row.getChildCount() > 0 ? row.getChildAt(0) : null;
                    hero.setNextFocusDownId(first == null ? View.NO_ID : first.getId());
                }
                if (row.getChildCount() == 0) {
                    row.addView(text("Aucune vidéo dans ce dossier.", 16, muted),
                            new LinearLayout.LayoutParams(dp(360), dp(180)));
                }
            }
            if (restoreFocus && next != null && next.isFocusable()) next.requestFocus();
        }
    }
    private String freeboxResumeSignatureKey(String path) {
        return "video_resume_signature_" + path;
    }
    /** Keeps a durable tombstone for files removed from Freebox/Vidéos. */
    private void rememberDeletedFreeboxPath(String path, String signature) {
        if (path == null || path.isEmpty()) return;
        try {
            JSONObject deleted = new JSONObject(homePrefs().getString(FREEBOX_DELETED_PATHS, "{}"));
            deleted.put(comparableSmbPath(path), new JSONObject()
                    .put("signature", signature == null ? "" : signature)
                    .put("deletedAt", System.currentTimeMillis()));
            homePrefs().edit().putString(FREEBOX_DELETED_PATHS, deleted.toString()).apply();
        } catch (Exception ignored) { }
    }
    private boolean isDeletedFreeboxPath(String path, String currentSignature, long currentModified) {
        if (path == null || path.isEmpty()) return false;
        try {
            JSONObject deleted = new JSONObject(homePrefs().getString(FREEBOX_DELETED_PATHS, "{}"));
            String markerKey = deleted.has(comparableSmbPath(path)) ? comparableSmbPath(path) : path;
            JSONObject marker = deleted.optJSONObject(markerKey);
            if (marker == null) return false;
            String oldSignature = marker.optString("signature", "");
            if (!oldSignature.isEmpty() && currentSignature != null && !currentSignature.isEmpty() && !oldSignature.equals(currentSignature)) {
                deleted.remove(markerKey);
                homePrefs().edit().putString(FREEBOX_DELETED_PATHS, deleted.toString()).apply();
                return false;
            }
            if (oldSignature.isEmpty()) {
                long deletedAt = marker.optLong("deletedAt", 0L);
                if (deletedAt > 0L && currentModified > deletedAt) {
                    deleted.remove(markerKey);
                    homePrefs().edit().putString(FREEBOX_DELETED_PATHS, deleted.toString()).apply();
                    return false;
                }
            }
            return true;
        } catch (Exception ignored) { return false; }
    }
    private boolean isDeletedFreeboxPath(String path, String currentSignature, long currentModified,
                                         jcifs.CIFSContext context) {
        if (!isDeletedFreeboxPath(path, currentSignature, currentModified)) return false;
        // A rename can briefly disappear from SMB and leave a tombstone for
        // the same case-insensitive path. A fresh probe of the listed spelling
        // repairs that marker without reviving genuinely deleted/stale entries.
        if (Boolean.TRUE.equals(freeboxPathExists(android.net.Uri.decode(path), context))) {
            clearDeletedFreeboxPath(path);
            return false;
        }
        return true;
    }
    private void clearDeletedFreeboxPath(String path) {
        if (path == null || path.isEmpty()) return;
        try {
            JSONObject deleted = new JSONObject(homePrefs().getString(FREEBOX_DELETED_PATHS, "{}"));
            deleted.remove(path);
            deleted.remove(comparableSmbPath(path));
            homePrefs().edit().putString(FREEBOX_DELETED_PATHS, deleted.toString()).apply();
        } catch (Exception ignored) { }
    }
    private boolean hasDeletedFreeboxPath(String path) {
        if (path == null || path.isEmpty()) return false;
        try {
            JSONObject deleted = new JSONObject(homePrefs().getString(FREEBOX_DELETED_PATHS, "{}"));
            return deleted.has(path) || deleted.has(comparableSmbPath(path));
        } catch (Exception ignored) { return false; }
    }
    // Compare encoded/decoded SMB paths without treating '+' as a space.
    private static String comparableSmbPath(String path) {
        if (path == null) return "";
        String decoded = android.net.Uri.decode(path);
        return java.text.Normalizer.normalize(decoded, java.text.Normalizer.Form.NFC)
                .replaceAll("/+$", "").toLowerCase(java.util.Locale.ROOT);
    }
    private Boolean freeboxPathExists(String path, jcifs.CIFSContext context) {
        if (path == null || path.isEmpty() || context == null) return null;
        try {
            return new jcifs.smb.SmbFile(path, context).exists();
        } catch (Exception ignored) {
            // An SMB error is inconclusive. Never turn it into a deletion.
            return null;
        }
    }
    private void reconcileFreeboxListing(String folder, jcifs.smb.SmbFile[] files, jcifs.CIFSContext context) {
        Set<String> present = new HashSet<>();
        for (jcifs.smb.SmbFile file : files) present.add(comparableSmbPath(file.getPath()));
        String parent = comparableSmbPath(folder) + "/";
        Set<String> confirmedMissing = new HashSet<>();
        ArrayList<JojoProgram> known = new ArrayList<>(cachedFreeboxHomeVideos());
        known.addAll(findFileVideoResumePrograms());
        // The global rail can outlive the per-file resume list after an APK
        // update. Include it in reconciliation so a NAS-side deletion is
        // tombstoned even when only the old Continue Watching snapshot remains.
        known.addAll(cachedContinueWatchingHomePrograms());
        for (JojoProgram program : known) {
            if (program == null) continue;
            String path = freeboxResumePath(program);
            String comparable = comparableSmbPath(path);
            if (!comparable.startsWith(parent) || present.contains(comparable)) continue;
            // Probe known descendants too; never infer deletion from a missing
            // direct-child listing or from an SMB timeout/access error.
            Boolean existsRemotely = freeboxPathExists(android.net.Uri.decode(path), context);
            if (existsRemotely == null || existsRemotely) continue;
            String previousSignature = homePrefs().getString(freeboxResumeSignatureKey(path), "");
            if (confirmedMissing.add(comparable)) rememberDeletedFreeboxPath(path, previousSignature);
            if (FILE_VIDEO_RESUME_SOURCE.equals(program.sourcePackage)) clearVideoResume(path);
            removeFreeboxHomeVideoFromCache(path);
            removeContinueWatchingHomeCacheEntry(path);
            runOnUiThread(() -> removeDeletedFreeboxHomeCards(program));
        }
        for (jcifs.smb.SmbFile file : files) {
            try {
                if (file.isDirectory()) {
                    // A folder found again in a successful listing must not keep
                    // a deletion marker from an earlier missing/renamed path.
                    if (hasDeletedFreeboxPath(file.getPath())) clearDeletedFreeboxPath(file.getPath());
                } else if (isVideoFile(cleanFileName(file.getName()))) {
                    String path = file.getPath();
                    String signature = freeboxFileSignature(file);
                    if (!isDeletedFreeboxPath(path, signature, file.getLastModified(), context)) loadFreeboxVideoResume(file);
                }
            } catch (Exception ignored) { }
        }
    }
    private String freeboxFileSignature(jcifs.smb.SmbFile file) {
        try {
            return file.getLastModified() + ":" + file.length();
        } catch (Exception ignored) {
            return "";
        }
    }
    private long freeboxResumeUpdatedAt(String path) {
        try {
            JSONArray stored = new JSONArray(homePrefs().getString(FILE_VIDEO_RESUMES, "[]"));
            for (int index = 0; index < stored.length(); index++) {
                JSONObject item = stored.optJSONObject(index);
                if (item != null && path.equals(item.optString("key", ""))) {
                    return item.optLong("updatedAt", 0L);
                }
            }
        } catch (Exception ignored) { }
        return 0L;
    }
    /**
     * A deleted Freebox file can later be replaced at the same SMB path. Do
     * not let the replacement inherit the old file's Continue Watching state.
     */
    private long loadFreeboxVideoResume(jcifs.smb.SmbFile file) {
        return loadFreeboxVideoResume(file, -1L, -1L);
    }
    private long loadFreeboxVideoResume(jcifs.smb.SmbFile file, long knownSize, long knownLastModified) {
        if (HomeWatchProgressBridge.isCloud(this)) {
            try { return HomeWatchProgressBridge.cloudFilePosition(this, file.getPath(),
                    knownSize >= 0 ? knownSize : file.length(),
                    knownLastModified >= 0 ? knownLastModified : file.getLastModified(), cleanFileName(file.getName())); }
            catch (Exception error) { return 0L; }
        }
        String path = file.getPath();
        long position = homePrefs().getLong("video_resume_" + path, 0L);
        String signature;
        try {
            long lastModified = knownLastModified >= 0L ? knownLastModified : file.getLastModified();
            long size = knownSize >= 0L ? knownSize : file.length();
            signature = lastModified + ":" + size;
        } catch (Exception ignored) {
            signature = "";
        }
        if (signature.isEmpty()) return position;
        String signatureKey = freeboxResumeSignatureKey(path);
        String previousSignature = homePrefs().getString(signatureKey, "");
        try {
            JSONArray resumes = new JSONArray(homePrefs().getString(FILE_VIDEO_RESUMES, "[]"));
            for (int i = 0; i < resumes.length(); i++) {
                JSONObject resume = resumes.optJSONObject(i);
                if (resume != null && path.equals(resume.optString("key")) && !resume.optString("fileSignature").isEmpty()) {
                    previousSignature = resume.optString("fileSignature");
                    break;
                }
            }
        } catch (Exception ignored) { }
        boolean replacement = !previousSignature.isEmpty() && !previousSignature.equals(signature);
        // Older entries did not have a signature. Their timestamp still lets
        // us detect the common delete-and-replace case during migration.
        if (!replacement && previousSignature.isEmpty() && position > 5000L) {
            long lastModified = knownLastModified >= 0L ? knownLastModified : file.getLastModified();
            replacement = lastModified > freeboxResumeUpdatedAt(path);
        }
        if (replacement) {
            clearVideoResume(path);
            JojoProgram previous = new JojoProgram(FILE_VIDEO_RESUME_SOURCE, cleanFileName(file.getName()), "", "", path, -1L, 0L);
            runOnUiThread(() -> removeDeletedFreeboxHomeCards(previous));
            position = 0L;
        }
        homePrefs().edit().putString(signatureKey, signature).apply();
        return position;
    }
    private static final class CompanionVideoEntry {
        final String root, path, canonicalPath;
        final boolean directory;
        final long size, modified, createdAt = System.currentTimeMillis();
        CompanionVideoEntry(String root, jcifs.smb.SmbFile file) throws Exception {
            this.root = root; path = file.getPath(); canonicalPath = file.getCanonicalPath(); directory = file.isDirectory();
            size = directory ? -1L : file.length(); modified = file.getLastModified();
        }
    }
    private final java.util.concurrent.ConcurrentHashMap<String, CompanionVideoEntry> companionVideoEntries =
            new java.util.concurrent.ConcurrentHashMap<>();

    private jcifs.smb.SmbFile companionVideosRoot() throws Exception {
        String remembered = homePrefs().getString("smb_home_videos_path", "").trim();
        SmbConnectionConfig connection = remembered.isEmpty() ? defaultSmbConnection() : smbConnectionForPath(remembered);
        if (connection == null) throw new IllegalStateException("Configure un lecteur SMB dans Jojo Home.");
        jcifs.CIFSContext context = smbBrowserContext(connection.user, connection.password);
        String base = connection.browserUrl();
        String basePath = comparableSmbPath(base);
        String[] candidates = { remembered, base + "Freebox/Vidéos/", base + "Freebox/Videos/", base };
        for (String path : candidates) {
            String compared = comparableSmbPath(path);
            if (path.isEmpty() || !compared.equals(basePath) && !compared.startsWith(basePath + "/")) continue;
            try {
                jcifs.smb.SmbFile candidate = new jcifs.smb.SmbFile(path, context);
                jcifs.smb.SmbFile folder = isVideosFolderPath(candidate.getPath()) ? candidate : findFreeboxVideosFolder(candidate);
                if (folder != null && isVideosFolderPath(folder.getPath()) && folder.isDirectory()) {
                    homePrefs().edit().putString("smb_home_videos_path", folder.getPath()).apply();
                    return folder;
                }
            } catch (Exception ignored) { }
        }
        throw new IOException("Dossier Vidéos indisponible. Vérifie le lecteur SMB dans Jojo Home.");
    }
    private CompanionVideoEntry companionVideoEntry(String id, String root) {
        CompanionVideoEntry entry = companionVideoEntries.get(id);
        if (entry == null || System.currentTimeMillis() - entry.createdAt > 15 * 60_000L
                || !entry.root.equals(root) || !entry.path.startsWith(root) || entry.path.equals(root))
            throw new IllegalArgumentException("Cet élément a changé ou expiré. Actualise le dossier Vidéos.");
        return entry;
    }
    /** Companion receives opaque handles, never SMB credentials or arbitrary filesystem paths. */
    public JSONObject companionVideos(String action, String id, int page) throws Exception {
        if (isFinishing() || isDestroyed()) throw new IllegalStateException("Ouvre Jojo Home sur cette TV.");
        if ("artwork".equals(action))
            return companionVideoArtwork(companionVideoEntry(id, homePrefs().getString("smb_home_videos_path", "")));
        jcifs.smb.SmbFile root = companionVideosRoot();
        String rootPath = root.getPath();
        CompanionVideoEntry selected = id.isEmpty() ? null : companionVideoEntry(id, rootPath);
        jcifs.smb.SmbFile file = selected == null ? root : new jcifs.smb.SmbFile(selected.path, root.getContext());
        if ("delete".equals(action)) {
            if (selected == null) throw new IllegalArgumentException("Le dossier Vidéos ne peut pas être supprimé.");
            if (!file.exists() || file.isDirectory() != selected.directory
                    || file.getLastModified() != selected.modified || !selected.directory && file.length() != selected.size)
                throw new IllegalArgumentException("Le fichier a changé depuis son affichage. Actualise avant de le supprimer.");
            deleteSmbTree(file, this);
            companionVideoEntries.entrySet().removeIf(entry -> entry.getValue().path.equals(selected.path)
                    || selected.directory && entry.getValue().path.startsWith(selected.path));
            if (selected.directory) runOnUiThread(() -> {
                removeFreeboxHomeVideoFromCache(selected.path);
                refreshHomeVideosSectionInPlace(true);
            });
            return new JSONObject().put("deleted", true);
        }
        if (!"list".equals(action) || page < 0 || page > 1000 || selected != null && !selected.directory)
            throw new IllegalArgumentException("Dossier Vidéos invalide.");
        ArrayList<jcifs.smb.SmbFile> children = new ArrayList<>();
        for (jcifs.smb.SmbFile child : file.listFiles()) {
            if (child.isDirectory() || isVideoFile(cleanFileName(child.getName()))) children.add(child);
        }
        children.sort((left, right) -> cleanFileName(left.getName()).compareToIgnoreCase(cleanFileName(right.getName())));
        long oldest = System.currentTimeMillis() - 15 * 60_000L;
        companionVideoEntries.entrySet().removeIf(entry -> entry.getValue().createdAt < oldest);
        JSONArray items = new JSONArray();
        int end = Math.min(children.size(), (page + 1) * 60);
        for (int index = page * 60; index < end; index++) {
            jcifs.smb.SmbFile child = children.get(index);
            CompanionVideoEntry entry = new CompanionVideoEntry(rootPath, child);
            String token = java.util.UUID.randomUUID().toString();
            if (companionVideoEntries.size() >= 2048) {
                Map.Entry<String, CompanionVideoEntry> first = companionVideoEntries.entrySet().stream().min(
                        java.util.Comparator.comparingLong(value -> value.getValue().createdAt)).orElse(null);
                if (first != null) companionVideoEntries.remove(first.getKey(), first.getValue());
            }
            companionVideoEntries.put(token, entry);
            items.put(new JSONObject().put("id", token).put("name", cleanFileName(child.getName()))
                    .put("directory", entry.directory).put("size", entry.size).put("modified", entry.modified));
        }
        return new JSONObject().put("folder", id).put("name", selected == null ? "Vidéos" : cleanFileName(file.getName()))
                .put("items", items).put("total", children.size()).put("nextPage", end < children.size() ? page + 1 : JSONObject.NULL);
    }
    private JSONObject companionVideoArtwork(CompanionVideoEntry entry) throws Exception {
        if (entry == null) throw new IllegalArgumentException("Vignette invalide.");
        String artwork = entry.directory ? homeVideosFolderArtwork(entry.path)
                : homeVideosFileArtwork(entry.path, entry.path.substring(entry.path.lastIndexOf('/') + 1));
        if (artwork.isEmpty() && entry.directory) artwork = smbFolderArtwork(entry.path);
        if (artwork.isEmpty() && !entry.directory) {
            VideoArtwork cached = sharedFileArtworkMetadata(entry.path);
            if (cached != null) artwork = cached.posterUrl;
        }
        File local = artwork.startsWith("jojo-home-asset:")
                ? homeArtworkAssetFile(artwork.substring("jojo-home-asset:".length())) : storedFile(artwork);
        if ((local == null || !local.isFile()) && (artwork.startsWith("https://") || artwork.startsWith("http://")))
            return new JSONObject().put("url", artwork);
        if ((local == null || !local.isFile()) && !entry.directory) {
            String identity = "smb:" + entry.canonicalPath + ":" + entry.modified + ":" + entry.size;
            String hash = Integer.toUnsignedString(identity.hashCode(), 16);
            String saved = homePrefs().getString("video_frame_" + hash, "");
            local = saved.isEmpty() ? null : new File(saved);
            if (local == null || !local.isFile()) local = new File(videoFrameDirectory(), "auto_" + hash + ".jpg");
        }
        if (local != null && local.isFile()) {
            BitmapFactory.Options options = new BitmapFactory.Options(); options.inJustDecodeBounds = true;
            BitmapFactory.decodeFile(local.getAbsolutePath(), options);
            options.inSampleSize = 1;
            while (Math.max(options.outWidth, options.outHeight) / options.inSampleSize > 576) options.inSampleSize *= 2;
            options.inJustDecodeBounds = false;
            Bitmap bitmap = BitmapFactory.decodeFile(local.getAbsolutePath(), options);
            if (bitmap != null) try {
                java.io.ByteArrayOutputStream bytes = new java.io.ByteArrayOutputStream();
                bitmap.compress(Bitmap.CompressFormat.JPEG, 88, bytes);
                return new JSONObject().put("image", "data:image/jpeg;base64," + android.util.Base64.encodeToString(bytes.toByteArray(), android.util.Base64.NO_WRAP));
            } finally { bitmap.recycle(); }
        }
        if (artwork.startsWith("https://") || artwork.startsWith("http://")) return new JSONObject().put("url", artwork);
        return new JSONObject();
    }

    private List<JojoProgram> findFreeboxHomeVideos() {
        SmbConnectionConfig connection = defaultSmbConnection();
        if (connection == null || connection.server.isEmpty()) return Collections.emptyList();
        try {
            jcifs.CIFSContext context = smbContext(connection.user, connection.password);
            jcifs.smb.SmbFile videosFolder = null;
            String baseUrl = connection.browserUrl();
            // Playback history must never select this rail's folder: deleting
            // a resume must not switch the rail to a parent or another folder.
            // Freebox OS does not reliably enumerate the SMB share root: on the
            // Firestick it answers STATUS_INVALID_PARAMETER. Try the known
            // Freebox share paths directly before falling back to enumeration.
            String rememberedVideosPath = homePrefs().getString("smb_home_videos_path", "").trim();
            String[] directPaths = new String[] {
                    rememberedVideosPath,
                    baseUrl + "Freebox/Vidéos/",
                    baseUrl + "Freebox/Videos/",
                    baseUrl
            };
            for (String path : directPaths) {
                if (path.isEmpty()) continue;
                if (videosFolder != null) break;
                try {
                    jcifs.smb.SmbFile candidate = new jcifs.smb.SmbFile(path, context);
                    jcifs.smb.SmbFile resolved = isVideosFolderPath(candidate.getPath())
                            ? candidate : findFreeboxVideosFolder(candidate);
                    if (resolved != null && isVideosFolderPath(resolved.getPath())) {
                        resolved.listFiles();
                        videosFolder = resolved;
                        homePrefs().edit().putString("smb_home_videos_path", resolved.getPath()).apply();
                        break;
                    }
                } catch (Exception ignored) { }
            }
            if (videosFolder == null) {
                jcifs.smb.SmbFile root = new jcifs.smb.SmbFile(baseUrl, context);
                videosFolder = findFreeboxVideosFolder(root);
            }
            if (videosFolder == null || !isVideosFolderPath(videosFolder.getPath())) return Collections.emptyList();
            ArrayList<JojoProgram> result = new ArrayList<>();
            jcifs.smb.SmbFile[] listedFiles = videosFolder.listFiles();
            int hiddenEntries = 0, unsupportedEntries = 0, unavailableEntries = 0, deletedEntries = 0;
            reconcileFreeboxListing(videosFolder.getPath(), listedFiles, context);
            for (jcifs.smb.SmbFile file : listedFiles) {
                String name = cleanFileName(file.getName());
                if (isHomeVideoHidden(file.getPath())) { hiddenEntries++; continue; }
                boolean directory;
                try { directory = file.isDirectory(); }
                catch (Exception entryError) {
                    unavailableEntries++;
                    android.util.Log.w("JojoHomeSmb", "Entrée Freebox ignorée: " + name, entryError);
                    continue;
                }
                if (directory) {
                    result.add(new JojoProgram(FREEBOX_FOLDER_SOURCE, name, "", "", file.getPath(), -1L, -1L));
                    continue;
                }
                if (!isVideoFile(name)) { unsupportedEntries++; continue; }
                String filePath = file.getPath();
                String fileSignature = freeboxFileSignature(file);
                if (isDeletedFreeboxPath(filePath, fileSignature, file.getLastModified(), context)) {
                    deletedEntries++;
                    continue;
                }
                long duration = cachedSmbVideoDurationMs(file);
                long position = loadFreeboxVideoResume(file);
                result.add(new JojoProgram(FILE_VIDEO_RESUME_SOURCE, name, "", "", file.getPath(), duration, position));
            }
            // Once the directory listing succeeds, only its entries belong
            // in Videos. An old cache/exists() result must not append a file
            // removed in Freebox OS. Network failures keep the cache below;
            // only a confirmed missing path clears playback progress above.
            android.util.Log.d("JojoHomeSmb", "VIDEOS_SCAN listed=" + listedFiles.length + " accepted=" + result.size()
                    + " hidden=" + hiddenEntries + " unsupported=" + unsupportedEntries
                    + " unavailable=" + unavailableEntries + " deleted=" + deletedEntries);
            cacheFreeboxHomeVideos(result);
            migrateLegacyFreeboxResumes(result);
            sortFreeboxHomeVideos(result);
            return result;
        } catch (Exception error) {
            android.util.Log.w("JojoHomeSmb", "Impossible de charger la ligne Vidéos Freebox depuis " + connection.server, error);
            // A transient SMB timeout must not erase a valid Home rail. Keep
            // the last snapshot visible and let the next Home return retry
            // the authoritative listing.
            return cachedFreeboxHomeVideos();
        }
    }
    /** Restores old video_resume_<path> entries into the shared resume records. */
    private void migrateLegacyFreeboxResumes(List<JojoProgram> videos) {
        if (HomeWatchProgressBridge.isCloud(this)) return;
        try {
            JSONArray stored = new JSONArray(homePrefs().getString(FILE_VIDEO_RESUMES, "[]"));
            Set<String> known = new HashSet<>();
            for (int index = 0; index < stored.length(); index++) {
                JSONObject item = stored.optJSONObject(index);
                if (item != null) known.add(item.optString("key", ""));
            }
            JSONArray updated = new JSONArray(stored.toString());
            boolean changed = false;
            for (JojoProgram video : videos) {
                if (video == null || !FILE_VIDEO_RESUME_SOURCE.equals(video.sourcePackage)
                        || video.intentUri == null || known.contains(video.intentUri)
                        || !SystemContinueWatching.hasProgress(video.duration, video.position)) continue;
                updated.put(new JSONObject()
                        .put("key", video.intentUri)
                        .put("position", video.position)
                        .put("duration", video.duration)
                        .put("title", video.title)
                        .put("source", video.intentUri)
                        .put("updatedAt", System.currentTimeMillis()));
                known.add(video.intentUri);
                changed = true;
            }
            if (changed) homePrefs().edit().putString(FILE_VIDEO_RESUMES, updated.toString()).putBoolean("nas_home_pending", true).apply();
        } catch (Exception ignored) { }
    }
    private void sortFreeboxHomeVideos(List<JojoProgram> videos) {
        Collator folderOrder = Collator.getInstance(Locale.FRENCH);
        folderOrder.setStrength(Collator.PRIMARY);
        Collections.sort(videos, (left, right) -> {
            boolean leftFolder = FREEBOX_FOLDER_SOURCE.equals(left.sourcePackage);
            boolean rightFolder = FREEBOX_FOLDER_SOURCE.equals(right.sourcePackage);
            if (leftFolder != rightFolder) return leftFolder ? -1 : 1;
            if (leftFolder) return folderOrder.compare(left.title, right.title);
            if (!leftFolder && left.duration != right.duration) return Long.compare(left.duration <= 0L ? Long.MAX_VALUE : left.duration, right.duration <= 0L ? Long.MAX_VALUE : right.duration);
            return left.title.compareToIgnoreCase(right.title);
        });
    }
    private jcifs.smb.SmbFile findFreeboxVideosFolder(jcifs.smb.SmbFile root) throws Exception {
        String rootName = Normalizer.normalize(cleanFileName(root.getName()), Normalizer.Form.NFD)
                .replaceAll("\\p{M}", "").toLowerCase(Locale.ROOT);
        if (rootName.equals("videos") || rootName.equals("video")) return root;
        ArrayList<jcifs.smb.SmbFile> candidates = new ArrayList<>();
        candidates.add(root);
        for (int depth = 0; depth < 2 && !candidates.isEmpty(); depth++) {
            ArrayList<jcifs.smb.SmbFile> next = new ArrayList<>();
            for (jcifs.smb.SmbFile parent : candidates) {
                for (jcifs.smb.SmbFile child : parent.listFiles()) {
                    if (!child.isDirectory()) continue;
                    String normalized = Normalizer.normalize(cleanFileName(child.getName()), Normalizer.Form.NFD)
                            .replaceAll("\\p{M}", "").toLowerCase(Locale.ROOT);
                    if ((normalized.equals("videos") || normalized.equals("video"))
                            && (child.getPath().toLowerCase(Locale.ROOT).contains("freebox") || depth > 0)) return child;
                    next.add(child);
                }
            }
            candidates = next;
        }
        return null;
    }
    private View contentRows() {
        final long renderGeneration = homeRenderGeneration;
        currentHomeHeroUpdater = null;
        currentHomeSuggestionsUpdater = null;
        currentHomeSuggestionsInteraction = null;
        // The home page provides the vertical ScrollView.  Keeping this as a plain
        // container prevents a nested scroller from moving only these rows.
        LinearLayout rows = new LinearLayout(this); rows.setOrientation(LinearLayout.VERTICAL); rows.setClipChildren(false); rows.setClipToPadding(false);
        rows.setVisibility(View.GONE);
        // Keep the section in the first Home layout pass.  The bridge/NAS
        // lookup below is asynchronous, but an empty container made the whole
        // "Continuer à regarder" row visibly pop in a moment after apps and
        // shortcuts had already appeared.
        List<JojoProgram> cachedContinue = cachedContinueWatchingHomePrograms();
        final boolean hadCachedContinue = !cachedContinue.isEmpty();
        if (!homeGridMode() && (hadCachedContinue || !continueWatchingModernHero()))
            addHomeSectionTitle(rows, "resumes", "Continuer à regarder", HOME_TITLE_TO_CARD_GAP_DP - HOME_CONTINUE_CONTENT_TOP_INSET_DP);
        if (continueWatchingModernHero()) {
            rows.addView(globalContinueRow(cachedContinue), homeHeroLayoutParams());
            rows.setVisibility(View.VISIBLE);
        } else {
            TextView loading = text("Chargement des reprises…", 16, muted);
            loading.setGravity(Gravity.CENTER_VERTICAL);
            rows.addView(loading, new LinearLayout.LayoutParams(-1, dp(continueWatchingRowHeightDp() * homeSectionRows("resumes"))));
        }
        if (!cachedContinue.isEmpty() && !continueWatchingModernHero()) {
            rows.removeAllViews();
            if (!homeGridMode()) addHomeSectionTitle(rows, "resumes", "Continuer à regarder", HOME_TITLE_TO_CARD_GAP_DP - HOME_CONTINUE_CONTENT_TOP_INSET_DP);
            // Keep a focusable classic rail while provider/NAS sources refresh.
            rows.addView(jojoProgramsRow(cachedContinue), new LinearLayout.LayoutParams(
                    -1, dp(continueWatchingRowHeightDp() * homeSectionRows("resumes"))));
            rows.setVisibility(View.VISIBLE);
        }
        refreshContentRowsData(rows, hadCachedContinue, renderGeneration);
        return rows;
    }

    private void refreshContentRowsData(LinearLayout rows, boolean hadCachedContinue, long renderGeneration) {
        if (isDestroyed() || homeResumeQueryExecutor.isShutdown()) return;
        final long queryGeneration = ++homeResumeQueryGeneration;
        // Migrate legacy Freebox positions from the local video cache before
        // the asynchronous resume query starts, so older recordings are not
        // filtered out of Videos without also entering Continue Watching.
        migrateLegacyFreeboxResumes(cachedFreeboxHomeVideos());
        Set<String> selected = contentApps();
        homeResumeQueryExecutor.execute(() -> {
            if (isDestroyed() || queryGeneration != homeResumeQueryGeneration) return;
            List<String> packages = new ArrayList<>(selected);
            // PackageManager can be slow on a TV with many applications.  It
            // must not run during the focus transaction that follows a player
            // exit, otherwise Home is visible but cannot consume D-pad input.
            // Include installed variants of the selected applications, whose
            // TV package may differ from a selection synchronized from the NAS.
            for (android.content.pm.ResolveInfo info : allLaunchableApps()) {
                String packageName = info.activityInfo == null ? "" : info.activityInfo.packageName;
                if (acceptsResumeSource(selected, packageName)
                        && !packages.contains(packageName)) packages.add(packageName);
            }
            Collections.sort(packages, (left, right) -> isJojoPackage(left) ? -1 : isJojoPackage(right) ? 1 : left.compareToIgnoreCase(right));
            LinkedHashMap<String, List<JojoProgram>> available = new LinkedHashMap<>();
            PublishedResumeSnapshot watchNextSnapshot = readSystemContinueWatchingSnapshot();
            List<JojoProgram> systemPrograms = new ArrayList<>(watchNextSnapshot.programs);
            List<JojoProgram> netflixNativePrograms = new ArrayList<>(watchNextSnapshot.programs);
            boolean netflixPreviewAvailable = true;
            boolean netflixQueried = false;
            for (JojoProgram program : systemPrograms) observeSharedExternalResume(program, "watch-next");
            // Jojo Home's integrated player writes profile-scoped canonical
            // progress. Legacy file/external preference records are not safe
            // to merge here because they have no reliable profile identity.
            for (JojoProgram progressResume : watchProgressHomePrograms()) {
                addResumeProgramIfMissing(systemPrograms, progressResume);
            }
            if (isDestroyed() || queryGeneration != homeResumeQueryGeneration) return;
            List<JojoProgram> externalResumeSnapshot = loadExternalPlaybackContinuePrograms();
            List<JSONObject> movieFavoriteSnapshot = com.jojotv.home.iptv.IptvStore.applyHomeFavoriteProgress(
                    this, ExternalPlaybackStore.list(this, "movies"));
            List<JSONObject> seriesFavoriteSnapshot = com.jojotv.home.iptv.IptvStore.applyHomeFavoriteProgress(
                    this, ExternalPlaybackStore.list(this, "series"));
            // SmartTube does not expose a MediaSession on this Philips TV, but
            // it does publish its watched videos to Android TV preview channels.
            // Those entries carry the real YouTube deep link, unlike the former
            // generic app shortcut which could only reopen SmartTube's home.
            for (JojoProgram smartTubeResume : findSmartTubeResumeProgramsSynced()) {
                if (acceptsResumeSource(selected, smartTubeResume.sourcePackage)) addResumeProgramIfMissing(systemPrograms, smartTubeResume);
            }
            // The official YouTube TV app follows the same Preview-channel
            // model on this device. Its notification timing, when published,
            // is merged below to draw the real progress bar.
            for (JojoProgram youtubeResume : findYoutubeResumePrograms()) addResumeProgramIfMissing(systemPrograms, youtubeResume);
            // Fallback pour Fire Stick : si pas de permission READ_TV_LISTINGS, charger JojoTV
            if (systemPrograms.isEmpty() && isFireOsDevice()) systemPrograms.addAll(findJojoPrograms());
            // Watch Next ne publie que le profil JojoTV actif. Le bridge JojoTV,
            // lui, agrège les snapshots de tous les profils ; il doit donc remplacer
            // les entrées Jojo de Watch Next, sans masquer les autres applications.
            List<JojoProgram> allJojoProfiles = findJojoPrograms();
            boolean jojoProfilesMerged = !allJojoProfiles.isEmpty();
            if (jojoProfilesMerged) {
                systemPrograms.removeIf(program -> isJojoPackage(program.sourcePackage));
                systemPrograms.addAll(allJojoProfiles);
            }
            List<JojoProgram> notificationPrograms = findNotificationResumePrograms();
            for (JojoProgram program : notificationPrograms) observeSharedExternalResume(program, "notification");
            android.util.Log.i("JojoHomeResume", "contentRows system=" + systemPrograms.size() + " jojoProfiles=" + allJojoProfiles.size() + " notification=" + notificationPrograms.size() + " packages=" + packages.size());
            for (JojoProgram notificationProgram : notificationPrograms) addResumeProgramIfMissing(systemPrograms, notificationProgram);
            // A completed external session must never be shown as a resume.
            // SmartTube may leave the item in its history after playback ends.
            systemPrograms.removeIf(program -> isResumeDismissed(program) || isFinishedExternalResume(program));
            for (String packageName : packages) {
                if (appLabel(packageName) == null) continue;
                // Selected providers can publish their resumes in a dedicated
                // Preview channel instead of Watch Next. Read only channels
                // identified as Continue/Reprendre, never their recommendations.
                PublishedResumeSnapshot previewSnapshot = hasTvListingsAccess() && !isJojoPackage(packageName)
                        && !NotificationResumeRules.isYoutubeVideoPackage(packageName)
                        ? readPreviewHistoryResumeSnapshot(packageName, packageName)
                        : new PublishedResumeSnapshot(false, Collections.emptyList());
                List<JojoProgram> programs = isJojoPackage(packageName)
                        ? jojoProfilesMerged ? Collections.emptyList() : findJojoPrograms() : previewSnapshot.programs;
                if ("netflix".equals(SystemContinueWatching.sharedResumeProvider(packageName))) {
                    netflixQueried = true;
                    netflixPreviewAvailable &= previewSnapshot.available;
                    netflixNativePrograms.addAll(previewSnapshot.programs);
                }
                List<JojoProgram> packagePrograms = new ArrayList<>(programs);
                if (NotificationResumeRules.isFreeTvPackage(packageName)) {
                    for (JojoProgram freeTvResume : findFreeTvResumePrograms(packageName))
                        addResumeProgramIfMissing(packagePrograms, freeTvResume);
                }
                for (JojoProgram systemProgram : systemPrograms) {
                    if (systemProgram == null || systemProgram.sourcePackage == null) continue;
                    if (acceptsResumeSource(Collections.singleton(packageName), systemProgram.sourcePackage)) addResumeProgramIfMissing(packagePrograms, systemProgram);
                }
                for (JojoProgram notificationProgram : notificationPrograms) {
                    if (notificationProgram == null || notificationProgram.sourcePackage == null) continue;
                    if (acceptsResumeSource(Collections.singleton(packageName), notificationProgram.sourcePackage)) addResumeProgramIfMissing(packagePrograms, notificationProgram);
                }
                String sharedProvider = SystemContinueWatching.sharedResumeProvider(packageName);
                if (!sharedProvider.isEmpty()) {
                    List<JojoProgram> nativeNetflixPrograms = "netflix".equals(sharedProvider) ? new ArrayList<>(packagePrograms) : Collections.emptyList();
                    homePrefs().edit().putString("nas_external_package_" + sharedProvider, packageName).apply();
                    packagePrograms = cachedSharedExternalResumePrograms(packageName);
                    if ("netflix".equals(sharedProvider)) {
                        for (JojoProgram nativeProgram : nativeNetflixPrograms) addResumeProgramIfMissing(packagePrograms, nativeProgram);
                        packagePrograms = mergeNetflixCloudResumes(packagePrograms, packageName);
                    }
                    systemPrograms.removeIf(program -> sharedProvider.equals(SystemContinueWatching.sharedResumeProvider(program.sourcePackage)));
                    systemPrograms.addAll(packagePrograms);
                }
                packagePrograms.removeIf(program -> isResumeDismissed(program) || isFinishedExternalResume(program));
                // Une application activée ne crée une section que lorsqu'elle fournit
                // effectivement un contenu à reprendre.
                if (!packagePrograms.isEmpty()) available.put(packageName, packagePrograms);
            }
            if (isDestroyed() || queryGeneration != homeResumeQueryGeneration) return;
            final boolean netflixPreviewComplete = netflixQueried && netflixPreviewAvailable;
            runOnUiThread(() -> {
                // Ignore a result belonging to a Home tree that has already
                // been replaced. Without this guard, an old query could clear
                // the new rail and rewire focus several seconds later.
                if (isDestroyed() || renderGeneration != homeRenderGeneration || rows != currentHomeResumesView
                        || queryGeneration != homeResumeQueryGeneration) return;
                reconcileNetflixResumeSnapshot(netflixNativePrograms, watchNextSnapshot.available, netflixPreviewComplete);
                externalPlaybackContinueSnapshot = Collections.unmodifiableList(
                        new ArrayList<>(externalResumeSnapshot));
                homeCategoryFavoriteSnapshots.put("movies", new ArrayList<>(movieFavoriteSnapshot));
                homeCategoryFavoriteSnapshots.put("series", new ArrayList<>(seriesFavoriteSnapshot));
                List<JojoProgram> allPrograms = new ArrayList<>(mergeContinueWatchingPrograms(systemPrograms, available));
                allPrograms.removeIf(this::isResumeDismissed);
                cacheContinueWatchingHomePrograms(allPrograms);
                if (homeDpadNavigationActive) {
                    homeRefreshPendingAfterDpad = true;
                    return;
                }
                if (continueWatchingModernHero() && currentHomeHeroUpdater != null) {
                    applyHomeHeroSnapshot(allPrograms);
                    nasHomeResumeRefreshPending = false;
                    return;
                }
                if (hadCachedContinue && isHomeDescendant(getCurrentFocus(), rows)) {
                    nasHomeResumeRefreshPending = true;
                    return;
                }
                if (!isFocusedExternalPlaybackRow()) renderExternalPlaybackRows();
                nasHomeResumeRefreshPending = false;
                String focusedResumeKey = focusedTag(rows);
                if (focusedResumeKey != null) pendingResumeFocusKey = focusedResumeKey;
                // Replace the reserved, invisible first-pass section.  Do not
                // append to it: otherwise its title remains above the real
                // Continue Watching rail once the asynchronous lookup ends.
                rows.removeAllViews();
                if (continueWatchingModernHero()) {
                    if (!allPrograms.isEmpty() && !homeGridMode()) addHomeSectionTitle(rows, "resumes", "Continuer à regarder", HOME_TITLE_TO_CARD_GAP_DP - HOME_CONTINUE_CONTENT_TOP_INSET_DP);
                    rows.addView(globalContinueRow(allPrograms), homeHeroLayoutParams());
                    if (!homeGridMode()) rows.addView(space(continueWatchingHeroBottomSpacingDp()));
                    rows.setVisibility(View.VISIBLE);
                    setHomeSectionVisible("resumes", true);
                } else {
                    currentHomeHeroUpdater = null;
                    systemPrograms.removeIf(this::isResumeDismissed);
                    available.values().forEach(programs -> programs.removeIf(this::isResumeDismissed));
                    available.values().removeIf(List::isEmpty);
                    if (!systemPrograms.isEmpty()) {
                        addHomeSectionTitle(rows, "resumes", "Continuer à regarder", HOME_TITLE_TO_CARD_GAP_DP - HOME_CONTINUE_CONTENT_TOP_INSET_DP);
                        rows.addView(jojoProgramsRow(systemPrograms), new LinearLayout.LayoutParams(-1, dp(continueWatchingRowHeightDp() * homeSectionRows("resumes"))));
                    }
                    for (java.util.Map.Entry<String, List<JojoProgram>> entry : available.entrySet()) {
                        String packageName = entry.getKey(); List<JojoProgram> programs = entry.getValue();
                        if (isJojoPackage(packageName)) continue;
                        String label = appLabel(packageName);
                        addHomeSectionTitle(rows, "resumes", label + " : Historique", HOME_TITLE_TO_CARD_GAP_DP - HOME_CONTINUE_CONTENT_TOP_INSET_DP);
                        rows.addView(previewProgramsRow(programs, packageName), new LinearLayout.LayoutParams(-1, dp(160 * homeSectionRows("resumes"))));
                        // Keep the trailing clearance identical to the other
                        // Home sections; the outer section spacer supplies the
                        // remaining separation before Vidéos.
                        rows.addView(space(4));
                    }
                    boolean hasResumeRows = !systemPrograms.isEmpty() || !available.isEmpty();
                    rows.setVisibility(hasResumeRows ? View.VISIBLE : View.GONE);
                    if (!hasResumeRows) currentHomeSectionTitles.remove("resumes");
                    setHomeSectionVisible("resumes", hasResumeRows);
                }
                if (currentHomeHeaderView != null && currentHomeAppsView != null) {
                    wireHomeHeaderDpad(currentHomeHeaderView, currentHomeAppsView, currentHomeFilesView, rows);
                }
                wireResumeRowsDpad(rows);
                wireHomeSectionVerticalDpad();
                wireHomeCategoryGridDpad(currentHomeCategoryGrid, rows);
                restorePendingResumeFocus(rows);
                refreshHomeVideosSectionInPlace();
            });
        });
    }

    private void setHomeSectionVisible(String key, boolean visible) {
        View section = currentHomeSectionViews.get(key);
        if (homeGridMode() && ("videos".equals(key) || ExternalPlaybackStore.categoryValid(key))) {
            visible = visible && key.equals(activeHomeGridCategory);
        }
        if (section != null) section.setVisibility(visible ? View.VISIBLE : View.GONE);
        View spacer = currentHomeSectionSpacers.get(key);
        if (spacer != null) spacer.setVisibility(visible ? View.VISIBLE : View.GONE);
    }

    private void refreshHomeResumeSectionInPlace() {
        if (!homeActivityResumed) {
            nasHomeResumeRefreshPending = true;
            return;
        }
        if (homeDpadNavigationActive) {
            homeRefreshPendingAfterDpad = true;
            return;
        }
        if (currentHomePage == null || !currentHomePage.isAttachedToWindow()) return;
        View oldSection = currentHomeSectionViews.get("resumes");
        View oldSpacer = currentHomeSectionSpacers.get("resumes");
        if (oldSection == null || oldSpacer == null) return;
        if (continueWatchingModernHero() && oldSection instanceof LinearLayout
                && currentHomeHeroUpdater != null) {
            List<JojoProgram> localPrograms = cachedContinueWatchingHomePrograms();
            cacheContinueWatchingHomePrograms(localPrograms);
            applyHomeHeroSnapshot(localPrograms);
            refreshContentRowsData((LinearLayout) oldSection, true, homeRenderGeneration);
            return;
        }
        if (oldSection.hasFocus() && !continueWatchingModernHero()) {
            nasHomeResumeRefreshPending = true;
            return;
        }
        if (!isFocusedExternalPlaybackRow()) renderExternalPlaybackRows();
        View focused = getWindow().getDecorView().findFocus();
        pendingResumeFocusKey = null;
        if (focused != null && oldSection.hasFocus()) {
            // The focused control inside the Hero is the Reprendre button;
            // resolve its stable card key from the ancestor Hero instead of
            // treating the button as the first child of the action row.
            View current = focused;
            while (current != null) {
                Object tag = current.getTag();
                if (tag instanceof String && !((String) tag).isEmpty()) {
                    pendingResumeFocusKey = (String) tag;
                    break;
                }
                if (current == oldSection) break;
                current = current.getParent() instanceof View
                        ? (View) current.getParent() : null;
            }
        }
        // The player may leave Android focus on the Search header or nowhere
        // while this row is replaced. Keep the card captured on player entry
        // as the authoritative target instead of falling back to Rechercher.
        if (pendingResumeFocusKey == null && lastHomeFocusKey != null
                && oldSection.findViewWithTag(lastHomeFocusKey) != null) {
            pendingResumeFocusKey = lastHomeFocusKey;
        }
        int index = currentHomePage.indexOfChild(oldSection);
        if (index < 0) return;
        LinearLayout.LayoutParams oldSectionParams = (LinearLayout.LayoutParams) oldSection.getLayoutParams();
        LinearLayout.LayoutParams sectionParams = new LinearLayout.LayoutParams(oldSectionParams.width, oldSectionParams.height);
        sectionParams.topMargin = oldSectionParams.topMargin;
        sectionParams.bottomMargin = oldSectionParams.bottomMargin;
        sectionParams.leftMargin = oldSectionParams.leftMargin;
        sectionParams.rightMargin = oldSectionParams.rightMargin;
        LinearLayout.LayoutParams spacerParams = (LinearLayout.LayoutParams) oldSpacer.getLayoutParams();
        currentHomePage.removeView(oldSection);
        currentHomePage.removeView(oldSpacer);
        View replacement = contentRows();
        currentHomeResumesView = replacement;
        currentHomeSectionViews.put("resumes", replacement);
        currentHomePage.addView(replacement, index, sectionParams);
        currentHomePage.addView(oldSpacer, index + 1, spacerParams);
        long navigation = homeFocusGeneration;
        replacement.post(() -> {
            if (replacement != currentHomeResumesView || activeScreen != null
                    || navigation != homeFocusGeneration || !replacement.isAttachedToWindow()) return;
            wireHomeHeaderDpad(currentHomeHeaderView, currentHomeAppsView, currentHomeFilesView, replacement);
            wireHomeSectionVerticalDpad();
            wireHomeCategoryGridDpad(currentHomeCategoryGrid, replacement);
            restorePendingResumeFocus((ViewGroup) replacement);
        });
    }

    /** Rebinds the modern carousel in the current frame instead of replacing it with an async loader. */
    private boolean refreshModernHeroImmediatelyAfterRemoval(JojoProgram removedProgram) {
        if (!continueWatchingModernHero() || !(currentHomeResumesView instanceof LinearLayout)) return false;
        LinearLayout rows = (LinearLayout) currentHomeResumesView;
        if (!rows.isAttachedToWindow()) return false;
        String removedKey = resumeDismissKey(removedProgram);
        List<JojoProgram> remaining = cachedContinueWatchingHomePrograms();
        int removedIndex = -1;
        for (int index = 0; index < remaining.size(); index++) {
            if (removedKey.equals(resumeDismissKey(remaining.get(index)))) {
                removedIndex = index;
                break;
            }
        }
        remaining.removeIf(program -> removedKey.equals(resumeDismissKey(program)));
        cacheContinueWatchingHomePrograms(remaining);

        // The popup has just been dismissed and the selected Hero button may
        // be destroyed below. Park focus on the still-attached section first,
        // otherwise Android TV can search the whole Activity and land on the
        // header or temporarily give the window back to Fire OS.
        rows.setFocusable(true);
        rows.setFocusableInTouchMode(true);
        rows.requestFocus();
        rows.removeAllViews();
        if (remaining.isEmpty()) {
            // Never leave the Home hierarchy without a focusable child after
            // deleting the last Hero item. On Fire OS that transient empty
            // focus state can hand the window back to the launcher/HDMI.
            View emptyHero = globalContinueRow(remaining);
            rows.addView(emptyHero, homeHeroLayoutParams());
            if (!homeGridMode()) rows.addView(space(continueWatchingHeroBottomSpacingDp()));
            rows.setVisibility(View.VISIBLE);
            setHomeSectionVisible("resumes", true);
            View emptyFocus = emptyHero instanceof ViewGroup ? firstFocusableChild((ViewGroup) emptyHero) : emptyHero;
            if (emptyFocus == null) emptyFocus = emptyHero;
            requestHomeFocus(emptyFocus, "resume-remove-modern-empty");
            rows.setFocusable(false);
        } else {
            if (!homeGridMode()) addHomeSectionTitle(rows, "resumes", "Continuer à regarder",
                    HOME_TITLE_TO_CARD_GAP_DP - HOME_CONTINUE_CONTENT_TOP_INSET_DP);
            // Keep the next item at the removed item's position. If the last
            // item was removed, wrap to the first remaining item instead of
            // falling back to the previous card.
            int nextIndex = removedIndex >= 0 && removedIndex < remaining.size() ? removedIndex : 0;
            if (!remaining.isEmpty()) {
                // Persist the logical successor as well as the carousel index.
                // The index alone is lost if the Home section is rebuilt again
                // while the asynchronous removal is being saved.
                pendingResumeFocusKey = resumeDismissKey(remaining.get(nextIndex));
            }
            View heroRow = globalContinueRow(remaining, nextIndex);
            rows.addView(heroRow, homeHeroLayoutParams());
            if (!homeGridMode()) rows.addView(space(continueWatchingHeroBottomSpacingDp()));
            rows.setVisibility(View.VISIBLE);
            setHomeSectionVisible("resumes", true);
            View nextHero = heroRow instanceof ViewGroup ? firstFocusableChild((ViewGroup) heroRow) : heroRow;
            requestHomeFocus(nextHero, "resume-remove-modern-rebind");
            rows.setFocusable(false);
        }
        if (currentHomeHeaderView != null && currentHomeAppsView != null) {
            wireHomeHeaderDpad(currentHomeHeaderView, currentHomeAppsView,
                    currentHomeFilesView, rows);
        }
        wireResumeRowsDpad(rows);
        wireHomeSectionVerticalDpad();
        wireHomeCategoryGridDpad(currentHomeCategoryGrid, rows);
        return true;
    }

    private void refreshHomeVideosSectionInPlace() {
        refreshHomeVideosSectionInPlace(false);
    }

    private void refreshHomeVideosSectionInPlace(boolean force) {
        if (!force && shouldDeferHomeContentRefresh()) {
            homeRefreshPendingAfterDpad = true;
            return;
        }
        if (currentHomePage == null || !currentHomePage.isAttachedToWindow()) return;
        View section = currentHomeSectionViews.get("videos");
        if (!(section instanceof ViewGroup)) return;
        ViewGroup sectionGroup = (ViewGroup) section;
        if (sectionGroup.getChildCount() < 3) return;
        View rowView = sectionGroup.getChildAt(2);
        if (!(rowView instanceof LinearLayout)) return;
        LinearLayout row = (LinearLayout) rowView;
        String focusedVideoKey = focusedTag(row);
        List<JojoProgram> cachedVideos = cachedFreeboxHomeVideos();
        if (cachedVideos.isEmpty() || visibleFreeboxHomeVideos(cachedVideos).isEmpty()) {
            row.removeAllViews();
            setHomeSectionVisible("videos", false);
        } else {
            setHomeSectionVisible("videos", true);
            renderFreeboxVideoTiles(row, cachedVideos);
            restoreFocusByTag(row, focusedVideoKey);
        }
        wireHomeSectionVerticalDpad();
    }

    private void refreshHomeResumeAfterPlayerWrite() {
        scheduleHomeReturnRefresh(false, 120L);
    }

    private List<JojoProgram> watchProgressHomePrograms() {
        ArrayList<JojoProgram> result = new ArrayList<>();
        Set<String> nativeSeriesResumes = new HashSet<>();
        for (WatchProgress progress : watchProgressContinueSnapshot) {
            if (progress == null) continue;
            String contentId = progress.getContentId() == null ? "" : progress.getContentId().trim();
            String contentType = progress.getContentType() == null ? "" : progress.getContentType().trim();
            if (contentId.isEmpty()) continue;
            boolean hasEpisode = progress.getEpisode() != null || "series".equalsIgnoreCase(contentType);
            if (HomeMediaRules.completedEpisodeResume(hasEpisode, false, progress.getProgressPercentage())) continue;

            long duration = progress.isLiveChannel() ? 0L : progress.getDuration();
            long position = progress.resolveResumePosition(duration);
            if (isFinishedResumePosition(position, duration)) continue;

            String sourcePackage;
            String intentUri;
            JSONObject externalItem = null;
            if (contentId.startsWith("tizentube:")) {
                String videoId = contentId.substring("tizentube:".length());
                if (!videoId.matches("[A-Za-z0-9_-]{11}")) continue;
                sourcePackage = selectedSharedResumePackage("tizentube", Collections.emptyList());
                if (sourcePackage.isEmpty()) continue;
                intentUri = new Intent(Intent.ACTION_VIEW, Uri.parse("https://www.youtube.com/watch?v=" + videoId))
                        .setPackage(sourcePackage).toUri(Intent.URI_INTENT_SCHEME);
            } else if ("freebox".equalsIgnoreCase(contentType)
                    || contentId.regionMatches(true, 0, "freebox:", 0, 8)) {
                sourcePackage = FILE_VIDEO_RESUME_SOURCE;
                intentUri = com.nuvio.tv.data.freebox.FreeboxMediaDisplayKt
                        .freeboxPathFromContentId(contentId);
                if (intentUri.isEmpty()) continue;
            } else if ("video".equalsIgnoreCase(contentType)
                    && (contentId.startsWith("smb://") || contentId.startsWith("/")
                    || contentId.startsWith("file:"))) {
                sourcePackage = FILE_VIDEO_RESUME_SOURCE;
                intentUri = contentId;
            } else if (HomeMediaRules.nativeIptvVodResume(contentId, contentType)) {
                if ("series".equalsIgnoreCase(contentType)) {
                    if (progress.getSeason() == null || progress.getEpisode() == null) continue;
                    // The snapshot is newest first. Keep one unfinished episode
                    // per provider series, while retaining its full watched history.
                    String seriesKey = WatchProgress.stableIdentity(contentType, contentId,
                            progress.getAddonBaseUrl(), null, null);
                    if (!nativeSeriesResumes.add(seriesKey)) continue;
                }
                sourcePackage = "external-playback";
                intentUri = contentId;
                externalItem = externalResumeItem(progress);
            } else if (contentId.startsWith(ExternalPlaybackStore.CONTENT_PREFIX)) {
                sourcePackage = "external-playback";
                intentUri = contentId.substring(ExternalPlaybackStore.CONTENT_PREFIX.length());
                externalItem = externalResumeItem(progress);
                String url = externalItem.optString("url", "");
                if (externalItem.optBoolean("deleted") || !ExternalPlaybackStore.supportedUrl(url)) continue;
            } else {
                // No local playback route is associated with this ID. Keep the
                // synchronized record in storage without inventing a title or URL match.
                continue;
            }
            if (hasEpisode && externalItem != null && externalItem.optBoolean("watched")) continue;

            String title = progress.getName() == null ? "" : progress.getName().trim();
            if (title.isEmpty() && externalItem != null) title = externalItem.optString("title", "").trim();
            if (title.isEmpty()) continue;
            String artwork = contentId.startsWith("tizentube:")
                    ? "https://i.ytimg.com/vi/" + contentId.substring("tizentube:".length()) + "/hqdefault.jpg"
                    : progress.getPoster();
            if (artwork == null || artwork.trim().isEmpty()) artwork = progress.getBackdrop();
            if (artwork == null || artwork.trim().isEmpty()) artwork = progress.getLogo();
            if (externalItem != null && (artwork == null || artwork.trim().isEmpty())) {
                for (String key : new String[]{"artwork", "poster", "backdrop", "logo", "thumbnail"}) {
                    String candidate = externalItem.optString(key, "").trim();
                    if (!candidate.isEmpty()) { artwork = candidate; break; }
                }
            }
            String description = progress.getDescription() == null ? "" : progress.getDescription().trim();
            if (description.isEmpty() && progress.getEpisodeTitle() != null) {
                description = progress.getEpisodeTitle().trim();
            }
            Integer seasonValue = progress.getSeason();
            Integer episodeValue = progress.getEpisode();
            String season = seasonValue == null && externalItem != null
                    ? externalItem.optString("season", "")
                    : seasonValue == null ? null : String.valueOf(seasonValue);
            String episode = episodeValue == null && externalItem != null
                    ? externalItem.optString("episode", "")
                    : episodeValue == null ? null : String.valueOf(episodeValue);
            result.add(new JojoProgram(sourcePackage, title, description,
                    artwork == null ? "" : artwork, intentUri, duration, position, season, episode));
        }
        return result;
    }

    private JSONObject externalResumeItem(JojoProgram program) {
        if (program == null) return new JSONObject();
        for (WatchProgress progress : watchProgressContinueSnapshot) {
            String contentId = program.intentUri != null && program.intentUri.startsWith("iptv:")
                    ? program.intentUri : ExternalPlaybackStore.CONTENT_PREFIX + program.intentUri;
            if (!contentId.equals(progress.getContentId())) continue;
            if (progress.getSeason() != null && !String.valueOf(progress.getSeason()).equals(program.seasonNumber)) continue;
            if (progress.getEpisode() != null && !String.valueOf(progress.getEpisode()).equals(program.episodeNumber)) continue;
            return externalResumeItem(progress);
        }
        return ExternalPlaybackStore.get(this, program.intentUri);
    }

    private JSONObject externalResumeItem(WatchProgress progress) {
        boolean nativeVod = HomeMediaRules.nativeIptvVodResume(progress.getContentId(), progress.getContentType());
        String id = nativeVod ? progress.getContentId()
                : progress.getContentId().substring(ExternalPlaybackStore.CONTENT_PREFIX.length());
        JSONObject stored = ExternalPlaybackStore.get(this, id);
        try {
            JSONObject item = new JSONObject(stored.toString());
            // Locally known provider details still enable link renewal. The
            // synchronized route is sufficient when the other TV has no record.
            if (nativeVod) {
                if (HomeWatchProgressBridge.isCloud(this)) item.put("deleted", false).put("watched", progress.isCompleted(WatchProgress.completionThreshold(progress.getContentType(), progress.getEpisode())));
                item.put("favoriteSource", "jojo-iptv").put("category",
                        "series".equalsIgnoreCase(progress.getContentType()) ? "series" : "movies");
            } else {
                String url = item.optString("url", "");
                if (!ExternalPlaybackStore.supportedUrl(url)) url = progress.getVideoId();
                item.put("url", url);
            }
            item.put("id", id).put("title", progress.getName());
            item.put("position", progress.isLiveChannel() ? 0L : progress.getPosition());
            item.put("duration", progress.isLiveChannel() ? 0L : progress.getDuration());
            item.put("progressProfileId", watchProgressSnapshotProfileId);
            item.put("started", true).put("lastPlayedAt", progress.getLastWatched());
            item.put("season", progress.getSeason()).put("episode", progress.getEpisode());
            item.put("category", progress.isLiveChannel() ? "live"
                    : progress.getSeason() != null ? "series" : item.optString("category", "movies"));
            if (!HomeMediaRules.mediaMetadataText(progress.getDescription()).isEmpty()
                    && (!nativeVod || externalPlaybackSynopsis(item).isEmpty()))
                item.put("description", progress.getDescription());
            if (progress.getPoster() != null) item.put("poster", progress.getPoster());
            if (progress.getBackdrop() != null) item.put("backdrop", progress.getBackdrop());
            if (progress.getLogo() != null) item.put("logo", progress.getLogo());
            return item;
        } catch (Exception ignored) { return stored; }
    }

    private boolean legacyHomeResume(JojoProgram program) {
        if (program == null || !isJojoPackage(program.sourcePackage)) return false;
        try {
            Intent route = Intent.parseUri(program.intentUri, Intent.URI_INTENT_SCHEME);
            if (route.getIntExtra("androidTvProfileId", 1) != watchProgressSnapshotProfileId) return true;
            String id = route.getStringExtra("contentId");
            String type = route.getStringExtra("contentType");
            return id != null && (HomeMediaRules.nativeIptvVodResume(id, type)
                    || id.startsWith(ExternalPlaybackStore.CONTENT_PREFIX)
                    || id.startsWith("freebox:") || ("video".equals(type)
                    && (id.startsWith("/") || id.startsWith("file:") || id.startsWith("smb://"))));
        } catch (Exception ignored) { return false; }
    }

    /** Update the active carousel without detaching its focused page. */
    private void applyHomeHeroSnapshot(List<JojoProgram> programs) {
        if (currentHomeHeroUpdater != null) {
            currentHomeHeroUpdater.accept(programs);
            return;
        }
        if (!(currentHomeResumesView instanceof LinearLayout)) return;
        LinearLayout rows = (LinearLayout) currentHomeResumesView;
        boolean hadFocus = rows.hasFocus();
        if (hadFocus) { rows.setFocusable(true); rows.requestFocus(); }
        currentHomeHeroUpdater = null;
        rows.removeAllViews();
        rows.addView(globalContinueRow(programs), homeHeroLayoutParams());
        if (!homeGridMode()) rows.addView(space(continueWatchingHeroBottomSpacingDp()));
        wireHomeSectionVerticalDpad();
        wireHomeCategoryGridDpad(currentHomeCategoryGrid, rows);
        if (hadFocus) {
            View target = firstFocusableChild(rows);
            if (target == null) target = currentHomeCategoryGrid instanceof ViewGroup
                    ? firstFocusableChild((ViewGroup) currentHomeCategoryGrid) : currentHomeCategoryGrid;
            if (target == null && currentHomeHeaderView instanceof ViewGroup)
                target = firstFocusableChild((ViewGroup) currentHomeHeaderView);
            if (target != null && target.requestFocus()) rows.setFocusable(false);
        }
    }

    private void scheduleHomeReturnRefresh(boolean includeVideos, long delayMs) {
        homeReturnRefreshIncludesVideos |= includeVideos;
        homeReturnRefreshHandler.removeCallbacks(homeReturnRefreshRunnable);
        homeReturnRefreshHandler.postDelayed(homeReturnRefreshRunnable, Math.max(0L, delayMs));
    }

    private List<JojoProgram> cachedContinueWatchingHomePrograms() {
        ArrayList<JojoProgram> result = new ArrayList<>();
        try {
            // Cloud owns native, profile-scoped progress, not the histories of other apps.
            JSONArray cached = HomeWatchProgressBridge.isCloud(this) ? new JSONArray()
                    : new JSONArray(homePrefs().getString(CONTINUE_WATCHING_HOME_CACHE, "[]"));
            for (int index = 0; index < cached.length(); index++) {
                JSONObject item = cached.optJSONObject(index);
                if (item == null) continue;
                String title = item.optString("title", "");
                if (title.isEmpty()) continue;
                String source = item.optString("source", "");
                String intent = item.optString("intent", "");
                if (FILE_VIDEO_RESUME_SOURCE.equals(source) || "external-playback".equals(source)
                        || !SystemContinueWatching.sharedResumeProvider(source).isEmpty()) continue;
                long duration = item.optLong("duration", -1L);
                long position = item.optLong("position", -1L);
                String description = item.optString("description", "");
                String artwork = item.optString("artwork", "");
                String season = item.optString("season", "");
                String episode = item.optString("episode", "");
                boolean watched = item.optBoolean("watched", false);
                JojoProgram program = new JojoProgram(source, title, description, artwork, intent,
                        duration, position, season, episode, watched);
                String freeboxPath = freeboxResumePath(program);
                if (!freeboxPath.isEmpty() && hasDeletedFreeboxPath(freeboxPath)) continue;
                if (isResumeDismissed(program) || legacyHomeResume(program)) continue;
                addResumeProgramIfMissing(result, program);
            }
        } catch (Exception ignored) { }
        for (JojoProgram progressResume : watchProgressHomePrograms()) {
            if (!isResumeDismissed(progressResume)) addResumeProgramIfMissing(result, progressResume);
        }
        // SmartTube maintains its own local/NAS snapshot because some TV
        // firmwares do not expose its PreviewPrograms early enough during the
        // first Home frame. Reuse that snapshot immediately so the Hero does
        // not temporarily lose SmartTube resumes until the async provider
        // query completes.
        for (JojoProgram smartTubeResume : cachedSmartTubeResumePrograms()) {
            if (!isResumeDismissed(smartTubeResume) && !isFinishedExternalResume(smartTubeResume)) {
                addResumeProgramIfMissing(result, smartTubeResume);
            }
        }
        for (JojoProgram program : cachedSharedExternalResumePrograms(null)) {
            if (!isResumeDismissed(program)) addResumeProgramIfMissing(result, program);
        }
        return keepContinueWatchingInsertionOrder(mergeNetflixCloudResumes(result));
    }

    private void cacheContinueWatchingHomePrograms(List<JojoProgram> programs) {
        if (HomeWatchProgressBridge.isCloud(this)) return;
        try {
            JSONArray cached = new JSONArray();
            List<JojoProgram> unique = new ArrayList<>();
            if (programs != null) for (JojoProgram program : programs) addResumeProgramIfMissing(unique, program);
            for (JojoProgram program : unique) cached.put(new JSONObject().put("source", program.sourcePackage).put("title", program.title).put("description", program.description).put("artwork", program.artwork).put("intent", program.intentUri).put("duration", program.duration).put("position", program.position).put("season", program.seasonNumber).put("episode", program.episodeNumber).put("watched", program.watched));
            homePrefs().edit().putString(CONTINUE_WATCHING_HOME_CACHE, cached.toString()).apply();
        } catch (Exception ignored) { }
    }

    private void removeContinueWatchingHomeCacheEntry(String path) {
        if (path == null || path.isEmpty()) return;
        try {
            JSONArray cached = new JSONArray(homePrefs().getString(CONTINUE_WATCHING_HOME_CACHE, "[]"));
            JSONArray retained = new JSONArray();
            for (int index = 0; index < cached.length(); index++) {
                JSONObject item = cached.optJSONObject(index);
                if (item == null) continue;
                JojoProgram program = new JojoProgram(item.optString("source", ""), item.optString("title", ""), item.optString("description", ""), item.optString("artwork", ""), item.optString("intent", ""), item.optLong("duration", -1L), item.optLong("position", -1L));
                if (!comparableSmbPath(path).equals(comparableSmbPath(freeboxResumePath(program)))) retained.put(item);
            }
            homePrefs().edit().putString(CONTINUE_WATCHING_HOME_CACHE, retained.toString()).apply();
        } catch (Exception ignored) { }
    }

    private void restorePendingResumeFocus(ViewGroup resumes) {
        if (pendingResumeFocusKey == null || pendingResumeFocusKey.isEmpty()) return;
        if (activeScreen != null || resumes != currentHomeResumesView
                || (activePopup != null && activePopup.isShowing())) return;
        // IPTV Continue Watching rows are rendered in their own category
        // containers (live/movies/series), outside the generic resumes view.
        // Search those rows first so returning from an IPTV player restores the
        // exact card launched by the user instead of falling back to another
        // Home section.
        View externalTarget = findExternalPlaybackFocusTarget(pendingResumeFocusKey);
        if (externalTarget != null && externalTarget.isFocusable()) {
            pendingResumeFocusKey = null;
            requestHomeFocus(externalTarget, "resume-refresh-restore-iptv");
            return;
        }
        View current = getWindow().getDecorView().findFocus();
        if (current != null && !resumes.hasFocus() && !isSearchHeader(current)) {
            pendingResumeFocusKey = null;
            return;
        }
        View target = resumes.findViewWithTag(pendingResumeFocusKey);
        if (target == null || !target.isFocusable()) {
            pendingResumeFocusKey = null;
            View fallback = firstFocusableChild(resumes);
            if (fallback == null) fallback = firstFocusableChild(currentHomeAppsView);
            if (fallback == null) fallback = resolveHomeFocusTarget();
            requestHomeFocus(fallback, "resume-refresh-fallback");
            return;
        }
        pendingResumeFocusKey = null;
        requestHomeFocus(target, "resume-refresh-restore");
    }

    private View findExternalPlaybackFocusTarget(String focusKey) {
        if (focusKey == null || focusKey.isEmpty()) return null;
        for (LinearLayout rows : currentExternalRows.values()) {
            if (rows == null || !rows.isAttachedToWindow()) continue;
            View target = rows.findViewWithTag(focusKey);
            if (target != null && target.isShown() && target.isFocusable()) return target;
        }
        return null;
    }

    private String focusedTag(ViewGroup root) {
        if (root == null) return null;
        View focused = root.findFocus();
        Object tag = focused == null ? null : focused.getTag();
        return tag instanceof String && !((String) tag).isEmpty() ? (String) tag : null;
    }

    private boolean restorePlayerReturnFocus(View page, View episodeTarget) {
        if (page == null || pendingPlayerFocusScreen != page || activeScreen != page
                || !page.isAttachedToWindow() || activePopup != null) return false;
        View target = episodeTarget;
        if (target == null && playerReturnFocusKey != null) target = page.findViewWithTag(playerReturnFocusKey);
        if (target == null && playerReturnFocusKey != null
                && playerReturnFocusKey.startsWith(FILE_VIDEO_RESUME_SOURCE + "|"))
            target = findPlayerReturnFileThumbnail(page,
                    playerReturnFocusKey.substring(FILE_VIDEO_RESUME_SOURCE.length() + 1));
        if (target == null && playerReturnFocusView != null && isHomeDescendant(playerReturnFocusView, page)
                && (playerReturnFocusKey == null || !(playerReturnFocusView.getTag() instanceof String)
                || playerReturnFocusKey.equals(playerReturnFocusView.getTag()))) target = playerReturnFocusView;
        if (target == null || !target.isFocusable()) return false;
        final View thumbnail = target;
        thumbnail.post(() -> {
            if (pendingPlayerFocusScreen != page || activeScreen != page
                    || !thumbnail.isAttachedToWindow() || activePopup != null) return;
            if (thumbnail.requestFocus()) {
                // Reveal cards outside the viewport after the new rail has been laid out.
                thumbnail.requestRectangleOnScreen(new android.graphics.Rect(0, 0, thumbnail.getWidth(), thumbnail.getHeight()), true);
                pendingPlayerFocusScreen = null;
                playerReturnFocusView = null;
                playerReturnFocusKey = null;
            }
        });
        return true;
    }

    private View findPlayerReturnFileThumbnail(View root, String path) {
        Object item = root.getTag(MULTI_ITEM_TAG);
        if (item instanceof FileClipboard) {
            FileClipboard file = (FileClipboard) item;
            String candidate = file.local != null ? file.local.getAbsolutePath()
                    : file.smb != null ? file.smb.getPath() : file.shizukuPath == null ? "" : file.shizukuPath;
            if (path.equals(candidate) && root.isFocusable()) return root;
        }
        if (root instanceof ViewGroup) {
            ViewGroup group = (ViewGroup) root;
            for (int index = 0; index < group.getChildCount(); index++) {
                View match = findPlayerReturnFileThumbnail(group.getChildAt(index), path);
                if (match != null) return match;
            }
        }
        return null;
    }

    private void restoreFocusByTag(ViewGroup root, String tag) {
        if (root == null || tag == null || tag.isEmpty()) return;
        View target = root.findViewWithTag(tag);
        if (target != null && target.isFocusable()) target.post(target::requestFocus);
    }

    private boolean hasResumeContentBelow(View card) {
        if (card == null) return false;
        View parent = card.getParent() instanceof View ? (View) card.getParent() : null;
        while (parent != null && !(parent instanceof HorizontalScrollView)) {
            parent = parent.getParent() instanceof View ? (View) parent.getParent() : null;
        }
        if (!(parent instanceof HorizontalScrollView)) return false;
        View rail = parent;
        ViewGroup rows = rail.getParent() instanceof ViewGroup ? (ViewGroup) rail.getParent() : null;
        if (rows == null) return false;
        int railIndex = rows.indexOfChild(rail);
        if (railIndex < 0) return false;
        // Ignore the trailing spacer: only a real section/row below the focused
        // rail authorizes vertical movement on the Home page.
        for (int index = railIndex + 1; index < rows.getChildCount(); index++) {
            View following = rows.getChildAt(index);
            if (following.getVisibility() != View.GONE && following.getHeight() > dp(40)) return true;
        }
        return false;
    }

    /** Makes the focused resume card visible only when another content section is below it. */
    private void revealResumeCard(View card) {
        if (card == null || !hasResumeContentBelow(card)) return;
        if (isHomeDescendant(card, restoringNavigationPage)) return;
        View parent = card.getParent() instanceof View ? (View) card.getParent() : null;
        while (parent != null) {
            if (parent instanceof ScrollView && !(parent instanceof HorizontalScrollView)) {
                ScrollView scroll = (ScrollView) parent;
                // compute Y position of card relative to the ScrollView's content
                int top = 0;
                View v = card;
                while (v != null && v != scroll) {
                    top += v.getTop();
                    View p = v.getParent() instanceof View ? (View) v.getParent() : null;
                    v = p;
                }
                final int cardTop = top;
                final int cardBottom = top + card.getHeight();
                scroll.post(() -> {
                    // Do not move Home just because a resume card receives
                    // focus.  On the usual one-screen layout the whole card
                    // is already visible; scrolling it upward only hides the
                    // top bar for no benefit.
                    int visibleTop = scroll.getScrollY() + dp(12);
                    int visibleBottom = scroll.getScrollY() + scroll.getHeight() - dp(12);
                    if (cardTop >= visibleTop && cardBottom <= visibleBottom) return;
                    int targetY = cardTop < visibleTop
                            ? Math.max(0, cardTop - dp(12))
                            : Math.max(0, cardBottom - scroll.getHeight() + dp(12));
                    scroll.smoothScrollTo(0, targetY);
                });
                return;
            }
            parent = parent.getParent() instanceof View ? (View) parent.getParent() : null;
        }
    }
    private View jojoProgramsRow(List<JojoProgram> programs) {
        LinearLayout rows = new LinearLayout(this); rows.setOrientation(LinearLayout.VERTICAL); rows.setClipChildren(false); rows.setClipToPadding(false);
        int count = ContentPresentationRules.visibleCardCount(continueWatchingCardLimit(), programs.size());
        int rowCount = Math.min(homeSectionRows("resumes"), Math.max(1, count));
        int perRow = Math.max(1, (int) Math.ceil(count / (double) rowCount));
        for (int rowIndex = 0; rowIndex < rowCount; rowIndex++) {
            HorizontalScrollView scroll = new HorizontalScrollView(this); scroll.setHorizontalScrollBarEnabled(false); scroll.setClipChildren(false); scroll.setClipToPadding(false); scroll.setPadding(0, dp(6), 0, dp(6));
            LinearLayout row = new LinearLayout(this); row.setClipChildren(false); row.setClipToPadding(false);
            int start = rowIndex * perRow, end = Math.min(count, start + perRow);
            for (int index = start; index < end; index++) { JojoProgram program = programs.get(index); View tile = jojoProgramTile(program); if (rowIndex == 0 && index == 0) registerHomeRowMoveTrigger(tile, "resumes"); row.addView(tile, new LinearLayout.LayoutParams(dp(continueWatchingTileWidthDp()), dp(continueWatchingCardHeightDp())) {{ rightMargin = dp(18); }}); }
            scroll.addView(row); rows.addView(scroll, new LinearLayout.LayoutParams(-1, dp(continueWatchingRowHeightDp()))); wireHorizontalCardRowDpad(row);
        }
        wireResumeRowsDpad(rows); return rows;
    }
