    /** Keeps every Continue Watching row reachable with the TV remote's Up/Down keys. */
    private void wireResumeRowsDpad(ViewGroup resumes) {
        boolean suggestions = resumes.findViewWithTag("home_empty_suggestions") != null;
        List<List<View>> resumeRows = findHorizontalRowFocusableChildren(resumes);
        for (int rowIndex = 0; rowIndex < resumeRows.size(); rowIndex++) {
            List<View> row = resumeRows.get(rowIndex);
            if (!suggestions && !row.isEmpty() && row.get(0).getParent() instanceof ViewGroup) {
                ((ViewGroup) row.get(0).getParent()).setTag("continue_watching_row");
            }
            List<View> above = rowIndex > 0 ? resumeRows.get(rowIndex - 1) : null;
            List<View> below = rowIndex + 1 < resumeRows.size() ? resumeRows.get(rowIndex + 1) : null;
            if (!suggestions && !row.isEmpty()) wireContinueWatchingAutoScroll(row.get(0));
            for (int itemIndex = 0; itemIndex < row.size(); itemIndex++) {
                View item = row.get(itemIndex);
                if (item.getId() == View.NO_ID) item.setId(View.generateViewId());
                if (above != null && !above.isEmpty()) {
                    View target = alignedTarget(above, itemIndex);
                    if (target.getId() == View.NO_ID) target.setId(View.generateViewId());
                    item.setNextFocusUpId(target.getId());
                }
                if (below != null && !below.isEmpty()) {
                    View target = alignedTarget(below, itemIndex);
                    if (target.getId() == View.NO_ID) target.setId(View.generateViewId());
                    item.setNextFocusDownId(target.getId());
                }
            }
        }
    }
    private boolean isJojoPackage(String packageName) { return "com.jojo.tv".equals(packageName) || "com.jojo.tv.debug".equals(packageName); }
    private String appLabel(String packageName) { try { return getPackageManager().getApplicationLabel(getPackageManager().getApplicationInfo(packageName, 0)).toString(); } catch (Exception ignored) { return null; } }
    private String homeAppLabel(android.content.pm.ResolveInfo info) { String label = info.loadLabel(getPackageManager()).toString(); String normalized = label.trim().toLowerCase(Locale.ROOT); if (normalized.startsWith("canal+")) return "CANAL+"; if (normalized.startsWith("free tv")) return "Free TV"; return label; }
    private HorizontalScrollView previewRow(String packageName) {
        HorizontalScrollView scroll = new HorizontalScrollView(this); scroll.setHorizontalScrollBarEnabled(false); scroll.setClipChildren(false); LinearLayout row = new LinearLayout(this); row.setGravity(Gravity.CENTER_VERTICAL); row.setClipChildren(false); row.setPadding(dp(28), dp(8), dp(38), dp(8));
        TextView loading = text("Chargement du contenu…", 16, muted); loading.setGravity(Gravity.CENTER_VERTICAL); row.addView(loading, new LinearLayout.LayoutParams(dp(300), dp(130)));
        new Thread(() -> { List<JojoProgram> programs = findPreviewProgramsForPackage(packageName); runOnUiThread(() -> { row.removeAllViews(); if (programs.isEmpty()) { TextView empty = text("Aucun contenu publié par " + appLabel(packageName) + ".", 16, muted); empty.setGravity(Gravity.CENTER_VERTICAL); row.addView(empty, new LinearLayout.LayoutParams(dp(420), dp(130))); } else for (JojoProgram program : programs) row.addView(previewProgramTile(program, packageName), new LinearLayout.LayoutParams(dp(210), dp(140)) {{ rightMargin = dp(16); }}); }); }).start();
        scroll.addView(row); return scroll;
    }
    private View previewProgramTile(JojoProgram program, String packageName) {
        LinearLayout card = new LinearLayout(this); card.setOrientation(LinearLayout.VERTICAL); card.setFocusable(true); card.setTag(resumeProgramKey(program));
        card.setClipChildren(false);
        card.setClipToPadding(false);
        FrameLayout imageCard = new FrameLayout(this); imageCard.setClipChildren(true); imageCard.setClipToPadding(true); imageCard.setLayerType(View.LAYER_TYPE_HARDWARE, null); imageCard.setBackground(cardBg()); imageCard.setOutlineProvider(new ViewOutlineProvider() { @Override public void getOutline(View view, Outline outline) { outline.setRoundRect(0, 0, view.getWidth(), view.getHeight(), dp(12)); } }); imageCard.setClipToOutline(true);
        FrameLayout imageFrame = new FrameLayout(this); imageFrame.setClipChildren(true); imageFrame.setClipToPadding(true); imageFrame.setLayerType(View.LAYER_TYPE_HARDWARE, null); imageFrame.setBackground(cardBg()); imageFrame.setOutlineProvider(new ViewOutlineProvider() { @Override public void getOutline(View view, Outline outline) { outline.setRoundRect(0, 0, view.getWidth(), view.getHeight(), dp(12)); } }); imageFrame.setClipToOutline(true);
        ImageView image = new ImageView(this); image.setScaleType(ImageView.ScaleType.CENTER_CROP); image.setBackground(cardBg()); image.setAlpha(.72f);
        imageCard.addView(image, new FrameLayout.LayoutParams(-1, -1));
        if (isThumbnailInProgress(program)) addInProgressBadge(imageCard);
        View border = new View(this); border.setBackground(continueWatchingTileFocusBorder()); border.setAlpha(0f);
        imageFrame.addView(imageCard, new FrameLayout.LayoutParams(-1, -1) {{ setMargins(dp(2), dp(2), dp(2), dp(2)); }});
        imageFrame.addView(border, new FrameLayout.LayoutParams(-1, -1));
        card.addView(imageFrame, new LinearLayout.LayoutParams(-1, dp(116)));
        String displayedTitle = program.title == null ? appLabel(packageName) : program.title;
        if (FILE_VIDEO_RESUME_SOURCE.equals(program.sourcePackage)) displayedTitle = displayVideoTitle(displayedTitle);
        TextView title = resumeMarqueeText(displayedTitle, 13, muted);
        title.setPadding(0, dp(5), 0, 0);
        card.addView(title, new LinearLayout.LayoutParams(-1, dp(26)));
        card.setOnFocusChangeListener((v, focused) -> {
            title.setTextColor(focused ? white : muted);
            setMarqueeFocus(title, focused);
            // Keep artwork at native brightness in both focus states; the
            // border and slight scale already identify the selected tile.
            image.animate().alpha(1f).scaleX(focused ? 1.04f : 1f).scaleY(focused ? 1.04f : 1f).setDuration(120).start();
            border.animate().alpha(focused ? 1f : 0f).setDuration(120).start();
            if (focused) {
                // A newly focused tile may not have its artwork loaded yet.
                // Clear the previous tile first so its fullscreen image can
                // never remain visible behind the new selection.
                clearFocusedResumeArtwork();
                revealResumeCard(v);
                updateDynamicBackground(image);
            } else {
                v.post(this::hideFocusedResumeArtworkWhenLeavingRows);
            }
            continueWatchingTileFocusChanged(v, focused);
        });
        card.setOnClickListener(v -> {
            try {
                if (program.intentUri != null && !program.intentUri.isEmpty()) {
                    startActivity(Intent.parseUri(program.intentUri, Intent.URI_INTENT_SCHEME));
                } else if (isTiviMatePackage(packageName)) {
                    Intent direct = getPackageManager().getLaunchIntentForPackage(packageName);
                    if (direct != null) { direct.setAction(Intent.ACTION_VIEW); direct.putExtra("androidTvDirectPlay", true); startActivity(direct); }
                    else openPackage(packageName, appLabel(packageName));
                } else openPackage(packageName, appLabel(packageName));
            } catch (Exception ignored) { openPackage(packageName, appLabel(packageName)); }
        });
        card.setOnLongClickListener(v -> { showContinueWatchingMenu(program, card); return true; });
        card.setOnKeyListener((v, keyCode, event) -> {
            if (handleTaggedCyclicCardDpad(v, keyCode, event)) return true;
            if (handleContinueWatchingDpad(v, keyCode, event)) return true;
            if (handleHomeRowMoveKey(v, keyCode, event)) return true;
            if (event.getAction() == KeyEvent.ACTION_DOWN && event.getRepeatCount() == 0
                    && (keyCode == KeyEvent.KEYCODE_DPAD_UP || keyCode == KeyEvent.KEYCODE_DPAD_DOWN)) {
                int targetId = keyCode == KeyEvent.KEYCODE_DPAD_UP ? v.getNextFocusUpId() : v.getNextFocusDownId();
                View target = targetId == View.NO_ID ? null : v.getRootView().findViewById(targetId);
                if (target != null && target.isFocusable()) {
                    target.requestFocus();
                    return true;
                }
            }
            if (event.getAction() == KeyEvent.ACTION_DOWN && event.getRepeatCount() == 0
                    && (keyCode == KeyEvent.KEYCODE_DPAD_LEFT || keyCode == KeyEvent.KEYCODE_DPAD_RIGHT)) {
                // Android TV can ignore nextFocusLeftId at the edge of a
                // horizontally scrolling row. Request the already-wired
                // target explicitly so cyclic rows wrap in both directions.
                int targetId = keyCode == KeyEvent.KEYCODE_DPAD_LEFT
                        ? v.getNextFocusLeftId() : v.getNextFocusRightId();
                View target = targetId == View.NO_ID ? null : v.getRootView().findViewById(targetId);
                if (target != null && target.isFocusable()) {
                    target.requestFocus();
                    return true;
                }
            }
            return keepHorizontalFocus(v, keyCode, event);
        });
        if (program.artwork != null) loadArtwork(image, program.artwork);
        return card;
    }

    private static final class JojoProgram {
        final String sourcePackage, title, description, artwork, intentUri;
        // Enriched after the listing is visible, without recreating its focused tile.
        volatile long duration;
        final long position;
        final String seasonNumber, episodeNumber;
        final boolean watched;
        final VideoFrameSource videoFrameSource;
        JojoProgram(String title, String description, String artwork, String intentUri) { this(null, title, description, artwork, intentUri, -1L, -1L, null, null); }
        JojoProgram(String sourcePackage, String title, String description, String artwork, String intentUri) { this(sourcePackage, title, description, artwork, intentUri, -1L, -1L, null, null); }
        JojoProgram(String sourcePackage, String title, String description, String artwork, String intentUri, long duration, long position) { this(sourcePackage, title, description, artwork, intentUri, duration, position, null, null); }
        JojoProgram(String sourcePackage, String title, String description, String artwork, String intentUri, long duration, long position, VideoFrameSource videoFrameSource) { this(sourcePackage, title, description, artwork, intentUri, duration, position, null, null, false, videoFrameSource); }
        JojoProgram(String sourcePackage, String title, String description, String artwork, String intentUri, long duration, long position, String seasonNumber, String episodeNumber) { this(sourcePackage, title, description, artwork, intentUri, duration, position, seasonNumber, episodeNumber, false); }
        JojoProgram(String sourcePackage, String title, String description, String artwork, String intentUri, long duration, long position, String seasonNumber, String episodeNumber, boolean watched) { this(sourcePackage, title, description, artwork, intentUri, duration, position, seasonNumber, episodeNumber, watched, null); }
        JojoProgram(String sourcePackage, String title, String description, String artwork, String intentUri, long duration, long position, String seasonNumber, String episodeNumber, boolean watched, VideoFrameSource videoFrameSource) { this.sourcePackage = sourcePackage; this.title = title; this.description = description; this.artwork = artwork; this.intentUri = intentUri; this.duration = duration; this.position = position; this.seasonNumber = seasonNumber; this.episodeNumber = episodeNumber; this.watched = watched; this.videoFrameSource = videoFrameSource; }
    }

    private static final class PublishedResumeSnapshot {
        final boolean available;
        final List<JojoProgram> programs;
        PublishedResumeSnapshot(boolean available, List<JojoProgram> programs) {
            this.available = available;
            this.programs = programs;
        }
    }

    private PublishedResumeSnapshot readSystemContinueWatchingSnapshot() {
        if (!hasTvListingsAccess()) return new PublishedResumeSnapshot(false, Collections.emptyList());
        Set<String> selected = contentApps();
        String[] projection = { "package_name", "title", "short_description", "thumbnail_uri", "poster_art_uri", "intent_uri", "duration_millis", "last_playback_position_millis", "season_display_number", "episode_display_number", "last_engagement_time_utc_millis" };
        ArrayList<SystemContinueWatching.Item> published = new ArrayList<>();
        long now = System.currentTimeMillis();
        try (Cursor programs = getContentResolver().query(TvContract.WatchNextPrograms.CONTENT_URI, projection, null, null, "last_engagement_time_utc_millis DESC")) {
            if (programs == null) return new PublishedResumeSnapshot(false, Collections.emptyList());
            while (programs.moveToNext()) {
                if (!WatchNextRules.isFreshResume(programs.getLong(10), now)) continue;
                // L'affiche est conçue pour la carte du launcher ; la miniature de lecture
                // peut être une image étroite avec un fond vide sur le reste de la carte.
                String artwork = programs.getString(3); if (SystemContinueWatching.isBlank(artwork)) artwork = programs.getString(4);
                published.add(new SystemContinueWatching.Item(programs.getString(0), programs.getString(1), programs.getString(2), artwork, programs.getString(5), programs.getLong(6), programs.getLong(7), programs.getString(8), programs.getString(9)));
            }
        } catch (Exception ignored) {
            // Some TV providers (notably Netflix builds) reject the optional
            // season/episode columns. Retry with the Android TV core columns
            // instead of dropping the provider's entire Watch Next rail.
            published.clear();
            try {
                String[] fallbackProjection = { "package_name", "title", "short_description", "thumbnail_uri", "poster_art_uri", "intent_uri", "duration_millis", "last_playback_position_millis", "last_engagement_time_utc_millis" };
                try (Cursor programs = getContentResolver().query(TvContract.WatchNextPrograms.CONTENT_URI, fallbackProjection, null, null, "last_engagement_time_utc_millis DESC")) {
                    if (programs == null) return new PublishedResumeSnapshot(false, Collections.emptyList());
                    while (programs.moveToNext()) {
                        if (!WatchNextRules.isFreshResume(programs.getLong(8), now)) continue;
                        String artwork = programs.getString(3); if (SystemContinueWatching.isBlank(artwork)) artwork = programs.getString(4);
                        published.add(new SystemContinueWatching.Item(programs.getString(0), programs.getString(1), programs.getString(2), artwork, programs.getString(5), programs.getLong(6), programs.getLong(7), null, null));
                    }
                }
            } catch (Exception ignoredAgain) { return new PublishedResumeSnapshot(false, Collections.emptyList()); }
        }
        ArrayList<JojoProgram> result = new ArrayList<>();
        for (SystemContinueWatching.Item item : SystemContinueWatching.resumableItems(published)) {
            // Watch Next is shared by every Android TV application.  Keeping
            // every provider here filled the rail with unrelated suggestions
            // and could push Netflix/Canal resumes beyond its visible limit.
            if (getPackageName().equals(item.sourcePackage)
                    || !acceptsResumeSource(selected, item.sourcePackage)) continue;
            // The provider itself publishes the resume duration.  A short
            // item can be a genuine episode/clip in progress (for example
            // Canal+'s "Le Club"), so do not infer recommendations from its
            // length. The only reliable rule is an actual, unfinished
            // playback position.
            // Providers can publish the resume card before timing columns are
            // available. Keep the card; the progress bar appears once timing
            // arrives from Watch Next or the notification listener.
            if (item.duration > 0L && item.position >= item.duration) continue;
            result.add(new JojoProgram(item.sourcePackage, item.title, item.description, item.artwork, item.intentUri, item.duration, item.position, item.seasonNumber, item.episodeNumber));
        }
        return new PublishedResumeSnapshot(true, result);
    }

    /** Applies the selected-app policy consistently to provider and playback sources. */
    private boolean acceptsResumeSource(Set<String> selectedPackages, String packageName) {
        if (packageName == null) return false;
        if (isTiviMatePackage(packageName)) return true;
        return NotificationResumeRules.acceptsPackage(selectedPackages, packageName);
    }

    private List<JojoProgram> findNotificationResumePrograms() {
        ArrayList<JojoProgram> result = new ArrayList<>();
        Set<String> selected = contentApps();
        LinkedHashMap<String, JojoProgram> merged = new LinkedHashMap<>();
        long now = System.currentTimeMillis();
        try {
            JSONArray items = new JSONArray(homePrefs().getString(NotificationResumeListenerService.ITEMS_KEY, "[]"));
            for (int index = 0; index < items.length(); index++) {
                JSONObject item = items.optJSONObject(index); if (item == null) continue;
                String packageName = item.optString("package", "");
                String title = item.optString("title", "");
                String normalizedPackage = packageName.toLowerCase(Locale.ROOT);
                if (!acceptsResumeSource(selected, packageName) || title.isEmpty()
                        || getPackageName().equals(packageName) || isJojoPackage(packageName)
                        || !NotificationResumeRules.isFresh(item.optLong("updatedAt", 0L), now)) continue;
                if (normalizedPackage.contains("smarttube")
                        && !item.optBoolean("playbackCaptured", false)
                        && item.optLong("position", -1L) <= 0L
                        && item.optLong("duration", -1L) <= 0L) continue;
                String intent = item.optString("intent", "");
                String netflixProfile = item.optString("netflixProfile", "");
                if (!netflixProfile.isEmpty() && !intent.isEmpty()) {
                    try { intent = Intent.parseUri(intent, Intent.URI_INTENT_SCHEME)
                            .putExtra("jojoHomeNetflixProfile", netflixProfile).toUri(Intent.URI_INTENT_SCHEME); }
                    catch (java.net.URISyntaxException ignored) { }
                }
                merged.put(NotificationResumeRules.resumeKey(packageName, title, netflixProfile), new JojoProgram(packageName, title, item.optString("description", ""), NotificationResumeRules.retainedArtworkUri(packageName, item.optString("artwork", "")), intent, item.optLong("duration", -1L), item.optLong("position", -1L)));
            }
        } catch (Exception ignored) { }
        try {
            MediaSessionManager manager = (MediaSessionManager) getSystemService(MEDIA_SESSION_SERVICE);
            if (manager != null) {
                List<android.media.session.MediaController> sessions = null;
                try {
                    sessions = manager.getActiveSessions(new ComponentName(this, NotificationResumeListenerService.class));
                } catch (Exception ignored) {
                }
                if (sessions == null || sessions.isEmpty()) {
                    try {
                        sessions = manager.getActiveSessions(null);
                    } catch (Exception ignored) {
                        sessions = Collections.emptyList();
                    }
                }
                if (sessions != null) for (android.media.session.MediaController controller : sessions) {
                    String packageName = controller.getPackageName();
                    if (!acceptsResumeSource(selected, packageName)
                            || getPackageName().equals(packageName) || isJojoPackage(packageName)) continue;
                    MediaMetadata metadata = controller.getMetadata();
                    if (metadata == null) continue;
                    String title = NotificationResumeListenerService.mediaContentTitle(this, packageName, metadata);
                    if (title == null || title.trim().isEmpty()) continue;
                    String description = firstMediaText(metadata, MediaMetadata.METADATA_KEY_DISPLAY_SUBTITLE, MediaMetadata.METADATA_KEY_ARTIST);
                    String artwork = mediaArtworkUri(packageName, title, metadata);
                    PlaybackState playback = controller.getPlaybackState();
                    String key = NotificationResumeRules.resumeKey(packageName, title);
                    JojoProgram previous = merged.get(key);
                    String playbackIntent = NotificationResumeListenerService.mediaPlaybackIntentUri(packageName, metadata);
                    if (previous != null && NotificationResumeRules.playbackVideoChanged(
                            packageName, previous.intentUri, playbackIntent)) previous = null;
                    long reportedDuration = metadata.getLong(MediaMetadata.METADATA_KEY_DURATION);
                    if (previous != null && NotificationResumeRules.isTizenTubePackage(packageName)
                            && reportedDuration > 0L && description != null && !description.trim().isEmpty()
                            && !NotificationResumeRules.matchesYoutubeVideo(title, description, reportedDuration,
                                previous.title, previous.description, previous.duration)) previous = null;
                    long duration = reportedDuration > 0L ? reportedDuration : previous == null ? -1L : previous.duration;
                    long position = NotificationResumeRules.playbackPosition(packageName, duration,
                            playback == null ? -1L : playback.getPosition(), previous == null ? -1L : previous.position,
                            NotificationResumeListenerService.isPlaybackActive(playback));
                    String intent = previous == null ? "" : previous.intentUri;
                    if (playbackIntent != null) intent = playbackIntent;
                    if (previous != null) {
                        if (SystemContinueWatching.isBlank(description)) description = previous.description;
                        if (SystemContinueWatching.isBlank(artwork)
                                || (NotificationResumeRules.isTizenTubePackage(packageName)
                                    && !SystemContinueWatching.isBlank(previous.intentUri)
                                    && !SystemContinueWatching.isBlank(previous.artwork))) artwork = previous.artwork;
                    }
                    merged.put(key, new JojoProgram(packageName, title, description == null ? "" : description, artwork == null ? "" : artwork, intent, duration, position));
                }
            }
        } catch (Exception ignored) { }
        result.addAll(merged.values());
        return result;
    }

    private String netflixNativeProfile(JojoProgram program) {
        if (program == null || !"netflix".equals(SystemContinueWatching.sharedResumeProvider(program.sourcePackage))) return "";
        try {
            String value = Intent.parseUri(program.intentUri, Intent.URI_INTENT_SCHEME).getStringExtra("jojoHomeNetflixProfile");
            return value == null ? "" : value;
        } catch (Exception ignored) { return ""; }
    }

    private List<JojoProgram> mergeNetflixCloudResumes(List<JojoProgram> local, String packageName) {
        Map<String, List<JojoProgram>> published = new LinkedHashMap<>();
        try {
            JSONArray shared = new JSONArray(com.jojotv.home.progresspilot.AccountSettingsRouting.netflixSnapshot(this));
            for (int index = 0; index < shared.length(); index++) {
                JSONObject snapshot = shared.getJSONObject(index);
                String profile = snapshot.getString("profile");
                JSONArray cards = snapshot.getJSONArray("cards");
                if (profile.isEmpty() || cards.length() == 0) continue;
                // The newer published list replaces this profile's old episode IDs as a unit.
                // Legacy cards have no Netflix profile: do not blend their stale episode into
                // an identified shared list or label them as another person's playback.
                List<JojoProgram> result = new ArrayList<>();
                for (int cardIndex = 0; cardIndex < cards.length(); cardIndex++) {
                    JSONObject item = cards.getJSONObject(cardIndex);
                    String content = item.getString("content");
                    if (!content.matches("[1-9][0-9]{0,19}")) continue;
                    Intent intent = new Intent(Intent.ACTION_VIEW, Uri.parse("https://www.netflix.com/watch/" + content))
                            .setPackage(packageName).putExtra("jojoHomeNetflixProfile", profile)
                            .putExtra("jojoHomeSharedResumeKey", SystemContinueWatching.netflixProfileContentKey(snapshot.getString("key"), content))
                            .putExtra("jojoHomeLegacyNetflixResumeKey", SHARED_EXTERNAL_RESUME_PREFIX + SystemContinueWatching.sharedResumeKey(
                                    packageName, item.getString("title"), item.getString("description"),
                                    "https://www.netflix.com/watch/" + content, item.getString("season"), item.getString("episode")));
                    result.add(new JojoProgram(packageName, item.getString("title"), item.getString("description"), "",
                            intent.toUri(Intent.URI_INTENT_SCHEME), item.getLong("duration"), item.getLong("position"),
                            item.getString("season"), item.getString("episode")));
                }
                if (!result.isEmpty()) published.put(profile, result);
            }
        } catch (Exception error) { android.util.Log.w("HomeNetflixResumes", "Netflix view unavailable: " + error.getClass().getSimpleName()); }
        return SystemContinueWatching.replaceNetflixProfileResumes(local, published,
                program -> program.sourcePackage, this::netflixNativeProfile);
    }

    private String selectedSharedResumePackage(String provider, List<JojoProgram> programs) {
        Set<String> selected = contentApps();
        LinkedHashSet<String> candidates = new LinkedHashSet<>();
        candidates.add(homePrefs().getString("nas_external_package_" + provider, ""));
        for (JojoProgram program : programs) if (program != null) candidates.add(program.sourcePackage);
        candidates.addAll(selected);
        for (String source : candidates) {
            if (provider.equals(SystemContinueWatching.sharedResumeProvider(source))
                    && acceptsResumeSource(selected, source) && isPackageInstalled(source)) return source;
        }
        return "";
    }

    /** Apply the identified list last: neither a first-frame cache nor the final merge may restore old episodes. */
    private List<JojoProgram> mergeNetflixCloudResumes(List<JojoProgram> programs) {
        if ("[]".equals(com.jojotv.home.progresspilot.AccountSettingsRouting.netflixSnapshot(this))) return programs;
        String source = selectedSharedResumePackage("netflix", programs);
        return source.isEmpty() ? programs : mergeNetflixCloudResumes(programs, source);
    }

    private String sharedExternalResumeKey(JojoProgram program) {
        if (program == null || SystemContinueWatching.sharedResumeProvider(program.sourcePackage).isEmpty()) return "";
        String reference = "";
        try {
            Intent intent = Intent.parseUri(program.intentUri, Intent.URI_INTENT_SCHEME);
            String savedKey = intent.getStringExtra("jojoHomeSharedResumeKey");
            if (savedKey != null && !savedKey.isEmpty()) return savedKey;
            reference = intent.getDataString();
            if (SystemContinueWatching.isBlank(reference)) {
                for (String name : new String[] {"episodeId", "episode_id", "contentId", "movieid", "movieId", "videoId", "programId"}) {
                    Object value = intent.getExtras() == null ? null : intent.getExtras().get(name);
                    if (value != null) {
                        reference = SystemContinueWatching.sharedResumeProvider(program.sourcePackage) + ":" + value;
                        break;
                    }
                }
            }
        } catch (Exception ignored) { }
        String key = SystemContinueWatching.sharedResumeKey(program.sourcePackage, program.title, program.description,
                reference, program.seasonNumber, program.episodeNumber);
        String redirect = sharedExternalResume(key).optString("redirect", "");
        if (!redirect.isEmpty() && NotificationResumeRules.isTizenTubePackage(program.sourcePackage)) {
            JSONObject resolved = sharedExternalResume(redirect);
            // A reused title/channel with another duration needs a new exact video ID.
            if (program.duration > 0L && resolved.optLong("duration", -1L) > 0L
                    && !NotificationResumeRules.matchesYoutubeVideo(program.title, program.description, program.duration,
                        resolved.optString("title", ""), resolved.optString("description", ""), resolved.optLong("duration", -1L))) return "";
        }
        return redirect.isEmpty() ? key : redirect;
    }

    private JSONObject sharedExternalResume(String key) {
        try { return new JSONObject(homePrefs().getString(SHARED_EXTERNAL_RESUME_PREFIX + key, "{}")); }
        catch (org.json.JSONException ignored) { return new JSONObject(); }
    }

    /** Cache provider-private images on the worker; only portable URLs/assets go to the NAS. */
    private String portableSharedExternalArtwork(JojoProgram program, String key) {
        String artwork = program.artwork == null ? "" : program.artwork;
        if (artwork.startsWith("http://") || artwork.startsWith("https://")) return artwork;
        if (isPersistedVideoFrameArtwork(storedFile(artwork))) return artwork;
        if (!artwork.startsWith("content://")) return "";
        String cached = homePrefs().getString("nas_external_image_" + key, "");
        String source = homePrefs().getString("nas_external_image_source_" + key, "");
        if (artwork.equals(source) && isPersistedVideoFrameArtwork(storedFile(cached))) return cached;
        try (java.io.InputStream input = getContentResolver().openInputStream(Uri.parse(artwork))) {
            Bitmap bitmap = BitmapFactory.decodeStream(input);
            if (bitmap == null) return "";
            cached = NotificationResumeListenerService.saveBitmap(this, program.sourcePackage, program.title, bitmap);
            if (cached == null) return "";
            homePrefs().edit().putString("nas_external_image_" + key, cached)
                    .putString("nas_external_image_source_" + key, artwork).apply();
            return cached;
        } catch (Exception ignored) { return ""; }
    }

    private void observeSharedExternalResume(JojoProgram program, String observationSource) {
        if (program == null || SystemContinueWatching.isBlank(program.title) || homeResumeSettingsPending) return;
        String key = sharedExternalResumeKey(program);
        if (key.isEmpty()) return;
        int percent = -1;
        try { percent = Intent.parseUri(program.intentUri, Intent.URI_INTENT_SCHEME)
                .getIntExtra("jojoHomeObservedPercent", -1); } catch (Exception ignored) { }
        String artwork = portableSharedExternalArtwork(program, key);
        synchronized (sharedExternalResumeLock) {
            if (homeResumeSettingsPending) return;
            try {
                JSONObject previous = sharedExternalResume(key);
                String fallbackKey = SystemContinueWatching.sharedResumeKey(program.sourcePackage, program.title,
                        program.description, "", program.seasonNumber, program.episodeNumber);
                JSONObject fallback = key.equals(fallbackKey) ? new JSONObject() : sharedExternalResume(fallbackKey);
                boolean linkedFallback = fallback.length() > 0 && !fallback.has("redirect")
                        && (!NotificationResumeRules.isTizenTubePackage(program.sourcePackage)
                            || fallback.optLong("duration", -1L) <= 0L
                            || NotificationResumeRules.matchesYoutubeVideo(program.title, program.description, program.duration,
                                fallback.optString("title", ""), fallback.optString("description", ""), fallback.optLong("duration", -1L)));
                boolean migrated = previous.length() == 0 && linkedFallback;
                if (migrated) previous = fallback;
                String baselineKey = "nas_external_observation_" + observationSource + "_" + key;
                String baselineValue = homePrefs().getString(baselineKey, linkedFallback
                        ? homePrefs().getString("nas_external_observation_" + observationSource + "_" + fallbackKey, "{}") : "{}");
                JSONObject baseline = new JSONObject(baselineValue);
                // Old baselines contained timing only. Seed their content from our own
                // last saved observation, never from another device's newer NAS state.
                JSONObject contentBaseline = baseline.optBoolean("contentCaptured", false) ? baseline
                        : jojoHomeDeviceId().equals(previous.optString("writer", "")) ? previous : new JSONObject();
                boolean episodeChanged = SystemContinueWatching.sharedResumeEpisodeChanged(baseline.length() > 0,
                        new SystemContinueWatching.Item(program.sourcePackage, contentBaseline.optString("title", ""),
                                contentBaseline.optString("description", ""), "", "", -1L, -1L,
                                contentBaseline.optString("season", ""), contentBaseline.optString("episode", "")),
                        new SystemContinueWatching.Item(program.sourcePackage, program.title, program.description,
                                "", "", program.duration, program.position, program.seasonNumber, program.episodeNumber));
                boolean newPlayback = SystemContinueWatching.sharedResumeProgressChanged(baseline.length() > 0,
                        baseline.optLong("position", -1L), program.position,
                        baseline.optInt("percent", -1), percent,
                        previous.optLong("position", -1L), previous.optInt("percent", -1)) || episodeChanged;
                boolean completed = isFinishedExternalResume(program) || percent >= 100;
                android.content.SharedPreferences.Editor editor = homePrefs().edit().putString(baselineKey,
                        new JSONObject().put("position", program.position).put("percent", percent)
                                .put("contentCaptured", true).put("title", program.title).put("description", program.description)
                                .put("season", program.seasonNumber).put("episode", program.episodeNumber)
                                .put("artwork", program.artwork == null ? "" : program.artwork).toString());
                // An unchanged native row cannot restore a remote deletion or stale progress.
                boolean fallbackRemoved = linkedFallback && fallback.optBoolean("deleted")
                        && ExternalPlaybackStore.compareRevisions(fallback.optLong("updatedAt", 0L), fallback.optString("writer", ""),
                            previous.optLong("updatedAt", 0L), previous.optString("writer", "")) >= 0;
                boolean providerRemoved = previous.optBoolean("providerRemoved")
                        || (fallbackRemoved && fallback.optBoolean("providerRemoved"));
                if (!SystemContinueWatching.mayRestoreSharedResume(previous.optBoolean("deleted") || fallbackRemoved,
                        providerRemoved, newPlayback, observationSource)) {
                    if (linkedFallback) {
                        long now = Math.max(System.currentTimeMillis(), Math.max(previous.optLong("updatedAt", 0L),
                                fallback.optLong("updatedAt", 0L)) + 1L);
                        JSONObject removed = new JSONObject(previous.toString())
                                .put("deleted", true).put("updatedAt", now).put("writer", jojoHomeDeviceId());
                        if (providerRemoved) removed.put("providerRemoved", true);
                        editor.putString(SHARED_EXTERNAL_RESUME_PREFIX + key, removed.toString());
                        editor.putString(SHARED_EXTERNAL_RESUME_PREFIX + fallbackKey, new JSONObject(fallback.toString())
                                .put("redirect", key).put("deleted", true).put("updatedAt", now).put("writer", jojoHomeDeviceId()).toString());
                    }
                    editor.apply(); return;
                }
                boolean first = previous.length() == 0;
                if (newPlayback && !completed) clearResumeDismissal(program);
                JSONObject item = new JSONObject(previous.toString());
                item.put("provider", SystemContinueWatching.sharedResumeProvider(program.sourcePackage));
                boolean timingOnly = !episodeChanged && "netflix".equals(item.optString("provider", ""))
                        && (!SystemContinueWatching.isBlank(previous.optString("season", ""))
                            || !SystemContinueWatching.isBlank(previous.optString("episode", "")))
                        && SystemContinueWatching.isBlank(program.seasonNumber) && SystemContinueWatching.isBlank(program.episodeNumber);
                // A progress-only session cannot erase the episode supplied by Watch Next/Preview.
                if (first || (newPlayback && !timingOnly) || migrated) {
                    item.put("source", program.sourcePackage).put("title", program.title)
                            .put("description", program.description).put("intent", program.intentUri)
                            .put("season", program.seasonNumber).put("episode", program.episodeNumber);
                } else if (item.optString("intent", "").isEmpty() && !SystemContinueWatching.isBlank(program.intentUri)) {
                    item.put("intent", program.intentUri);
                }
                item.put("duration", SystemContinueWatching.sharedResumeTiming(episodeChanged ? -1L : previous.optLong("duration", -1L), program.duration, newPlayback))
                        .put("position", SystemContinueWatching.sharedResumeTiming(episodeChanged ? -1L : previous.optLong("position", -1L), program.position, newPlayback));
                if (first || newPlayback) {
                    item.put("percent", percent).put("deleted", completed || (first && isResumeDismissed(program)));
                    item.remove("providerRemoved");
                }
                boolean changedImage = baseline.length() > 0
                        && !baseline.optString("artwork", "").equals(program.artwork == null ? "" : program.artwork);
                if (!artwork.isEmpty() && (first || newPlayback || changedImage
                        || (item.optString("artwork", "").isEmpty() && item.optString("artworkKey", "").isEmpty()))) {
                    if (artwork.startsWith("file://")) {
                        String artworkKey = SHARED_EXTERNAL_ARTWORK_PREFIX + key;
                        item.remove("artwork"); item.put("artworkKey", artworkKey);
                        editor.putString(artworkKey, artwork);
                    } else { item.remove("artworkKey"); item.put("artwork", artwork); }
                }
                if (!item.toString().equals(previous.toString()) || linkedFallback) {
                    long now = Math.max(System.currentTimeMillis(), Math.max(previous.optLong("updatedAt", 0L),
                            fallback.optLong("updatedAt", 0L)) + 1L);
                    item.put("updatedAt", now).put("writer", jojoHomeDeviceId());
                    editor.putString(SHARED_EXTERNAL_RESUME_PREFIX + key, item.toString());
                    if (linkedFallback) editor.putString(SHARED_EXTERNAL_RESUME_PREFIX + fallbackKey,
                            new JSONObject(fallback.toString()).put("redirect", key).put("deleted", true)
                                    .put("updatedAt", now).put("writer", jojoHomeDeviceId()).toString());
                }
                editor.apply();
            } catch (org.json.JSONException error) {
                android.util.Log.w("JojoHomeSync", "Cannot remember external resume", error);
            }
        }
    }

    private void reconcileNetflixResumeSnapshot(List<JojoProgram> published,
                                                boolean watchNextAvailable, boolean previewAvailable) {
        if (!watchNextAvailable || !previewAvailable || homeResumeSettingsPending) return;
        synchronized (sharedExternalResumeLock) {
            if (homeResumeSettingsPending) return;
            Set<String> current = new HashSet<>();
            for (JojoProgram program : published) {
                if (program == null || !"netflix".equals(SystemContinueWatching.sharedResumeProvider(program.sourcePackage))) continue;
                String key = sharedExternalResumeKey(program);
                if (!key.isEmpty()) current.add(key);
            }
            Set<String> previous = new HashSet<>(homePrefs().getStringSet(NETFLIX_PUBLISHED_RESUME_KEYS, Collections.emptySet()));
            if (!homePrefs().contains(NETFLIX_PUBLISHED_RESUME_KEYS)) {
                // Migrate only locally observed native rows, never NAS-only or notification-only history.
                for (String setting : homePrefs().getAll().keySet()) {
                    if (!setting.startsWith("nas_external_observation_watch-next_")
                            && !setting.startsWith("nas_external_observation_preview-")) continue;
                    int keyStart = setting.lastIndexOf("_netflix_");
                    if (keyStart < 0) continue;
                    String key = setting.substring(keyStart + 1);
                    String redirect = sharedExternalResume(key).optString("redirect", "");
                    previous.add(redirect.isEmpty() ? key : redirect);
                }
            }
            for (String key : SystemContinueWatching.removedNetflixResumeKeys(previous, current, watchNextAvailable, previewAvailable)) {
                JSONObject item = sharedExternalResume(key);
                if ("netflix".equals(item.optString("provider", "")) && !item.optBoolean("deleted") && !item.has("redirect"))
                    deleteSharedExternalResume(key, true);
            }
            if (!previous.equals(current) || !homePrefs().contains(NETFLIX_PUBLISHED_RESUME_KEYS))
                homePrefs().edit().putStringSet(NETFLIX_PUBLISHED_RESUME_KEYS, current).apply();
        }
    }

    private List<JojoProgram> cachedSharedExternalResumePrograms(String requestedPackage) {
        ArrayList<JojoProgram> result = new ArrayList<>();
        Set<String> selected = contentApps();
        for (Map.Entry<String, ?> entry : homePrefs().getAll().entrySet()) {
            if (!entry.getKey().startsWith(SHARED_EXTERNAL_RESUME_PREFIX) || !(entry.getValue() instanceof String)) continue;
            try {
                JSONObject item = new JSONObject((String) entry.getValue());
                String provider = item.optString("provider", "");
                String source = requestedPackage == null
                        ? homePrefs().getString("nas_external_package_" + provider, item.optString("source", "")) : requestedPackage;
                boolean replayed = Boolean.FALSE.equals(com.jojotv.home.progresspilot.AccountSettingsRouting.resumeDismissal(
                        this, HomeWatchProgressBridge.currentProfileId(this), entry.getKey()));
                if (item.optBoolean("deleted") && !replayed || item.has("redirect") || source.isEmpty()
                        || !provider.equals(SystemContinueWatching.sharedResumeProvider(source))
                        || !acceptsResumeSource(selected, source)) continue;
                String savedIntent = item.optString("intent", "");
                Intent intent = savedIntent.isEmpty() ? new Intent()
                        : Intent.parseUri(savedIntent, Intent.URI_INTENT_SCHEME);
                ComponentName component = intent.getComponent();
                if (component != null && !source.equals(component.getPackageName())) {
                    intent.setComponent(intent.getData() != null ? null : new ComponentName(source, component.getClassName()));
                }
                intent.setPackage(source).putExtra("jojoHomeSharedResumeKey",
                        entry.getKey().substring(SHARED_EXTERNAL_RESUME_PREFIX.length()));
                String art = item.optString("artwork", "");
                String artworkKey = item.optString("artworkKey", "");
                if (!artworkKey.isEmpty()) {
                    String value = homePrefs().getString(artworkKey, "");
                    art = localArtworkSettingValue(artworkKey, value);
                    if (art.startsWith("jojo-home-asset:")) art = "";
                }
                JojoProgram program = new JojoProgram(source, item.optString("title", ""), item.optString("description", ""),
                        art, intent.toUri(Intent.URI_INTENT_SCHEME), item.optLong("duration", -1L),
                        item.optLong("position", -1L), item.optString("season", ""), item.optString("episode", ""));
                if (!isFinishedExternalResume(program)) result.add(program);
            } catch (Exception ignored) { }
        }
        return result;
    }

    private void deleteSharedExternalResume(JojoProgram program) {
        deleteSharedExternalResume(sharedExternalResumeKey(program), false);
    }

    private void deleteSharedExternalResume(String key, boolean providerRemoved) {
        if (key.isEmpty()) return;
        synchronized (sharedExternalResumeLock) {
            try {
                JSONObject item = sharedExternalResume(key);
                item.put("deleted", true).put("updatedAt", Math.max(System.currentTimeMillis(), item.optLong("updatedAt", 0L) + 1L))
                        .put("writer", jojoHomeDeviceId());
                if (providerRemoved) item.put("providerRemoved", true);
                homePrefs().edit().putString(SHARED_EXTERNAL_RESUME_PREFIX + key, item.toString()).apply();
            } catch (org.json.JSONException ignored) { }
        }
    }

    private String sharedNotificationSnapshot(String value, boolean retainLocal) {
        try {
            JSONArray result = new JSONArray();
            JSONArray incoming = new JSONArray(value);
            for (int index = 0; index < incoming.length(); index++) {
                JSONObject item = incoming.optJSONObject(index);
                if (item != null && SystemContinueWatching.sharedResumeProvider(item.optString("package", "")).isEmpty()) result.put(item);
            }
            if (retainLocal) {
                JSONArray local = new JSONArray(homePrefs().getString(NotificationResumeListenerService.ITEMS_KEY, "[]"));
                for (int index = 0; index < local.length(); index++) {
                    JSONObject item = local.optJSONObject(index);
                    if (item != null && !SystemContinueWatching.sharedResumeProvider(item.optString("package", "")).isEmpty()) result.put(item);
                }
            }
            return result.toString();
        } catch (org.json.JSONException ignored) {
            return retainLocal ? homePrefs().getString(NotificationResumeListenerService.ITEMS_KEY, "[]") : "[]";
        }
    }

    /** Revisions live with each content record, even before preference callbacks run on UI. */
    private void versionSharedExternalResumes(JSONObject values, boolean preserveNewer) throws org.json.JSONException {
        for (Map.Entry<String, ?> entry : homePrefs().getAll().entrySet()) {
            String key = entry.getKey();
            if (!key.startsWith(SHARED_EXTERNAL_RESUME_PREFIX) || !(entry.getValue() instanceof String)) continue;
            JSONObject item = new JSONObject((String) entry.getValue());
            JSONObject incoming = values.optJSONObject(key);
            long at = item.optLong("updatedAt", 0L);
            String writer = item.optString("writer", "");
            if (preserveNewer && incoming != null && ExternalPlaybackStore.compareRevisions(at, writer,
                    incoming.optLong("changedAt", 0L), incoming.optString("writer", "")) <= 0) continue;
            values.put(key, new JSONObject().put("type", "string").put("value", entry.getValue())
                    .put("changedAt", at).put("writer", writer));
            String artworkKey = item.optString("artworkKey", "");
            if (!artworkKey.isEmpty() && homePrefs().contains(artworkKey)) {
                String art = homePrefs().getString(artworkKey, "");
                if (isPersistedVideoFrameArtwork(storedFile(art))) art = homeArtworkAssetReference(artworkKey, storedFile(art));
                values.put(artworkKey, new JSONObject().put("type", "string").put("value", art)
                        .put("changedAt", at).put("writer", writer));
            }
        }
    }

    private List<JojoProgram> findJojoPrograms() {
        // NAS is the cross-device source of truth. The local bridge is only a
        // low-latency overlay for the active TV; it must never hide resumes from
        // another profile/device and an available-but-empty bridge must never
        // suppress a valid NAS snapshot.
        String nasToken = homePrefs().getString("nas_token", "");
        android.util.Log.i("JojoHomeResume", "findJojoPrograms nas=" + (!nasToken.isEmpty()) + " fireOs=" + isFireOsDevice());
        List<JojoProgram> fromNas = findJojoProgramsFromNas();
        JojoBridgeResponse bridge = findJojoProgramsFromBridge("content://com.jojo.tv.homebridge/continue_watching");
        if (!bridge.available) bridge = findJojoProgramsFromBridge("content://com.jojo.tv.debug.homebridge/continue_watching");
        // The NAS remains authoritative across devices, but the local bridge is
        // the fastest deletion signal for the active profile. Replace that one
        // profile in the cached NAS snapshot instead of merging it: a valid empty
        // bridge response must remove stale cards immediately, while profiles
        // belonging to the other TVs remain untouched.
        if (!nasToken.isEmpty()) {
            android.util.Log.i("JojoHomeResume", "findJojoPrograms source=nas nas=" + fromNas.size() + " bridge=" + (bridge.available ? bridge.programs.size() : 0));
            return bridge.available ? overlayActiveJojoBridgeSnapshot(fromNas, bridge.programs) : fromNas;
        }
        if (bridge.available) return bridge.programs;
        if (!fromNas.isEmpty()) return fromNas;
        List<JojoProgram> published = findPreviewProgramsForPackage("com.jojo.tv");
        if (published.isEmpty()) published = findPreviewProgramsForPackage("com.jojo.tv.debug");
        // Android TV Home exposes each JojoTV profile in a distinct Preview channel.
        // Those channels are the authoritative source: merging them with the bridge
        // is wrong because the bridge only returns the active profile and uses the
        // same intent for two profiles watching the same programme.
        if (!published.isEmpty()) return mergeJojoProgramSources(fromNas, published);
        try {
            Long jojoChannel = null;
            Cursor channels = getContentResolver().query(TvContract.Channels.CONTENT_URI, new String[]{TvContract.Channels._ID, TvContract.Channels.COLUMN_INTERNAL_PROVIDER_ID}, null, null, null);
            if (channels != null) try {
                int id = channels.getColumnIndex(TvContract.Channels._ID), provider = channels.getColumnIndex(TvContract.Channels.COLUMN_INTERNAL_PROVIDER_ID);
                while (channels.moveToNext()) {
                    String key = provider >= 0 ? channels.getString(provider) : null;
                    if (key != null && (key.startsWith("com.jojo.tv:continue_watching") || key.startsWith("com.jojo.tv.debug:continue_watching"))) {
                        jojoChannel = channels.getLong(id);
                        break;
                    }
                }
            } finally { channels.close(); }
            if (jojoChannel == null) return fromNas;
            String[] projection = {TvContract.PreviewPrograms.COLUMN_TITLE, TvContract.Programs.COLUMN_SHORT_DESCRIPTION, TvContract.PreviewPrograms.COLUMN_POSTER_ART_URI, TvContract.PreviewPrograms.COLUMN_THUMBNAIL_URI, TvContract.PreviewPrograms.COLUMN_INTENT_URI};
            Cursor programs = getContentResolver().query(TvContract.PreviewPrograms.CONTENT_URI, projection, TvContract.PreviewPrograms.COLUMN_CHANNEL_ID + "=?", new String[]{String.valueOf(jojoChannel)}, null);
            List<JojoProgram> result = new ArrayList<>();
            if (programs != null) try { while (programs.moveToNext()) {
                // JojoTV's poster column is the reference artwork. The
                // thumbnail column can contain an episode frame and must only
                // be used when the poster is unavailable.
                String art = programs.getString(2); if (SystemContinueWatching.isBlank(art)) art = programs.getString(3);
                result.add(new JojoProgram(programs.getString(0), programs.getString(1), art, programs.getString(4)));
            }} finally { programs.close(); }
            return mergeJojoProgramSources(fromNas, result);
        } catch (Exception ignored) { return fromNas; }
    }

    private List<JojoProgram> findJojoProgramsFromNas() {
        if (homePrefs().getString("nas_token", "").isEmpty()) return Collections.emptyList();
        // Rendering Continue Watching must remain a cache-only operation.
        // Pulls are scheduled explicitly by the Home lifecycle/bridge timer;
        // starting one from contentRows() made every row replacement enqueue
        // another NAS refresh while the user was navigating.
        return cachedJojoProgramsFromNas();
    }

    private List<JojoProgram> cachedJojoProgramsFromNas() {
        if (HomeWatchProgressBridge.isCloud(this)) return Collections.emptyList();
        String cachedEntries = homePrefs().getString(JOJOTV_NAS_RESUME_CACHE, "[]");
        try {
            return jojoProgramsFromNasEntries(new JSONArray(cachedEntries));
        } catch (Exception ignored) {
            return Collections.emptyList();
        }
    }
    private List<JojoProgram> fetchJojoProgramsFromNas() {
        if (HomeWatchProgressBridge.isCloud(this)) return Collections.emptyList();
        try {
            long knownRevision = homePrefs().getLong(JOJOTV_NAS_RESUME_REVISION, 0L);
            JSONObject delta = null;
            try { delta = nasRequest("GET", nasBaseUrl() + "/api/sync/changes?since=" + knownRevision, homePrefs().getString("nas_token", ""), null); }
            catch (Exception ignored) { /* Old Companion: fall back to the snapshot endpoints. */ }
            long serverRevision = delta == null ? knownRevision : delta.optLong("revision", knownRevision);
            long oldestAvailable = delta == null ? knownRevision : delta.optLong("oldestAvailableRevision", serverRevision);
            JSONArray changes = delta == null ? null : delta.optJSONArray("changes");
            boolean relevant = delta == null || knownRevision == 0L || (knownRevision > 0L && knownRevision < oldestAvailable - 1L);
            boolean remoteHomeSettingsChanged = false;
            if (changes != null) for (int index = 0; index < changes.length(); index++) {
                JSONObject change = changes.optJSONObject(index);
                String domain = change == null ? "" : change.optString("domain", "");
                // Removing a JojoTV favourite also removes its resume record.
                // Re-read the profile snapshot for both domains so a stale
                // cached resume cannot survive a favourite deletion.
                if ("watch_progress".equals(domain) || "profiles".equals(domain) || "iptv_favorites".equals(domain)) relevant = true;
                if ("profile_blobs".equals(domain) && change != null && !jojoHomeDeviceId().equals(change.optString("deviceId", ""))) {
                    JSONArray keys = change.optJSONArray("keys");
                    for (int keyIndex = 0; keys != null && keyIndex < keys.length(); keyIndex++) {
                        if ("jojo-home-settings".equals(keys.optString(keyIndex))
                                || SMB_CONNECTIONS_SECRET.equals(keys.optString(keyIndex))) remoteHomeSettingsChanged = true;
                    }
                }
            }
            if (remoteHomeSettingsChanged) runOnUiThread(() -> restoreHomeSettingsFromNas(false, false));
            if (!relevant) {
                if (serverRevision > knownRevision) homePrefs().edit().putLong(JOJOTV_NAS_RESUME_REVISION, serverRevision).apply();
                return cachedJojoProgramsFromNas();
            }
            JSONArray profiles = nasRequest("GET", nasBaseUrl() + "/api/sync/profiles", homePrefs().getString("nas_token", ""), null).optJSONArray("profiles");
            if (profiles == null || profiles.length() == 0) {
                // A transiently incomplete profile directory must not make
                // Jojo Home fall back to profile 1 and hide the other
                // profiles already present in its cached NAS snapshot.
                JSONArray cachedProfiles = new JSONArray();
                java.util.HashSet<Integer> cachedIds = new java.util.HashSet<>();
                JSONArray cachedEntries = new JSONArray(homePrefs().getString(JOJOTV_NAS_RESUME_CACHE, "[]"));
                for (int index = 0; index < cachedEntries.length(); index++) {
                    int cachedProfileId = cachedEntries.optJSONObject(index) == null ? 0 : cachedEntries.optJSONObject(index).optInt("jojotvProfileId", 0);
                    if (cachedProfileId > 0 && cachedIds.add(cachedProfileId)) {
                        cachedProfiles.put(new JSONObject().put("profileId", cachedProfileId));
                    }
                }
                profiles = cachedProfiles.length() > 0
                        ? cachedProfiles
                        : new JSONArray().put(new JSONObject().put("profileId", 1));
            }
            JSONArray cached = new JSONArray();
            List<JojoProgram> result = new ArrayList<>();
            for (int index = 0; index < profiles.length(); index++) {
                int profileId = profiles.optJSONObject(index) == null ? 0 : profiles.optJSONObject(index).optInt("profileId", 0);
                if (profileId <= 0) continue;
                JSONObject response = nasRequest("GET", nasBaseUrl() + "/api/sync/profiles/" + profileId + "/watch-progress", homePrefs().getString("nas_token", ""), null);
                JSONArray entries = response.optJSONArray("entries");
                if (entries == null) entries = new JSONArray();
                for (int entryIndex = 0; entryIndex < entries.length(); entryIndex++) {
                    JSONObject entry = entries.optJSONObject(entryIndex);
                    if (entry != null) cached.put(new JSONObject(entry.toString()).put("jojotvProfileId", profileId));
                }
                result = mergeJojoProgramSources(result, jojoProgramsFromNasEntries(entries, profileId));
            }
            String updatedCache = cached.toString();
            String previousCache = homePrefs().getString(JOJOTV_NAS_RESUME_CACHE, "[]");
            if (!updatedCache.equals(previousCache)) {
                // Make the snapshot durable before notifying Home. Otherwise
                // the first rebuild could read the previous cache because
                // SharedPreferences.apply() writes asynchronously.
                homePrefs().edit().putString(JOJOTV_NAS_RESUME_CACHE, updatedCache).commit();
                publishFetchedJojoProgramsToHome();
            }
            homePrefs().edit().putLong(JOJOTV_NAS_RESUME_REVISION, serverRevision).commit();
            homePrefs().edit().putLong("jojotv_nas_resume_last_success", System.currentTimeMillis()).remove("jojotv_nas_resume_last_error").apply();
            return result;
        } catch (Exception error) {
            homePrefs().edit().putString("jojotv_nas_resume_last_error", safeNasError(error)).apply();
            // Keep the last JojoTV-only cache on a temporary NAS failure. A valid
            // empty NAS response above deliberately writes an empty snapshot.
            return cachedJojoProgramsFromNas();
        }
    }
    private void publishFetchedJojoProgramsToHome() {
        runOnUiThread(() -> {
            if (activeScreen != null || currentHomePage == null || !currentHomePage.isAttachedToWindow()) return;
            if (homeDpadNavigationActive) {
                nasHomeResumeRefreshPending = true;
                homeRefreshPendingAfterDpad = true;
                return;
            }
            // The Home section can update its focused Hero without detaching it.
            refreshHomeResumeSectionInPlace();
        });
    }
    /**
     * The old implementation only persisted the NAS response.  Consequently the
     * launcher kept displaying its already-built row until a device reboot rebuilt
     * the whole home screen.  Recreate the home only when the resume snapshot has
     * genuinely changed; this keeps normal navigation and focus untouched.
     */
    private void refreshVisibleHomeResumeRow() {
        if (isFinishing() || isDestroyed() || activeScreen != null) return;
        View focused = getWindow().getDecorView().findFocus();
        if (focused != null && focused.getTag() instanceof String) {
            pendingResumeFocusKey = (String) focused.getTag();
        }
        goHome();
    }
    private void refreshJojoProgramsFromNasAsync() {
        synchronized (this) { if (nasResumeRefreshInFlight) return; nasResumeRefreshInFlight = true; }
        new Thread(() -> { try { fetchJojoProgramsFromNas(); } finally { synchronized (this) { nasResumeRefreshInFlight = false; } } }).start();
    }

    private List<JojoProgram> jojoProgramsFromNasEntries(JSONArray entries) {
        List<JojoProgram> result = new ArrayList<>();
        for (int index = 0; index < entries.length(); index++) {
            JSONObject entry = entries.optJSONObject(index);
            if (entry == null) continue;
            int profileId = entry.optInt("jojotvProfileId", 1);
            result = mergeJojoProgramSources(result, jojoProgramsFromNasEntries(new JSONArray().put(entry), profileId));
        }
        return result;
    }
    private List<JojoProgram> jojoProgramsFromNasEntries(JSONArray entries, int profileId) {
        ArrayList<JojoProgram> result = new ArrayList<>();
        if (profileId != watchProgressSnapshotProfileId) return result;
        // The NAS returns its historical watch-progress list.  The home row is
        // capped, so rendering that raw order lets old entries consume every
        // visible slot while newly watched videos remain off-screen.
        ArrayList<JSONObject> ordered = new ArrayList<>();
        for (int index = 0; index < entries.length(); index++) {
            JSONObject entry = entries.optJSONObject(index);
            if (entry != null) ordered.add(entry);
        }
        Collections.sort(ordered, (left, right) -> Long.compare(
            right.optLong("lastWatched", 0L), left.optLong("lastWatched", 0L)
        ));
        for (JSONObject entry : ordered) {
            if (entry == null) continue;
            String contentId = entry.optString("contentId", "").trim();
            String contentType = entry.optString("contentType", "").trim();
            String videoId = entry.optString("videoId", "").trim();
            long position = entry.optLong("position"), duration = entry.optLong("duration");
            if (contentId.isEmpty() || contentType.isEmpty() || videoId.isEmpty() || !isNasResume(position, duration)) continue;
            String title = entry.optString("name", "").trim();
            if (title.isEmpty()) title = contentId;
            String description = entry.optString("description", "").trim();
            String season = entry.has("season") && !entry.isNull("season") ? String.valueOf(entry.optInt("season")) : null;
            String episode = entry.has("episode") && !entry.isNull("episode") ? String.valueOf(entry.optInt("episode")) : null;
            if (description.isEmpty()) {
                String episodeTitle = entry.optString("episodeTitle", "").trim();
                String episodeLabel = SystemContinueWatching.episodeLabel(season, episode);
                description = episodeLabel.isEmpty() ? episodeTitle : episodeTitle.isEmpty() ? episodeLabel : episodeLabel + " · " + episodeTitle;
            }
            String profileLabel = "Profil " + profileId;
            description = description.isEmpty() ? profileLabel : profileLabel + " · " + description;
            // Les cartes « Continuer à regarder » sont horizontales : le backdrop
            // est la bonne image. Le poster vertical ne sert qu'en secours.
            String artwork = entry.optString("backdrop", "").trim();
            if (artwork.isEmpty()) artwork = entry.optString("poster", "").trim();
            result.add(new JojoProgram("com.jojo.tv", title, description, artwork, nasJojoResumeIntent(entry, contentId, contentType, videoId, profileId), duration, position, season, episode));
        }
        return result;
    }

    private boolean isFinishedResumePosition(long position, long duration) {
        return duration > 0L && position >= duration;
    }

    private boolean isNasResume(long position, long duration) {
        if (position <= 0L) return false;
        if (duration <= 0L) return position >= 30_000L;
        // The NAS keeps the watch-progress record after playback completes.
        // Do not restore that finished record on a new device, while still
        // keeping a programme stopped well before its end.
        if (isFinishedResumePosition(position, duration)) return false;
        float ratio = position / (float) duration;
        return ratio >= .02f;
    }

    private String nasJojoResumeIntent(JSONObject entry, String contentId, String contentType, String videoId) { return nasJojoResumeIntent(entry, contentId, contentType, videoId, entry.optInt("jojotvProfileId", 1)); }
    private String nasJojoResumeIntent(JSONObject entry, String contentId, String contentType, String videoId, int profileId) {
        String packageName = installedJojoTvPackage();
        if (packageName == null) packageName = "com.jojo.tv";
        Intent intent = new Intent(Intent.ACTION_VIEW).setComponent(new ComponentName(packageName, "com.nuvio.tv.MainActivity"));
        intent.putExtra("contentId", contentId).putExtra("contentType", contentType).putExtra("androidTvProfileId", profileId).putExtra("androidTvDirectPlay", true);
        intent.putExtra("androidTvName", entry.optString("name", contentId)).putExtra("androidTvPoster", entry.optString("poster", "")).putExtra("androidTvBackdrop", entry.optString("backdrop", "")).putExtra("androidTvLogo", entry.optString("logo", ""));
        intent.putExtra("androidTvVideoId", videoId).putExtra("androidTvPosition", entry.optLong("position")).putExtra("androidTvDuration", entry.optLong("duration")).putExtra("androidTvLastWatched", entry.optLong("lastWatched")).putExtra("androidTvDescription", entry.optString("description", ""));
        String progressKey = entry.optString("key", "");
        if (!progressKey.isEmpty()) intent.putExtra("androidTvProgressKey", progressKey);
        if (entry.has("season") && !entry.isNull("season")) intent.putExtra("androidTvSeason", entry.optInt("season"));
        if (entry.has("episode") && !entry.isNull("episode")) intent.putExtra("androidTvEpisode", entry.optInt("episode"));
        String episodeTitle = entry.optString("episodeTitle", ""); if (!episodeTitle.isEmpty()) intent.putExtra("androidTvEpisodeTitle", episodeTitle);
        intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK | Intent.FLAG_ACTIVITY_CLEAR_TOP);
        return intent.toUri(Intent.URI_INTENT_SCHEME);
    }

    private String installedJojoTvPackage() {
        PackageManager pm = getPackageManager();
        String[] candidates = { "com.jojo.tv", "com.jojo.tv.debug", "com.nuvio.tv" };
        for (String candidate : candidates) {
            if (pm.getLaunchIntentForPackage(candidate) != null) return candidate;
        }
        return null;
    }

    private List<JojoProgram> mergeJojoProgramSources(List<JojoProgram> remembered, List<JojoProgram> latest) {
        LinkedHashMap<String, JojoProgram> merged = new LinkedHashMap<>();
        if (remembered != null) for (JojoProgram program : remembered) if (program != null) merged.put(jojoProgramIdentity(program), program);
        if (latest != null) for (JojoProgram program : latest) if (program != null) merged.put(jojoProgramIdentity(program), program);
        return new ArrayList<>(merged.values());
    }

    private String jojoProgramIdentity(JojoProgram program) {
        String profileId = SystemContinueWatching.jojoIntentExtra(program.intentUri, "androidTvProfileId");
        String contentId = SystemContinueWatching.jojoIntentExtra(program.intentUri, "contentId");
        if (!SystemContinueWatching.isBlank(contentId)) return (profileId == null ? "" : profileId + "|") + contentId + "|" + String.valueOf(program.seasonNumber) + "|" + String.valueOf(program.episodeNumber);
        if (program.intentUri != null && !program.intentUri.isEmpty()) return program.intentUri;
        return String.valueOf(program.title) + "|" + String.valueOf(program.description) + "|" + String.valueOf(program.seasonNumber) + "|" + String.valueOf(program.episodeNumber);
    }

    private List<JojoProgram> overlayActiveJojoBridgeSnapshot(List<JojoProgram> fromNas, List<JojoProgram> fromBridge) {
        String activeProfileId = jojoProgramSnapshotProfileId(fromBridge);
        if (!SystemContinueWatching.isBlank(activeProfileId)) {
            homePrefs().edit().putString("jojo_bridge_active_profile", activeProfileId).apply();
        } else {
            activeProfileId = homePrefs().getString("jojo_bridge_active_profile", "");
        }
        if (SystemContinueWatching.isBlank(activeProfileId)) {
            return mergeJojoProgramSources(fromNas, fromBridge);
        }

        ArrayList<JojoProgram> replaced = new ArrayList<>();
        for (JojoProgram program : fromNas) {
            String profileId = SystemContinueWatching.jojoIntentExtra(program.intentUri, "androidTvProfileId");
            if (!activeProfileId.equals(profileId)) replaced.add(program);
        }
        // The bridge intent contains a fresh position/timestamp and therefore
        // differs from the NAS intent even when both describe the same resume.
        // Merge through the stable profile/content/episode identity so the
        // local low-latency update replaces the NAS card instead of duplicating it.
        return mergeJojoProgramSources(replaced, fromBridge);
    }

    private String jojoProgramSnapshotProfileId(List<JojoProgram> programs) {
        String profileId = null;
        if (programs == null) return "";
        for (JojoProgram program : programs) {
            String candidate = SystemContinueWatching.jojoIntentExtra(program.intentUri, "androidTvProfileId");
            if (SystemContinueWatching.isBlank(candidate)) continue;
            if (profileId != null && !profileId.equals(candidate)) return "";
            profileId = candidate;
        }
        return profileId == null ? "" : profileId;
    }

    private List<JojoProgram> rememberJojoProfileSnapshots(List<JojoProgram> latest) {
        List<SystemContinueWatching.Item> remembered = new ArrayList<>();
        try {
            JSONArray saved = new JSONArray(homePrefs().getString("jojo_profile_resume_cache", "[]"));
            for (int index = 0; index < saved.length(); index++) {
                JSONObject value = saved.optJSONObject(index); if (value == null) continue;
                remembered.add(new SystemContinueWatching.Item("com.jojo.tv", value.optString("title"), value.optString("description"), value.optString("artwork"), value.optString("intent"), value.optLong("duration", -1L), value.optLong("position", -1L), value.optString("season", null), value.optString("episode", null)));
            }
        } catch (Exception ignored) { }
        List<SystemContinueWatching.Item> current = new ArrayList<>();
        for (JojoProgram program : latest) current.add(new SystemContinueWatching.Item("com.jojo.tv", program.title, program.description, program.artwork, program.intentUri, program.duration, program.position, program.seasonNumber, program.episodeNumber));
        String activeProfileId = jojoSnapshotProfileId(current);
        if (!SystemContinueWatching.isBlank(activeProfileId)) homePrefs().edit().putString("jojo_profile_resume_cache_active_profile", activeProfileId).apply();
        else activeProfileId = homePrefs().getString("jojo_profile_resume_cache_active_profile", "");
        List<SystemContinueWatching.Item> merged = SystemContinueWatching.replaceJojoProfileSnapshot(remembered, current, activeProfileId);
        JSONArray saved = new JSONArray();
        List<JojoProgram> result = new ArrayList<>();
        for (SystemContinueWatching.Item item : merged) {
            JSONObject value = new JSONObject();
            try { value.put("title", item.title).put("description", item.description).put("artwork", item.artwork).put("intent", item.intentUri).put("duration", item.duration).put("position", item.position).put("season", item.seasonNumber).put("episode", item.episodeNumber); saved.put(value); } catch (Exception ignored) { }
            result.add(new JojoProgram("com.jojo.tv", item.title, item.description, item.artwork, item.intentUri, item.duration, item.position, item.seasonNumber, item.episodeNumber));
        }
        homePrefs().edit().putString("jojo_profile_resume_cache", saved.toString()).apply();
        return result;
    }
    private String jojoSnapshotProfileId(List<SystemContinueWatching.Item> items) {
        String profileId = null;
        for (SystemContinueWatching.Item item : items) {
            String candidate = SystemContinueWatching.jojoProfileId(item);
            if (SystemContinueWatching.isBlank(candidate)) continue;
            if (profileId != null && !profileId.equals(candidate)) return "";
            profileId = candidate;
        }
        return profileId == null ? "" : profileId;
    }

    private static final class JojoBridgeResponse {
        final boolean available;
        final List<JojoProgram> programs;
        JojoBridgeResponse(boolean available, List<JojoProgram> programs) { this.available = available; this.programs = programs; }
    }

    private JojoBridgeResponse findJojoProgramsFromBridge(String uri) {
        String authority = Uri.parse(uri).getAuthority();
        if (authority == null || getPackageManager().resolveContentProvider(authority, 0) == null) {
            return new JojoBridgeResponse(false, Collections.emptyList());
        }
        JojoBridgeResponse extended = readJojoProgramsFromBridge(uri, SystemContinueWatching.bridgeColumns());
        return extended.available ? extended : readJojoProgramsFromBridge(uri, SystemContinueWatching.legacyBridgeColumns());
    }
    private JojoBridgeResponse readJojoProgramsFromBridge(String uri, List<String> columns) {
        List<JojoProgram> result = new ArrayList<>();
        Set<String> seen = new HashSet<>();
        try {
            Cursor programs = getContentResolver().query(Uri.parse(uri), columns.toArray(new String[0]), null, null, null);
            if (programs == null) return new JojoBridgeResponse(false, result);
            try { while (programs.moveToNext()) {
                int title = programs.getColumnIndex("title"), description = programs.getColumnIndex("description"), poster = programs.getColumnIndex("poster"), thumbnail = programs.getColumnIndex("thumbnail"), intent = programs.getColumnIndex("intent_uri"), duration = programs.getColumnIndex("duration"), position = programs.getColumnIndex("position"), season = programs.getColumnIndex("season_number"), episode = programs.getColumnIndex("episode_number");
                // Keep JojoTV's poster as the single reference image. Using
                // the thumbnail first made Jojo Home display a different
                // episode frame than the JojoTV card for the same programme.
                String art = poster < 0 ? null : programs.getString(poster); if (SystemContinueWatching.isBlank(art) && thumbnail >= 0) art = programs.getString(thumbnail);
                String intentUri = intent < 0 ? null : programs.getString(intent);
                String titleValue = title < 0 ? null : programs.getString(title), descriptionValue = description < 0 ? null : programs.getString(description);
                String key = intentUri == null ? titleValue + "|" + descriptionValue : intentUri;
                String seasonValue = season < 0 ? null : programs.getString(season);
                String episodeValue = episode < 0 ? null : programs.getString(episode);
                if (SystemContinueWatching.isBlank(seasonValue)) seasonValue = SystemContinueWatching.jojoIntentExtra(intentUri, "androidTvSeason");
                if (SystemContinueWatching.isBlank(episodeValue)) episodeValue = SystemContinueWatching.jojoIntentExtra(intentUri, "androidTvEpisode");
                if (seen.add(key)) result.add(new JojoProgram("com.jojo.tv", titleValue, descriptionValue, art, intentUri, duration < 0 ? -1L : programs.getLong(duration), position < 0 ? -1L : programs.getLong(position), seasonValue, episodeValue));
            }} finally { programs.close(); }
            return new JojoBridgeResponse(true, result);
        } catch (Exception ignored) { return new JojoBridgeResponse(false, result); }
    }
    private List<JojoProgram> findPreviewProgramsForPackage(String packageName) {
        List<Long> channelIds = new ArrayList<>();
        try {
            Cursor channels = getContentResolver().query(previewChannelsUri(), new String[]{TvContract.Channels._ID, "package_name", TvContract.Channels.COLUMN_INTERNAL_PROVIDER_ID}, null, null, null);
            if (channels != null) try {
                int id = channels.getColumnIndex(TvContract.Channels._ID), owner = channels.getColumnIndex("package_name"), internal = channels.getColumnIndex(TvContract.Channels.COLUMN_INTERNAL_PROVIDER_ID);
                while (channels.moveToNext()) {
                    String ownerPackage = owner >= 0 ? channels.getString(owner) : null;
                    String providerId = internal >= 0 ? channels.getString(internal) : null;
                    if (packageName.equals(ownerPackage) || (providerId != null && providerId.startsWith(packageName))) channelIds.add(channels.getLong(id));
                }
            } finally { channels.close(); }
        } catch (Exception ignored) { return Collections.emptyList(); }

        List<JojoProgram> result = new ArrayList<>();
        for (Long channelId : channelIds) {
            // Some Android TV providers do not expose playback columns in a
            // PreviewPrograms projection. A failed channel must not hide the other
            // profile channels, so retry it with the standard contract columns.
            List<JojoProgram> programs = readPreviewChannel(packageName, channelId, true);
            result.addAll(programs);
        }
        return result;
    }

    /** App channels (SmartTube, JojoTV, etc.) live in TvProvider's preview view,
     * not in the regular tuner-channel view returned by Channels.CONTENT_URI. */
    private Uri previewChannelsUri() {
        return TvContract.Channels.CONTENT_URI.buildUpon()
                .appendQueryParameter("preview", "true")
                .build();
    }

    private List<JojoProgram> readPreviewChannel(String packageName, long channelId, boolean includeProgress) {
        return readPreviewChannelSnapshot(packageName, channelId, includeProgress).programs;
    }

    private PublishedResumeSnapshot readPreviewChannelSnapshot(String packageName, long channelId, boolean includeProgress) {
        return readPreviewChannelSnapshot(packageName, channelId, includeProgress, true);
    }

    private PublishedResumeSnapshot readPreviewChannelSnapshot(String packageName, long channelId,
                                                               boolean includeProgress, boolean includeEpisodeNumbers) {
        List<JojoProgram> result = new ArrayList<>();
        String[] projection = includeProgress
                ? new String[]{TvContract.PreviewPrograms.COLUMN_TITLE, TvContract.Programs.COLUMN_SHORT_DESCRIPTION, TvContract.PreviewPrograms.COLUMN_POSTER_ART_URI, TvContract.PreviewPrograms.COLUMN_THUMBNAIL_URI, TvContract.PreviewPrograms.COLUMN_INTENT_URI, "duration_millis", "last_playback_position_millis"}
                : new String[]{TvContract.PreviewPrograms.COLUMN_TITLE, TvContract.Programs.COLUMN_SHORT_DESCRIPTION, TvContract.PreviewPrograms.COLUMN_POSTER_ART_URI, TvContract.PreviewPrograms.COLUMN_THUMBNAIL_URI, TvContract.PreviewPrograms.COLUMN_INTENT_URI};
        if (includeEpisodeNumbers) {
            projection = java.util.Arrays.copyOf(projection, projection.length + 2);
            projection[projection.length - 2] = "season_display_number";
            projection[projection.length - 1] = "episode_display_number";
        }
        try {
            // TvProvider exposes App/Preview channel programs through the
            // channel-scoped URI. A generic SQL selection can return an empty
            // cursor for programs published by another package (SmartTube).
            Cursor programs = getContentResolver().query(
                    TvContract.buildPreviewProgramsUriForChannel(channelId),
                    projection, null, null, null);
            if (programs == null) return new PublishedResumeSnapshot(false, result);
            try {
                int seasonIndex = programs.getColumnIndex("season_display_number");
                int episodeIndex = programs.getColumnIndex("episode_display_number");
                while (programs.moveToNext()) {
                    String art = programs.getString(2); if (SystemContinueWatching.isBlank(art)) art = programs.getString(3);
                    String intentUri = programs.getString(4);
                    String season = seasonIndex < 0 ? "" : programs.getString(seasonIndex);
                    String episode = episodeIndex < 0 ? "" : programs.getString(episodeIndex);
                    if (SystemContinueWatching.isBlank(season)) season = SystemContinueWatching.jojoIntentExtra(intentUri, "androidTvSeason");
                    if (SystemContinueWatching.isBlank(episode)) episode = SystemContinueWatching.jojoIntentExtra(intentUri, "androidTvEpisode");
                    long duration = includeProgress && !programs.isNull(5) ? programs.getLong(5) : -1L;
                    long position = includeProgress && !programs.isNull(6) ? programs.getLong(6) : -1L;
                    if (position > 0L || SystemContinueWatching.hasPublishedResumeLabel(programs.getString(1)))
                        observeSharedExternalResume(new JojoProgram(packageName, programs.getString(0), programs.getString(1),
                                art, intentUri, duration, position, season, episode), "preview-" + channelId);
                    if (duration > 0L && position >= 0L && (position >= duration || (position == 0L
                            && !(hasMixedPreviewResumeChannel(packageName)
                                && SystemContinueWatching.hasPublishedResumeLabel(programs.getString(1)))))) continue;
                    result.add(new JojoProgram(packageName, programs.getString(0), programs.getString(1), art, intentUri, duration, position, season, episode));
                }
            } finally { programs.close(); }
            return new PublishedResumeSnapshot(true, result);
        } catch (Exception ignored) {
            // Retry only an unsupported projection, never an empty or completed channel.
            if (includeEpisodeNumbers) return readPreviewChannelSnapshot(packageName, channelId, includeProgress, false);
            if (includeProgress) return readPreviewChannelSnapshot(packageName, channelId, false, false);
        }
        return new PublishedResumeSnapshot(false, result);
    }

    private String resumeDismissKey(JojoProgram program) {
        String sharedKey = sharedExternalResumeKey(program);
        if (!sharedKey.isEmpty()) return SHARED_EXTERNAL_RESUME_PREFIX + sharedKey;
        if (program != null && (FILE_VIDEO_RESUME_SOURCE.equals(program.sourcePackage)
                || FREEBOX_FOLDER_SOURCE.equals(program.sourcePackage) || "external-playback".equals(program.sourcePackage))) {
            if ("external-playback".equals(program.sourcePackage) && program.intentUri != null
                    && program.intentUri.startsWith("iptv:"))
                return com.jojotv.home.iptv.IptvStore.homeResumeDismissalKey(program.intentUri);
            return program.sourcePackage + "|" + program.intentUri;
        }
        String source = program == null || program.sourcePackage == null ? "" : program.sourcePackage;
        String contentId = program == null ? null : SystemContinueWatching.jojoIntentExtra(program.intentUri, "contentId");
        String season = program == null ? null : SystemContinueWatching.jojoIntentExtra(program.intentUri, "androidTvSeason");
        String episode = program == null ? null : SystemContinueWatching.jojoIntentExtra(program.intentUri, "androidTvEpisode");
        if (!SystemContinueWatching.isBlank(contentId)) return source + "|" + contentId + "|" + season + "|" + episode;
        // SmartTube regenerates its preview intent and description while an
        // item remains in History.  Use the displayed title for dismissal so
        // a user removal cannot be undone by that metadata refresh.
        String normalizedSource = source.toLowerCase(Locale.ROOT);
        if (normalizedSource.contains("smarttube") || normalizedSource.contains("youtube")) {
            return source + "|" + (program == null || program.title == null ? "" : program.title.trim().toLowerCase(Locale.ROOT)) + "|" + season + "|" + episode;
        }
        // Provider intents and synopses may be regenerated whenever playback or
        // metadata changes. A dismissal must survive those updates.
        String title = program == null || program.title == null
                ? "" : program.title.trim().toLowerCase(Locale.ROOT);
        return source + "|" + title + "|" + season + "|" + episode;
    }

    private String legacyProviderDismissKey(JojoProgram program) {
        // Exact episode/video identities must not inherit a whole-title mask.
        String sharedKey = sharedExternalResumeKey(program);
        if (!sharedKey.isEmpty()) return SHARED_EXTERNAL_RESUME_PREFIX + sharedKey;
        String source = program == null || program.sourcePackage == null ? "" : program.sourcePackage;
        return source + "|" + (program == null ? "" : String.valueOf(program.title)) + "|"
                + (program == null ? "" : String.valueOf(program.description));
    }

    private String resumeSuppressionKey(JojoProgram program) {
        if (program != null && "external-playback".equals(program.sourcePackage)
                && program.intentUri != null && !program.intentUri.isEmpty()) {
            if (program.intentUri.startsWith("iptv:")) return resumeDismissKey(program);
            String key = ExternalPlaybackStore.continueWatchingDismissalKey(
                    externalResumeItem(program));
            if (!key.isEmpty()) return key;
        }
        if (program != null && isJojoPackage(program.sourcePackage)) {
            String contentType = SystemContinueWatching.jojoIntentExtra(program.intentUri, "contentType");
            String season = SystemContinueWatching.jojoIntentExtra(program.intentUri, "androidTvSeason");
            String episode = SystemContinueWatching.jojoIntentExtra(program.intentUri, "androidTvEpisode");
            boolean seriesResume = "series".equalsIgnoreCase(contentType)
                    || "episode".equalsIgnoreCase(contentType)
                    || !SystemContinueWatching.isBlank(season)
                    || !SystemContinueWatching.isBlank(episode);
            if (seriesResume) {
                String profile = SystemContinueWatching.jojoIntentExtra(program.intentUri, "androidTvProfileId");
                String contentId = SystemContinueWatching.jojoIntentExtra(program.intentUri, "contentId");
                String identity = SystemContinueWatching.isBlank(contentId) ? "" : contentId.trim();
                if (identity.isEmpty()) {
                    String title = resumeTitleKey(program);
                    if (!title.isEmpty()) identity = title + "|" + resumeYearKey(program);
                }
                if (!identity.isEmpty()) {
                    return "jojo-series-resume|" + program.sourcePackage + "|"
                            + (profile == null ? "" : profile) + "|" + identity;
                }
            }
        }
        return resumeDismissKey(program);
    }

    private boolean isFinishedExternalResume(JojoProgram program) {
        if (program == null || program.sourcePackage == null) return false;
        long endingWindow = NotificationResumeRules.isYoutubeVideoPackage(program.sourcePackage) ? 5_000L : 0L;
        return program.duration > 0L && program.position > 0L
                && program.position >= Math.max(0L, program.duration - endingWindow);
    }

    private String legacyResumeDismissKey(JojoProgram program) {
        String source = program == null || program.sourcePackage == null ? "" : program.sourcePackage;
        return source + "|" + (program == null ? "" : String.valueOf(program.title)) + "|" + (program == null ? "" : String.valueOf(program.intentUri));
    }

    private boolean isResumeDismissed(JojoProgram program) {
        if (program != null) {
            Boolean hidden = com.jojotv.home.progresspilot.AccountSettingsRouting.resumeDismissal(
                    this, HomeWatchProgressBridge.currentProfileId(this), resumeDismissKey(program));
            if (hidden != null) return hidden;
            // Upgrading the shared identity must not restore an explicitly hidden Netflix card.
            // A newer explicit replay on the new identity has already taken precedence above.
            if ("netflix".equals(SystemContinueWatching.sharedResumeProvider(program.sourcePackage))) {
                try {
                    String legacy = Intent.parseUri(program.intentUri, Intent.URI_INTENT_SCHEME).getStringExtra("jojoHomeLegacyNetflixResumeKey");
                    if (legacy != null) {
                        hidden = com.jojotv.home.progresspilot.AccountSettingsRouting.resumeDismissal(
                                this, HomeWatchProgressBridge.currentProfileId(this), legacy);
                        if (hidden != null) return hidden;
                        if (homePrefs().getStringSet(JOJOTV_HOME_HIDDEN_RESUME_KEYS, Collections.emptySet()).contains(legacy)) return true;
                    }
                } catch (java.net.URISyntaxException ignored) { }
            }
        }
        if (program != null && HomeWatchProgressBridge.isCloud(this)) {
            if (FILE_VIDEO_RESUME_SOURCE.equals(program.sourcePackage) || FREEBOX_FOLDER_SOURCE.equals(program.sourcePackage))
                return hasDeletedFreeboxPath(program.intentUri);
            if ("external-playback".equals(program.sourcePackage) && program.intentUri.startsWith("iptv:")) return false;
        }
        String sharedKey = sharedExternalResumeKey(program);
        if (!sharedKey.isEmpty() && sharedExternalResume(sharedKey).optBoolean("deleted")) return true;
        if (program != null && "external-playback".equals(program.sourcePackage)) {
            String stableKey = resumeDismissKey(program);
            String suppressionKey = resumeSuppressionKey(program);
            Set<String> hidden = homePrefs().getStringSet(JOJOTV_HOME_HIDDEN_RESUME_KEYS, Collections.emptySet());
            if (pendingExternalRemovals.contains(program.intentUri)
                    || pendingResumeDismissals.contains(stableKey)
                    || pendingResumeDismissals.contains(suppressionKey)
                    || hidden.contains(stableKey) || hidden.contains(suppressionKey)) return true;
            JSONObject item = externalResumeItem(program);
            return item.optBoolean("deleted") || !item.optBoolean("started");
        }
        // The historic generic set was populated from preview-channel
        // recommendations (Canal+, Netflix, SmartTube).  Those cards were not
        // actual resumes, so applying its entries to Watch Next now hides
        // legitimate current playback.  Use only the clean Jojo Home set.
        String freeboxPath = freeboxResumePath(program);
        if (program != null && (FILE_VIDEO_RESUME_SOURCE.equals(program.sourcePackage)
                || FREEBOX_FOLDER_SOURCE.equals(program.sourcePackage)) && isHomeVideoHidden(program.intentUri)) return true;
        if (!freeboxPath.isEmpty() && isHomeVideoHidden(freeboxPath)) return true;
        if (!freeboxPath.isEmpty() && hasDeletedFreeboxPath(freeboxPath)) return true;
        // A provider/bridge can replay its previous Watch Next row after the
        // local progress was cleared. Keep that stale row hidden until a new
        // playback session writes fresh progress for the same file.
        if (program != null && FILE_VIDEO_RESUME_SOURCE.equals(program.sourcePackage)
                && homePrefs().contains("video_resume_invalidated_" + program.intentUri)
                && !homePrefs().contains("video_resume_" + program.intentUri)) return true;
        String stableKey = resumeDismissKey(program);
        String legacyKey = legacyProviderDismissKey(program);
        String suppressionKey = resumeSuppressionKey(program);
        if (pendingResumeDismissals.contains(stableKey) || pendingResumeDismissals.contains(legacyKey)
                || pendingResumeDismissals.contains(suppressionKey)) return true;
        Set<String> hidden = homePrefs().getStringSet(JOJOTV_HOME_HIDDEN_RESUME_KEYS, Collections.emptySet());
        return hidden.contains(stableKey) || hidden.contains(legacyKey) || hidden.contains(suppressionKey);
    }

    private List<WatchProgress> canonicalProgressForProgram(JojoProgram program) {
        ArrayList<WatchProgress> result = new ArrayList<>();
        if (program == null || program.intentUri == null) return result;
        for (WatchProgress progress : watchProgressContinueSnapshot) {
            boolean matches = false;
            if ("external-playback".equals(program.sourcePackage)) {
                // The external record ID identifies the playable item. Season/episode fields can
                // be absent on a legacy row and present on its mirror; dismiss all such aliases.
                String contentId = program.intentUri.startsWith("iptv:")
                        ? program.intentUri : ExternalPlaybackStore.CONTENT_PREFIX + program.intentUri;
                matches = contentId.equals(progress.getContentId());
            } else if (FILE_VIDEO_RESUME_SOURCE.equals(program.sourcePackage)) {
                String path = progress.getContentId().startsWith("freebox:")
                        ? com.nuvio.tv.data.freebox.FreeboxMediaDisplayKt.freeboxPathFromContentId(progress.getContentId())
                        : progress.getContentId();
                matches = path.equals(program.intentUri) || path.replaceFirst("^file://", "")
                        .equals(program.intentUri.replaceFirst("^file://", ""));
            }
            if (matches) result.add(progress);
        }
        return result;
    }

    private void dismissResumeLocally(JojoProgram program) {
        if (HomeWatchProgressBridge.isCloud(this)) {
            List<WatchProgress> targets = canonicalProgressForProgram(program);
            if (!targets.isEmpty()) {
                new Thread(() -> {
                    try {
                        for (WatchProgress progress : targets)
                            HomeWatchProgressBridge.hideCloudContent(this, progress.getContentId(), true);
                    } catch (Exception error) {
                        runOnUiThread(() -> Toast.makeText(this, "La reprise n’a pas pu être masquée", Toast.LENGTH_LONG).show());
                    }
                }).start();
                return;
            }
        }
        deleteSharedExternalResume(program);
        // Keep every new removal in the clean launcher-owned set.  In
        // particular, do not add it to the legacy recommendation set above.
        Set<String> hidden = new HashSet<>(homePrefs().getStringSet(JOJOTV_HOME_HIDDEN_RESUME_KEYS, Collections.emptySet()));
        String stableKey = resumeDismissKey(program);
        String legacyKey = legacyProviderDismissKey(program);
        String suppressionKey = resumeSuppressionKey(program);
        pendingResumeDismissals.add(stableKey);
        com.jojotv.home.progresspilot.AccountSettingsRouting.recordResumeDismissal(
                this, HomeWatchProgressBridge.currentProfileId(this), stableKey, true);
        pendingResumeDismissals.add(legacyKey);
        pendingResumeDismissals.add(suppressionKey);
        hidden.add(stableKey);
        hidden.add(suppressionKey);
        // Keep the pre-stable-key spelling too. This protects a removal made
        // while an older provider row is still present in an in-flight result.
        hidden.add(legacyKey);
        android.content.SharedPreferences.Editor removal = homePrefs().edit()
                .putStringSet(JOJOTV_HOME_HIDDEN_RESUME_KEYS, hidden)
                .remove(CONTINUE_WATCHING_HOME_CACHE);
        if ("external-playback".equals(program.sourcePackage)) {
            // The provider series mask must also remove canonical episode progress,
            // including records known only on another device after NAS synchronization.
            long removedAt = System.currentTimeMillis();
            for (WatchProgress progress : canonicalProgressForProgram(program)) {
                removedAt = Math.max(removedAt, progress.getLastWatched());
            }
            removal.putLong(HomeWatchProgressBridge.REMOVAL_PREFIX + watchProgressSnapshotProfileId
                    + "_" + suppressionKey, removedAt);
        }
        // Native favorite removal hides the resume but retains watched episodes and positions.
        List<WatchProgress> progressToRemove = "external-playback".equals(program.sourcePackage)
                && program.intentUri.startsWith("iptv:") ? Collections.emptyList() : canonicalProgressForProgram(program);
        for (WatchProgress progress : progressToRemove) {
            long removedAt = Math.max(System.currentTimeMillis(), progress.getLastWatched());
            String prefix = HomeWatchProgressBridge.REMOVAL_PREFIX + watchProgressSnapshotProfileId + "_";
            removal.putLong(prefix + progress.getStorageKey(), removedAt);
            if ("external-playback".equals(program.sourcePackage)) {
                // Keep the provider record identity too: imported rows may have legacy and
                // episode-enriched wp2 keys for the same external item.
                removal.putLong(prefix + progress.getContentId(), removedAt);
            }
        }
        long dismissedAt = System.currentTimeMillis();
        String removalPrefix = HomeWatchProgressBridge.REMOVAL_PREFIX
                + (watchProgressSnapshotProfileId > 0 ? watchProgressSnapshotProfileId : 1) + "_";
        for (String key : new String[] { stableKey, legacyKey, suppressionKey }) {
            removal.putLong(removalPrefix + key, dismissedAt);
        }
        if (program != null && FILE_VIDEO_RESUME_SOURCE.equals(program.sourcePackage)) {
            // Keep exact path evidence even when the canonical snapshot has
            // not arrived yet (offline launch or a delayed NAS response).
            removal.putLong(removalPrefix + program.intentUri.replaceFirst("^file://", ""), dismissedAt);
        }
        removal.apply();
    }

    private void clearResumeDismissal(JojoProgram program) {
        if (program == null) return;
        String stableKey = resumeDismissKey(program);
        com.jojotv.home.progresspilot.AccountSettingsRouting.recordResumeDismissal(
                this, HomeWatchProgressBridge.currentProfileId(this), stableKey, false);
        String legacyKey = legacyProviderDismissKey(program);
        String suppressionKey = resumeSuppressionKey(program);
        pendingResumeDismissals.remove(stableKey);
        pendingResumeDismissals.remove(legacyKey);
        pendingResumeDismissals.remove(suppressionKey);
        Set<String> hidden = new HashSet<>(homePrefs().getStringSet(
                JOJOTV_HOME_HIDDEN_RESUME_KEYS, Collections.emptySet()));
        boolean changed = hidden.remove(stableKey);
        changed |= hidden.remove(legacyKey);
        changed |= hidden.remove(suppressionKey);
        if (changed) {
            android.content.SharedPreferences.Editor restored = homePrefs().edit()
                    .putStringSet(JOJOTV_HOME_HIDDEN_RESUME_KEYS, hidden)
                    .remove(CONTINUE_WATCHING_HOME_CACHE);
            String prefix = HomeWatchProgressBridge.RESTORATION_PREFIX
                    + (watchProgressSnapshotProfileId > 0 ? watchProgressSnapshotProfileId : 1) + "_";
            long now = System.currentTimeMillis();
            for (String key : new String[] { stableKey, legacyKey, suppressionKey }) restored.putLong(prefix + key, now);
            for (WatchProgress progress : canonicalProgressForProgram(program)) {
                restored.putLong(prefix + progress.getStorageKey(), now);
                restored.putLong(prefix + progress.getContentId(), now);
            }
            if (program != null && FILE_VIDEO_RESUME_SOURCE.equals(program.sourcePackage)) {
                restored.putLong(prefix + program.intentUri.replaceFirst("^file://", ""), now);
            }
            restored.apply();
        }
    }

