    private void showContinueWatchingMenu(JojoProgram program, View anchor,
                                          boolean fromFavoriteRow, boolean fromHomeHero,
                                          View categoryHeroAnchor) {
        boolean fromSuggestions = isHomeSuggestionCard(anchor);
        LinearLayout menu = new LinearLayout(this); menu.setOrientation(LinearLayout.VERTICAL); menu.setBackground(lightMenuBg());
        PopupWindow popup = new PopupWindow(menu, dp(300), -2, true); popup.setBackgroundDrawable(lightMenuBg()); popup.setOutsideTouchable(true); popup.setElevation(dp(12)); trackPopup(popup);
        View unwatched = popupRow(R.drawable.ic_reset_arrow, "Marquer comme non vu");
        View restart = popupRow(R.drawable.ic_reset_arrow, "Reprendre depuis le début");
        ImageView homePoster = fromHomeHero ? homeHeroPosterView(anchor) : null;
        View posterArtwork = homePoster == null ? null
                : popupRow(R.drawable.ic_menu_wallpaper, "Changer de vignette");
        View artwork = popupRow(R.drawable.ic_menu_wallpaper,
                fromHomeHero ? "Changer la vignette du Hero" : "Changer de vignette");
        View heroArtwork = categoryHeroAnchor != null && !fromHomeHero
                ? popupRow(R.drawable.ic_menu_wallpaper, "Changer la vignette du Hero") : null;
        boolean fromVideoLibrary = !fromHomeHero && (categoryHeroAnchor != null || fromSuggestions)
                && (FILE_VIDEO_RESUME_SOURCE.equals(program.sourcePackage)
                || FREEBOX_FOLDER_SOURCE.equals(program.sourcePackage));
        View remove = popupRow(R.drawable.ic_menu_delete,
                fromHomeHero && "external-playback".equals(program.sourcePackage)
                        ? "Supprimer de la liste et des favoris" : fromFavoriteRow ? "Retirer des favoris"
                        : !fromVideoLibrary && FILE_VIDEO_RESUME_SOURCE.equals(program.sourcePackage)
                        ? "Retirer de Continuer à regarder" : "Supprimer de la liste");
        menu.addView(unwatched);
        if (!isExternalLiveProgram(program)) menu.addView(restart);
        if (posterArtwork != null) menu.addView(posterArtwork);
        menu.addView(artwork);
        if (heroArtwork != null) menu.addView(heroArtwork);
        View move = fromFavoriteRow && "live".equals(homeCategoryPages.get(activeScreen))
                && beginLiveChannelGridMove != null ? popupRow(R.drawable.ic_menu_move, "Déplacer") : null;
        if (move != null) {
            android.graphics.Path cross = new android.graphics.Path();
            cross.addRect(11f, 3f, 13f, 21f, android.graphics.Path.Direction.CW);
            cross.addRect(3f, 11f, 21f, 13f, android.graphics.Path.Direction.CW);
            cross.moveTo(12f, 1f); cross.lineTo(16f, 5f); cross.lineTo(8f, 5f); cross.close();
            cross.moveTo(12f, 23f); cross.lineTo(8f, 19f); cross.lineTo(16f, 19f); cross.close();
            cross.moveTo(1f, 12f); cross.lineTo(5f, 8f); cross.lineTo(5f, 16f); cross.close();
            cross.moveTo(23f, 12f); cross.lineTo(19f, 16f); cross.lineTo(19f, 8f); cross.close();
            android.graphics.drawable.ShapeDrawable icon = new android.graphics.drawable.ShapeDrawable(
                    new android.graphics.drawable.shapes.PathShape(cross, 24f, 24f));
            icon.getPaint().setColor(Color.WHITE);
            icon.setIntrinsicWidth(dp(24));
            icon.setIntrinsicHeight(dp(24));
            ((ImageView) ((LinearLayout) move).getChildAt(0)).setImageDrawable(icon);
        }
        if (move != null) menu.addView(move);
        menu.addView(remove);
        View deleteFreebox = null;
        if (isFreeboxResume(program)) {
            deleteFreebox = popupRow(R.drawable.ic_menu_delete, "Supprimer de la Freebox");
            deleteFreebox.setBackgroundColor(Color.rgb(110, 24, 30));
            menu.addView(deleteFreebox);
        }
        if ((fromHomeHero || fromSuggestions || homeCategoryPages.containsKey(activeScreen)
                || freeboxFolderPageUrls.containsKey(activeScreen))
                && (FILE_VIDEO_RESUME_SOURCE.equals(program.sourcePackage)
                || "external-playback".equals(program.sourcePackage))) {
            addOpenWithMenuRow(menu, popup, fromHomeHero ? "Accueil › Hero"
                            : fromSuggestions ? "Accueil › Suggestions"
                            : homeCategoryTitle(homeCategoryPages.get(activeScreen)),
                    playerPackage -> {
                        if (FILE_VIDEO_RESUME_SOURCE.equals(program.sourcePackage))
                            openFileVideoResume(program, false, playerPackage);
                        else openExternalPlayback(externalResumeItem(program), !fromHomeHero, false, playerPackage);
                    });
        }
        finalizePopupMenu(menu);
        View finalDeleteFreebox = deleteFreebox;
        unwatched.setOnClickListener(v -> { popup.dismiss(); markResumeAsUnwatched(program, anchor); });
        restart.setOnClickListener(v -> { popup.dismiss(); restartContinueWatchingProgram(program); });
        if (posterArtwork != null) posterArtwork.setOnClickListener(v -> {
            popup.dismiss();
            chooseResumeArtwork(program, homePoster, false, true);
        });
        artwork.setOnClickListener(v -> {
            popup.dismiss();
            chooseResumeArtwork(program, anchor, fromHomeHero);
        });
        if (heroArtwork != null) heroArtwork.setOnClickListener(v -> {
            popup.dismiss();
            chooseCategoryHeroArtwork(program, categoryHeroAnchor, anchor);
        });
        if (move != null) move.setOnClickListener(v -> {
            popup.dismiss();
            beginLiveChannelGridMove.onClick(anchor);
        });
        remove.setOnClickListener(v -> {
            popup.dismiss();
            if (fromHomeHero) removeHomeHeroContinueWatching(program, anchor, true);
            else if (fromFavoriteRow) removeExternalFavorite(program, anchor);
            else if (fromVideoLibrary) removeVideoFromHomeLists(program, anchor);
            else removeContinueWatchingProgram(program, anchor);
        });
        if (finalDeleteFreebox != null) finalDeleteFreebox.setOnClickListener(v -> { popup.dismiss(); requestFreeboxResumeDeletion(program); });
        showPopupBelow(popup, anchor, 0, dp(4));
        unwatched.requestFocus();
    }

    private void removeHomeHeroContinueWatching(JojoProgram selected, View card, boolean removeFavorite) {
        final JojoProgram program = capturedHomeRemovalProgram(selected);
        if (program == null) return;
        if (!"external-playback".equals(program.sourcePackage)) {
            removeContinueWatchingProgram(program, card);
            return;
        }
        if (program.intentUri == null || program.intentUri.isEmpty()) return;
        String resolvedFavoriteRecordId = program.intentUri;
        if (removeFavorite && !program.intentUri.startsWith("iptv:")) {
            JSONObject playback = ExternalPlaybackStore.get(getApplicationContext(), program.intentUri);
            if ("series".equals(playback.optString("category"))) {
                String seriesFavoriteId = externalPlaybackHeroFavorite(playback).optString("id", "");
                if (!seriesFavoriteId.isEmpty()) resolvedFavoriteRecordId = seriesFavoriteId;
            }
        }
        final String favoriteRecordId = resolvedFavoriteRecordId;
        final boolean canonicalRemoval = !canonicalProgressForProgram(program).isEmpty();
        dismissResumeLocally(program);
        if (!pendingExternalRemovals.add(program.intentUri)) return;
        if (removeFavorite && !favoriteRecordId.equals(program.intentUri)) {
            pendingExternalRemovals.add(favoriteRecordId);
        }
        if (removeFavorite) prunePendingHomeFavoriteSnapshots();
        long navigation = ++homeFocusGeneration;
        boolean reboundImmediately = refreshModernHeroImmediatelyAfterRemoval(program);
        if (!reboundImmediately) {
            removeResumeCards(program, card);
            refreshHomeResumeSectionInPlace();
        }
        // Use the pruned snapshots: rereading the store can wait for the pending write.
        renderExternalPlaybackRows(new HashSet<>(homeCategoryFavoriteSnapshots.keySet()));
        Toast.makeText(this, removeFavorite ? "Vidéo retirée de la liste et des favoris"
                : "Vidéo retirée de la liste", Toast.LENGTH_SHORT).show();
        resumeMutationExecutor.execute(() -> {
            boolean saved = false;
            boolean localOnly = false;
            try {
                if (removeFavorite) {
                    JSONObject favorite = ExternalPlaybackStore.get(getApplicationContext(), favoriteRecordId);
                    saved = "series".equals(favorite.optString("category"))
                            ? ExternalPlaybackStore.removeSeriesFavoriteFromHomeLists(getApplicationContext(), favoriteRecordId)
                            : ExternalPlaybackStore.removeFromHomeLists(getApplicationContext(), favoriteRecordId);
                } else {
                    saved = ExternalPlaybackStore.removeFromContinueWatching(getApplicationContext(), program.intentUri)
                            || canonicalRemoval;
                    if (!saved) {
                        JSONObject stored = ExternalPlaybackStore.get(getApplicationContext(), program.intentUri);
                        localOnly = !program.intentUri.equals(stored.optString("id"))
                                || !ExternalPlaybackStore.supportedUrl(stored.optString("url", ""));
                    }
                }
            } catch (RuntimeException error) {
                android.util.Log.e("JojoHomeResume", "REMOVE_HOME_HERO_FAILED", error);
            }
            final boolean success = saved || localOnly;
            runOnUiThread(() -> {
                if (success && removeFavorite) prunePendingHomeFavoriteSnapshots();
                pendingExternalRemovals.remove(program.intentUri);
                if (removeFavorite) pendingExternalRemovals.remove(favoriteRecordId);
                if (isDestroyed()) return;
                if (!success) {
                    clearResumeDismissal(program);
                    Toast.makeText(this, "Suppression impossible, réessayez", Toast.LENGTH_LONG).show();
                }
                if (removeFavorite) refreshActiveHomeCategoryPage();
                if (activeScreen != null || navigation != homeFocusGeneration) return;
                renderExternalPlaybackRows();
                if (!reboundImmediately || !success) refreshHomeResumeSectionInPlace();
            });
        });
    }

    private void showResumeVideoFrameChooser(JojoProgram program, View anchor, boolean heroSelection, PopupWindow artworkPopup) {
        if (program == null || program.intentUri == null || program.intentUri.isEmpty()) return;
        VideoFrameSource source;
        try {
            source = resumeVideoFrameSourceForProgram(program);
        } catch (Exception error) {
            android.util.Log.w("JojoHomeArtwork", "FRAME_SOURCE_UNAVAILABLE", error);
            Toast.makeText(this, "Impossible d’accéder à la vidéo pour extraire une image", Toast.LENGTH_LONG).show();
            return;
        }
        artworkPopup.dismiss();
        showVideoFrameChooser(program.title, source, anchor, program.intentUri,
                heroSelection ? resumeDismissKey(program) : null, !heroSelection);
    }

    private void updateExternalPlaybackFromMenu(JojoProgram program, boolean deleted) {
        JSONObject item = externalResumeItem(program);
        try {
            // The popup owns window focus until dismissal. Restore its source
            // card explicitly before taking the row's replacement snapshot.
            for (LinearLayout rows : currentExternalRows.values()) {
                View anchor = rows.findViewWithTag(resumeDismissKey(program));
                if (anchor != null && anchor.isAttachedToWindow()) { anchor.requestFocus(); break; }
            }
            item.put("position", 0L).put("started", false).put("deleted", deleted);
            ExternalPlaybackStore.save(this, item);
            renderExternalPlaybackRows();
            refreshHomeResumeSectionInPlace();
        } catch (org.json.JSONException error) {
            Toast.makeText(this, "Impossible de modifier la vidéo", Toast.LENGTH_SHORT).show();
        }
    }

    private void markResumeAsUnwatched(JojoProgram program, View card) {
        if (program == null) return;
        if ("external-playback".equals(program.sourcePackage)
                || "external-playback-series-episode".equals(program.sourcePackage)) {
            markExternalPlaybackAsUnwatched(program, card);
            return;
        }
        if (FILE_VIDEO_RESUME_SOURCE.equals(program.sourcePackage)) {
            removeFileVideoResume(program, card);
            Toast.makeText(this, "Contenu marqué comme non vu", Toast.LENGTH_SHORT).show();
            return;
        }
        // External providers do not expose one common reset API. Keep the
        // launcher state coherent by removing the current resume card; a new
        // playback session can publish it again normally.
        dismissResumeLocally(program);
        removeResumeCards(program, card);
        Toast.makeText(this, "Contenu marqué comme non vu", Toast.LENGTH_SHORT).show();
    }

    private void removeFileVideoResume(JojoProgram program, View card) {
        boolean reboundImmediately = refreshModernHeroImmediatelyAfterRemoval(program);
        List<JojoProgram> remainingPrograms = cachedContinueWatchingHomePrograms();
        String removedKey = resumeDismissKey(program);
        remainingPrograms.removeIf(candidate -> removedKey.equals(resumeDismissKey(candidate)));
        clearVideoResume(program.intentUri);
        restoreFreeboxVideoInHomeCache(program);
        // Clearing one file resume invalidates the persisted Continue Watching
        // snapshot. Keep the other cards available while providers refresh it.
        cacheContinueWatchingHomePrograms(remainingPrograms);
        refreshHomeVideosSectionInPlace(true);
        if (!reboundImmediately) {
            removeResumeCards(program, card);
            refreshHomeResumeSectionInPlace();
        }
    }

    private void markExternalPlaybackAsUnwatched(JojoProgram selected, View card) {
        if (selected.intentUri == null || selected.intentUri.isEmpty()) {
            Toast.makeText(this, "Impossible de marquer comme non vu", Toast.LENGTH_SHORT).show();
            return;
        }
        final JojoProgram program = capturedHomeRemovalProgram(selected);
        final int profileId = HomeWatchProgressBridge.currentProfileId(this);
        resumeMutationExecutor.execute(() -> {
            boolean saved = false;
            try {
                saved = ExternalPlaybackStore.markUnwatched(getApplicationContext(), program.intentUri, profileId);
            } catch (Exception error) {
                android.util.Log.w("JojoHomeResume", "Unwatched reset failed: " + error.getClass().getSimpleName());
            }
            final boolean success = saved;
            runOnUiThread(() -> {
                if (isFinishing() || isDestroyed() || profileId != HomeWatchProgressBridge.currentProfileId(this)) return;
                if (program.intentUri.startsWith("iptv:") && !program.intentUri.equals(
                        com.jojotv.home.iptv.IptvStore.homeRemovalContentId(
                                com.jojotv.home.iptv.IptvStore.catalogContentId(program.intentUri)))) return;
                if (!success) {
                    Toast.makeText(this, "Impossible de marquer comme non vu", Toast.LENGTH_SHORT).show();
                    return;
                }
                refreshExternalPlaybackAfterUnwatched(program, card);
            });
        });
    }

    private void refreshExternalPlaybackAfterUnwatched(JojoProgram program, View card) {
        boolean nativeIptv = program.intentUri.startsWith("iptv:");
        String nativeResumeKey = nativeIptv
                ? com.jojotv.home.iptv.IptvStore.homeResumeDismissalKey(program.intentUri) : "";
        if (nativeIptv) {
            List<WatchProgress> remainingProgress = new ArrayList<>(watchProgressContinueSnapshot);
            remainingProgress.removeIf(progress -> nativeResumeKey.equals("external-playback|" + progress.getContentId()));
            watchProgressContinueSnapshot = remainingProgress;
        }
        for (List<JSONObject> favorites : homeCategoryFavoriteSnapshots.values()) {
            for (JSONObject favorite : favorites) {
                String id = favorite.optString("id");
                if (!program.intentUri.equals(id) && !(nativeIptv && id.startsWith("iptv:")
                        && nativeResumeKey.equals(com.jojotv.home.iptv.IptvStore.homeResumeDismissalKey(id)))) continue;
                try { favorite.put("position", 0L).put("started", false).put("watched", false).put("seriesStarted", false); }
                catch (org.json.JSONException ignored) { }
            }
        }
        // Keep the favorite in Films/Séries, but remove its old resume snapshot
        // so Home cannot resurrect the stale Hero on the next visit.
        List<JojoProgram> remainingPrograms = cachedContinueWatchingHomePrograms();
        String removedKey = resumeDismissKey(program);
        remainingPrograms.removeIf(candidate -> removedKey.equals(resumeDismissKey(candidate))
                || nativeIptv && candidate.intentUri != null && candidate.intentUri.startsWith("iptv:")
                && nativeResumeKey.equals(com.jojotv.home.iptv.IptvStore.homeResumeDismissalKey(candidate.intentUri))
                || isExternalPlaybackResumeSource(candidate.sourcePackage)
                && isExternalPlaybackResumeSource(program.sourcePackage)
                && program.intentUri.equals(candidate.intentUri));
        cacheContinueWatchingHomePrograms(remainingPrograms);

        // The selected Films tile is built from a snapshot. Rebuild the open
        // category page now so its En cours badge reflects the reset state.
        refreshActiveHomeCategoryPage();
        renderExternalPlaybackRows();
        if (!refreshModernHeroImmediatelyAfterRemoval(program)) {
            removeResumeCards(program, card);
            refreshHomeResumeSectionInPlace();
        }
        Toast.makeText(this, "Contenu marqué comme non vu", Toast.LENGTH_SHORT).show();
    }

    private void restartContinueWatchingProgram(JojoProgram program) {
        if (program == null) return;
        if ("external-playback".equals(program.sourcePackage)) {
            updateExternalPlaybackFromMenu(program, false);
            openExternalPlayback(externalResumeItem(program), false, true);
            return;
        }
        if (FILE_VIDEO_RESUME_SOURCE.equals(program.sourcePackage)) {
            clearVideoResume(program.intentUri);
            openFileVideoResume(program, true);
            return;
        }
        try {
            Intent intent = Intent.parseUri(program.intentUri, Intent.URI_INTENT_SCHEME);
            if (isSmartTubePackage(program.sourcePackage)) {
                intent = smartTubeStartIntent(intent);
            } else if (isJojoTvResume(program, intent)) {
                intent.putExtra("androidTvPosition", 0L).putExtra("androidTvLastWatched", 0L);
                Intent playerIntent = directJojoTvPlayerIntent(intent);
                if (playerIntent != null) intent = playerIntent;
            }
            startActivity(intent);
        } catch (Exception ignored) {
            openJojoProgram(program);
        }
    }

    private Intent smartTubeStartIntent(Intent source) {
        if (source == null || source.getData() == null) return source;
        Uri data = source.getData();
        Uri.Builder builder = data.buildUpon().clearQuery();
        for (String name : data.getQueryParameterNames()) {
            if (!"t".equals(name)) {
                for (String value : data.getQueryParameters(name)) builder.appendQueryParameter(name, value);
            }
        }
        source.setData(builder.build());
        return source;
    }

    private boolean isFreeboxResume(JojoProgram program) {
        String contentId = decodedJojoIntentExtra(program == null ? null : program.intentUri, "contentId");
        String contentType = decodedJojoIntentExtra(program == null ? null : program.intentUri, "contentType");
        if (contentId != null && contentId.toLowerCase(Locale.ROOT).startsWith("freebox:")) return true;
        if ("freebox".equalsIgnoreCase(contentType)) return true;
        return program != null && FILE_VIDEO_RESUME_SOURCE.equals(program.sourcePackage)
                && program.intentUri != null
                && program.intentUri.toLowerCase(Locale.ROOT).startsWith("smb://");
    }

    private String freeboxResumePath(JojoProgram program) {
        if (program == null) return "";
        if (program.intentUri != null && program.intentUri.startsWith("smb://")) return program.intentUri;
        String contentId = decodedJojoIntentExtra(program.intentUri, "contentId");
        if (contentId != null && contentId.regionMatches(true, 0, "freebox:", 0, 8)) {
            return com.nuvio.tv.data.freebox.FreeboxMediaDisplayKt.freeboxPathFromContentId(contentId);
        }
        return "";
    }

    private String decodedJojoIntentExtra(String intentUri, String name) {
        String value = SystemContinueWatching.jojoIntentExtra(intentUri, name);
        if (value == null) return null;
        try { return java.net.URLDecoder.decode(value, "UTF-8"); }
        catch (Exception ignored) { return value; }
    }

