    private void chooseCategoryHeroArtwork(JojoProgram fallback, View hero, View thumbnail) {
        if (hero == null) return;
        Object displayed = hero.getTag(CATEGORY_HERO_PROGRAM_TAG);
        JojoProgram program = displayed instanceof JojoProgram ? (JojoProgram) displayed : fallback;
        if (program == null) return;
        if (thumbnail != null) {
            if (thumbnail.getId() == View.NO_ID) thumbnail.setId(View.generateViewId());
            hero.setNextFocusDownId(thumbnail.getId());
        }
        if (FREEBOX_FOLDER_SOURCE.equals(program.sourcePackage)) {
            chooseFreeboxFolderArtwork(program, hero, true);
        } else {
            Object provider = hero.getTag(CATEGORY_HERO_ITEM_TAG);
            showResumeArtworkPicker(program, hero, true, null, (preview, artworkUrl) -> {
                if (thumbnail != null && thumbnail.isAttachedToWindow()) thumbnail.requestFocus();
            }, provider instanceof JSONObject ? (JSONObject) provider : null);
        }
    }

    private static final class ResumeArtworkCandidate {
        final String url;
        final String title;
        final String year;
        final String source;
        final int tmdbId;
        final String tmdbMediaType;
        final String overview;
        final Boolean landscape;
        ResumeArtworkCandidate(String url, String title, String year) {
            this(url, title, year, "TMDB", 0, "", "", null);
        }
        ResumeArtworkCandidate(String url, String title, String year, String source) {
            this(url, title, year, source, 0, "", "", null);
        }
        ResumeArtworkCandidate(String url, String title, String year, String source,
                               int tmdbId, String tmdbMediaType, String overview) {
            this(url, title, year, source, tmdbId, tmdbMediaType, overview, null);
        }
        ResumeArtworkCandidate(String url, String title, String year, String source,
                               int tmdbId, String tmdbMediaType, String overview,
                               Boolean landscape) {
            this.url = url;
            this.title = title;
            this.year = year;
            this.source = source;
            this.tmdbId = tmdbId;
            this.tmdbMediaType = tmdbMediaType == null ? "" : tmdbMediaType;
            this.overview = overview == null ? "" : overview;
            this.landscape = landscape;
        }
    }

    private boolean tmdbArtworkTitleMatches(String sourceTitle, String query, String candidateTitle) {
        String source = normalizeTmdbArtworkText(sourceTitle);
        String searched = normalizeTmdbArtworkText(query);
        String candidate = normalizeTmdbArtworkText(candidateTitle);
        if (candidate.isEmpty()) return false;
        if (candidate.equals(searched) || candidate.equals(source)) return true;
        // TMDB can append a descriptive subtitle to the programme name:
        // "Détox ta maison" -> "Détox ta maison : 7 jours pour tout ranger".
        if (searched.length() >= 12 && searched.split(" ").length >= 3
                && candidate.startsWith(searched + " ")) return true;
        // A one-word title is too ambiguous for fuzzy matching (for example
        // "Prisoner" must not select "Prisoners" or "Prison Valley").
        if (!searched.contains(" ") || !candidate.contains(" ")) return false;
        if (!searched.isEmpty() && (searched.contains(candidate) || candidate.contains(searched))) {
            int shorter = Math.min(searched.length(), candidate.length());
            int longer = Math.max(searched.length(), candidate.length());
            if (shorter >= 5 && shorter >= Math.round(longer * 0.80f)) return true;
        }
        String[] searchedTokens = searched.split("\\s+");
        String[] candidateTokens = candidate.split("\\s+");
        java.util.HashSet<String> searchedWords = new java.util.HashSet<>();
        for (String word : searchedTokens) if (word.length() >= 3) searchedWords.add(word);
        java.util.HashSet<String> candidateWords = new java.util.HashSet<>();
        for (String word : candidateTokens) if (word.length() >= 3) candidateWords.add(word);
        if (searchedWords.isEmpty() || candidateWords.isEmpty()) return false;
        int matches = 0;
        for (String word : candidateWords) if (searchedWords.contains(word)) matches++;
        // IPTV providers often prepend a franchise or channel qualifier to the
        // title.  TMDB may index only the canonical suffix (for example,
        // "Paris Has Fallen" is indexed as "Has Fallen").  Accept that
        // unambiguous case while still requiring every meaningful TMDB token
        // to be present in the searched title.
        if (matches >= 2
                && matches == candidateWords.size()
                && searchedWords.size() - matches <= 1) return true;
        // Reject broad results that merely share two generic words. A result
        // must cover most of both the searched title and the TMDB title.
        return matches >= 2
                && matches >= Math.ceil(searchedWords.size() * 0.70d)
                && matches >= Math.ceil(candidateWords.size() * 0.80d);
    }

    private String normalizeTmdbArtworkText(String value) {
        if (value == null) return "";
        return Normalizer.normalize(value, Normalizer.Form.NFD)
                .replaceAll("\\p{M}", "")
                .toLowerCase(Locale.ROOT)
                .replace("’", " ").replace("'", " ")
                .replaceAll("[^\\p{L}\\p{N}]+", " ")
                .replaceAll("\\s+", " ").trim();
    }

    private String providerArtworkYear(JSONObject provider, String fallbackTitle) {
        String year = HomeMediaRules.providerArtworkYear(
                firstExternalValue(provider, "year", "first_air_date", "release_date", "releaseDate"),
                firstExternalValue(provider, "providerTitle", "title"));
        return year.isEmpty() ? HomeMediaRules.providerArtworkYear("", fallbackTitle) : year;
    }

    private List<ResumeArtworkCandidate> filterArtworkCandidatesByYear(
            List<ResumeArtworkCandidate> candidates, String expectedYear) {
        if (candidates == null || expectedYear == null || expectedYear.isEmpty()) return candidates;
        ArrayList<ResumeArtworkCandidate> filtered = new ArrayList<>();
        for (ResumeArtworkCandidate candidate : candidates) {
            if (candidate == null) continue;
            // Official-site results do not always expose a release year. Keep
            // those fallbacks, but only keep TMDB results from the exact year.
            if ("TMDB".equals(candidate.source) && !expectedYear.equals(candidate.year)) continue;
            filtered.add(candidate);
        }
        return filtered;
    }

    private String tmdbImagePath(JSONObject item, String field) {
        if (item == null) return "";
        String path = item.optString(field, "").trim();
        return path.isEmpty() || "null".equalsIgnoreCase(path) ? "" : path;
    }

    private boolean hasTmdbImagePath(JSONArray images) {
        if (images == null) return false;
        for (int index = 0; index < images.length(); index++) {
            if (!tmdbImagePath(images.optJSONObject(index), "file_path").isEmpty()) return true;
        }
        return false;
    }

    private List<ResumeArtworkCandidate> findResumeArtworkCandidates(String title) throws Exception {
        return findResumeArtworkCandidates(title, null);
    }

    private List<ResumeArtworkCandidate> findResumeArtworkCandidates(String title, JSONObject provider) throws Exception {
        ArrayList<ResumeArtworkCandidate> candidates = new ArrayList<>();
        if (title == null || title.trim().isEmpty() || BuildConfig.TMDB_API_KEY == null || BuildConfig.TMDB_API_KEY.trim().isEmpty()) return candidates;
        String category = provider == null ? "" : provider.optString("category", "");
        String expectedType = "series".equals(category) ? "tv" : "movies".equals(category) ? "movie"
                : provider == null ? "" : provider.optString("tmdbMediaType", provider.optString("mediaType", ""));
        if ("series".equals(expectedType)) expectedType = "tv";
        if ("movies".equals(expectedType)) expectedType = "movie";
        if (!"tv".equals(expectedType) && !"movie".equals(expectedType)) expectedType = "";
        int expectedId = provider == null ? 0 : provider.optInt("tmdbId", provider.optInt("tmdb_id", 0));
        String expectedYear = provider == null ? "" : providerArtworkYear(provider, title);
        java.util.LinkedHashSet<String> queries = new java.util.LinkedHashSet<>(provider == null
                ? videoArtworkSearchTitles(title, null) : HomeMediaRules.providerArtworkSearchTitles(title));
        String normalized = provider == null ? videoArtworkSearchTitle(title, null)
                : queries.isEmpty() ? title.trim() : queries.iterator().next();
        JSONObject known = expectedId > 0 && !expectedType.isEmpty() ? fetchJson(
                "https://api.themoviedb.org/3/" + expectedType + "/" + expectedId + "?api_key="
                        + java.net.URLEncoder.encode(BuildConfig.TMDB_API_KEY, "UTF-8") + "&language=fr-FR") : null;
        // TiviMate prefixes channel names with the country/provider and often
        // appends the broadcast quality (for example "FR | TF1 FHD"). These
        // transport labels are not part of the artwork search identity.
        normalized = normalized.replaceFirst("(?i)^\\s*[a-z]{2}\\s*[|:/-]\\s*", "")
                .replaceFirst("(?i)\\s+(?:FHD|UHD|HD|SD|H265|HEVC)\\s*$", "")
                .trim();
        if (!normalized.isEmpty()) queries.add(normalized);
        String accentFree = normalizeTmdbArtworkText(normalized);
        if (!accentFree.isEmpty()) queries.add(accentFree);
        String apostropheFree = normalized.replaceAll("[’']", " ").replaceAll("\\s+", " ").trim();
        if (!apostropheFree.isEmpty()) queries.add(apostropheFree);
        String prefix = normalized.replaceFirst("\\s+[-–—|:]\\s+.*$", "").trim();
        if (prefix.length() >= 3) queries.add(prefix);
        // Search the canonical suffix as well. IPTV names frequently contain
        // a localised/franchise prefix that is absent from the TMDB title.
        String suffix = normalized.replaceFirst("^\\S+\\s+", "").trim();
        if (suffix.length() >= 3 && suffix.contains(" ")) queries.add(suffix);
        Set<String> inspectedTitles = new HashSet<>();
        tmdbSearch:
        for (String language : new String[] { "fr-FR", "en-US" }) {
            for (String query : queries) {
                for (int page = 1; page <= 3 && candidates.size() < 24; page++) {
                    String endpoint = "https://api.themoviedb.org/3/search/multi?api_key="
                            + java.net.URLEncoder.encode(BuildConfig.TMDB_API_KEY, "UTF-8")
                            + "&language=" + language + "&include_adult=false&page=" + page + "&query="
                            + java.net.URLEncoder.encode(query, "UTF-8");
                    JSONArray results = known == null ? fetchJson(endpoint).optJSONArray("results") : new JSONArray().put(known);
                    if (results == null) continue;
                    for (int index = 0; index < results.length() && candidates.size() < 24; index++) {
                        JSONObject result = results.optJSONObject(index);
                        String mediaType = result == null ? "" : result.optString("media_type", "");
                        if (mediaType.isEmpty() && result != null) {
                            mediaType = result.has("title") ? "movie" : result.has("name") ? "tv" : "";
                        }
                        if (result == null || !("movie".equals(mediaType) || "tv".equals(mediaType))) continue;
                        String resultTitle = result.optString("title", result.optString("name", "Résultat TMDB"));
                        if (known == null && !tmdbArtworkTitleMatches(normalized, query, resultTitle)) continue;
                        String date = result.optString("release_date", result.optString("first_air_date", ""));
                        String year = date.length() >= 4 ? date.substring(0, 4) : "";
                        if (provider != null && !HomeMediaRules.providerArtworkIdentityMatches(expectedType, expectedId,
                                expectedYear, mediaType, result.optInt("id"), year)) continue;
                        // The year in a recording name is often the broadcast
                        // year, not TMDB's first-air/release year. Keep it as
                        // metadata, but never reject an otherwise exact title.
                        // Continue Watching cards are landscape. Search results
                        // expose only one backdrop, while the images endpoint
                        // contains the complete set of relevant landscape
                        // artwork for the matched movie/series.
                        JSONArray backdrops = null;
                        JSONArray posters = null;
                        int resultId = result.optInt("id", 0);
                        if (resultId <= 0 || !inspectedTitles.add(mediaType + ":" + resultId)) continue;
                        if (resultId > 0) {
                            String imagesEndpoint = "https://api.themoviedb.org/3/" + mediaType + "/" + resultId
                                    + "/images?api_key=" + java.net.URLEncoder.encode(BuildConfig.TMDB_API_KEY, "UTF-8")
                                    + "&include_image_language=fr,null,en";
                            JSONObject images = fetchJson(imagesEndpoint);
                            backdrops = images.optJSONArray("backdrops");
                            posters = images.optJSONArray("posters");
                        }
                        JSONObject details = null;
                        String fallbackBackdrop = tmdbImagePath(result, "backdrop_path");
                        String fallbackPoster = tmdbImagePath(result, "poster_path");
                        if ((!hasTmdbImagePath(backdrops) && fallbackBackdrop.isEmpty())
                                || (!hasTmdbImagePath(posters) && fallbackPoster.isEmpty())) {
                            String detailsEndpoint = "https://api.themoviedb.org/3/" + mediaType + "/" + resultId
                                    + "?api_key=" + java.net.URLEncoder.encode(BuildConfig.TMDB_API_KEY, "UTF-8")
                                    + "&language=" + language;
                            try { details = fetchJson(detailsEndpoint); }
                            catch (Exception ignored) { }
                            if (fallbackBackdrop.isEmpty()) fallbackBackdrop = tmdbImagePath(details, "backdrop_path");
                            if (fallbackPoster.isEmpty()) fallbackPoster = tmdbImagePath(details, "poster_path");
                        }
                        if (!hasTmdbImagePath(backdrops)) {
                            backdrops = new JSONArray();
                            if (!fallbackBackdrop.isEmpty())
                                backdrops.put(new JSONObject().put("file_path", fallbackBackdrop));
                        }
                        if (!hasTmdbImagePath(posters)) {
                            posters = new JSONArray();
                            if (!fallbackPoster.isEmpty())
                                posters.put(new JSONObject().put("file_path", fallbackPoster));
                        }
                        JSONArray[] imageSets = { backdrops, posters };
                        for (JSONArray imageSet : imageSets) {
                            if (imageSet == null) continue;
                            // Keep both TMDB orientations available.  The
                            // previous global limit was reached by backdrops
                            // before posters were even inspected, so Portrait
                            // mode could falsely report no result.
                            int imageSetCount = 0;
                            for (int imageIndex = 0; imageIndex < imageSet.length()
                                    && candidates.size() < 24 && imageSetCount < 12; imageIndex++) {
                                JSONObject artwork = imageSet.optJSONObject(imageIndex);
                                String filePath = tmdbImagePath(artwork, "file_path");
                                if (filePath.isEmpty()) continue;
                                String imageUrl = "https://image.tmdb.org/t/p/w780" + filePath;
                                boolean duplicate = false;
                                for (ResumeArtworkCandidate candidate : candidates) if (candidate.url.equals(imageUrl)) { duplicate = true; break; }
                                if (!duplicate) {
                                    double aspectRatio = artwork == null ? 0d : artwork.optDouble("aspect_ratio", 0d);
                                    Boolean landscape = aspectRatio > 0d
                                            ? (aspectRatio == 1d ? null : aspectRatio > 1d)
                                            : imageSet == backdrops;
                                    candidates.add(new ResumeArtworkCandidate(
                                            imageUrl, resultTitle, year, "TMDB", resultId, mediaType,
                                            result.optString("overview", ""), landscape));
                                    imageSetCount++;
                                }
                            }
                        }
                        if (candidates.size() >= 24) break tmdbSearch;
                    }
                    if (known != null) break tmdbSearch;
                }
            }
        }
        return candidates;
    }

    private static final int MAX_ARTWORK_SEARCH_RESPONSE_BYTES = 2 * 1024 * 1024;

    private String fetchText(String address) throws IOException {
        java.net.HttpURLConnection connection = (java.net.HttpURLConnection) new URL(address).openConnection();
        connection.setConnectTimeout(7000);
        connection.setReadTimeout(10000);
        connection.setRequestProperty("User-Agent", "JojoHome/1.0");
        try (java.io.InputStream input = connection.getInputStream();
             java.io.ByteArrayOutputStream result = new java.io.ByteArrayOutputStream(32 * 1024)) {
            byte[] buffer = new byte[8192];
            int totalBytes = 0;
            while (totalBytes < MAX_ARTWORK_SEARCH_RESPONSE_BYTES) {
                int count = input.read(buffer, 0,
                        Math.min(buffer.length, MAX_ARTWORK_SEARCH_RESPONSE_BYTES - totalBytes));
                if (count == -1) break;
                if (count == 0) continue;
                result.write(buffer, 0, count);
                totalBytes += count;
            }
            return result.toString("UTF-8");
        } finally { connection.disconnect(); }
    }

    private static final class OfficialArtworkSource {
        final String name;
        final String searchUrl;
        OfficialArtworkSource(String name, String searchUrl) {
            this.name = name;
            this.searchUrl = searchUrl;
        }
    }

    private String normalizedHtmlText(String html) {
        return normalizeTmdbArtworkText(html == null ? "" : html);
    }

    private List<ResumeArtworkCandidate> findOfficialArtworkCandidates(String title, OfficialArtworkSource source) throws Exception {
        return findOfficialArtworkCandidates(title, source, false);
    }

    private List<ResumeArtworkCandidate> findOfficialArtworkCandidates(String title, OfficialArtworkSource source, boolean providerTitle) throws Exception {
        ArrayList<ResumeArtworkCandidate> result = new ArrayList<>();
        List<String> providerQueries = providerTitle ? HomeMediaRules.providerArtworkSearchTitles(title) : Collections.emptyList();
        String query = providerTitle ? providerQueries.isEmpty() ? "" : providerQueries.get(0) : videoArtworkSearchTitle(title, null);
        if (query.isEmpty()) return result;
        String html = fetchText(source.searchUrl + java.net.URLEncoder.encode(query, "UTF-8"));
        String normalizedQuery = normalizeTmdbArtworkText(query);
        if (normalizedQuery.isEmpty() || !normalizedHtmlText(html).contains(normalizedQuery)) return result;
        html = html.replace("\\u002F", "/").replace("\\/", "/")
                .replace("&amp;", "&").replace("\\u0026", "&");
        java.util.regex.Matcher matcher = java.util.regex.Pattern.compile(
                "https?://[^\\\"'<> ]+?\\.(?:jpg|jpeg|png|webp)(?:\\?[^\\\"'<> ]*)?",
                java.util.regex.Pattern.CASE_INSENSITIVE).matcher(html);
        java.util.LinkedHashSet<String> urls = new java.util.LinkedHashSet<>();
        while (matcher.find() && urls.size() < 8) {
            String url = matcher.group().replace("\\u003D", "=");
            String lower = url.toLowerCase(Locale.ROOT);
            if (lower.contains("logo") || lower.contains("icon") || lower.contains("avatar")
                    || lower.contains("favicon") || lower.contains("sprite") || lower.contains("placeholder")) continue;
            int contextStart = Math.max(0, matcher.start() - 500);
            int contextEnd = Math.min(html.length(), matcher.end() + 500);
            // The old implementation accepted the first images of the whole
            // page as soon as the title appeared anywhere. Keep only images
            // whose own result block contains the searched programme title.
            if (!normalizedHtmlText(html.substring(contextStart, contextEnd)).contains(normalizedQuery)) continue;
            urls.add(url);
        }
        for (String url : urls) result.add(new ResumeArtworkCandidate(url, query, "", source.name));
        return result;
    }

    /** Official broadcaster pages provide useful artwork when TMDB has no match. */
    private List<ResumeArtworkCandidate> findFranceTvArtworkCandidates(String title) throws Exception {
        return findOfficialArtworkCandidates(title, new OfficialArtworkSource(
                "France.tv", "https://www.france.tv/recherche/?q="));
    }

    private List<ResumeArtworkCandidate> findArtworkCandidatesWithOfficialSources(String title) throws Exception {
        return findArtworkCandidatesWithOfficialSources(title, null);
    }

    private List<ResumeArtworkCandidate> findArtworkCandidatesWithOfficialSources(String title, JSONObject provider) throws Exception {
        ArrayList<ResumeArtworkCandidate> result = new ArrayList<>();
        result.addAll(findResumeArtworkCandidates(title, provider));
        // Official-site searches are slow and often expose stale/placeholder
        // image URLs. They are a fallback only when TMDB has no usable result.
        if (!result.isEmpty()) return result;
        java.util.HashSet<String> known = new java.util.HashSet<>();
        for (ResumeArtworkCandidate candidate : result) known.add(candidate.url);
        OfficialArtworkSource[] sources = new OfficialArtworkSource[] {
                new OfficialArtworkSource("France.tv", "https://www.france.tv/recherche/?q="),
                new OfficialArtworkSource("TF1+", "https://www.tf1.fr/recherche?query="),
                new OfficialArtworkSource("M6+", "https://www.m6.fr/recherche?query="),
                new OfficialArtworkSource("ARTE", "https://www.arte.tv/fr/search/?q="),
                new OfficialArtworkSource("Canal+", "https://www.canalplus.com/recherche/?q="),
                new OfficialArtworkSource("T18", "https://www.t18.fr/recherche?q="),
                new OfficialArtworkSource("RMC+", "https://www.rmcplus.fr/recherche?q=")
        };
        for (OfficialArtworkSource source : sources) {
            try {
                for (ResumeArtworkCandidate candidate : findOfficialArtworkCandidates(title, source, provider != null)) {
                    if (known.add(candidate.url)) result.add(candidate);
                }
            } catch (Exception ignored) {
                // An unavailable broadcaster must not prevent TMDB or the
                // other official sources from returning their candidates.
            }
        }
        return result;
    }

    private String youtubeResumeVideoId(JojoProgram program) {
        String id = NotificationResumeRules.youtubeVideoId(program.intentUri);
        if (id == null) try {
            id = NotificationResumeRules.youtubeVideoId(
                    Intent.parseUri(program.intentUri, Intent.URI_INTENT_SCHEME).getDataString());
        } catch (Exception ignored) { }
        return id;
    }

    private List<ResumeArtworkCandidate> findYoutubeArtworkCandidates(JojoProgram program) throws Exception {
        String currentId = youtubeResumeVideoId(program);
        List<YouTubeArtwork.Video> videos;
        try { videos = YouTubeArtwork.search(program.title); }
        catch (Exception error) { if (currentId == null) throw error; videos = Collections.emptyList(); }
        LinkedHashMap<String, YouTubeArtwork.Video> ordered = new LinkedHashMap<>();
        for (YouTubeArtwork.Video video : videos) if (video.id.equals(currentId)) ordered.put(video.id, video);
        if (currentId != null && ordered.isEmpty()) try {
            YouTubeArtwork.Video video = YouTubeArtwork.video(YouTubeArtwork.player(currentId));
            if (video != null && !video.thumbnail.isEmpty()) ordered.put(video.id, video);
        } catch (Exception ignored) { }
        for (YouTubeArtwork.Video video : videos) ordered.putIfAbsent(video.id, video);
        ArrayList<ResumeArtworkCandidate> result = new ArrayList<>();
        for (YouTubeArtwork.Video video : ordered.values()) result.add(new ResumeArtworkCandidate(
                video.thumbnail, video.title, "", video.id.equals(currentId)
                ? "YouTube · vidéo en cours" : "YouTube · " + video.author, 0, "", "", true));
        return result;
    }

    private List<ResumeArtworkCandidate> findYoutubeFrameCandidates(JojoProgram program, PopupWindow popup) throws Exception {
        String id = youtubeResumeVideoId(program);
        if (id == null) id = YouTubeArtwork.exactVideoId(YouTubeArtwork.search(program.title),
                program.title, program.description, program.duration);
        if (id == null || !popup.isShowing()) return Collections.emptyList();
        List<YouTubeArtwork.Frame> frames = YouTubeArtwork.frames(YouTubeArtwork.player(id), id);
        ArrayList<ResumeArtworkCandidate> result = new ArrayList<>();
        Bitmap sheet = null;
        String sheetUrl = "";
        try {
            for (YouTubeArtwork.Frame frame : frames) {
                if (!popup.isShowing()) break;
                File cached = new File(getCacheDir(), "youtube_frame_" + id + "_" + frame.timeMs
                        + "_" + frame.width + "x" + frame.height + ".jpg");
                if (!cached.isFile() || cached.length() == 0L) {
                    if (!sheetUrl.equals(frame.url)) {
                        if (sheet != null) { sheet.recycle(); sheet = null; }
                        byte[] bytes = YouTubeArtwork.download(frame.url, 5 * 1_024 * 1_024);
                        BitmapFactory.Options bounds = new BitmapFactory.Options(); bounds.inJustDecodeBounds = true;
                        BitmapFactory.decodeByteArray(bytes, 0, bytes.length, bounds);
                        if (bounds.outWidth < 1 || bounds.outHeight < 1
                                || (long) bounds.outWidth * bounds.outHeight > 8_000_000L) continue;
                        sheet = BitmapFactory.decodeByteArray(bytes, 0, bytes.length);
                        sheetUrl = frame.url;
                    }
                    if (sheet == null || frame.x + frame.width > sheet.getWidth()
                            || frame.y + frame.height > sheet.getHeight()) continue;
                    Bitmap image = Bitmap.createBitmap(sheet, frame.x, frame.y, frame.width, frame.height);
                    try (FileOutputStream output = new FileOutputStream(cached)) {
                        if (!image.compress(Bitmap.CompressFormat.JPEG, 92, output)) throw new IOException("Frame indisponible");
                    } finally { if (image != sheet) image.recycle(); }
                }
                long seconds = frame.timeMs / 1_000L;
                result.add(new ResumeArtworkCandidate(Uri.fromFile(cached).toString(), program.title, "",
                        "Frame YouTube · " + String.format(Locale.ROOT, "%d:%02d", seconds / 60L, seconds % 60L),
                        0, "", "", frame.width > frame.height));
            }
        } finally { if (sheet != null) sheet.recycle(); }
        return result;
    }

    private ResumeArtworkCandidate retainYoutubeFrame(ResumeArtworkCandidate candidate) throws IOException {
        File permanent = new File(getFilesDir(), "selected_hero_" + UUID.randomUUID() + ".jpg");
        try (InputStream input = new FileInputStream(new File(Uri.parse(candidate.url).getPath()));
             FileOutputStream output = new FileOutputStream(permanent)) {
            byte[] buffer = new byte[8_192]; int read;
            while ((read = input.read(buffer)) != -1) output.write(buffer, 0, read);
        }
        return new ResumeArtworkCandidate(Uri.fromFile(permanent).toString(), candidate.title,
                "", candidate.source, 0, "", "", candidate.landscape);
    }

    private void showResumeArtworkPicker(JojoProgram program, View anchor, boolean heroSelection,
                                         Boolean portraitArtworkOverride) {
        showResumeArtworkPicker(program, anchor, heroSelection, portraitArtworkOverride, null);
    }

    private void showResumeArtworkPicker(JojoProgram program, View anchor, boolean heroSelection,
                                         Boolean portraitArtworkOverride,
                                         ResumeArtworkSelectionRefresh afterSelection) {
        showResumeArtworkPicker(program, anchor, heroSelection, portraitArtworkOverride, afterSelection, null);
    }

    private void showResumeArtworkPicker(JojoProgram program, View anchor, boolean heroSelection,
                                         Boolean portraitArtworkOverride,
                                         ResumeArtworkSelectionRefresh afterSelection, JSONObject providerItem) {
        showResumeArtworkPicker(program, anchor, heroSelection, portraitArtworkOverride, afterSelection, providerItem, false);
    }

    private void showResumeArtworkPicker(JojoProgram program, View anchor, boolean heroSelection,
                                         Boolean portraitArtworkOverride,
                                         ResumeArtworkSelectionRefresh afterSelection, JSONObject providerItem,
                                         boolean youtubeFrames) {
        final String resumeKey = resumeDismissKey(program);
        final boolean youtubeArtwork = NotificationResumeRules.isTizenTubePackage(program.sourcePackage);
        final boolean externalProvider = "external-playback".equals(program.sourcePackage)
                || "external-playback-series-episode".equals(program.sourcePackage);
        final JSONObject sourceItem = !externalProvider ? null
                : providerItem != null ? providerItem : externalResumeItem(program);
        final boolean catalogueArtwork = sourceItem != null && ("series".equals(sourceItem.optString("category"))
                || "movies".equals(sourceItem.optString("category"))
                || "external-playback-series-episode".equals(program.sourcePackage));
        final JSONObject artworkSource = !catalogueArtwork ? null
                : "movies".equals(sourceItem.optString("category")) ? sourceItem : homeHeroEditorialSource(sourceItem, true);
        String sourceTitle = artworkSource == null ? "" : firstExternalValue(artworkSource,
                "originalTitle", "original_title", "original_name", "providerTitle", "title");
        final String artworkSearchTitle = sourceTitle.isEmpty() ? program.title : sourceTitle;
        final String homePosterIdentity = homeHeroPosterArtworkIdentity(anchor);
        final boolean homePosterSelection = !homePosterIdentity.isEmpty();
        // Category pages pass the provider item id as the program intent. Keep
        // the preference key tied to that canonical id, even when an older
        // card was reconstructed with a playback URI instead.
        final String externalArtworkKey;
        if ("external-playback".equals(program.sourcePackage)) {
            JSONObject stored = sourceItem != null ? sourceItem : externalResumeItem(program);
            String itemId = stored.optString("id", "").trim();
            externalArtworkKey = heroSelection ? externalHeroArtworkIdentity(program, stored)
                    : itemId.isEmpty() ? resumeKey : "external-playback|" + itemId;
        } else if ("external-playback-series-episode".equals(program.sourcePackage)
                && program.intentUri != null && !program.intentUri.trim().isEmpty()) {
            String episodeId = program.intentUri.trim();
            // Use the displayed provider identity even before the episode has been played.
            JSONObject episode = sourceItem != null ? sourceItem : ExternalPlaybackStore.get(this, episodeId);
            String groupIdentity = !heroSelection
                    ? externalPlaybackEpisodeGroupThumbnailIdentity(episode) : "";
            String episodeIdentity = !groupIdentity.isEmpty() ? groupIdentity
                    : !heroSelection ? externalPlaybackEpisodeThumbnailIdentity(episode) : "";
            externalArtworkKey = episodeIdentity.isEmpty()
                    ? "external-playback|" + episodeId : episodeIdentity;
        } else {
            externalArtworkKey = resumeKey;
        }
        final boolean channelLogo = isExternalLiveProgram(program);
        final boolean fileVideoFramesAvailable = FILE_VIDEO_RESUME_SOURCE.equals(program.sourcePackage)
                && program.intentUri != null && !program.intentUri.isEmpty();
        final boolean videoFramesAvailable = fileVideoFramesAvailable || youtubeArtwork;
        final boolean recurringVideo = fileVideoFramesAvailable
                && !homeVideosProgrammeArtworkKey(program.intentUri, program.title, false).isEmpty();
        final String artworkCategory = "external-playback-series-episode".equals(program.sourcePackage)
                ? "series" : artworkSource != null && ExternalPlaybackStore.categoryValid(artworkSource.optString("category"))
                ? artworkSource.optString("category") : activeHomeCategoryForArtwork(program);
        // Preserve the provider identity/year even when the Hero displays a
        // cleaned title. Local video years can instead be broadcast years.
        final String expectedArtworkYear = artworkSource != null
                && artworkSource.optInt("tmdbId", artworkSource.optInt("tmdb_id", 0)) <= 0
                ? providerArtworkYear(artworkSource, artworkSearchTitle) : "";
        final boolean portraitArtwork = homePosterSelection || !heroSelection
                && (recurringVideo || (portraitArtworkOverride != null
                ? portraitArtworkOverride
                : artworkTargetIsPortrait(anchor, artworkCategory)));
        LinearLayout panel = new LinearLayout(this);
        panel.setOrientation(LinearLayout.VERTICAL);
        panel.setPadding(dp(24), dp(20), dp(24), dp(18));
        panel.setBackground(artworkPickerPanelBg());
        TextView title = text(heroSelection ? "Changer la vignette du Hero" : "Changer de vignette", 21, white);
        panel.addView(title);
        TextView detail = text(program.title == null ? "Vidéo" : program.title, 14, muted);
        detail.setPadding(0, dp(6), 0, dp(12));
        panel.addView(detail);
        View videoFrames = null;
        if (videoFramesAvailable) {
            videoFrames = popupRow(R.drawable.ic_menu_wallpaper,
                    youtubeFrames ? "Vignettes YouTube" : "Frame vidéo");
            panel.addView(videoFrames, new LinearLayout.LayoutParams(-1, dp(58)));
        }
        TextView status = text(youtubeArtwork ? youtubeFrames ? "Chargement des frames d’aperçu YouTube…"
                : "Recherche des vignettes YouTube…" : channelLogo ? "Recherche des logos de chaîne…"
                : "Recherche des vignettes TMDB et sites officiels…", 16, muted);
        status.setGravity(Gravity.CENTER);
        panel.addView(status, new LinearLayout.LayoutParams(-1, dp(210)));
        PopupWindow popup = new PopupWindow(panel, dp(900), -2, true);
        popup.setBackgroundDrawable(new android.graphics.drawable.ColorDrawable(Color.TRANSPARENT));
        popup.setOutsideTouchable(true);
        popup.setElevation(dp(16));
        trackPopup(popup);
        if (videoFrames != null) videoFrames.setOnClickListener(v -> {
            if (youtubeArtwork) {
                popup.dismiss();
                showResumeArtworkPicker(program, anchor, heroSelection, portraitArtworkOverride,
                        afterSelection, providerItem, !youtubeFrames);
            } else showResumeVideoFrameChooser(program, anchor, heroSelection, popup);
        });
        popup.showAtLocation(getWindow().getDecorView(), Gravity.CENTER, 0, 0);
        if (videoFrames != null) videoFrames.requestFocus(); else status.requestFocus();
        final View frameButton = videoFrames;
        new Thread(() -> {
            try {
                List<ResumeArtworkCandidate> candidates = youtubeArtwork ? youtubeFrames
                        ? findYoutubeFrameCandidates(program, popup) : findYoutubeArtworkCandidates(program)
                        : channelLogo ? findChannelLogoCandidates(program)
                        : findArtworkCandidatesWithOfficialSources(artworkSearchTitle, artworkSource);
                if (!channelLogo && !expectedArtworkYear.isEmpty()) {
                    candidates = filterArtworkCandidatesByYear(candidates, expectedArtworkYear);
                }
                if (homePosterSelection && !channelLogo && !youtubeArtwork) {
                    candidates = filterArtworkCandidatesByOrientation(candidates, false);
                } else if (heroSelection && !channelLogo) {
                    candidates = filterHeroLandscapeArtworkCandidates(candidates);
                } else if (recurringVideo) {
                    candidates = filterArtworkCandidatesByOrientation(candidates, false);
                }
                final List<ResumeArtworkCandidate> filteredCandidates = candidates;
                runOnUiThread(() -> {
                    if (!popup.isShowing()) return;
                    panel.removeView(status);
                    if (filteredCandidates.isEmpty()) {
                        TextView empty = text(youtubeFrames ? "Aucune frame d’aperçu disponible pour cette vidéo YouTube."
                                : channelLogo ? "Pas de résultat : aucun logo de chaîne disponible."
                                : "Pas de résultat pour cette recherche de vignette.", 16, muted);
                        empty.setGravity(Gravity.CENTER);
                        empty.setFocusable(true);
                        panel.addView(empty, new LinearLayout.LayoutParams(-1, dp(210)));
                        if (frameButton != null) frameButton.requestFocus(); else empty.requestFocus();
                        return;
                    }
                    HorizontalScrollView scroll = new HorizontalScrollView(this);
                    scroll.setFocusable(false);
                    scroll.setFocusableInTouchMode(false);
                    scroll.setHorizontalScrollBarEnabled(false);
                    LinearLayout row = new LinearLayout(this);
                    row.setOrientation(LinearLayout.HORIZONTAL);
                    row.setGravity(Gravity.CENTER_VERTICAL);
                    row.setPadding(dp(6), dp(6), dp(6), dp(6));
                    row.setFocusable(false);
                    scroll.addView(row, new HorizontalScrollView.LayoutParams(-2, -2));
                    for (ResumeArtworkCandidate candidate : filteredCandidates) {
                        LinearLayout item = new LinearLayout(this);
                        item.setOrientation(LinearLayout.VERTICAL);
                        item.setPadding(dp(5), dp(5), dp(5), dp(5));
                        item.setFocusable(true);
                        item.setFocusableInTouchMode(true);
                        item.setBackground(resumeArtworkPickerItemBg(false));
                        clipArtworkPickerCard(item);
                        ImageView image = new ImageView(this);
                        image.setScaleType(ImageView.ScaleType.FIT_CENTER);
                        image.setBackgroundColor(channelLogo ? Color.rgb(245, 245, 245) : Color.rgb(35, 43, 60));
                        roundImage(image, 10);
                        boolean candidatePortrait = youtubeArtwork && homePosterSelection || !heroSelection && !channelLogo
                                && (candidate.landscape == null ? portraitArtwork : !candidate.landscape);
                        int candidateWidth = candidatePortrait ? 126 : 190;
                        int candidateHeight = candidatePortrait ? 189 : 107;
                        // Clip the artwork itself as well as the outer choice
                        // card.  Clipping only the card leaves the ImageView's
                        // four corners square inside the rounded frame.
                        FrameLayout imageFrame = new FrameLayout(this);
                        imageFrame.addView(image, new FrameLayout.LayoutParams(-1, -1));
                        clipArtworkPickerCard(imageFrame);
                        item.addView(imageFrame, new LinearLayout.LayoutParams(
                                dp(candidateWidth), dp(candidateHeight)));
                        TextView label = text(candidate.source + "\n" + candidate.title + (candidate.year.isEmpty() ? "" : " " + candidate.year), 12, white);
                        label.setGravity(Gravity.CENTER);
                        label.setMinHeight(dp(42));
                        item.addView(label, new LinearLayout.LayoutParams(dp(candidateWidth), -2));
                        item.setOnClickListener(v -> {
                            final ResumeArtworkCandidate selected;
                            try { selected = youtubeFrames ? retainYoutubeFrame(candidate) : candidate; }
                            catch (IOException error) {
                                Toast.makeText(this, "Enregistrement de la frame impossible", Toast.LENGTH_LONG).show();
                                return;
                            }
                            boolean fileVideo = FILE_VIDEO_RESUME_SOURCE.equals(program.sourcePackage);
                            boolean externalArtwork = "external-playback".equals(program.sourcePackage)
                                    || "external-playback-series-episode".equals(program.sourcePackage);
                            boolean refreshCategoryThumbnail = !heroSelection
                                    && "external-playback".equals(program.sourcePackage)
                                    && activeScreen == homeCategoryPageView;
                            if (homePosterSelection) saveExternalArtworkSelection(
                                    homePosterIdentity, selected, false);
                            else if (channelLogo) homePrefs().edit().putString(
                                    channelLogoOverrideKey(program.intentUri, heroSelection), selected.url).apply();
                            else if (fileVideo && !heroSelection) saveHomeVideosFileArtwork(
                                    program.intentUri, selected.url, selected,
                                    image.getDrawable() instanceof BitmapDrawable
                                            ? ((BitmapDrawable) image.getDrawable()).getBitmap() : null);
                            else if (!fileVideo && externalArtwork) {
                                saveExternalArtworkSelection(
                                        externalArtworkKey,
                                        selected, heroSelection);
                            }
                            else if (youtubeArtwork) saveResumeArtworkUrl(selected.url, resumeKey);
                            else saveResumeArtworkSelection(resumeKey, selected);
                            if (homePosterSelection) {
                                showSelectedArtwork(resolveArtworkView(anchor), image, selected.url);
                            } else if (fileVideo) {
                                ImageView target = resolveArtworkView(anchor);
                                showSelectedArtwork(target, image, selected.url);
                            } else if (heroSelection) {
                                ImageView target = resolveArtworkView(anchor);
                                showSelectedArtwork(target, image, selected.url);
                            } else if (!heroSelection && (refreshCategoryThumbnail
                                    || "external-playback-series-episode".equals(program.sourcePackage))) {
                                // The category rail is not part of the Home
                                // resume row. Update its selected tile directly.
                                ImageView target = resolveArtworkView(anchor);
                                showSelectedArtwork(target, image, selected.url);
                            } else {
                                ImageView target = findResumeArtworkView(currentHomeResumesView, resumeKey);
                                showSelectedArtwork(target, image, selected.url);
                            }
                            if (!fileVideo && !homePosterSelection) updateCachedResumeArtwork(program, selected.url);
                            popup.dismiss();
                            if (fileVideo && anchor != null) {
                                Object refresh = anchor.getTag(CATEGORY_VIDEO_METADATA_REFRESH_TAG);
                                if (refresh instanceof Runnable) ((Runnable) refresh).run();
                            }
                            if (afterSelection != null) afterSelection.refresh(image, selected.url);
                            else restoreResumeArtworkFocus(anchor);
                        });
                        item.setOnFocusChangeListener((v, focused) ->
                                v.setBackground(resumeArtworkPickerItemBg(focused)));
                        row.addView(item, new LinearLayout.LayoutParams(
                                dp(candidateWidth + 12),
                                -2));
                        artworkLoadFailures.put(image, () -> {
                            if (item.getParent() instanceof ViewGroup) {
                                ((ViewGroup) item.getParent()).removeView(item);
                            }
                            if (popup.isShowing() && row.getChildCount() == 0) {
                                panel.removeView(scroll);
                                TextView empty = text("Pas de résultat pour cette recherche de vignette.", 16, muted);
                                empty.setGravity(Gravity.CENTER);
                                empty.setFocusable(true);
                                panel.addView(empty, new LinearLayout.LayoutParams(-1, dp(210)));
                                if (frameButton != null) frameButton.requestFocus(); else empty.requestFocus();
                            }
                        });
                        loadArtwork(image, candidate.url);
                    }
                    panel.addView(scroll, new LinearLayout.LayoutParams(-1, -2));
                    scroll.post(() -> {
                        View first = row.getChildAt(0);
                        if (first != null) first.requestFocus();
                    });
                });
            } catch (Exception error) {
                runOnUiThread(() -> {
                    if (!popup.isShowing()) return;
                    status.setText(youtubeArtwork ? "YouTube est temporairement indisponible."
                            : "Recherche de vignettes impossible");
                    if (youtubeArtwork) {
                        View retry = popupRow(R.drawable.ic_reset_arrow, "Réessayer");
                        retry.setOnClickListener(v -> {
                            popup.dismiss();
                            showResumeArtworkPicker(program, anchor, heroSelection, portraitArtworkOverride,
                                    afterSelection, providerItem, youtubeFrames);
                        });
                        panel.addView(retry, new LinearLayout.LayoutParams(-1, dp(58)));
                        retry.requestFocus();
                    } else status.requestFocus();
                });
            }
        }, "JojoHomeResumeArtworkSearch").start();
    }

    private ImageView findResumeArtworkView(View root, String resumeKey) {
        if (root == null) return null;
        if (resumeKey.equals(root.getTag())) return findFirstImageView(root);
        if (root instanceof ViewGroup) {
            ViewGroup group = (ViewGroup) root;
            for (int index = 0; index < group.getChildCount(); index++) {
                ImageView result = findResumeArtworkView(group.getChildAt(index), resumeKey);
                if (result != null) return result;
            }
        }
        return null;
    }

    private ImageView findFirstImageView(View root) {
        if (root instanceof ImageView) return (ImageView) root;
        if (root instanceof ViewGroup) {
            ViewGroup group = (ViewGroup) root;
            for (int index = 0; index < group.getChildCount(); index++) {
                ImageView result = findFirstImageView(group.getChildAt(index));
                if (result != null) return result;
            }
        }
        return null;
    }

    private void updateCachedResumeArtwork(JojoProgram program, String artworkUrl) {
        if (program == null || artworkUrl == null || artworkUrl.isEmpty()) return;
        if ("external-playback".equals(program.sourcePackage)) {
            for (LinearLayout rows : currentExternalRows.values()) {
                ImageView target = findResumeArtworkView(rows, resumeDismissKey(program));
                if (target != null) loadArtwork(target, artworkUrl);
            }
        }
        try {
            JSONArray cached = new JSONArray(homePrefs().getString(CONTINUE_WATCHING_HOME_CACHE, "[]"));
            for (int index = 0; index < cached.length(); index++) {
                JSONObject item = cached.optJSONObject(index);
                if (item == null) continue;
                JojoProgram cachedProgram = new JojoProgram(item.optString("source", ""), item.optString("title", ""), item.optString("description", ""), item.optString("artwork", ""), item.optString("intent", ""), item.optLong("duration", -1L), item.optLong("position", -1L));
                if (resumeDismissKey(program).equals(resumeDismissKey(cachedProgram))) item.put("artwork", artworkUrl);
            }
            homePrefs().edit().putString(CONTINUE_WATCHING_HOME_CACHE, cached.toString()).apply();
        } catch (Exception ignored) { }
    }

    private GradientDrawable resumeArtworkPickerItemBg(boolean focused) {
        GradientDrawable background = new GradientDrawable();
        background.setColor(focused
                ? withAlpha(folderButtonThemeColor(), 145)
                : withAlpha(Color.rgb(18, 28, 50), 120));
        background.setCornerRadius(dp(12));
        background.setStroke(dp(focused ? 3 : 1), focused
                ? Color.WHITE
                : withAlpha(Color.rgb(180, 198, 230), 150));
        return background;
    }

    private void clipArtworkPickerCard(View card) {
        if (card instanceof ViewGroup) {
            ((ViewGroup) card).setClipChildren(true);
            ((ViewGroup) card).setClipToPadding(true);
        }
        card.setOutlineProvider(new ViewOutlineProvider() {
            @Override public void getOutline(View view, Outline outline) {
                outline.setRoundRect(0, 0, view.getWidth(), view.getHeight(), dp(12));
            }
        });
        card.setClipToOutline(true);
    }

    private void saveResumeArtworkUrl(String artworkUrl, String resumeKey) {
        if (artworkUrl == null || artworkUrl.isEmpty() || resumeKey == null) return;
        String preferenceKey = resumeKey.startsWith("external-playback|")
                ? externalHeroArtworkKey(resumeKey)
                : "resume_artwork_" + Integer.toUnsignedString(resumeKey.hashCode(), 16);
        android.content.SharedPreferences.Editor editor = homePrefs().edit()
                .putString(preferenceKey, artworkUrl)
                .putBoolean("nas_home_pending", true)
                .putString("nas_home_snapshot", "");
        String metadataKey = "resume_artwork_metadata_" + Integer.toUnsignedString(resumeKey.hashCode(), 16);
        String programmeHeroKey = "";
        String path = "";
        String fileVideoPrefix = FILE_VIDEO_RESUME_SOURCE + "|";
        if (resumeKey.startsWith(fileVideoPrefix)) {
            path = resumeKey.substring(fileVideoPrefix.length());
            String fileName = Uri.decode(path.substring(path.lastIndexOf('/') + 1));
            programmeHeroKey = homeVideosProgrammeArtworkKey(path, fileName, true);
            if (!programmeHeroKey.isEmpty()) editor.putString(programmeHeroKey, artworkUrl);
        }
        try {
            String metadata = new JSONObject().put("artworkUrl", artworkUrl)
                    .put("selectedAt", System.currentTimeMillis()).put("mediaPath", path).toString();
            editor.putString(metadataKey, metadata);
            if (!programmeHeroKey.isEmpty()) editor.putString(programmeHeroKey + "_metadata", metadata);
        } catch (Exception ignored) { }
        editor.apply();
        synchronized (artworkBitmapCache) { artworkBitmapCache.remove(artworkUrl); }
        final String videoPath = path;
        final String videoProgrammeHeroKey = programmeHeroKey;
        if (!videoPath.isEmpty()) runOnUiThread(() -> {
            for (java.util.Map.Entry<ImageView, String> entry : homeVideosFileHeroArtworkViews.entrySet()) {
                String imagePath = entry.getValue();
                if (!videoPath.equals(imagePath) && (videoProgrammeHeroKey.isEmpty()
                        || !videoProgrammeHeroKey.equals(homeVideosProgrammeArtworkKey(imagePath, null, true)))) continue;
                ImageView image = entry.getKey();
                image.setTag("selected-file-hero-artwork:" + artworkUrl);
                loadArtwork(image, artworkUrl);
            }
        });
    }

    private void saveResumeArtworkSelection(String resumeKey, ResumeArtworkCandidate candidate) {
        if (candidate == null || candidate.url == null || candidate.url.isEmpty()) return;
        saveResumeArtworkUrl(candidate.url, resumeKey);
        try {
            String metadata = new JSONObject()
                            .put("tmdbId", candidate.tmdbId)
                            .put("mediaType", candidate.tmdbMediaType)
                            .put("artworkUrl", candidate.url)
                            .put("selectedAt", System.currentTimeMillis())
                            .put("title", candidate.title)
                            .put("year", candidate.year)
                            .put("mediaPath", resumeKey.startsWith(FILE_VIDEO_RESUME_SOURCE + "|")
                                    ? resumeKey.substring(FILE_VIDEO_RESUME_SOURCE.length() + 1) : "")
                            .put("overview", candidate.overview).toString();
            android.content.SharedPreferences.Editor editor = homePrefs().edit().putString(
                    "resume_artwork_metadata_" + Integer.toUnsignedString(resumeKey.hashCode(), 16), metadata);
            String prefix = FILE_VIDEO_RESUME_SOURCE + "|";
            if (resumeKey.startsWith(prefix)) {
                String path = resumeKey.substring(prefix.length());
                String name = Uri.decode(path.substring(path.lastIndexOf('/') + 1));
                String programmeKey = homeVideosProgrammeArtworkKey(path, name, true);
                if (!programmeKey.isEmpty()) editor.putString(programmeKey + "_metadata", metadata);
            }
            editor.apply();
        } catch (Exception ignored) { }
    }

    private void saveExternalArtworkSelection(String resumeKey, ResumeArtworkCandidate candidate,
                                               boolean heroSelection) {
        if (candidate == null || candidate.url == null || candidate.url.isEmpty()) return;
        saveExternalArtworkSelection(resumeKey, candidate.url, heroSelection);
    }

    private void saveExternalArtworkSelection(String resumeKey, String artworkUrl,
                                               boolean heroSelection) {
        String key = heroSelection ? externalHeroArtworkKey(resumeKey) : externalThumbnailArtworkKey(resumeKey);
        try {
            JSONObject revisions = compactHomeSettingRevisions(new JSONObject(homePrefs().getString("nas_setting_changes", "{}")));
            saveManualExternalArtwork(this, key, artworkUrl, revisions, jojoHomeDeviceId());
            nasAutoSyncHandler.removeCallbacks(nasAutoPushRunnable);
            nasAutoSyncHandler.postDelayed(nasAutoPushRunnable, 900L);
        } catch (org.json.JSONException error) {
            android.util.Log.e("JojoHomeSync", "Cannot save manual artwork selection", error);
            Toast.makeText(this, "Impossible de sauvegarder la vignette", Toast.LENGTH_LONG).show();
        }
    }

    public static boolean saveExternalArtworkSelection(Context context, String resumeKey, String artworkUrl,
                                                        boolean heroSelection) {
        if (!ExternalPlaybackStore.supportedUrl(artworkUrl)) return false;
        android.content.SharedPreferences prefs = context.getSharedPreferences("home_settings", MODE_PRIVATE);
        synchronized (prefs) {
            try {
                String writer = prefs.getString("nas_device_id", "");
                if (writer.isEmpty()) {
                    writer = "jojohome-" + UUID.randomUUID();
                    prefs.edit().putString("nas_device_id", writer).commit();
                }
                saveManualExternalArtwork(context, heroSelection ? externalHeroArtworkKey(resumeKey)
                        : externalThumbnailArtworkKey(resumeKey), artworkUrl,
                        new JSONObject(prefs.getString("nas_setting_changes", "{}")), writer);
                return true;
            } catch (org.json.JSONException error) {
                android.util.Log.e("JojoHomeSync", "Cannot save manual artwork selection", error);
                return false;
            }
        }
    }

    private static void saveManualExternalArtwork(Context context, String key, String artworkUrl,
            JSONObject revisions, String writer) throws org.json.JSONException {
        android.content.SharedPreferences prefs = context.getSharedPreferences("home_settings", MODE_PRIVATE);
        android.content.SharedPreferences selections = context.getSharedPreferences("external_artwork_selections", MODE_PRIVATE);
        JSONObject previous = revisions.optJSONObject(key);
        JSONObject stored = new JSONObject(selections.getString(key, "{}"));
        long changedAt = Math.max(System.currentTimeMillis(), Math.max(stored.optLong("changedAt"),
                previous == null ? 0L : previous.optLong("changedAt")) + 1L);
        JSONObject choice = new JSONObject().put("type", "string").put("value", artworkUrl)
                .put("manualArtwork", true).put("changedAt", changedAt).put("writer", writer);
        selections.edit().putString(key, choice.toString()).apply();
        com.jojotv.home.progresspilot.AccountContentRouting.artworkChanged(context);
        revisions.put(key, new JSONObject().put("changedAt", changedAt).put("writer", writer));
        prefs.edit().putString(key, artworkUrl).putString("nas_setting_changes", revisions.toString())
                .putLong("nas_home_updated_at", changedAt).putBoolean("nas_home_pending", true)
                .putString("nas_home_snapshot", "").apply();
    }

    private void requestFreeboxResumeDeletion(JojoProgram program) {
        if (program != null && (FILE_VIDEO_RESUME_SOURCE.equals(program.sourcePackage)
                || FREEBOX_FOLDER_SOURCE.equals(program.sourcePackage))) {
            boolean folder = FREEBOX_FOLDER_SOURCE.equals(program.sourcePackage);
            String smbPath = program.intentUri == null ? "" : program.intentUri.trim();
            String deletionName = folder ? cleanFileName(program.title) + " (dossier et tout son contenu)"
                    : cleanFileName(smbPath);
            showDeleteConfirm(deletionName, () -> new Thread(() -> {
                try {
                    SmbConnectionConfig connection = smbConnectionForPath(smbPath);
                    String user = connection == null ? homePrefs().getString("smb_user", "") : connection.user;
                    String password = connection == null ? homePrefs().getString("smb_password", "") : connection.password;
                    jcifs.smb.SmbFile remoteFile = new jcifs.smb.SmbFile(smbPath, smbContext(user, password));
                    deleteSmbTree(remoteFile, this);
                    runOnUiThread(() -> {
                        if (folder) {
                            rememberDeletedFreeboxPath(smbPath, "");
                            removeFreeboxHomeVideoFromCache(smbPath);
                            List<JojoProgram> remaining = cachedContinueWatchingHomePrograms();
                            String key = resumeDismissKey(program);
                            remaining.removeIf(item -> key.equals(resumeDismissKey(item)));
                            cacheContinueWatchingHomePrograms(remaining);
                            removeDeletedFreeboxHomeCards(program);
                        }
                        Toast.makeText(this, folder ? "Dossier supprimé de la Freebox"
                                : "Vidéo supprimée de la Freebox", Toast.LENGTH_SHORT).show();
                    });
                } catch (Exception error) {
                    runOnUiThread(() -> Toast.makeText(this, "Suppression de la Freebox impossible : "
                            + error.getMessage(), Toast.LENGTH_LONG).show());
                }
            }, "JojoHomeDeleteFreeboxResume").start());
            return;
        }
        Intent request = new Intent("com.jojo.tv.action.DELETE_FREEBOX_RESUME")
                .setPackage("com.jojo.tv")
                .putExtra("contentId", decodedJojoIntentExtra(program.intentUri, "contentId"))
                .putExtra("intentUri", program.intentUri);
        try {
            sendBroadcast(request);
            Toast.makeText(this, "Suppression envoyée à JojoTV", Toast.LENGTH_SHORT).show();
        } catch (RuntimeException error) {
            Toast.makeText(this, "JojoTV est nécessaire pour supprimer de la Freebox", Toast.LENGTH_LONG).show();
        }
    }

    private SmbConnectionConfig smbConnectionForPath(String path) {
        if (path == null || path.trim().isEmpty()) return defaultSmbConnection();
        String candidate = Uri.decode(path).replace('\\', '/').toLowerCase(Locale.ROOT);
        SmbConnectionConfig best = null;
        for (SmbConnectionConfig connection : smbConnections()) {
            if (connection == null) continue;
            String root = Uri.decode(connection.browserUrl()).replace('\\', '/').toLowerCase(Locale.ROOT);
            if (candidate.startsWith(root) && (best == null || root.length() > best.browserUrl().length())) best = connection;
        }
        return best == null ? defaultSmbConnection() : best;
    }

    private void removeContinueWatchingProgram(JojoProgram program, View card) {
        if (program == null) return;
        if (FILE_VIDEO_RESUME_SOURCE.equals(program.sourcePackage)) {
            removeFileVideoResume(program, card);
            Toast.makeText(this, "Reprise retirée de Continuer à regarder", Toast.LENGTH_SHORT).show();
            return;
        }
        if (FREEBOX_FOLDER_SOURCE.equals(program.sourcePackage)) {
            removeVideoFromHomeLists(program, card);
            return;
        }
        if ("external-playback".equals(program.sourcePackage)) {
            removeHomeHeroContinueWatching(program, card, true);
            return;
        }
        // Keep a removed card hidden if Android TV or the NAS merely
        // republishes stale progress. A deliberate new file playback clears
        // this exact source-based key in NuvioPlayerActivity.
        dismissResumeLocally(program);
        if (!refreshModernHeroImmediatelyAfterRemoval(program)) {
            removeResumeCards(program, card);
            refreshHomeResumeSectionInPlace();
        }
        if (!isJojoPackage(program.sourcePackage)) {
            deleteSmartTubeResumeFromNas(program);
            Toast.makeText(this, "Reprise supprimée de la liste", Toast.LENGTH_SHORT).show();
            return;
        }
        String progressKey = SystemContinueWatching.jojoIntentExtra(program.intentUri, "androidTvProgressKey");
        String profileText = SystemContinueWatching.jojoIntentExtra(program.intentUri, "androidTvProfileId");
        int profileId;
        try { profileId = Integer.parseInt(profileText); } catch (Exception ignored) { profileId = 1; }
        if (SystemContinueWatching.isBlank(progressKey) || homePrefs().getString("nas_token", "").isEmpty()) {
            Toast.makeText(this, "Reprise masquée de la liste", Toast.LENGTH_SHORT).show();
            return;
        }
        final int targetProfileId = profileId;
        Toast.makeText(this, "Reprise retirée de la liste", Toast.LENGTH_SHORT).show();
        new Thread(() -> {
            try {
                nasRequest("DELETE", nasBaseUrl() + "/api/sync/profiles/" + targetProfileId + "/watch-progress", homePrefs().getString("nas_token", ""), new JSONObject().put("keys", new JSONArray().put(progressKey)));
                removeJojoResumeFromNasCache(targetProfileId, progressKey);
            } catch (Exception error) {
                runOnUiThread(() -> Toast.makeText(this, "Reprise masquée localement", Toast.LENGTH_SHORT).show());
            }
        }).start();
    }

    private boolean isExternalRemovalPending(String id) {
        if (pendingExternalRemovals.contains(id)) return true;
        if (!id.startsWith("iptv:")) return false;
        String key = com.jojotv.home.iptv.IptvStore.homeResumeDismissalKey(id);
        for (String pending : pendingExternalRemovals) {
            if (pending.startsWith("iptv:") && key.equals(
                    com.jojotv.home.iptv.IptvStore.homeResumeDismissalKey(pending))) return true;
        }
        return false;
    }
    private void prunePendingHomeFavoriteSnapshots() {
        for (List<JSONObject> items : homeCategoryFavoriteSnapshots.values())
            items.removeIf(item -> isExternalRemovalPending(item.optString("id")));
    }
    private JojoProgram capturedHomeRemovalProgram(JojoProgram selected) {
        if (selected == null || selected.intentUri == null || !selected.intentUri.startsWith("iptv:")) return selected;
        String id = com.jojotv.home.iptv.IptvStore.homeRemovalContentId(selected.intentUri);
        return id.equals(selected.intentUri) ? selected : new JojoProgram(selected.sourcePackage,
                selected.title, selected.description, selected.artwork, id, selected.duration, selected.position,
                selected.seasonNumber, selected.episodeNumber, selected.watched, selected.videoFrameSource);
    }
    private void removeExternalFavorite(JojoProgram selected, View card) {
        if (selected == null || selected.intentUri == null || selected.intentUri.isEmpty()) return;
        // Capture ownership before queuing the write; an account switch must not remove another account's favorite.
        final JojoProgram program = capturedHomeRemovalProgram(selected);
        if (!pendingExternalRemovals.add(program.intentUri)) return;
        dismissResumeLocally(program);
        long startedAt = android.os.SystemClock.elapsedRealtime();
        removeResumeCards(program, card);
        android.util.Log.i("JojoHomeResume", "REMOVE_FAVORITE_VISIBLE at=" + startedAt
                + " id=" + program.intentUri);
        resumeMutationExecutor.execute(() -> {
            boolean success = false;
            try {
                JSONObject favorite = ExternalPlaybackStore.get(getApplicationContext(), program.intentUri);
                success = "series".equals(favorite.optString("category"))
                        ? ExternalPlaybackStore.removeSeriesFavoriteFromHomeLists(getApplicationContext(), program.intentUri)
                        : ExternalPlaybackStore.removeFromHomeLists(getApplicationContext(), program.intentUri);
            } catch (RuntimeException error) {
                android.util.Log.e("JojoHomeResume", "REMOVE_FAVORITE_FAILED at="
                        + android.os.SystemClock.elapsedRealtime(), error);
            }
            final boolean removed = success;
            runOnUiThread(() -> {
                if (removed) prunePendingHomeFavoriteSnapshots();
                pendingExternalRemovals.remove(program.intentUri);
                android.util.Log.i("JojoHomeResume", "REMOVE_FAVORITE_SAVED at="
                        + android.os.SystemClock.elapsedRealtime() + " elapsedMs="
                        + (android.os.SystemClock.elapsedRealtime() - startedAt)
                        + " success=" + removed);
                if (isDestroyed()) return;
                if (!removed) {
                    clearResumeDismissal(program);
                    Toast.makeText(this, "Retrait du favori impossible, réessayez", Toast.LENGTH_LONG).show();
                }
                if (removed) cacheContinueWatchingHomePrograms(cachedContinueWatchingHomePrograms());
                renderExternalPlaybackRows();
                refreshHomeResumeSectionInPlace();
                if (removed) refreshActiveHomeCategoryPage();
            });
        });
    }

    /** Removes every visible copy without rebuilding Home, keeping focus in the carousel. */
    private void removeResumeCards(JojoProgram program, View card) {
        if (card == null || !(card.getParent() instanceof ViewGroup)) return;
        if (isHomeSuggestionCard(card)) {
            refreshEmptyHomeSuggestions();
            return;
        }
        String resumeKey = resumeDismissKey(program);
        // A Home Hero passes its focused action button here. Its parent is the
        // action bar, not the thumbnail row, so looking for a sibling there
        // always produces the wrong focus target. Resolve the actual tagged
        // resume card first and calculate the successor from that row.
        View focusCard = card;
        if (!(resumeKey.equals(card.getTag()))) {
            ArrayList<View> matchingCards = new ArrayList<>();
            collectResumeCardsWithKey(currentHomeResumesView, resumeKey, matchingCards);
            if ("external-playback".equals(program.sourcePackage)) {
                for (LinearLayout externalRows : currentExternalRows.values()) {
                    collectResumeCardsWithKey(externalRows, resumeKey, matchingCards);
                }
            }
            if (!matchingCards.isEmpty()) focusCard = matchingCards.get(0);
        }
        ViewGroup row = focusCard.getParent() instanceof ViewGroup
                ? (ViewGroup) focusCard.getParent() : null;
        int index = row == null ? -1 : row.indexOfChild(focusCard);
        View nextFocus = row != null && index >= 0 && index + 1 < row.getChildCount()
                ? row.getChildAt(index + 1)
                : row != null && index > 0 ? row.getChildAt(index - 1) : null;
        String nextFocusKey = nextFocus != null && nextFocus.getTag() instanceof String
                ? (String) nextFocus.getTag() : null;
        // A NAS/TV-provider refresh can rebuild this row just after a removal.
        // Keep the neighbouring card identity so focus is restored to the row,
        // rather than falling back to the first item in the top bar.
        pendingResumeFocusKey = nextFocusKey;
        // The visual tag is deliberately stable: playback time changes while
        // a card is displayed, but must never make its neighbour unfindable.
        if (nextFocus != null && nextFocus.isFocusable()) {
            // Do this before removing the selected card.  Popup dismissal can
            // otherwise let Android choose the first header action (Search).
            requestHomeFocus(nextFocus, "resume-remove-neighbour");
            revealResumeCard(nextFocus);
        }
        ArrayList<View> copies = new ArrayList<>();
        collectResumeCardsWithKey(currentHomeResumesView, resumeKey, copies);
        if ("external-playback".equals(program.sourcePackage)) {
            for (LinearLayout externalRows : currentExternalRows.values()) collectResumeCardsWithKey(externalRows, resumeKey, copies);
        }
        if (!copies.contains(card)) copies.add(card);
        for (View copy : copies) {
            if (copy.getParent() instanceof ViewGroup) ((ViewGroup) copy.getParent()).removeView(copy);
        }
        if ("external-playback".equals(program.sourcePackage)) {
            for (Map.Entry<String, LinearLayout> entry : currentExternalRows.entrySet()) {
                setHomeSectionVisible(entry.getKey(), hasVisibleResumeCard(entry.getValue()));
            }
        }
        if (!(currentHomeResumesView instanceof ViewGroup)) return;
        // A HorizontalScrollView can remain focusable after its last card is
        // removed, and different Continue Watching layouts do not all expose
        // their cards through the same horizontal-row shape. Count the actual
        // tagged cards instead of relying on a generic focusable descendant.
        boolean hasResumeCards = hasVisibleResumeCard(currentHomeResumesView);
        if (!hasResumeCards) {
            currentHomeResumesView.setVisibility(View.GONE);
            setHomeSectionVisible("resumes", false);
            if (currentHomeHeaderView != null && currentHomeAppsView != null) {
                wireHomeHeaderDpad(currentHomeHeaderView, currentHomeAppsView,
                        currentHomeFilesView, currentHomeResumesView);
            }
            wireHomeSectionVerticalDpad();
        } else {
            currentHomeResumesView.setVisibility(View.VISIBLE);
            setHomeSectionVisible("resumes", true);
            wireHomeSectionVerticalDpad();
        }
        Runnable restoreResumeFocus = () -> {
            View target = nextFocus != null && nextFocus.isAttachedToWindow() ? nextFocus
                    : nextFocusKey == null ? null : currentHomeResumesView.findViewWithTag(nextFocusKey);
            if (target != null && target.isFocusable()) {
                pendingResumeFocusKey = null;
                requestHomeFocus(target, "resume-remove-neighbour");
                revealResumeCard(target);
                return;
            }
            View fallback = firstFocusableChild((ViewGroup) currentHomeResumesView);
            if (fallback == null) fallback = firstFocusableChild(currentHomeAppsView);
            if (fallback == null) fallback = resolveHomeFocusTarget();
            requestHomeFocus(fallback, "resume-remove-fallback");
        };
        restoreResumeFocus.run();
    }

    private void collectResumeCardsWithKey(View root, String resumeKey, List<View> result) {
        if (root == null) return;
        if (resumeKey.equals(root.getTag()) && root.isFocusable()) result.add(root);
        if (root instanceof ViewGroup) {
            ViewGroup group = (ViewGroup) root;
            for (int index = 0; index < group.getChildCount(); index++) {
                collectResumeCardsWithKey(group.getChildAt(index), resumeKey, result);
            }
        }
    }

    private void removeJojoResumeFromNasCache(int profileId, String progressKey) {
        try {
            JSONArray current = new JSONArray(homePrefs().getString(JOJOTV_NAS_RESUME_CACHE, "[]"));
            JSONArray retained = new JSONArray();
            for (int index = 0; index < current.length(); index++) {
                JSONObject entry = current.optJSONObject(index);
                if (entry == null) continue;
                boolean matches = entry.optInt("jojotvProfileId", 1) == profileId && progressKey.equals(entry.optString("key", ""));
                if (!matches) retained.put(entry);
            }
            homePrefs().edit().putString(JOJOTV_NAS_RESUME_CACHE, retained.toString()).apply();
        } catch (Exception ignored) { }
    }

