    private View jojoProgramTile(JojoProgram program, boolean showDurationBeforeTitle,
                                 boolean portraitArtwork, boolean compactCategoryThumbnail,
                                 float compactArtworkScale, boolean showCompactCategoryTitle,
                                 boolean scaleCompactArtworkOnFocus, boolean hideDurationBeforeTitle) {
        LinearLayout card = new LinearLayout(this); card.setOrientation(LinearLayout.VERTICAL); card.setFocusable(true); card.setClipChildren(false); card.setClipToPadding(false); card.setTag(resumeDismissKey(program));
        if (compactCategoryThumbnail && Build.VERSION.SDK_INT >= Build.VERSION_CODES.O)
            card.setDefaultFocusHighlightEnabled(false);
        FrameLayout imageCard = new FrameLayout(this); imageCard.setClipChildren(true); imageCard.setClipToPadding(true); imageCard.setBackgroundColor(Color.TRANSPARENT); imageCard.setOutlineProvider(new ViewOutlineProvider() { @Override public void getOutline(View view, Outline outline) { outline.setRoundRect(0, 0, view.getWidth(), view.getHeight(), dp(12)); } }); imageCard.setClipToOutline(true);
        if (FILE_VIDEO_RESUME_SOURCE.equals(program.sourcePackage)
                || FREEBOX_FOLDER_SOURCE.equals(program.sourcePackage)) {
            playbackBadgePrograms.put(imageCard, program);
            imageCard.addOnAttachStateChangeListener(playbackBadgeAttachListener);
        }
        // No permanent blue frame around an unfocused thumbnail. The yellow
        // focus border below remains the only border drawn by the launcher.
        FrameLayout imageFrame = new FrameLayout(this); imageFrame.setTag("jojo_program_tile_artwork_frame"); imageFrame.setClipChildren(true); imageFrame.setClipToPadding(true); imageFrame.setBackgroundColor(Color.TRANSPARENT); imageFrame.setOutlineProvider(new ViewOutlineProvider() { @Override public void getOutline(View view, Outline outline) { outline.setRoundRect(0, 0, view.getWidth(), view.getHeight(), dp(12)); } }); imageFrame.setClipToOutline(true);
        // SmartTube resumes use the exact same landscape artwork treatment as
        // the Freebox Videos row. FIT_CENTER produced a different framing and
        // left the thumbnail visibly inconsistent with the other video cards.
        ImageView artwork = new ImageView(this);
        boolean externalLogo = isExternalLiveProgram(program);
        if (externalLogo) artwork.setContentDescription("live-channel-logo");
        artwork.setScaleType(externalLogo ? ImageView.ScaleType.FIT_CENTER : ImageView.ScaleType.CENTER_CROP);
        artwork.setPadding(externalLogo ? dp(24) : 0, externalLogo ? dp(18) : 0,
                externalLogo ? dp(24) : 0, externalLogo ? dp(18) : 0);
        // Keep the source thumbnail at full opacity. The previous .72 alpha
        // permanently veiled Continue Watching artwork and made dark areas
        // look grainy through hardware-layer compositing.
        artwork.setBackground(null); artwork.setAlpha(1f); imageCard.addView(artwork, new FrameLayout.LayoutParams(-1, -1));
        if (externalLogo) artwork.setBackgroundColor(compactCategoryThumbnail
                ? Color.BLACK : Color.rgb(245, 245, 245));
        boolean externalVideo = "external-playback".equals(program.sourcePackage)
                || "external-playback-series-episode".equals(program.sourcePackage);
        boolean episode = "external-playback-series-episode".equals(program.sourcePackage)
                || ("external-playback".equals(program.sourcePackage)
                && program.episodeNumber != null && !program.episodeNumber.trim().isEmpty());
        if (episode) {
            imageCard.setTag("series_episode_status_host");
        }
        if (externalVideo) {
            boolean watched = episode && (program.watched
                    || (program.duration > 0L && (float) program.position / program.duration
                    >= WatchProgress.EPISODE_COMPLETED_THRESHOLD));
            if (watched) {
                addEpisodeWatchedBadge(imageCard);
            }
        }
        if (FREEBOX_FOLDER_SOURCE.equals(program.sourcePackage)) {
            // Use the original badge artwork: it already contains the exact
            // pale folder shape and black play triangle used before the
            // dynamic-tint change.
            ImageView folderBadge = new ImageView(this);
            Bitmap badgeBitmap = dynamicFolderBadgeBitmap(folderInnerIconTint());
            if (badgeBitmap != null) folderBadge.setImageBitmap(badgeBitmap);
            else folderBadge.setImageResource(R.drawable.images);
            folderBadge.setScaleType(ImageView.ScaleType.CENTER_INSIDE);
            folderBadge.setContentDescription("Dossier");
            folderBadge.setBackgroundColor(Color.TRANSPARENT);
            FrameLayout.LayoutParams badgeParams = new FrameLayout.LayoutParams(dp(42), dp(42), Gravity.BOTTOM | Gravity.RIGHT);
            // Keep the folder marker slightly inset from the lower-right
            // corner of the Videos card, without touching the rounded edge.
            badgeParams.setMargins(0, 0, dp(4), dp(4));
            imageCard.addView(folderBadge, badgeParams);
        }
        if (isThumbnailInProgress(program)
                && imageCard.findViewWithTag("series_episode_status_badge") == null) {
            addInProgressBadge(imageCard);
        }
        View border = new View(this); border.setBackground(continueWatchingTileFocusBorder()); border.setAlpha(0f);
        imageFrame.addView(imageCard, new FrameLayout.LayoutParams(-1, -1));
        imageFrame.addView(border, new FrameLayout.LayoutParams(-1, -1));
        int artworkHeightDp = portraitArtwork ? 240 : continueWatchingTileHeightDp() + 4;
        if (compactCategoryThumbnail) artworkHeightDp = Math.round(artworkHeightDp * compactArtworkScale);
        card.addView(imageFrame, new LinearLayout.LayoutParams(-1, dp(artworkHeightDp)));
        String videoTitle = SystemContinueWatching.displayTitle(program.title, program.description);
        if (isIptvProgram(program)) {
            videoTitle = displayIptvTitle(videoTitle, program.seasonNumber, program.episodeNumber);
        }
        if (FILE_VIDEO_RESUME_SOURCE.equals(program.sourcePackage)) videoTitle = displayVideoTitle(videoTitle);
        final String titleWithoutDuration = videoTitle;
        // Freebox videos keep their duration in the title when they move to
        // Continue Watching, just as they do in the Videos row. The previous
        // flag was only enabled for the dedicated Videos row, so the duration
        // disappeared after the video acquired progress.
        if (!hideDurationBeforeTitle
                && (showDurationBeforeTitle || FILE_VIDEO_RESUME_SOURCE.equals(program.sourcePackage))
                && program.duration > 0L) {
            videoTitle = SystemContinueWatching.compactPlaybackTimeLabel(program.duration).replace(" min", "min") + " " + videoTitle;
        }
        TextView title = resumeMarqueeText(videoTitle, 15, Color.WHITE);
        Runnable loadDuration = () -> loadVisibleSmbProgramDuration(card, program, title,
                titleWithoutDuration, !hideDurationBeforeTitle
                        && (showDurationBeforeTitle || FILE_VIDEO_RESUME_SOURCE.equals(program.sourcePackage)));
        card.addOnLayoutChangeListener((view, left, top, right, bottom, oldLeft, oldTop, oldRight, oldBottom) -> loadDuration.run());
        card.addOnAttachStateChangeListener(new View.OnAttachStateChangeListener() {
            @Override public void onViewAttachedToWindow(View view) { view.post(loadDuration); }
            @Override public void onViewDetachedFromWindow(View view) { }
        });
        title.setTypeface(null, 1);
        title.setPadding(dp(2), dp(5), dp(2), 0);
        if (portraitArtwork) {
            title.setSingleLine(false);
            title.setHorizontallyScrolling(false);
            title.setMaxLines(2);
            title.setEllipsize(TextUtils.TruncateAt.END);
        }
        if (compactCategoryThumbnail && !showCompactCategoryTitle) title.setVisibility(View.GONE);
        card.addView(title, new LinearLayout.LayoutParams(-1, dp(portraitArtwork ? 50 : 28)));
        String seasonEpisode = isIptvProgram(program) ? "" : seasonEpisodeCode(program.seasonNumber, program.episodeNumber);
        if (!compactCategoryThumbnail && !seasonEpisode.isEmpty()) {
            TextView subtitle = text(seasonEpisode, 12, muted);
            subtitle.setSingleLine(true);
            subtitle.setEllipsize(TextUtils.TruncateAt.END);
            subtitle.setPadding(dp(2), dp(3), dp(2), 0);
            card.addView(subtitle, new LinearLayout.LayoutParams(-1, dp(22)));
        }
        card.setOnKeyListener((v, keyCode, event) -> {
            if (handleContinueWatchingDpad(v, keyCode, event)) return true;
            if (event.getAction() == KeyEvent.ACTION_DOWN && event.getRepeatCount() == 0
                    && keyCode == KeyEvent.KEYCODE_DPAD_LEFT && openHomeRowMoveDrawer(v)) return true;
            if (event.getAction() == KeyEvent.ACTION_DOWN && event.getRepeatCount() == 0
                    && (keyCode == KeyEvent.KEYCODE_DPAD_UP || keyCode == KeyEvent.KEYCODE_DPAD_DOWN)) {
                int targetId = keyCode == KeyEvent.KEYCODE_DPAD_UP ? v.getNextFocusUpId() : v.getNextFocusDownId();
                View target = targetId == View.NO_ID ? null : v.getRootView().findViewById(targetId);
                if (target != null && target.isFocusable()) {
                    target.requestFocus();
                    return true;
                }
            }
            if (event.getAction() == KeyEvent.ACTION_DOWN && event.getRepeatCount() == 0
                    && (keyCode == KeyEvent.KEYCODE_DPAD_LEFT || keyCode == KeyEvent.KEYCODE_DPAD_RIGHT)) {
                // HorizontalScrollView may ignore nextFocusLeftId at the edge
                // of a row. Request the configured target explicitly so the
                // first card also wraps to the last one from the left.
                int targetId = keyCode == KeyEvent.KEYCODE_DPAD_LEFT
                        ? v.getNextFocusLeftId() : v.getNextFocusRightId();
                View target = targetId == View.NO_ID ? null : v.getRootView().findViewById(targetId);
                if (target != null && target.isFocusable()) {
                    target.requestFocus();
                    return true;
                }
            }
            return keepHorizontalFocus(v, keyCode, event);
        });
        card.setOnFocusChangeListener((v, focused) -> {
            if (focused) loadDuration.run();
            border.animate().alpha(focused ? 1f : 0f).setDuration(120).start();
            setMarqueeFocus(title, focused);
            // Keep the thumbnail at its original luminosity. Focus is shown by
            // the border and the small scale change, without a gray veil.
            float focusScale = focused && (!compactCategoryThumbnail || scaleCompactArtworkOnFocus)
                    ? 1.04f : 1f;
            artwork.animate().alpha(1f).scaleX(focusScale).scaleY(focusScale).setDuration(120).start();
            if (focused) {
                // Do not keep the artwork of the folder/video that previously
                // had focus while this tile is waiting for its own artwork.
                if (!compactCategoryThumbnail) clearFocusedResumeArtwork();
                revealResumeCard(v);
                // Category pages have their own opaque Hero; the Home wallpaper is hidden.
                if (!compactCategoryThumbnail) updateDynamicBackground(artwork);
            } else {
                v.post(this::hideFocusedResumeArtworkWhenLeavingRows);
            }
            continueWatchingTileFocusChanged(v, focused);
        });
        card.setOnClickListener(v -> {
            // Save the semantic card key before launching another Activity.
            // onPause() is not reliable on every Android TV/Fire OS player
            // hand-off and may run after focus has already fallen back to the
            // Search header.
            rememberHomeFocus();
            if (FREEBOX_FOLDER_SOURCE.equals(program.sourcePackage)) openSmbFolderHomeShortcut(program.intentUri);
            else if (FILE_VIDEO_RESUME_SOURCE.equals(program.sourcePackage)) openFileVideoResume(program);
            else if ("external-playback".equals(program.sourcePackage)) openExternalPlayback(externalResumeItem(program), false, false);
            else openJojoProgram(program);
        });
        card.setOnLongClickListener(v -> {
            if (FREEBOX_FOLDER_SOURCE.equals(program.sourcePackage)) {
                showFreeboxFolderHomeMenu(program, card, false);
                return true;
            }
            showContinueWatchingMenu(program, card); return true;
        });
        String resumeArtwork = "";
        if (FILE_VIDEO_RESUME_SOURCE.equals(program.sourcePackage)) {
            homeVideosFileArtworkViews.put(artwork, program.intentUri);
            resumeArtwork = homeVideosFileArtwork(program.intentUri, program.title);
        }
        if ("external-playback-series-episode".equals(program.sourcePackage)) {
            // A persisted manual choice takes precedence over the generic resume cache.
            resumeArtwork = selectedSeriesEpisodeArtwork(
                    ExternalPlaybackStore.get(this, program.intentUri), program.artwork);
        } else if (FREEBOX_FOLDER_SOURCE.equals(program.sourcePackage)) {
            resumeArtwork = homeVideosFolderArtwork(program.intentUri);
        } else if (resumeArtwork.isEmpty() && !FILE_VIDEO_RESUME_SOURCE.equals(program.sourcePackage)
                && !("external-playback".equals(program.sourcePackage) && !externalLogo)
                && !("external-playback".equals(program.sourcePackage) && externalLogo)) {
            resumeArtwork = homePrefs().getString(
                    "resume_artwork_" + Integer.toUnsignedString(resumeDismissKey(program).hashCode(), 16), "");
        }
        if (!resumeArtwork.isEmpty()) loadArtwork(artwork, resumeArtwork);
        else if ("com.jojo.tv".equals(program.sourcePackage) || "com.jojo.tv.debug".equals(program.sourcePackage)) {
            // NAS may still contain an older provider-branded image. Show it
            // immediately if necessary, but always resolve the official TMDB
            // artwork in the background; the saved result replaces it on the
            // next bind and survives subsequent NAS refreshes.
            if (program.artwork != null && !program.artwork.isEmpty()) loadArtwork(artwork, program.artwork);
            loadResumeTmdbArtwork(artwork, program);
        }
        else if ("external-playback".equals(program.sourcePackage)) {
            JSONObject externalItem = externalResumeItem(program);
            String providerArtwork = externalPlaybackArtwork(externalItem);
            // Category thumbnails have their own preference.  Do not reuse
            // program.artwork here: on Films/Séries that field is populated
            // from the Hero and made every manual thumbnail selection appear
            // to be ignored after the page was rebuilt.
            String selectedArtwork = externalLogo
                    ? liveChannelArtwork(externalItem, false)
                    : selectedExternalFavoriteArtwork(externalItem);
            if (!ExternalPlaybackStore.supportedUrl(selectedArtwork)) {
                selectedArtwork = ExternalPlaybackStore.supportedUrl(program.artwork)
                        ? program.artwork : providerArtwork;
            }
            String cached = homePrefs().getString(externalLogo
                    ? liveChannelLogoCacheKey(program.intentUri, false)
                    : "resume_artwork_external_" + program.intentUri, "");
            if (!selectedArtwork.isEmpty()) loadArtwork(artwork, selectedArtwork);
            else {
                if (!cached.isEmpty()) loadArtwork(artwork, cached);
                loadExternalResumeArtwork(artwork, program, false);
            }
        }
        else if (!FILE_VIDEO_RESUME_SOURCE.equals(program.sourcePackage)
                && !FREEBOX_FOLDER_SOURCE.equals(program.sourcePackage)
                && program.artwork != null && !program.artwork.isEmpty()) loadArtwork(artwork, program.artwork, isSmartTubePackage(program.sourcePackage));
        else if (FREEBOX_FOLDER_SOURCE.equals(program.sourcePackage))
            loadFreeboxFolderVideoArtwork(artwork, program.title, program.intentUri, true);
        else if (FILE_VIDEO_RESUME_SOURCE.equals(program.sourcePackage)) {
            VideoFrameSource frameSource = null;
            try {
                frameSource = resumeVideoFrameSourceForProgram(program);
            } catch (Exception ignored) { }
            loadVideoArtwork(artwork, program.title, !portraitArtwork, program.intentUri, frameSource, false, false, true);
        }
        else if (isSmartTubePackage(program.sourcePackage) || isTiviMatePackage(program.sourcePackage)) loadResumeSourceArtwork(artwork, program.sourcePackage);
        return card;
    }

    private void refreshVisiblePlaybackBadges() {
        Set<String> startedFolders = null;
        for (Map.Entry<FrameLayout, JojoProgram> entry : new ArrayList<>(playbackBadgePrograms.entrySet())) {
            FrameLayout imageCard = entry.getKey();
            if (imageCard == null || !imageCard.isAttachedToWindow() || !imageCard.isShown()) continue;
            JojoProgram program = entry.getValue();
            boolean folder = FREEBOX_FOLDER_SOURCE.equals(program.sourcePackage);
            boolean started;
            if (folder) {
                if (startedFolders == null) startedFolders = inProgressFreeboxFolderPaths(
                        HomeWatchProgressBridge.currentProfileId(this));
                started = startedFolders.contains(comparableSmbPath(program.intentUri));
            } else {
                long position = loadVideoResume(program.intentUri);
                long duration = program.duration;
                boolean completed = program.watched;
                boolean useSnapshot = HomeWatchProgressBridge.isCloud(this)
                        || (!homePrefs().contains("video_resume_" + program.intentUri)
                        && !homePrefs().contains("video_resume_invalidated_" + program.intentUri));
                for (WatchProgress progress : watchProgressContinueSnapshot) {
                    String path = com.nuvio.tv.data.freebox.FreeboxMediaDisplayKt.freeboxPathFromContentId(progress.getContentId());
                    if (!program.intentUri.equals(path) && !program.intentUri.equals(progress.getContentId())) continue;
                    if (useSnapshot) position = progress.getPosition();
                    if (progress.getDuration() > 0L) duration = progress.getDuration();
                    if (useSnapshot) completed = progress.isCompleted(
                            WatchProgress.completionThreshold(progress.getContentType(), progress.getEpisode()));
                    break;
                }
                started = HomeMediaRules.thumbnailInProgress(position, duration, completed);
            }
            View badge = imageCard.findViewWithTag("series_episode_status_badge");
            if (started && badge == null) addInProgressBadge(imageCard, folder);
            else if (!started && badge != null) clearEpisodeStatusBadge(imageCard);
        }
    }

    private boolean isThumbnailInProgress(JojoProgram program) {
        return program != null && HomeMediaRules.thumbnailInProgress(program.position, program.duration, program.watched)
                && !isExternalLiveProgram(program);
    }

    /** Gather playback state once on the category worker, never while drawing a card. */
    private Set<String> inProgressSeriesFolderKeys(String category, List<JSONObject> items, int profileId) {
        if ("videos".equals(category)) return inProgressFreeboxFolderPaths(profileId);
        Set<String> keys = new HashSet<>();
        if (!"series".equals(category)) return keys;
        boolean hasLegacySeries = false;
        for (JSONObject item : items) {
            if (isSeriesItemInProgress(item, profileId)) keys.add(item.optString("id", ""));
            if (!item.optString("id", "").startsWith("iptv:")) hasLegacySeries = true;
        }
        if (hasLegacySeries) {
            for (JSONObject episode : ExternalPlaybackStore.listAll(this, "series", false)) {
                if (!isSeriesItemInProgress(episode, profileId)) continue;
                for (JSONObject item : items) {
                    if (ExternalPlaybackStore.sameContinueWatchingItem(item, episode)) {
                        keys.add(item.optString("id", ""));
                    }
                }
            }
        }
        return keys;
    }

    private boolean isSeriesItemInProgress(JSONObject item, int profileId) {
        return (!item.has("progressProfileId") || item.optInt("progressProfileId") == profileId)
                && item.optBoolean("seriesStarted", item.optBoolean("started", false)
                || item.optBoolean("watched", false) || item.optLong("position", 0L) > 0L);
    }

    private Set<String> inProgressFreeboxFolderPaths(int profileId) {
        Set<String> folders = new HashSet<>();
        Set<String> startedPaths = new HashSet<>();
        // Read the full started snapshot, rather than the unfinished Hero resumes.
        if (watchProgressSnapshotProfileId == profileId) {
            for (WatchProgress progress : watchProgressContinueSnapshot) {
                if (progress.getPosition() <= 0L && progress.getProgressPercentage() <= 0f) continue;
                String id = progress.getContentId();
                String source;
                if ("freebox".equalsIgnoreCase(progress.getContentType()) || id.startsWith("freebox:")) {
                    source = com.nuvio.tv.data.freebox.FreeboxMediaDisplayKt.freeboxPathFromContentId(id);
                } else if ("video".equalsIgnoreCase(progress.getContentType())) source = id;
                else continue;
                if (!HomeWatchProgressBridge.isCloud(this) && homePrefs().getInt("video_resume_invalidation_profile_" + source, 1) == profileId
                        && progress.getLastWatched() <= homePrefs().getLong("video_resume_invalidated_" + source, -1L)) continue;
                startedPaths.add(source);
            }
        }
        // Older file players keep their completed episodes in this local store.
        try {
            JSONArray stored = new JSONArray(HomeWatchProgressBridge.isCloud(this) ? "[]" : homePrefs().getString(FILE_VIDEO_RESUMES, "[]"));
            for (int index = 0; index < stored.length(); index++) {
                JSONObject item = stored.optJSONObject(index);
                if (item == null || item.optInt("profileId", 1) != profileId || item.optLong("position", 0L) <= 0L) continue;
                String key = item.optString("key", "");
                String source = item.optString("source", "");
                if (key.isEmpty() || source.isEmpty()) continue;
                if (homePrefs().getInt("video_resume_invalidation_profile_" + key, 1) == profileId
                        && item.optLong("updatedAt", 0L) <= homePrefs().getLong("video_resume_invalidated_" + key, -1L)) continue;
                startedPaths.add(source);
            }
        } catch (org.json.JSONException ignored) { }
        for (String source : startedPaths) {
            if (hasDeletedFreeboxPath(source)) continue;
            String path = comparableSmbPath(source);
            if (!path.startsWith("smb://")) continue;
            // Include the series and season ancestors; exact paths avoid homonymous folders.
            for (int separator = path.lastIndexOf('/'); separator > 6;
                    separator = path.lastIndexOf('/', separator - 1)) {
                folders.add(path.substring(0, separator));
            }
        }
        return folders;
    }

