    private void applyPopupRowFocus(View row, GradientDrawable normalBg, GradientDrawable focusBg) {
        if (!(row instanceof ViewGroup)) return;
        ViewGroup vg = (ViewGroup) row;
        if (vg.getChildCount() < 2 || !(vg.getChildAt(0) instanceof ImageView) || !(vg.getChildAt(1) instanceof TextView)) return;
        ImageView symbol = (ImageView) vg.getChildAt(0);
        TextView title = (TextView) vg.getChildAt(1);
        row.setOnFocusChangeListener((v, focused) -> {
            int foreground = focused ? contrastingFolderThemeTextColor() : popupTitleColor();
            symbol.setColorFilter(focused ? foreground : popupMenuIconTint());
            v.setBackground(focused ? focusBg : normalBg);
            title.setTextColor(foreground);
            setMarqueeFocus(title, focused);
        });
    }
    private void finalizePopupMenu(LinearLayout menu) {
        int count = menu.getChildCount();
        if (count == 0) return;
        if (count == 1) {
            View single = menu.getChildAt(0);
            single.setBackground(popupRowSingleBg());
            applyPopupRowFocus(single, popupRowSingleBg(), popupFocusSingleBg());
            return;
        }
        for (int i = 0; i < count; i++) {
            View row = menu.getChildAt(i);
            if (i == 0) {
                row.setBackground(popupRowTopBg());
                applyPopupRowFocus(row, popupRowTopBg(), popupFocusTopBg());
            } else if (i == count - 1) {
                row.setBackground(popupRowBottomBg());
                applyPopupRowFocus(row, popupRowBottomBg(), popupFocusBottomBg());
            } else {
                row.setBackground(popupRowMiddleBg());
                applyPopupRowFocus(row, popupRowMiddleBg(), popupFocusMiddleBg());
            }

        }
        View[] rows = new View[count];
        for (int i = 0; i < count; i++) rows[i] = menu.getChildAt(i);
        wireCyclicVerticalFocus(rows);
    }

    private void wireCyclicVerticalFocus(View... items) {
        if (items == null || items.length < 2) return;
        View first = items[0];
        View last = items[items.length - 1];
        for (int i = 0; i < items.length; i++) {
            View current = items[i];
            current.setNextFocusUpId(i == 0 ? last.getId() : items[i - 1].getId());
            current.setNextFocusDownId(i == items.length - 1 ? first.getId() : items[i + 1].getId());
        }
        ViewParent parent = first.getParent();
        if (parent instanceof ViewGroup && parent == last.getParent()) {
            ((ViewGroup) parent).setTag("cyclic_vertical_focus_group");
        }
    }

    private boolean handleCyclicVerticalGroupDpad(KeyEvent event) {
        if (event == null || event.getAction() != KeyEvent.ACTION_DOWN
                || event.getRepeatCount() != 0
                || (event.getKeyCode() != KeyEvent.KEYCODE_DPAD_UP
                && event.getKeyCode() != KeyEvent.KEYCODE_DPAD_DOWN)) return false;
        View focused = getCurrentFocus();
        View current = focused;
        while (current != null) {
            if (current instanceof ViewGroup
                    && "cyclic_vertical_focus_group".equals(current.getTag())) {
                ViewGroup group = (ViewGroup) current;
                int index = group.indexOfChild(focused);
                if (index < 0) return false;
                int count = group.getChildCount();
                if (count < 2) return true;
                int targetIndex = event.getKeyCode() == KeyEvent.KEYCODE_DPAD_UP
                        ? (index + count - 1) % count : (index + 1) % count;
                View target = group.getChildAt(targetIndex);
                if (target != null && target.isFocusable()) target.requestFocus();
                return true;
            }
            ViewParent parent = current.getParent();
            current = parent instanceof View ? (View) parent : null;
        }
        return false;
    }

