    private String appOrderDeviceSuffix() {
        // The application order belongs to one physical launcher instance.
        // Two Fire Sticks must therefore not share the same NAS key.
        return "device_" + Integer.toUnsignedString(jojoHomeDeviceId().hashCode(), 16);
    }
    private String legacyAppOrderDeviceSuffix() {
        return isFireOsDevice() ? "firetv" : "androidtv";
    }
    private String appOrderKey() {
        String suffix = appOrderDeviceSuffix();
        return suffix.isEmpty() ? "app_order" : "app_order_" + suffix;
    }
    private void migrateAppOrderToDeviceKey() {
        android.content.SharedPreferences prefs = homePrefs();
        String legacyKey = "app_order";
        String deviceKey = appOrderKey();
        if (!deviceKey.equals(legacyKey) && !prefs.contains(deviceKey)) {
            if (prefs.contains(legacyKey)) {
                prefs.edit().putString(deviceKey, prefs.getString(legacyKey, "")).remove(legacyKey).apply();
            } else if (prefs.contains("app_order_" + legacyAppOrderDeviceSuffix())) {
                // Migrate the previous platform-wide key. It is only a
                // one-time seed; all subsequent changes use the physical
                // device key above.
                prefs.edit().putString(deviceKey, prefs.getString("app_order_" + legacyAppOrderDeviceSuffix(), "")).apply();
            }
        }
    }
    private List<String> appOrderForDeviceSuffix(String suffix) {
        String serialized = homePrefs().getString("app_order_" + suffix, "");
        List<String> result = new ArrayList<>();
        if (!serialized.isEmpty()) Collections.addAll(result, serialized.split("\\|"));
        return result;
    }
    private List<String> appOrder() {
        migrateAppOrderToDeviceKey();
        String serialized = homePrefs().getString(appOrderKey(), "");
        List<String> result = new ArrayList<>(); if (!serialized.isEmpty()) Collections.addAll(result, serialized.split("\\|")); return result;
    }
    private void beginAppMove(String packageName) {
        // A manual move must take effect even if the user previously chose the
        // alphabetical display mode.  The current visible sequence becomes the
        // initial manual order on the first Left/Right press.
        if (AppPresentationRules.isAlphabeticalOrder(appSortMode())) {
            homePrefs().edit().putString("app_sort_mode", "manual").apply();
        }
        movingPackageName = packageName;
        applyAppMovePresentation();
    }
    private void finishAppMove() {
        String movedPackage = movingPackageName;
        movingPackageName = null;
        applyAppMovePresentation();
        View moved = findRenderedAppTile(movedPackage);
        if (moved != null) moved.post(moved::requestFocus);
    }
    private void applyAppMovePresentation() {
        boolean movingRow = movingPackageName != null;
        for (ViewGroup row : renderedAppRows) {
            boolean rowContainsMovingPackage = false;
            for (int index = 0; index < row.getChildCount(); index++) {
                View tile = row.getChildAt(index);
                if (tile.getTag() instanceof String && tile.getTag().equals(movingPackageName)) {
                    rowContainsMovingPackage = true;
                    break;
                }
            }
            for (int index = 0; index < row.getChildCount(); index++) {
                View tile = row.getChildAt(index);
                boolean moving = rowContainsMovingPackage && tile.getTag() instanceof String && tile.getTag().equals(movingPackageName);
                float targetScaleX = moving ? 1.18f : (movingRow ? unfocusedScaleX() * 0.94f : unfocusedScaleX());
                float targetScaleY = moving ? 1.18f : (movingRow ? unfocusedScaleY() * 0.94f : unfocusedScaleY());
                tile.animate().alpha(moving ? 1f : (movingRow ? .38f : 1f)).scaleX(targetScaleX).scaleY(targetScaleY).setDuration(90).start();
                tile.setElevation(!movingRow && tile.hasFocus() ? dp(20) : 0);
                if (tile instanceof ViewGroup && ((ViewGroup) tile).getChildCount() > 0) {
                    View iconStage = ((ViewGroup) tile).getChildAt(0);
                    iconStage.setElevation(AppTileRules.elevatesTransparentStageOnFocus()
                            && !movingRow && tile.hasFocus() ? dp(14) : 0);
                }
            }
        }
    }
    private ArrayList<View> renderedAppTiles() {
        ArrayList<View> result = new ArrayList<>();
        for (ViewGroup row : renderedAppRows) {
            for (int index = 0; index < row.getChildCount(); index++) {
                View tile = row.getChildAt(index);
                if (tile.getTag() instanceof String) result.add(tile);
            }
        }
        return result;
    }
    private ArrayList<View> renderedAppViews() {
        ArrayList<View> result = new ArrayList<>();
        for (ViewGroup row : renderedAppRows) {
            for (int index = 0; index < row.getChildCount(); index++) result.add(row.getChildAt(index));
        }
        return result;
    }
    private View findRenderedAppTile(String packageName) {
        if (packageName == null) return null;
        for (ViewGroup row : renderedAppRows) {
            View tile = row.findViewWithTag(packageName);
            if (tile != null) return tile;
        }
        return null;
    }
    private GridLayout.LayoutParams appTileGridParams(int columnIndex) {
        GridLayout.LayoutParams params = new GridLayout.LayoutParams();
        params.rowSpec = GridLayout.spec(0);
        params.columnSpec = GridLayout.spec(columnIndex);
        params.width = dp(iconTileWidth());
        params.height = dp(iconTileHeight());
        params.setMargins(dp(1), dp(4), dp(1), dp(4));
        return params;
    }
    private boolean isVerticalAppColumn() {
        if (renderedAppRows.size() != 1 || !(renderedAppRows.get(0) instanceof LinearLayout)) return false;
        return ((LinearLayout) renderedAppRows.get(0)).getOrientation() == LinearLayout.VERTICAL;
    }
    private void reorderRenderedAppTilesInPlace(List<View> orderedTiles) {
        boolean verticalColumn = isVerticalAppColumn();
        int nextIndex = 0;
        for (ViewGroup row : renderedAppRows) {
            int rowSize = row.getChildCount();
            row.removeAllViews();
            for (int columnIndex = 0; columnIndex < rowSize && nextIndex < orderedTiles.size(); columnIndex++) {
                View tile = orderedTiles.get(nextIndex++);
                if (row instanceof GridLayout) {
                    row.addView(tile, appTileGridParams(columnIndex));
                } else {
                    ViewGroup.LayoutParams params = tile.getLayoutParams();
                    if (params == null) row.addView(tile);
                    else row.addView(tile, params);
                }
            }
            if (verticalColumn) {
                ArrayList<View> columnTiles = new ArrayList<>();
                for (int index = 0; index < row.getChildCount(); index++) {
                    columnTiles.add(row.getChildAt(index));
                }
                wireCyclicVerticalFocus(columnTiles.toArray(new View[0]));
            } else {
                wireAppRowDpad(row);
            }
        }
        if (!verticalColumn) wireRenderedAppHorizontalDpad();
    }
    private void wireRenderedAppHorizontalDpad() {
        ArrayList<View> tiles = renderedAppViews();
        for (int index = 0; index < tiles.size(); index++) {
            View tile = tiles.get(index);
            if (tile == null || !tile.isFocusable()) continue;
            if (tile.getId() == View.NO_ID) tile.setId(View.generateViewId());
            View left = tiles.get(Math.max(0, index - 1));
            View right = tiles.get(Math.min(tiles.size() - 1, index + 1));
            tile.setNextFocusLeftId(left.getId());
            tile.setNextFocusRightId(right.getId());
        }
    }
    private void updateAppRowEdges(ViewGroup row) { wireAppRowDpad(row); }
    private void refreshHomeAppRows() {
        if (movingPackageName != null) pendingFocusPackage = movingPackageName;
        goHome();
    }
    private void moveApp(int delta) {
        if (movingPackageName == null) return;
        try {
            ArrayList<View> tiles = renderedAppTiles();
            ArrayList<String> packages = new ArrayList<>();
            for (View t : tiles) if (t.getTag() instanceof String) packages.add((String) t.getTag());
            int currentIndex = packages.indexOf(movingPackageName);
            if (currentIndex < 0) return;
            int targetIndex = currentIndex + delta;
            if (targetIndex < 0 || targetIndex >= packages.size()) return;
            // Move exactly one visual slot in place.  Recreating the entire home
            // here caused remote-input latency, lost focus and skipped positions.
            View movingTile = tiles.get(currentIndex);
            packages.remove(currentIndex);
            packages.add(targetIndex, movingPackageName);
            homePrefs().edit().putString(appOrderKey(), joinOrder(packages)).apply();
            ArrayList<View> orderedTiles = renderedAppViews();
            int movingVisualIndex = orderedTiles.indexOf(movingTile);
            if (movingVisualIndex < 0) return;
            orderedTiles.remove(movingVisualIndex);
            orderedTiles.add(targetIndex, movingTile);
            reorderRenderedAppTilesInPlace(orderedTiles);
            applyAppMovePresentation();
            // Rebuilding the GridLayout briefly detaches the focused tile. If
            // focus is not restored synchronously, Android's fallback search
            // sends it to the first header control (Rechercher).
            movingTile.requestFocus();
            movingTile.post(() -> {
                movingTile.requestFocus();
                revealAppTile(movingTile);
            });
        } catch (Exception ignored) {
            // Avoid crashing if view state changed concurrently
        }
    }
    private void reorderGridChildren(ViewGroup row, int current, int target) {
        if (!(row instanceof GridLayout)) return;
        GridLayout grid = (GridLayout) row;
        ArrayList<View> children = new ArrayList<>();
        for (int index = 0; index < grid.getChildCount(); index++) children.add(grid.getChildAt(index));
        if (current < 0 || current >= children.size() || target < 0 || target >= children.size()) return;
        View moving = children.remove(current);
        children.add(target, moving);
        grid.removeAllViews();
        for (View child : children) {
            ViewGroup.LayoutParams params = child.getLayoutParams();
            if (params != null) grid.addView(child, params);
            else grid.addView(child);
        }
        grid.requestLayout();
    }
    private String joinOrder(List<String> packages) { StringBuilder builder = new StringBuilder(); for (String value : packages) { if (builder.length() > 0) builder.append('|'); builder.append(value); } return builder.toString(); }
