    /** Match the date/clock container to its visible text so its centering does not create a false final gap. */
    private int headerDateTimeWidth(TextView date, TextView clock) {
        float dateWidth = date == null ? 0f : date.getPaint().measureText(String.valueOf(date.getText()));
        float clockWidth = clock == null ? 0f : clock.getPaint().measureText(String.valueOf(clock.getText()));
        // Long French dates such as "Dimanche 6 Septembre" need a little
        // more than the former 190 dp cap. Keep the width content-driven so
        // shorter dates do not create a larger gap before the account item.
        return Math.max(dp(96), Math.min(dp(230), Math.round(Math.max(dateWidth, clockWidth)) + dp(14)));
    }

    /**
     * Keeps all labels intact while distributing the actual remaining pixels evenly.
     * This runs after optional header items have been filtered, so Account always
     * reaches the date/clock block instead of leaving a hard-coded empty area.
     */
    private void layoutTopBarItems(LinearLayout bar) {
        ArrayList<View> visibleItems = new ArrayList<>();
        for (int index = 0; index < bar.getChildCount(); index++) {
            View child = bar.getChildAt(index);
            if ("header_group_spacer".equals(child.getTag())) {
                LinearLayout.LayoutParams spacerParams = (LinearLayout.LayoutParams) child.getLayoutParams();
                if (spacerParams.width != 0 || spacerParams.weight != 1f || spacerParams.rightMargin != 0) {
                    spacerParams.width = 0;
                    spacerParams.weight = 1f;
                    spacerParams.rightMargin = 0;
                    child.setLayoutParams(spacerParams);
                }
            } else if (child.getVisibility() == View.VISIBLE) visibleItems.add(child);
            else {
                LinearLayout.LayoutParams hiddenParams = (LinearLayout.LayoutParams) child.getLayoutParams();
                if (hiddenParams.rightMargin != 0) {
                    hiddenParams.rightMargin = 0;
                    child.setLayoutParams(hiddenParams);
                }
            }
        }
        int count = visibleItems.size();
        if (count == 0) return;
        // Do not use the physical screen width here: inner pages have their
        // own side padding, so their header can be narrower than Home.
        // Measuring the actual bar keeps every icon inside its container.
        int availableWidth = bar.getWidth() - bar.getPaddingLeft() - bar.getPaddingRight();
        if (availableWidth <= 0) {
            availableWidth = getResources().getDisplayMetrics().widthPixels - (safeEdgeInset() * 2) - dp(16);
        }
        for (View child : visibleItems) {
            LinearLayout.LayoutParams params = (LinearLayout.LayoutParams) child.getLayoutParams();
            if (child == bar.findViewWithTag("storage") || child == bar.findViewWithTag("nas")) {
                if (params.width != dp(118)) {
                    params.width = dp(118);
                    child.setLayoutParams(params);
                }
            }
        }
        int usedWidth = 0;
        for (View child : visibleItems) {
            LinearLayout.LayoutParams params = (LinearLayout.LayoutParams) child.getLayoutParams();
            usedWidth += Math.max(0, params.width);
        }
        int gap = count > 1 ? Math.max(dp(3), (availableWidth - usedWidth) / (count - 1)) : 0;
        gap = Math.min(gap, dp(18));
        for (int index = 0; index < count; index++) {
            View child = visibleItems.get(index);
            LinearLayout.LayoutParams params = (LinearLayout.LayoutParams) child.getLayoutParams();
            int rightMargin = index == count - 1 ? 0 : gap;
            if (params.rightMargin != rightMargin) {
                params.rightMargin = rightMargin;
                child.setLayoutParams(params);
            }
        }
    }
    private View headerCommand(int drawable, String labelText, View.OnClickListener click) {
        return headerCommand(drawable, labelText, click, 1f);
    }
    private View headerCommand(int drawable, String labelText, View.OnClickListener click, float iconScale) {
        LinearLayout command = new LinearLayout(this);
        command.setOrientation(LinearLayout.VERTICAL);
        command.setGravity(Gravity.CENTER);
        command.setContentDescription(labelText);
        command.setFocusable(true);
        command.setClipChildren(false);
        command.setClipToPadding(false);
        command.setPadding(dp(4), 0, dp(4), 0);

        FrameLayout iconContainer = new FrameLayout(this);
        iconContainer.setClipToPadding(false);
        iconContainer.setClipChildren(false);
        iconContainer.setBackground(topBarIconBg(false));
        ImageView icon = new ImageView(this);
        icon.setTag("header_icon");
        icon.setImageResource(drawable);
        icon.setPadding(dp(3), dp(3), dp(3), dp(3));
        icon.setColorFilter(Color.WHITE);
        icon.setScaleX(iconScale);
        icon.setScaleY(iconScale);
        // Android TV: 52 dp focus disc and 24 dp visible glyph.  This command
        // grows to 1.14 on focus, hence the 46 dp container and 27 dp image.
        iconContainer.addView(icon, new FrameLayout.LayoutParams(dp(27), dp(27), Gravity.CENTER));

        TextView label = text(labelText, 9, muted);
        label.setGravity(Gravity.CENTER);
        label.setSingleLine(true);
        LinearLayout content = new LinearLayout(this);
        content.setGravity(Gravity.CENTER_VERTICAL);
        content.setClipChildren(false);
        content.setClipToPadding(false);
        content.addView(iconContainer, new LinearLayout.LayoutParams(dp(46), dp(46)));
        LinearLayout.LayoutParams labelParams = new LinearLayout.LayoutParams(headerLabelWidth(labelText), dp(46));
        labelParams.leftMargin = dp(2);
        content.addView(label, labelParams);
        command.addView(content, new LinearLayout.LayoutParams(-2, dp(46)));
        command.addView(headerFocusIndicator(), headerFocusIndicatorParams(labelText));
        command.setOnClickListener(click);
        command.setOnFocusChangeListener((v, focused) -> {
            iconContainer.setBackground(topBarIconBg(focused));
            command.animate().scaleX(focused ? 1.14f : 1f).scaleY(focused ? 1.14f : 1f).setDuration(120).start();
            label.setTextColor(focused ? folderThemeColor() : muted);
            label.setTypeface(null, focused ? 1 : 0);
            updateHeaderFocusIndicator(command, focused);
            ImageView iconView = icon;
            if (iconView instanceof ImageView) {
                Object marker = v.getTag(R.id.network_header_marker);
                if (marker instanceof Boolean && ((Boolean) marker)) {
                    // network header handled elsewhere; keep its drawable colors
                } else {
                    if (focused) iconView.setColorFilter(folderThemeColor());
                    else iconView.setColorFilter(Color.WHITE);
                }
            }
        });
        command.setLayoutParams(new LinearLayout.LayoutParams(
                dp(46) + dp(6) + headerLabelWidth(labelText), dp(HOME_HEADER_ITEM_HEIGHT_DP)));
        return command;
    }
    private IptvStore homeAccountStore() {
        if (homeAccountStore == null) homeAccountStore = new IptvStore(getApplicationContext());
        return homeAccountStore;
    }

    private void refreshHomeHeaderAccount() {
        if (isDestroyed() || homeAccountExecutor.isShutdown()) return;
        if (homeAccountSelectionPending) { homeHeaderAccountRefreshPending = true; return; }
        if (homeHeaderAccountLoading) { homeHeaderAccountRefreshPending = true; return; }
        homeHeaderAccountLoading = true;
        final int requestGeneration = homeAccountChangeGeneration;
        IptvStore store = homeAccountStore();
        boolean loadFromDisk = !homeHeaderAccountLoaded;
        homeAccountExecutor.execute(() -> {
            try {
                if (loadFromDisk) store.load();
                List<IptvAccount> accounts = store.accounts();
                IptvAccount account = store.selectedAccount();
                List<IptvAvatar> avatars = store.cachedAvatars();
                runOnUiThread(() -> {
                    if (isDestroyed()) return;
                    if (requestGeneration != homeAccountChangeGeneration) {
                        finishHomeHeaderAccountRefresh();
                        return;
                    }
                    boolean changed = homeHeaderAccountLoaded && !java.util.Objects.equals(homeHeaderAccount, account);
                    updateHomeHeaderAccount(accounts, account, avatars);
                    finishHomeHeaderAccountRefresh();
                    if (changed && (activePopup == null || !activePopup.isShowing())) refreshActiveHomeAccountSettingsPage();
                });
            } catch (Exception ignored) {
                runOnUiThread(this::finishHomeHeaderAccountRefresh);
            }
        });
    }

    private void finishHomeHeaderAccountRefresh() {
        homeHeaderAccountLoading = false;
        if (homeHeaderAccountRefreshPending) {
            homeHeaderAccountRefreshPending = false;
            refreshHomeHeaderAccount();
        }
    }

    private void updateHomeHeaderAccount(List<IptvAccount> accounts, IptvAccount account, List<IptvAvatar> avatars) {
        homeHeaderAccountLoaded = true;
        homeHeaderAccounts = accounts;
        homeHeaderAccount = account;
        homeHeaderAccountAvatars = avatars;
        ArrayList<View> roots = new ArrayList<>(screenBackStack);
        roots.add(getWindow().getDecorView());
        roots.add(currentHomeShell);
        Set<View> updated = new HashSet<>();
        for (View root : roots) {
            View command = findTopBarItemByKey(root, "profile");
            if (command != null && updated.add(command)) applyHomeHeaderAccount(command);
        }
    }

    private void applyHomeHeaderAccount(View command) {
        FrameLayout slot = command.findViewWithTag("header_account_icon_slot");
        if (slot == null) return;
        ImageView original = (ImageView) slot.getChildAt(0);
        View portrait = slot.getChildCount() > 1 ? slot.getChildAt(1) : null;
        boolean focused = command.hasFocus();
        original.setBackground(profileHeaderIconBg(focused));
        original.setColorFilter(focused ? contrastingFolderThemeTextColor() : Color.WHITE);
        original.setVisibility(homeHeaderAccount == null ? View.VISIBLE : View.GONE);
        if (homeHeaderAccount == null) {
            if (portrait != null) slot.removeView(portrait);
            slot.setBackgroundColor(Color.TRANSPARENT);
            command.setContentDescription("Compte");
            return;
        }
        Object binding = java.util.Arrays.asList(homeHeaderAccount, homeHeaderAccountAvatars,
                homePrefs().getString("nas_url", BuildConfig.JOJOTV_NAS_SYNC_URL));
        if (portrait == null || !binding.equals(portrait.getTag())) {
            if (portrait != null) slot.removeView(portrait);
            portrait = homeAccountAvatarView(homeAccountStore(), homeHeaderAccount, homeHeaderAccountAvatars, 36);
            portrait.setTag(binding);
            slot.addView(portrait, new FrameLayout.LayoutParams(dp(36), dp(36), Gravity.CENTER));
        }
        slot.setBackground(profileHeaderIconBg(focused));
        command.setContentDescription("Compte · " + homeHeaderAccount.getName());
    }

    private View profileCommand() {
        LinearLayout command = new LinearLayout(this);
        command.setOrientation(LinearLayout.VERTICAL);
        command.setGravity(Gravity.CENTER);
        command.setContentDescription("Compte");
        command.setFocusable(true);
        command.setClipChildren(false);
        command.setClipToPadding(false);

        FrameLayout iconContainer = new FrameLayout(this);
        iconContainer.setTag("header_account_icon_slot");
        ImageView profile = new ImageView(this);
        profile.setTag("header_icon");
        profile.setImageResource(R.drawable.ic_profile_header);
        // The profile vector already contains its thin circular outline. Keep
        // the focus background on that 27 dp icon instead of adding a second,
        // oversized white disc from the 46 dp command container.
        iconContainer.setBackgroundColor(Color.TRANSPARENT);
        profile.setBackground(profileHeaderIconBg(false));
        profile.setColorFilter(Color.WHITE);
        iconContainer.addView(profile, new FrameLayout.LayoutParams(dp(27), dp(27), Gravity.CENTER));
        TextView label = text("Compte", 9, muted);
        label.setGravity(Gravity.CENTER_VERTICAL);
        label.setSingleLine(true);
        LinearLayout content = new LinearLayout(this);
        content.setGravity(Gravity.CENTER_VERTICAL);
        content.setClipChildren(false);
        content.setClipToPadding(false);
        content.addView(iconContainer, new LinearLayout.LayoutParams(dp(46), dp(46)));
        LinearLayout.LayoutParams labelParams = new LinearLayout.LayoutParams(headerLabelWidth("Compte"), dp(46));
        labelParams.leftMargin = dp(2);
        content.addView(label, labelParams);
        command.addView(content, new LinearLayout.LayoutParams(-2, dp(46)));
        command.addView(headerFocusIndicator(), headerFocusIndicatorParams("Compte"));
        command.setOnClickListener(this::showProfileOverlay);
        command.setOnFocusChangeListener((v, focused) -> {
            applyHomeHeaderAccount(command);
            command.animate().scaleX(focused ? 1.14f : 1f).scaleY(focused ? 1.14f : 1f).setDuration(120).start();
            label.setTextColor(focused ? folderThemeColor() : muted);
            label.setTypeface(null, focused ? 1 : 0);
            updateHeaderFocusIndicator(command, focused);
        });
        applyHomeHeaderAccount(command);
        command.addOnAttachStateChangeListener(new View.OnAttachStateChangeListener() {
            @Override public void onViewAttachedToWindow(View view) {
                applyHomeHeaderAccount(command);
                if (!homeHeaderAccountLoaded) refreshHomeHeaderAccount();
            }
            @Override public void onViewDetachedFromWindow(View view) { }
        });
        command.setLayoutParams(new LinearLayout.LayoutParams(
                dp(46) + dp(6) + headerLabelWidth("Compte"), dp(HOME_HEADER_ITEM_HEIGHT_DP)));
        return command;
    }
    private GradientDrawable profileHeaderIconBg(boolean focused) {
        GradientDrawable background = new GradientDrawable();
        background.setShape(GradientDrawable.OVAL);
        background.setColor(focused ? folderButtonThemeColor() : Color.TRANSPARENT);
        if (focused) background.setStroke(dp(1), buttonFocusOutlineColor(folderThemeColor()));
        return background;
    }
    /** Opens the device's source/input screen without assuming a Philips launcher. */
    private void openSystemSources() {
        String[] actions = isFireOsDevice()
                ? new String[] { "android.settings.TV_INPUT_SETTINGS", "com.android.tv.action.VIEW_INPUTS", Settings.ACTION_SETTINGS }
                : new String[] { "com.android.tv.action.VIEW_INPUTS", "android.settings.TV_INPUT_SETTINGS", Settings.ACTION_SETTINGS };
        for (String action : actions) {
            try {
                Intent intent = new Intent(action).addCategory(Intent.CATEGORY_DEFAULT);
                if (intent.resolveActivity(getPackageManager()) == null) continue;
                startActivity(intent);
                return;
            } catch (Exception ignored) { }
        }
        Toast.makeText(this, isFireOsDevice() ? "Réglages des sources Fire TV indisponibles" : "Sélecteur de sources indisponible", Toast.LENGTH_SHORT).show();
    }
    private View createSettingsPanel() {
        LinearLayout root = new LinearLayout(this); root.setOrientation(LinearLayout.HORIZONTAL); root.setBackgroundColor(Color.rgb(12, 22, 41));
        LinearLayout panel = new LinearLayout(this); panel.setOrientation(LinearLayout.VERTICAL); panel.setPadding(dp(24), dp(24), dp(18), dp(22)); panel.setBackgroundColor(Color.rgb(22, 38, 69));
        TextView title = text("⚙  Paramètres", 21, white); title.setTypeface(null, 1); panel.addView(title, new LinearLayout.LayoutParams(-1, dp(66)));
        panel.addView(settingsRow(isFireOsDevice() ? "Paramètres Fire TV" : "Paramètres Android TV", "Réseau, image, son et préférences système", v -> openAndroidTvSettings()), new LinearLayout.LayoutParams(-1, dp(76)));
        panel.addView(settingsRow("Lecteurs réseau", smbConnections().isEmpty() ? "Ajouter un NAS ou un dossier partagé PC" : smbConnections().size() + " lecteur(s) SMB enregistré(s)", v -> openScreen(createSmbConnectionsPage())), new LinearLayout.LayoutParams(-1, dp(76)));
        panel.addView(settingsRow("Paramètres de l’application", "Personnaliser Jojo Home", v -> openScreen(createAppSettingsPage())), new LinearLayout.LayoutParams(-1, dp(76)));
        root.addView(panel, new LinearLayout.LayoutParams(dp(400), -1));
        View dimmedArea = new View(this); dimmedArea.setFocusable(true); root.addView(dimmedArea, new LinearLayout.LayoutParams(0, -1, 1f));
        panel.post(() -> focusFirst(panel)); return root;
    }
    private LinearLayout settingsPageHeader(String title, String backLabel, View.OnClickListener backAction) { LinearLayout header = new LinearLayout(this); header.setGravity(Gravity.CENTER_VERTICAL); header.addView(sectionTitle(title), new LinearLayout.LayoutParams(0, -1, 1f)); if (!TextUtils.isEmpty(backLabel)) { TextView back = text(backLabel, 16, white); back.setGravity(Gravity.CENTER_VERTICAL | Gravity.RIGHT); back.setPadding(dp(14), 0, dp(14), 0); back.setFocusable(true); back.setOnFocusChangeListener((v, focused) -> back.setBackground(focused ? settingsOverlayFocusBg() : new GradientDrawable())); back.setOnClickListener(backAction); header.addView(back, new LinearLayout.LayoutParams(dp(300), -1)); } return header; }
    private TextView buttonRow(String title, String subtitle, View.OnClickListener click) {
        String content = title + (TextUtils.isEmpty(subtitle) ? "" : "\n" + subtitle);
        TextView button = text(content, 17, white);
        button.setTag("settings_option");
        button.setGravity(Gravity.CENTER);
        button.setTextAlignment(View.TEXT_ALIGNMENT_CENTER);
        button.setPadding(dp(20), 0, dp(20), 0);
        button.setFocusable(true);
        button.setBackground(settingsCardBg(false));
        button.setOnClickListener(click);
        button.setOnFocusChangeListener((v, focused) -> {
            button.setBackground(settingsCardBg(focused));
            button.setTextColor(focused ? contrastingFolderThemeTextColor() : Color.WHITE);
            button.setTypeface(null, focused ? Typeface.BOLD : Typeface.NORMAL);
        });
        button.setMinHeight(dp(72));
        return button;
    }
    private TextView settingsRow(String title, String subtitle, View.OnClickListener click) {
        return buttonRow(title, subtitle, click);
    }
    private TextView selectedSettingsRow(String title, String value, View.OnClickListener click) {
        TextView row;
        if (SettingsPresentation.isToggleValue(value)) {
            android.widget.Switch toggle = new android.widget.Switch(this);
            toggle.setSwitchMinWidth(dp(40));
            toggle.setSwitchPadding(dp(20));
            toggle.setSplitTrack(false);
            toggle.setFocusable(true);
            toggle.setOnClickListener(click);
            toggle.setTag("settings_option");
            row = toggle;
        } else row = settingsRow(title, value, click);
        setSelectedSettingText(row, title, value);
        return row;
    }
    private void openAndroidTvSettings() {
        if (isFireTv()) try { startActivity(new Intent().setComponent(new ComponentName("com.amazon.tv.launcher", "com.amazon.tv.launcher.ui.MainSettingsActivity"))); return; } catch (Exception ignored) { }
        try { startActivity(new Intent(Settings.ACTION_SETTINGS)); }
        catch (Exception error) { Toast.makeText(this, "Paramètres système indisponibles", Toast.LENGTH_SHORT).show(); }
    }
    private boolean isFireTv() { return Build.MANUFACTURER != null && Build.MANUFACTURER.toLowerCase(Locale.ROOT).contains("amazon"); }
    private void addSettingsLink(LinearLayout options, String title, String detail, View.OnClickListener action) {
        options.addView(settingsRow(title, detail, action), new LinearLayout.LayoutParams(-1, dp(72)));
    }

    private View createAppSettingsPage() {
        pendingSettingsFocus = "settings_nav_0";
        return createAccountSettingsPage();
    }

    private boolean isHomeAccountSettingsPage(View page) {
        Object navigation = page == null ? null : page.getTag(SETTINGS_NAVIGATION_TAG);
        return navigation instanceof View && "settings_nav_0".equals(((View) navigation).getTag());
    }

    private void refreshActiveHomeAccountSettingsPage() {
        if (!isHomeAccountSettingsPage(activeScreen)) return;
        View focused = activeScreen.findFocus();
        pendingSettingsFocus = focused != null && focused.getTag() instanceof String
                ? (String) focused.getTag() : "account_selected";
        replaceScreen(createAccountSettingsPage());
    }

    private View createAccountSettingsPage() {
        return createAccountSettingsPage(false);
    }

    private View createAccountSettingsPage(boolean addAccountOnLoad) {
        String requestedFocus = pendingSettingsFocus;
        FrameLayout page = createSettingsShell("Compte", settingsSectionDescription(0));
        LinearLayout options = new LinearLayout(this);
        options.setOrientation(LinearLayout.VERTICAL);
        ScrollView scroll = new ScrollView(this);
        scroll.setVerticalScrollBarEnabled(false);
        scroll.addView(options, new ScrollView.LayoutParams(-1, -2));
        ((LinearLayout) page.getTag()).addView(scroll, new LinearLayout.LayoutParams(-1, 0, 1f));
        options.addView(text("Chargement des comptes…", 16, SettingsPresentation.secondaryTextColor()));
        finishSettingsPage(page, options);
        IptvStore store = homeAccountStore();
        final int accountGeneration = homeAccountChangeGeneration;
        homeAccountExecutor.execute(() -> {
            try {
                store.load();
                List<IptvAccount> accounts = store.accounts();
                IptvAccount account = store.selectedAccount();
                List<IptvAvatar> avatars = store.cachedAvatars();
                runOnUiThread(() -> {
                    if (isDestroyed() || activeScreen != page
                            || accountGeneration != homeAccountChangeGeneration) return;
                    updateHomeHeaderAccount(accounts, account, avatars);
                    View focused = page.findFocus();
                    String focusTag = focused != null && focused.getTag() instanceof String
                            ? (String) focused.getTag() : requestedFocus;
                    options.removeAllViews();
                    if (account != null) {
                        LinearLayout selected = homeAccountSettingsRow(store, account, avatars, "Compte sélectionné", v -> {
                            List<IptvAccount> currentAccounts = homeHeaderAccounts;
                            if (currentAccounts.isEmpty()) { refreshActiveHomeAccountSettingsPage(); return; }
                            IptvAccount currentAccount = homeHeaderAccount;
                            String[] names = new String[currentAccounts.size()];
                            int selectedIndex = 0;
                            for (int index = 0; index < currentAccounts.size(); index++) {
                                names[index] = currentAccounts.get(index).getName();
                                if (currentAccount != null && currentAccounts.get(index).getId().equals(currentAccount.getId())) selectedIndex = index;
                            }
                            showChoices(v, names, selectedIndex, index -> selectHomeAccount(store,
                                    currentAccounts.get(index).getId(), null, () -> {
                                        if (activeScreen != page) return;
                                        pendingSettingsFocus = "account_selected";
                                        replaceScreen(createAccountSettingsPage());
                                    }));
                        });
                        selected.setTag("account_selected");
                        options.addView(selected);
                    } else options.addView(text("Aucun compte", 16, SettingsPresentation.secondaryTextColor()));
                    addSettingsLink(options, "Ajouter un compte", "Nom et avatar", v -> showHomeAccountForm(page, store, null));
                    options.getChildAt(options.getChildCount() - 1).setTag("account_add");
                    if (account != null) {
                        addSettingsLink(options, "Éditer le compte", account.getName(), v -> showHomeAccountForm(page, store, account));
                        options.getChildAt(options.getChildCount() - 1).setTag("account_edit");
                        addSettingsLink(options, "Supprimer le compte", account.getName(), v -> showHomeAccountDeletion(page, store, account));
                        options.getChildAt(options.getChildCount() - 1).setTag("account_delete");
                        addSettingsLink(options, "Choisir un avatar", "Avatar, Smileys, Famille et Animaux", v -> {
                            String[] groups = { "avatar", "smileys", "famille", "animaux" };
                            String[] titles = { "Avatar : initiale et couleur", "Smileys", "Famille", "Animaux" };
                            showChoices(v, titles, account.getAvatar().isEmpty() ? 0 : -1, index -> {
                                // Open after the choice popup has dismissed and restored its anchor.
                                page.post(() -> showHomeAccountAvatars(page, store, account, groups[index], titles[index]));
                            });
                        });
                        options.getChildAt(options.getChildCount() - 1).setTag("account_avatar");
                    }
                    styleSettingsOptions(options);
                    pendingSettingsFocus = requestedFocus != null && !requestedFocus.startsWith("settings_nav_")
                            ? requestedFocus : focusTag;
                    finishSettingsPage(page, options);
                    if (addAccountOnLoad) page.post(() -> {
                        if (!isDestroyed() && page.isAttachedToWindow() && activeScreen == page) showHomeAccountForm(page, store, null);
                    });
                });
            } catch (Exception error) {
                runOnUiThread(() -> {
                    if (isDestroyed() || activeScreen != page) return;
                    options.removeAllViews();
                    options.addView(text(error.getMessage(), 16, SettingsPresentation.errorTextColor()));
                    addSettingsLink(options, "Réessayer", "Charger les comptes existants", v -> replaceScreen(createAccountSettingsPage()));
                    styleSettingsControl(options.getChildAt(1));
                    finishSettingsPage(page, options);
                });
            }
        });
        return page;
    }

    private LinearLayout homeAccountSettingsRow(IptvStore store, IptvAccount account, List<IptvAvatar> avatars,
            String detail, View.OnClickListener action) {
        LinearLayout row = new LinearLayout(this);
        row.setGravity(Gravity.CENTER_VERTICAL);
        row.setFocusable(true);
        row.setFocusableInTouchMode(true);
        FrameLayout portrait = homeAccountAvatarView(store, account, avatars, 48);
        LinearLayout.LayoutParams portraitParams = new LinearLayout.LayoutParams(dp(48), dp(48));
        portraitParams.setMarginEnd(dp(16));
        row.addView(portrait, portraitParams);
        row.addView(text(account.getName() + (detail.isEmpty() ? "" : "\n" + detail), 17, SettingsPresentation.textColor()),
                new LinearLayout.LayoutParams(0, -1, 1f));
        row.setOnClickListener(action);
        return row;
    }

    private FrameLayout homeAccountAvatarView(IptvStore store, IptvAccount account, List<IptvAvatar> avatars, int size) {
        FrameLayout portrait = new FrameLayout(this);
        GradientDrawable circle = new GradientDrawable();
        circle.setShape(GradientDrawable.OVAL);
        circle.setColor(SettingsPresentation.backgroundColor());
        portrait.setBackground(circle);
        portrait.setClipToOutline(true);
        TextView initial = text(account.getName().isEmpty() ? "?"
                : account.getName().substring(0, account.getName().offsetByCodePoints(0, 1)).toUpperCase(Locale.ROOT), Math.max(16, size / 2), SettingsPresentation.textColor());
        initial.setGravity(Gravity.CENTER);
        portrait.addView(initial, new FrameLayout.LayoutParams(-1, -1));
        ImageView picture = new ImageView(this);
        picture.setScaleType(ImageView.ScaleType.CENTER_CROP);
        portrait.addView(picture, new FrameLayout.LayoutParams(-1, -1));
        IptvAvatar known = null;
        for (IptvAvatar entry : avatars) {
            if (entry.getId().equals(account.getAvatar()) || !entry.getEmoji().isEmpty() && entry.getEmoji().equals(account.getAvatar())) {
                known = entry;
                if (!entry.getEmoji().isEmpty()) initial.setText(entry.getEmoji());
                break;
            }
        }
        if (known != null) applyHomeAccountInitialColor(circle, initial, known);
        Bitmap cached = known == null ? null : store.cachedAvatarBitmap(known);
        if (cached != null) { picture.setImageBitmap(cached); initial.setVisibility(View.INVISIBLE); }
        boolean refreshCatalog = known == null;
        if (!account.getAvatar().isEmpty() && cached == null && (known == null || !known.getImage().isEmpty())) {
            portrait.getViewTreeObserver().addOnPreDrawListener(new android.view.ViewTreeObserver.OnPreDrawListener() {
                @Override public boolean onPreDraw() {
                    if (!portrait.getGlobalVisibleRect(new android.graphics.Rect())) return true;
                    portrait.getViewTreeObserver().removeOnPreDrawListener(this);
                    cachedArtworkLoadExecutor.execute(() -> {
                        try {
                            List<IptvAvatar> entries = refreshCatalog ? homeAccountAvatarCatalog(store, true) : avatars;
                            for (IptvAvatar entry : entries) {
                                if (!entry.getId().equals(account.getAvatar()) && (entry.getEmoji().isEmpty() || !entry.getEmoji().equals(account.getAvatar()))) continue;
                                Bitmap bitmap = store.cachedAvatarBitmap(entry);
                                if (bitmap == null && !entry.getImage().isEmpty()) {
                                    bitmap = store.avatarBitmap(entry);
                                }
                                Bitmap loaded = bitmap;
                                runOnUiThread(() -> {
                                    // Home keeps detached views in its back stack; retain their loaded avatar too.
                                    if (isDestroyed()) return;
                                    applyHomeAccountInitialColor(circle, initial, entry);
                                    if (!entry.getEmoji().isEmpty()) initial.setText(entry.getEmoji());
                                    if (loaded != null) { picture.setImageBitmap(loaded); initial.setVisibility(View.INVISIBLE); }
                                    else if (entry.getImage().isEmpty()) initial.setVisibility(View.VISIBLE);
                                });
                                break;
                            }
                        } catch (Exception ignored) { }
                    });
                    return true;
                }
            });
        }
        return portrait;
    }

    private void applyHomeAccountInitialColor(GradientDrawable circle, TextView initial, IptvAvatar avatar) {
        Integer color = avatar.initialColor();
        if (color == null) return;
        int foreground = contrastingThemeTextColor(color);
        circle.setColor(color);
        circle.setStroke(dp(1), withAlpha(foreground, 72));
        initial.setTextColor(foreground);
    }

    private List<IptvAvatar> homeAccountAvatarCatalog(IptvStore store, boolean refresh) throws Exception {
        synchronized (store) {
            List<IptvAvatar> avatars = store.cachedAvatars();
            if (!refresh && !avatars.isEmpty()) return avatars;
            try { return store.fetchAvatars(); }
            catch (Exception error) {
                if (avatars.isEmpty()) throw error;
                return avatars;
            }
        }
    }

    private PopupWindow homeAccountSettingsPopup(LinearLayout panel, String title, int height) {
        panel.setOrientation(LinearLayout.VERTICAL);
        panel.setPadding(dp(22), dp(18), dp(22), dp(18));
        panel.setBackground(settingsPanelBackground());
        TextView heading = text(title, 20, SettingsPresentation.textColor());
        heading.setTypeface(null, Typeface.BOLD);
        heading.setPadding(0, 0, 0, dp(16));
        panel.addView(heading, new LinearLayout.LayoutParams(-1, -2));
        PopupWindow popup = new PopupWindow(panel, dp(480), height, true);
        popup.setBackgroundDrawable(new android.graphics.drawable.ColorDrawable(Color.TRANSPARENT));
        popup.setOutsideTouchable(true);
        popup.setElevation(dp(14));
        trackPopup(popup);
        return popup;
    }

    private void showHomeAccountForm(FrameLayout page, IptvStore store, IptvAccount account) {
        LinearLayout panel = new LinearLayout(this);
        PopupWindow popup = homeAccountSettingsPopup(panel, account == null ? "Ajouter un compte" : "Éditer le compte", -2);
        EditText name = settingsField(panel, "Nom du compte", "Nom");
        name.setSingleLine(true);
        name.setInputType(android.text.InputType.TYPE_CLASS_TEXT | android.text.InputType.TYPE_TEXT_FLAG_CAP_WORDS);
        name.setFilters(new android.text.InputFilter[] { new android.text.InputFilter.LengthFilter(40) });
        name.setImeOptions(android.view.inputmethod.EditorInfo.IME_ACTION_DONE | android.view.inputmethod.EditorInfo.IME_FLAG_NO_FULLSCREEN
                | android.view.inputmethod.EditorInfo.IME_FLAG_NO_EXTRACT_UI);
        name.setText(account == null ? "" : account.getName());
        name.setSelection(name.length());
        TextView error = text("", 14, SettingsPresentation.errorTextColor());
        panel.addView(error, new LinearLayout.LayoutParams(-1, -2));
        TextView save = settingsAction("Enregistrer", true, null);
        panel.addView(save, new LinearLayout.LayoutParams(-1, dp(48)));
        TextView cancel = settingsAction("Annuler", false, v -> popup.dismiss());
        panel.addView(cancel, new LinearLayout.LayoutParams(-1, dp(48)));
        name.setNextFocusDownId(save.getId());
        save.setNextFocusUpId(name.getId());
        save.setNextFocusDownId(cancel.getId());
        cancel.setNextFocusUpId(save.getId());
        save.setOnClickListener(v -> {
            IptvAccount next = new IptvAccount(account == null ? UUID.randomUUID().toString() : account.getId(),
                    name.getText().toString().trim(), account == null ? "" : account.getAvatar(),
                    account == null ? "#D3A033" : account.getOrnamentColor());
            changeHomeAccount(page, store, () -> store.saveAccount(next), account == null ? "account_add" : "account_edit", popup, save, error);
        });
        name.setOnEditorActionListener((field, actionId, event) -> {
            if (actionId != android.view.inputmethod.EditorInfo.IME_ACTION_DONE) return false;
            save.requestFocus();
            return true;
        });
        popup.setInputMethodMode(PopupWindow.INPUT_METHOD_NEEDED);
        popup.setSoftInputMode(android.view.WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);
        popup.showAtLocation(getWindow().getDecorView(), Gravity.CENTER, 0, 0);
        name.requestFocus();
    }

    private void showHomeAccountDeletion(FrameLayout page, IptvStore store, IptvAccount account) {
        LinearLayout panel = new LinearLayout(this);
        PopupWindow popup = homeAccountSettingsPopup(panel, "Supprimer le compte", -2);
        panel.addView(text("Supprimer le compte « " + account.getName() + " » ?", 16, SettingsPresentation.textColor()));
        TextView error = text("", 14, SettingsPresentation.errorTextColor());
        panel.addView(error);
        TextView cancel = settingsAction("Annuler", false, v -> popup.dismiss());
        panel.addView(cancel, new LinearLayout.LayoutParams(-1, dp(48)));
        TextView remove = settingsAction("Supprimer", false, null);
        remove.setOnClickListener(v -> changeHomeAccount(page, store, () -> store.deleteAccount(account.getId()),
                "account_selected", popup, remove, error));
        panel.addView(remove, new LinearLayout.LayoutParams(-1, dp(48)));
        wireCyclicVerticalFocus(cancel, remove);
        popup.showAtLocation(getWindow().getDecorView(), Gravity.CENTER, 0, 0);
        cancel.requestFocus();
    }

    private void showHomeAccountAvatars(FrameLayout page, IptvStore store, IptvAccount account, String group, String title) {
        if (activeScreen != page) return;
        LinearLayout panel = new LinearLayout(this);
        int height = Math.min(dp(440), getResources().getDisplayMetrics().heightPixels - dp(100));
        PopupWindow popup = homeAccountSettingsPopup(panel, title, height);
        ScrollView scroll = new ScrollView(this);
        scroll.setVerticalScrollBarEnabled(false);
        LinearLayout rows = new LinearLayout(this);
        rows.setOrientation(LinearLayout.VERTICAL);
        scroll.addView(rows);
        panel.addView(scroll, new LinearLayout.LayoutParams(-1, 0, 1f));
        TextView status = text("Chargement des avatars du NAS…", 16, SettingsPresentation.secondaryTextColor());
        rows.addView(status);
        TextView close = settingsAction("Retour", false, v -> popup.dismiss());
        panel.addView(close, new LinearLayout.LayoutParams(-1, dp(48)));
        popup.showAtLocation(getWindow().getDecorView(), Gravity.CENTER, 0, 0);
        close.requestFocus();
        artworkLoadExecutor.execute(() -> {
            try {
                List<IptvAvatar> entries = homeAccountAvatarCatalog(store, true);
                runOnUiThread(() -> {
                    if (isDestroyed() || !popup.isShowing()) return;
                    if (homeHeaderAccountLoaded) updateHomeHeaderAccount(homeHeaderAccounts, homeHeaderAccount, entries);
                    rows.removeAllViews();
                    View selected = null;
                    ArrayList<View> focusable = new ArrayList<>();
                    for (IptvAvatar avatar : entries) {
                        if (!avatar.getGroup().equals(group)) continue;
                        boolean chosen = account.getAvatar().equals(avatar.getId())
                                || !avatar.getEmoji().isEmpty() && account.getAvatar().equals(avatar.getEmoji());
                        IptvAccount preview = new IptvAccount(account.getId(), account.getName(), avatar.getId(), account.getOrnamentColor());
                        LinearLayout row = homeAccountSettingsRow(store, preview, entries, chosen ? "Sélectionné" : "", null);
                        ((TextView) row.getChildAt(1)).setText(avatar.getName() + (chosen ? "\nSélectionné" : ""));
                        row.setOnClickListener(v -> changeHomeAccount(page, store,
                                () -> store.saveAccount(new IptvAccount(account.getId(), account.getName(), avatar.getId(), account.getOrnamentColor())),
                                "account_avatar", popup, row, null));
                        styleSettingsControl(row);
                        LinearLayout.LayoutParams params = new LinearLayout.LayoutParams(-1, dp(68));
                        params.bottomMargin = dp(6);
                        rows.addView(row, params);
                        focusable.add(row);
                        if (chosen) selected = row;
                    }
                    if (focusable.isEmpty()) rows.addView(text("Aucun avatar dans ce groupe.", 16, SettingsPresentation.secondaryTextColor()));
                    else {
                        focusable.add(close);
                        wireCyclicVerticalFocus(focusable.toArray(new View[0]));
                        View target = selected == null ? rows.getChildAt(0) : selected;
                        rows.post(target::requestFocus);
                    }
                });
            } catch (Exception error) {
                runOnUiThread(() -> {
                    if (isDestroyed() || !popup.isShowing()) return;
                    status.setText(error.getMessage());
                    status.setTextColor(SettingsPresentation.errorTextColor());
                    TextView retry = settingsAction("Réessayer", false, v -> showHomeAccountAvatars(page, store, account, group, title));
                    rows.addView(retry, new LinearLayout.LayoutParams(-1, dp(48)));
                    wireCyclicVerticalFocus(retry, close);
                    retry.requestFocus();
                });
            }
        });
    }

