    private void changeHomeAccount(IptvStore store, Runnable change, PopupWindow popup, View action,
            TextView errorText, Runnable onChanged) {
        changeHomeAccount(store, change, popup, action, errorText, onChanged, false);
    }

    private void selectHomeAccount(IptvStore store, String id, PopupWindow popup, Runnable onChanged) {
        // Keep the focused row enabled until the selected profile is published.
        changeHomeAccount(store, () -> store.selectAccount(id), popup, null, null, onChanged, true);
    }

    private void changeHomeAccount(IptvStore store, Runnable change, PopupWindow popup, View action,
            TextView errorText, Runnable onChanged, boolean selection) {
        if (homeAccountSelectionPending) return;
        if (selection) homeAccountSelectionPending = true;
        final int generation = ++homeAccountChangeGeneration;
        final long requestedAt = android.os.SystemClock.elapsedRealtime();
        if (action != null) action.setEnabled(false);
        java.util.concurrent.ExecutorService executor = selection ? homeAccountSelectionExecutor : homeAccountExecutor;
        executor.execute(() -> {
            try {
                change.run();
                List<IptvAccount> accounts = store.accounts();
                IptvAccount account = store.selectedAccount();
                List<IptvAvatar> avatars = store.cachedAvatars();
                runOnUiThread(() -> {
                    if (isDestroyed() || generation != homeAccountChangeGeneration) return;
                    if (selection) homeAccountSelectionPending = false;
                    updateHomeHeaderAccount(accounts, account, avatars);
                    if (popup != null) popup.dismiss();
                    // Popup key releases do not always reach the Activity.
                    finishHomeDpadNavigation();
                    if (selection) android.util.Log.d("JojoHomeProfile", "Profile activated in "
                            + (android.os.SystemClock.elapsedRealtime() - requestedAt) + "ms");
                    Runnable refresh = () -> {
                        if (isDestroyed() || generation != homeAccountChangeGeneration) return;
                        renderExternalPlaybackRows();
                        refreshActiveHomeCategoryPage();
                        onChanged.run();
                    };
                    // Draw the new account/avatar before rebuilding its content rows.
                    if (selection) getWindow().getDecorView().postOnAnimation(() ->
                            getWindow().getDecorView().post(refresh));
                    else refresh.run();
                    if (homeHeaderAccountRefreshPending && !homeHeaderAccountLoading) {
                        homeHeaderAccountRefreshPending = false;
                        refreshHomeHeaderAccount();
                    }
                });
            } catch (Exception error) {
                runOnUiThread(() -> {
                    if (isDestroyed() || generation != homeAccountChangeGeneration) return;
                    if (selection) homeAccountSelectionPending = false;
                    if (action != null) action.setEnabled(true);
                    if (errorText != null && popup != null && popup.isShowing()) errorText.setText(error.getMessage());
                    else if (popup == null || popup.isShowing()) Toast.makeText(this, error.getMessage(), Toast.LENGTH_LONG).show();
                    if (selection) refreshHomeHeaderAccount();
                });
            }
        });
    }

