    private void checkForJojoHomeUpdate(View ignored) {
        SmbConnectionConfig connection = defaultSmbConnection();
        if (connection == null || connection.server.isEmpty()) {
            showJojoHomeUpdateDialog("Vérification impossible",
                    "Configurez d’abord le NAS Freebox dans Paramètres > Connexions > Lecteurs SMB.", null);
            return;
        }
        final View originScreen = activeScreen;
        final PopupWindow checking = showJojoHomeUpdateDialog("Mise à jour de Jojo Home",
                "Version installée : " + BuildConfig.VERSION_NAME + "\n\nRecherche sur la Freebox en cours…", null);
        new Thread(() -> {
            try {
                jcifs.CIFSContext context = smbBrowserContext(connection.user, connection.password);
                String folderUrl = connection.shareRootUrl();
                try (jcifs.smb.SmbFile configuredRoot = new jcifs.smb.SmbFile(folderUrl, context)) {
                    if (configuredRoot.getShare() == null) folderUrl += "Freebox/";
                }
                String remoteVersion = null;
                String remoteUrl = null;
                java.util.regex.Pattern pattern = java.util.regex.Pattern.compile("^Jojo Home[_ -]+v?([0-9]+(?:\\.[0-9]+){1,3})\\.apk$", java.util.regex.Pattern.CASE_INSENSITIVE);
                try (jcifs.smb.SmbFile root = new jcifs.smb.SmbFile(folderUrl, context)) {
                    for (jcifs.smb.SmbFile file : root.listFiles()) {
                        try (jcifs.smb.SmbFile entry = file) {
                            if (entry.isDirectory()) continue;
                            java.util.regex.Matcher matcher = pattern.matcher(entry.getName());
                            if (!matcher.matches()) continue;
                            if (remoteVersion == null || compareJojoHomeVersions(matcher.group(1), remoteVersion) > 0) {
                                remoteVersion = matcher.group(1);
                                remoteUrl = entry.getCanonicalPath();
                            }
                        }
                    }
                }
                final String foundVersion = remoteVersion;
                final String foundUrl = remoteUrl;
                runOnUiThread(() -> {
                    if (isDestroyed() || activeScreen != originScreen || !checking.isShowing()) return;
                    checking.dismiss();
                    String installed = "Version installée : " + BuildConfig.VERSION_NAME;
                    if (foundVersion == null) {
                        showJojoHomeUpdateDialog("Aucune mise à jour disponible",
                                installed + "\n\nAucun APK de Jojo Home trouvé à la racine du partage Freebox.", null);
                    } else if (compareJojoHomeVersions(foundVersion, BuildConfig.VERSION_NAME) > 0) {
                        showJojoHomeUpdateDialog("Mise à jour disponible",
                                installed + "\nVersion sur la Freebox : " + foundVersion,
                                () -> installJojoHomeUpdate(connection, foundUrl));
                    } else {
                        String status = compareJojoHomeVersions(foundVersion, BuildConfig.VERSION_NAME) == 0
                                ? "Vous utilisez déjà cette version."
                                : "La version présente sur la Freebox est plus ancienne.";
                        showJojoHomeUpdateDialog("Aucune mise à jour disponible",
                                installed + "\nVersion sur la Freebox : " + foundVersion
                                        + "\n\n" + status, null);
                    }
                });
            } catch (Exception error) {
                runOnUiThread(() -> {
                    if (isDestroyed() || activeScreen != originScreen || !checking.isShowing()) return;
                    checking.dismiss();
                    showJojoHomeUpdateDialog("Vérification impossible", error.getMessage(), null);
                });
            }
        }, "JojoHomeUpdateCheck").start();
    }

    private PopupWindow showJojoHomeUpdateDialog(String title, String message, Runnable install) {
        LinearLayout panel = new LinearLayout(this);
        PopupWindow popup = homeAccountSettingsPopup(panel, title, -2);
        TextView description = text(message, 16, SettingsPresentation.secondaryTextColor());
        description.setPadding(0, 0, 0, dp(16));
        panel.addView(description, new LinearLayout.LayoutParams(-1, -2));
        ArrayList<View> actions = new ArrayList<>();
        if (install != null) {
            TextView start = settingsAction("Installer", true, v -> {
                popup.dismiss();
                install.run();
            });
            panel.addView(start, new LinearLayout.LayoutParams(-1, dp(48)));
            actions.add(start);
        }
        TextView close = settingsAction(install == null ? "Fermer" : "Plus tard", false, v -> popup.dismiss());
        LinearLayout.LayoutParams closeParams = new LinearLayout.LayoutParams(-1, dp(48));
        if (install != null) closeParams.topMargin = dp(8);
        panel.addView(close, closeParams);
        actions.add(close);
        wireCyclicVerticalFocus(actions.toArray(new View[0]));
        popup.showAtLocation(getWindow().getDecorView(), Gravity.CENTER, 0, 0);
        actions.get(0).requestFocus();
        return popup;
    }

    private void installJojoHomeUpdate(SmbConnectionConfig connection, String url) {
        final View originScreen = activeScreen;
        new Thread(() -> {
            try {
                jcifs.CIFSContext context = smbContext(connection.user, connection.password);
                try (jcifs.smb.SmbFile source = new jcifs.smb.SmbFile(url, context)) {
                    installSmbApk(source);
                }
            } catch (Exception error) {
                runOnUiThread(() -> {
                    hideApkInstallProgress();
                    if (isDestroyed() || activeScreen != originScreen) return;
                    showJojoHomeUpdateDialog("Installation impossible", error.getMessage(),
                            () -> installJojoHomeUpdate(connection, url));
                });
            }
        }, "JojoHomeUpdateInstall").start();
    }

    private int compareJojoHomeVersions(String left, String right) {
        String[] leftParts = left == null ? new String[0] : left.split("\\.");
        String[] rightParts = right == null ? new String[0] : right.split("\\.");
        int count = Math.max(leftParts.length, rightParts.length);
        for (int index = 0; index < count; index++) {
            int leftValue = index < leftParts.length ? parseVersionPart(leftParts[index]) : 0;
            int rightValue = index < rightParts.length ? parseVersionPart(rightParts[index]) : 0;
            if (leftValue != rightValue) return Integer.compare(leftValue, rightValue);
        }
        return 0;
    }

    private int parseVersionPart(String value) {
        try { return Integer.parseInt(value); } catch (Exception ignored) { return 0; }
    }

