        filesView.setOnClickListener(v -> showChoices(filesView, new String[] { "Liste", "Grille" }, filesGridMode() ? 1 : 0, index -> { homePrefs().edit().putBoolean("files_grid", index == 1).apply(); setSettingValue(filesView, "Affichage des fichiers", index == 1 ? "Grille" : "Liste"); }));
