    private View createWeatherSettingsPage() {
        useHomeTextPalette();
        LinearLayout options = new LinearLayout(this); options.setOrientation(LinearLayout.VERTICAL);

        TextView source = selectedSettingsRow("Localisation météo", weatherUsesCurrentLocation() ? "Position actuelle" : "Ville choisie", null);
        source.setTag("weather_location_mode");
        source.setOnClickListener(v -> showChoices(source, new String[] { "Position actuelle", "Ville choisie" }, weatherUsesCurrentLocation() ? 0 : 1, index -> {
            if (index == 0) {
                saveWeatherLocationMode("current");
                cachedWeather = null;
                weatherRequestInFlight = false;
                pendingSettingsFocus = "weather_location_mode";
                if (checkSelfPermission(Manifest.permission.ACCESS_COARSE_LOCATION) != PackageManager.PERMISSION_GRANTED) {
                    weatherLocationPermissionRequestedFromSettings = true;
                    requestPermissions(new String[] { Manifest.permission.ACCESS_COARSE_LOCATION }, REQUEST_WEATHER_LOCATION);
                } else {
                    replaceScreen(createWeatherSettingsPage());
                }
            } else if (weatherManualCity().isEmpty()) {
                showWeatherCityPopup();
            } else {
                saveWeatherLocationMode("manual");
                cachedWeather = null;
                weatherRequestInFlight = false;
                pendingSettingsFocus = "weather_location_mode";
                replaceScreen(createWeatherSettingsPage());
            }
        }));
        options.addView(source, new LinearLayout.LayoutParams(dp(520), dp(72)));

        String selectedCity = weatherManualCity();
        TextView city = selectedCity.isEmpty()
                ? settingsRow("Ville choisie", "Choisir une ville", null)
                : selectedSettingsRow("Ville choisie", selectedCity, null);
        city.setTag("weather_manual_city");
        city.setOnClickListener(v -> showWeatherCityPopup());
        options.addView(city, new LinearLayout.LayoutParams(dp(520), dp(72)));

        TextView enabled = selectedSettingsRow("Afficher la météo", weatherWidgetEnabled() ? "Activé" : "Désactivé", null);
        enabled.setTag("weather_enabled");
        enabled.setOnClickListener(v -> showChoices(enabled, new String[] { "Activé", "Désactivé" }, weatherWidgetEnabled() ? 0 : 1, index -> {
            homePrefs().edit().putBoolean("weather_widget", index == 0).apply();
            setSettingValue(enabled, "Afficher la météo", index == 0 ? "Activé" : "Désactivé");
        }));
        options.addView(enabled, new LinearLayout.LayoutParams(dp(520), dp(72)));

        TextView refresh = settingsRow("Actualiser maintenant", weatherLocationLabel(), v -> {
            reloadWeatherForLocationChange();
            setSettingValue((TextView) v, "Actualiser maintenant", "Actualisation lancée");
        });
        refresh.setTag("weather_refresh");
        options.addView(refresh, new LinearLayout.LayoutParams(dp(520), dp(72)));

        TextView refreshPosition = settingsRow("Actualiser ma position", "Rechercher une position GPS/réseau récente", v -> {
            setSettingValue((TextView) v, "Actualiser ma position", "Recherche de position lancée");
            refreshWeatherFromCurrentPosition();
        });
        weatherPositionStatus = refreshPosition;
        refreshPosition.setTag("weather_refresh_position");
        options.addView(refreshPosition, new LinearLayout.LayoutParams(dp(520), dp(72)));
        return createSettingsOptionsPage("Météo", options, true);
    }
    private String weatherDeviceSuffix() { return isFireOsDevice() ? "firetv" : "androidtv"; }
    private String weatherLocationModeKey(String suffix) { return "weather_location_mode_" + suffix; }
    private String weatherManualCityKey(String suffix) { return "weather_manual_city_" + suffix; }
    private String weatherLocationModeForSuffix(String suffix) {
        android.content.SharedPreferences prefs = homePrefs();
        String scoped = prefs.getString(weatherLocationModeKey(suffix), "").trim();
        return scoped.isEmpty() ? prefs.getString("weather_location_mode", "current") : scoped;
    }
    private String weatherManualCityForSuffix(String suffix) {
        android.content.SharedPreferences prefs = homePrefs();
        String scoped = prefs.getString(weatherManualCityKey(suffix), "");
        return scoped.trim().isEmpty() ? prefs.getString("weather_manual_city", "").trim() : scoped.trim();
    }
    private void migrateWeatherSettingsToDeviceKeys() {
        android.content.SharedPreferences prefs = homePrefs();
        String suffix = weatherDeviceSuffix();
        String modeKey = weatherLocationModeKey(suffix);
        String cityKey = weatherManualCityKey(suffix);
        if (prefs.contains(modeKey) || prefs.contains(cityKey)) return;
        prefs.edit()
            .putString(modeKey, prefs.getString("weather_location_mode", "current"))
            .putString(cityKey, prefs.getString("weather_manual_city", ""))
            .apply();
    }
    private void saveWeatherLocationMode(String mode) {
        ++weatherGeneration;
        cancelWeatherLocationRequest();
        weatherRequestInFlight = false;
        homePrefs().edit().putString(weatherLocationModeKey(weatherDeviceSuffix()), mode).apply();
        syncHomeSettingsToNas();
    }
    private void saveWeatherManualCity(String city) {
        ++weatherGeneration;
        cancelWeatherLocationRequest();
        weatherRequestInFlight = false;
        homePrefs().edit()
            .putString(weatherManualCityKey(weatherDeviceSuffix()), city)
            .putString(weatherLocationModeKey(weatherDeviceSuffix()), "manual")
            .apply();
        syncHomeSettingsToNas();
    }
    private boolean weatherUsesCurrentLocation() { return !"manual".equals(weatherLocationModeForSuffix(weatherDeviceSuffix())); }
    private String weatherManualCity() { return weatherManualCityForSuffix(weatherDeviceSuffix()); }
    private String weatherLocationLabel() { return weatherUsesCurrentLocation() ? "Position actuelle" : (weatherManualCity().isEmpty() ? "Ville à choisir" : weatherManualCity()); }
