    private void reloadWeatherForLocationChange() {
        cachedWeather = null;
        weatherRequestInFlight = false;
        WeatherWidgetViews weather = activeWeatherWidget;
        if (weather == null || !weather.root.isAttachedToWindow() || !weatherWidgetEnabled()) return;
        weather.label.setText("Météo locale…");
        weather.currentTemperature.setText("--°");
        refreshWeather(weather.icon, weather.label, weather.currentTemperature, weather.forecastIcons, weather.forecastDays, weather.forecastTemperatures);
        scheduleWeatherAutoRefresh();
    }
    private void cancelWeatherLocationRequest() {
        if (weatherPositionListener != null) {
            try { ((LocationManager) getSystemService(LOCATION_SERVICE)).removeUpdates(weatherPositionListener); }
            catch (Exception ignored) { }
            weatherPositionListener = null;
        }
        weatherPositionHandler.removeCallbacksAndMessages(null);
    }

    private void weatherPositionUnavailable() {
        weatherRequestInFlight = false;
        if (activeWeatherWidget != null) {
            activeWeatherWidget.label.setText("Position indisponible");
            activeWeatherWidget.currentTemperature.setText("--°");
            setForecastVisibility(activeWeatherWidget.forecastDays, false);
        }
        if (weatherPositionStatus != null) setSettingValue(weatherPositionStatus, "Actualiser ma position", "Position indisponible — choisir une ville");
        Toast.makeText(this, "Position indisponible : activez la localisation ou choisissez votre ville", Toast.LENGTH_LONG).show();
    }

    private void refreshWeatherFromCurrentPosition() {
        saveWeatherLocationMode("current");
        cancelWeatherLocationRequest();
        final int generation = ++weatherGeneration;
        cachedWeather = null;
        weatherRequestInFlight = true;
        if (activeWeatherWidget != null) {
            activeWeatherWidget.label.setText("Recherche de position…");
            activeWeatherWidget.currentTemperature.setText("--°");
            setForecastVisibility(activeWeatherWidget.forecastDays, false);
        }
        if (checkSelfPermission(Manifest.permission.ACCESS_COARSE_LOCATION) != PackageManager.PERMISSION_GRANTED) {
            pendingFreshWeatherPosition = true;
            requestPermissions(new String[] { Manifest.permission.ACCESS_COARSE_LOCATION }, REQUEST_WEATHER_LOCATION);
            return;
        }
        LocationManager manager = (LocationManager) getSystemService(LOCATION_SERVICE);
        final long requestedAt = android.os.SystemClock.elapsedRealtimeNanos();
        weatherPositionListener = new LocationListener() {
            @Override public void onLocationChanged(Location point) {
                if (generation != weatherGeneration || point == null
                        || point.getElapsedRealtimeNanos() < requestedAt - 30_000_000_000L) return;
                cancelWeatherLocationRequest();
                refreshedWeatherLocation = new Location(point);
                loadWeather(point.getLatitude(), point.getLongitude(), "", null, null, null, null, null, null);
            }
        };
        boolean requested = false;
        for (String provider : new String[] { LocationManager.NETWORK_PROVIDER, LocationManager.GPS_PROVIDER }) {
            if (LocationManager.GPS_PROVIDER.equals(provider)
                    && checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION) != PackageManager.PERMISSION_GRANTED) continue;
            try {
                if (manager != null && manager.isProviderEnabled(provider)) {
                    manager.requestLocationUpdates(provider, 0L, 0f, weatherPositionListener, Looper.getMainLooper());
                    requested = true;
                }
            } catch (Exception ignored) { }
        }
        if (!requested) {
            cancelWeatherLocationRequest();
            weatherPositionUnavailable();
            return;
        }
        weatherPositionHandler.postDelayed(() -> {
            if (generation != weatherGeneration || weatherPositionListener == null) return;
            cancelWeatherLocationRequest();
            weatherPositionUnavailable();
        }, 12000L);
    }
