    private void applyInterfaceStyle(int index) {
        String[] styles = interfaceStyleChoices();
        if (index <= 0 || index >= styles.length) { homePrefs().edit().putString("interface_style", "Personnalisé").apply(); return; }
        int[][] palettes = new int[][] {
                { 0, 0, 5, 0 }, { 1, 1, 9, 1 }, { 8, 5, 5, 5 },
                { 3, 3, 4, 3 }, { 4, 4, 4, 4 }, { 1, 0, 18, 1 }
        };
        int[] palette = palettes[index - 1];
        homePrefs().edit().putInt("button_theme", palette[0]).putInt("folder_theme", palette[1]).putInt("folder_icon_theme", palette[2]).putInt("network_folder_theme", palette[3]).putString("interface_style", styles[index]).apply();
    }
