    private List<ResumeArtworkCandidate> filterArtworkCandidatesByOrientation(
            List<ResumeArtworkCandidate> candidates, boolean wantLandscape) {
        if (candidates == null || candidates.isEmpty()) return Collections.emptyList();
        ArrayList<ResumeArtworkCandidate> filtered = new ArrayList<>();
        for (ResumeArtworkCandidate candidate : candidates) {
            if (candidate == null) continue;
            if (candidate.landscape != null && candidate.landscape == wantLandscape) filtered.add(candidate);
        }
        return filtered;
    }

    private boolean artworkTargetIsPortrait(View anchor, String category) {
        ImageView target = anchor instanceof ImageView
                ? (ImageView) anchor : resolveArtworkView(anchor);
        if (target != null && target.getWidth() > 0 && target.getHeight() > 0) {
            return target.getHeight() > target.getWidth();
        }
        return category != null && !category.isEmpty()
                && homeCategoryThumbnailPortrait(category);
    }

    private List<ResumeArtworkCandidate> filterHeroLandscapeArtworkCandidates(
            List<ResumeArtworkCandidate> candidates) {
        if (candidates == null || candidates.isEmpty()) return Collections.emptyList();
        ArrayList<ResumeArtworkCandidate> filtered = new ArrayList<>();
        for (ResumeArtworkCandidate candidate : candidates) {
            if (candidate == null || !Boolean.TRUE.equals(candidate.landscape)) continue;
            filtered.add(candidate);
        }
        return filtered;
    }

    private void addArtworkOrientationTabs(LinearLayout panel, LinearLayout choices,
                                           HorizontalScrollView rail, boolean initialPortrait) {
        boolean[] portrait = { initialPortrait };
        LinearLayout tabs = new LinearLayout(this);
        tabs.setGravity(Gravity.CENTER_VERTICAL);
        TextView landscapeTab = text("Paysage", 15, folderThemeColor());
        TextView portraitTab = text("Portrait", 15, folderThemeColor());
        TextView empty = text("", 14, muted);
        for (TextView tab : new TextView[] { landscapeTab, portraitTab }) {
            tab.setGravity(Gravity.CENTER);
            tab.setFocusable(true);
            tab.setOnFocusChangeListener((view, focused) -> {
                boolean active = portrait[0] == (view == portraitTab);
                tab.setBackground(folderPaletteControlBg(active || focused, 10));
                tab.setTextColor(active || focused ? contrastingFolderThemeTextColor() : folderThemeColor());
            });
            tabs.addView(tab, new LinearLayout.LayoutParams(dp(130), dp(42)) {{ rightMargin = dp(8); }});
        }
        Runnable showOrientation = () -> {
            View first = null;
            for (int index = 0; index < choices.getChildCount(); index++) {
                View choice = choices.getChildAt(index);
                Object orientation = choice.getTag();
                boolean visible = !(orientation instanceof Boolean) || (Boolean) orientation == portrait[0];
                choice.setVisibility(visible ? View.VISIBLE : View.GONE);
                if (visible && first == null) first = choice;
            }
            landscapeTab.setBackground(folderPaletteControlBg(!portrait[0], 10));
            landscapeTab.setTextColor(!portrait[0] ? contrastingFolderThemeTextColor() : folderThemeColor());
            portraitTab.setBackground(folderPaletteControlBg(portrait[0], 10));
            portraitTab.setTextColor(portrait[0] ? contrastingFolderThemeTextColor() : folderThemeColor());
            empty.setText("Pas de résultat en mode " + (portrait[0] ? "Portrait" : "Paysage") + ".");
            empty.setVisibility(first == null ? View.VISIBLE : View.GONE);
            rail.scrollTo(0, 0);
            if (first != null) first.requestFocus();
            else (portrait[0] ? portraitTab : landscapeTab).requestFocus();
        };
        landscapeTab.setOnClickListener(view -> { portrait[0] = false; showOrientation.run(); });
        portraitTab.setOnClickListener(view -> { portrait[0] = true; showOrientation.run(); });
        panel.addView(tabs, new LinearLayout.LayoutParams(-1, dp(48)));
        panel.addView(rail, new LinearLayout.LayoutParams(-1, dp(200)));
        panel.addView(empty, new LinearLayout.LayoutParams(-1, dp(24)));
        showOrientation.run();
    }

