    private boolean isContinueWatchingCachePreference(String key) {
        boolean manuallySelectedArtwork = true;
        if (key != null && key.startsWith("resume_artwork_")
                && key.matches("resume_artwork_[0-9a-f]{1,8}")) {
            String url = homePrefs().getString(key, "");
            manuallySelectedArtwork = !url.isEmpty() && !(url.startsWith("https://") || url.startsWith("http://"));
            try {
                JSONObject selection = new JSONObject(homePrefs().getString("resume_artwork_metadata_"
                        + key.substring("resume_artwork_".length()), "{}"));
                manuallySelectedArtwork |= selection.optLong("selectedAt", 0L) > 0L
                        || !selection.optString("artworkUrl", "").isEmpty();
            } catch (Exception ignored) { manuallySelectedArtwork = true; }
        }
        return HomeMediaRules.continueWatchingCachePreference(key, manuallySelectedArtwork);
    }

    private void clearContinueWatchingCache(TextView action) {
        if (continueWatchingCacheClearing) return;
        continueWatchingCacheClearing = true;
        CharSequence idleText = action.getText();
        action.setText("Effacer le cache de Continuer à regarder\nNettoyage en cours…");
        styleSettingsText(action, action);
        new Thread(() -> {
            boolean cleared = false;
            try {
                HomeWatchProgressBridge.clearContinueWatchingCache(getApplicationContext());
                android.content.SharedPreferences.Editor editor = homePrefs().edit();
                for (String key : homePrefs().getAll().keySet()) {
                    if (isContinueWatchingCachePreference(key)) editor.remove(key);
                }
                editor.apply();
                getSharedPreferences("home_hero_editorial_cache", MODE_PRIVATE).edit().clear().apply();
                synchronized (artworkBitmapCache) { artworkBitmapCache.evictAll(); }
                // Only generated files directly inside the app cache are eligible.
                // Selected images live in filesDir and remain untouched.
                synchronized (homeHeroPreviewWriteLock) {
                    File cacheDirectory = getCacheDir().getCanonicalFile();
                    File[] files = cacheDirectory.listFiles();
                    if (files != null) for (File file : files) {
                        if (!HomeMediaRules.continueWatchingCacheFile(file.getName())) continue;
                        File target = file.getCanonicalFile();
                        if (cacheDirectory.equals(target.getParentFile()) && target.isFile()
                                && !target.delete() && target.exists()) throw new IOException("Cache image non supprimé");
                    }
                }
                cleared = true;
            } catch (Exception error) {
                android.util.Log.w("JojoHome", "Continue Watching cache clear failed: "
                        + error.getClass().getSimpleName());
            }
            final boolean success = cleared;
            runOnUiThread(() -> {
                continueWatchingCacheClearing = false;
                if (isDestroyed()) return;
                action.setText(idleText);
                styleSettingsText(action, action);
                folderHeroMetadataCache.clear();
                resolvedTitleLogoUrls.clear();
                netflixHeroEpisodeCodeCache.clear();
                homeVisualSettingsDirty = true;
                if (activeScreen == null) goHome();
                Toast.makeText(this, success ? "Cache de Continuer à regarder effacé"
                        : "Le cache n’a pas pu être entièrement effacé", Toast.LENGTH_LONG).show();
            });
        }, "JojoHomeClearResumeCache").start();
    }
    private void addShizukuStartupSettings(LinearLayout options) {
        String title = "Démarrer Shizuku avec Jojo Home";
        TextView automatic = selectedSettingsRow(title,
                ShizukuFiles.autoStartEnabled(this) ? "Activé" : "Désactivé", null);
        automatic.setTag("shizuku_auto_start");
        TextView test = settingsRow("Configurer et tester Shizuku", ShizukuFiles.startupStatus(), null);
        test.setTag("shizuku_startup_test");
        Runnable configure = () -> {
            pendingShizukuPath = null;
            test.setEnabled(false);
            ShizukuFiles.startWithAdb(this, true, () -> {
                if (isFinishing() || isDestroyed()) return;
                test.setEnabled(true);
                if (!test.isAttachedToWindow()) return;
                setSettingValue(test, "Configurer et tester Shizuku", ShizukuFiles.startupStatus());
                if (ShizukuFiles.availability() == ShizukuFiles.Availability.PERMISSION_REQUIRED) {
                    ShizukuFiles.requestPermission();
                }
            });
            setSettingValue(test, "Configurer et tester Shizuku", ShizukuFiles.startupStatus());
        };
        automatic.setOnClickListener(v -> showChoices(automatic,
                new String[] { "Activé", "Désactivé" }, ShizukuFiles.autoStartEnabled(this) ? 0 : 1, index -> {
                    ShizukuFiles.setAutoStartEnabled(this, index == 0);
                    setSettingValue(automatic, title, index == 0 ? "Activé" : "Désactivé");
                    if (index == 0) configure.run();
                }));
        test.setOnClickListener(v -> configure.run());
        options.addView(automatic, new LinearLayout.LayoutParams(-1, dp(72)));
        options.addView(test, new LinearLayout.LayoutParams(-1, dp(72)));
        TextView explanation = text("Première connexion : accepte « Toujours autoriser » sur la TV. "
                + "Le débogage réseau sur le port 5555 doit rester actif.", 14, muted);
        options.addView(explanation, new LinearLayout.LayoutParams(-1, dp(72)));
    }

