    private String localFolderLayoutKey(File directory) { return "local:" + (directory == null ? "/" : directory.getAbsolutePath()); }
    private String smbFolderLayoutKey(String url) { return "smb:" + url.replaceAll("/+$", ""); }
    private String shizukuFolderLayoutKey(String path) { return "shizuku:" + path; }
    private List<SmbConnectionConfig> smbConnections() {
        String serialized = homePrefs().getString("smb_connections_json", "");
        List<SmbConnectionConfig> connections = SmbConnectionConfig.fromPrefsString(serialized, homePrefs().getString("smb_server", ""), homePrefs().getString("smb_user", ""), homePrefs().getString("smb_password", ""));
        return connections == null ? new ArrayList<>() : connections;
    }
    private void saveSmbConnections(List<SmbConnectionConfig> connections) {
        synchronized (smbConnectionsStateLock) {
            try {
                Map<String, SmbConnectionConfig.SyncEntry> entries = SmbConnectionConfig.recordSyncChanges(
                        smbConnectionSyncEntries(), smbConnections(), connections, System.currentTimeMillis(), jojoHomeDeviceId());
                android.content.SharedPreferences.Editor editor = homePrefs().edit()
                        .putString(NAS_SMB_CONNECTIONS_STATE, smbConnectionSyncJson(entries).toString())
                        .putBoolean(NAS_SMB_CONNECTIONS_PENDING, true);
                writeSmbConnectionPreferences(editor, connections);
                editor.apply();
            } catch (org.json.JSONException error) {
                throw new IllegalStateException("Impossible de préparer la synchronisation SMB", error);
            }
        }
    }
    private void writeSmbConnectionPreferences(android.content.SharedPreferences.Editor editor, List<SmbConnectionConfig> connections) {
        editor.putString("smb_connections_json", SmbConnectionConfig.toPrefsString(connections));
        if (connections != null && !connections.isEmpty()) {
            SmbConnectionConfig primary = connections.get(0);
            editor.putString("smb_server", primary.server);
            editor.putString("smb_user", primary.user);
            editor.putString("smb_password", primary.password);
        } else {
            editor.remove("smb_server").remove("smb_user").remove("smb_password");
        }
    }
    private SmbConnectionConfig defaultSmbConnection() {
        List<SmbConnectionConfig> connections = smbConnections();
        return connections.isEmpty() ? null : connections.get(0);
    }
    private void openSmbConnectionBrowser(SmbConnectionConfig connection) {
        if (connection == null || connection.server.isEmpty()) {
            openScreen(createSmbSetup());
            return;
        }
        openScreen(createSmbBrowser(connection.browserUrl(), connection.user, connection.password));
    }
    private void replaceSmbConnectionBrowser(SmbConnectionConfig connection) {
        if (connection == null || connection.server.isEmpty()) {
            replaceScreen(createSmbSetup());
            return;
        }
        replaceScreen(createSmbBrowser(connection.browserUrl(), connection.user, connection.password));
    }
    private String fileLayoutPreferences() { return homePrefs().getString("files_layout_by_folder", "{}"); }
    private boolean filesGridMode(String folderKey) {
        try { return new JSONObject(fileLayoutPreferences()).optBoolean(folderKey, filesGridMode()); }
        catch (Exception ignored) { return filesGridMode(); }
    }
    private void setFilesGridMode(String folderKey, boolean grid) {
        try { JSONObject values = new JSONObject(fileLayoutPreferences()); values.put(folderKey, grid); homePrefs().edit().putString("files_layout_by_folder", values.toString()).apply(); }
        catch (Exception ignored) { homePrefs().edit().putBoolean("files_grid", grid).apply(); }
    }
    private View browserLayoutToggle(String folderKey, View.OnClickListener refresh) {
        boolean grid = filesGridMode(folderKey); ImageView toggle = new ImageView(this); toggle.setImageResource(grid ? R.drawable.ic_view_list : R.drawable.ic_view_grid); toggle.setColorFilter(folderThemeColor()); toggle.setPadding(dp(11), dp(9), dp(11), dp(9)); toggle.setFocusable(true); toggle.setContentDescription(grid ? "Afficher en liste" : "Afficher en grille"); toggle.setBackground(folderPaletteControlBg(false, 10)); toggle.setOnClickListener(v -> { setFilesGridMode(folderKey, !grid); refresh.onClick(v); }); toggle.setOnFocusChangeListener((v, focused) -> { toggle.setBackground(folderPaletteControlBg(focused, 10)); toggle.setColorFilter(focused ? contrastingFolderThemeTextColor() : folderThemeColor()); }); return toggle;
    }
    private View shizukuBrowserHeader(String path) {
        String folderKey = shizukuFolderLayoutKey(path);
        LinearLayout header = new LinearLayout(this);
        header.setGravity(Gravity.CENTER_VERTICAL);
        // Shizuku paths must stay as explicit as local and SMB locations: using only
        // the folder name made every nested Android/data directory look like "data".
        TextView title = text(path, 13, muted);
        title.setSingleLine(true);
        title.setEllipsize(TextUtils.TruncateAt.START);
        title.setGravity(Gravity.CENTER_VERTICAL);
        header.addView(title, new LinearLayout.LayoutParams(0, dp(42), 1f));
        View refresh = browserRefreshButton(v -> replaceScreen(createShizukuBrowser(path)));
        refresh.setNextFocusLeftId(refresh.getId());
        header.addView(refresh, new LinearLayout.LayoutParams(dp(42), dp(42)));
        header.addView(spaceWidth(8));
        header.addView(browserLocationLink("Local / USB", false, v -> replaceScreen(createLocalBrowser(null))), new LinearLayout.LayoutParams(dp(118), dp(42)));
        header.addView(spaceWidth(8));
        header.addView(browserLocationLink("NAS", false, v -> {
            String server = homePrefs().getString("smb_server", "");
            if (server.isEmpty()) replaceScreen(createSmbSetup());
            else {
                String root = server.startsWith("smb://") ? server : "smb://" + server;
                if (!root.endsWith("/")) root += "/";
                replaceScreen(createSmbBrowser(root, homePrefs().getString("smb_user", ""), homePrefs().getString("smb_password", "")));
            }
        }), new LinearLayout.LayoutParams(dp(76), dp(42)));
        header.addView(spaceWidth(8));
        header.addView(browserLayoutToggle(folderKey, v -> replaceScreen(createShizukuBrowser(path))), new LinearLayout.LayoutParams(dp(48), dp(42)));
        return header;
    }
    private void spaceSettingsOptions(LinearLayout options) { for (int index = 0; index < options.getChildCount(); index++) { LinearLayout.LayoutParams params = (LinearLayout.LayoutParams) options.getChildAt(index).getLayoutParams(); params.bottomMargin = dp(10); options.getChildAt(index).setLayoutParams(params); } }
    private void arrangeSettingsHubOptions(LinearLayout options, int columns) {
        ArrayList<View> cells = new ArrayList<>();
        for (int i = 0; i < options.getChildCount(); i++) {
            View cell = options.getChildAt(i);
            if (cell.getId() == View.NO_ID) cell.setId(View.generateViewId());
            cells.add(cell);
        }
        options.removeAllViews();
        for (int i = 0; i < cells.size(); i += columns) {
            LinearLayout line = new LinearLayout(this);
            line.setGravity(Gravity.CENTER_VERTICAL);
            line.setClipChildren(false);
            line.setClipToPadding(false);
            for (int column = 0; column < columns; column++) {
                if (column > 0) line.addView(spaceWidth(12), new LinearLayout.LayoutParams(dp(12), 1));
                int index = i + column;
                View cell = index < cells.size() ? cells.get(index) : new View(this);
                line.addView(cell, new LinearLayout.LayoutParams(0, dp(72), 1f));
                if (index >= cells.size()) continue;
                cell.setNextFocusLeftId(column > 0 ? cells.get(index - 1).getId() : cell.getId());
                cell.setNextFocusRightId(column + 1 < columns && index + 1 < cells.size()
                        ? cells.get(index + 1).getId() : cell.getId());
                if (index >= columns) cell.setNextFocusUpId(cells.get(index - columns).getId());
                cell.setNextFocusDownId(i + columns < cells.size()
                        ? cells.get(Math.min(index + columns, cells.size() - 1)).getId() : cell.getId());
            }
            LinearLayout.LayoutParams params = new LinearLayout.LayoutParams(-1, dp(82));
            params.bottomMargin = dp(10);
            options.addView(line, params);
        }
    }
    private void arrangeSettingsOptions(LinearLayout options) {
        if (!settingsGridMode()) return;
        ArrayList<View> cells = new ArrayList<>();
        for (int index = 0; index < options.getChildCount(); index++) cells.add(options.getChildAt(index));
        options.removeAllViews();
        for (int index = 0; index < cells.size();) {
            View view = cells.get(index);
            if (!(view instanceof TextView) || !"settings_option".equals(view.getTag())) {
                options.addView(view, new LinearLayout.LayoutParams(-1, -2));
                index++;
                continue;
            }
            View left = view;
            View right = null;
            if (index + 1 < cells.size()) {
                View next = cells.get(index + 1);
                if (next instanceof TextView && "settings_option".equals(next.getTag())) {
                    right = next;
                }
            }
            LinearLayout line = new LinearLayout(this);
            line.setOrientation(LinearLayout.HORIZONTAL);
            line.setGravity(Gravity.CENTER_VERTICAL);
            line.setClipChildren(false);
            line.setClipToPadding(false);
            line.setPadding(dp(10), 0, dp(10), 0);
            line.addView(left, new LinearLayout.LayoutParams(0, dp(72), 1f));
            if (right != null) {
                line.addView(spaceWidth(14), new LinearLayout.LayoutParams(dp(14), 1));
                line.addView(right, new LinearLayout.LayoutParams(0, dp(72), 1f));
                linkSettingsGridPair(left, right);
                index += 2;
            } else {
                line.addView(spaceWidth(14), new LinearLayout.LayoutParams(dp(14), 1));
                if (SettingsGridRules.lastRowNeedsPlaceholder(1)) line.addView(new View(this), new LinearLayout.LayoutParams(0, dp(72), 1f));
                index += 1;
            }
            LinearLayout.LayoutParams lineParams = new LinearLayout.LayoutParams(-1, dp(82));
            lineParams.bottomMargin = dp(10);
            options.addView(line, lineParams);
        }
    }
    private void linkSettingsGridPair(View left, View right) { if (!SettingsGridRules.linksColumnsForDpad()) return; if (left.getId() == View.NO_ID) left.setId(View.generateViewId()); if (right.getId() == View.NO_ID) right.setId(View.generateViewId()); left.setNextFocusRightId(right.getId()); right.setNextFocusLeftId(left.getId()); }
    private void linkSettingsFirstOptionUpToBack(LinearLayout options, LinearLayout header) { if (options.getChildCount() == 0 || header.getChildCount() < 2) return; View first = options.getChildAt(0); if (first instanceof ViewGroup && ((ViewGroup) first).getChildCount() > 0) first = ((ViewGroup) first).getChildAt(0); View back = header.getChildAt(1); if (back.getId() == View.NO_ID) back.setId(View.generateViewId()); first.setNextFocusUpId(back.getId()); }
    private View createAppIconManager() { LinearLayout page = pickerPage("Icônes des applications", "Sélectionnez une application, puis une image locale ou SMB"); page.setTag(APP_ICON_MANAGER_TAG, Boolean.TRUE); LinearLayout content = (LinearLayout) page.getTag(); ScrollView scroll = new ScrollView(this); LinearLayout list = new LinearLayout(this); list.setOrientation(LinearLayout.VERTICAL); for (android.content.pm.ResolveInfo info : allLaunchableApps()) if (!info.activityInfo.packageName.equals(getPackageName())) list.addView(appIconRow(info), new LinearLayout.LayoutParams(dp(620), dp(70))); scroll.addView(list); content.addView(scroll, new LinearLayout.LayoutParams(-1, -1)); page.post(() -> focusFirst(list)); return page; }
