    private static boolean isPreinstalledSystemApp(ApplicationInfo application) {
        return application != null
                && (application.flags & ApplicationInfo.FLAG_SYSTEM) != 0
                && (application.flags & ApplicationInfo.FLAG_UPDATED_SYSTEM_APP) == 0;
    }
    private List<android.content.pm.ResolveInfo> installedAppsForManager() {
        // Services without a launcher (WebView, Alexa runtime, provisioning,
        // etc.) must not be fabricated into application tiles.
        return allLaunchableApps();
    }
    private View createAppsPickerPage(String title, String subtitle) {
        // Keep the picker heading close to the top bar, like the other home panels.
        LinearLayout page = pickerPage(title, subtitle, 10);
        LinearLayout content = (LinearLayout) page.getTag();
        ScrollView scroll = new ScrollView(this);
        scroll.setHorizontalScrollBarEnabled(false);
        scroll.setVerticalScrollBarEnabled(false);
        // Focus scaling may enlarge a tile, but scrolling content must stay inside
        // this viewport instead of drawing beneath the page header or bottom bar.
        scroll.setClipChildren(true);
        scroll.setClipToPadding(true);

        LinearLayout rows = new LinearLayout(this);
        rows.setOrientation(LinearLayout.VERTICAL);
        rows.setPadding(dp(11), dp(11), dp(11), dp(11));
        rows.setClipChildren(false);
        rows.setClipToPadding(false);
        // Keep the dedicated Apps screen aligned with the requested TV layout:
        // seven application tiles per row. The tiles already use appTile(),
        // so their long-press menu is identical to the Home Applications rail.
        int columns = 7;
        ArrayList<LinearLayout> appRows = new ArrayList<>();
        LinearLayout row = null;
        int column = 0;
        List<android.content.pm.ResolveInfo> availableApps;
        if (pendingAddFavorite) {
            availableApps = favoriteAppCandidates();
        } else {
            availableApps = new ArrayList<>();
            for (android.content.pm.ResolveInfo info : installedAppsForManager()) {
                if (info == null || info.activityInfo == null) continue;
                String packageName = info.activityInfo.packageName;
                ApplicationInfo application = info.activityInfo.applicationInfo;
                if (isPreinstalledSystemApp(application) && !packageName.equals(getPackageName())) continue;
                availableApps.add(info);
            }
        }
        for (android.content.pm.ResolveInfo info : availableApps) {
            if (row == null || column == columns) {
                row = new LinearLayout(this);
                row.setOrientation(LinearLayout.HORIZONTAL);
                row.setClipChildren(false);
                row.setClipToPadding(false);
                rows.addView(row, new LinearLayout.LayoutParams(-2, dp(iconTileHeight() + 40)));
                appRows.add(row);
                column = 0;
            }
            // Both application pickers share the favorites tile presentation,
            // with a visible label regardless of the Home label preference.
            View tile = appTile(info, true);
            if (!pendingAddFavorite) {
                tile.setOnClickListener(v -> openPackage(info.activityInfo.packageName, homeAppLabel(info)));
                tile.setOnLongClickListener(v -> { showAppMenu(info, tile); return true; });
            }
            if (tile.getId() == View.NO_ID) tile.setId(View.generateViewId());
            LinearLayout.LayoutParams params = new LinearLayout.LayoutParams(dp(iconTileWidth()), dp(iconTileHeight() + 26));
            params.setMargins(dp(7), dp(7), dp(7), dp(7));
            row.addView(tile, params);
            column++;
        }
        wireAppPickerRows(appRows);
        scroll.addView(rows, new ScrollView.LayoutParams(-2, -2));
        content.addView(scroll, new LinearLayout.LayoutParams(-1, -1));
        page.post(() -> focusFirst(rows));
        return page;
    }
    private void wireAppPickerRows(List<LinearLayout> rows) {
        for (int rowIndex = 0; rowIndex < rows.size(); rowIndex++) {
            LinearLayout row = rows.get(rowIndex);
            wireAppRowDpad(row);
            for (int column = 0; column < row.getChildCount(); column++) {
                View tile = row.getChildAt(column);
                if (tile.getId() == View.NO_ID) tile.setId(View.generateViewId());
                if (rowIndex > 0) {
                    LinearLayout above = rows.get(rowIndex - 1);
                    View target = above.getChildAt(Math.min(column, above.getChildCount() - 1));
                    if (target.getId() == View.NO_ID) target.setId(View.generateViewId());
                    tile.setNextFocusUpId(target.getId());
                }
                if (rowIndex + 1 < rows.size()) {
                    LinearLayout below = rows.get(rowIndex + 1);
                    View target = below.getChildAt(Math.min(column, below.getChildCount() - 1));
                    if (target.getId() == View.NO_ID) target.setId(View.generateViewId());
                    tile.setNextFocusDownId(target.getId());
                }
            }
        }
    }
    private View appIconRow(android.content.pm.ResolveInfo info) { String packageName = info.activityInfo.packageName; LinearLayout row = new LinearLayout(this); row.setGravity(Gravity.CENTER_VERTICAL); row.setPadding(dp(12), 0, dp(12), 0); row.setFocusable(true); row.setBackground(settingsCardBg(false)); ImageView preview = new AppIconImageView(this); android.graphics.drawable.Drawable banner = info.activityInfo.loadBanner(getPackageManager()); android.graphics.drawable.Drawable custom = appIconDrawable(packageName); preview.setImageDrawable(custom != null ? custom : (banner != null ? banner : info.loadIcon(getPackageManager()))); String onlineIconId = onlineAppIconId(packageName); if (!onlineIconId.isEmpty()) { preview.setBackground(onlineAppIconBackground()); OnlineAppIconLoader.load(preview, onlineIconId); } preview.setScaleType(ImageView.ScaleType.FIT_CENTER); row.addView(preview, new LinearLayout.LayoutParams(dp(90), dp(52))); TextView label = text(info.loadLabel(getPackageManager()).toString() + "\nChoisir une image", 16, white); label.setPadding(dp(18), 0, 0, 0); row.addView(label, new LinearLayout.LayoutParams(0, -1, 1f)); row.setOnClickListener(v -> chooseAppIcon(packageName)); row.setOnLongClickListener(v -> { showAppMenu(info, row); return true; }); row.setOnFocusChangeListener((v, focused) -> { row.setBackground(settingsCardBg(focused)); label.setTextColor(focused ? contrastingFolderThemeTextColor() : white); }); return row; }
    private void chooseAppIcon(String packageName) { pendingAppIconPackage = packageName; if (!hasMediaAccess()) { requestMediaAccess(); return; } openScreen(createMediaPicker()); }
    private String onlineAppIconId(String packageName) {
        String iconId = homePrefs().getString("app_icon_online_" + packageName, "").trim();
        return iconId.matches("[a-z0-9-]+:[a-z0-9-]+") ? iconId : "";
    }
    private String defaultIconifyQuery(String packageName) {
        String label = "";
        try { label = getPackageManager().getApplicationInfo(packageName, 0).loadLabel(getPackageManager()).toString(); }
        catch (Exception ignored) { }
        String app = (packageName + " " + label).toLowerCase(Locale.ROOT);
        if (app.contains("netflix")) return "netflix";
        if (app.contains("canal")) return "my canal";
        if (app.contains("prime") || app.contains("avod") || (app.contains("amazon") && app.contains("video"))) return "prime video";
        return label.isEmpty() ? packageName.replace('.', ' ') : label;
    }
