    private String preferredOnlineAppIconId(String packageName, String query) {
        String identity = ((packageName == null ? "" : packageName) + " "
                + (query == null ? "" : query)).toLowerCase(Locale.ROOT);
        return identity.contains("youtube") && !identity.contains("music")
                ? "logos:youtube" : "";
    }
    private List<String> onlineAppIconSearchTerms(String packageName, String query) {
        java.util.LinkedHashSet<String> terms = new java.util.LinkedHashSet<>();
        String term = query == null ? "" : query.trim();
        if (!term.isEmpty()) terms.add(term);
        String app = packageName == null ? "" : packageName;
        try { app += " " + getPackageManager().getApplicationInfo(packageName, 0).loadLabel(getPackageManager()); }
        catch (Exception ignored) { }
        app = app.toLowerCase(Locale.ROOT);
        String lowerTerm = term.toLowerCase(Locale.ROOT);
        if (app.contains("netflix") && lowerTerm.contains("netflix")) {
            terms.add("netflix logo");
            terms.add("netflix brand");
        } else if (app.contains("canal") && lowerTerm.contains("canal")) {
            terms.add("mycanal");
            terms.add("canal plus");
            terms.add("canal+");
        } else if ((app.contains("prime") || app.contains("amazon") || app.contains("avod"))
                && (lowerTerm.contains("prime") || lowerTerm.contains("video") || lowerTerm.contains("amazon"))) {
            terms.add("amazon prime video");
            terms.add("primevideo");
            terms.add("prime video logo");
        } else if (!term.isEmpty()) {
            terms.add(term + " logo");
        }
        return new ArrayList<>(terms);
    }
    private List<String> fetchOnlineAppIconSearch(String term, String iconSetPrefix) throws Exception {
        java.net.HttpURLConnection connection = null;
        try {
            String encoded = java.net.URLEncoder.encode(term, "UTF-8");
            String searchUrl = "https://api.iconify.design/search?query=" + encoded + "&limit=48";
            if (iconSetPrefix != null && !iconSetPrefix.isEmpty()) {
                searchUrl += "&prefix=" + java.net.URLEncoder.encode(iconSetPrefix, "UTF-8");
            }
            connection = (java.net.HttpURLConnection) new URL(searchUrl).openConnection();
            connection.setConnectTimeout(5000);
            connection.setReadTimeout(5000);
            connection.setRequestProperty("Accept", "application/json");
            int responseCode = connection.getResponseCode();
            if (responseCode < 200 || responseCode >= 300) throw new IOException("HTTP " + responseCode);
            StringBuilder body = new StringBuilder();
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(connection.getInputStream(), "UTF-8"))) {
                String line;
                while ((line = reader.readLine()) != null) body.append(line);
            }
            JSONArray icons = new JSONObject(body.toString()).optJSONArray("icons");
            List<String> iconIds = new ArrayList<>();
            if (icons != null) {
                for (int index = 0; index < icons.length(); index++) {
                    String iconId = icons.optString(index, "");
                    if (iconId.matches("[a-z0-9-]+:[a-z0-9-]+") && !iconIds.contains(iconId)) iconIds.add(iconId);
                }
            }
            return iconIds;
        } finally {
            if (connection != null) connection.disconnect();
        }
    }
    private void searchOnlineAppIcons(String packageName, String query, GridLayout results, ScrollView scroll, TextView status, PopupWindow popup) {
        String term = query == null ? "" : query.trim();
        if (term.isEmpty()) { status.setText("Saisis un nom d’application ou de marque."); return; }
        int generation = ++onlineAppIconSearchGeneration;
        status.setText("Recherche dans Iconify…");
        results.removeAllViews();
        onlineAppIconSearchExecutor.execute(() -> {
            java.util.LinkedHashSet<String> iconIds = new java.util.LinkedHashSet<>();
            String errorMessage = null;
            boolean completedSearch = false;
            List<String> searchTerms = onlineAppIconSearchTerms(packageName, term);
            for (String searchTerm : searchTerms) {
                try {
                    for (String iconId : fetchOnlineAppIconSearch(searchTerm, "logos")) {
                        if (iconIds.size() >= 64) break;
                        iconIds.add(iconId);
                    }
                    completedSearch = true;
                } catch (Exception ignored) { }
                if (!iconIds.isEmpty() || iconIds.size() >= 64) break;
            }
            for (String searchTerm : searchTerms) {
                try {
                    for (String iconId : fetchOnlineAppIconSearch(searchTerm, null)) {
                        if (iconIds.size() >= 64) break;
                        iconIds.add(iconId);
                    }
                    completedSearch = true;
                } catch (Exception ignored) { }
                if (iconIds.size() >= 64) break;
            }
            if (!completedSearch) errorMessage = "La banque d’icônes est inaccessible. Vérifie la connexion Internet.";
            final String error = errorMessage;
            final String preferredIconId = preferredOnlineAppIconId(packageName, term);
            final List<String> foundIconIds = new ArrayList<>(iconIds);
            if (!preferredIconId.isEmpty()) {
                foundIconIds.remove(preferredIconId);
                foundIconIds.add(0, preferredIconId);
            }
            runOnUiThread(() -> {
                if (isDestroyed() || !popup.isShowing() || generation != onlineAppIconSearchGeneration) return;
                if (error != null) { status.setText(error); return; }
                if (foundIconIds.isEmpty()) { status.setText("Aucune icône trouvée. Essaie un autre terme."); return; }
                status.setText(foundIconIds.size() + " icônes trouvées · sélectionne celle à utiliser");
                int pickerWidth = Math.min(dp(940), getResources().getDisplayMetrics().widthPixels - dp(32));
                int previewWidth = Math.max(dp(52), (pickerWidth - dp(44)) / 4 - dp(26));
                int previewHeight = Math.round(previewWidth * 9f / 16f);
                for (int index = 0; index < foundIconIds.size(); index++) {
                    String iconId = foundIconIds.get(index);
                    LinearLayout tile = new LinearLayout(this);
                    tile.setOrientation(LinearLayout.VERTICAL);
                    tile.setGravity(Gravity.CENTER);
                    tile.setPadding(dp(8), dp(8), dp(8), dp(7));
                    tile.setFocusable(true);
                    tile.setFocusableInTouchMode(true);
                    tile.setContentDescription("Utiliser l’icône " + iconId);
                    tile.setBackground(onlineIconControlBg(false));
                    ImageView image = new AppIconImageView(this);
                    image.setScaleType(ImageView.ScaleType.FIT_CENTER);
                    image.setBackground(onlineAppIconBackground());
                    image.setImageResource(R.drawable.ic_file_image);
                    tile.addView(image, new LinearLayout.LayoutParams(-1, previewHeight));
                    OnlineAppIconLoader.load(image, iconId);
                    String iconLabel = iconId.replace(':', ' ')
                            + (iconId.equals(preferredIconId) ? "\nRecommandée" : "");
                    TextView label = text(iconLabel, 12, Color.WHITE);
                    label.setGravity(Gravity.CENTER);
                    label.setMaxLines(2);
                    label.setEllipsize(TextUtils.TruncateAt.END);
                    LinearLayout.LayoutParams labelParams = new LinearLayout.LayoutParams(-1, dp(32));
                    labelParams.topMargin = dp(5);
                    tile.addView(label, labelParams);
                    tile.setOnFocusChangeListener((v, focused) -> {
                        tile.setBackground(onlineIconControlBg(focused));
                        if (focused) scroll.post(() -> scroll.smoothScrollTo(0, Math.max(0, tile.getTop() - dp(100))));
                    });
                    tile.setOnClickListener(v -> {
                        popup.dismiss();
                        saveOnlineAppIcon(packageName, iconId);
                    });
                    GridLayout.LayoutParams params = new GridLayout.LayoutParams(
                            GridLayout.spec(index / 4), GridLayout.spec(index % 4, 1f));
                    params.width = 0;
                    params.height = previewHeight + dp(52);
                    params.setMargins(dp(5), dp(5), dp(5), dp(5));
                    results.addView(tile, params);
                }
                if (results.getChildCount() > 0) results.getChildAt(0).requestFocus();
            });
        });
    }
    private void saveOnlineAppIcon(String packageName, String iconId) {
        if (!iconId.matches("[a-z0-9-]+:[a-z0-9-]+")) return;
        String path = homePrefs().getString("app_icon_" + packageName, "");
        if (!path.isEmpty()) {
            File previous = new File(path);
            if (previous.isFile()) previous.delete();
        }
        homePrefs().edit().remove("app_icon_" + packageName)
                .remove("app_icon_local_override_" + packageName)
                .putString("app_icon_online_" + packageName, iconId).apply();
        markHomeAssetsChangedAndSync();
        pendingFocusPackage = packageName;
        goHome();
    }
    private boolean isSmartTube(String packageName) { return packageName != null && packageName.toLowerCase(Locale.ROOT).contains("smarttube"); }
    private GradientDrawable smartTubeBg() { GradientDrawable background = new GradientDrawable(GradientDrawable.Orientation.LEFT_RIGHT, new int[] { Color.rgb(63, 68, 91), Color.rgb(72, 77, 101) }); return background; }    private android.graphics.drawable.Drawable appIconDrawable(String packageName) { String path = homePrefs().getString("app_icon_" + packageName, ""); if (path.isEmpty()) return null; try { android.graphics.Bitmap bitmap = BitmapFactory.decodeFile(path); return bitmap == null ? null : new BitmapDrawable(getResources(), bitmap); } catch (Exception ignored) { return null; } }
    private void restoreOfficialAppIcon(String packageName) { String path = homePrefs().getString("app_icon_" + packageName, ""); if (!path.isEmpty()) { File icon = new File(path); if (icon.isFile()) icon.delete(); } homePrefs().edit().remove("app_icon_" + packageName).remove("app_icon_local_override_" + packageName).remove("app_icon_online_" + packageName).apply(); markHomeAssetsChangedAndSync(); pendingFocusPackage = packageName; goHome(); }
    private void saveAppIcon(Uri source) throws java.io.IOException { if (pendingAppIconPackage == null) return; String packageName = pendingAppIconPackage; File target = new File(getFilesDir(), "app_icon_" + packageName.replaceAll("[^a-zA-Z0-9._-]", "_") + ".png"); try (java.io.InputStream input = "file".equals(source.getScheme()) ? new FileInputStream(new File(source.getPath())) : getContentResolver().openInputStream(source); java.io.FileOutputStream output = new java.io.FileOutputStream(target)) { if (input == null) throw new java.io.IOException("Image indisponible"); byte[] buffer = new byte[32 * 1024]; int count; while ((count = input.read(buffer)) != -1) output.write(buffer, 0, count); } homePrefs().edit().putString("app_icon_" + packageName, target.getAbsolutePath()).putBoolean("app_icon_local_override_" + packageName, true).remove("app_icon_online_" + packageName).apply(); markHomeAssetsChangedAndSync(); }
    private String nasSyncStatus() {
        if (homePrefs().getString("nas_token", "").isEmpty()) return "Non connecté";
        long revision = homePrefs().getLong(JOJOTV_NAS_RESUME_REVISION, 0L);
        String error = homePrefs().getString("jojotv_nas_resume_last_error", "");
        return error == null || error.isEmpty()
            ? "Connecté · révision " + revision
            : "Connecté · révision " + revision + " · erreur : " + error;
    }
    private String nasBaseUrl() { return homePrefs().getString("nas_url", "http://192.168.1.32:8095").replaceAll("/+$", ""); }
    private void consumeConfirmedJojoHomeRestoreOnLaunch() {
        if (!nasDataSyncEnabled()) return;
        String token = homePrefs().getString("nas_token", "");
        String ip = localPrivateIpv4();
        if (token.isEmpty() || ip.isEmpty()) return;
        new Thread(() -> {
            try {
                JSONObject response = nasRequest("GET", nasBaseUrl() + "/api/manual-restores/pending?tv=" + java.net.URLEncoder.encode(ip, "UTF-8"), null, null);
                JSONObject restore = response.optJSONObject("restore");
                if (!nasDataSyncEnabled() || restore == null || !"jojohome".equals(restore.optString("app"))
                        || restore.optString("id").isEmpty()) return;
                restoreHomeSettingsFromNas(false);
                nasRequest("POST", nasBaseUrl() + "/api/manual-restores/" + java.net.URLEncoder.encode(restore.optString("id"), "UTF-8") + "/ack", null, new JSONObject());
            } catch (Exception ignored) { }
        }, "JojoHomeManualRestore").start();
    }
    private String localPrivateIpv4() {
        try {
            java.util.Enumeration<java.net.NetworkInterface> interfaces = java.net.NetworkInterface.getNetworkInterfaces();
            while (interfaces.hasMoreElements()) {
                java.net.NetworkInterface network = interfaces.nextElement();
                if (!network.isUp() || network.isLoopback()) continue;
                java.util.Enumeration<java.net.InetAddress> addresses = network.getInetAddresses();
                while (addresses.hasMoreElements()) {
                    java.net.InetAddress address = addresses.nextElement();
                    String value = address.getHostAddress();
                    if (address instanceof java.net.Inet4Address && (value.startsWith("192.168.") || value.startsWith("10.") || value.matches("172\\.(1[6-9]|2[0-9]|3[0-1])\\..*"))) return value;
                }
            }
        } catch (Exception ignored) { }
        return "";
    }
    private View createNasSyncPage() {
        // Android TV applique sinon un pan automatique après l'ouverture du clavier,
        // qui masque les deux premiers champs du formulaire. Cet écran gère son
        // défilement explicitement dans keepNasFieldVisible().
        getWindow().setSoftInputMode(android.view.WindowManager.LayoutParams.SOFT_INPUT_ADJUST_NOTHING);
        FrameLayout page = createSettingsShell("Compte NAS", "Accès au NAS et synchronisation optionnelle des données sur cette TV.");
        LinearLayout content = (LinearLayout) page.getTag();
        ScrollView scroll = new ScrollView(this); scroll.setFillViewport(true); scroll.setVerticalScrollBarEnabled(false);
        LinearLayout form = new LinearLayout(this); form.setOrientation(LinearLayout.VERTICAL); form.setPadding(dp(2), dp(2), dp(2), dp(12));
        scroll.addView(form); content.addView(scroll, new LinearLayout.LayoutParams(-1, 0, 1f));
        boolean connected = !homePrefs().getString("nas_token", "").isEmpty();
        TextView state = text(nasSyncStatus(), 14, SettingsPresentation.secondaryTextColor()); state.setPadding(0, 0, 0, dp(15));
        state.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);
        if (connected) {
            TextView confirmation = text("✓  Compte NAS connecté\n" + homePrefs().getString("nas_email", ""), 18, SettingsPresentation.textColor());
            confirmation.setPadding(dp(18), dp(14), dp(18), dp(14));
            confirmation.setBackground(settingsSurfaceBackground(false, true));
            form.addView(confirmation, new LinearLayout.LayoutParams(-1, dp(76)));
            form.addView(space(14));
            form.addView(state);
            boolean nasSyncEnabled = nasDataSyncEnabled();
            TextView sync = settingsRow("Synchronisation NAS automatique",
                    nasSyncEnabled ? "Activée sur cette TV" : "Désactivée sur cette TV · accès aux fichiers conservé", v ->
                    showChoices(v, new String[]{"Désactivée", "Activée"}, nasDataSyncEnabled() ? 1 : 0, index -> {
                        com.jojotv.home.progresspilot.NasDataSyncRouting.setEnabled(this, index == 1);
                        nasAutoSyncHandler.removeCallbacks(nasAutoPushRunnable);
                        nasAutoSyncHandler.removeCallbacks(nasAutoRestoreRunnable);
                        if (index == 1) {
                            restoreHomeSettingsFromNas(false, false);
                            IptvStore.requestSync(getApplicationContext(), () -> runOnUiThread(() -> refreshSyncedIptvHome()));
                        }
                        replaceScreen(createNasSyncPage());
                    }));
            styleSettingsControl(sync); form.addView(sync, new LinearLayout.LayoutParams(-1, dp(72)));
            TextView syncHelp = text("Ce choix est propre à cette TV. Les sources Supabase déjà choisies restent inchangées.",
                    14, SettingsPresentation.secondaryTextColor());
            syncHelp.setPadding(0, dp(8), 0, dp(14)); form.addView(syncHelp);
            form.addView(space(14));
            TextView backups = settingsRow("Sauvegarde et restauration", "Créer, choisir ou récupérer une sauvegarde", v -> openScreen(createMaintenancePage()));
            styleSettingsControl(backups); form.addView(backups, new LinearLayout.LayoutParams(-1, dp(72)));
            form.addView(space(20));
            TextView disconnect = settingsAction("Déconnecter ce téléviseur", false, v -> { homePrefs().edit().putString("nas_token", "").putString("nas_email", "").remove(JOJOTV_NAS_RESUME_REVISION).remove(JOJOTV_NAS_RESUME_CACHE).apply(); replaceScreen(createNasSyncPage()); });
            form.addView(disconnect, new LinearLayout.LayoutParams(-1, dp(48)));
            finishSettingsPage(page, form);
            return page;
        }
        form.addView(state);
        EditText server = settingsField(form, "Adresse du serveur NAS", "http://192.168.1.32:8095"); server.setText(nasBaseUrl()); keepNasFieldVisible(server, scroll);
        EditText email = settingsField(form, "Adresse e-mail JojoTV", "Adresse de votre compte");
        email.setInputType(android.text.InputType.TYPE_CLASS_TEXT | android.text.InputType.TYPE_TEXT_VARIATION_EMAIL_ADDRESS); keepNasFieldVisible(email, scroll);
        EditText password = settingsField(form, "Mot de passe", "Mot de passe du compte NAS");
        password.setInputType(android.text.InputType.TYPE_CLASS_TEXT | android.text.InputType.TYPE_TEXT_VARIATION_PASSWORD); keepNasFieldVisible(password, scroll);
        LinearLayout actions = new LinearLayout(this);
        TextView register = settingsAction("Créer un compte", false, v -> authenticateNas(true, server.getText().toString(), email.getText().toString(), password.getText().toString(), state));
        TextView login = settingsAction("Se connecter", true, v -> authenticateNas(false, server.getText().toString(), email.getText().toString(), password.getText().toString(), state));
        actions.addView(register, new LinearLayout.LayoutParams(0, dp(48), 1f)); actions.addView(spaceWidth(12)); actions.addView(login, new LinearLayout.LayoutParams(0, dp(48), 1f)); content.addView(actions);
        password.setNextFocusDownId(login.getId()); login.setNextFocusUpId(password.getId()); register.setNextFocusUpId(password.getId());
        register.setNextFocusRightId(login.getId()); login.setNextFocusLeftId(register.getId());
        finishSettingsPage(page, content);
        return page;
    }
