    private GradientDrawable nasFieldBackground() { GradientDrawable background = new GradientDrawable(); background.setColor(Color.rgb(37, 57, 103)); background.setCornerRadius(dp(14)); background.setStroke(dp(1), Color.rgb(85, 118, 181)); return background; }
    private GradientDrawable nasConnectedBackground() { GradientDrawable background = new GradientDrawable(); background.setColor(Color.rgb(27, 81, 65)); background.setCornerRadius(dp(14)); background.setStroke(dp(1), Color.rgb(105, 215, 166)); return background; }
    private void keepNasFieldVisible(EditText field, ScrollView scroll) {
        View.OnFocusChangeListener previous = field.getOnFocusChangeListener();
        field.setOnFocusChangeListener((view, focused) -> {
            if (previous != null) previous.onFocusChange(view, focused);
            if (!focused) return;
            // Avec le clavier TV, amener le bas du champ contre la limite du ScrollView
            // faisait disparaître les deux champs précédents. On conserve une marge haute
            // qui laisse serveur, e-mail et mot de passe lisibles simultanément.
            // Le clavier Fire TV termine son animation après le changement de focus :
            // appliquer le déplacement ensuite et sans animation évite qu'il recouvre
            // le champ Mot de passe ou le bouton de connexion.
            scroll.postDelayed(() -> {
                android.graphics.Rect bounds = new android.graphics.Rect(); field.getDrawingRect(bounds);
                ((ViewGroup) scroll.getChildAt(0)).offsetDescendantRectToMyCoords(field, bounds);
                scroll.scrollTo(0, Math.max(0, bounds.top - dp(80)));
            }, 650L);
        });
    }
