            android.content.SharedPreferences.Editor editor = homePrefs().edit().putString("icon_size", remote.optString("iconSize", "medium")).putInt("home_rows", remote.optInt("homeRows", 1)).putInt("background_color", remote.optInt("backgroundColor", 0)).putInt("background_theme_color", remote.has("backgroundThemeColor") ? remote.optInt("backgroundThemeColor", -1) : -1).putBoolean("weather_widget", remote.optBoolean("weatherEnabled", true)).putString("weather_location_mode", remote.optString("weatherLocationMode", "current")).putString("weather_manual_city", remote.optString("weatherManualCity", "")).putString("dynamic_wallpaper_mode", remote.optString("dynamicWallpaperMode", "glow")).putBoolean("dynamic_wallpaper", remote.optBoolean("dynamicWallpaper", false)).putString("app_sort_mode", remote.optString("appSortMode", "manual")).putBoolean("show_app_labels", remote.optBoolean("showAppLabels", false)).putString("app_labels_mode", remote.optString("appLabelsMode", remote.optBoolean("showAppLabels", false) ? "always" : "focus")).putBoolean("start_at_boot", remote.optBoolean("startAtBoot", false)).putInt("autostart_delay_seconds", remote.optInt("autostartDelaySeconds", 8)).putBoolean("autostart_after_standby", remote.optBoolean("autostartAfterStandby", false)).putBoolean("settings_grid", remote.optBoolean("settingsGrid", false)).putBoolean("files_grid", remote.optBoolean("filesGrid", false)).putString("files_layout_by_folder", remote.optString("filesLayouts", "{}")) .putString("continue_watching_position", remote.optString("continueWatchingPosition", "after")).putString("home_file_shortcuts_position", remote.optString("homeFileShortcutsPosition", "before")).putStringSet("hidden_apps", hasCurrentFavorites ? jsonSet(remote.optJSONArray("hiddenApps")) : hiddenApps()).putStringSet("favorite_apps", hasCurrentFavorites ? jsonSet(remote.optJSONArray("favoriteApps")) : favoriteApps()).putInt("favorite_apps_version", 3).putStringSet("content_apps", jsonSet(remote.optJSONArray("contentApps"))).putLong("nas_home_updated_at", remote.optLong("updatedAt", System.currentTimeMillis()));
             // The Applications row is device-local: two TVs can have
