    private String homeAssetKey(String type, String identity) { String compact = identity.replaceAll("[^a-zA-Z0-9]+", "-").replaceAll("(^-+|-+$)", "").toLowerCase(Locale.ROOT); if (compact.length() > 36) compact = compact.substring(0, 36); return "jojo-home-" + type + "-" + compact + "-" + Integer.toHexString(identity.hashCode()); }
    private File storedFile(String rawUri) { try { Uri uri = Uri.parse(rawUri); return "file".equals(uri.getScheme()) ? new File(uri.getPath()) : null; } catch (Exception ignored) { return null; } }
    private boolean isHomeArtworkPreferenceKey(String key) {
        return key != null && (key.startsWith("resume_artwork_") || key.startsWith("file_artwork_")
                || (key.startsWith("home_videos_") && key.contains("artwork"))
                || (key.startsWith("smb_") && key.contains("_artwork_")));
    }
    private boolean isVideoFrameArtworkFileName(String name) {
        return name != null && (name.startsWith("selected_video_") || name.startsWith("selected_hero_")
                || name.startsWith("resume_artwork_")
                || name.startsWith("selected_folder_") || name.startsWith("synced_artwork_")
                || name.startsWith("notification_resume_"));
    }
    private boolean isPersistedVideoFrameArtwork(File file) {
        return file != null && file.isFile() && getFilesDir().equals(file.getAbsoluteFile().getParentFile())
                && isVideoFrameArtworkFileName(file.getName());
    }
    private String homeArtworkAssetKey(String preferenceKey, File file) {
        if (file == null) return "";
        String name = file.getName();
        if (name.startsWith("synced_artwork_") && name.endsWith(".jpg")) {
            String key = name.substring("synced_artwork_".length(), name.length() - ".jpg".length());
            if (homeArtworkAssetFile(key) != null) return key;
        }
        return homeAssetKey("artwork", preferenceKey + "|" + name);
    }
    private String homeArtworkAssetReference(String preferenceKey, File file) {
        String assetKey = homeArtworkAssetKey(preferenceKey, file);
        return assetKey.isEmpty() ? "" : "jojo-home-asset:" + assetKey;
    }
    private File homeArtworkAssetFile(String assetKey) {
        if (assetKey == null || !assetKey.matches("jojo-home-artwork-[a-z0-9-]+")) return null;
        return new File(getFilesDir(), "synced_artwork_" + assetKey + ".jpg");
    }
    private void normalizeHomeArtworkSettingsForSync(JSONObject values) throws org.json.JSONException {
        for (Map.Entry<String, ?> entry : homePrefs().getAll().entrySet()) {
            String key = entry.getKey();
            if (!isHomeArtworkPreferenceKey(key) || !(entry.getValue() instanceof String)) continue;
            JSONObject setting = values.optJSONObject(key);
            if (setting == null || !"string".equals(setting.optString("type", ""))) continue;
            setting.put("value", artworkSettingValueForSync(key, (String) entry.getValue()));
        }
    }
    private String artworkSettingValueForSync(String key, String value) {
        if (value == null || value.isEmpty() || !isHomeArtworkPreferenceKey(key)
                || value.startsWith("jojo-home-asset:")) return value == null ? "" : value;
        File file = storedFile(value);
        if (isPersistedVideoFrameArtwork(file)) return homeArtworkAssetReference(key, file);
        if (file != null && isVideoFrameArtworkFileName(file.getName()) && !file.isFile()) return "";
        return value;
    }
    private boolean isHomeArtworkValueAvailable(String key, String value) {
        if (value == null || value.isEmpty()) return false;
        if (value.startsWith("jojo-home-asset:")) {
            String assetKey = value.substring("jojo-home-asset:".length());
            File target = homeArtworkAssetFile(assetKey);
            if (target != null && target.isFile() && target.length() > 0L) return true;
            File local = storedFile(homePrefs().getString(key, ""));
            return isPersistedVideoFrameArtwork(local)
                    && value.equals(homeArtworkAssetReference(key, local));
        }
        File file = storedFile(value);
        if (value.startsWith("file:")) return file != null && file.isFile();
        return true;
    }
    private boolean isMissingLocalVideoFrameArtwork(String value) {
        if (value == null || !value.startsWith("file:")) return false;
        File file = storedFile(value);
        return file != null && isVideoFrameArtworkFileName(file.getName()) && !file.isFile();
    }
    private String localArtworkSettingValue(String key, String incoming) {
        if (incoming.startsWith("jojo-home-asset:")) {
            File target = homeArtworkAssetFile(incoming.substring("jojo-home-asset:".length()));
            if (target != null && target.isFile() && target.length() > 0L) return Uri.fromFile(target).toString();
            String current = homePrefs().getString(key, "");
            File currentFile = storedFile(current);
            if (isPersistedVideoFrameArtwork(currentFile)
                    && incoming.equals(homeArtworkAssetReference(key, currentFile))) return current;
            return incoming;
        }
        if (isMissingLocalVideoFrameArtwork(incoming)) {
            String current = homePrefs().getString(key, "");
            return isHomeArtworkValueAvailable(key, current) ? current : "";
        }
        return incoming;
    }
    private static final String EMPTY_CONTINUE_HERO_NAS_ASSET = "jojo-home-empty-hero-4k";
    private File emptyContinueWatchingHeroAssetFile() {
        return new File(getFilesDir(), "jojo_home_empty_hero_4k.png");
    }
    private String homeAssetsFingerprint() {
        StringBuilder result = new StringBuilder(); File wallpaper = storedFile(homePrefs().getString("wallpaper_uri", ""));
        File emptyHero = emptyContinueWatchingHeroAssetFile();
        result.append("|emptyHero:").append(EMPTY_CONTINUE_HERO_NAS_ASSET)
                .append(emptyHero.isFile() ? ":" + emptyHero.length() : ":missing");
        if (wallpaper != null && wallpaper.isFile()) result.append("wallpaper:").append(wallpaper.length()).append(':').append(wallpaper.lastModified());
        for (java.util.Map.Entry<String, ?> entry : homePrefs().getAll().entrySet()) if (entry.getValue() instanceof String) {
            if (entry.getKey().startsWith("app_icon_online_")) result.append('|').append(entry.getKey()).append(':').append(entry.getValue());
            else if (entry.getKey().startsWith("app_icon_")) { File icon = new File((String) entry.getValue()); if (icon.isFile()) result.append('|').append(entry.getKey()).append(':').append(icon.length()).append(':').append(icon.lastModified()); }
            else if (isHomeArtworkPreferenceKey(entry.getKey())) {
                String value = (String) entry.getValue();
                if (value.startsWith("jojo-home-asset:")) {
                    File target = homeArtworkAssetFile(value.substring("jojo-home-asset:".length()));
                    result.append("|artwork:").append(entry.getKey()).append(':').append(value)
                            .append(target != null && target.isFile() ? ":present:" + target.length() : ":missing");
                } else {
                    File selected = storedFile(value);
                    if (isVideoFrameArtworkFileName(selected == null ? "" : selected.getName())) {
                        result.append("|artwork:").append(entry.getKey()).append(':');
                        if (selected.isFile()) result.append(homeArtworkAssetReference(entry.getKey(), selected))
                                .append(':').append(selected.length()).append(':').append(selected.lastModified());
                        else result.append("missing:").append(selected.getName());
                    }
                }
            }
        }
        return result.toString();
    }
    private void pushHomeAssetsToNas() throws Exception {
        String fingerprint = homeAssetsFingerprint(); if (fingerprint.equals(homePrefs().getString("nas_assets_snapshot", ""))) return;
        // Keep NAS assets that are not present locally (for example after an
        // reinstall). Replacing the manifest with an empty local icon object
        // was the reason custom application banners disappeared on this TV.
        JSONObject manifest = new JSONObject();
        try {
            JSONObject remote = nasRequest("GET", nasBaseUrl() + "/api/sync/profiles/1/blobs/jojo-home-assets", homePrefs().getString("nas_token", ""), null).optJSONObject("value");
            if (remote != null) manifest = new JSONObject(remote.toString());
        } catch (Exception ignored) { }
        JSONObject wallpaper = manifest.optJSONObject("wallpaper"); if (wallpaper == null) wallpaper = new JSONObject(); File wallpaperFile = storedFile(homePrefs().getString("wallpaper_uri", ""));
        if (wallpaperFile != null && wallpaperFile.isFile()) { String key = homeAssetKey("wallpaper", wallpaperFile.getName()); nasUploadAsset(key, wallpaperFile, homePrefs().getBoolean("wallpaper_video", false) ? "video/*" : "image/*"); wallpaper.put("key", key).put("video", homePrefs().getBoolean("wallpaper_video", false)); manifest.put("wallpaper", wallpaper); }
        JSONObject icons = manifest.optJSONObject("icons"); if (icons == null) icons = new JSONObject();
        for (java.util.Map.Entry<String, ?> entry : homePrefs().getAll().entrySet()) if (entry.getKey().startsWith("app_icon_online_") && entry.getValue() instanceof String) icons.remove(entry.getKey().substring("app_icon_online_".length()));
        for (java.util.Map.Entry<String, ?> entry : homePrefs().getAll().entrySet()) if (entry.getKey().startsWith("app_icon_") && !entry.getKey().startsWith("app_icon_online_") && entry.getValue() instanceof String) { String packageName = entry.getKey().substring("app_icon_".length()); if (!onlineAppIconId(packageName).isEmpty()) { icons.remove(packageName); continue; } File icon = new File((String) entry.getValue()); if (icon.isFile()) { String key = homeAssetKey("icon", packageName); nasUploadAsset(key, icon, "image/png"); icons.put(packageName, key); } }
        Set<String> uploadedArtwork = new HashSet<>();
        for (java.util.Map.Entry<String, ?> entry : homePrefs().getAll().entrySet()) {
            if (!isHomeArtworkPreferenceKey(entry.getKey()) || !(entry.getValue() instanceof String)) continue;
            File artwork = storedFile((String) entry.getValue());
            if (!isPersistedVideoFrameArtwork(artwork)) continue;
            String assetKey = homeArtworkAssetKey(entry.getKey(), artwork);
            if (uploadedArtwork.add(assetKey)) nasUploadAsset(assetKey, artwork,
                    artwork.getName().endsWith(".png") ? "image/png" : "image/jpeg");
        }
        manifest.put("icons", icons).put("updatedAt", System.currentTimeMillis()); nasRequest("PUT", nasBaseUrl() + "/api/sync/profiles/1/blobs/jojo-home-assets", homePrefs().getString("nas_token", ""), new JSONObject().put("value", manifest)); homePrefs().edit().putString("nas_assets_snapshot", fingerprint).apply();
    }
    private void restoreHomeAssetsFromNas() {
        try { JSONObject response = nasRequest("GET", nasBaseUrl() + "/api/sync/profiles/1/blobs/jojo-home-assets", homePrefs().getString("nas_token", ""), null); JSONObject manifest = response.optJSONObject("value"); if (manifest == null) { homePrefs().edit().putString("nas_assets_snapshot", "").apply(); pushHomeAssetsToNas(); return; }
            boolean emptyHeroDownloaded = false;
            File emptyHero = emptyContinueWatchingHeroAssetFile();
            boolean emptyHeroExpected = EMPTY_CONTINUE_HERO_NAS_ASSET.equals(manifest.optString("emptyContinueHero", ""));
            boolean emptyHeroRestorePending = emptyHeroExpected && (!emptyHero.isFile() || emptyHero.length() == 0L);
            if (emptyHeroRestorePending) {
                try {
                    nasDownloadAsset(EMPTY_CONTINUE_HERO_NAS_ASSET, emptyHero);
                    emptyHeroDownloaded = emptyHero.isFile() && emptyHero.length() > 0L;
                    emptyHeroRestorePending = !emptyHeroDownloaded;
                } catch (Exception ignored) { }
            }
            boolean missingArtworkAsset = false;
            for (java.util.Map.Entry<String, ?> entry : homePrefs().getAll().entrySet()) {
                if (!isHomeArtworkPreferenceKey(entry.getKey()) || !(entry.getValue() instanceof String)) continue;
                String reference = (String) entry.getValue();
                if (!reference.startsWith("jojo-home-asset:")) continue;
                File target = homeArtworkAssetFile(reference.substring("jojo-home-asset:".length()));
                if (target == null || !target.isFile() || target.length() == 0L) {
                    missingArtworkAsset = true;
                    break;
                }
            }
            long remoteUpdatedAt = manifest.optLong("updatedAt", 0L);
            String localFingerprint = homeAssetsFingerprint();
            if (!emptyHeroRestorePending && !missingArtworkAsset && remoteUpdatedAt > 0L
                    && remoteUpdatedAt == homePrefs().getLong("nas_assets_remote_updated_at", 0L)
                    && localFingerprint.equals(homePrefs().getString("nas_assets_snapshot", ""))) return;
            JSONObject wallpaper = manifest.optJSONObject("wallpaper"); if (wallpaper != null && !wallpaper.optString("key").isEmpty()) { boolean video = wallpaper.optBoolean("video", false); File target = new File(getFilesDir(), video ? "personal_wallpaper_video" : "personal_wallpaper_image"); nasDownloadAsset(wallpaper.getString("key"), target); homePrefs().edit().putString("wallpaper_uri", Uri.fromFile(target).toString()).putBoolean("wallpaper_video", video).apply(); }
            JSONObject icons = manifest.optJSONObject("icons"); if (icons != null) { java.util.Iterator<String> names = icons.keys(); android.content.SharedPreferences.Editor editor = homePrefs().edit(); while (names.hasNext()) { String packageName = names.next(); String key = icons.optString(packageName); if (key.isEmpty()) continue; File target = new File(getFilesDir(), "app_icon_" + packageName.replaceAll("[^a-zA-Z0-9._-]", "_") + ".png"); boolean localOverride = homePrefs().getBoolean("app_icon_local_override_" + packageName, false); // A marker alone is not enough: the local copy may have been cleared by an uninstall, migration, or reset. In that case the NAS copy is authoritative and must be restored.
                    if (localOverride && target.isFile() && target.length() > 0L) { editor.putString("app_icon_" + packageName, target.getAbsolutePath()); continue; } nasDownloadAsset(key, target); editor.putString("app_icon_" + packageName, target.getAbsolutePath()).putBoolean("app_icon_local_override_" + packageName, true); } editor.apply(); }
            android.content.SharedPreferences.Editor artworkEditor = homePrefs().edit();
            boolean artworkPreferencesChanged = false;
            boolean artworkRestorePending = false;
            for (java.util.Map.Entry<String, ?> entry : homePrefs().getAll().entrySet()) {
                if (!isHomeArtworkPreferenceKey(entry.getKey()) || !(entry.getValue() instanceof String)) continue;
                String reference = (String) entry.getValue();
                if (!reference.startsWith("jojo-home-asset:")) continue;
                String assetKey = reference.substring("jojo-home-asset:".length());
                File target = homeArtworkAssetFile(assetKey);
                if (target == null) { artworkRestorePending = true; continue; }
                try {
                    if (!target.isFile() || target.length() == 0L) nasDownloadAsset(assetKey, target);
                } catch (Exception ignored) { artworkRestorePending = true; continue; }
                if (target.isFile() && target.length() > 0L) {
                    String localUri = Uri.fromFile(target).toString();
                    if (!localUri.equals(reference)) {
                        artworkEditor.putString(entry.getKey(), localUri);
                        artworkPreferencesChanged = true;
                    }
                } else artworkRestorePending = true;
            }
            if (artworkPreferencesChanged || emptyHeroDownloaded) {
                applyingNasSettings = true;
                try { artworkEditor.commit(); }
                finally { applyingNasSettings = false; }
                runOnUiThread(() -> { if (activeScreen == null) goHome(); });
            }
            if (!emptyHeroRestorePending && !artworkRestorePending) {
                homePrefs().edit().putString("nas_assets_snapshot", homeAssetsFingerprint())
                        .putLong("nas_assets_remote_updated_at", remoteUpdatedAt).apply();
            }
        } catch (Exception ignored) { }
    }
    private Map<String, SmbConnectionConfig.SyncEntry> smbConnectionSyncEntries() throws org.json.JSONException {
        String saved = homePrefs().getString(NAS_SMB_CONNECTIONS_STATE, "");
        return smbConnectionSyncEntries(saved.isEmpty() ? null : new JSONObject(saved));
    }
    private Map<String, SmbConnectionConfig.SyncEntry> smbConnectionSyncEntries(JSONObject snapshot) {
        Map<String, SmbConnectionConfig.SyncEntry> result = new java.util.LinkedHashMap<>();
        JSONObject entries = snapshot == null ? null : snapshot.optJSONObject("entries");
        if (entries == null) return result;
        java.util.Iterator<String> keys = entries.keys();
        while (keys.hasNext()) {
            String key = keys.next();
            JSONObject entry = entries.optJSONObject(key);
            if (entry == null) continue;
            boolean deleted = entry.optBoolean("deleted", false);
            List<SmbConnectionConfig> connections = SmbConnectionConfig.fromPrefsString(entry.optString("value", ""), "", "", "");
            SmbConnectionConfig connection = connections.size() == 1 ? connections.get(0) : null;
            if (!deleted && (connection == null || !key.equals(SmbConnectionConfig.syncKey(connection)))) continue;
            result.put(key, new SmbConnectionConfig.SyncEntry(connection, entry.optLong("changedAt", 0L), entry.optString("writer", ""), deleted));
        }
        return result;
    }
    private JSONObject smbConnectionSyncJson(Map<String, SmbConnectionConfig.SyncEntry> values) throws org.json.JSONException {
        JSONObject entries = new JSONObject();
        for (Map.Entry<String, SmbConnectionConfig.SyncEntry> item : values.entrySet()) {
            SmbConnectionConfig.SyncEntry entry = item.getValue();
            JSONObject value = new JSONObject().put("changedAt", entry.changedAt).put("writer", entry.writer).put("deleted", entry.deleted);
            if (!entry.deleted) value.put("value", SmbConnectionConfig.toPrefsString(Collections.singletonList(entry.connection)));
            entries.put(item.getKey(), value);
        }
        return new JSONObject().put("version", 1).put("entries", entries);
    }
    private boolean syncHomeSmbConnectionsWithNas() throws Exception {
        synchronized (smbConnectionsRequestLock) {
            String token = homePrefs().getString("nas_token", "");
            String address = nasBaseUrl() + "/api/sync/profiles/1/secrets/" + SMB_CONNECTIONS_SECRET;
            JSONObject snapshot = nasRequest("GET", address, token, null).optJSONObject("value");
            Map<String, SmbConnectionConfig.SyncEntry> remote = smbConnectionSyncEntries(snapshot), merged;
            synchronized (smbConnectionsStateLock) {
                merged = SmbConnectionConfig.mergeSyncEntries(
                        SmbConnectionConfig.seedSyncEntries(smbConnectionSyncEntries(), smbConnections()), remote);
            }
            // Leave a fresh TV eligible for the legacy single-reader restore.
            if (snapshot == null && merged.isEmpty()) return false;
            boolean remoteChanged = !SmbConnectionConfig.sameSyncEntries(merged, remote);
            if (remoteChanged || homePrefs().getBoolean(NAS_SMB_CONNECTIONS_PENDING, false)) {
                homePrefs().edit().putBoolean(NAS_SMB_CONNECTIONS_PENDING, true).apply();
                if (remoteChanged) nasRequest("PUT", address, token, new JSONObject().put("value", smbConnectionSyncJson(merged)));
                // Secret writes are encrypted but do not enter the change
                // journal. Publish only an opaque wake-up marker as a blob.
                nasRequest("PUT", nasBaseUrl() + "/api/sync/profiles/1/blobs/" + SMB_CONNECTIONS_SECRET,
                        token, new JSONObject().put("value", new JSONObject().put("revision", UUID.randomUUID().toString())));
            }
            boolean changed;
            int count;
            synchronized (smbConnectionsStateLock) {
                List<SmbConnectionConfig> current = smbConnections();
                Map<String, SmbConnectionConfig.SyncEntry> saved = smbConnectionSyncEntries();
                // A user may edit the list while the HTTP request is in flight.
                // Preserve that newer edit and keep it pending for the next push.
                Map<String, SmbConnectionConfig.SyncEntry> applied = SmbConnectionConfig.mergeSyncEntries(
                        SmbConnectionConfig.seedSyncEntries(saved, current), merged);
                List<SmbConnectionConfig> connections = SmbConnectionConfig.connectionsFromSync(applied, current);
                changed = !SmbConnectionConfig.toPrefsString(current).equals(SmbConnectionConfig.toPrefsString(connections));
                android.content.SharedPreferences.Editor editor = homePrefs().edit()
                        .putBoolean(NAS_SMB_CONNECTIONS_PENDING, !SmbConnectionConfig.sameSyncEntries(applied, merged));
                if (!homePrefs().contains(NAS_SMB_CONNECTIONS_STATE) || !SmbConnectionConfig.sameSyncEntries(saved, applied)) {
                    editor.putString(NAS_SMB_CONNECTIONS_STATE, smbConnectionSyncJson(applied).toString());
                }
                if (changed || (snapshot != null && !homePrefs().contains("smb_connections_json"))) {
                    writeSmbConnectionPreferences(editor, connections);
                }
                editor.apply();
                count = connections.size();
            }
            if (changed) android.util.Log.i("JojoHomeSmbSync", "SMB_LIST_APPLIED readers=" + count);
            return changed;
        }
    }
    private void pushHomeSmbSecretToNas() throws Exception {
        syncHomeSmbConnectionsWithNas();
        // Retain the old single-reader secret for TVs awaiting the update.
        String server = homePrefs().getString("smb_server", "");
        if (server.isEmpty()) return;
        JSONObject value = new JSONObject().put("server", server).put("user", homePrefs().getString("smb_user", "")).put("password", homePrefs().getString("smb_password", ""));
        nasRequest("PUT", nasBaseUrl() + "/api/sync/profiles/1/secrets/jojo-home-smb", homePrefs().getString("nas_token", ""), new JSONObject().put("value", value));
    }
    private boolean restoreHomeSmbSecretFromNas() {
        try {
            boolean changed = syncHomeSmbConnectionsWithNas();
            if (homePrefs().contains(NAS_SMB_CONNECTIONS_STATE)) return changed;
        } catch (Exception error) {
            android.util.Log.w("JojoHomeSmbSync", "SMB_LIST_RESTORE_FAILED " + error.getClass().getSimpleName());
        }
        // An explicitly saved empty list means the user removed the last reader.
        if (homePrefs().contains("smb_connections_json") || !smbConnections().isEmpty()) return false;
        try {
            JSONObject response = nasRequest("GET", nasBaseUrl() + "/api/sync/profiles/1/secrets/jojo-home-smb", homePrefs().getString("nas_token", ""), null);
            JSONObject value = response.optJSONObject("value");
            if (value == null || value.optString("server").isEmpty()) return false;
            if (homePrefs().contains("smb_connections_json") || !smbConnections().isEmpty()) return false;
            String server = value.optString("server"); String user = value.optString("user"); String password = value.optString("password");
            SmbConnectionConfig primary = new SmbConnectionConfig("NAS", server, user, password);
            boolean changed = !server.equals(homePrefs().getString("smb_server", "")) || !user.equals(homePrefs().getString("smb_user", "")) || !password.equals(homePrefs().getString("smb_password", "")) || !SmbConnectionConfig.toPrefsString(java.util.Collections.singletonList(primary)).equals(homePrefs().getString("smb_connections_json", ""));
            homePrefs().edit().putString("smb_server", server).putString("smb_user", user).putString("smb_password", password).putString("smb_connections_json", SmbConnectionConfig.toPrefsString(java.util.Collections.singletonList(primary))).apply();
            return changed;
        } catch (Exception ignored) { return false; }
    }
    private void nasUploadAsset(String key, File source, String contentType) throws Exception { java.net.HttpURLConnection connection = (java.net.HttpURLConnection) new URL(nasBaseUrl() + "/api/sync/profiles/1/assets/" + key).openConnection(); connection.setConnectTimeout(10000); connection.setReadTimeout(60000); connection.setRequestMethod("PUT"); connection.setDoOutput(true); connection.setFixedLengthStreamingMode(source.length()); connection.setRequestProperty("Authorization", "Bearer " + homePrefs().getString("nas_token", "")); connection.setRequestProperty("Content-Type", contentType); try (java.io.InputStream input = new FileInputStream(source); java.io.OutputStream output = connection.getOutputStream()) { byte[] buffer = new byte[32 * 1024]; int count; while ((count = input.read(buffer)) != -1) output.write(buffer, 0, count); } int code = connection.getResponseCode(); if (code < 200 || code >= 300) throw new java.io.IOException("NAS HTTP " + code); connection.disconnect(); }
    private void nasDownloadAsset(String key, File target) throws Exception { java.net.HttpURLConnection connection = (java.net.HttpURLConnection) new URL(nasBaseUrl() + "/api/sync/profiles/1/assets/" + key).openConnection(); connection.setConnectTimeout(10000); connection.setReadTimeout(60000); connection.setRequestProperty("Authorization", "Bearer " + homePrefs().getString("nas_token", "")); int code = connection.getResponseCode(); if (code < 200 || code >= 300) throw new java.io.IOException("NAS HTTP " + code); File temporary = new File(target.getParentFile(), target.getName() + ".tmp"); try (java.io.InputStream input = connection.getInputStream(); java.io.OutputStream output = new java.io.FileOutputStream(temporary)) { byte[] buffer = new byte[32 * 1024]; int count; while ((count = input.read(buffer)) != -1) output.write(buffer, 0, count); } if (target.exists() && !target.delete()) throw new java.io.IOException("Remplacement impossible"); if (!temporary.renameTo(target)) throw new java.io.IOException("Finalisation impossible"); connection.disconnect(); }
    private String jojoHomeDeviceId() {
        synchronized (homePrefs()) {
            String current = homePrefs().getString("nas_device_id", "");
            if (!current.isEmpty()) return current;
            current = "jojohome-" + UUID.randomUUID();
            homePrefs().edit().putString("nas_device_id", current).commit();
            return current;
        }
    }
    private JSONObject nasRequest(String method, String address, String token, JSONObject body) throws Exception {
        java.net.HttpURLConnection connection = (java.net.HttpURLConnection) new URL(address).openConnection();
        try {
            connection.setConnectTimeout(7000);
            connection.setReadTimeout(10000);
            connection.setRequestMethod(method);
            connection.setRequestProperty("Accept", "application/json");
            connection.setRequestProperty("X-JojoTV-Device-Id", jojoHomeDeviceId());
            if (token != null && !token.isEmpty()) connection.setRequestProperty("Authorization", "Bearer " + token);
            if (body != null) {
                connection.setDoOutput(true);
                connection.setChunkedStreamingMode(16 * 1024);
                connection.setRequestProperty("Content-Type", "application/json; charset=utf-8");
                try (android.util.JsonWriter writer = new android.util.JsonWriter(new java.io.BufferedWriter(
                        new java.io.OutputStreamWriter(connection.getOutputStream(), java.nio.charset.StandardCharsets.UTF_8)))) {
                    writeHomeSyncJson(writer, body);
                }
            }
            int code = connection.getResponseCode();
            java.io.InputStream input = code >= 200 && code < 300 ? connection.getInputStream() : connection.getErrorStream();
            JSONObject response;
            try (android.util.JsonReader reader = new android.util.JsonReader(
                    new java.io.InputStreamReader(input, java.nio.charset.StandardCharsets.UTF_8))) {
                response = (JSONObject) readHomeSyncJson(reader);
            }
            if (code < 200 || code >= 300) throw new IllegalStateException(response.optString("error", "NAS HTTP " + code));
            return response;
        } finally {
            connection.disconnect();
        }
    }
    private interface ChoiceCallback { void onChoice(int index); }
    private void showChoices(View anchor, String[] values, int selected, ChoiceCallback callback) {
        boolean settings = Boolean.TRUE.equals(anchor.getTag(SETTINGS_SURFACE_TAG));
        int toggled = SettingsPresentation.toggledChoice(values, selected);
        if (settings && anchor instanceof android.widget.Switch && toggled >= 0) {
            callback.onChoice(toggled);
            tintSettingsSwitch((android.widget.Switch) anchor);
            return;
        }
        LinearLayout list = new LinearLayout(this); list.setOrientation(LinearLayout.VERTICAL); list.setPadding(0, dp(4), 0, dp(4));
        GradientDrawable choiceBackground = settingsPanelBackground();
        choiceBackground.setCornerRadius(dp(SettingsPresentation.rowCornerRadiusDp()));
        ScrollView scroll = new ScrollView(this); scroll.setVerticalScrollBarEnabled(false); scroll.setBackground(settings ? choiceBackground : panelOverlayBg());
        scroll.setOutlineProvider(new ViewOutlineProvider() {
            @Override public void getOutline(View view, Outline outline) {
                outline.setRoundRect(0, 0, view.getWidth(), view.getHeight(), dp(10));
            }
        });
        scroll.setClipToOutline(true);
        scroll.setLayerType(View.LAYER_TYPE_HARDWARE, null);
        scroll.addView(list);
        ArrayList<View> choiceRows = new ArrayList<>();
        int popupHeight = Math.min(dp(360), dp(8 + values.length * 46));
        PopupWindow popup = new PopupWindow(scroll, dp(280), popupHeight, true); popup.setBackgroundDrawable(new android.graphics.drawable.ColorDrawable(Color.TRANSPARENT)); popup.setOutsideTouchable(true); popup.setElevation(dp(12)); trackPopup(popup);
        for (int index = 0; index < values.length; index++) {
            final int picked = index;
            int normalTextColor = settings ? SettingsPresentation.textColor() : index == selected ? selectionTextColor() : white;
            TextView choice = text((index == selected ? "✓  " : "    ") + values[index], 16, normalTextColor);
            choice.setGravity(Gravity.CENTER_VERTICAL); choice.setPadding(dp(16), 0, dp(14), 0); choice.setFocusable(true);
            choice.setOnFocusChangeListener((v, focused) -> { choice.setBackground(settings ? settingsSurfaceBackground(focused, picked == selected) : focused ? settingsOverlayFocusBg() : new GradientDrawable()); choice.setTextColor(focused ? contrastingFolderThemeTextColor() : normalTextColor); if (focused) scroll.post(() -> scroll.smoothScrollTo(0, Math.max(0, choice.getTop() - (scroll.getHeight() - choice.getHeight()) / 2))); });
            choice.setOnClickListener(v -> { callback.onChoice(picked); popup.dismiss(); anchor.requestFocus(); });
            list.addView(choice, new LinearLayout.LayoutParams(-1, dp(46)));
            choiceRows.add(choice);
            if (index == selected) list.post(choice::requestFocus);
        }
        wireCyclicVerticalFocus(choiceRows.toArray(new View[0]));
        showChoicePopupBesideAnchor(popup, anchor);
    }
    private void setSettingValue(TextView row, String title, String value) {
        boolean settings = Boolean.TRUE.equals(row.getTag(SETTINGS_SURFACE_TAG));
        row.setBackground(settings ? settingsSurfaceBackground(row.hasFocus(), false) : settingsCardBg(false));
        setSelectedSettingText(row, title, value);
        if (settings) styleSettingsText(row, row);
    }
    /** Binary choices use the switch state; other choices keep their explicit value. */
    private void setSelectedSettingText(TextView row, String title, String value) {
        String cleanValue = SettingsPresentation.cleanValue(value);
        if (row instanceof android.widget.Switch) {
            android.widget.Switch toggle = (android.widget.Switch) row;
            toggle.setChecked(SettingsPresentation.toggleChecked(cleanValue));
            toggle.setText(title);
            toggle.setContentDescription(title + " : " + cleanValue);
            tintSettingsSwitch(toggle);
            return;
        }
        String selection = cleanValue;
        String content = title + (selection.isEmpty() ? "" : "\n" + selection);
        android.text.SpannableString styled = new android.text.SpannableString(content);
        if (!selection.isEmpty()) {
            int start = title.length() + 1;
            styled.setSpan(new android.text.style.CharacterStyle() {
                @Override public void updateDrawState(android.text.TextPaint paint) {
                    paint.setColor(row.hasFocus() ? contrastingFolderThemeTextColor()
                            : Boolean.TRUE.equals(row.getTag(SETTINGS_SURFACE_TAG)) ? SettingsPresentation.secondaryTextColor() : selectionTextColor());
                }
            }, start, content.length(), android.text.Spannable.SPAN_EXCLUSIVE_EXCLUSIVE);
            styled.setSpan(new android.text.style.StyleSpan(Typeface.BOLD), start, content.length(), android.text.Spannable.SPAN_EXCLUSIVE_EXCLUSIVE);
        }
        row.setText(styled);
    }
    private android.content.SharedPreferences homePrefs() { return getSharedPreferences("home_settings", MODE_PRIVATE); }
    private String iconSize() { return homePrefs().getString("icon_size", "medium"); }
    private int iconSizeIndex() { return iconSize().equals("small") ? 0 : iconSize().equals("large") ? 2 : 1; }
    private String iconSizeLabel() { String value = iconSize(); return value.equals("small") ? "Petit" : value.equals("large") ? "Grand" : "Moyen"; }
    // Medium is the Android TV Home banner size; keep the large preset one step above it.
    private int iconTileWidth() {
        int baseWidth = iconSize().equals("small") ? 72
                : iconSize().equals("large") ? largeIconTileWidthDp()
                : mediumIconTileWidthDp();
        return Math.round(baseWidth * 1.10f);
    }
    private int mediumIconTileWidthDp() {
        // Use a compact medium banner width for favorites bar
        return 122;
    }
    private int largeIconTileWidthDp() {
        return Math.max(largeIconTileWidthFallback(), mediumIconTileWidthDp() + dp(40));
    }
    private int largeIconTileWidthFallback() {
        return 250;
    }
    private int appBannerHeight() { return Math.round(iconTileWidth() * 9f / 16f); }
    private int iconTileHeight() { return appBannerHeight() + 26; }
    private int appRowHeight() { return iconTileHeight() + 24; }
    // Focus/unfocused scale multipliers relative to the compact layout size
    // Global focus multipliers. Reduced another 3% on top of previous values.
    private float unfocusedScaleX() { return 0.922f * 0.90f; }
    private float unfocusedScaleY() { return 0.922f * 0.90f; }
    private float focusedScaleX() { return 1.144f * 0.90f; }
    private float focusedScaleY() { return 1.144f * 0.90f; }
    // Keep the app card compact; focus enlarges only the artwork inside it.
    private float appFocusScaleX() { return 1.18f; }
    private float appFocusScaleY() { return 1.18f; }
    private float headerAppsMenuFocusScale() { return 1.11f; }
