    private LinearLayout colorThemeSettingRow(String title, String value, int color) {
        LinearLayout row = new LinearLayout(this);
        row.setOrientation(LinearLayout.HORIZONTAL);
        row.setGravity(Gravity.CENTER_VERTICAL);
        row.setBaselineAligned(false);
        row.setPadding(dp(20), 0, dp(18), 0);
        row.setFocusable(true);
        row.setBackground(settingsCardBg(false));
        row.setTag("settings_option");
        TextView copy = text("", 17, white);
        setSelectedSettingText(copy, title, value);
        copy.setGravity(Gravity.CENTER);
        copy.setIncludeFontPadding(false);
        row.setOnFocusChangeListener((v, focused) -> {
            row.setBackground(settingsCardBg(focused));
            if (focused) copy.setText(copy.getText().toString());
            else setSelectedSettingText(copy, title, value);
            copy.setTextColor(focused ? contrastingFolderThemeTextColor() : white);
        });
        row.addView(copy, new LinearLayout.LayoutParams(0, -1, 1f));
        row.addView(folderButtonThemePreview(color));
        return row;
    }
