    /**
     * Recolors only the yellow folder pixels in the original badge artwork.
     * The navy surround, highlights, and black play triangle stay pixel-identical.
     */
    private Bitmap dynamicFolderBadgeBitmap(int tint) {
        synchronized (dynamicFolderBadgeCache) {
            Bitmap cached = dynamicFolderBadgeCache.get(tint);
            if (cached != null) return cached;
        }
        Bitmap source = BitmapFactory.decodeResource(getResources(), R.drawable.images);
        if (source == null) return null;
        Bitmap result = source.copy(Bitmap.Config.ARGB_8888, true);
        int[] pixels = new int[result.getWidth() * result.getHeight()];
        result.getPixels(pixels, 0, result.getWidth(), 0, 0, result.getWidth(), result.getHeight());
        float[] targetHsv = new float[3];
        Color.colorToHSV(tint, targetHsv);
        float[] sourceHsv = new float[3];
        for (int index = 0; index < pixels.length; index++) {
            int pixel = pixels[index];
            int red = Color.red(pixel), green = Color.green(pixel), blue = Color.blue(pixel);
            // The source folder is the only bright yellow region. This avoids
            // touching the navy background and the dark triangle.
            if (red < 80 || red < blue + 20 || green < blue + 15) continue;
            Color.colorToHSV(pixel, sourceHsv);
            float relativeValue = Math.min(1f, sourceHsv[2] / .78f);
            float[] recolored = {
                    targetHsv[0],
                    targetHsv[1],
                    Math.min(1f, targetHsv[2] * (.82f + relativeValue * .18f))
            };
            pixels[index] = Color.HSVToColor(Color.alpha(pixel), recolored);
        }
        result.setPixels(pixels, 0, result.getWidth(), 0, 0, result.getWidth(), result.getHeight());
        synchronized (dynamicFolderBadgeCache) { dynamicFolderBadgeCache.put(tint, result); }
        return result;
    }

