    private void cycleBackgroundColor() { int next = (safeBackgroundColorIndex() + 1) % homeColors().length; homePrefs().edit().putInt("background_color", next).apply(); openScreen(createAppSettingsPage()); }
    private List<JojoProgram> mergeContinueWatchingPrograms(List<JojoProgram> systemPrograms, Map<String, List<JojoProgram>> available) {
        List<JojoProgram> merged = new ArrayList<>();
        for (JojoProgram program : systemPrograms) {
            addResumeProgramIfMissing(merged, program);
        }
        for (List<JojoProgram> programs : available.values()) {
            for (JojoProgram program : programs) addResumeProgramIfMissing(merged, program);
        }
        merged.removeIf(program -> FILE_VIDEO_RESUME_SOURCE.equals(program.sourcePackage)
                || "external-playback".equals(program.sourcePackage) || legacyHomeResume(program));
        // Keep the first-frame sources and order while the provider queries complete.
        List<JojoProgram> current = HomeWatchProgressBridge.isCloud(this)
                ? cachedContinueWatchingHomePrograms() : watchProgressHomePrograms();
        for (JojoProgram saved : cachedSharedExternalResumePrograms(null)) {
            if (!isResumeDismissed(saved)) addResumeProgramIfMissing(current, saved);
        }
        for (JojoProgram observed : merged) addResumeProgramIfMissing(current, observed);
        return keepContinueWatchingInsertionOrder(mergeNetflixCloudResumes(current));
    }

    // Serialize updates from the Freebox and provider refresh workers so new
    // entries cannot receive the same arrival ordinal.
    private synchronized List<JojoProgram> keepContinueWatchingInsertionOrder(List<JojoProgram> programs) {
        if (HomeWatchProgressBridge.isCloud(this)) return programs;
        JSONObject order = new JSONObject();
        try { order = new JSONObject(homePrefs().getString(CONTINUE_WATCHING_INSERTION_ORDER, "{}")); } catch (Exception ignored) { }
        long next = homePrefs().getLong(CONTINUE_WATCHING_INSERTION_NEXT, 0L);
        // Older/legacy keys can have ordinals newer than the saved counter.
        // Catch it up before assigning an arrival number to a new Hero item.
        for (java.util.Iterator<String> keys = order.keys(); keys.hasNext();) {
            next = Math.max(next, order.optLong(keys.next(), 0L));
        }
        boolean changed = false;
        for (JojoProgram program : programs) {
            String key = continueWatchingInsertionKey(program);
            if (order.has(key)) continue;
            String legacyKey = resumeDismissKey(program);
            try {
                if (!key.equals(legacyKey) && order.has(legacyKey)) {
                    order.put(key, order.optLong(legacyKey));
                } else {
                    order.put(key, ++next);
                }
                changed = true;
            } catch (Exception ignored) { }
        }
        if (changed) {
            android.content.SharedPreferences.Editor editor = homePrefs().edit()
                    .putString(CONTINUE_WATCHING_INSERTION_ORDER, order.toString())
                    .putLong(CONTINUE_WATCHING_INSERTION_NEXT, next);
            editor.apply();
        }
        final JSONObject finalOrder = order;
        Collections.sort(programs, (left, right) -> Long.compare(
                finalOrder.optLong(continueWatchingInsertionKey(left), Long.MAX_VALUE),
                finalOrder.optLong(continueWatchingInsertionKey(right), Long.MAX_VALUE)));
        return programs;
    }

    private String continueWatchingInsertionKey(JojoProgram program) {
        if (program != null && "external-playback".equals(program.sourcePackage)) {
            JSONObject item = externalResumeItem(program);
            String providerKey = ExternalPlaybackStore.continueWatchingKey(item);
            if (!providerKey.isEmpty()) return "provider|" + providerKey;
        }
        return resumeDismissKey(program);
    }

    private void addResumeProgramIfMissing(List<JojoProgram> programs, JojoProgram program) {
        if (program == null || legacyHomeResume(program)) return;
        if ((isJojoPackage(program.sourcePackage) || FILE_VIDEO_RESUME_SOURCE.equals(program.sourcePackage)
                || "external-playback".equals(program.sourcePackage))
                && HomeMediaRules.completedEpisodeResume(!resumeEpisodeKey(program).isEmpty(), program.watched,
                program.duration > 0L ? program.position / (float) program.duration : 0f)) return;
        String key = resumeProgramKey(program);
        for (int index = 0; index < programs.size(); index++) {
            JojoProgram existing = programs.get(index);
            if (key.equals(resumeProgramKey(existing))) {
                programs.set(index, preferResumeProgress(existing, program));
                return;
            }
            if ("external-playback".equals(existing.sourcePackage)
                    && "external-playback".equals(program.sourcePackage)) {
                JSONObject previous = externalResumeItem(existing);
                JSONObject candidate = externalResumeItem(program);
                if (ExternalPlaybackStore.sameContinueWatchingItem(previous, candidate)) {
                    if (ExternalPlaybackStore.preferForContinueWatching(candidate, previous)) {
                        programs.set(index, program);
                    }
                    return;
                }
            }
            if (!sameResumeContent(existing, program)) continue;
            programs.set(index, preferResumeProgress(existing, program));
            return;
        }
        programs.add(program);
    }

    /** Provider previews carry the deep link/artwork, while a MediaSession or
     * notification may be the only source that exposes duration and position. */
    private boolean sameResumeContent(JojoProgram left, JojoProgram right) {
        if (left == null || right == null || left.sourcePackage == null || right.sourcePackage == null) return false;
        String leftNetflixProfile = netflixNativeProfile(left), rightNetflixProfile = netflixNativeProfile(right);
        if (!leftNetflixProfile.isEmpty() && !rightNetflixProfile.isEmpty()
                && !SystemContinueWatching.sameNetflixProfile(leftNetflixProfile, rightNetflixProfile)) return false;
        String leftSharedKey = sharedExternalResumeKey(left);
        String rightSharedKey = sharedExternalResumeKey(right);
        if (!leftSharedKey.isEmpty() || !rightSharedKey.isEmpty())
            return !leftSharedKey.isEmpty() && leftSharedKey.equals(rightSharedKey);
        String leftFreeboxPath = freeboxResumePath(left);
        String rightFreeboxPath = freeboxResumePath(right);
        if (!leftFreeboxPath.isEmpty() || !rightFreeboxPath.isEmpty()) {
            return !leftFreeboxPath.isEmpty() && !rightFreeboxPath.isEmpty()
                    && comparableSmbPath(leftFreeboxPath).equals(comparableSmbPath(rightFreeboxPath));
        }
        if (FILE_VIDEO_RESUME_SOURCE.equals(left.sourcePackage)
                || FILE_VIDEO_RESUME_SOURCE.equals(right.sourcePackage)) {
            return FILE_VIDEO_RESUME_SOURCE.equals(left.sourcePackage)
                    && FILE_VIDEO_RESUME_SOURCE.equals(right.sourcePackage)
                    && !SystemContinueWatching.isBlank(left.intentUri)
                    && left.intentUri.equals(right.intentUri);
        }
        boolean leftExternal = isExternalPlaybackResumeSource(left.sourcePackage);
        boolean rightExternal = isExternalPlaybackResumeSource(right.sourcePackage);
        if (leftExternal || rightExternal) {
            return leftExternal && rightExternal
                    && !SystemContinueWatching.isBlank(left.intentUri)
                    && left.intentUri.equals(right.intentUri);
        }
        String leftContentId = resumeContentIdentity(left);
        String rightContentId = resumeContentIdentity(right);
        if (!leftContentId.isEmpty() && leftContentId.equals(rightContentId)) return true;
        if (!NotificationResumeRules.acceptsPackage(Collections.singleton(left.sourcePackage), right.sourcePackage)) return false;
        String leftTitle = resumeTitleKey(left);
        String rightTitle = resumeTitleKey(right);
        if (leftTitle.isEmpty() || !leftTitle.equals(rightTitle)) return false;
        String leftEpisode = resumeEpisodeKey(left);
        String rightEpisode = resumeEpisodeKey(right);
        if (!leftEpisode.isEmpty() && !rightEpisode.isEmpty() && !leftEpisode.equals(rightEpisode)) return false;
        String leftYear = resumeYearKey(left);
        String rightYear = resumeYearKey(right);
        return leftYear.isEmpty() || rightYear.isEmpty() || leftYear.equals(rightYear);
    }

    private JojoProgram preferResumeProgress(JojoProgram existing, JojoProgram candidate) {
        if (existing == null) return candidate;
        if (candidate == null) return existing;
        String existingFreeboxPath = freeboxResumePath(existing);
        String candidateFreeboxPath = freeboxResumePath(candidate);
        boolean sameFreeboxFile = !existingFreeboxPath.isEmpty() && !candidateFreeboxPath.isEmpty()
                && comparableSmbPath(existingFreeboxPath).equals(comparableSmbPath(candidateFreeboxPath));
        JojoProgram preferred = existing;
        if (sameFreeboxFile) {
            if (resumePresentationScore(candidate) > resumePresentationScore(existing)) preferred = candidate;
        } else if (isExternalPlaybackResumeSource(candidate.sourcePackage)
                && !isExternalPlaybackResumeSource(existing.sourcePackage)) {
            preferred = candidate;
        } else if (isExternalPlaybackResumeSource(existing.sourcePackage)
                && !isExternalPlaybackResumeSource(candidate.sourcePackage)) {
            preferred = existing;
        } else if (isJojoPackage(candidate.sourcePackage) && !isJojoPackage(existing.sourcePackage)) {
            preferred = candidate;
        } else if (isJojoPackage(existing.sourcePackage) && !isJojoPackage(candidate.sourcePackage)) {
            preferred = existing;
        } else if (resumePresentationScore(candidate) > resumePresentationScore(existing)) {
            preferred = candidate;
        }
        JojoProgram other = preferred == existing ? candidate : existing;
        boolean existingHasProgress = SystemContinueWatching.hasProgress(existing.duration, existing.position);
        boolean candidateHasProgress = SystemContinueWatching.hasProgress(candidate.duration, candidate.position);
        JojoProgram timing = SystemContinueWatching.hasProgress(preferred.duration, preferred.position)
                ? preferred : other;
        if (candidateHasProgress && (!existingHasProgress || isBetterResumeTiming(candidate, existing))) timing = candidate;
        String title = SystemContinueWatching.isBlank(preferred.title) ? other.title : preferred.title;
        String artwork = SystemContinueWatching.isBlank(preferred.artwork) ? other.artwork : preferred.artwork;
        String description = SystemContinueWatching.isBlank(preferred.description) ? other.description : preferred.description;
        String season = SystemContinueWatching.isBlank(preferred.seasonNumber) ? other.seasonNumber : preferred.seasonNumber;
        String episode = SystemContinueWatching.isBlank(preferred.episodeNumber) ? other.episodeNumber : preferred.episodeNumber;
        return new JojoProgram(preferred.sourcePackage, title, description, artwork, preferred.intentUri,
                timing.duration, timing.position, season, episode, preferred.watched || other.watched);
    }

    private String resumeTitleKey(JojoProgram program) {
        if (program == null) return "";
        String title = cleanIptvTitle(program.title);
        if (title == null) return "";
        title = title.replaceAll("(?i)\\bS\\s*\\d{1,2}\\s*E\\s*\\d{1,3}\\b", " ");
        return normalizeTmdbArtworkText(title);
    }

    private String resumeContentIdentity(JojoProgram program) {
        if (program == null) return "";
        String contentId = decodedJojoIntentExtra(program.intentUri, "contentId");
        if (SystemContinueWatching.isBlank(contentId) && isExternalPlaybackResumeSource(program.sourcePackage)) {
            contentId = program.intentUri;
        }
        if (SystemContinueWatching.isBlank(contentId)) return "";
        contentId = contentId.trim();
        if (contentId.regionMatches(true, 0, ExternalPlaybackStore.CONTENT_PREFIX, 0,
                ExternalPlaybackStore.CONTENT_PREFIX.length())) {
            contentId = contentId.substring(ExternalPlaybackStore.CONTENT_PREFIX.length());
        }
        return contentId.toLowerCase(Locale.ROOT);
    }

    private String resumeYearKey(JojoProgram program) {
        if (program == null) return "";
        String year = "";
        if (isExternalPlaybackResumeSource(program.sourcePackage)) {
            JSONObject item = externalResumeItem(program);
            year = firstExternalValue(item, "year", "release_year", "releaseYear", "first_air_date", "air_date");
        }
        if (year.isEmpty()) year = program.title == null ? "" : program.title;
        java.util.regex.Matcher matcher = java.util.regex.Pattern.compile("(?<!\\d)(?:19|20)\\d{2}(?!\\d)")
                .matcher(year);
        return matcher.find() ? matcher.group() : "";
    }

    private int resumePresentationScore(JojoProgram program) {
        if (program == null) return Integer.MIN_VALUE;
        int score = SystemContinueWatching.isBlank(program.title) ? 0 : 1;
        if (!SystemContinueWatching.isBlank(program.artwork)) score += 8;
        if (!SystemContinueWatching.isBlank(program.description)) score += 8;
        if (!SystemContinueWatching.isBlank(program.intentUri)) score += 2;
        if (!resumeEpisodeKey(program).isEmpty()) score++;
        if (FILE_VIDEO_RESUME_SOURCE.equals(program.sourcePackage)) score += 4;
        if (isJojoPackage(program.sourcePackage)) score += 2;
        return score;
    }

    private String resumeEpisodeKey(JojoProgram program) {
        if (program == null) return "";
        String season = program.seasonNumber;
        String episode = program.episodeNumber;
        if ((season == null || season.trim().isEmpty() || episode == null || episode.trim().isEmpty())
                && program.title != null) {
            java.util.regex.Matcher matcher = java.util.regex.Pattern
                    .compile("(?i)(?:^|\\b)s\\s*(\\d{1,2})\\s*e\\s*(\\d{1,3})(?:\\b|$)")
                    .matcher(program.title);
            if (matcher.find()) {
                if (season == null || season.trim().isEmpty()) season = matcher.group(1);
                if (episode == null || episode.trim().isEmpty()) episode = matcher.group(2);
            }
        }
        String code = seasonEpisodeCode(season, episode);
        return code.isEmpty() ? "" : code;
    }

    private boolean isBetterResumeTiming(JojoProgram candidate, JojoProgram existing) {
        if (!SystemContinueWatching.hasProgress(candidate.duration, candidate.position)) return false;
        if (!SystemContinueWatching.hasProgress(existing.duration, existing.position)) return true;
        // This is the latest local player checkpoint, which is published on
        // exit before Android TV Watch Next or NAS snapshots have caught up.
        if (FILE_VIDEO_RESUME_SOURCE.equals(candidate.sourcePackage)) return true;
        // Canal+ and Netflix films/episodes are not one-minute programs. A
        // notification duration above that placeholder is the reliable value.
        boolean externalVideo = NotificationResumeRules.acceptsPackage(
                new HashSet<>(java.util.Arrays.asList("com.canal.fai", "com.netflix.ninja")), candidate.sourcePackage);
        if (externalVideo && existing.duration < 5L * 60L * 1000L && candidate.duration >= 5L * 60L * 1000L) return true;
        return false;
    }

    private String resumeProgramKey(JojoProgram program) {
        if (program == null) return "";
        String source = program.sourcePackage == null ? "" : program.sourcePackage;
        String title = program.title == null ? "" : program.title;
        String intent = program.intentUri == null ? "" : program.intentUri;
        return source + "|" + title + "|" + intent + "|" + program.duration + "|" + program.position;
    }
    private int lastHomePlaybackIndex(List<JojoProgram> programs) {
        if (programs == null || programs.isEmpty()) return -1;
        String lastPlaybackKey = homePrefs().getString(ExternalPlaybackStore.LAST_HOME_PLAYBACK_KEY, "");
        if (TextUtils.isEmpty(lastPlaybackKey)) return -1;
        for (int index = 0; index < programs.size(); index++) {
            JojoProgram program = programs.get(index);
            if (lastPlaybackKey.equals(resumeDismissKey(program))) return index;
            if (program != null && FILE_VIDEO_RESUME_SOURCE.equals(program.sourcePackage)
                    && !TextUtils.isEmpty(program.intentUri)
                    && lastPlaybackKey.equals(FILE_VIDEO_RESUME_SOURCE + "|"
                    + ExternalPlaybackStore.id(program.intentUri))) return index;
        }
        return -1;
    }
    private View globalContinueRow(List<JojoProgram> programs) {
        int lastPlaybackIndex = lastHomePlaybackIndex(programs);
        return globalContinueRow(programs, lastPlaybackIndex >= 0 ? lastPlaybackIndex : 0);
    }

    private void setHomeHeroFallbackTitle(TextView title, String value) {
        int availableWidth = 0;
        if (title != null && title.getParent() instanceof ViewGroup) {
            ViewGroup titleSlot = (ViewGroup) title.getParent();
            if (titleSlot.getParent() instanceof View) {
                View editorial = (View) titleSlot.getParent();
                ViewGroup.LayoutParams editorialParams = editorial.getLayoutParams();
                int editorialWidth = editorial.getWidth() > 0 ? editorial.getWidth()
                        : editorialParams == null ? 0 : editorialParams.width;
                if (editorialWidth > 0) {
                    availableWidth = editorialWidth - editorial.getPaddingLeft()
                            - editorial.getPaddingRight();
                    ViewGroup.LayoutParams slotParams = titleSlot.getLayoutParams();
                    if (slotParams instanceof ViewGroup.MarginLayoutParams) {
                        ViewGroup.MarginLayoutParams margins = (ViewGroup.MarginLayoutParams) slotParams;
                        availableWidth -= margins.leftMargin + margins.rightMargin;
                    }
                }
            }
        }
        if (availableWidth <= 0 && title != null) {
            availableWidth = title.getWidth();
            if (availableWidth <= 0 && title.getParent() instanceof ViewGroup) {
                ViewGroup titleSlot = (ViewGroup) title.getParent();
                ViewGroup.LayoutParams slotParams = titleSlot.getLayoutParams();
                if (slotParams != null && slotParams.width > 0) availableWidth = slotParams.width;
            }
        }
        if (title != null) {
            title.setText(splitHomeHeroFallbackTitle(value, Math.max(dp(1), availableWidth),
                    title.getPaint()));
        }
    }

    private String splitHomeHeroFallbackTitle(String value, int availableWidth,
                                              android.text.TextPaint paint) {
        if (TextUtils.isEmpty(value)) return "";
        String normalized = value.trim().replaceAll("\\s+", " ")
                .replaceAll("\\s+([!?])", "$1");
        if (availableWidth <= 0 || paint == null
                || paint.measureText(normalized) <= availableWidth * .80f) {
            return normalized;
        }
        int midpoint = normalized.length() / 2;
        int lineBreak = -1;
        float bestScore = Float.MAX_VALUE;
        for (int candidate = normalized.indexOf(' '); candidate >= 0;
             candidate = normalized.indexOf(' ', candidate + 1)) {
            int leftWordStart = normalized.lastIndexOf(' ', candidate - 1) + 1;
            int rightWordEnd = normalized.indexOf(' ', candidate + 1);
            if (rightWordEnd < 0) rightWordEnd = normalized.length();
            if (!homeHeroTitleTokenHasText(normalized.substring(leftWordStart, candidate))
                    || !homeHeroTitleTokenHasText(normalized.substring(candidate + 1, rightWordEnd))) {
                continue;
            }
            String firstLine = normalized.substring(0, candidate);
            String secondLine = normalized.substring(candidate + 1);
            float firstWidth = paint.measureText(firstLine);
            float secondWidth = paint.measureText(secondLine);
            float overflow = Math.max(0f, Math.max(firstWidth, secondWidth) - availableWidth);
            float score = overflow * 1000f + Math.abs(firstWidth - secondWidth)
                    + Math.abs(candidate - midpoint);
            if (score < bestScore) {
                bestScore = score;
                lineBreak = candidate;
            }
        }
        if (lineBreak < 0) return normalized;
        return normalized.substring(0, lineBreak).trim() + "\n"
                + normalized.substring(lineBreak + 1).trim();
    }

    private boolean homeHeroTitleTokenHasText(String token) {
        for (int index = 0; index < token.length(); index++) {
            if (Character.isLetterOrDigit(token.charAt(index))) return true;
        }
        return false;
    }

    private View globalContinueRow(List<JojoProgram> initialPrograms, int initialIndex) {
        currentHomeSuggestionsUpdater = null;
        currentHomeSuggestionsInteraction = null;
        final List<JojoProgram> programs = new ArrayList<>(initialPrograms);
        final int heroStyle = homeHeroChoice();
        boolean fillHomeHero = homeGridMode() && continueWatchingModernHero();
        final FrameLayout artworkHost = fillHomeHero && currentHomeShell != null
                ? (FrameLayout) currentHomeShell.findViewWithTag(HOME_HERO_BACKGROUND_TAG) : null;
        LinearLayout rows = new LinearLayout(this);
        rows.setOrientation(LinearLayout.VERTICAL);
        rows.setClipChildren(false);
        rows.setClipToPadding(false);
        HorizontalScrollView scroll = new HorizontalScrollView(this);
        scroll.setHorizontalScrollBarEnabled(false);
        scroll.setFillViewport(true);
        scroll.setClipChildren(false);
        scroll.setClipToPadding(false);
        scroll.setPadding(0, fillHomeHero ? 0 : dp(4), 0, fillHomeHero ? 0 : dp(4));
        LinearLayout row = new LinearLayout(this);
        row.setClipChildren(false);
        row.setClipToPadding(false);

        int edgeInset = safeEdgeInset();
        int heroWidth = getResources().getDisplayMetrics().widthPixels;
        FrameLayout hero = new FrameLayout(this);
        hero.setTag(CONTINUE_WATCHING_HERO_TAG, Boolean.TRUE);
        hero.setFocusable(false);
        hero.setClickable(false);
        hero.setId(View.generateViewId());
        hero.setClipChildren(true);
        hero.setClipToPadding(true);
        registerHomeRowMoveTrigger(hero, "resumes");

        for (int index = 0; index < programs.size(); index++) {
            if (resumeProgramKey(programs.get(index)).equals(pendingSyncedHeroKey)) {
                initialIndex = index;
                pendingSyncedHeroKey = null;
                break;
            }
        }
        final int[] selectedIndex = { Math.max(0, Math.min(initialIndex, programs.size())) };
        final TextView[] watchButton = { null };
        final ImageView[] displayedTitleLogo = { null };
        final ImageView[] displayedArtwork = { null };
        final ImageView[] displayedPoster = { null };
        final View.OnLayoutChangeListener[] refinedHeroLayoutListener = { null };
        final View[] suggestionsPage = { null };
        final Runnable[] bindSelected = new Runnable[1];
        final boolean[] heroInteractionPaused = { false };
        final java.util.function.Consumer<Boolean> updateHeroInteraction = userAction -> {
            if (!scroll.isAttachedToWindow()) return;
            boolean paused = hero.hasFocus();
            if (paused == heroInteractionPaused[0]) return;
            heroInteractionPaused[0] = paused;
            if (paused) {
                cancelContinueWatchingAutoScroll(scroll, true);
                hero.animate().cancel();
                hero.setAlpha(1f);
            } else if (!programs.isEmpty())
                scheduleContinueWatchingAutoScroll(scroll, HOME_HERO_AUTO_ADVANCE_MS);
        };
        currentHomeSuggestionsInteraction = updateHeroInteraction;
        final java.util.function.IntConsumer changePage = direction -> {
            cancelContinueWatchingAutoScroll(scroll, true);
            int target = HomeMediaRules.homeHeroNextPage(selectedIndex[0], programs.size(), direction);
            if (target != selectedIndex[0]) {
                selectedIndex[0] = target;
                bindSelected[0].run();
                heroInteractionPaused[0] = hero.hasFocus();
            }
            if (!programs.isEmpty() && !heroInteractionPaused[0])
                scheduleContinueWatchingAutoScroll(scroll, HOME_HERO_AUTO_ADVANCE_MS);
        };
        LinearLayout dots = new LinearLayout(this);
        dots.setGravity(Gravity.LEFT | Gravity.CENTER_VERTICAL);
        HorizontalScrollView dotsScroll = new HorizontalScrollView(this);
        dotsScroll.setHorizontalScrollBarEnabled(false);
        dotsScroll.addView(dots, new HorizontalScrollView.LayoutParams(-2, dp(18)));
        Runnable updatePagination = () -> {
            if (dots.getChildCount() != HomeMediaRules.homeHeroPageCount(programs.size())) {
                dots.removeAllViews();
                for (int index = 0; index < HomeMediaRules.homeHeroPageCount(programs.size()); index++) {
                    final int targetIndex = index;
                    View dot = new View(this);
                    dot.setFocusable(false);
                    dot.setClickable(true);
                    dot.setContentDescription(index == programs.size() ? "Suggestions pour vous"
                            : "Vidéo " + (index + 1) + " sur " + programs.size());
                    dot.setOnClickListener(v -> {
                        if (selectedIndex[0] == targetIndex) return;
                        changePage.accept(targetIndex - selectedIndex[0]);
                    });
                    LinearLayout.LayoutParams dotParams = new LinearLayout.LayoutParams(dp(12), dp(12));
                    dotParams.rightMargin = dp(9);
                    dots.addView(dot, dotParams);
                }
            }
            updateContinueWatchingHeroDots(dots, selectedIndex[0], hero.hasFocus());
        };
        Runnable wirePage = () -> {
            if (!hero.isAttachedToWindow()) return;
            if (currentHomeHeaderView != null && currentHomeAppsView != null)
                wireHomeHeaderDpad(currentHomeHeaderView, currentHomeAppsView, currentHomeFilesView, rows);
            wireResumeRowsDpad(rows);
            wireHomeSectionVerticalDpad();
            wireHomeCategoryGridDpad(currentHomeCategoryGrid, currentHomeResumesView);
        };
        bindSelected[0] = () -> {
            boolean suggestions = selectedIndex[0] == programs.size();
            if (suggestions && suggestionsPage[0] != null && suggestionsPage[0].getParent() == hero) {
                updatePagination.run();
                refreshEmptyHomeSuggestions();
                return;
            }
            JojoProgram program = suggestions ? null : programs.get(selectedIndex[0]);
            String selectedHeroKey = suggestions ? "home_suggestions_page" : resumeDismissKey(program);
            if (program != null) android.util.Log.d("HomeProgressSync", "HERO_BOUND profile=" + watchProgressSnapshotProfileId
                    + " routeHash=" + program.intentUri.hashCode() + " position=" + program.position
                    + " duration=" + program.duration + " at=" + android.os.SystemClock.elapsedRealtime());
            ImageView previousArtwork = displayedArtwork[0];
            if (previousArtwork == null && artworkHost != null && artworkHost.getChildCount() > 0)
                previousArtwork = (ImageView) artworkHost.getChildAt(0);
            Bitmap retainedArtwork = previousArtwork != null
                    && previousArtwork.getDrawable() instanceof BitmapDrawable
                    ? ((BitmapDrawable) previousArtwork.getDrawable()).getBitmap() : null;
            if (previousArtwork != null) {
                artworkLoadRequests.remove(previousArtwork);
                videoArtworkRequests.remove(previousArtwork);
            }
            if (displayedPoster[0] != null) {
                artworkLoadRequests.remove(displayedPoster[0]);
                videoArtworkRequests.remove(displayedPoster[0]);
            }
            Bitmap retainedTitleLogo = null;
            if (selectedHeroKey.equals(hero.getTag()) && displayedTitleLogo[0] != null
                    && displayedTitleLogo[0].getVisibility() == View.VISIBLE
                    && displayedTitleLogo[0].getDrawable() instanceof BitmapDrawable) {
                retainedTitleLogo = ((BitmapDrawable) displayedTitleLogo[0].getDrawable()).getBitmap();
            }
            // Rebinding replaces the focused button. Remember its state so a
            // carousel wrap does not leave the D-pad focus without a target.
            boolean restoreButtonFocus = hero.hasFocus();
            if (restoreButtonFocus) {
                // Removing the focused button makes Android TV search from
                // the whole activity for one frame. Park focus on the Hero
                // container so it cannot flash the Accueil item.
                hero.setFocusable(true);
                hero.setFocusableInTouchMode(true);
                hero.requestFocus();
            }
            if (refinedHeroLayoutListener[0] != null) {
                hero.removeOnLayoutChangeListener(refinedHeroLayoutListener[0]);
                refinedHeroLayoutListener[0] = null;
            }
            hero.removeAllViews();
            hero.setTag(selectedHeroKey);
            hero.setContentDescription(null);
            FrameLayout.LayoutParams dotsParams = new FrameLayout.LayoutParams(
                    -2, dp(heroStyle == 0 ? 18 : 16), Gravity.RIGHT | Gravity.BOTTOM);
            dotsParams.rightMargin = dp(heroStyle == 0 ? 28 : 32);
            dotsParams.bottomMargin = dp(heroStyle == 0 ? 6 : 14);
            dotsScroll.setTranslationY(heroStyle == 0 ? -dp(5) : 0);
            if (suggestions) {
                if (artworkHost != null) artworkHost.removeAllViews();
                displayedArtwork[0] = null;
                displayedPoster[0] = null;
                displayedTitleLogo[0] = null;
                watchButton[0] = null;
                if (suggestionsPage[0] == null) suggestionsPage[0] = homeSuggestionsHero(changePage,
                        () -> HomeMediaRules.homeHeroPageCount(programs.size()));
                FrameLayout.LayoutParams suggestionsParams = new FrameLayout.LayoutParams(-1, -1);
                suggestionsParams.setMargins(edgeInset, 0, edgeInset, 0);
                suggestionsParams.bottomMargin = dp(30);
                hero.addView(suggestionsPage[0], suggestionsParams);
                hero.addView(dotsScroll, dotsParams);
                updatePagination.run();
                refreshEmptyHomeSuggestions();
                hero.post(wirePage);
                if (restoreButtonFocus) hero.post(() -> {
                    if (suggestionsPage[0].getParent() != hero || !hero.isAttachedToWindow()) return;
                    View target = firstFocusableChild((ViewGroup) suggestionsPage[0]);
                    if (target != null && target.requestFocus()) {
                        hero.setFocusableInTouchMode(false);
                        hero.setFocusable(false);
                    }
                });
                return;
            }

            boolean externalLogo = isExternalLiveProgram(program);
            HeroArtworkImageView artwork = new HeroArtworkImageView(this, true,
                    heroStyle == 0 ? HERO_HORIZONTAL_FADE_END_FRACTION : .38f,
                    0f, false, false);
            artwork.landscapeOnly = "external-playback".equals(program.sourcePackage) && !externalLogo;
            // Fit the full image between opaque bars without cropping its top/bottom.
            // FIT_END keeps it on the right and reuses the image-edge fade mask.
            boolean fitBetweenHomeBars = artworkHost != null && homeBarsChoice() == 1;
            artwork.setScaleType(externalLogo ? ImageView.ScaleType.FIT_CENTER
                    : fitBetweenHomeBars ? ImageView.ScaleType.FIT_END : ImageView.ScaleType.CENTER_CROP);
            artwork.setBackgroundColor(Color.TRANSPARENT);
            if (retainedArtwork != null) artwork.setImageBitmap(retainedArtwork);
            displayedArtwork[0] = artwork;
            // Leave the editorial side transparent so it inherits the active
            // Home wallpaper; the artwork view fades into it from the centre.
            if (artworkHost != null) {
                artworkHost.removeAllViews();
                artworkHost.addView(artwork, new FrameLayout.LayoutParams(-1, -1));
            } else {
                hero.addView(artwork, new FrameLayout.LayoutParams(
                        heroArtworkWidth(), fillHomeHero ? -1 : dp(continueWatchingHeroHeightDp()),
                        Gravity.RIGHT | Gravity.CENTER_VERTICAL));
            }
            loadContinueWatchingHeroArtwork(artwork, program, true);
            LinearLayout content = new LinearLayout(this);
            content.setOrientation(LinearLayout.VERTICAL);
            content.setGravity(Gravity.TOP);
            content.setClipChildren(false);
            content.setClipToPadding(false);
            // The hero is 10dp taller. Split that increase across its top
            // and bottom insets so the editorial block remains centred while
            // its button, progress bar and dots keep their existing rhythm.
            // Reserve space below the action/progress block for the pagination dots.
            content.setPadding(dp(28), dp(23), dp(16), dp(6));
            int editorialWidth = fillHomeHero ? Math.round(heroWidth * .36f)
                    : Math.min(dp(510), Math.round(heroWidth * .48f));
            FrameLayout.LayoutParams contentParams = new FrameLayout.LayoutParams(
                    editorialWidth, -1, Gravity.LEFT);
            hero.addView(content, contentParams);

            String episodeCode = seasonEpisodeCode(program.seasonNumber, program.episodeNumber);
            boolean titleContainsEpisode = program.title != null
                    && java.util.regex.Pattern.compile("(?i)(?:^|\\b)s\\s*\\d{1,2}\\s*e\\s*\\d{1,3}(?:\\b|$)")
                    .matcher(program.title).find();
            if (episodeCode.isEmpty() && titleContainsEpisode) {
                java.util.regex.Matcher episodeMatcher = java.util.regex.Pattern
                        .compile("(?i)\\bs\\s*(\\d{1,2})\\s*e\\s*(\\d{1,3})\\b")
                        .matcher(program.title);
                if (episodeMatcher.find()) {
                    episodeCode = "S" + formatTwoDigits(episodeMatcher.group(1))
                            + "E" + formatTwoDigits(episodeMatcher.group(2));
                }
            }
            boolean netflixResume = "netflix".equals(SystemContinueWatching.sharedResumeProvider(program.sourcePackage));
            boolean seriesResume = !isExternalLiveProgram(program)
                    && (!episodeCode.isEmpty() || titleContainsEpisode || (netflixResume && "tv".equals(
                        SystemContinueWatching.netflixResumeMediaType(program.title, program.description,
                                program.seasonNumber, program.episodeNumber))));
            String titleValue = SystemContinueWatching.displayTitle(program.title, program.description);
            if (seriesResume) {
                titleValue = FILE_VIDEO_RESUME_SOURCE.equals(program.sourcePackage)
                        ? videoArtworkSearchTitle(program.title, null)
                        : cleanIptvTitle(titleValue);
            } else if (FILE_VIDEO_RESUME_SOURCE.equals(program.sourcePackage)) {
                titleValue = displayVideoTitle(titleValue);
            }
            FrameLayout titleSlot = new FrameLayout(this);
            titleSlot.setClipChildren(false);
            titleSlot.setClipToPadding(false);
            int titleSlotWidth = Math.max(dp(1), editorialWidth - dp(28) - dp(16));
            TextView title = text(titleValue, 30, Color.WHITE);
            title.setTypeface(null, Typeface.BOLD);
            title.setText(splitHomeHeroFallbackTitle(titleValue, titleSlotWidth, title.getPaint()));
            title.setSingleLine(false);
            title.setMaxLines(2);
            title.setIncludeFontPadding(false);
            title.setEllipsize(TextUtils.TruncateAt.END);
            title.setHorizontallyScrolling(false);
            title.setGravity(Gravity.TOP | Gravity.LEFT);
            titleSlot.addView(title, new FrameLayout.LayoutParams(
                    FrameLayout.LayoutParams.MATCH_PARENT, FrameLayout.LayoutParams.MATCH_PARENT));
            ImageView titleLogo = folderTitleLogoView();
            titleLogo.setVisibility(View.GONE);
            if (heroStyle == 0) prepareTitleLogoFallback(titleLogo, title);
            else titleLogo.setTag("home_refined_hero_title");
            displayedTitleLogo[0] = titleLogo;
            if (retainedTitleLogo != null) applyLoadedArtwork(titleLogo, retainedTitleLogo);
            int heroEditorialSpacing = dp(8);
            content.addView(titleSlot, new LinearLayout.LayoutParams(titleSlotWidth, dp(76)));
            // Cap wide title logos to the Zone Interdite reference ratio while
            // keeping the existing 76dp height and 21x18dp anchor.
            FrameLayout.LayoutParams titleLogoParams = new FrameLayout.LayoutParams(
                    titleLogoReferenceMaxWidth(76), dp(76), Gravity.TOP | Gravity.LEFT);
            titleLogoParams.leftMargin = dp(21);
            titleLogoParams.topMargin = dp(18);
            if (heroStyle == 0) hero.addView(titleLogo, titleLogoParams);
            JSONObject resumeMetadata = isExternalPlaybackResumeSource(program.sourcePackage)
                    ? externalResumeItem(program) : netflixResume ? sharedExternalResume(sharedExternalResumeKey(program)) : null;
            // Follow the same cleaned title path as the category Hero. Resume
            // records may carry provider suffixes or episode markers that
            // make the title-logo and genre lookups miss the folder match.
            String logoSearchTitle = titleValue;
            String heroCategory = isExternalLiveProgram(program) ? "live"
                    : seriesResume ? "series"
                    : isExternalPlaybackResumeSource(program.sourcePackage) ? "movies"
                    : "videos";
            boolean freeboxVideo = FILE_VIDEO_RESUME_SOURCE.equals(program.sourcePackage);
            boolean freeboxFolder = FREEBOX_FOLDER_SOURCE.equals(program.sourcePackage);
            JSONObject heroMetadataSource = resumeMetadata;
            if (resumeMetadata != null && isExternalPlaybackResumeSource(program.sourcePackage)) {
                JSONObject editorialSource = homeHeroEditorialSource(resumeMetadata, seriesResume);
                if (editorialSource.has("id")) heroMetadataSource = editorialSource;
            }
            if (heroStyle == 0 && !freeboxVideo && !freeboxFolder && !netflixResume)
                loadHomeCategoryHeroTitleLogo(heroCategory, logoSearchTitle,
                    heroMetadataSource, program, titleLogo);

            TextView heroMetadata = text(
                    freeboxVideo || freeboxFolder || netflixResume ? ""
                            : homeCategoryHeroMetadata(heroCategory, program, heroMetadataSource),
                    15, Color.WHITE);
            heroMetadata.setAlpha(.82f);
            heroMetadata.setSingleLine(true);
            heroMetadata.setEllipsize(TextUtils.TruncateAt.END);
            heroMetadata.setGravity(Gravity.LEFT | Gravity.CENTER_VERTICAL);
            LinearLayout.LayoutParams heroMetadataParams = new LinearLayout.LayoutParams(-1, dp(30));
            heroMetadataParams.topMargin = heroEditorialSpacing;
            content.addView(heroMetadata, heroMetadataParams);
            if (heroMetadataSource != null && !netflixResume && !isExternalLiveProgram(program) && !freeboxVideo && !freeboxFolder) {
                loadHeroGenreFallback(heroMetadata, titleValue,
                        seriesResume ? "tv" : "movie",
                        firstExternalValue(heroMetadataSource, "year", "release_year", "releaseYear"),
                        heroMetadataSource);
            }

            TextView heroCredits = text("", 13, Color.WHITE);
            heroCredits.setTag("home_continue_hero_credits");
            heroCredits.setAlpha(.84f);
            heroCredits.setMaxLines(2);
            heroCredits.setEllipsize(TextUtils.TruncateAt.END);
            heroCredits.setVisibility(View.GONE);
            LinearLayout.LayoutParams heroCreditsParams = new LinearLayout.LayoutParams(-1, dp(36));
            heroCreditsParams.topMargin = heroEditorialSpacing;
            content.addView(heroCredits, heroCreditsParams);
            if (!freeboxVideo && !freeboxFolder && !netflixResume) {
                loadContinueWatchingHeroCredits(hero, heroCredits, program, heroMetadataSource,
                        seriesResume);
            }

            String synopsisValue = freeboxVideo || freeboxFolder || netflixResume ? ""
                    : homeCategoryHeroSynopsis(heroCategory, program, heroMetadataSource);
            String subtitleValue = seriesResume ? episodeCode : "";
            TextView episodeBadge = null;
            if (!subtitleValue.isEmpty() || netflixResume) {
                episodeBadge = text(subtitleValue, 17, Color.WHITE);
                episodeBadge.setVisibility(subtitleValue.isEmpty() ? View.GONE : View.VISIBLE);
                TextView subtitle = episodeBadge;
                subtitle.setTypeface(null, Typeface.BOLD);
                subtitle.setSingleLine(true);
                subtitle.setGravity(Gravity.CENTER);
                // Compact the series code badge by 30% while keeping the
                // SxxExx label itself readable and unchanged.
                subtitle.setPadding(dp(13), 0, dp(13), 0);
                GradientDrawable episodeBadgeBackground = new GradientDrawable();
                episodeBadgeBackground.setColor(Color.rgb(82, 82, 82));
                episodeBadgeBackground.setCornerRadius(dp(13));
                subtitle.setBackground(episodeBadgeBackground);
                LinearLayout.LayoutParams subtitleParams = new LinearLayout.LayoutParams(-2, dp(28));
                subtitleParams.gravity = Gravity.LEFT;
                subtitleParams.topMargin = heroEditorialSpacing;
                content.addView(subtitle, subtitleParams);
            }

            TextView description = text(synopsisValue, 14, Color.WHITE);
            description.setAlpha(.88f);
            description.setText(shortenContinueWatchingHeroSynopsis(synopsisValue));
            description.setMaxLines(9);
            description.setEllipsize(TextUtils.TruncateAt.END);
            int synopsisHeight = description.getLineHeight() * 9;
            LinearLayout.LayoutParams descriptionParams = new LinearLayout.LayoutParams(-1, synopsisHeight);
            descriptionParams.topMargin = heroEditorialSpacing;
            content.addView(description, descriptionParams);
            if (!freeboxVideo && !freeboxFolder && !netflixResume)
                useMediumSynopsisWhenClipped(description, heroMediumSynopsis(heroMetadataSource));
            if (freeboxFolder) {
                loadHomeCategoryFolderMetadata(hero, program, title, titleLogo, heroMetadata,
                        heroCredits, description, artwork);
            } else if (freeboxVideo) {
                loadHomeCategoryVideoFileMetadata(hero, program, title, titleLogo,
                        heroMetadata, heroCredits, description);
            } else if (netflixResume) {
                loadNetflixContinueWatchingMetadata(hero, program, heroMetadataSource, title, titleLogo, artwork,
                        heroMetadata, heroCredits, description, episodeBadge, episodeCode);
            } else if (isExternalPlaybackResumeSource(program.sourcePackage) && !isExternalLiveProgram(program)) {
                loadContinueWatchingIptvMetadata(hero, program, heroMetadataSource, seriesResume,
                        titleLogo, heroMetadata, heroCredits, description);
            }

            // Title and synopsis belong to the top editorial block. The
            // remaining space is flexible so the complete playback block
            // (button, time, progress and dots) stays anchored at the bottom.
            View editorialSpacer = new View(this);
            content.addView(editorialSpacer, new LinearLayout.LayoutParams(-1, 0, 1f));

            float playbackBlockLiftPx = -dp(5);
            LinearLayout actions = new LinearLayout(this);
            actions.setGravity(Gravity.CENTER_VERTICAL);
            actions.setTranslationY(playbackBlockLiftPx);
            TextView button = text("▶  Reprendre", 15, Color.rgb(8, 12, 20));
            button.setTypeface(null, Typeface.BOLD);
            button.setGravity(Gravity.CENTER);
            button.setFocusable(true);
            button.setClickable(true);
            // Keep the focus identity on the actual control that receives
            // focus. This lets a rebuilt Hero restore the same item instead
            // of falling back to the first header action.
            button.setTag(resumeDismissKey(program));
            if (freeboxVideo) button.setTag(CATEGORY_VIDEO_METADATA_REFRESH_TAG, (Runnable) () ->
                    loadHomeCategoryVideoFileMetadata(hero, program, title, titleLogo,
                            heroMetadata, heroCredits, description));
            button.setBackground(homeHeroButtonBackground(heroStyle, false));
            button.setTextColor(homeHeroButtonTextColor(heroStyle, false));
            watchButton[0] = button;
            // Keep the artwork reference separately from the stable focus
            // key stored in the normal tag so the picker can update this Hero
            // immediately for every resume type.
            button.setTag(CONTINUE_WATCHING_HERO_TAG, artwork);
            button.setOnFocusChangeListener((view, focused) -> {
                view.setBackground(homeHeroButtonBackground(heroStyle, focused));
                button.setTextColor(homeHeroButtonTextColor(heroStyle, focused));
                for (android.graphics.drawable.Drawable icon : button.getCompoundDrawables())
                    if (icon != null) icon.setTint(button.getCurrentTextColor());
                updateContinueWatchingHeroDots(dots, selectedIndex[0], focused);
                if (focused) cancelContinueWatchingAutoScroll(scroll, true);
                else scheduleContinueWatchingAutoScroll(scroll, HOME_HERO_AUTO_ADVANCE_MS);
            });
            button.setOnClickListener(view -> openContinueWatchingProgram(programs.get(selectedIndex[0])));
            button.setOnLongClickListener(view -> {
                JojoProgram selected = programs.get(selectedIndex[0]);
                if (FREEBOX_FOLDER_SOURCE.equals(selected.sourcePackage)) showFreeboxFolderHomeMenu(selected, button, true);
                else showContinueWatchingMenu(selected, button, false, true);
                return true;
            });
            button.setOnKeyListener((view, keyCode, event) -> {
                if (event.getAction() != KeyEvent.ACTION_DOWN || event.getRepeatCount() != 0) return false;
                if (keyCode == KeyEvent.KEYCODE_DPAD_LEFT || keyCode == KeyEvent.KEYCODE_DPAD_RIGHT) {
                    changePage.accept(keyCode == KeyEvent.KEYCODE_DPAD_LEFT ? -1 : 1);
                    return true;
                }
                if (keyCode == KeyEvent.KEYCODE_DPAD_UP || keyCode == KeyEvent.KEYCODE_DPAD_DOWN) {
                    int targetId = keyCode == KeyEvent.KEYCODE_DPAD_UP
                            ? view.getNextFocusUpId() : view.getNextFocusDownId();
                    View target = targetId == View.NO_ID ? null : view.getRootView().findViewById(targetId);
                    if (target != null && target.isFocusable()) {
                        target.requestFocus();
                        return true;
                    }
                }
                return false;
            });
            actions.addView(button, new LinearLayout.LayoutParams(dp(130), dp(40)));
            if (restoreButtonFocus) {
                // Wait until the replacement view is attached and laid out;
                // requesting focus synchronously races removeAllViews().
                button.post(() -> {
                    if (button.isAttachedToWindow() && watchButton[0] == button) {
                        boolean requested = button.requestFocus();
                        if (requested) {
                            hero.setFocusableInTouchMode(false);
                            hero.setFocusable(false);
                        }
                    }
                });
            }
            TextView remaining = text(continueWatchingRemainingLabel(program), 14, Color.WHITE);
            remaining.setGravity(Gravity.CENTER_VERTICAL);
            LinearLayout.LayoutParams remainingParams = new LinearLayout.LayoutParams(0, dp(40), 1f);
            remainingParams.leftMargin = dp(18);
            actions.addView(remaining, remainingParams);
            // Remonter uniquement le bloc de lecture du Hero d'accueil
            // (bouton, durée restante, progression et indicateurs), sans
            // déplacer le titre ni la description.
            LinearLayout.LayoutParams actionsParams = new LinearLayout.LayoutParams(-1, dp(44));
            actionsParams.topMargin = -dp(10);
            content.addView(actions, actionsParams);

            LinearLayout progressAndDots = new LinearLayout(this);
            progressAndDots.setGravity(Gravity.CENTER_VERTICAL);
            progressAndDots.setTranslationY(playbackBlockLiftPx);
            if (SystemContinueWatching.hasProgress(program.duration, program.position)) {
                float ratio = Math.min(1f, Math.max(.02f, program.position / (float) program.duration));
                FrameLayout progressFrame = new FrameLayout(this);
                View track = new View(this);
                track.setBackground(continueWatchingTrack());
                progressFrame.addView(track, new FrameLayout.LayoutParams(-1, dp(5), Gravity.CENTER_VERTICAL));
                View progress = new View(this);
                progress.setBackground(continueWatchingProgress());
                progressFrame.addView(progress, new FrameLayout.LayoutParams(Math.max(dp(8), Math.round(dp(270) * ratio)), dp(5), Gravity.LEFT | Gravity.CENTER_VERTICAL));
                progressAndDots.addView(progressFrame, new LinearLayout.LayoutParams(0, dp(18), 1f));
                progressFrame.addOnLayoutChangeListener((view, left, top, right, bottom,
                        oldLeft, oldTop, oldRight, oldBottom) -> {
                    int trackWidth = right - left;
                    if (trackWidth <= 0) return;
                    FrameLayout.LayoutParams progressParams = (FrameLayout.LayoutParams) progress.getLayoutParams();
                    int targetWidth = Math.max(dp(8), Math.round(trackWidth * ratio));
                    if (progressParams.width == targetWidth) return;
                    progress.post(() -> {
                        if (!progress.isAttachedToWindow()) return;
                        FrameLayout.LayoutParams settled = (FrameLayout.LayoutParams) progress.getLayoutParams();
                        int width = Math.max(dp(8), Math.round(progressFrame.getWidth() * ratio));
                        if (settled.width == width) return;
                        settled.width = width;
                        progress.setLayoutParams(settled);
                    });
                });
            } else {
                progressAndDots.addView(new View(this), new LinearLayout.LayoutParams(0, dp(18), 1f));
            }

            hero.addView(dotsScroll, dotsParams);
            updatePagination.run();
            content.addView(progressAndDots, new LinearLayout.LayoutParams(-1, dp(18)));
            if (heroStyle == 0) {
                keepHomeHeroSynopsisAbovePlayback(content, description, editorialSpacer);
            } else {
                displayedPoster[0] = applyRefinedHomeHero(hero, content, titleSlot, title,
                        heroMetadata, heroCredits, episodeBadge, description,
                        actions, button, remaining, progressAndDots, dotsScroll,
                        program, heroMetadataSource, heroStyle, refinedHeroLayoutListener);
            }
            hero.post(wirePage);
        };

        bindSelected[0].run();
        Runnable advanceHero = () -> {
            if (programs.isEmpty() || heroInteractionPaused[0]) return;
            int targetIndex = HomeMediaRules.homeHeroNextPage(selectedIndex[0], programs.size(), 1);
            selectedIndex[0] = targetIndex;
            hero.animate().cancel();
            bindSelected[0].run();
            hero.setAlpha(.55f);
            hero.animate().alpha(1f).setDuration(500L).start();
        };
        scroll.addOnAttachStateChangeListener(new View.OnAttachStateChangeListener() {
            @Override public void onViewAttachedToWindow(View view) {
                if (!programs.isEmpty()) {
                    continueWatchingCarouselAdvancers.put(scroll, advanceHero);
                    scheduleContinueWatchingAutoScroll(scroll, HOME_HERO_AUTO_ADVANCE_MS);
                }
            }
            @Override public void onViewDetachedFromWindow(View view) {
                continueWatchingCarouselAdvancers.remove(scroll);
                cancelContinueWatchingAutoScroll(scroll, true);
            }
        });
        currentHomeHeroUpdater = updated -> {
            if (updated == null) return;
            boolean changed = homeTitleLogoRefreshPending || homeArtworkRefreshPending || programs.size() != updated.size();
            for (int index = 0; !changed && index < programs.size(); index++) {
                JojoProgram previous = programs.get(index), current = updated.get(index);
                changed = !resumeProgramKey(previous).equals(resumeProgramKey(current))
                        || previous.duration != current.duration
                        || previous.position != current.position
                        || previous.watched != current.watched
                        || !java.util.Objects.equals(previous.title, current.title)
                        || !java.util.Objects.equals(previous.intentUri, current.intentUri)
                        || !java.util.Objects.equals(previous.description, current.description)
                        || !java.util.Objects.equals(previous.artwork, current.artwork)
                        || !java.util.Objects.equals(previous.seasonNumber, current.seasonNumber)
                        || !java.util.Objects.equals(previous.episodeNumber, current.episodeNumber);
            }
            int newlyPlayedIndex = lastHomePlaybackIndex(updated);
            boolean selectSyncedPlayback = false;
            for (int index = 0; index < updated.size(); index++) {
                if (resumeProgramKey(updated.get(index)).equals(pendingSyncedHeroKey)) {
                    newlyPlayedIndex = index;
                    selectSyncedPlayback = true;
                    pendingSyncedHeroKey = null;
                    break;
                }
            }
            boolean selectLastPlayback = newlyPlayedIndex >= 0
                    && (selectSyncedPlayback || preferLastPlaybackInHomeHero || lastHomePlaybackIndex(programs) < 0);
            boolean selectedSuggestions = selectedIndex[0] == programs.size();
            boolean keepSuggestions = selectedSuggestions && (!programs.isEmpty() || hero.hasFocus());
            if (selectedSuggestions && hero.hasFocus() && !preferLastPlaybackInHomeHero) selectLastPlayback = false;
            if (!changed && !selectLastPlayback) {
                refreshEmptyHomeSuggestions();
                return;
            }
            homeTitleLogoRefreshPending = false;
            homeArtworkRefreshPending = false;
            String selectedKey = selectedSuggestions ? "" : continueWatchingInsertionKey(programs.get(selectedIndex[0]));
            int previousIndex = selectedIndex[0];
            List<JojoProgram> snapshot = new ArrayList<>(updated);
            programs.clear();
            programs.addAll(snapshot);
            selectedIndex[0] = keepSuggestions ? programs.size()
                    : Math.min(previousIndex, Math.max(0, programs.size() - 1));
            if (selectLastPlayback) {
                selectedIndex[0] = newlyPlayedIndex;
                preferLastPlaybackInHomeHero = false;
            } else {
                for (int index = 0; index < programs.size(); index++) {
                    if (selectedKey.equals(continueWatchingInsertionKey(programs.get(index)))) {
                        selectedIndex[0] = index;
                        break;
                    }
                }
            }
            bindSelected[0].run();
            if (!programs.isEmpty() && scroll.isAttachedToWindow()
                    && !continueWatchingCarouselAdvancers.containsKey(scroll)) {
                continueWatchingCarouselAdvancers.put(scroll, advanceHero);
                scheduleContinueWatchingAutoScroll(scroll, HOME_HERO_AUTO_ADVANCE_MS);
            } else if (programs.isEmpty()) {
                continueWatchingCarouselAdvancers.remove(scroll);
                cancelContinueWatchingAutoScroll(scroll, true);
            }
        };
        row.setGravity(Gravity.LEFT);
        // Let the Hero occupy the full reserved height so its black lower
        // area reaches the fixed bottom navigation without a visible gap.
        row.addView(hero, new LinearLayout.LayoutParams(heroWidth,
                fillHomeHero ? -1 : dp(continueWatchingHeroHeightDp())));
        scroll.addView(row, new HorizontalScrollView.LayoutParams(heroWidth, -1));
        LinearLayout.LayoutParams scrollParams = new LinearLayout.LayoutParams(
                heroWidth + edgeInset * 2,
                fillHomeHero ? -1 : dp(continueWatchingHeroHeightDp()));
        scrollParams.leftMargin = -edgeInset;
        rows.addView(scroll, scrollParams);
        wireHorizontalCardRowDpad(row);
        wireResumeRowsDpad(rows);
        // The cached first Home render can be focused before the generic row
        // wiring runs. Start the carousel from the attached Hero itself so it
        // does not depend on a later refresh to schedule the first advance.
        if (!programs.isEmpty()) {
            scroll.post(() -> {
                if (scroll.isAttachedToWindow()) scheduleContinueWatchingAutoScroll(scroll, HOME_HERO_AUTO_ADVANCE_MS);
            });
        }
        return rows;
    }

    private View homeSuggestionsHero(java.util.function.IntConsumer changePage,
            java.util.function.IntSupplier pageCount) {
        LinearLayout hero = new LinearLayout(this);
        hero.setOrientation(LinearLayout.VERTICAL);
        hero.setBackgroundColor(Color.BLACK);
        hero.setPadding(dp(12), dp(8), dp(12), dp(10));
        hero.setFocusable(false);
        hero.setTag("home_empty_suggestions");
        hero.setContentDescription("Suggestions pour vous");
        TextView heading = text("Suggestions pour vous", 23, Color.WHITE);
        heading.setTypeface(Typeface.DEFAULT, Typeface.BOLD);
        heading.setGravity(Gravity.CENTER_VERTICAL);
        heading.setMaxLines(1);
        heading.setEllipsize(TextUtils.TruncateAt.END);
        float fontScale = Math.max(1f, getResources().getConfiguration().fontScale);
        LinearLayout titleRow = new LinearLayout(this);
        titleRow.setGravity(Gravity.CENTER_VERTICAL);
        titleRow.addView(heading, new LinearLayout.LayoutParams(0, -1, 1f));
        hero.addView(titleRow, new LinearLayout.LayoutParams(-1, dp(Math.round(36 * fontScale))));

        String[] categories = {"videos", "movies", "series"};
        int[] colors = {Color.rgb(109, 202, 105), Color.rgb(176, 113, 229), Color.rgb(83, 174, 230)};
        int[] icons = {R.drawable.ic_home_category_clapper, R.drawable.ic_home_category_film_reel,
                R.drawable.ic_home_category_series_bottom};
        LinearLayout headers = new LinearLayout(this);
        TextView[] categoryLabels = new TextView[categories.length];
        for (int column = 0; column < categories.length; column++) {
            LinearLayout label = new LinearLayout(this);
            label.setGravity(Gravity.CENTER_VERTICAL);
            label.setPadding(dp(6), 0, dp(6), 0);
            ImageView icon = new ImageView(this);
            icon.setImageResource(icons[column]);
            icon.setColorFilter(colors[column]);
            label.addView(icon, new LinearLayout.LayoutParams(dp(20), dp(20)));
            TextView name = text(homeCategoryTitle(categories[column]), 16, Color.WHITE);
            name.setMaxLines(1);
            name.setEllipsize(TextUtils.TruncateAt.END);
            categoryLabels[column] = name;
            name.setTypeface(Typeface.DEFAULT, Typeface.BOLD);
            name.setPadding(dp(8), 0, 0, 0);
            label.addView(name);
            LinearLayout.LayoutParams params = new LinearLayout.LayoutParams(0, dp(Math.round(30 * fontScale)), 1f);
            if (column < 2) params.rightMargin = dp(12);
            headers.addView(label, params);
        }
        hero.addView(headers);
        RecyclerView list = new RecyclerView(this, null, android.R.attr.scrollViewStyle);
        LinearLayoutManager layout = new LinearLayoutManager(this);
        list.setLayoutManager(layout);
        list.setItemAnimator(null);
        list.setFocusable(false);
        list.setOverScrollMode(View.OVER_SCROLL_NEVER);
        list.setVerticalScrollBarEnabled(false);
        HomeSuggestionsAdapter adapter = new HomeSuggestionsAdapter(list, categories, icons, colors,
                categoryLabels, changePage, pageCount);
        list.setAdapter(adapter);
        hero.addView(list, new LinearLayout.LayoutParams(-1, 0, 1f));
        Runnable resize = () -> {
            int bodyHeight = hero.getHeight() - hero.getPaddingTop() - hero.getPaddingBottom()
                    - titleRow.getHeight() - headers.getHeight();
            float density = getResources().getDisplayMetrics().density;
            int visibleRows = hero.getHeight() == 0 ? 3 : HomeMediaRules.homeSuggestionRowCount(
                    Math.round(bodyHeight / density) - 8, getResources().getConfiguration().fontScale);
            int maximumHeight = dp(Math.round(112 * Math.max(1f, getResources().getConfiguration().fontScale)));
            int rowHeight = hero.getHeight() == 0 ? dp(86)
                    : Math.max(1, Math.min(maximumHeight, (bodyHeight - dp(8) * visibleRows) / visibleRows));
            int cardWidth = hero.getWidth() == 0 ? dp(280)
                    : Math.max(1, (hero.getWidth() - hero.getPaddingLeft() - hero.getPaddingRight() - dp(24)) / 3);
            adapter.resize(rowHeight, dp(HomeMediaRules.homeSuggestionArtworkWidthDp(
                    Math.round(cardWidth / density), Math.round(rowHeight / density))));
        };
        Runnable update = () -> {
            adapter.refresh();
            resize.run();
        };
        currentHomeSuggestionsUpdater = () -> { if (hero.isAttachedToWindow()) update.run(); };
        hero.addOnLayoutChangeListener((view, left, top, right, bottom, oldLeft, oldTop, oldRight, oldBottom) -> {
            if (right - left != oldRight - oldLeft || bottom - top != oldBottom - oldTop) resize.run();
        });
        list.addOnLayoutChangeListener((view, left, top, right, bottom, oldLeft, oldTop, oldRight, oldBottom) -> {
            adapter.focusPending();
            adapter.wireNavigation();
        });
        list.addOnScrollListener(new RecyclerView.OnScrollListener() {
            @Override public void onScrolled(RecyclerView recycler, int dx, int dy) { adapter.wireNavigation(); }
        });
        update.run();
        preloadHomeCategoryFavoriteSnapshots();
        return hero;
    }

    private void refreshEmptyHomeSuggestions() {
        if (currentHomeSuggestionsUpdater != null) currentHomeSuggestionsUpdater.run();
    }

    private boolean homeSuggestionRowVisible(ViewGroup row) {
        if (row.getVisibility() != View.VISIBLE) return false;
        if (!(row.getParent() instanceof RecyclerView)) return true;
        RecyclerView list = (RecyclerView) row.getParent();
        return row.getBottom() > list.getPaddingTop()
                && row.getTop() < list.getHeight() - list.getPaddingBottom();
    }

    private final class HomeSuggestionRow extends RecyclerView.ViewHolder {
        final View[] cards = new View[3];
        final String[] artworkKeys = new String[3];
        HomeSuggestionRow(LinearLayout row) { super(row); }
    }

    private final class HomeSuggestionsAdapter extends RecyclerView.Adapter<HomeSuggestionRow> {
        final RecyclerView list;
        final String[] categories;
        final int[] icons, colors;
        final TextView[] labels;
        final java.util.function.IntConsumer changePage;
        final java.util.function.IntSupplier pageCount;
        final List<List<JojoProgram>> programs = new ArrayList<>();
        Set<String> inProgressVideoFolders = Collections.emptySet();
        String snapshot = "";
        int rowHeight = dp(86), artworkWidth = dp(112);
        int pendingRow = -1, pendingColumn;

        HomeSuggestionsAdapter(RecyclerView list, String[] categories, int[] icons, int[] colors, TextView[] labels,
                java.util.function.IntConsumer changePage, java.util.function.IntSupplier pageCount) {
            this.list = list;
            this.categories = categories;
            this.icons = icons;
            this.colors = colors;
            this.labels = labels;
            this.changePage = changePage;
            this.pageCount = pageCount;
            for (String category : categories) programs.add(Collections.emptyList());
        }

        @Override public int getItemCount() {
            int count = 1;
            for (List<JojoProgram> column : programs) count = Math.max(count, column.size());
            return count;
        }

        private int[] counts() {
            return new int[]{programs.get(0).size(), programs.get(1).size(), programs.get(2).size()};
        }

        private JojoProgram program(int row, int column) {
            return row >= 0 && row < programs.get(column).size() ? programs.get(column).get(row) : null;
        }

        void refresh() {
            List<List<JojoProgram>> updated = new ArrayList<>();
            int profileId = HomeWatchProgressBridge.currentProfileId(MainActivity.this);
            inProgressVideoFolders = inProgressFreeboxFolderPaths(profileId);
            StringBuilder nextSnapshot = new StringBuilder().append(profileId).append('|').append(homeVideoArtworkRevision).append('\n');
            for (String category : categories) {
                List<JojoProgram> column = homeSuggestionPrograms(category);
                updated.add(column);
                for (JojoProgram program : column) {
                    nextSnapshot.append(resumeDismissKey(program)).append('|').append(program.title)
                            .append('|').append(program.artwork).append('|').append(program.duration)
                            .append('|').append(program.position).append('|').append(program.watched)
                            .append('|').append(inProgressVideoFolders.contains(comparableSmbPath(program.intentUri))).append('\n');
                }
                nextSnapshot.append(homeCategoryFavoriteSnapshots.get(category)).append('\n');
            }
            if (snapshot.contentEquals(nextSnapshot)) return;
            snapshot = nextSnapshot.toString();
            View focused = list.findFocus();
            View rowView = focused == null ? null : list.findContainingItemView(focused);
            int focusedRow = rowView == null ? -1 : list.getChildAdapterPosition(rowView), focusedColumn = 0;
            if (rowView instanceof LinearLayout) focusedColumn = ((LinearLayout) rowView).indexOfChild(focused);
            JojoProgram selected = focusedRow < 0 ? null : program(focusedRow, Math.max(0, focusedColumn));
            int previousCount = getItemCount();
            for (int column = 0; column < categories.length; column++) {
                programs.set(column, updated.get(column));
                labels[column].setText(homeCategoryTitle(categories[column]) + " · " + programs.get(column).size());
            }
            if (focusedRow >= 0) {
                int targetRow = Math.min(focusedRow, getItemCount() - 1);
                if (selected != null) for (int index = 0; index < programs.get(focusedColumn).size(); index++) {
                    if (resumeDismissKey(selected).equals(resumeDismissKey(programs.get(focusedColumn).get(index)))) {
                        targetRow = index;
                        break;
                    }
                }
                pendingRow = targetRow;
                pendingColumn = HomeMediaRules.homeSuggestionTargetColumn(counts(), targetRow, focusedColumn);
                if (targetRow != focusedRow) ((LinearLayoutManager) list.getLayoutManager()).scrollToPosition(targetRow);
                list.post(this::focusPending);
            }
            // Keep attached rows and their focus when metadata or contents change.
            // notifyDataSetChanged makes RecyclerView invalidate the whole tree.
            int count = getItemCount();
            notifyItemRangeChanged(0, Math.min(previousCount, count));
            if (count > previousCount) notifyItemRangeInserted(previousCount, count - previousCount);
            else if (count < previousCount) notifyItemRangeRemoved(count, previousCount - count);
        }

        void resize(int height, int width) {
            if (rowHeight == height && artworkWidth == width) return;
            rowHeight = height;
            artworkWidth = width;
            for (int index = 0; index < list.getChildCount(); index++) {
                HomeSuggestionRow holder = (HomeSuggestionRow) list.getChildViewHolder(list.getChildAt(index));
                size(holder);
            }
            list.requestLayout();
        }

        private void size(HomeSuggestionRow holder) {
            if (holder.itemView.getLayoutParams().height != rowHeight) {
                holder.itemView.getLayoutParams().height = rowHeight;
                holder.itemView.requestLayout();
            }
            for (View card : holder.cards) {
                View picture = ((ViewGroup) card).getChildAt(0);
                int height = Math.max(1, artworkWidth * 9 / 16);
                if (picture.getLayoutParams().width != artworkWidth || picture.getLayoutParams().height != height) {
                    picture.getLayoutParams().width = artworkWidth;
                    picture.getLayoutParams().height = height;
                    picture.requestLayout();
                }
            }
        }

        @Override public HomeSuggestionRow onCreateViewHolder(ViewGroup parent, int viewType) {
            LinearLayout row = new LinearLayout(MainActivity.this);
            row.setTag("home_suggestions_row");
            RecyclerView.LayoutParams rowParams = new RecyclerView.LayoutParams(-1, rowHeight);
            rowParams.topMargin = dp(8);
            row.setLayoutParams(rowParams);
            HomeSuggestionRow holder = new HomeSuggestionRow(row);
            for (int column = 0; column < 3; column++) {
                final int selectedColumn = column;
                View card = homeSuggestionCard();
                card.setOnClickListener(view -> {
                    int position = holder.getBindingAdapterPosition();
                    if (position == RecyclerView.NO_POSITION) return;
                    rememberHomeFocus();
                    JojoProgram selected = program(position, selectedColumn);
                    if (selected == null) openHomeCategoryPage(categories[selectedColumn]);
                    else if ("external-playback".equals(selected.sourcePackage))
                        openExternalPlayback(ExternalPlaybackStore.get(MainActivity.this, selected.intentUri), true, false);
                    else openContinueWatchingProgram(selected);
                });
                card.setOnLongClickListener(view -> {
                    int position = holder.getBindingAdapterPosition();
                    if (position == RecyclerView.NO_POSITION) return true;
                    JojoProgram selected = program(position, selectedColumn);
                    if (selected == null) return false;
                    rememberHomeFocus();
                    if (FREEBOX_FOLDER_SOURCE.equals(selected.sourcePackage))
                        showFreeboxFolderHomeMenu(selected, view, false);
                    else showContinueWatchingMenu(selected, view,
                            "external-playback".equals(selected.sourcePackage), false);
                    return true;
                });
                card.setOnKeyListener((view, keyCode, event) -> handleKey(holder, selectedColumn, keyCode, event));
                LinearLayout.LayoutParams params = new LinearLayout.LayoutParams(0, -1, 1f);
                if (column < 2) params.rightMargin = dp(12);
                row.addView(card, params);
                holder.cards[column] = card;
            }
            return holder;
        }

        @Override public void onBindViewHolder(HomeSuggestionRow holder, int position) {
            size(holder);
            for (int column = 0; column < 3; column++) {
                JojoProgram selected = program(position, column);
                JSONObject item = null;
                if (selected != null && "external-playback".equals(selected.sourcePackage)) {
                    for (JSONObject favorite : homeCategoryFavoriteSnapshots.getOrDefault(categories[column], Collections.emptyList())) {
                        if (selected.intentUri.equals(favorite.optString("id", ""))) { item = favorite; break; }
                    }
                    if (item == null) item = externalResumeItem(selected);
                }
                View card = holder.cards[column];
                boolean visible = selected != null || position == 0;
                card.setTag("home-suggestion:" + categories[column] + ":" + position);
                card.setVisibility(visible ? View.VISIBLE : View.INVISIBLE);
                card.setFocusable(visible);
                card.setLongClickable(selected != null);
                card.setNextFocusUpId(View.NO_ID);
                card.setNextFocusDownId(View.NO_ID);
                String key = selected == null ? "" : resumeDismissKey(selected) + "|" + selected.artwork + "|" + item
                        + ("videos".equals(categories[column]) ? "|" + homeVideoArtworkRevision : "");
                bindHomeSuggestionCard(card, categories[column], selected, item,
                        visible && !key.equals(holder.artworkKeys[column]), icons[column], colors[column],
                        selected != null && inProgressVideoFolders.contains(comparableSmbPath(selected.intentUri)));
                if (visible) holder.artworkKeys[column] = key;
            }
            List<View> targets = immediateFocusableChildren((ViewGroup) holder.itemView);
            for (int index = 0; index < targets.size(); index++) {
                View card = targets.get(index);
                card.setNextFocusLeftId(targets.get((index + targets.size() - 1) % targets.size()).getId());
                card.setNextFocusRightId(targets.get((index + 1) % targets.size()).getId());
            }
            if (position == 0) registerHomeRowMoveTrigger(holder.cards[0], "resumes");
            else holder.cards[0].setTag(HOME_ROW_MOVE_KEY_TAG, null);
        }

        @Override public void onViewAttachedToWindow(HomeSuggestionRow holder) {
            size(holder);
            list.post(this::focusPending);
        }

        @Override public void onViewRecycled(HomeSuggestionRow holder) {
            for (int column = 0; column < 3; column++) {
                ImageView image = (ImageView) ((ViewGroup) ((ViewGroup) holder.cards[column]).getChildAt(0)).getChildAt(0);
                artworkLoadRequests.remove(image);
                videoArtworkRequests.remove(image);
                image.setTag("");
                image.setTag(HOME_HERO_PREVIEW_KEY_TAG, "");
                image.setTag(CATEGORY_VIDEO_METADATA_REQUEST_TAG, null);
                ((HomeSuggestionImageView) image).landscapeFallback = null;
                image.setImageDrawable(null);
                holder.artworkKeys[column] = null;
            }
        }

        void wireNavigation() {
            if (!list.isAttachedToWindow()) return;
            if (currentHomeHeaderView != null && currentHomeAppsView != null)
                wireHomeHeaderDpad(currentHomeHeaderView, currentHomeAppsView, currentHomeFilesView, currentHomeResumesView);
            wireResumeRowsDpad((ViewGroup) list.getParent());
            wireHomeSectionVerticalDpad();
            wireHomeCategoryGridDpad(currentHomeCategoryGrid, currentHomeResumesView);
        }

        void focusPending() {
            if (pendingRow < 0) return;
            if (list.hasPendingAdapterUpdates() || list.isComputingLayout()) {
                if (list.isAttachedToWindow()) list.postOnAnimation(this::focusPending);
                return;
            }
            HomeSuggestionRow holder = (HomeSuggestionRow) list.findViewHolderForAdapterPosition(pendingRow);
            if (holder == null) return;
            int column = pendingColumn;
            if (holder.cards[column].requestFocus()) pendingRow = -1;
        }

        private void focusAt(int row, int column, int direction) {
            pendingRow = row;
            pendingColumn = HomeMediaRules.homeSuggestionTargetColumn(counts(), row, column);
            HomeSuggestionRow holder = (HomeSuggestionRow) list.findViewHolderForAdapterPosition(row);
            if (holder != null && holder.itemView.getTop() >= list.getPaddingTop()
                    && holder.itemView.getBottom() <= list.getHeight() - list.getPaddingBottom()) {
                focusPending();
                return;
            }
            list.stopScroll();
            // Scroll synchronously: the next card must be attached before the
            // currently focused row can be recycled and Android searches the header.
            View first = list.getChildAt(0);
            if (first != null) {
                int top = first.getTop() + (row - list.getChildAdapterPosition(first)) * (rowHeight + dp(8));
                int scroll = top < list.getPaddingTop() ? top - list.getPaddingTop()
                        : Math.max(0, top + rowHeight - list.getHeight() + list.getPaddingBottom());
                list.scrollBy(0, scroll);
            }
            focusPending();
            list.post(this::focusPending);
        }

        private boolean handleKey(HomeSuggestionRow holder, int column, int keyCode, KeyEvent event) {
            if (keyCode != KeyEvent.KEYCODE_DPAD_UP && keyCode != KeyEvent.KEYCODE_DPAD_DOWN
                    && keyCode != KeyEvent.KEYCODE_DPAD_LEFT && keyCode != KeyEvent.KEYCODE_DPAD_RIGHT) return false;
            if (event.getAction() != KeyEvent.ACTION_DOWN) return true;
            int row = pendingRow >= 0 ? pendingRow : holder.getBindingAdapterPosition();
            if (row == RecyclerView.NO_POSITION) return true;
            if (keyCode == KeyEvent.KEYCODE_DPAD_LEFT || keyCode == KeyEvent.KEYCODE_DPAD_RIGHT) {
                int direction = keyCode == KeyEvent.KEYCODE_DPAD_LEFT ? -1 : 1;
                for (int step = 1; step <= 3; step++) {
                    int target = column + direction * step;
                    if ((target < 0 || target >= 3) && pageCount.getAsInt() > 1) {
                        if (event.getRepeatCount() == 0) changePage.accept(direction);
                        return true;
                    }
                    target = Math.floorMod(target, 3);
                    if (row == 0 || row < programs.get(target).size()) { focusAt(row, target, 0); break; }
                }
                return true;
            }
            int direction = keyCode == KeyEvent.KEYCODE_DPAD_UP ? -1 : 1;
            int targetRow = row + direction;
            int targetColumn = pendingRow >= 0 ? pendingColumn : column;
            if (targetRow >= 0 && targetRow < Math.max(1, programs.get(targetColumn).size())) {
                focusAt(targetRow, targetColumn, direction);
                return true;
            }
            List<View> targets = direction > 0 ? immediateFocusableChildren(currentHomeCategoryGrid)
                    : currentHomeHeaderView != null && currentHomeHeaderView.getTag() instanceof ViewGroup
                    ? immediateFocusableChildren((ViewGroup) currentHomeHeaderView.getTag()) : Collections.emptyList();
            View target = alignedTarget(targets, targetColumn);
            if (target != null && target.isShown()) {
                pendingRow = -1;
                if (direction > 0) target.setNextFocusUpId(holder.cards[column].getId());
                target.requestFocus();
            }
            return true;
        }
    }

    private List<JojoProgram> homeSuggestionPrograms(String category) {
        ArrayList<JojoProgram> result = new ArrayList<>();
        if ("videos".equals(category)) {
            for (JojoProgram program : cachedFreeboxHomeVideos()) {
                if (!FILE_VIDEO_RESUME_SOURCE.equals(program.sourcePackage)
                        || !hasDeletedFreeboxPath(program.intentUri)) result.add(program);
            }
        } else {
            for (JSONObject item : homeCategoryFavoriteSnapshots.getOrDefault(category, Collections.emptyList())) {
                if (!isExternalRemovalPending(item.optString("id")) && !item.optBoolean("resumeHidden", false))
                    result.add(homeCategoryExternalProgram(category, item));
            }
        }
        return result;
    }

    private GradientDrawable homeSuggestionCardBackground(boolean focused) {
        GradientDrawable background = new GradientDrawable();
        background.setColor(focused ? folderThemeColor() : Color.rgb(16, 23, 31));
        background.setCornerRadius(dp(10));
        background.setStroke(dp(focused ? 2 : 1), focused ? buttonFocusOutlineColor(folderThemeColor()) : Color.rgb(38, 47, 58));
        return background;
    }

    private void applyHomeSuggestionFocus(View card, boolean focused) {
        card.setBackground(homeSuggestionCardBackground(focused));
        int foreground = focused ? contrastingFolderThemeTextColor() : Color.WHITE;
        ((TextView) card.findViewWithTag("suggestion-title")).setTextColor(foreground);
        ((TextView) card.findViewWithTag("suggestion-metadata")).setTextColor(
                focused ? withAlpha(foreground, 225) : Color.rgb(176, 187, 199));
        FrameLayout picture = (FrameLayout) ((ViewGroup) card).getChildAt(0);
        HomeSuggestionImageView image = (HomeSuggestionImageView) picture.getChildAt(0);
        ((GradientDrawable) picture.getBackground()).setColor(
                focused && !image.hasArtwork ? folderThemeColor() : Color.rgb(7, 12, 18));
        if (!image.hasArtwork && picture.getTag() instanceof Integer) {
            image.setColorFilter(focused ? foreground : (Integer) picture.getTag());
        }
    }

    /** Suggestions only accept wide artwork, including asynchronous cached results. */
    private final class HomeSuggestionImageView extends ImageView {
        boolean hasArtwork;
        Runnable landscapeFallback;

        HomeSuggestionImageView() { super(MainActivity.this); }

        @Override public void setImageBitmap(Bitmap bitmap) {
            if (bitmap != null && bitmap.getWidth() <= bitmap.getHeight()) {
                Runnable fallback = landscapeFallback;
                landscapeFallback = null;
                if (fallback != null) fallback.run();
                return;
            }
            hasArtwork = bitmap != null;
            if (hasArtwork) {
                landscapeFallback = null;
                clearColorFilter();
                setPadding(0, 0, 0, 0);
                setScaleType(ImageView.ScaleType.CENTER_CROP);
            }
            super.setImageBitmap(bitmap);
        }
    }

    private boolean isHomeSuggestionCard(View card) {
        return card != null && card.getTag() instanceof String
                && ((String) card.getTag()).startsWith("home-suggestion:");
    }

    private View homeSuggestionCard() {
        LinearLayout card = new LinearLayout(this);
        card.setOrientation(LinearLayout.HORIZONTAL);
        card.setGravity(Gravity.CENTER_VERTICAL);
        card.setId(View.generateViewId());
        card.setBackground(homeSuggestionCardBackground(false));
        card.setClipToOutline(true);
        card.setPadding(dp(6), dp(6), dp(8), dp(6));
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) card.setDefaultFocusHighlightEnabled(false);
        card.setOnFocusChangeListener(this::applyHomeSuggestionFocus);
        card.setOnKeyListener((view, keyCode, event) -> {
            if (event.getAction() != KeyEvent.ACTION_DOWN
                    || (keyCode != KeyEvent.KEYCODE_DPAD_LEFT && keyCode != KeyEvent.KEYCODE_DPAD_RIGHT)) return false;
            int targetId = keyCode == KeyEvent.KEYCODE_DPAD_LEFT ? view.getNextFocusLeftId() : view.getNextFocusRightId();
            View target = ((ViewGroup) view.getParent()).findViewById(targetId);
            return target != null && target.requestFocus();
        });
        FrameLayout picture = new FrameLayout(this);
        GradientDrawable pictureBackground = new GradientDrawable();
        pictureBackground.setColor(Color.rgb(7, 12, 18));
        pictureBackground.setCornerRadius(dp(6));
        picture.setBackground(pictureBackground);
        picture.setClipToOutline(true);
        ImageView image = new HomeSuggestionImageView();
        image.setScaleType(ImageView.ScaleType.FIT_CENTER);
        picture.addView(image, new FrameLayout.LayoutParams(-1, -1));
        card.addView(picture, new LinearLayout.LayoutParams(dp(112), dp(63)));
        LinearLayout details = new LinearLayout(this);
        details.setOrientation(LinearLayout.VERTICAL);
        details.setGravity(Gravity.CENTER_VERTICAL);
        details.setPadding(dp(10), 0, 0, 0);
        for (String field : new String[]{"title", "metadata"}) {
            TextView line = text("", "title".equals(field) ? 15 : 12,
                    "title".equals(field) ? Color.WHITE : Color.rgb(185, 192, 198));
            line.setTag("suggestion-" + field);
            line.setIncludeFontPadding(false);
            line.setMaxLines("title".equals(field) ? 2 : 1);
            line.setEllipsize(TextUtils.TruncateAt.END);
            if ("title".equals(field)) line.setTypeface(Typeface.DEFAULT, Typeface.BOLD);
            details.addView(line, new LinearLayout.LayoutParams(-1, -2));
        }
        card.addView(details, new LinearLayout.LayoutParams(0, -1, 1f));
        return card;
    }

    private void bindHomeSuggestionCard(View card, String category, JojoProgram program,
                                        JSONObject item, boolean loadImage, int icon, int color, boolean folderStarted) {
        TextView title = card.findViewWithTag("suggestion-title");
        TextView metadata = card.findViewWithTag("suggestion-metadata");
        FrameLayout picture = (FrameLayout) ((ViewGroup) card).getChildAt(0);
        HomeSuggestionImageView image = (HomeSuggestionImageView) picture.getChildAt(0);
        updateHomeSuggestionProgressBadge(picture, category, program, item, folderStarted);
        title.setText(program == null ? "Parcourir les " + homeCategoryTitle(category).toLowerCase(Locale.FRANCE)
                : homeCategoryHeroTitle(category, program));
        ArrayList<String> facts = new ArrayList<>();
        if (program != null) {
            String year = homeSuggestionMetadata(item), badge = homeSuggestionBadge(category, program, item);
            if (!year.isEmpty()) facts.add(year);
            if (!badge.isEmpty()) facts.add(badge);
        }
        metadata.setText(program == null ? "Ouvrir le dossier" : TextUtils.join(" · ", facts));
        metadata.setVisibility(metadata.length() == 0 ? View.GONE : View.VISIBLE);
        picture.setTag(color);
        card.setContentDescription(homeCategoryTitle(category) + " · " + title.getText() + " · " + metadata.getText());
        if (loadImage) {
            image.setImageDrawable(null);
            image.setTag("");
            image.setTag(HOME_HERO_PREVIEW_KEY_TAG, "");
            image.setTag(CATEGORY_VIDEO_METADATA_REQUEST_TAG, null);
            image.hasArtwork = false;
            image.landscapeFallback = null;
            image.setScaleType(ImageView.ScaleType.CENTER_INSIDE);
            image.setPadding(dp(18), dp(12), dp(18), dp(12));
            image.setImageResource(icon);
            image.setColorFilter(color);
            if (program != null) loadHomeSuggestionArtwork(image, category, program, item);
        }
        applyHomeSuggestionFocus(card, card.hasFocus());
    }

    private void updateHomeSuggestionProgressBadge(FrameLayout picture, String category, JojoProgram program,
                                                   JSONObject item, boolean folderStarted) {
        clearEpisodeStatusBadge(picture);
        if (program == null) return;
        boolean seriesFolder = "series".equals(category)
                || FREEBOX_FOLDER_SOURCE.equals(program.sourcePackage);
        boolean started = "series".equals(category)
                ? item != null && isSeriesItemInProgress(item, HomeWatchProgressBridge.currentProfileId(this))
                : seriesFolder ? folderStarted : isThumbnailInProgress(program);
        if (started) addInProgressBadge(picture, seriesFolder);
    }

    private void loadHomeSuggestionArtwork(HomeSuggestionImageView image, String category,
                                           JojoProgram program, JSONObject item) {
        if (!"external-playback".equals(program.sourcePackage) || item == null) {
            loadContinueWatchingHeroArtwork(image, program);
            return;
        }
        String selected = selectedExternalFavoriteHeroArtwork(item);
        if (selected.isEmpty()) selected = firstExternalValue(item, "backdrop", "backdrop_url", "backdropUrl");
        image.landscapeFallback = () -> loadHomeSuggestionExternalLandscape(image, category, program, item);
        if (ExternalPlaybackStore.supportedUrl(selected)) loadArtwork(image, selected);
        else {
            Runnable fallback = image.landscapeFallback;
            image.landscapeFallback = null;
            fallback.run();
        }
    }

    private void loadHomeSuggestionExternalLandscape(ImageView image, String category,
                                                      JojoProgram program, JSONObject item) {
        Object request = new Object();
        image.setTag(CATEGORY_VIDEO_METADATA_REQUEST_TAG, request);
        if (!selectedExternalFavoriteHeroArtwork(item).isEmpty()) return;
        String mediaType = "series".equals(category) ? "tv" : "movie";
        List<String> queries = externalInfoSearchTitles(item, item.optString("title", program.title),
                "series".equals(category));
        String yearValue = firstExternalValue(item, "year", "release_year", "releaseYear");
        java.util.regex.Matcher year = java.util.regex.Pattern.compile("(?:19|20)\\d{2}")
                .matcher(yearValue.isEmpty() ? program.title : yearValue);
        String yearHint = year.find() ? year.group() : "";
        int knownId = item.optInt("tmdbId", item.optInt("tmdb_id", 0));
        String identity = mediaType + "|" + knownId + "|" + TextUtils.join("|", queries) + "|" + yearHint;
        FolderMetadata metadata = folderHeroMetadataCache.get("info-fr-v3|" + identity);
        String cacheKey = "home_suggestion_landscape_v1|" + identity;
        String cached = metadata != null && ExternalPlaybackStore.supportedUrl(metadata.backdrop)
                ? metadata.backdrop : homePrefs().getString(cacheKey, "");
        if (ExternalPlaybackStore.supportedUrl(cached)) {
            loadArtwork(image, cached);
            return;
        }
        if (!homePrefs().getBoolean("tmdb_enabled", true) || TextUtils.isEmpty(BuildConfig.TMDB_API_KEY)) return;
        homeSuggestionArtworkExecutor.execute(() -> {
            try {
                if (isDestroyed() || image.getTag(CATEGORY_VIDEO_METADATA_REQUEST_TAG) != request) return;
                int id = knownId > 0 ? knownId : findExternalInfoTmdbId(queries, mediaType, yearHint);
                if (id <= 0 || isDestroyed() || image.getTag(CATEGORY_VIDEO_METADATA_REQUEST_TAG) != request) return;
                JSONObject details = fetchJson("https://api.themoviedb.org/3/" + mediaType + "/" + id
                        + "?api_key=" + java.net.URLEncoder.encode(BuildConfig.TMDB_API_KEY, "UTF-8")
                        + "&language=fr-FR");
                String path = details.optString("backdrop_path", "");
                if (!path.startsWith("/")) return;
                String url = "https://image.tmdb.org/t/p/w780" + path;
                homePrefs().edit().putString(cacheKey, url).apply();
                runOnUiThread(() -> {
                    if (!isDestroyed() && image.getTag(CATEGORY_VIDEO_METADATA_REQUEST_TAG) == request
                            && selectedExternalFavoriteHeroArtwork(item).isEmpty())
                        loadArtwork(image, url);
                });
            } catch (Exception ignored) { }
        });
    }

    private String homeSuggestionBadge(String category, JojoProgram program, JSONObject item) {
        if ("series".equals(category)) {
            int count = item == null ? 0 : providerSeriesSeasonCount(item);
            return count <= 0 ? "" : count + (count == 1 ? " saison" : " saisons");
        }
        if ("videos".equals(category)) {
            return formatHeroRuntime(HomeMediaRules.playbackRuntimeMinutes(program.duration));
        }
        return formatHeroRuntime(externalHeroRuntimeMinutes(item) > 0
                ? externalHeroRuntimeMinutes(item) : (int) Math.round(program.duration / 60_000d));
    }

    private String homeSuggestionMetadata(JSONObject item) {
        String year = firstExternalValue(item, "year", "release_year", "releaseYear").replaceAll("[^0-9]", "");
        if (year.length() >= 4) year = year.substring(0, 4);
        else year = "";
        return year;
    }

    private void openContinueWatchingProgram(JojoProgram program) {
        rememberHomeFocus();
        if (program != null && currentHomeResumesView instanceof ViewGroup) {
            String focusKey = resumeDismissKey(program);
            View hero = currentHomeResumesView.findViewWithTag(focusKey);
            if (hero != null && hero.isFocusable()) {
                lastHomeFocus = hero;
                lastHomeFocusKey = focusKey;
                pendingResumeFocusKey = focusKey;
            }
        }
        if (FREEBOX_FOLDER_SOURCE.equals(program.sourcePackage)) openSmbFolderHomeShortcut(program.intentUri);
        else if (FILE_VIDEO_RESUME_SOURCE.equals(program.sourcePackage)) openFileVideoResume(program);
        else if ("external-playback".equals(program.sourcePackage)) openExternalPlayback(externalResumeItem(program), false, false);
        else openJojoProgram(program);
    }

    private String externalPlaybackSynopsis(JSONObject item) {
        if (item == null) return "";
        for (String field : new String[]{"description", "descr", "overview", "synopsis", "plot", "desc"}) {
            String value = HomeMediaRules.mediaMetadataText(item.optString(field, ""));
            if (!value.isEmpty()) return value;
        }
        return "";
    }

    private JSONObject externalPlaybackHeroFavorite(JSONObject item) {
        if (item == null) return new JSONObject();
        String seriesId = item.optString("stalkerSeriesId");
        String favoriteId = ExternalPlaybackStore.favoriteId(item.optString("stalkerSource"),
                seriesId.isEmpty() ? item.optString("category") : "series",
                seriesId.isEmpty() ? item.optString("stalkerId") : seriesId);
        return favoriteId.isEmpty() ? new JSONObject() : ExternalPlaybackStore.get(this, favoriteId);
    }

    /**
     * The Séries folder works from the complete local series list. A resumed
     * episode can have a different provider id from that list, so select the
     * matching local record with the richest editorial metadata instead of
     * assuming the favorite id is identical.
     */
    private JSONObject externalPlaybackSeriesEditorial(JSONObject episode) {
        if (episode == null) return new JSONObject();
        String source = episode.optString("stalkerSource", "").trim();
        String seriesId = episode.optString("stalkerSeriesId", "").trim();
        String expectedTitle = normalizeTmdbArtworkText(episode.optString("providerTitle",
                episode.optString("title", ""))
                .replaceFirst("(?i)\\s*(?:s\\s*\\d{1,2}\\s*e\\s*\\d{1,3}|\\d{1,2}\\s*x\\s*\\d{1,3}).*$", ""));
        JSONObject best = new JSONObject();
        int bestScore = -1;
        // The Home worker already validates the full store; binding must stay on cached data.
        for (JSONObject candidate : homeCategoryFavoriteSnapshots.getOrDefault("series", Collections.emptyList())) {
            if (candidate == null) continue;
            String candidateSource = candidate.optString("stalkerSource", "").trim();
            if (!source.isEmpty() && !candidateSource.isEmpty() && !source.equals(candidateSource)) continue;
            String candidateId = candidate.optString("stalkerId", "").trim();
            String candidateTitle = normalizeTmdbArtworkText(candidate.optString("providerTitle",
                    candidate.optString("title", "")));
            boolean sameId = !seriesId.isEmpty() && seriesId.equals(candidateId);
            boolean sameTitle = !expectedTitle.isEmpty() && expectedTitle.equals(candidateTitle);
            if (!sameId && !sameTitle) continue;
            int score = sameId ? 20 : 10;
            String candidateSynopsis = externalPlaybackSynopsis(candidate);
            if (!candidateSynopsis.isEmpty()
                    && !candidateSynopsis.matches("(?i)^(?:n/?a|null|unknown|indisponible)[.!]?$")) score += 8;
            if (!heroGenres(candidate).isEmpty()) score += 4;
            if (externalHeroRuntimeMinutes(candidate) > 0) score += 2;
            if (score > bestScore) {
                best = candidate;
                bestScore = score;
            }
        }
        if (best.has("id")) return best;
        return externalPlaybackHeroFavorite(episode);
    }

    /**
     * Use the same enriched/favorite fiche as the folder Hero. The resume
     * record contributes only playback state and any provider fields missing
     * from that editorial fiche.
     */
    private JSONObject homeHeroEditorialSource(JSONObject playback, boolean seriesResume) {
        JSONObject editorial = seriesResume
                ? externalPlaybackSeriesEditorial(playback)
                : externalPlaybackHeroFavorite(playback);
        if (editorial == null || !editorial.has("id")) return playback;
        try {
            JSONObject merged = new JSONObject(editorial.toString());
            java.util.Iterator<String> keys = playback.keys();
            while (keys.hasNext()) {
                String key = keys.next();
                if (!merged.has(key) || merged.optString(key, "").trim().isEmpty()) {
                    merged.put(key, playback.get(key));
                }
            }
            for (String key : new String[]{"position", "started", "season", "episode"}) {
                if (playback.has(key)) merged.put(key, playback.get(key));
            }
            return merged;
        } catch (Exception ignored) {
            return editorial;
        }
    }

    private String externalPlaybackHeroSynopsis(JSONObject item) {
        String synopsis = externalPlaybackSynopsis(item);
        if (synopsis.isEmpty()) synopsis = externalPlaybackSynopsis(externalPlaybackHeroFavorite(item));
        if (synopsis.isEmpty()) synopsis = externalPlaybackSeriesSynopsis(item);
        return synopsis;
    }

    /**
     * Episode resume records can lose their provider series link when they are
     * copied into Watch Next.  In that case recover the synopsis from the
     * already imported series favorite, which is the same source used by the
     * Séries detail page.
     */
    private String externalPlaybackSeriesSynopsis(JSONObject episode) {
        if (episode == null) return "";
        String source = episode.optString("stalkerSource", "").trim();
        String seriesId = episode.optString("stalkerSeriesId", "").trim();
        String episodeTitle = episode.optString("providerTitle", episode.optString("title", ""));
        String expectedTitle = normalizeTmdbArtworkText(episodeTitle
                .replaceFirst("(?i)\\s*(?:s\\s*\\d{1,2}\\s*e\\s*\\d{1,3}|\\d{1,2}\\s*x\\s*\\d{1,3}).*$", ""));
        for (JSONObject series : homeCategoryFavoriteSnapshots.getOrDefault("series", Collections.emptyList())) {
            if (series == null) continue;
            String candidateSource = series.optString("stalkerSource", "").trim();
            String candidateId = series.optString("stalkerId", "").trim();
            boolean sameProviderId = !seriesId.isEmpty() && seriesId.equals(candidateId)
                    && (source.isEmpty() || source.equals(candidateSource));
            String candidateTitle = normalizeTmdbArtworkText(series.optString("providerTitle",
                    series.optString("title", "")));
            boolean sameTitle = !expectedTitle.isEmpty() && expectedTitle.equals(candidateTitle)
                    && (source.isEmpty() || candidateSource.isEmpty() || source.equals(candidateSource));
            if (sameProviderId || sameTitle) {
                String synopsis = externalPlaybackSynopsis(series);
                if (!synopsis.isEmpty()) return synopsis;
            }
        }
        return "";
    }

    private String externalPlaybackArtwork(JSONObject item) {
        if (item == null) return "";
        for (String field : new String[]{"artwork", "backdrop", "backdrop_url", "backdropUrl", "poster",
                "poster_url", "posterUrl", "screenshot_uri", "pic", "cover", "cover_url", "image", "image_url"}) {
            String value = item.optString(field, "").trim();
            if (ExternalPlaybackStore.supportedUrl(value)) return value;
        }
        return "";
    }

    private String cleanHeroSynopsis(String value, JojoProgram program) {
        value = HomeMediaRules.mediaMetadataText(value);
        if (value.isEmpty()) return "";
        String synopsis = SystemContinueWatching.publishedResumeSynopsis(
                program == null ? null : program.sourcePackage, value)
                .replaceFirst("(?i)^profil\\s+\\d+\\s*[·|:-]\\s*", "").trim();
        if (synopsis.matches("(?i)^profil\\s+\\d+$")
                || synopsis.matches("(?i)^s\\d{1,2}e\\d{1,3}(?:\\s*[·|:-].*)?$")
                || synopsis.matches("(?i)^(?:n/?a|null|unknown|indisponible)[.!]?$")) return "";
        String title = program == null || program.title == null ? "" : program.title.trim();
        return !title.isEmpty() && normalizeTmdbArtworkText(title).equals(normalizeTmdbArtworkText(synopsis)) ? "" : synopsis;
    }

    private String continueWatchingHeroSynopsis(JojoProgram program) {
        if (program == null) return "";
        String synopsis = cleanHeroSynopsis(program.description, program);
        if (synopsis.isEmpty() && FILE_VIDEO_RESUME_SOURCE.equals(program.sourcePackage)) {
            synopsis = cleanHeroSynopsis(smbFolderSynopsis(program.intentUri), program);
        }
        if (synopsis.isEmpty() && isExternalPlaybackResumeSource(program.sourcePackage)) {
            synopsis = cleanHeroSynopsis(externalPlaybackHeroSynopsis(
                    externalResumeItem(program)), program);
        }
        // Some previously cached cards predate the dedicated external source
        // label. Their content ID still points at the authoritative playback
        // record, so recover its synopsis before any TMDB fallback.
        if (synopsis.isEmpty() && program.intentUri != null && !program.intentUri.isEmpty()) {
            JSONObject stored = externalResumeItem(program);
            if (stored.has("id")) synopsis = cleanHeroSynopsis(externalPlaybackHeroSynopsis(stored), program);
        }
        if (!synopsis.isEmpty()) return synopsis;
        return homePrefs().getString("resume_synopsis_"
                + Integer.toUnsignedString(resumeDismissKey(program).hashCode(), 16), "").trim();
    }

    private String shortenContinueWatchingHeroSynopsis(String value) {
        if (value == null) return "";
        String synopsis = value.trim().replaceAll("\\s+", " ");
        if (synopsis.length() <= 480) return synopsis;
        int sentenceEnd = -1;
        for (int index = 80; index < Math.min(480, synopsis.length()); index++) {
            char character = synopsis.charAt(index);
            if (character == '.' || character == '!' || character == '?') {
                sentenceEnd = index + 1;
                break;
            }
        }
        if (sentenceEnd > 0) return synopsis.substring(0, sentenceEnd).trim();
        int cut = synopsis.substring(0, 480).lastIndexOf(' ');
        return synopsis.substring(0, cut > 0 ? cut : 480).trim() + "…";
    }

    private String heroMediumSynopsis(JSONObject item) {
        return firstExternalValue(item, "mediumSynopsis", "synopsisMedium", "synopsis_medium",
                "mediumDescription", "descriptionMedium", "description_medium");
    }

    private String heroShortSynopsis(JSONObject item) {
        return firstExternalValue(item, "shortSynopsis", "short_synopsis",
                "synopsisShort", "synopsis_short", "shortDescription", "short_description",
                "descriptionShort", "description_short", "shortOverview", "short_overview",
                "overviewShort", "overview_short", "shortPlot", "short_plot",
                "plotShort", "plot_short");
    }

    private String shorterHeroSynopsis(String current) {
        String text = current.trim().replaceAll("\\s+", " ");
        if (text.length() <= 80) return text;
        int limit = Math.max(80, Math.min(280, Math.round(text.length() * .75f)));
        int sentenceEnd = -1;
        for (int index = 80; index < limit; index++) {
            char character = text.charAt(index);
            if (character == '.' || character == '!' || character == '?') sentenceEnd = index + 1;
        }
        if (sentenceEnd > 0) return text.substring(0, sentenceEnd).trim();
        int wordEnd = text.lastIndexOf(' ', limit);
        return text.substring(0, wordEnd > 80 ? wordEnd : limit).trim() + "…";
    }

    private void keepHomeHeroSynopsisAbovePlayback(LinearLayout content, TextView synopsis,
                                                   View flexibleSpacer) {
        Runnable resize = () -> resizeHomeHeroSynopsis(content, synopsis, flexibleSpacer);
        View.OnLayoutChangeListener resizeSynopsis = (view, left, top, right, bottom,
                oldLeft, oldTop, oldRight, oldBottom) -> {
                    content.removeCallbacks(resize);
                    content.post(resize);
                };
        content.addOnLayoutChangeListener(resizeSynopsis);
        flexibleSpacer.addOnLayoutChangeListener(resizeSynopsis);
    }

    private void resizeHomeHeroSynopsis(LinearLayout content, TextView synopsis,
                                       View flexibleSpacer) {
        if (!content.isAttachedToWindow() || content.getHeight() <= 0) return;
        int availableHeight = content.getHeight() - content.getPaddingTop()
                - content.getPaddingBottom();
        for (int index = 0; index < content.getChildCount(); index++) {
            View child = content.getChildAt(index);
            if (child == synopsis || child == flexibleSpacer
                    || child.getVisibility() == View.GONE) continue;
            ViewGroup.LayoutParams rawParams = child.getLayoutParams();
            if (!(rawParams instanceof LinearLayout.LayoutParams)) continue;
            LinearLayout.LayoutParams params = (LinearLayout.LayoutParams) rawParams;
            // A negative action margin raises the controls visually; don't
            // spend that overlap allowance on synopsis height.
            availableHeight -= child.getMeasuredHeight()
                    + Math.max(0, params.topMargin) + Math.max(0, params.bottomMargin);
        }
        LinearLayout.LayoutParams synopsisParams =
                (LinearLayout.LayoutParams) synopsis.getLayoutParams();
        availableHeight -= Math.max(0, synopsisParams.topMargin)
                + Math.max(0, synopsisParams.bottomMargin);
        int lineHeight = Math.max(1, synopsis.getLineHeight());
        int maxLines = Math.max(1, Math.min(9, availableHeight / lineHeight));
        int targetHeight = maxLines * lineHeight;
        if (synopsisParams.height != targetHeight || synopsis.getMaxLines() != maxLines) {
            synopsisParams.height = targetHeight;
            synopsis.setMaxLines(maxLines);
            synopsis.setLayoutParams(synopsisParams);
        }
    }

    private void useMediumSynopsisWhenClipped(TextView view, String preferredMedium) {
        view.getViewTreeObserver().addOnPreDrawListener(() -> {
            android.text.Layout layout = view.getLayout();
            if (layout == null || layout.getLineCount() == 0) return true;
            int lastLine = layout.getLineCount() - 1;
            if (layout.getEllipsisCount(lastLine) == 0
                    && layout.getLineBottom(lastLine) <= view.getHeight()) return true;
            String current = view.getText().toString();
            String medium = preferredMedium == null ? "" : preferredMedium.trim();
            String replacement = !medium.isEmpty() && medium.length() < current.length()
                    ? medium : shorterHeroSynopsis(current);
            if (replacement.length() >= current.length() || replacement.equals(current)) return true;
            view.setText(replacement);
            return false; // measure the shorter synopsis before drawing
        });
    }

    private void loadContinueWatchingHeroSynopsis(TextView synopsisView, JojoProgram program) {
        if (synopsisView == null || program == null || !TextUtils.isEmpty(synopsisView.getText())) return;
        final String resumeKey = resumeDismissKey(program);
        final String requestKey = "synopsis|" + resumeKey;
        synopsisView.setTag(requestKey);
        if (!resumeSynopsisEnrichmentInFlight.add(requestKey)) return;

        if (isExternalPlaybackResumeSource(program.sourcePackage)) {
            TiviMateFavoriteImporter.enrichPlaybackMetadata(this, program.intentUri, () -> {
                String value = preferredHomeHeroSynopsis(
                        externalResumeItem(program), program);
                runOnUiThread(() -> {
                    resumeSynopsisEnrichmentInFlight.remove(requestKey);
                    if (!value.isEmpty() && synopsisView.isAttachedToWindow()
                            && requestKey.equals(synopsisView.getTag())) {
                        synopsisView.setText(shortenContinueWatchingHeroSynopsis(value));
                    }
                });
            });
            return;
        }

        if (!FILE_VIDEO_RESUME_SOURCE.equals(program.sourcePackage) && !isJojoPackage(program.sourcePackage)) {
            resumeSynopsisEnrichmentInFlight.remove(requestKey);
            return;
        }
        new Thread(() -> {
            String value = "";
            try {
                String lookupTitle = FILE_VIDEO_RESUME_SOURCE.equals(program.sourcePackage)
                        ? videoArtworkSearchTitle(program.title, null) : program.title;
                value = findStrictTmdbSynopsis(lookupTitle);
                if (!value.isEmpty()) homePrefs().edit().putString("resume_synopsis_"
                        + Integer.toUnsignedString(resumeKey.hashCode(), 16), value).apply();
            } catch (Exception ignored) { }
            final String resolved = value;
            runOnUiThread(() -> {
                resumeSynopsisEnrichmentInFlight.remove(requestKey);
                if (!resolved.isEmpty() && synopsisView.isAttachedToWindow()
                        && requestKey.equals(synopsisView.getTag())) {
                    synopsisView.setText(shortenContinueWatchingHeroSynopsis(resolved));
                }
            });
        }, "JojoHomeHeroSynopsis").start();
    }

    private boolean isExternalPlaybackResumeSource(String source) {
        return "external-playback".equals(source)
                || "external-playback-series-episode".equals(source);
    }

    private String findStrictTmdbSynopsis(String rawTitle) throws Exception {
        if (rawTitle == null || rawTitle.trim().isEmpty() || BuildConfig.TMDB_API_KEY == null
                || BuildConfig.TMDB_API_KEY.trim().isEmpty()) return "";
        String query = displayVideoTitle(rawTitle).replace('_', ' ')
                .replaceFirst("(?i)^\\s*\\d{1,3}(?:h\\d{0,2}|min)\\s+", "")
                .replaceAll("\\s+", " ").trim();
        String expected = normalizeTmdbArtworkText(query);
        if (expected.isEmpty()) return "";
        java.util.regex.Matcher yearMatcher = java.util.regex.Pattern.compile("(?:19|20)\\d{2}").matcher(rawTitle);
        String expectedYear = yearMatcher.find() ? yearMatcher.group() : "";
        for (String language : new String[]{"fr-FR", "en-US"}) {
            String endpoint = "https://api.themoviedb.org/3/search/multi?api_key="
                    + java.net.URLEncoder.encode(BuildConfig.TMDB_API_KEY, "UTF-8")
                    + "&language=" + language + "&include_adult=false&page=1&query="
                    + java.net.URLEncoder.encode(query, "UTF-8");
            JSONArray results = fetchJson(endpoint).optJSONArray("results");
            if (results == null) continue;
            LinkedHashMap<String, JSONObject> exact = new LinkedHashMap<>();
            for (int index = 0; index < results.length(); index++) {
                JSONObject candidate = results.optJSONObject(index);
                if (candidate == null) continue;
                String type = candidate.optString("media_type", "");
                if (!("movie".equals(type) || "tv".equals(type))) continue;
                String candidateTitle = candidate.optString("title", candidate.optString("name", ""));
                String originalTitle = candidate.optString("original_title", candidate.optString("original_name", ""));
                if (!expected.equals(normalizeTmdbArtworkText(candidateTitle))
                        && !expected.equals(normalizeTmdbArtworkText(originalTitle))) continue;
                String date = candidate.optString("release_date", candidate.optString("first_air_date", ""));
                if (!expectedYear.isEmpty() && date.length() >= 4 && !expectedYear.equals(date.substring(0, 4))) continue;
                exact.put(type + "|" + candidate.optInt("id"), candidate);
            }
            // A title-only ambiguity is deliberately rejected: a missing
            // synopsis is preferable to the description of another programme.
            if (exact.size() != 1) continue;
            String overview = exact.values().iterator().next().optString("overview", "").trim();
            if (!overview.isEmpty()) return overview;
        }
        return "";
    }

    private void loadContinueWatchingHeroArtwork(ImageView artwork, JojoProgram program) {
        loadContinueWatchingHeroArtwork(artwork, program, false);
    }

    private void loadContinueWatchingHeroArtwork(ImageView artwork, JojoProgram program,
            boolean editorialNetflix) {
        homeVideosFileHeroArtworkViews.remove(artwork);
        boolean netflixResume = editorialNetflix
                && "netflix".equals(SystemContinueWatching.sharedResumeProvider(program.sourcePackage));
        if (netflixResume) artwork.setImageDrawable(null);
        showHomeHeroPreview(artwork, program, netflixResume);
        boolean externalLogo = isExternalLiveProgram(program);
        String resumeArtwork = "";
        if (FILE_VIDEO_RESUME_SOURCE.equals(program.sourcePackage)) {
            homeVideosFileHeroArtworkViews.put(artwork, program.intentUri);
            resumeArtwork = homeVideosFileHeroArtwork(program.intentUri, program.title);
        }
        if (FREEBOX_FOLDER_SOURCE.equals(program.sourcePackage)) {
            resumeArtwork = smbFolderHeroArtwork(program.intentUri);
        } else if (resumeArtwork.isEmpty() && !FILE_VIDEO_RESUME_SOURCE.equals(program.sourcePackage)
                && !"external-playback".equals(program.sourcePackage)) {
            resumeArtwork = homePrefs().getString(
                    "resume_artwork_" + Integer.toUnsignedString(resumeDismissKey(program).hashCode(), 16), "");
        }
        if (!resumeArtwork.isEmpty()) loadArtwork(artwork, resumeArtwork);
        else if (netflixResume) {
            // The metadata request supplies a clean backdrop; never load the notification composite.
            return;
        } else if (isJojoPackage(program.sourcePackage)) {
            if (program.artwork != null && !program.artwork.isEmpty()) loadArtwork(artwork, program.artwork);
            loadResumeTmdbArtwork(artwork, program);
        } else if ("external-playback".equals(program.sourcePackage)) {
            JSONObject item = externalResumeItem(program);
            if (!externalLogo) {
                loadExternalHeroLandscapeArtwork(artwork, program, item);
                return;
            }
            String providerArtwork = liveChannelArtwork(item, true);
            if (!ExternalPlaybackStore.supportedUrl(providerArtwork)
                    && ExternalPlaybackStore.supportedUrl(program.artwork)) providerArtwork = program.artwork;
            String cached = homePrefs().getString(liveChannelLogoCacheKey(program.intentUri, true), "");
            if (!providerArtwork.isEmpty()) loadArtwork(artwork, providerArtwork);
            else {
                if (!cached.isEmpty()) loadArtwork(artwork, cached);
                loadExternalResumeArtwork(artwork, program, true);
            }
        } else if (!FILE_VIDEO_RESUME_SOURCE.equals(program.sourcePackage)
                && !FREEBOX_FOLDER_SOURCE.equals(program.sourcePackage)
                && program.artwork != null && !program.artwork.isEmpty()) {
            loadArtwork(artwork, program.artwork, isSmartTubePackage(program.sourcePackage));
        } else if (FREEBOX_FOLDER_SOURCE.equals(program.sourcePackage)) {
            loadFreeboxFolderVideoArtwork(artwork, program.title, program.intentUri, false);
        } else if (FILE_VIDEO_RESUME_SOURCE.equals(program.sourcePackage)) {
            VideoFrameSource frameSource = null;
            try { frameSource = resumeVideoFrameSourceForProgram(program); } catch (Exception ignored) { }
            loadVideoArtwork(artwork, program.title, true, program.intentUri, frameSource, true);
        } else if (isSmartTubePackage(program.sourcePackage) || isTiviMatePackage(program.sourcePackage)) {
            loadResumeSourceArtwork(artwork, program.sourcePackage);
        }
    }

    private void showHomeHeroPreview(ImageView artwork, JojoProgram program, boolean editorialNetflix) {
        String prefix = editorialNetflix ? "home-hero-netflix-editorial-v1:" : "home-hero-preview-v2-sharp:";
        String key = prefix + HomeWatchProgressBridge.currentProfileId(this)
                + ":" + resumeDismissKey(program);
        artwork.setTag(HOME_HERO_PREVIEW_KEY_TAG, key);
        if (artwork.getDrawable() != null) return;
        Bitmap preview;
        synchronized (artworkBitmapCache) { preview = artworkBitmapCache.get(key); }
        if (preview != null) {
            artwork.setImageBitmap(preview);
            return;
        }
        File file = homeHeroPreviewFile(key);
        if (!file.isFile()) return;
        // Restore the sharp local copy independently of queued artwork loads.
        // Large disk decodes must never delay the first layout or the D-pad.
        new Thread(() -> {
            Bitmap decoded = decodeArtworkFile(file, HOME_HERO_PREVIEW_MAX_DIMENSION);
            if (decoded == null) return;
            final Bitmap ready;
            synchronized (artworkBitmapCache) {
                Bitmap current = artworkBitmapCache.get(key);
                ready = current == null ? decoded : current;
                if (current == null) artworkBitmapCache.put(key, decoded);
            }
            runOnUiThread(() -> {
                if (!isDestroyed() && key.equals(artwork.getTag(HOME_HERO_PREVIEW_KEY_TAG))
                        && artwork.getDrawable() == null) artwork.setImageBitmap(ready);
            });
        }, "JojoHomeHeroPreviewRead").start();
    }

    private File homeHeroPreviewFile(String key) {
        return new File(getCacheDir(), "home_hero_preview_"
                + Integer.toUnsignedString(key.hashCode(), 16) + ".png");
    }

    private void cacheHomeHeroPreview(ImageView image, Bitmap bitmap) {
        Object tag = image.getTag(HOME_HERO_PREVIEW_KEY_TAG);
        if (!(tag instanceof String)) return;
        String key = (String) tag;
        synchronized (artworkBitmapCache) {
            if (artworkBitmapCache.get(key) == bitmap) return;
            artworkBitmapCache.put(key, bitmap);
        }
        new Thread(() -> {
            synchronized (homeHeroPreviewWriteLock) {
                synchronized (artworkBitmapCache) {
                    if (artworkBitmapCache.get(key) != bitmap) return;
                }
                Bitmap preview = bitmap;
                try {
                    int largest = Math.max(bitmap.getWidth(), bitmap.getHeight());
                    if (largest > HOME_HERO_PREVIEW_MAX_DIMENSION) {
                        float scale = HOME_HERO_PREVIEW_MAX_DIMENSION / (float) largest;
                        // The full bitmap is still displayed and shared by
                        // other views: do not recycle it while scaling.
                        preview = Bitmap.createScaledBitmap(bitmap,
                                Math.max(1, Math.round(bitmap.getWidth() * scale)),
                                Math.max(1, Math.round(bitmap.getHeight() * scale)), true);
                    }
                    synchronized (artworkBitmapCache) {
                        if (artworkBitmapCache.get(key) != bitmap) return;
                    }
                    File file = homeHeroPreviewFile(key);
                    File pending = new File(file.getPath() + ".tmp");
                    try (java.io.FileOutputStream output = new java.io.FileOutputStream(pending)) {
                        preview.compress(Bitmap.CompressFormat.PNG, 90, output);
                    }
                    pending.renameTo(file);
                } catch (Exception ignored) { }
                // Keep the full bitmap in memory; only the disk copy is scaled.
            }
        }, "JojoHomeHeroPreview").start();
    }

    private void loadExternalHeroLandscapeArtwork(ImageView image, JojoProgram program,
                                                   JSONObject item) {
        boolean series = "series".equals(item.optString("category")) || program.seasonNumber != null;
        JSONObject editorial = homeHeroEditorialSource(item, series);
        String category = series ? "series" : "movies";
        // Resolve from the folder fiche, not the playback poster or a separate title search.
        loadHomeCategoryHeroArtwork(image, category, program, editorial);
        if (selectedExternalFavoriteHeroArtwork(editorial).isEmpty())
            loadHomeSuggestionExternalLandscape(image, category, program, editorial);
    }

