    private void updateContinueWatchingHeroDots(LinearLayout dots, int selectedIndex, boolean focused) {
        if (dots == null) return;
        boolean refined = homeHeroChoice() != 0;
        for (int index = 0; index < dots.getChildCount(); index++) {
            View dot = dots.getChildAt(index);
            boolean active = index == selectedIndex;
            dot.setBackground(homeContinueWatchingHeroDot(active));
            ViewGroup.LayoutParams params = dot.getLayoutParams();
            params.width = dp(refined ? active ? (focused ? 28 : 24) : 6 : active ? (focused ? 48 : 40) : 12);
            params.height = dp(refined ? active ? (focused ? 6 : 4) : 6 : active ? (focused ? 8 : 6) : 12);
            dot.setLayoutParams(params);
        }
        if (dots.getParent() instanceof android.widget.HorizontalScrollView
                && selectedIndex >= 0 && selectedIndex < dots.getChildCount()) {
            View activeDot = dots.getChildAt(selectedIndex);
            dots.post(() -> {
                if (activeDot.getParent() != dots || activeDot.getWidth() <= 0) return;
                android.graphics.Rect activeBounds = new android.graphics.Rect(
                        Math.max(0, activeDot.getLeft() - dp(8)), activeDot.getTop(),
                        activeDot.getRight() + dp(8), activeDot.getBottom());
                dots.requestRectangleOnScreen(activeBounds, false);
            });
        }
    }

    private GradientDrawable continueWatchingHeroDot(boolean active) {
        GradientDrawable dot = new GradientDrawable();
        dot.setShape(GradientDrawable.OVAL);
        dot.setColor(active ? Color.WHITE : Color.argb(115, 255, 255, 255));
        return dot;
    }

    private GradientDrawable homeContinueWatchingHeroDot(boolean active) {
        GradientDrawable dot = new GradientDrawable();
        dot.setShape(active ? GradientDrawable.RECTANGLE : GradientDrawable.OVAL);
        if (active) dot.setCornerRadius(dp(4));
        dot.setColor(active ? folderButtonThemeColor() : Color.argb(115, 255, 255, 255));
        return dot;
    }
