    private View createIndexedMediaBrowser() {
        LinearLayout page = pickerPage("Stockage local et USB", "Images et vidéos détectées sur la TV ou une clé USB");
        LinearLayout content = (LinearLayout) page.getTag(); TextView capacity = text(localStorageSummary(), 15, muted); capacity.setPadding(0, 0, 0, dp(14)); content.addView(capacity); ScrollView scroll = new ScrollView(this); LinearLayout list = new LinearLayout(this); list.setOrientation(LinearLayout.VERTICAL); scroll.addView(list); content.addView(scroll, new LinearLayout.LayoutParams(-1, 0, 1f));
        new Thread(() -> { List<MediaFile> files = loadMediaFiles(); runOnUiThread(() -> { if (files.isEmpty()) list.addView(empty("Aucune image ou vidéo détectée. Insérez une clé USB ou copiez un média sur la TV.")); else for (MediaFile file : files) list.addView(mediaRow(file), new LinearLayout.LayoutParams(dp(760), dp(64))); list.post(() -> focusFirst(list)); }); }).start();
        return page;
    }
