    private void applyPhotoThumbnail(ImageView icon, Bitmap bitmap) { if (bitmap == null) return; runOnUiThread(() -> { icon.setPadding(0, 0, 0, 0); icon.setScaleType(ImageView.ScaleType.CENTER_CROP); icon.setImageBitmap(bitmap); }); }
    private void loadLocalThumbnail(ImageView icon, File file) {
        String key = localPhotoKey(file);
        icon.setTag(R.id.smb_photo_file_tag, new LocalPhotoSource(file, key));
        Bitmap cached = smbPhotoBitmapCache.get(key + "|" + PHOTO_PREVIEW_MAX_DIMENSION);
        if (cached != null) showSmbPhotoThumbnail(icon, cached);
    }
    private void requestLocalPhotoThumbnail(ImageView icon, LocalPhotoSource source) {
        if ("loading".equals(icon.getTag(R.id.smb_photo_thumbnail_status))) return;
        icon.setTag(R.id.smb_photo_thumbnail_status, "loading");
        try {
            smbPhotoThumbnailExecutor.execute(() -> {
                Bitmap loaded = null;
                try {
                    if (!isDestroyed() && source.visible) loaded = loadLocalPhotoBitmap(source.file, PHOTO_PREVIEW_MAX_DIMENSION);
                } catch (Exception | OutOfMemoryError ignored) { }
                final Bitmap bitmap = loaded;
                runOnUiThread(() -> {
                    if (icon.getTag(R.id.smb_photo_file_tag) != source) return;
                    if (!icon.isAttachedToWindow() || !source.visible) icon.setTag(R.id.smb_photo_thumbnail_status, null);
                    else if (bitmap != null) showSmbPhotoThumbnail(icon, bitmap);
                    else icon.setTag(R.id.smb_photo_thumbnail_status, "failed");
                });
            });
        } catch (java.util.concurrent.RejectedExecutionException ignored) { icon.setTag(R.id.smb_photo_thumbnail_status, null); }
    }
    private void loadVisibleSmbPhotoThumbnails(View root) {
        loadVisibleSmbPhotoThumbnails(root, smbPhotoBitmapCache.snapshot(), true);
    }
    private void loadVisibleSmbPhotoThumbnails(View root, java.util.Map<String, Bitmap> cachedPhotos, boolean attached) {
        if (root == null) return;
        if (root instanceof ImageView) {
            ImageView icon = (ImageView) root;
            Object taggedFile = icon.getTag(R.id.smb_photo_file_tag);
            if (taggedFile instanceof LocalPhotoSource) {
                LocalPhotoSource source = (LocalPhotoSource) taggedFile;
                boolean wasVisible = source.visible;
                source.visible = attached && icon.isAttachedToWindow() && icon.getGlobalVisibleRect(new android.graphics.Rect());
                Object status = icon.getTag(R.id.smb_photo_thumbnail_status);
                if (source.visible && !wasVisible && "failed".equals(status)) {
                    icon.setTag(R.id.smb_photo_thumbnail_status, null);
                    status = null;
                }
                if (source.visible && !"loading".equals(status) && !"loaded".equals(status) && !"failed".equals(status))
                    requestLocalPhotoThumbnail(icon, source);
                else if (!source.visible && "loaded".equals(status)
                        && !cachedPhotos.containsKey(source.key + "|" + PHOTO_PREVIEW_MAX_DIMENSION)) {
                    icon.setImageResource(R.drawable.ic_file_image);
                    icon.setTag(R.id.smb_photo_thumbnail_status, null);
                }
                return;
            }
            if (!(taggedFile instanceof SmbPhotoSource)) return;
            SmbPhotoSource source = (SmbPhotoSource) taggedFile;
            boolean wasVisible = source.visible;
            source.visible = attached && icon.isAttachedToWindow() && icon.getGlobalVisibleRect(new android.graphics.Rect());
            Object status = icon.getTag(R.id.smb_photo_thumbnail_status);
            if (source.visible && !wasVisible && "failed".equals(status)) {
                icon.setTag(R.id.smb_photo_thumbnail_status, null);
                status = null;
            }
            if (source.visible) {
                if (!"loading".equals(status) && !"loaded".equals(status) && !"failed".equals(status))
                    loadSmbThumbnail(icon, source);
            } else if ("loaded".equals(status)
                    && !cachedPhotos.containsKey(smbPhotoBitmapKey(source, PHOTO_PREVIEW_MAX_DIMENSION))) {
                // Keep warm thumbnails while scrolling. Release only evicted previews;
                // their disk cache will restore them when they become visible again.
                icon.setImageResource(R.drawable.ic_file_image);
                icon.setTag(R.id.smb_photo_thumbnail_status, null);
            }
            return;
        }
        if (root instanceof android.view.ViewGroup) {
            android.view.ViewGroup group = (android.view.ViewGroup) root;
            for (int index = 0; index < group.getChildCount(); index++)
                loadVisibleSmbPhotoThumbnails(group.getChildAt(index), cachedPhotos, attached);
        }
    }
    private Runnable observeSmbPhotoThumbnails(ScrollView scroll, android.view.ViewGroup list) {
        final boolean[] pending = { false };
        android.view.ViewTreeObserver.OnPreDrawListener ready = new android.view.ViewTreeObserver.OnPreDrawListener() {
            @Override public boolean onPreDraw() {
                android.view.ViewTreeObserver observer = list.getViewTreeObserver();
                if (observer.isAlive()) observer.removeOnPreDrawListener(this);
                pending[0] = false;
                loadVisibleSmbPhotoThumbnails(list);
                return true;
            }
        };
        Runnable update = () -> {
            if (!list.isAttachedToWindow() || pending[0]) return;
            pending[0] = true;
            list.getViewTreeObserver().addOnPreDrawListener(ready);
            list.postInvalidateOnAnimation();
        };
        list.addOnAttachStateChangeListener(new View.OnAttachStateChangeListener() {
            @Override public void onViewAttachedToWindow(View view) { update.run(); }
            @Override public void onViewDetachedFromWindow(View view) {
                android.view.ViewTreeObserver observer = list.getViewTreeObserver();
                if (observer.isAlive()) observer.removeOnPreDrawListener(ready);
                pending[0] = false;
                loadVisibleSmbPhotoThumbnails(list, java.util.Collections.emptyMap(), false);
            }
        });
        scroll.setOnScrollChangeListener((view, scrollX, scrollY, oldScrollX, oldScrollY) -> update.run());
        return update;
    }
    private void cancelSmbPhotoThumbnail(ImageView icon, SmbPhotoSource source) {
        runOnUiThread(() -> {
            if (icon.getTag(R.id.smb_photo_file_tag) != source) return;
            icon.setTag(R.id.smb_photo_thumbnail_status, null);
            if (!isFinishing() && !isDestroyed() && icon.isAttachedToWindow())
                loadVisibleSmbPhotoThumbnails(icon);
        });
    }
    private void deliverSmbPhotoThumbnail(ImageView icon, SmbPhotoSource source, Bitmap bitmap) {
        runOnUiThread(() -> {
            if (icon.getTag(R.id.smb_photo_file_tag) != source) return;
            if (isFinishing() || isDestroyed() || !icon.isAttachedToWindow()) {
                icon.setTag(R.id.smb_photo_thumbnail_status, null);
            } else if (bitmap == null) icon.setTag(R.id.smb_photo_thumbnail_status, "failed");
            else showSmbPhotoThumbnail(icon, bitmap);
        });
    }
    private void loadSmbThumbnail(ImageView icon, SmbPhotoSource source) {
        Bitmap cached = cachedSmbPhotoBitmap(source, PHOTO_PREVIEW_MAX_DIMENSION);
        if (cached != null) { showSmbPhotoThumbnail(icon, cached); return; }
        if ("loading".equals(icon.getTag(R.id.smb_photo_thumbnail_status))) return;
        icon.setTag(R.id.smb_photo_thumbnail_status, "loading");
        try {
            // Local cached previews must never wait behind an uncached NAS decode.
            cachedArtworkLoadExecutor.execute(() -> {
                try {
                    Bitmap disk = readSmbPhotoCache(source, PHOTO_PREVIEW_MAX_DIMENSION);
                    if (disk != null) { deliverSmbPhotoThumbnail(icon, source, disk); return; }
                    smbPhotoThumbnailExecutor.execute(() -> {
                        boolean acquired = false;
                        try {
                            if (!source.visible) { cancelSmbPhotoThumbnail(icon, source); return; }
                            photoPreviewDecodeSemaphore.acquire();
                            acquired = true;
                            if (!source.visible) { cancelSmbPhotoThumbnail(icon, source); return; }
                            deliverSmbPhotoThumbnail(icon, source, loadSmbPhotoBitmap(source, PHOTO_PREVIEW_MAX_DIMENSION));
                        } catch (InterruptedException interrupted) {
                            Thread.currentThread().interrupt();
                            cancelSmbPhotoThumbnail(icon, source);
                        } catch (Exception | OutOfMemoryError ignored) {
                            deliverSmbPhotoThumbnail(icon, source, null);
                        } finally {
                            if (acquired) photoPreviewDecodeSemaphore.release();
                        }
                    });
                } catch (Exception | OutOfMemoryError ignored) { deliverSmbPhotoThumbnail(icon, source, null); }
            });
        } catch (java.util.concurrent.RejectedExecutionException ignored) {
            icon.setTag(R.id.smb_photo_thumbnail_status, null);
        }
    }
    private static final class VideoArtwork {
        final String posterUrl;
        final String backdropUrl;
        final int tmdbId;
        final String tmdbMediaType;
        VideoArtwork(String posterUrl, String backdropUrl) {
            this(posterUrl, backdropUrl, 0, "");
        }
        VideoArtwork(String posterUrl, String backdropUrl, int tmdbId, String tmdbMediaType) {
            this.posterUrl = posterUrl;
            this.backdropUrl = backdropUrl;
            this.tmdbId = tmdbId;
            this.tmdbMediaType = tmdbMediaType == null ? "" : tmdbMediaType;
        }
    }
    /** A seekable source lets MediaMetadataRetriever read both local files and SMB files without copying a multi-GB recording. */
    private interface VideoFrameSource {
        String identity();
        default String mediaPath() { return null; }
        VideoFrameSession open() throws Exception;
    }
    private static final class VideoFrameSession {
        final MediaMetadataRetriever retriever;
        final MediaDataSource dataSource;
        VideoFrameSession(MediaMetadataRetriever retriever, MediaDataSource dataSource) { this.retriever = retriever; this.dataSource = dataSource; }
        void close() {
            try { retriever.release(); } catch (Exception ignored) { }
            if (dataSource != null) try { dataSource.close(); } catch (Exception ignored) { }
        }
    }
    private static final class SmbVideoMediaDataSource extends MediaDataSource {
        private final jcifs.smb.SmbRandomAccessFile input;
        SmbVideoMediaDataSource(jcifs.smb.SmbFile file) throws Exception { input = new jcifs.smb.SmbRandomAccessFile(file, "r"); }
        @Override public synchronized int readAt(long position, byte[] buffer, int offset, int size) throws IOException {
            try { input.seek(position); return input.read(buffer, offset, size); } catch (Exception error) { return -1; }
        }
        @Override public synchronized long getSize() throws IOException {
            try { return input.length(); } catch (Exception error) { return -1L; }
        }
        @Override public synchronized void close() throws IOException { try { input.close(); } catch (Exception ignored) { } }
    }
    private VideoFrameSource resumeVideoFrameSource(String location) throws Exception {
        String normalizedLocation = location == null ? "" : location.trim();
        if (normalizedLocation.regionMatches(true, 0, "smb://", 0, 6)) {
            // Cards and the frame picker create this source on the UI thread.
            // Even constructing a jcifs context can resolve the local hostname;
            // defer it until the artwork worker reads the cache or opens the video.
            return new VideoFrameSource() {
                private VideoFrameSource delegate;
                private synchronized VideoFrameSource resolve() throws Exception {
                    if (delegate == null) {
                        SmbConnectionConfig connection = smbConnectionForPath(normalizedLocation);
                        if (connection == null) connection = defaultSmbConnection();
                        String user = connection == null ? homePrefs().getString("smb_user", "") : connection.user;
                        String password = connection == null ? homePrefs().getString("smb_password", "") : connection.password;
                        delegate = smbVideoFrameSource(new jcifs.smb.SmbFile(
                                normalizedLocation, smbContext(user, password)));
                    }
                    return delegate;
                }
                @Override public String mediaPath() { return normalizedLocation; }
                @Override public String identity() {
                    try { return resolve().identity(); }
                    catch (Exception ignored) { return "smb:" + normalizedLocation; }
                }
                @Override public VideoFrameSession open() throws Exception { return resolve().open(); }
            };
        }
        Uri uri = Uri.parse(normalizedLocation);
        if ("content".equals(uri.getScheme())) return new VideoFrameSource() {
            @Override public String identity() { return "content:" + location; }
            @Override public String mediaPath() { return location; }
            @Override public VideoFrameSession open() throws Exception {
                MediaMetadataRetriever retriever = new MediaMetadataRetriever();
                try {
                    retriever.setDataSource(MainActivity.this, uri);
                    return new VideoFrameSession(retriever, null);
                } catch (Exception error) {
                    try { retriever.release(); } catch (Exception ignored) { }
                    throw error;
                }
            }
        };
        return localVideoFrameSource("file".equals(uri.getScheme()) ? new File(uri.getPath()) : new File(location));
    }

    private VideoFrameSource resumeVideoFrameSourceForProgram(JojoProgram program) throws Exception {
        return program.videoFrameSource != null
                ? program.videoFrameSource : resumeVideoFrameSource(program.intentUri);
    }

    private VideoFrameSource localVideoFrameSource(final File file) {
        return new VideoFrameSource() {
            @Override public String identity() { return "local:" + file.getAbsolutePath() + ":" + file.lastModified() + ":" + file.length(); }
            @Override public VideoFrameSession open() {
                MediaMetadataRetriever retriever = new MediaMetadataRetriever();
                retriever.setDataSource(file.getAbsolutePath());
                return new VideoFrameSession(retriever, null);
            }
        };
    }
    private VideoFrameSource smbVideoFrameSource(final jcifs.smb.SmbFile file) {
        return new VideoFrameSource() {
            @Override public String mediaPath() { return file.getPath(); }
            @Override public String identity() {
                try { return "smb:" + file.getCanonicalPath() + ":" + file.getLastModified() + ":" + file.length(); }
                catch (Exception ignored) { return "smb:" + file.getPath(); }
            }
            @Override public VideoFrameSession open() throws Exception {
                SmbVideoMediaDataSource source = new SmbVideoMediaDataSource(file);
                MediaMetadataRetriever retriever = new MediaMetadataRetriever();
                try { retriever.setDataSource(source); return new VideoFrameSession(retriever, source); }
                catch (Exception error) { try { retriever.release(); } catch (Exception ignored) { } source.close(); throw error; }
            }
        };
    }
    private String videoFrameKey(VideoFrameSource source) { return "video_frame_" + Integer.toUnsignedString(source.identity().hashCode(), 16); }
    private File videoFrameDirectory() { File folder = new File(getCacheDir(), "video_frames"); if (!folder.exists()) folder.mkdirs(); return folder; }
    private File savedVideoFrame(VideoFrameSource source) {
        String path = homePrefs().getString(videoFrameKey(source), "");
        File frame = path.isEmpty() ? null : new File(path);
        return frame != null && frame.isFile() && frame.length() > 0L ? frame : null;
    }
    private Bitmap readSavedVideoFrame(VideoFrameSource source) {
        File frame = savedVideoFrame(source);
        return frame == null ? null : BitmapFactory.decodeFile(frame.getAbsolutePath());
    }
    private File automaticVideoFrameFile(VideoFrameSource source) {
        String hash = Integer.toUnsignedString(source.identity().hashCode(), 16);
        return new File(videoFrameDirectory(), "auto_" + hash + ".jpg");
    }
    private Bitmap readAutomaticVideoFrame(VideoFrameSource source) {
        File frame = automaticVideoFrameFile(source);
        return frame.isFile() && frame.length() > 0L
                ? BitmapFactory.decodeFile(frame.getAbsolutePath()) : null;
    }
    private File saveAutomaticVideoFrame(VideoFrameSource source, Bitmap frame) throws Exception {
        File target = automaticVideoFrameFile(source);
        File temporary = new File(target.getParentFile(), target.getName() + ".tmp");
        try (FileOutputStream output = new FileOutputStream(temporary)) {
            if (!frame.compress(Bitmap.CompressFormat.JPEG, 88, output)) throw new IOException("Image non enregistrée");
        }
        if (target.exists() && !target.delete()) throw new IOException("Cache impossible à remplacer");
        if (!temporary.renameTo(target)) throw new IOException("Cache impossible à finaliser");
        return target;
    }
    private boolean brokenGreenVideoFrame(Bitmap bitmap) {
        int columns = 16, rows = 9, stronglyGreen = 0, vividGreen = 0, chromatic = 0, greenRows = 0;
        int cyanGreen = 0, cyanGreenRows = 0;
        int total = columns * rows;
        for (int row = 0; row < rows; row++) {
            int rowGreen = 0, rowCyanGreen = 0;
            for (int column = 0; column < columns; column++) {
                int x = Math.min(bitmap.getWidth() - 1, Math.max(0, Math.round((column + .5f) * bitmap.getWidth() / columns)));
                int y = Math.min(bitmap.getHeight() - 1, Math.max(0, Math.round((row + .5f) * bitmap.getHeight() / rows)));
                int pixel = bitmap.getPixel(x, y), red = Color.red(pixel), green = Color.green(pixel), blue = Color.blue(pixel);
                int spread = Math.max(red, Math.max(green, blue)) - Math.min(red, Math.min(green, blue));
                if (spread >= 18 && Math.max(red, Math.max(green, blue)) >= 45) chromatic++;
                if (green >= red + 24 && green >= blue + 24 && green >= 45) { stronglyGreen++; rowGreen++; }
                if (green >= 80 && green >= red * 3 / 2 && green >= blue * 3 / 2) vividGreen++;
                // Broken hardware decoding can produce a cyan-green wash
                // rather than pure green, as well as thin horizontal stripes.
                if (green >= 105 && green >= red + 40 && blue >= red + 30
                        && green >= blue - 25) { cyanGreen++; rowCyanGreen++; }
            }
            if (rowGreen >= columns / 3) greenRows++;
            if (rowCyanGreen >= columns / 3) cyanGreenRows++;
        }
        return (stronglyGreen >= total * 85 / 100 && vividGreen >= total * 70 / 100)
                || (stronglyGreen >= total * 25 / 100 && chromatic > 0 && stronglyGreen >= chromatic * 70 / 100 && greenRows >= rows / 2)
                || (cyanGreen >= total * 35 / 100 && cyanGreenRows >= rows * 2 / 3);
    }
    private int videoFrameColourDistance(int first, int second) { return Math.abs(Color.red(first) - Color.red(second)) + Math.abs(Color.green(first) - Color.green(second)) + Math.abs(Color.blue(first) - Color.blue(second)); }
    private boolean decoderMosaicVideoFrame(Bitmap bitmap) {
        int columns = 24, rows = 14, saturated = 0, abrupt = 0, transitions = 0;
        int[] previousRow = new int[columns];
        for (int row = 0; row < rows; row++) {
            int previous = 0; boolean hasPrevious = false;
            for (int column = 0; column < columns; column++) {
                int x = Math.min(bitmap.getWidth() - 1, Math.max(0, Math.round((column + .5f) * bitmap.getWidth() / columns)));
                int y = Math.min(bitmap.getHeight() - 1, Math.max(0, Math.round((row + .5f) * bitmap.getHeight() / rows)));
                int pixel = bitmap.getPixel(x, y);
                int spread = Math.max(Color.red(pixel), Math.max(Color.green(pixel), Color.blue(pixel))) - Math.min(Color.red(pixel), Math.min(Color.green(pixel), Color.blue(pixel)));
                if (spread >= 90) saturated++;
                if (hasPrevious) { transitions++; if (videoFrameColourDistance(pixel, previous) >= 270) abrupt++; }
                if (row > 0) { transitions++; if (videoFrameColourDistance(pixel, previousRow[column]) >= 270) abrupt++; }
                previous = pixel; hasPrevious = true; previousRow[column] = pixel;
            }
        }
        return saturated >= columns * rows * 75 / 100 && transitions > 0 && abrupt >= transitions * 70 / 100;
    }
    private boolean usableVideoFrame(Bitmap bitmap) { return bitmap != null && bitmap.getWidth() >= 80 && bitmap.getHeight() >= 45 && !brokenGreenVideoFrame(bitmap) && !decoderMosaicVideoFrame(bitmap); }
    private long videoFrameFingerprint(Bitmap bitmap) {
        long fingerprint = 17L;
        for (int row = 0; row < 5; row++) for (int column = 0; column < 8; column++) {
            int x = Math.min(bitmap.getWidth() - 1, Math.max(0, Math.round((column + .5f) * bitmap.getWidth() / 8f)));
            int y = Math.min(bitmap.getHeight() - 1, Math.max(0, Math.round((row + .5f) * bitmap.getHeight() / 5f)));
            fingerprint = fingerprint * 31L + bitmap.getPixel(x, y);
        }
        return fingerprint;
    }
    private Bitmap scaledVideoFrame(Bitmap bitmap) {
        if (bitmap == null) return null;
        int width = bitmap.getWidth(), height = bitmap.getHeight();
        if (width <= 640) return bitmap;
        Bitmap scaled = Bitmap.createScaledBitmap(bitmap, 640, Math.max(1, Math.round(height * 640f / width)), true);
        if (scaled != bitmap) bitmap.recycle();
        return scaled;
    }
    private Bitmap usableVideoFrameAt(MediaMetadataRetriever retriever, long positionUs) {
        long safe = Math.max(0L, positionUs);
        long[] positions = new long[] { safe, safe + 2_000_000L, Math.max(0L, safe - 2_000_000L), safe };
        int[] options = new int[] { MediaMetadataRetriever.OPTION_CLOSEST_SYNC, MediaMetadataRetriever.OPTION_NEXT_SYNC, MediaMetadataRetriever.OPTION_PREVIOUS_SYNC, MediaMetadataRetriever.OPTION_CLOSEST };
        for (int index = 0; index < positions.length; index++) {
            Bitmap frame = null;
            try { frame = retriever.getFrameAtTime(positions[index], options[index]); } catch (Exception ignored) { }
            Bitmap scaled = scaledVideoFrame(frame);
            if (usableVideoFrame(scaled)) return scaled;
            if (scaled != null) scaled.recycle();
        }
        return null;
    }
    private Bitmap selectableVideoFrameAt(MediaMetadataRetriever retriever, long positionUs) {
        long safe = Math.max(0L, positionUs);
        long[] positions = new long[] { safe, safe + 2_000_000L, Math.max(0L, safe - 2_000_000L), safe };
        int[] options = new int[] { MediaMetadataRetriever.OPTION_CLOSEST_SYNC, MediaMetadataRetriever.OPTION_NEXT_SYNC, MediaMetadataRetriever.OPTION_PREVIOUS_SYNC, MediaMetadataRetriever.OPTION_CLOSEST };
        for (int index = 0; index < positions.length; index++) {
            Bitmap frame = null;
            try { frame = retriever.getFrameAtTime(positions[index], options[index]); } catch (Exception ignored) { }
            Bitmap scaled = scaledVideoFrame(frame);
            // The manual picker should show the decoded frame for inspection.
            // Auto-thumbnail quality heuristics can reject real episode frames
            // (for example, green-heavy or highly detailed scenes).
            if (scaled != null && scaled.getWidth() >= 80 && scaled.getHeight() >= 45) return scaled;
            if (scaled != null) scaled.recycle();
        }
        return null;
    }
    private long videoFrameDurationUs(MediaMetadataRetriever retriever) {
        try { return Math.max(0L, Long.parseLong(retriever.extractMetadata(MediaMetadataRetriever.METADATA_KEY_DURATION)) * 1000L); } catch (Exception ignored) { return 0L; }
    }
    private Bitmap videoFrameAt(VideoFrameSource source, float fraction) throws Exception {
        VideoFrameSession session = source.open();
        try {
            long durationUs = videoFrameDurationUs(session.retriever);
            long timeUs = durationUs > 0L ? Math.max(1_000_000L, (long) (durationUs * fraction)) : 10_000_000L;
            return usableVideoFrameAt(session.retriever, timeUs);
        } finally { session.close(); }
    }
    private File saveVideoFrame(VideoFrameSource source, Bitmap frame) throws Exception {
        File target = new File(videoFrameDirectory(), videoFrameKey(source) + ".jpg");
        File temporary = new File(target.getParentFile(), target.getName() + ".tmp");
        try (FileOutputStream output = new FileOutputStream(temporary)) { if (!frame.compress(Bitmap.CompressFormat.JPEG, 88, output)) throw new IOException("Image non enregistrée"); }
        if (target.exists() && !target.delete()) throw new IOException("Cache impossible à remplacer");
        if (!temporary.renameTo(target)) throw new IOException("Cache impossible à finaliser");
        homePrefs().edit().putString(videoFrameKey(source), target.getAbsolutePath()).apply();
        return target;
    }
    private void applyVideoFrame(ImageView icon, Bitmap frame, String token) {
        applyVideoFrame(icon, frame, token, null);
    }
    private void applyVideoFrame(ImageView icon, Bitmap frame, String token, Object artworkRequest) {
        if (frame == null) return;
        runOnUiThread(() -> {
            if (!token.equals(icon.getTag())) return;
            if (artworkRequest != null && videoArtworkRequests.get(icon) != artworkRequest) return;
            icon.setPadding(0, 0, 0, 0);
            icon.clearColorFilter();
            icon.setScaleType(ImageView.ScaleType.CENTER_CROP);
            icon.setImageBitmap(frame);
            cacheHomeHeroPreview(icon, frame);
        });
    }
    private void loadVideoFrameFallback(ImageView icon, VideoFrameSource source, String token) {
        loadVideoFrameFallback(icon, source, token, false);
    }
    private void loadVideoFrameFallback(ImageView icon, VideoFrameSource source, String token, boolean independentHero) {
        loadVideoFrameFallback(icon, source, token, independentHero, videoArtworkRequests.get(icon));
    }
    private void loadVideoFrameFallback(ImageView icon, VideoFrameSource source, String token,
                                        boolean independentHero, Object artworkRequest) {
        if (source == null) return;
        new Thread(() -> {
            boolean acquired = false;
            try {
                videoFrameDecodeSemaphore.acquire(); acquired = true;
                if (!independentHero) {
                    Bitmap saved = readSavedVideoFrame(source);
                    if (usableVideoFrame(saved)) { applyVideoFrame(icon, saved, token, artworkRequest); return; }
                }
                Bitmap automatic = readAutomaticVideoFrame(source);
                if (usableVideoFrame(automatic)) { applyVideoFrame(icon, automatic, token, artworkRequest); return; }
                Bitmap frame = videoFrameAt(source, 0.50f);
                if (frame == null) return;
                try { saveAutomaticVideoFrame(source, frame); } catch (Exception ignored) { }
                if (!independentHero) saveVideoFrame(source, frame);
                applyVideoFrame(icon, frame, token, artworkRequest);
            } catch (Exception error) {
                Log.w("JojoHomeArtwork", "FRAME_FALLBACK_FAILED", error);
            } finally { if (acquired) videoFrameDecodeSemaphore.release(); }
        }, "JojoHomeVideoFrame").start();
    }
    private String videoArtworkSearchTitle(String fileName) { return videoArtworkSearchTitle(fileName, null); }
    /**
     * Episodes are often named only S01E01 on a NAS.  Search TMDB with the
     * containing series folder in that case, and never include the episode
     * marker in a series lookup.
     */
    private String videoArtworkSearchTitle(String fileName, String seriesFolder) {
        String title = cleanFileName(fileName).replaceFirst("(?i)\\.(mkv|mp4|webm|avi|mov|ts|m2ts)$", "");
        // SMB/Freebox keeps copied recordings as "Title.1", "Title.2", ….
        // That suffix is a filesystem disambiguator, never part of the TMDB
        // identity, so every copy can reuse the artwork of the original.
        title = title.replaceFirst("(?i)(?:[._ -]+(?:copy|copie)?\\d+|\\s*\\(\\d+\\))$", "");
        title = title.replaceAll("[._]+", " ");
        title = title.replaceFirst("(?i)\\b(?:s\\s*\\d{1,2}\\s*e\\s*\\d{1,3}|\\d{1,2}\\s*x\\s*\\d{1,3})\\b.*$", "");
        // Freebox episodes are also commonly named "Titre E01" without a
        // season marker. The episode suffix is not part of the TMDB title.
        title = title.replaceFirst("(?i)\\s+e\\s*\\d{1,3}\\b.*$", "");
        // France TV recordings can include a localized episode suffix rather
        // than an SxxEyy marker (for example "Series - Épisode 1.mkv").
        title = title.replaceFirst("(?iu)\\s+[-–—:]\\s*(?:épisode|episode|ep)\\s*(?:n[°o]\\s*)?\\d{1,3}\\b.*$", "");
        title = title.replaceFirst("(?i)\\b(2160p|1080p|720p|480p|4k|uhd|bluray|brrip|web[- ]?dl|webrip|hdtv|dvdrip|x26[45]|hevc|av1|aac|ac3|eac3|dts|truehd|vostfr|multi|french|vf[fiq]?|proper|repack)\\b.*$", "");
        title = title.replaceAll("(?i)\\(\\s*(?:19|20)\\d{2}\\s*\\)", " ");
        title = title.replaceAll("\\[[^]]*]", " ").replaceAll("^[^\\p{L}\\p{N}]+", " ").replaceAll("\\s+", " ").trim();
        // A download name such as ">.S01E01.mkv" has no usable title; its
        // parent folder is the only reliable series identity.
        if (title.replaceAll("[^\\p{L}\\p{N}]", "").length() < 3 && seriesFolder != null) {
            String folder = seriesFolder.replaceAll("/+$", "");
            int lastSlash = folder.lastIndexOf('/');
            if (lastSlash >= 0) folder = folder.substring(lastSlash + 1);
            try { folder = java.net.URLDecoder.decode(folder, "UTF-8"); } catch (Exception ignored) { }
            title = folder.replaceAll("[._]+", " ").replaceAll("\\s+", " ").trim();
        }
        return title;
    }
    /** Search the complete recording title first, then the programme without its episode subtitle. */
    private List<String> videoArtworkSearchTitles(String fileName, String seriesFolder) {
        return HomeMediaRules.recordingArtworkSearchTitles(videoArtworkSearchTitle(fileName, seriesFolder));
    }
    private String videoArtworkCacheKey(String fileName) { return videoArtworkCacheKey(fileName, null); }
    private String videoArtworkCacheKey(String fileName, String seriesFolder) { return "video_artwork_tmdb_" + Integer.toUnsignedString(videoArtworkSearchTitle(fileName, seriesFolder).toLowerCase(Locale.ROOT).hashCode(), 16); }
    private VideoArtwork findVideoArtwork(String fileName) throws Exception { return findVideoArtwork(fileName, null); }
    private VideoArtwork findVideoArtwork(String fileName, String seriesFolder) throws Exception {
        String title = videoArtworkSearchTitle(fileName, seriesFolder);
        if (title.isEmpty()) return null;
        String key = videoArtworkCacheKey(fileName, seriesFolder);
        String saved = homePrefs().getString(key, "");
        if (!saved.isEmpty()) {
            JSONObject cache = new JSONObject(saved);
            String poster = cache.optString("poster", ""), backdrop = cache.optString("backdrop", "");
            int tmdbId = cache.optInt("tmdbId", 0);
            String tmdbMediaType = cache.optString("tmdbMediaType", "");
            if ((!poster.isEmpty() || !backdrop.isEmpty()) && tmdbId > 0 && !tmdbMediaType.isEmpty()) {
                return new VideoArtwork(poster, backdrop, tmdbId, tmdbMediaType);
            }
        }
        if (BuildConfig.TMDB_API_KEY != null && !BuildConfig.TMDB_API_KEY.trim().isEmpty()) for (String query : videoArtworkSearchTitles(fileName, seriesFolder)) {
            String endpoint = "https://api.themoviedb.org/3/search/multi?api_key="
                    + java.net.URLEncoder.encode(BuildConfig.TMDB_API_KEY, "UTF-8")
                    + "&language=fr-FR&include_adult=false&query="
                    + java.net.URLEncoder.encode(query, "UTF-8");
            JSONArray results = fetchJson(endpoint).optJSONArray("results");
            if (results == null) continue;
            for (int index = 0; index < results.length(); index++) {
                JSONObject result = results.optJSONObject(index);
                if (result == null || "person".equals(result.optString("media_type"))) continue;
                String resultTitle = result.optString("title", result.optString("name", ""));
                if (!tmdbArtworkTitleMatches(title, query, resultTitle)) continue;
                String posterPath = tmdbImagePath(result, "poster_path");
                String backdropPath = tmdbImagePath(result, "backdrop_path");
                if (posterPath.isEmpty() && backdropPath.isEmpty()) continue;
                String poster = posterPath.isEmpty() ? "" : "https://image.tmdb.org/t/p/w500" + posterPath;
                String backdrop = backdropPath.isEmpty() ? "" : "https://image.tmdb.org/t/p/w780" + backdropPath;
                int tmdbId = result.optInt("id", 0);
                String tmdbMediaType = result.optString("media_type", "");
                if (tmdbMediaType.isEmpty()) tmdbMediaType = result.has("title") ? "movie" : result.has("name") ? "tv" : "";
                if (tmdbId <= 0 || (!"movie".equals(tmdbMediaType) && !"tv".equals(tmdbMediaType))) continue;
                homePrefs().edit().putString(key, new JSONObject()
                        .put("poster", poster)
                        .put("backdrop", backdrop)
                        .put("tmdbId", tmdbId)
                        .put("tmdbMediaType", tmdbMediaType)
                        .put("matchedTitle", resultTitle)
                        .toString()).apply();
                return new VideoArtwork(poster, backdrop, tmdbId, tmdbMediaType);
            }
        }
        try {
            List<ResumeArtworkCandidate> official = findArtworkCandidatesWithOfficialSources(fileName);
            if (!official.isEmpty()) {
                String url = official.get(0).url;
                homePrefs().edit().putString(key, new JSONObject().put("poster", url).put("backdrop", url).toString()).apply();
                return new VideoArtwork(url, url);
            }
        } catch (Exception ignored) { }
        return null;
    }
    private VideoArtwork findSharedVideoArtwork(String fileName, String seriesFolder) throws Exception {
        String key = videoArtworkCacheKey(fileName, seriesFolder);
        java.util.concurrent.FutureTask<VideoArtwork> task = new java.util.concurrent.FutureTask<>(() -> {
            videoArtworkLookupSemaphore.acquire();
            try { return findVideoArtwork(fileName, seriesFolder); }
            finally { videoArtworkLookupSemaphore.release(); }
        });
        java.util.concurrent.FutureTask<VideoArtwork> pending = videoArtworkLookupsInFlight.putIfAbsent(key, task);
        if (pending != null) return pending.get();
        try {
            task.run();
            return task.get();
        } finally { videoArtworkLookupsInFlight.remove(key, task); }
    }

