    private ArrayList<File> localPhotoSiblings(File current) { ArrayList<File> photos = new ArrayList<>(); File parent = current == null ? null : current.getParentFile(); File[] children = parent == null ? null : parent.listFiles(); if (children != null) for (File child : children) if (!child.isDirectory() && isImageFile(child.getName()) && (showHiddenFiles() || !isHiddenName(child.getName()))) photos.add(child); Collections.sort(photos, (a, b) -> a.getName().compareToIgnoreCase(b.getName())); if (photos.isEmpty() && current != null) photos.add(current); return photos; }
    private int photoIndex(List<?> photos, Object current) { String currentPath = current instanceof File ? ((File) current).getAbsolutePath() : current instanceof jcifs.smb.SmbFile ? ((jcifs.smb.SmbFile) current).getPath() : String.valueOf(current); for (int i = 0; i < photos.size(); i++) { Object item = photos.get(i); String itemPath = item instanceof File ? ((File) item).getAbsolutePath() : item instanceof jcifs.smb.SmbFile ? ((jcifs.smb.SmbFile) item).getPath() : String.valueOf(item); if (currentPath.equals(itemPath)) return i; } return 0; }
    private View createLocalPhotoViewer(File current) {
        ArrayList<File> photos = localPhotoSiblings(current);
        return createPhotoCoverflowViewer(photos, current, new PhotoCoverflowLoader<File>() {
            @Override public String id(File photo) { return photo.getAbsolutePath(); }
            @Override public String label(File photo) { return cleanFileName(photo.getName()); }
            @Override public Bitmap cached(File photo, int maximumDimension) {
                return smbPhotoBitmapCache.get(localPhotoKey(photo) + "|" + maximumDimension);
            }
            @Override public Bitmap loadCached(File photo, int maximumDimension) {
                return readPhotoCache(localPhotoKey(photo), maximumDimension);
            }
            @Override public Bitmap load(File photo, int maximumDimension) throws Exception {
                return loadLocalPhotoBitmap(photo, maximumDimension);
            }
        });
    }

    private interface PhotoCoverflowLoader<T> {
        String id(T photo);
        String label(T photo);
        default boolean progressivePreview() { return false; }
        default int progressivePreviewDimension() { return PHOTO_PREVIEW_MAX_DIMENSION; }
        default Bitmap cached(T photo, int maximumDimension) { return null; }
        default Bitmap loadCached(T photo, int maximumDimension) { return cached(photo, maximumDimension); }
        Bitmap load(T photo, int maximumDimension) throws Exception;
    }

    private <T> void addPhotoLoadRequest(Map<String, PhotoLoadQueue.Request<Bitmap>> requests,
            PhotoCoverflowLoader<T> loader, T photo, int maximumDimension,
            java.util.concurrent.atomic.AtomicBoolean open, java.util.function.Consumer<Bitmap> complete) {
        String key = loader.id(photo) + "|" + maximumDimension;
        PhotoLoadQueue.Request<Bitmap> previous = requests.get(key);
        java.util.function.Consumer<Bitmap> delivery = previous == null ? complete
                : bitmap -> { previous.complete.accept(bitmap); complete.accept(bitmap); };
        requests.put(key, new PhotoLoadQueue.Request<>(() -> {
            if (!open.get() || Thread.currentThread().isInterrupted()) return null;
            try {
                Bitmap cached = loader.loadCached(photo, maximumDimension);
                return cached != null ? cached : loader.load(photo, maximumDimension);
            } catch (OutOfMemoryError ignored) { return null; }
        }, delivery));
    }

    private Bitmap sharperPhotoBitmap(Bitmap current, Bitmap candidate) {
        if (candidate == null) return current;
        if (current == null) return candidate;
        return Math.max(candidate.getWidth(), candidate.getHeight()) > Math.max(current.getWidth(), current.getHeight())
                ? candidate : current;
    }
    private void bindPhotoCoverflowBitmap(FrameLayout card, ImageView image, Bitmap bitmap,
                                           int distance, boolean fullscreen) {
        image.setScaleType(fullscreen || distance == 0
                ? ImageView.ScaleType.FIT_CENTER : ImageView.ScaleType.CENTER_CROP);
        if (!fullscreen && distance == 0)
            image.setBackground(new android.graphics.drawable.ColorDrawable(Color.BLACK));
        image.setImageBitmap(bitmap);
        if (!fullscreen) layoutPhotoCoverflowCards((FrameLayout) card.getParent());
    }
    private void layoutPhotoCoverflowCards(FrameLayout stage) {
        if (stage.getWidth() <= 0 || stage.getHeight() <= 0 || stage.getChildCount() == 0) return;
        int maximumWidth = Math.min(dp(720), Math.max(1, stage.getWidth() - dp(240)));
        int maximumHeight = Math.max(1, stage.getHeight() - dp(24));
        FrameLayout center = (FrameLayout) stage.getChildAt(0);
        ImageView centerImage = (ImageView) center.getChildAt(0);
        Drawable artwork = centerImage.getDrawable();
        int centerWidth = maximumWidth, centerHeight = maximumHeight;
        if (artwork instanceof BitmapDrawable) {
            Bitmap bitmap = ((BitmapDrawable) artwork).getBitmap();
            float scale = Math.min(maximumWidth / (float) bitmap.getWidth(),
                    maximumHeight / (float) bitmap.getHeight());
            centerWidth = Math.max(1, Math.round(bitmap.getWidth() * scale));
            centerHeight = Math.max(1, Math.round(bitmap.getHeight() * scale));
        }
        center.setLayoutParams(new FrameLayout.LayoutParams(centerWidth, centerHeight, Gravity.CENTER));
        center.setTranslationX(0);
        // Keep both previews visible on each side, including beside landscape photos.
        int sideSpace = (stage.getWidth() - centerWidth) / 2;
        int nearWidth = Math.min(dp(168), Math.max(dp(80), sideSpace - dp(84)));
        int farWidth = dp(144);
        int centerGap = Math.min(dp(36), Math.max(dp(8), sideSpace - nearWidth - dp(48)));
        int previewGap = Math.min(dp(24), Math.max(dp(8), sideSpace - nearWidth - centerGap - dp(24)));
        int nearOffset = centerWidth / 2 + centerGap + nearWidth / 2;
        int farOffset = centerWidth / 2 + centerGap + nearWidth + previewGap + farWidth / 2;
        for (int i = 1; i < stage.getChildCount(); i++) {
            FrameLayout card = (FrameLayout) stage.getChildAt(i);
            int relative = (Integer) card.getTag();
            int distance = Math.abs(relative);
            int width = distance == 1 ? nearWidth : farWidth;
            int height = Math.max(1, Math.round(maximumHeight * (distance == 1 ? .70f : .64f)));
            card.setLayoutParams(new FrameLayout.LayoutParams(width, height, Gravity.CENTER));
            card.setTranslationX((relative < 0 ? -1 : 1) * (distance == 1 ? nearOffset : farOffset));
        }
    }
    /** Native TV adaptation of OriginKit's flat-slat coverflow carousel. */
    private <T> View createPhotoCoverflowViewer(List<T> photos, T current, PhotoCoverflowLoader<T> loader) {
        return createPhotoCoverflowPage(photos, photoIndex(photos, current), loader, false, null);
    }
    private <T> View createPhotoCoverflowPage(List<T> photos, int initialIndex,
            PhotoCoverflowLoader<T> loader, boolean fullscreen, PhotoSlideshow.State sharedState) {
        FrameLayout page = new FrameLayout(this);
        page.setId(View.generateViewId());
        page.setFocusable(true);
        page.setFocusableInTouchMode(true);
        page.setBackgroundColor(Color.rgb(5, 8, 14));
        homeBottomBarHiddenPages.put(page, Boolean.TRUE);
        final int total = photos == null ? 0 : photos.size();
        if (total == 0) return page;

        FrameLayout stage = new FrameLayout(this);
        stage.setClipChildren(false);
        stage.setClipToPadding(false);
        FrameLayout.LayoutParams stageParams = new FrameLayout.LayoutParams(-1, -1);
        if (!fullscreen) {
            stageParams.topMargin = dp(16);
            stageParams.bottomMargin = dp(78);
            stage.addOnLayoutChangeListener((view, left, top, right, bottom, oldLeft, oldTop, oldRight, oldBottom) -> {
                if (right - left != oldRight - oldLeft || bottom - top != oldBottom - oldTop)
                    layoutPhotoCoverflowCards(stage);
            });
        }
        page.addView(stage, stageParams);

        TextView caption = resumeMarqueeText("", 18, Color.WHITE);
        caption.setGravity(Gravity.CENTER);
        caption.setTypeface(null, Typeface.BOLD);
        caption.setPadding(dp(24), 0, dp(24), 0);
        FrameLayout.LayoutParams captionParams = new FrameLayout.LayoutParams(dp(700), dp(36), Gravity.CENTER_HORIZONTAL | Gravity.BOTTOM);
        captionParams.bottomMargin = dp(34);
        if (!fullscreen) page.addView(caption, captionParams);
        TextView counter = text("", 13, muted);
        counter.setGravity(Gravity.CENTER);
        FrameLayout.LayoutParams counterParams = new FrameLayout.LayoutParams(dp(180), dp(24), Gravity.CENTER_HORIZONTAL | Gravity.BOTTOM);
        counterParams.bottomMargin = dp(14);
        if (!fullscreen) page.addView(counter, counterParams);

        TextView photoStatus = text("Chargement de la photo…", 16, Color.WHITE);
        photoStatus.setGravity(Gravity.CENTER);
        photoStatus.setPadding(dp(24), dp(12), dp(24), dp(12));
        page.addView(photoStatus, new FrameLayout.LayoutParams(-2, -2, Gravity.CENTER));

        final int[] slots = fullscreen ? new int[] { 0 }
                : total == 1 ? new int[] { 0 } : total == 2 ? new int[] { 0, 1, -1 }
                : new int[] { 0, 1, -1, 2, -2 };
        final ArrayList<FrameLayout> cards = new ArrayList<>();
        final ArrayList<ImageView> images = new ArrayList<>();
        final String[] boundPhotoIds = new String[slots.length];
        for (int relative : slots) {
            FrameLayout card = new FrameLayout(this);
            card.setTag(relative);
            card.setClipChildren(true);
            card.setClipToPadding(true);
            card.setLayerType(View.LAYER_TYPE_HARDWARE, null);
            ImageView image = new ImageView(this);
            image.setScaleType(fullscreen || relative == 0
                    ? ImageView.ScaleType.FIT_CENTER : ImageView.ScaleType.CENTER_CROP);
            image.setBackground(fullscreen
                    ? new android.graphics.drawable.ColorDrawable(Color.BLACK) : continueWatchingArtworkBg());
            if (!fullscreen) roundImage(image, 18);
            card.addView(image, new FrameLayout.LayoutParams(-1, -1));
            if (!fullscreen) {
                View sheen = new View(this);
                sheen.setBackground(continueWatchingShade());
                sheen.setAlpha(.18f);
                card.addView(sheen, new FrameLayout.LayoutParams(-1, -1));
            }
            stage.addView(card);
            cards.add(card);
            images.add(image);
        }

        final PhotoSlideshow.State session = sharedState == null
                ? new PhotoSlideshow.State(initialIndex, homePrefs().getBoolean("photo_slideshow_enabled", true)) : sharedState;
        final boolean[] rendered = { false };
        final java.util.concurrent.atomic.AtomicBoolean open = new java.util.concurrent.atomic.AtomicBoolean(true);
        PhotoLoadQueue<Bitmap> previews = new PhotoLoadQueue<>(photoCarouselPreviewExecutor, 2);
        PhotoLoadQueue<Bitmap> highResolution = new PhotoLoadQueue<>(photoViewerExecutor, 1);
        final Runnable[] render = new Runnable[1];
        PhotoSlideshow slideshow = new PhotoSlideshow(session, total, photoSlideshowSeconds(), new PhotoSlideshow.Scheduler() {
            @Override public void schedule(Runnable task, long delayMillis) { page.postDelayed(task, delayMillis); }
            @Override public void cancel(Runnable task) { page.removeCallbacks(task); }
        }, () -> render[0].run());
        ImageView slideshowControl = new ImageView(this);
        slideshowControl.setId(View.generateViewId());
        slideshowControl.setPadding(dp(12), dp(12), dp(12), dp(12));
        slideshowControl.setFocusable(true);
        Runnable paintSlideshow = () -> {
            slideshowControl.setImageResource(session.playing ? R.drawable.ic_player_pause : R.drawable.ic_player_play);
            String label = session.playing ? "Mettre le diaporama en pause" : "Reprendre le diaporama";
            slideshowControl.setContentDescription(label);
            if (Build.VERSION.SDK_INT >= 26) slideshowControl.setTooltipText(label);
            boolean focused = slideshowControl.hasFocus();
            slideshowControl.setColorFilter(focused ? contrastingFolderThemeTextColor() : Color.WHITE);
            GradientDrawable background = new GradientDrawable();
            background.setColor(focused ? folderButtonThemeColor() : Color.argb(160, 0, 0, 0));
            background.setCornerRadius(dp(8));
            if (focused) background.setStroke(dp(2), buttonFocusOutlineColor(folderButtonThemeColor()));
            slideshowControl.setBackground(background);
        };
        slideshowControl.setOnFocusChangeListener((view, focused) -> paintSlideshow.run());
        slideshowControl.setOnClickListener(view -> {
            slideshow.setPlaying(!session.playing);
            paintSlideshow.run();
        });
        FrameLayout.LayoutParams slideshowParams = new FrameLayout.LayoutParams(dp(48), dp(48), Gravity.RIGHT | Gravity.BOTTOM);
        slideshowParams.rightMargin = dp(16);
        slideshowParams.bottomMargin = dp(16);
        if (total > 1) {
            page.addView(slideshowControl, slideshowParams);
            page.setNextFocusDownId(slideshowControl.getId());
            slideshowControl.setNextFocusUpId(page.getId());
        }
        paintSlideshow.run();
        page.addOnAttachStateChangeListener(new View.OnAttachStateChangeListener() {
            @Override public void onViewAttachedToWindow(View view) {
                if (!open.getAndSet(true)) {
                    for (ImageView image : images) image.setTag(null);
                    render[0].run();
                }
                activePhotoSlideshow = slideshow;
                slideshow.setActive(homeActivityResumed && hasWindowFocus());
                paintSlideshow.run();
            }
            @Override public void onViewDetachedFromWindow(View view) {
                open.set(false);
                previews.clear();
                highResolution.clear();
                slideshow.setActive(false);
                if (activePhotoSlideshow == slideshow) activePhotoSlideshow = null;
            }
        });
        render[0] = () -> {
            slideshow.photoChanged();
            Map<String, PhotoLoadQueue.Request<Bitmap>> previewRequests = new LinkedHashMap<>();
            Map<String, PhotoLoadQueue.Request<Bitmap>> qualityPreviewRequests = new LinkedHashMap<>();
            Map<String, PhotoLoadQueue.Request<Bitmap>> highResolutionRequests = new LinkedHashMap<>();
            Set<String> visiblePhotos = new HashSet<>();
            // Retain visible quality before reassigning slots, even if the shared cache evicted it.
            Map<String, Bitmap> displayedPhotos = new HashMap<>();
            for (int i = 0; i < images.size(); i++) {
                Drawable displayed = images.get(i).getDrawable();
                if (boundPhotoIds[i] != null && displayed instanceof BitmapDrawable) {
                    Bitmap bitmap = ((BitmapDrawable) displayed).getBitmap();
                    displayedPhotos.put(boundPhotoIds[i], sharperPhotoBitmap(displayedPhotos.get(boundPhotoIds[i]), bitmap));
                }
            }
            T activePhoto = photos.get(session.index);
            caption.setText(loader.label(activePhoto));
            counter.setText((session.index + 1) + " / " + total);
            photoStatus.setText("Chargement de la photo…");
            photoStatus.setVisibility(View.VISIBLE);
            final int[] activeLoads = { 2 };
            for (int slotIndex = 0; slotIndex < slots.length; slotIndex++) {
                int relative = slots[slotIndex];
                int photoIndex = Math.floorMod(session.index + relative, total);
                T photo = photos.get(photoIndex);
                int distance = Math.abs(relative);
                int width = dp(distance == 0 ? 720 : distance == 1 ? 168 : 144);
                int maximumHeight = stage.getHeight() > 0 ? Math.max(1, stage.getHeight() - dp(24)) : dp(420);
                int height = distance == 0 ? maximumHeight
                        : Math.max(1, Math.round(maximumHeight * (distance == 1 ? .70f : .64f)));
                FrameLayout card = cards.get(slotIndex);
                FrameLayout.LayoutParams params = fullscreen
                        ? new FrameLayout.LayoutParams(-1, -1)
                        : new FrameLayout.LayoutParams(width, height, Gravity.CENTER);
                card.setLayoutParams(params);
                card.setElevation(dp(distance == 0 ? 10 : 2));
                card.setAlpha(distance == 0 ? 1f : distance == 1 ? .72f : .40f);
                card.setScaleX(rendered[0] ? .94f : 1f);
                card.setScaleY(rendered[0] ? .94f : 1f);
                card.animate().scaleX(1f).scaleY(1f).setDuration(160).start();
                ImageView image = images.get(slotIndex);
                String photoId = loader.id(photo);
                String token = photoId + ":" + (distance == 0 ? "active" : "slat");
                boundPhotoIds[slotIndex] = photoId;
                if (!token.equals(image.getTag())) {
                    image.setTag(token);
                    Bitmap ready = displayedPhotos.get(photoId);
                    ready = sharperPhotoBitmap(ready, loader.cached(photo, PHOTO_VIEWER_MAX_DIMENSION));
                    ready = sharperPhotoBitmap(ready, loader.cached(photo, PHOTO_CAROUSEL_PREVIEW_MAX_DIMENSION));
                    ready = sharperPhotoBitmap(ready, loader.cached(photo, PHOTO_PREVIEW_MAX_DIMENSION));
                    if (ready != null) bindPhotoCoverflowBitmap(card, image, ready, distance, fullscreen);
                    else image.setImageDrawable(null);
                }
                java.util.function.Consumer<Bitmap> show = bitmap -> runOnUiThread(() -> {
                    if (!open.get() || !token.equals(image.getTag())) return;
                    if (distance == 0 && --activeLoads[0] <= 0 && bitmap == null && image.getDrawable() == null) {
                        photoStatus.setText("Photo impossible à charger");
                        photoStatus.setVisibility(View.VISIBLE);
                    }
                    if (bitmap == null) return;
                    Drawable currentImage = image.getDrawable();
                    if (currentImage instanceof BitmapDrawable) {
                        Bitmap displayed = ((BitmapDrawable) currentImage).getBitmap();
                        if (Math.max(displayed.getWidth(), displayed.getHeight()) > Math.max(bitmap.getWidth(), bitmap.getHeight())) return;
                    }
                    bindPhotoCoverflowBitmap(card, image, bitmap, distance, fullscreen);
                    if (distance == 0) {
                        photoStatus.setVisibility(View.GONE);
                        slideshow.photoDisplayed();
                    }
                });
                visiblePhotos.add(photoId);
                addPhotoLoadRequest(previewRequests, loader, photo, PHOTO_PREVIEW_MAX_DIMENSION, open, show);
                if (distance == 0)
                    addPhotoLoadRequest(highResolutionRequests, loader, photo, PHOTO_VIEWER_MAX_DIMENSION, open, show);
                else
                    addPhotoLoadRequest(qualityPreviewRequests, loader, photo, PHOTO_CAROUSEL_PREVIEW_MAX_DIMENSION, open, show);
                if (distance == 0 && image.getDrawable() != null) {
                    photoStatus.setVisibility(View.GONE);
                    slideshow.photoDisplayed();
                }
            }
            // Fullscreen has no side cards, but prepares the same next two photos as the carousel.
            for (int step = 1; step <= Math.min(2, total - 1); step++) {
                T next = photos.get((session.index + step) % total);
                if (visiblePhotos.contains(loader.id(next))) continue;
                addPhotoLoadRequest(previewRequests, loader, next, PHOTO_PREVIEW_MAX_DIMENSION, open, bitmap -> { });
                addPhotoLoadRequest(qualityPreviewRequests, loader, next, PHOTO_CAROUSEL_PREVIEW_MAX_DIMENSION, open, bitmap -> { });
            }
            previewRequests.putAll(qualityPreviewRequests);
            previews.replace(previewRequests);
            highResolution.replace(highResolutionRequests);
            if (!fullscreen) layoutPhotoCoverflowCards(stage);
            rendered[0] = true;
        };
        View.OnKeyListener photoKeys = (view, keyCode, event) -> {
            if (event.getAction() != KeyEvent.ACTION_DOWN) return false;
            if (view == page && (keyCode == KeyEvent.KEYCODE_DPAD_CENTER || keyCode == KeyEvent.KEYCODE_ENTER)) {
                if (event.getRepeatCount() == 0) {
                    if (!fullscreen) openScreen(createPhotoCoverflowPage(photos, session.index, loader, true, session));
                    else { slideshow.setPlaying(!session.playing); paintSlideshow.run(); }
                }
                return true;
            }
            if (keyCode == KeyEvent.KEYCODE_MEDIA_PLAY_PAUSE || keyCode == KeyEvent.KEYCODE_MEDIA_PLAY
                    || keyCode == KeyEvent.KEYCODE_MEDIA_PAUSE || keyCode == KeyEvent.KEYCODE_MEDIA_STOP) {
                if (event.getRepeatCount() == 0) {
                    slideshow.setPlaying(keyCode == KeyEvent.KEYCODE_MEDIA_PLAY
                            || keyCode == KeyEvent.KEYCODE_MEDIA_PLAY_PAUSE && !session.playing);
                    paintSlideshow.run();
                }
                return true;
            }
            if (total < 2) return false;
            if (keyCode == KeyEvent.KEYCODE_DPAD_LEFT) {
                slideshow.move(-1);
                return true;
            }
            if (keyCode == KeyEvent.KEYCODE_DPAD_RIGHT) {
                slideshow.move(1);
                return true;
            }
            return false;
        };
        page.setOnKeyListener(photoKeys);
        slideshowControl.setOnKeyListener(photoKeys);
        render[0].run();
        page.post(page::requestFocus);
        return page;
    }

    // Legacy helper retained for callers outside the Local/NAS photo routes.
    private FrameLayout photoViewerFrame() { FrameLayout page = new FrameLayout(this); page.setFocusable(true); page.setFocusableInTouchMode(true); page.setBackgroundColor(Color.BLACK); ImageView image = new ImageView(this); image.setScaleType(ImageView.ScaleType.FIT_CENTER); image.setAdjustViewBounds(true); page.addView(image, new FrameLayout.LayoutParams(-1, -1)); TextView label = text("", 14, Color.WHITE); label.setGravity(Gravity.CENTER); page.addView(label, new FrameLayout.LayoutParams(dp(220), dp(36), Gravity.LEFT | Gravity.BOTTOM)); page.setTag(image); return page; }
    private void positionPhotoLabel(ImageView image, TextView label, android.graphics.Bitmap bitmap) { FrameLayout page = image.getParent() instanceof FrameLayout ? (FrameLayout) image.getParent() : null; if (page == null || page.getWidth() == 0 || page.getHeight() == 0) { label.post(() -> positionPhotoLabel(image, label, bitmap)); return; } int pageWidth = page.getWidth(), pageHeight = page.getHeight(); float scale = Math.min(pageWidth / (float) bitmap.getWidth(), pageHeight / (float) bitmap.getHeight()); int photoWidth = Math.round(bitmap.getWidth() * scale), photoHeight = Math.round(bitmap.getHeight() * scale); int sideMargin = Math.max(0, (pageWidth - photoWidth) / 2), verticalMargin = Math.max(0, (pageHeight - photoHeight) / 2); FrameLayout.LayoutParams params = (FrameLayout.LayoutParams) label.getLayoutParams(); params.width = dp(220); params.height = dp(36); params.leftMargin = dp(12); params.rightMargin = dp(12); params.topMargin = 0; params.bottomMargin = dp(12); if (sideMargin >= dp(130)) { params.width = Math.max(dp(110), sideMargin - dp(16)); params.gravity = Gravity.LEFT | Gravity.BOTTOM; } else if (verticalMargin >= dp(50)) { params.width = Math.min(dp(300), photoWidth); params.gravity = Gravity.CENTER_HORIZONTAL | Gravity.BOTTOM; params.bottomMargin = Math.max(dp(8), verticalMargin - dp(40)); } else { params.width = Math.min(dp(280), pageWidth - dp(24)); params.gravity = Gravity.RIGHT | Gravity.TOP; params.topMargin = dp(12); } label.setLayoutParams(params); label.setVisibility(View.VISIBLE); }
    private void showLocalPhoto(ImageView image, TextView label, ArrayList<File> photos, int index) { File photo = photos.get(index); String token = photo.getAbsolutePath(); image.setTag(token); label.setText(cleanFileName(photo.getName()) + "   " + (index + 1) + " / " + photos.size()); image.setImageDrawable(null); new Thread(() -> { boolean acquired = false; try { photoViewerDecodeSemaphore.acquire(); acquired = true; Bitmap bitmap; try (InputStream input = new FileInputStream(photo)) { bitmap = decodePhotoBytes(readPhotoBytes(input), photo.getName(), PHOTO_VIEWER_MAX_DIMENSION); } final Bitmap decoded = bitmap; runOnUiThread(() -> { if (!token.equals(image.getTag())) return; if (decoded != null) { image.setImageBitmap(decoded); positionPhotoLabel(image, label, decoded); } else Toast.makeText(this, "Photo impossible à lire", Toast.LENGTH_LONG).show(); }); } catch (Exception error) { runOnUiThread(() -> { if (token.equals(image.getTag())) Toast.makeText(this, "Photo impossible à lire", Toast.LENGTH_LONG).show(); }); } finally { if (acquired) photoViewerDecodeSemaphore.release(); } }).start(); }
    private void openLocalFile(File file) { if (pendingResumeArtworkKey != null) { if (!isImageFile(file.getName())) { Toast.makeText(this, "Choisissez une image pour la vignette", Toast.LENGTH_SHORT).show(); return; } new Thread(() -> { try { saveResumeArtwork(Uri.fromFile(file), pendingResumeArtworkKey); runOnUiThread(() -> { pendingResumeArtworkKey = null; goHome(); }); } catch (Exception error) { runOnUiThread(() -> Toast.makeText(this, "Impossible de lire cette image", Toast.LENGTH_LONG).show()); } }).start(); return; } if (pendingAppIconPackage != null) { if (!isImageFile(file.getName())) { Toast.makeText(this, "Choisissez une image pour l’icône", Toast.LENGTH_SHORT).show(); return; } new Thread(() -> { try { saveAppIcon(Uri.fromFile(file)); runOnUiThread(() -> { pendingAppIconPackage = null; goHome(); }); } catch (Exception error) { runOnUiThread(() -> Toast.makeText(this, "Impossible de lire cette image", Toast.LENGTH_LONG).show()); } }).start(); return; } if (isImageFile(file.getName())) { openScreen(createLocalPhotoViewer(file)); return; } if (isVideoFile(file.getName())) { openNuvioPlayer(Uri.fromFile(file), cleanFileName(file.getName()), file.getAbsolutePath(), file.getAbsolutePath()); return; } if (isApkFile(file.getName())) { installApk(file); return; } if (isWordDocumentFile(file.getName())) { openWordDocument(file.getName(), () -> new FileInputStream(file)); return; } if (!isMediaFile(file.getName())) { Toast.makeText(this, "Ce type de fichier ne peut pas être utilisé comme fond d’écran", Toast.LENGTH_SHORT).show(); return; } new Thread(() -> { try { savePersonalWallpaper(Uri.fromFile(file)); runOnUiThread(() -> openScreen(createAppSettingsPage())); } catch (Exception error) { runOnUiThread(() -> Toast.makeText(this, "Impossible de lire ce fichier", Toast.LENGTH_LONG).show()); } }).start(); }
    private void installApk(File apk) {
        pendingResumeArtworkKey = null;
        hideApkInstallProgress();
        if (Build.VERSION.SDK_INT >= 26 && !getPackageManager().canRequestPackageInstalls()) {
            Toast.makeText(this, "Autorisez Jojo Home à installer des applications, puis réessayez", Toast.LENGTH_LONG).show();
            startActivity(new Intent(Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES, Uri.parse("package:" + getPackageName())));
            return;
        }
        try {
            // Save this before launching Android's installer. The installer can
            // pause/resume this activity synchronously on TV, so assigning it
            // after startActivity() loses the pending prompt on some devices.
            pendingInstalledApkPackage = getPackageNameFromApk(apk);
            pendingInstalledApkChecks = 0;
            Uri uri = androidx.core.content.FileProvider.getUriForFile(this, getPackageName() + ".files", apk);
            // ACTION_VIEW can be resolved by Fire TV's generic document viewer.
            // Its installation pane is the one with the invisible white-header
            // copy shown on the TV.  Ask for the dedicated package-installer
            // contract instead so the system uses its normal, readable flow.
            Intent intent = new Intent(Intent.ACTION_INSTALL_PACKAGE)
                    .setData(uri)
                    .addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION)
                    .addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);
            startActivity(intent);
        } catch (Exception error) {
            pendingInstalledApkPackage = null;
            pendingInstalledApkChecks = 0;
            android.util.Log.e("JojoHomeInstall", "Impossible d’ouvrir l’installateur pour " + apk.getAbsolutePath(), error);
            Toast.makeText(this, "Installateur Android TV indisponible", Toast.LENGTH_LONG).show();
        }
    }

    private void showApkInstallProgress(String fileName) {
        runOnUiThread(() -> {
            hideApkInstallProgress();
            FrameLayout root = (FrameLayout) getWindow().getDecorView().findViewById(android.R.id.content);
            if (root == null) return;
            apkInstallProgressBanner = new FrameLayout(this);
            GradientDrawable background = new GradientDrawable();
            background.setColor(withAlpha(overlayThemeColor(), 238));
            background.setCornerRadius(dp(10));
            background.setStroke(dp(1), folderThemeColor());
            apkInstallProgressBanner.setBackground(background);
            apkInstallProgressBanner.setPadding(dp(20), dp(12), dp(20), dp(12));

            LinearLayout content = new LinearLayout(this);
            content.setOrientation(LinearLayout.VERTICAL);
            TextView title = text("Préparation de l’installation", 16, white);
            title.setTypeface(null, Typeface.BOLD);
            apkInstallProgressLabel = text("0 %  ·  " + fileName, 14, muted);
            apkInstallProgressBar = new android.widget.ProgressBar(this, null, android.R.attr.progressBarStyleHorizontal);
            apkInstallProgressBar.setMax(100);
            apkInstallProgressBar.setProgress(0);
            content.addView(title, new LinearLayout.LayoutParams(-1, dp(26)));
            content.addView(apkInstallProgressLabel, new LinearLayout.LayoutParams(-1, dp(24)));
            content.addView(apkInstallProgressBar, new LinearLayout.LayoutParams(-1, dp(8)));
            apkInstallProgressBanner.addView(content, new FrameLayout.LayoutParams(dp(520), -2));
            FrameLayout.LayoutParams params = new FrameLayout.LayoutParams(dp(560), -2, Gravity.CENTER_HORIZONTAL | Gravity.BOTTOM);
            params.bottomMargin = dp(34);
            root.addView(apkInstallProgressBanner, params);
        });
    }

    private void updateApkInstallProgress(long copied, long total, String fileName) {
        if (total <= 0) return;
        int percent = (int) Math.max(0, Math.min(100, (copied * 100L) / total));
        runOnUiThread(() -> {
            if (apkInstallProgressBar == null || apkInstallProgressLabel == null) return;
            apkInstallProgressBar.setProgress(percent);
            apkInstallProgressLabel.setText(percent + " %  ·  " + fileName);
        });
    }

    private void hideApkInstallProgress() {
        if (apkInstallProgressBanner != null) {
            ViewGroup parent = apkInstallProgressBanner.getParent() instanceof ViewGroup ? (ViewGroup) apkInstallProgressBanner.getParent() : null;
            if (parent != null) parent.removeView(apkInstallProgressBanner);
        }
        apkInstallProgressBanner = null;
        apkInstallProgressLabel = null;
        apkInstallProgressBar = null;
    }

    private String getPackageNameFromApk(File apk) {
        try {
            PackageManager pm = getPackageManager();
            android.content.pm.PackageInfo info = pm.getPackageArchiveInfo(apk.getAbsolutePath(), 0);
            return info != null && info.packageName != null ? info.packageName : null;
        } catch (Exception ignored) {
            return null;
        }
    }

    private void maybeShowInstalledAppOverlay() {
        String packageName = pendingInstalledApkPackage;
        if (packageName == null) return;
        // onResume() may run while the system installer is still committing
        // the package. Keep the request alive and retry briefly instead of
        // dropping the Home-placement prompt.
        if (!isPackageInstalled(packageName)) {
            if (++pendingInstalledApkChecks > 30) {
                pendingInstalledApkPackage = null;
                pendingInstalledApkChecks = 0;
                return;
            }
            getWindow().getDecorView().postDelayed(this::maybeShowInstalledAppOverlay, 1000L);
            return;
        }
        pendingInstalledApkPackage = null;
        pendingInstalledApkChecks = 0;
        if (isAppFavorite(packageName)) return;

        String label = appLabel(packageName);
        if (label == null || label.isEmpty()) label = "Nouvelle application";

        LinearLayout panel = new LinearLayout(this);
        panel.setOrientation(LinearLayout.VERTICAL);
        panel.setPadding(dp(24), dp(24), dp(24), dp(24));
        panel.setBackground(panelOverlayBg());

        TextView title = text("Installation terminée", 20, white);
        title.setTypeface(null, Typeface.BOLD);
        panel.addView(title);

        panel.addView(space(12));
        panel.addView(text("L’application " + label + " a été installée.", 15, white));
        panel.addView(space(18));

        TextView launch = text("Ajouter aux favoris", 16, white);
        launch.setGravity(Gravity.CENTER);
        launch.setFocusable(true);
        launch.setBackground(cardBg());
        launch.setPadding(dp(16), dp(12), dp(16), dp(12));
        launch.setOnFocusChangeListener((v, focused) -> launch.setBackground(focused ? settingsOverlayFocusBg() : cardBg()));
        launch.setOnClickListener(v -> {
            // Add the newly installed app to the favorites bar only on request.
            try {
                Set<String> favorites = favoriteApps();
                favorites.add(packageName);
                saveFavoriteApps(favorites);
                Set<String> hidden = hiddenApps();
                if (hidden.remove(packageName))
                    homePrefs().edit().putStringSet("hidden_apps", hidden).apply();
                List<String> order = appOrder();
                order.removeAll(Collections.singleton(packageName));
                order.add(packageName);
                homePrefs().edit().putString(appOrderKey(), joinOrder(order)).apply();
                pendingFocusPackage = packageName;
            } catch (Exception ignored) {}
            removeOverlay(panel);
            goHome();
        });
        panel.addView(launch, new LinearLayout.LayoutParams(-1, dp(48)));

        TextView close = text("Fermer", 16, white);
        close.setGravity(Gravity.CENTER);
        close.setFocusable(true);
        close.setBackground(cardBg());
        close.setPadding(dp(16), dp(12), dp(16), dp(12));
        close.setOnFocusChangeListener((v, focused) -> close.setBackground(focused ? settingsOverlayFocusBg() : cardBg()));
        close.setOnClickListener(v -> removeOverlay(panel));
        LinearLayout.LayoutParams closeParams = new LinearLayout.LayoutParams(-1, dp(48));
        closeParams.topMargin = dp(12);
        panel.addView(close, closeParams);

        showModalOverlay(panel);
    }

    /** Opens the picker owned by the Android TV launcher, exactly like its + tile. */
    private void openAndroidTvAddAppLink(View returnFocus) {
        // The launcher-owned panel can keep a stale package snapshot after an
        // APK installation. Use our picker, which queries PackageManager at
        // click time and therefore includes newly installed launchable apps.
        showAndroidTvStyleAddFavoritesPicker(returnFocus);
    }

    private void showAndroidTvStyleAddFavoritesPicker(View returnFocus) {
        if (activePopup != null && activePopup.isShowing()) return;
        LinearLayout panel = new LinearLayout(this);
        panel.setOrientation(LinearLayout.VERTICAL);
        panel.setPadding(dp(14), dp(34), dp(14), dp(24));
        // Keep this picker visually aligned with Android TV's Sources panel.
        // This is intentionally a fixed system-panel shade, not a theme colour.
        panel.setBackgroundColor(Color.rgb(17, 20, 28));

        TextView title = text("Sélectionner une application", 18, white);
        title.setTypeface(null, Typeface.BOLD);
        title.setGravity(Gravity.CENTER_VERTICAL);
        title.setSingleLine(true);
        panel.addView(title, new LinearLayout.LayoutParams(-1, dp(48)));
        panel.addView(space(20));

        ScrollView scroll = new ScrollView(this);
        scroll.setFillViewport(true);
        scroll.setHorizontalScrollBarEnabled(false);
        scroll.setVerticalScrollBarEnabled(false);
        LinearLayout list = new LinearLayout(this);
        list.setOrientation(LinearLayout.VERTICAL);
        list.setClipChildren(false);
        list.setClipToPadding(false);

        for (android.content.pm.ResolveInfo info : favoriteAppCandidates()) {
            View option = androidTvStyleAppPickerOption(info);
            list.addView(option, new LinearLayout.LayoutParams(-1, dp(72)));
        }
        if (list.getChildCount() == 0) {
            TextView empty = text("Aucune application installée n’est disponible à ajouter.", 16, muted);
            empty.setGravity(Gravity.CENTER_VERTICAL);
            list.addView(empty, new LinearLayout.LayoutParams(-1, dp(72)));
        }
        scroll.addView(list);
        panel.addView(scroll, new LinearLayout.LayoutParams(-1, 0, 1f));

        // One third of the TV width keeps the heading on a single line while
        // preserving the panel's familiar right-side drawer presentation.
        int width = Math.max(dp(1), getResources().getDisplayMetrics().widthPixels / 3);
        PopupWindow popup = new PopupWindow(panel, width, -1, true);
        popup.setBackgroundDrawable(new android.graphics.drawable.ColorDrawable(Color.TRANSPARENT));
        popup.setOutsideTouchable(false);
        popup.setFocusable(true);
        popup.setElevation(dp(16));
        trackPopup(popup);
        popup.setOnDismissListener(() -> {
            if (pendingFocusPackage != null) {
                goHome();
                return;
            }
            if (returnFocus != null && returnFocus.isAttachedToWindow()) {
                returnFocus.post(returnFocus::requestFocus);
            }
        });
        final PopupWindow pickerPopup = popup;
        for (int index = 0; index < list.getChildCount(); index++) {
            View option = list.getChildAt(index);
            option.setOnKeyListener((v, keyCode, event) -> {
                if (event.getAction() == KeyEvent.ACTION_DOWN && keyCode == KeyEvent.KEYCODE_DPAD_LEFT) {
                    pickerPopup.dismiss();
                    return true;
                }
                return false;
            });
        }
        popup.showAtLocation(getWindow().getDecorView(), Gravity.END | Gravity.CENTER_VERTICAL, 0, 0);
        panel.post(() -> {
            View first = firstFocusableChild(list);
            if (first != null) first.requestFocus();
        });
    }

    private View androidTvStyleAppPickerOption(android.content.pm.ResolveInfo info) {
        LinearLayout row = new LinearLayout(this);
        row.setGravity(Gravity.CENTER_VERTICAL);
        row.setPadding(dp(8), 0, dp(8), 0);
        row.setFocusable(true);
        row.setClipChildren(false);
        row.setClipToPadding(false);
        row.setBackground(new GradientDrawable());

        FrameLayout iconStage = new FrameLayout(this);

        ImageView icon = new AppIconImageView(this);
        android.graphics.drawable.Drawable banner = info.activityInfo.loadBanner(getPackageManager());
        icon.setImageDrawable(banner != null ? banner : info.loadIcon(getPackageManager()));
        icon.setScaleType(ImageView.ScaleType.FIT_CENTER);
        iconStage.addView(icon, new FrameLayout.LayoutParams(-1, -1));
        row.addView(iconStage, new LinearLayout.LayoutParams(dp(58), dp(33)));

        TextView label = text(homeAppLabel(info), 16, white);
        label.setGravity(Gravity.CENTER_VERTICAL);
        label.setSingleLine(true);
        label.setHorizontallyScrolling(true);
        label.setEllipsize(TextUtils.TruncateAt.MARQUEE);
        label.setMarqueeRepeatLimit(-1);
        label.setPadding(dp(10), 0, 0, 0);
        row.addView(label, new LinearLayout.LayoutParams(0, -1, 1f));

        row.setOnFocusChangeListener((v, focused) -> {
            row.setBackground(focused ? settingsOverlayFocusBg() : new GradientDrawable());
            label.setSelected(focused);
        });
        row.setOnClickListener(v -> {
            String packageName = info.activityInfo.packageName;
            Set<String> favorites = favoriteApps();
            if (favorites.contains(packageName)) {
                Toast.makeText(this, "Application déjà présente dans les favoris", Toast.LENGTH_SHORT).show();
                return;
            }
            favorites.add(packageName);
            saveFavoriteApps(favorites);
            Set<String> hidden = hiddenApps();
            if (hidden.remove(packageName))
                homePrefs().edit().putStringSet("hidden_apps", hidden).apply();
            List<String> order = appOrder();
            if (!order.contains(packageName)) {
                order.add(packageName);
                homePrefs().edit().putString(appOrderKey(), joinOrder(order)).apply();
            }
            pendingFocusPackage = packageName;
            Toast.makeText(this, "Application ajoutée aux favoris", Toast.LENGTH_SHORT).show();
            row.requestFocus();
        });
        return row;
    }

    /**
     * Show every launchable user app in the Home '+' picker, including apps
     * already present on the Applications rail. The click handlers prevent a
     * duplicate favorite from being added again.
     */
    private List<android.content.pm.ResolveInfo> favoriteAppCandidates() {
        List<android.content.pm.ResolveInfo> result = new ArrayList<>();
        for (android.content.pm.ResolveInfo info : allLaunchableApps()) {
            if (info == null || info.activityInfo == null) continue;
            String packageName = info.activityInfo.packageName;
            ApplicationInfo application = info.activityInfo.applicationInfo;
            if (isPreinstalledSystemApp(application) && !packageName.equals(getPackageName())) continue;
            result.add(info);
        }
        return result;
    }

    private boolean isPackageInstalled(String packageName) {
        try {
            getPackageManager().getPackageInfo(packageName, 0);
            return true;
        } catch (PackageManager.NameNotFoundException ignored) {
            return false;
        }
    }

    private Set<String> favoriteApps() {
        android.content.SharedPreferences prefs = homePrefs();
        if (prefs.getInt("favorite_apps_version", 0) >= 3) {
            return new HashSet<>(prefs.getStringSet("favorite_apps", new HashSet<>()));
        }
        // Older builds did not persist a distinct favorites list. Rebuild the
        // current home safely from installed apps, while converting former
        // hidden favorites into ordinary side-menu applications.
        Set<String> favorites = new HashSet<>();
        Set<String> legacyHidden = hiddenApps();
        Set<String> installed = new HashSet<>();
        for (android.content.pm.ResolveInfo info : allLaunchableApps()) {
            String packageName = info.activityInfo.packageName;
            installed.add(packageName);
            if (!packageName.equals(getPackageName()) && !legacyHidden.contains(packageName)) favorites.add(packageName);
        }
        // In previous releases, removing a favorite incorrectly put it in
        // hidden_apps. Make those installed applications visible in the side
        // menu again; retain only stale entries for uninstalled packages.
        legacyHidden.removeAll(installed);
        prefs.edit().putStringSet("favorite_apps", favorites).putStringSet("hidden_apps", legacyHidden).putInt("favorite_apps_version", 3).apply();
        return favorites;
    }
    private void saveFavoriteApps(Set<String> favorites) { homePrefs().edit().putStringSet("favorite_apps", new HashSet<>(favorites)).putInt("favorite_apps_version", 3).apply(); }
    private boolean isAppFavorite(String packageName) { return packageName != null && !packageName.isEmpty() && favoriteApps().contains(packageName); }

    private void showModalOverlay(View content) {
        PopupWindow popup = new PopupWindow(content, dp(520), -2, true);
        popup.setBackgroundDrawable(new android.graphics.drawable.ColorDrawable(Color.TRANSPARENT));
        popup.setOutsideTouchable(false);
        popup.setFocusable(true);
        popup.setElevation(dp(16));
        trackPopup(popup);
        popup.showAtLocation(getWindow().getDecorView(), Gravity.CENTER, 0, 0);
        content.post(() -> {
            if (content instanceof ViewGroup) {
                View firstFocusable = findFirstFocusable(content);
                if (firstFocusable != null) firstFocusable.requestFocus();
            }
        });
    }

    private View findFirstFocusable(View view) {
        if (view.isFocusable()) return view;
        if (view instanceof ViewGroup) {
            for (int i = 0; i < ((ViewGroup) view).getChildCount(); i++) {
                View candidate = findFirstFocusable(((ViewGroup) view).getChildAt(i));
                if (candidate != null) return candidate;
            }
        }
        return null;
    }

    private void removeOverlay(View content) {
        if (content == null || content.getParent() == null) return;
        try {
            PopupWindow popup = activePopup;
            if (popup != null && popup.isShowing()) popup.dismiss();
        } catch (Exception ignored) {
        }
    }
    private void openLocalDirectory(File directory) {
        if (isAndroidDataDirectory(directory)) {
            if (isFireOsDevice()) openScreen(createLocalBrowser(directory));
            else openScreen(createShizukuBrowser(directory.getAbsolutePath()));
        } else if (!hasSharedStorageAccess()) requestSharedStorageAccess(); else openScreen(createLocalBrowser(directory));
    }
    private boolean isAndroidDataDirectory(File directory) { if (directory == null) return false; try { return directory.getCanonicalPath().equals(new File(androidDataPath()).getCanonicalPath()); } catch (Exception ignored) { return directory.getAbsolutePath().equals(androidDataPath()); } }
    private View localFileRow(File file) { boolean directory = file.isDirectory(); String name = cleanFileName(file.getName()); String detail = directory ? fileDate(file.lastModified()) : fileKind(name, false) + " · " + formatStorageSize(file.length()) + " · " + fileDate(file.lastModified()); FileClipboard item = new FileClipboard(file); View row = browserRow(fileIcon(name, directory), name, detail, null); attachMultiSelectionBadge((FrameLayout) row, item); row.setOnClickListener(v -> { if (multiSelectMode) { toggleMultiSelection(item, row); return; } if (directory) openLocalDirectory(file); else if (isPdfFile(name)) openScreen(createPdfViewer(file)); else openLocalFile(file); }); if (directory) loadLocalFolderArtwork(file, (ImageView) row.getTag()); else if (isImageFile(name)) loadLocalThumbnail((ImageView) row.getTag(), file); else if (isVideoFile(name) && !isMovVideoFile(name)) loadVideoArtwork((ImageView) row.getTag(), name, true, file.getParent(), localVideoFrameSource(file)); row.setOnLongClickListener(v -> { showLocalFileMenu(file, row); return true; }); return row; }
    private View localFileTile(File file) { boolean directory = file.isDirectory(); String name = cleanFileName(file.getName()); String detail = directory ? fileDate(file.lastModified()) + "\n" + localFolderContentsSummary(file) : fileKind(name, false) + " · " + formatStorageSize(file.length()) + "\n" + fileDate(file.lastModified()); FileClipboard item = new FileClipboard(file); View tile = browserTile(fileIcon(name, directory), name, detail, null); attachMultiSelectionBadge((FrameLayout) tile, item); tile.setOnClickListener(v -> { if (multiSelectMode) { toggleMultiSelection(item, tile); return; } if (directory) openLocalDirectory(file); else if (isPdfFile(name)) openScreen(createPdfViewer(file)); else openLocalFile(file); }); if (directory) loadLocalFolderArtwork(file, (ImageView) tile.getTag()); else if (isImageFile(name)) loadLocalThumbnail((ImageView) tile.getTag(), file); else if (isVideoFile(name) && !isMovVideoFile(name)) loadVideoArtwork((ImageView) tile.getTag(), name, true, file.getParent(), localVideoFrameSource(file)); tile.setOnLongClickListener(v -> { showLocalFileMenu(file, tile); return true; }); return tile; }
    private View createSmbSetup() { return createSmbConnectionsPage(); }
    private View createSmbConnectionsPage() {
        FrameLayout page = createSettingsShell("Lecteurs SMB", "Ouvrez un partage réseau ou modifiez ses paramètres de connexion.");
        LinearLayout content = (LinearLayout) page.getTag();
        LinearLayout actions = new LinearLayout(this);
        TextView add = settingsAction("Ajouter un lecteur", true, v -> openScreen(createSmbConnectionEditor(null)));
        add.setTag("smb_connection_add");
        TextView discover = settingsAction("Découvrir le réseau", false, v -> openScreen(createSmbDiscoveryPage()));
        actions.addView(add, new LinearLayout.LayoutParams(0, dp(48), 1f));
        actions.addView(spaceWidth(12));
        actions.addView(discover, new LinearLayout.LayoutParams(0, dp(48), 1f));
        content.addView(actions);
        content.addView(space(16));
        ScrollView scroll = new ScrollView(this); scroll.setFillViewport(true); scroll.setVerticalScrollBarEnabled(false);
        LinearLayout list = new LinearLayout(this); list.setOrientation(LinearLayout.VERTICAL);
        scroll.addView(list); content.addView(scroll, new LinearLayout.LayoutParams(-1, 0, 1f));
        List<SmbConnectionConfig> connections = smbConnections();
        if (connections.isEmpty()) {
            list.addView(text("Aucun lecteur réseau enregistré.\nAjoutez un serveur et le nom de son partage.", 16, SettingsPresentation.secondaryTextColor()));
        } else {
            for (int index = 0; index < connections.size(); index++) {
                final int connectionIndex = index;
                SmbConnectionConfig connection = connections.get(index);
                LinearLayout row = new LinearLayout(this); row.setGravity(Gravity.CENTER_VERTICAL);
                TextView open = settingsRow(connection.displayLabel(), connection.normalizedServer(), v -> openSmbConnectionBrowser(connection));
                open.setOnLongClickListener(v -> { openScreen(createSmbConnectionEditor(connection)); return true; });
                styleSettingsControl(open);
                row.addView(open, new LinearLayout.LayoutParams(0, dp(72), 1f));
                row.addView(spaceWidth(12));
                TextView edit = settingsAction("Modifier", false, v -> openScreen(createSmbConnectionEditor(connection)));
                row.addView(edit, new LinearLayout.LayoutParams(dp(110), dp(48)));
                row.addView(spaceWidth(12));
                TextView remove = settingsAction("Supprimer", false, v -> confirmSmbConnectionRemoval(connectionIndex, connection));
                remove.setTag("smb_connection_delete_" + connectionIndex);
                row.addView(remove, new LinearLayout.LayoutParams(dp(132), dp(48)));
                open.setNextFocusRightId(edit.getId()); edit.setNextFocusLeftId(open.getId());
                edit.setNextFocusRightId(remove.getId()); remove.setNextFocusLeftId(edit.getId());
                remove.setNextFocusRightId(remove.getId());
                LinearLayout.LayoutParams params = new LinearLayout.LayoutParams(-1, -2); params.bottomMargin = dp(10);
                list.addView(row, params);
            }
        }
        finishSettingsPage(page, content);
        return page;
    }
    private void confirmSmbConnectionRemoval(int index, SmbConnectionConfig connection) {
        showDeleteConfirm(connection.displayLabel(), "Cette connexion sera retirée des appareils synchronisés avec ce compte. Les fichiers du serveur seront conservés.", () -> {
            List<SmbConnectionConfig> connections = smbConnections();
            if (index >= connections.size() || !connections.get(index).label.equals(connection.label)
                    || !connections.get(index).matches(connection.browserUrl(), connection.user, connection.password)) {
                Toast.makeText(this, "La liste des lecteurs a changé. Sélectionnez à nouveau le lecteur à supprimer.", Toast.LENGTH_LONG).show();
                replaceScreen(createSmbConnectionsPage());
                return;
            }
            connections.remove(index);
            saveSmbConnections(connections);
            syncHomeSettingsToNas();
            pendingSettingsFocus = connections.isEmpty() ? "smb_connection_add"
                    : "smb_connection_delete_" + Math.min(index, connections.size() - 1);
            replaceScreen(createSmbConnectionsPage());
        });
    }
    private View createSmbDiscoveryPage() {
        FrameLayout page = createSettingsShell("Découverte du réseau", "Recherchez les partages SMB disponibles sur le réseau local.");
        LinearLayout content = (LinearLayout) page.getTag();
        TextView state = text("Appuyez sur Rechercher pour commencer.", 16, SettingsPresentation.secondaryTextColor()); content.addView(state, new LinearLayout.LayoutParams(-1, dp(54)));
        ScrollView scroll = new ScrollView(this); scroll.setVerticalScrollBarEnabled(false);
        LinearLayout results = new LinearLayout(this); results.setOrientation(LinearLayout.VERTICAL); scroll.addView(results); content.addView(scroll, new LinearLayout.LayoutParams(-1, 0, 1f));
        TextView scan = settingsAction("Rechercher", true, null); content.addView(scan, new LinearLayout.LayoutParams(dp(240), dp(48)));
        scan.setOnClickListener(v -> {
            scan.setEnabled(false); state.setText("Recherche en cours… (maximum 12 secondes)"); results.removeAllViews();
            new Thread(() -> {
                List<String> hosts = NetworkDiscovery.discoverSmbHosts();
                runOnUiThread(() -> {
                    scan.setEnabled(true); results.removeAllViews();
                    if (hosts.isEmpty()) { state.setText("Aucun appareil SMB trouvé sur le réseau local."); return; }
                    state.setText(hosts.size() + " appareil(s) SMB trouvé(s). Sélectionnez-en un pour saisir son partage et ses identifiants.");
                    for (String host : hosts) {
                        TextView row = settingsRow(host, "Dossier partagé à préciser", view -> openScreen(createSmbConnectionEditor(new SmbConnectionConfig("PC " + host, host, "", ""))));
                        styleSettingsControl(row);
                        LinearLayout.LayoutParams params = new LinearLayout.LayoutParams(-1, dp(72)); params.bottomMargin = dp(10);
                        results.addView(row, params);
                    }
                    finishSettingsPage(page, content);
                    results.post(() -> focusFirst(results));
                });
            }, "JojoHomeNetworkDiscovery").start();
        });
        finishSettingsPage(page, content);
        return page;
    }
    private View createSmbConnectionEditor(SmbConnectionConfig current) {
        SmbConnectionConfig[] editedConnection = { current };
        FrameLayout page = createSettingsShell(current == null ? "Nouveau lecteur SMB" : "Modifier le lecteur SMB", "Indiquez le serveur et son partage, par exemple 192.168.1.254/Partage.");
        LinearLayout content = (LinearLayout) page.getTag();
        ScrollView formScroll = new ScrollView(this); formScroll.setFillViewport(true); formScroll.setVerticalScrollBarEnabled(false);
        LinearLayout form = new LinearLayout(this); form.setOrientation(LinearLayout.VERTICAL); form.setPadding(dp(2), dp(2), dp(2), 0);
        formScroll.addView(form); content.addView(formScroll, new LinearLayout.LayoutParams(-1, 0, 1f));
        LinearLayout columns = new LinearLayout(this);
        LinearLayout left = new LinearLayout(this); left.setOrientation(LinearLayout.VERTICAL);
        LinearLayout right = new LinearLayout(this); right.setOrientation(LinearLayout.VERTICAL);
        columns.addView(left, new LinearLayout.LayoutParams(0, -2, 1f)); columns.addView(spaceWidth(16)); columns.addView(right, new LinearLayout.LayoutParams(0, -2, 1f)); form.addView(columns);
        EditText label = settingsField(left, "Nom du lecteur", "Ex. PC Bureau");
        EditText server = settingsField(right, "Adresse SMB", "192.168.1.254/Partage");
        EditText user = settingsField(left, "Identifiant", "Facultatif pour un accès invité");
        EditText password = settingsField(right, "Mot de passe", "Mot de passe du partage");
        label.setText(current == null ? "NAS" : current.displayLabel()); server.setText(current == null ? homePrefs().getString("smb_server", "") : current.server); user.setText(current == null ? homePrefs().getString("smb_user", "") : current.user); password.setText(current == null ? homePrefs().getString("smb_password", "") : current.password);
        password.setInputType(android.text.InputType.TYPE_CLASS_TEXT | android.text.InputType.TYPE_TEXT_VARIATION_PASSWORD);
        TextView loginHelp = text("Windows : PC\\utilisateur ou MicrosoftAccount\\adresse e-mail. Mot de passe du compte, pas le code PIN.", 13, SettingsPresentation.secondaryTextColor());
        LinearLayout.LayoutParams loginHelpParams = new LinearLayout.LayoutParams(-1, -2); loginHelpParams.topMargin = dp(10); form.addView(loginHelp, loginHelpParams);
        TextView state = text("Vous pouvez tester la connexion avant de l’enregistrer.", 14, SettingsPresentation.secondaryTextColor());
        state.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);
        LinearLayout.LayoutParams stateParams = new LinearLayout.LayoutParams(-1, -2); stateParams.topMargin = dp(10); stateParams.bottomMargin = dp(12); content.addView(state, stateParams);
        LinearLayout actions = new LinearLayout(this);
        TextView test = settingsAction("Tester la connexion", false, null);
        TextView save = settingsAction("Enregistrer", true, null);
        actions.addView(test, new LinearLayout.LayoutParams(0, dp(48), 1f)); actions.addView(spaceWidth(12)); actions.addView(save, new LinearLayout.LayoutParams(0, dp(48), 1f)); content.addView(actions);
        save.setOnClickListener(v -> {
            String value = server.getText().toString().trim();
            if (value.isEmpty()) { state.setText("Indiquez l’adresse du serveur et le nom du partage."); state.setTextColor(SettingsPresentation.errorTextColor()); server.requestFocus(); return; }
            String name = label.getText().toString().trim();
            String login = user.getText().toString();
            String secret = password.getText().toString();
            List<SmbConnectionConfig> connections = smbConnections();
            SmbConnectionConfig savedConnection = new SmbConnectionConfig(name.isEmpty() ? SmbConnectionConfig.defaultLabelForServer(value) : name, value, login, secret);
            int existingIndex = -1;
            for (int index = 0; index < connections.size() && editedConnection[0] != null; index++) {
                SmbConnectionConfig candidate = connections.get(index);
                if (candidate.label.equals(editedConnection[0].label)
                        && candidate.matches(editedConnection[0].browserUrl(), editedConnection[0].user, editedConnection[0].password)) {
                    existingIndex = index;
                    break;
                }
            }
            if (existingIndex < 0) {
                for (int index = 0; index < connections.size(); index++) {
                    SmbConnectionConfig candidate = connections.get(index);
                    if (candidate.browserUrl().equals(savedConnection.browserUrl()) && candidate.user.equals(savedConnection.user)) {
                        existingIndex = index;
                        break;
                    }
                }
            }
            if (existingIndex < 0) connections.add(savedConnection);
            else connections.set(existingIndex, savedConnection);
            saveSmbConnections(connections);
            editedConnection[0] = savedConnection;
            syncHomeSettingsToNas();
            openSmbConnectionBrowser(savedConnection);
         });
        test.setOnClickListener(v -> {
            String value = server.getText().toString().trim();
            if (value.isEmpty()) { state.setText("Indiquez l’adresse du serveur et le nom du partage."); state.setTextColor(SettingsPresentation.errorTextColor()); server.requestFocus(); return; }
            String login = user.getText().toString(); String secret = password.getText().toString();
            test.setEnabled(false); test.setAlpha(.55f); state.setTextColor(SettingsPresentation.secondaryTextColor()); state.setText("Test de connexion en cours…");
            new Thread(() -> {
                try {
                    String root = SmbConnectionConfig.browserUrlFor(value);
                    jcifs.smb.SmbFile target = new jcifs.smb.SmbFile(root, smbContext(login, secret));
                    target.listFiles();
                    runOnUiThread(() -> { test.setEnabled(true); test.setAlpha(1f); state.setTextColor(SettingsPresentation.textColor()); state.setText("✓  Connexion réussie. Vous pouvez enregistrer ce lecteur."); });
                } catch (Exception error) {
                    android.util.Log.e("JojoHomeSmb", "SMB connection test failed for " + value, error);
                    boolean logonFailure = error instanceof jcifs.smb.SmbAuthException
                            && ((jcifs.smb.SmbAuthException) error).getNtStatus() == jcifs.smb.NtStatus.NT_STATUS_LOGON_FAILURE;
                    String message = logonFailure ? "Authentification SMB refusée. Vérifiez l’identifiant et le mot de passe du compte."
                            : "Connexion SMB refusée. Vérifiez l’adresse, le partage et les identifiants.";
                    runOnUiThread(() -> { test.setEnabled(true); test.setAlpha(1f); state.setTextColor(SettingsPresentation.errorTextColor()); state.setText(message); });
                }
            }, "JojoHomeSmbConnectionTest").start();
        });
        label.setNextFocusRightId(server.getId()); server.setNextFocusLeftId(label.getId());
        label.setNextFocusDownId(user.getId()); server.setNextFocusDownId(password.getId());
        user.setNextFocusUpId(label.getId()); password.setNextFocusUpId(server.getId());
        user.setNextFocusRightId(password.getId()); password.setNextFocusLeftId(user.getId());
        user.setNextFocusDownId(test.getId()); password.setNextFocusDownId(save.getId());
        test.setNextFocusUpId(user.getId()); save.setNextFocusUpId(password.getId()); test.setNextFocusRightId(save.getId());
        server.setTag("smb_server_field"); pendingSettingsFocus = "smb_server_field";
        finishSettingsPage(page, content); save.setNextFocusLeftId(test.getId()); return page;
    }
    private EditText smbField(String hint) { EditText field = new EditText(this); field.setSingleLine(true); field.setTextColor(white); field.setTextSize(17); field.setHint(hint); field.setHintTextColor(muted); field.setPadding(dp(14), 0, dp(14), 0); field.setBackgroundColor(Color.rgb(37, 57, 103)); field.setFocusable(true); return field; }
