    private SmbEntryMetadata readSmbEntryMetadata(jcifs.smb.SmbFile file) {
        String rawName = file.getName();
        boolean directory = rawName.endsWith("/");
        boolean videosFolder = false;
        long modified = 0L, size = -1L;
        try {
            directory = file.isDirectory();
            modified = file.getLastModified();
            size = directory ? 0L : file.length();
            videosFolder = directory && isSmbFolderInsideVideos(file);
        } catch (Exception error) {
            android.util.Log.w("JojoHomeSmb", "Could not read SMB attributes for " + file.getPath(), error);
        }
        return new SmbEntryMetadata(cleanFileName(rawName), directory, videosFolder, modified, size);
    }
    private String smbEntryDetail(SmbEntryMetadata entry, boolean grid) {
        String detail = entry.directory ? "" : fileKind(entry.name, false);
        if (!entry.directory && entry.size >= 0L) detail += " · " + formatStorageSize(entry.size);
        if (entry.modified > 0L) detail += (detail.isEmpty() ? "" : grid ? "\n" : " · ") + fileDate(entry.modified);
        return detail;
    }
    private View createSmbBrowser(String url, String user, String password) {
        boolean gridMode = filesGridMode(smbFolderLayoutKey(url));
        LinearLayout page = pickerPage("Réseau SMB", "", 10);
        LinearLayout browserHeader = smbBrowserHeaderPlain(url, user, password);
        placeBrowserHeaderInTitle(page, "Réseau SMB", browserHeader);
        LinearLayout content = (LinearLayout) page.getTag();
        ScrollView scroll = new ScrollView(this);
        scroll.setVerticalScrollBarEnabled(false);
        scroll.setHorizontalScrollBarEnabled(false);
        LinearLayout list = new LinearLayout(this); list.setOrientation(LinearLayout.VERTICAL); list.addView(text("Connexion…", 16, muted));
        rememberBrowserList(page, list);
        Runnable updateVisiblePhotoThumbnails = observeSmbPhotoThumbnails(scroll, list);
        scroll.addView(list); content.addView(scroll, new LinearLayout.LayoutParams(-1, 0, 1f));
        java.util.concurrent.atomic.AtomicBoolean smbLoadFinished = new java.util.concurrent.atomic.AtomicBoolean(false);
        java.util.concurrent.atomic.AtomicReference<String> smbLoadStage = new java.util.concurrent.atomic.AtomicReference<>("connexion");
        long smbLoadStartedAt = android.os.SystemClock.elapsedRealtime();
        list.postDelayed(() -> {
            if (smbLoadFinished.get() || !list.isAttachedToWindow()) return;
            // This is a slow-load notice, not a failed connection. A successful
            // listing must still be published after this notice appears.
            android.util.Log.w("JojoHomeSmb", "SMB_BROWSER_SLOW stage=" + smbLoadStage.get()
                    + " elapsedMs=" + (android.os.SystemClock.elapsedRealtime() - smbLoadStartedAt));
            list.removeAllViews();
            View waiting = empty("Lecture du partage SMB en cours… Patientez ou appuyez sur Retour.");
            waiting.setFocusable(true);
            waiting.setOnClickListener(v -> goBackScreen());
            list.addView(waiting);
            waiting.requestFocus();
        }, 15000L);
        new Thread(() -> {
            try {
                // Use the same network timeout as the successful settings test.
                final jcifs.CIFSContext context = smbContext(user, password);
                jcifs.smb.SmbFile folder = new jcifs.smb.SmbFile(url, context);
                smbLoadStage.set("liste");
                java.util.Map<String, SmbEntryMetadata> entryMetadata = new java.util.HashMap<>();
                // Capture attributes during enumeration while jcifs still has
                // them cached, instead of querying every file after they expire.
                jcifs.smb.SmbFile[] entries = folder.listFiles(entry -> {
                    entryMetadata.put(entry.getPath(), readSmbEntryMetadata(entry));
                    return true;
                });
                android.util.Log.i("JojoHomeSmb", "SMB_BROWSER_LIST_OK entries=" + entries.length
                        + " elapsedMs=" + (android.os.SystemClock.elapsedRealtime() - smbLoadStartedAt));
                smbLoadStage.set("préparation");
                if (isVideosFolderPath(url)) reconcileFreeboxListing(folder.getPath(), entries, context);
                // Do not block the folder listing on getDiskFreeSpace(). On
                // some Freebox folders this call never answers promptly, so
                // the screen stayed on "Connexion…" even though listFiles()
                // could already return the HEIC files.
                final long[] capacity = new long[] {
                        homePrefs().getLong("smb_free", -1L),
                        homePrefs().getLong("smb_total", -1L)
                };
                java.util.Map<String, Long> durations = new java.util.concurrent.ConcurrentHashMap<>();
                java.util.Map<String, String> durationKeys = new java.util.HashMap<>();
                final boolean chronologicalEpisodes = !isVideosFolderPath(url) && containsEpisodeNames(entries, entryMetadata);
                for (jcifs.smb.SmbFile entry : entries) try {
                    SmbEntryMetadata metadata = entryMetadata.get(entry.getPath());
                    if (metadata.directory || !isVideoFile(metadata.name) || metadata.size < 0L) continue;
                    String key = smbVideoDurationCacheKey(entry.getPath(), metadata.size, metadata.modified);
                    durationKeys.put(entry.getPath(), key);
                    durations.put(entry.getPath(), getSharedPreferences("smb_video_durations", MODE_PRIVATE).getLong(key, -1L));
                } catch (Exception ignored) { }
                java.util.Map<String, View> renderedEntries = new java.util.HashMap<>();
                Runnable renderEntries = () -> {
                if (!list.isAttachedToWindow()) return;
                java.util.Map<String, Long> displayedDurations = new java.util.HashMap<>(durations);
                // Duration enrichment can trigger a second render shortly
                // after the first listing. Keep already decoded SMB artwork
                // attached to the corresponding path instead of replacing it
                // with the folder/video placeholder while the new request is
                // running.
                java.util.Map<String, android.graphics.drawable.Drawable> preservedArtwork = new java.util.HashMap<>();
                for (java.util.Map.Entry<String, View> item : renderedEntries.entrySet()) {
                    Object tagged = item.getValue().getTag();
                    if (!(tagged instanceof ImageView)) continue;
                    android.graphics.drawable.Drawable drawable = ((ImageView) tagged).getDrawable();
                    if (drawable instanceof android.graphics.drawable.BitmapDrawable) {
                        preservedArtwork.put(item.getKey(), drawable);
                    }
                }
                java.util.Comparator<jcifs.smb.SmbFile> entryOrder = (a, b) -> {
                    try {
                        boolean aDirectory = entryMetadata.get(a.getPath()).directory;
                        boolean bDirectory = entryMetadata.get(b.getPath()).directory;
                        if (aDirectory != bDirectory) return aDirectory ? -1 : 1;
                        boolean aVideo = !aDirectory && isVideoFile(cleanFileName(a.getName()));
                        boolean bVideo = !bDirectory && isVideoFile(cleanFileName(b.getName()));
                        if (aVideo != bVideo) {
                            return aVideo ? -1 : 1;
                        }
                        if (aVideo) {
                            if (chronologicalEpisodes) {
                                long leftEpisode = smbEpisodeSortKey(cleanFileName(a.getName()));
                                long rightEpisode = smbEpisodeSortKey(cleanFileName(b.getName()));
                                int episodeOrder = Long.compare(leftEpisode, rightEpisode);
                                if (episodeOrder != 0) return episodeOrder;
                            }
                            long left = displayedDurations.getOrDefault(a.getPath(), -1L);
                            long right = displayedDurations.getOrDefault(b.getPath(), -1L);
                            int order = Long.compare(left > 0L ? left : Long.MAX_VALUE,
                                    right > 0L ? right : Long.MAX_VALUE);
                            if (order != 0) return order;
                        }
                        return cleanFileName(a.getName()).compareToIgnoreCase(cleanFileName(b.getName()));
                    } catch (Exception ignored) { return 0; }
                };
                    boolean initial = renderedEntries.isEmpty();
                    String focusedPath = null;
                    for (java.util.Map.Entry<String, View> item : renderedEntries.entrySet()) {
                        if (item.getValue().hasFocus()) { focusedPath = item.getKey(); break; }
                    }
                    java.util.Arrays.sort(entries, entryOrder);
                    renderedEntries.clear();
                    list.removeAllViews();
                    ((TextView) browserHeader.getTag()).setText("NAS : " + storageCapacityLabel(capacity[0], capacity[1]));
                    android.widget.GridLayout grid = gridMode ? new android.widget.GridLayout(this) : null;
                    if (grid != null) grid.setColumnCount(7);
                    int shown = 0;
                    for (jcifs.smb.SmbFile entry : entries) try {
                        if (!"IPC$".equalsIgnoreCase(cleanFileName(entry.getName()))
                                && (showHiddenFiles() || !isHiddenName(cleanFileName(entry.getName())))) {
                            long durationMs = displayedDurations.getOrDefault(entry.getPath(), -1L);
                            SmbEntryMetadata metadata = entryMetadata.get(entry.getPath());
                            View entryView = grid != null ? smbTile(entry, metadata, context, user, password, durationMs)
                                    : smbRow(entry, metadata, context, user, password, durationMs);
                            android.graphics.drawable.Drawable artwork = preservedArtwork.get(entry.getPath());
                            if (artwork != null && entryView.getTag() instanceof ImageView) {
                                ImageView icon = (ImageView) entryView.getTag();
                                icon.setImageDrawable(artwork);
                                if (!metadata.directory && isImageFile(metadata.name)
                                        && artwork instanceof android.graphics.drawable.BitmapDrawable
                                        && ((android.graphics.drawable.BitmapDrawable) artwork).getBitmap() != null) {
                                    icon.setTag(R.id.smb_photo_thumbnail_status, "loaded");
                                }
                            }
                            renderedEntries.put(entry.getPath(), entryView);
                            if (grid != null) addFileGridTile(grid, entryView);
                            else list.addView(entryView, new LinearLayout.LayoutParams(-1, dp(52)));
                            shown++;
                        }
                    } catch (Exception ignored) { }
                    String smbPath = Uri.parse(url).getPath();
                    if (smbPath == null || smbPath.isEmpty() || "/".equals(smbPath)) {
                        View refresh = browserHeader.getChildAt(1);
                        for (jcifs.smb.SmbFile entry : entries) {
                            if (!"Freebox".equalsIgnoreCase(cleanFileName(entry.getName()))) continue;
                            View freeboxTile = renderedEntries.get(entry.getPath());
                            if (freeboxTile != null && refresh.isFocusable()) {
                                if (freeboxTile.getId() == View.NO_ID) freeboxTile.setId(View.generateViewId());
                                freeboxTile.setNextFocusRightId(refresh.getId());
                            }
                            break;
                        }
                    }
                    if (grid != null && grid.getChildCount() > 0) {
                        list.addView(grid);
                        wireGridBrowserHeaderFocus(page, grid);
                        wireBrowserHeaderDownToFirst(page, grid.getChildAt(0));
                    }
                    if (shown == 0) list.addView(empty("Aucun dossier ou fichier dans ce partage."));
                    if (grid == null) { wirePickerBackFocus(page, list); wireBrowserHeaderDownToFirst(page, list.getChildAt(0)); }
                    View restoreFocus = focusedPath == null ? null : renderedEntries.get(focusedPath);
                    if (restoreFocus != null) restoreFocus.requestFocus();
                    else if (initial) list.post(() -> focusInitialBrowserEntry(page));
                    updateVisiblePhotoThumbnails.run();
                };
                // Publish cached durations immediately; media probing must not
                // hold the folder on its connection screen.
                jcifs.smb.SmbFile[] entriesToEnrich = entries.clone();
                smbLoadStage.set("affichage");
                smbLoadFinished.set(true);
                runOnUiThread(renderEntries);
                for (jcifs.smb.SmbFile entry : entriesToEnrich) {
                    if (!list.isAttachedToWindow()) return;
                    String key = durationKeys.get(entry.getPath());
                    if (key == null || durations.getOrDefault(entry.getPath(), -1L) > 0L) continue;
                    long duration = readSmbVideoDurationMs(entry);
                    if (duration > 0L) {
                        durations.put(entry.getPath(), duration);
                        // Publish each result without waiting for the other new files.
                        list.removeCallbacks(renderEntries);
                        list.post(renderEntries);
                    }
                }
            } catch (Exception error) {
                smbLoadFinished.set(true);
                String detail = error.getMessage(); if (detail == null || detail.trim().isEmpty()) detail = error.getClass().getSimpleName();
                android.util.Log.e("JojoHomeSmb", "SMB browser failed for " + url + " stage=" + smbLoadStage.get()
                        + " elapsedMs=" + (android.os.SystemClock.elapsedRealtime() - smbLoadStartedAt), error);
                final String message = detail.length() > 130 ? detail.substring(0, 130) : detail;
                runOnUiThread(() -> { if (!list.isAttachedToWindow()) return; list.removeAllViews(); View failure = empty("Connexion SMB refusée : " + message); failure.setFocusable(true); failure.setOnClickListener(v -> goBackScreen()); list.addView(failure); failure.requestFocus(); });
            }
        }, "JojoHomeSmbBrowser").start();
        return page;
    }
    private String smbVideoDurationCacheKey(jcifs.smb.SmbFile file) throws jcifs.smb.SmbException {
        // A replacement recording with the same name must get a new duration.
        return smbVideoDurationCacheKey(file.getPath(), file.length(), file.getLastModified());
    }
    private String smbVideoDurationCacheKey(String path, long size, long modified) {
        return "smb_video_duration_" + path + "|" + size + "|" + modified;
    }
    private boolean containsEpisodeNames(jcifs.smb.SmbFile[] entries, java.util.Map<String, SmbEntryMetadata> entryMetadata) {
        int numberedEpisodes = 0;
        for (jcifs.smb.SmbFile entry : entries) {
            try {
                SmbEntryMetadata metadata = entryMetadata.get(entry.getPath());
                if (!metadata.directory && isVideoFile(metadata.name)
                        && smbEpisodeSortKey(metadata.name) != Long.MAX_VALUE) {
                    numberedEpisodes++;
                    if (numberedEpisodes >= 2) return true;
                }
            } catch (Exception ignored) { }
        }
        return false;
    }
    private long smbEpisodeSortKey(String name) {
        String value = name == null ? "" : name;
        java.util.regex.Matcher matcher = java.util.regex.Pattern.compile("(?i)\\bs(\\d{1,2})\\s*e(\\d{1,3})\\b").matcher(value);
        if (matcher.find()) return episodeSortKey(Integer.parseInt(matcher.group(1)), Integer.parseInt(matcher.group(2)));
        matcher = java.util.regex.Pattern.compile("(?i)\\b(\\d{1,2})x(\\d{1,3})\\b").matcher(value);
        if (matcher.find()) return episodeSortKey(Integer.parseInt(matcher.group(1)), Integer.parseInt(matcher.group(2)));
        matcher = java.util.regex.Pattern.compile("(?i)\\b(?:e|ep|episode|épisode)[ ._-]*(\\d{1,3})\\b").matcher(value);
        if (matcher.find()) return episodeSortKey(1, Integer.parseInt(matcher.group(1)));
        matcher = java.util.regex.Pattern.compile("^\\s*(\\d{1,3})(?:[ ._-]+)").matcher(value);
        if (matcher.find()) return episodeSortKey(1, Integer.parseInt(matcher.group(1)));
        return Long.MAX_VALUE;
    }
    private long episodeSortKey(int season, int episode) {
        return Math.max(0, season) * 1_000_000L + Math.max(0, episode);
    }
    private long readSmbVideoDurationMs(jcifs.smb.SmbFile file) {
        VideoFrameSession session = null;
        try {
            String cacheKey = null;
            try { cacheKey = smbVideoDurationCacheKey(file); }
            catch (Exception ignored) { /* Metadata unavailable; the video can still be probed. */ }
            if (cacheKey != null) {
                long cached = getSharedPreferences("smb_video_durations", MODE_PRIVATE).getLong(cacheKey, -1L);
                if (cached > 0L) return cached;
            }
            session = smbVideoFrameSource(file).open();
            long durationUs = videoFrameDurationUs(session.retriever);
            long durationMs = durationUs > 0L ? durationUs / 1000L : -1L;
            if (durationMs > 0L && cacheKey != null) getSharedPreferences("smb_video_durations", MODE_PRIVATE)
                    .edit().putLong(cacheKey, durationMs).apply();
            return durationMs;
        } catch (Exception ignored) {
            return -1L;
        } finally {
            if (session != null) session.close();
        }
    }
    /** Directory rendering only reads remembered durations; it never opens a decoder. */
    private long cachedSmbVideoDurationMs(jcifs.smb.SmbFile file) {
        try {
            return getSharedPreferences("smb_video_durations", MODE_PRIVATE)
                    .getLong(smbVideoDurationCacheKey(file), -1L);
        } catch (Exception ignored) { return -1L; }
    }

    private void loadVisibleSmbProgramDuration(View card, JojoProgram program, TextView title,
                                               String titleWithoutDuration, boolean showDuration) {
        boolean categoryVideo = card.getTag(CATEGORY_VIDEO_METADATA_REFRESH_TAG) instanceof Runnable;
        if (isFinishing() || isDestroyed() || !FILE_VIDEO_RESUME_SOURCE.equals(program.sourcePackage) || program.duration > 0L
                || program.intentUri == null || !program.intentUri.startsWith("smb://")
                || !card.isAttachedToWindow()
                || (!categoryVideo && !card.hasFocus() && (!showDuration || title.getVisibility() == View.GONE
                || !card.getGlobalVisibleRect(new android.graphics.Rect())))) return;
        final String user = homePrefs().getString("smb_user", "");
        final String password = homePrefs().getString("smb_password", "");
        final String key = program.intentUri + "|" + user;
        if (key.equals(card.getTag(CATEGORY_VIDEO_METADATA_REQUEST_TAG))) return;
        card.setTag(CATEGORY_VIDEO_METADATA_REQUEST_TAG, key);
        java.util.function.LongConsumer apply = duration -> {
            card.setTag(CATEGORY_VIDEO_METADATA_REQUEST_TAG, null);
            if (duration <= 0L || !card.isAttachedToWindow()) return;
            program.duration = duration;
            if (showDuration) title.setText(SystemContinueWatching.compactPlaybackTimeLabel(duration)
                    .replace(" min", "min") + " " + titleWithoutDuration);
            Object refresh = card.getTag(CATEGORY_VIDEO_METADATA_REFRESH_TAG);
            if ((categoryVideo || card.hasFocus()) && refresh instanceof Runnable) ((Runnable) refresh).run();
        };
        synchronized (smbDurationRequests) {
            List<java.util.function.LongConsumer> pending = smbDurationRequests.get(key);
            if (pending != null) { pending.add(apply); return; }
            pending = new ArrayList<>();
            pending.add(apply);
            smbDurationRequests.put(key, pending);
        }
        smbDurationWork.execute(() -> {
            long duration = -1L;
            try {
                jcifs.smb.SmbFile file = new jcifs.smb.SmbFile(program.intentUri, smbContext(user, password));
                duration = readSmbVideoDurationMs(file);
            } catch (Exception ignored) { }
            final long result = duration;
            final List<java.util.function.LongConsumer> pending;
            synchronized (smbDurationRequests) { pending = smbDurationRequests.remove(key); }
            runOnUiThread(() -> {
                if (pending != null) for (java.util.function.LongConsumer callback : pending) callback.accept(result);
            });
        });
    }
    private String smbVideoDisplayName(String name, long durationMs) {
        if (durationMs <= 0L) return name;
        return SystemContinueWatching.compactPlaybackTimeLabel(durationMs).replace(" min", "min") + " " + name;
    }
    private void prepareSmbArtworkView(ImageView image, String contentDescription) {
        image.setContentDescription(contentDescription);
        image.setPadding(0, 0, 0, 0);
        image.setScaleType(ImageView.ScaleType.CENTER_CROP);
        image.clearColorFilter();
        roundImage(image, 7);
    }
    private void loadSmbFolderArtwork(jcifs.smb.SmbFile folder, ImageView icon) {
        prepareSmbArtworkView(icon, "smb-folder-artwork");
        new Thread(() -> {
            try {
                String folderName = cleanFileName(folder.getName());
                String saved = smbFolderArtwork(folder.getPath());
                if (!saved.isEmpty()) { runOnUiThread(() -> loadArtwork(icon, saved)); return; }
                String searchTitle = folderName;
                String artworkSeriesFolder = folder.getPath();
                jcifs.smb.SmbFile representativeVideo = firstSmbVideoFile(folder);
                VideoFrameSource frameSource = representativeVideo == null
                        ? null : smbVideoFrameSource(representativeVideo);
                String normalizedFolder = Normalizer.normalize(folderName, Normalizer.Form.NFD)
                        .replaceAll("\\p{M}", "").toLowerCase(Locale.ROOT);
                // "Séries"/"Serie"/"TV" are containers, not TMDB titles.
                // Search with an episode name while still using its frame as
                // artwork when the provider has no result.
                if (representativeVideo != null && (normalizedFolder.equals("series")
                        || normalizedFolder.equals("serie") || normalizedFolder.equals("tv"))) {
                    searchTitle = cleanFileName(representativeVideo.getName());
                    artworkSeriesFolder = null;
                }
                loadVideoArtwork(icon, searchTitle, true, artworkSeriesFolder, frameSource,
                        true, false, false, artworkSeriesFolder != null);
            } catch (Exception ignored) {
                // Keep the folder icon when the NAS cannot enumerate it.
            }
        }, "JojoHomeSmbFolderArtwork").start();
    }
    private int compareSmbVideoFiles(jcifs.smb.SmbFile left, jcifs.smb.SmbFile right) {
        int order = HomeMediaRules.compareEpisodes(cleanFileName(left.getName()), cleanFileName(right.getName()));
        return order != 0 ? order : comparableSmbPath(left.getPath()).compareTo(comparableSmbPath(right.getPath()));
    }
    private jcifs.smb.SmbFile firstSmbVideoFile(jcifs.smb.SmbFile folder) throws Exception {
        return firstSmbVideoFile(folder, 0);
    }
    private jcifs.smb.SmbFile firstSmbVideoFile(jcifs.smb.SmbFile folder, int depth) throws Exception {
        if (folder == null || depth > 8) return null;
        ArrayList<jcifs.smb.SmbFile> videos = new ArrayList<>();
        ArrayList<jcifs.smb.SmbFile> directories = new ArrayList<>();
        for (jcifs.smb.SmbFile child : folder.listFiles()) try {
            if (child.isDirectory()) directories.add(child);
            else if (isVideoFile(cleanFileName(child.getName()))) videos.add(child);
        } catch (Exception ignored) { }
        videos.sort(this::compareSmbVideoFiles);
        if (!videos.isEmpty()) return videos.get(0);
        directories.sort(this::compareSmbVideoFiles);
        for (jcifs.smb.SmbFile directory : directories) {
            try {
                jcifs.smb.SmbFile first = firstSmbVideoFile(directory, depth + 1);
                if (first != null) return first;
            } catch (Exception ignored) { }
        }
        return null;
    }
    private void loadFreeboxFolderVideoArtwork(ImageView icon, String title, String folderPath,
                                               boolean homeVideosFolder) {
        if (icon == null || folderPath == null || folderPath.isEmpty()) return;
        String cachedArtwork = cachedVideoArtworkUrl(title, folderPath, true);
        if (!cachedArtwork.isEmpty()) {
            loadArtwork(icon, cachedArtwork);
            return;
        }
        final Object originalTag = icon.getTag();
        final Object folderRequest = new Object();
        videoArtworkRequests.put(icon, folderRequest);
        SmbConnectionConfig connection = defaultSmbConnection();
        String user = connection == null ? homePrefs().getString("smb_user", "") : connection.user;
        String password = connection == null ? homePrefs().getString("smb_password", "") : connection.password;
        new Thread(() -> {
            VideoFrameSource frameSource = null;
            try {
                jcifs.smb.SmbFile folder = new jcifs.smb.SmbFile(folderPath, smbContext(user, password));
                jcifs.smb.SmbFile video = firstSmbVideoFile(folder);
                if (video != null) frameSource = smbVideoFrameSource(video);
            } catch (Exception ignored) { }
            VideoFrameSource resolvedFrameSource = frameSource;
            runOnUiThread(() -> {
                if (icon.getTag() != originalTag || videoArtworkRequests.get(icon) != folderRequest) return;
                loadVideoArtwork(icon, title, true, folderPath, resolvedFrameSource,
                        true, homeVideosFolder, false, true);
            });
        }, "JojoHomeFolderVideoArtwork").start();
    }
    private String smbFolderArtworkKey(jcifs.smb.SmbFile folder) {
        return smbFolderArtworkKey(folder.getPath());
    }
    private String smbFolderArtworkKey(String folderPath) {
        return "smb_folder_v2_thumbnail_artwork_"
                + Integer.toUnsignedString((folderPath == null ? "" : folderPath).hashCode(), 16);
    }
    private String homeVideosFolderArtworkKey(String folderPath) {
        return "smb_home_videos_thumbnail_artwork_"
                + Integer.toUnsignedString((folderPath == null ? "" : folderPath).hashCode(), 16);
    }
    private String smbFolderHeroArtworkKey(String folderPath) {
        return "smb_folder_v2_hero_artwork_"
                + Integer.toUnsignedString((folderPath == null ? "" : folderPath).hashCode(), 16);
    }
    private String smbFolderArtwork(String folderPath) {
        return validSmbFolderArtwork(smbFolderArtworkKey(folderPath));
    }
    private String homeVideosFolderArtwork(String folderPath) {
        String key = homeVideosFolderArtworkKey(folderPath);
        String migrationKey = key + "_independent_v1";
        // Keep the one-time migration marker, but never infer that a matching
        // SMB-browser URL is inherited: the user may have explicitly chosen
        // that same artwork for the Videos folder, and that choice must persist.
        if (!homePrefs().getBoolean(migrationKey, false)) {
            homePrefs().edit().putBoolean(migrationKey, true).apply();
        }
        return validSmbFolderArtwork(key);
    }
    private String smbFolderHeroArtwork(String folderPath) {
        return validSmbFolderArtwork(smbFolderHeroArtworkKey(folderPath));
    }
    private String validSmbFolderArtwork(String key) {
        String selected = homePrefs().getString(key, "").trim();
        if (!selected.startsWith("file:")) return selected;
        Uri uri = Uri.parse(selected);
        String framePath = uri.getPath();
        if (framePath == null) return selected;
        File frame = new File(framePath);
        if (!new File(getCacheDir(), "video_frames").equals(frame.getParentFile())) return selected;
        Bitmap bitmap = BitmapFactory.decodeFile(frame.getAbsolutePath());
        boolean valid = usableVideoFrame(bitmap);
        if (bitmap != null) bitmap.recycle();
        if (valid) return selected;
        homePrefs().edit().remove(key).apply();
        return "";
    }
    private String smbFolderMetadataKey(String folderPath) {
        String normalized = folderPath == null ? "" : folderPath.replaceAll("/+$", "") + "/";
        return "smb_folder_tmdb_metadata_" + Integer.toUnsignedString(normalized.hashCode(), 16);
    }
    private JSONObject selectedSmbFolderArtworkMetadata(String folderPath) {
        if (folderPath == null) return new JSONObject();
        JSONObject latest = new JSONObject();
        long latestSelection = -1L;
        for (String artworkKey : new String[] { smbFolderHeroArtworkKey(folderPath),
                 homeVideosFolderArtworkKey(folderPath), smbFolderArtworkKey(folderPath) }) try {
            String artworkUrl = homePrefs().getString(artworkKey, "");
            if (artworkUrl.isEmpty()) continue;
            JSONObject selected = new JSONObject(homePrefs().getString(artworkKey + "_tmdb_choice", "{}"));
            if (artworkUrl.equals(selected.optString("artworkUrl", ""))
                    && selected.optInt("tmdbId", 0) > 0
                    && selected.optLong("selectedAt", 0L) > latestSelection) {
                latest = selected;
                latestSelection = selected.optLong("selectedAt", 0L);
            }
        } catch (Exception ignored) { }
        return latest;
    }
    private void saveSmbFolderArtworkMetadata(String folderPath, String artworkKey,
                                               ResumeArtworkCandidate candidate) {
        try {
            android.content.SharedPreferences.Editor editor = homePrefs().edit()
                    .remove(smbFolderMetadataKey(folderPath));
            if (candidate.tmdbId > 0 && ("movie".equals(candidate.tmdbMediaType)
                    || "tv".equals(candidate.tmdbMediaType))) {
                editor.putString(artworkKey + "_tmdb_choice", new JSONObject()
                         .put("artworkUrl", candidate.url)
                         .put("tmdbId", candidate.tmdbId)
                         .put("mediaType", candidate.tmdbMediaType)
                         .put("selectedAt", System.currentTimeMillis()).toString());
            } else editor.remove(artworkKey + "_tmdb_choice");
            editor.apply();
            folderHeroMetadataCache.remove(folderPath);
        } catch (Exception ignored) { }
    }
    private FolderMetadata cachedFreeboxFolderMetadata(String folderPath) {
        try {
            JSONObject saved = new JSONObject(homePrefs().getString(smbFolderMetadataKey(folderPath), "{}"));
            if (saved.optInt("tmdbId", 0) <= 0) return null;
            if (!"fr-FR".equals(saved.optString("metadataLanguage", ""))) return null;
            JSONObject selected = selectedSmbFolderArtworkMetadata(folderPath);
            int selectedId = selected.optInt("tmdbId", 0);
            if (selectedId > 0 && (selectedId != saved.optInt("tmdbId", 0)
                    || !selected.optString("mediaType", "").equals(saved.optString("mediaType", "")))) return null;
            if (!saved.optBoolean("validated_match_v3", false)
                    && !(saved.optBoolean("manuallySelected", false)
                    && saved.optString("selectedArtwork", "").equals(smbFolderHeroArtwork(folderPath)))) return null;
            FolderMetadata details = new FolderMetadata();
            details.tmdbId = saved.optInt("tmdbId", 0);
            details.tmdbMediaType = saved.optString("mediaType", "");
            details.title = saved.optString("title", "");
            details.originalLanguage = saved.optString("originalLanguage", "");
            details.date = saved.optString("year", "");
            details.genres = saved.optString("genres", "");
            details.runtime = saved.optString("runtime", "");
            details.overview = saved.optString("overview", "");
            details.logo = saved.optInt("titleLogoPolicyVersion", 0) == TITLE_LOGO_POLICY_VERSION
                    ? saved.optString("logo", "") : "";
            if (!isUsableTitleLogoUrl(details.logo)) details.logo = "";
            details.backdrop = saved.optString("backdrop", "");
            details.director = saved.optString("director", "");
            details.creditsLoaded = saved.optBoolean("creditsLoaded", false) && HomeMediaRules.currentTmdbPeoplePolicy(
                    details.tmdbMediaType, saved.optInt("peoplePolicyVersion", 0));
            restoreFolderCast(details, saved);
            return details;
        } catch (Exception ignored) { return null; }
    }
    private String smbFolderSynopsis(String filePath) {
        String parent = smbParentFolderPath(filePath);
        if (!isSeriesFolderPath(parent)) return "";
        FolderMetadata details = cachedFreeboxFolderMetadata(parent);
        return details == null || details.overview == null ? "" : details.overview.trim();
    }
    private void saveSmbFolderMetadata(String folderPath, ResumeArtworkCandidate candidate) {
        if (folderPath == null || candidate == null || candidate.tmdbId <= 0) return;
        try {
            homePrefs().edit().putString(smbFolderMetadataKey(folderPath), new JSONObject()
                    .put("tmdbId", candidate.tmdbId)
                    .put("mediaType", candidate.tmdbMediaType)
                    .put("title", candidate.title)
                    .put("year", candidate.year)
                    .put("manuallySelected", true)
                    .put("selectedArtwork", candidate.url)
                    .put("overview", candidate.overview.trim())
                    .toString()).apply();
        } catch (Exception ignored) { }
    }
    private void saveSmbFolderMetadata(String folderPath, FolderMetadata details) {
        if (folderPath == null || details == null || details.tmdbId <= 0) return;
        try {
            JSONObject previous = new JSONObject(homePrefs().getString(smbFolderMetadataKey(folderPath), "{}"));
            boolean manual = previous.optBoolean("manuallySelected", false)
                    && previous.optInt("tmdbId", 0) == details.tmdbId
                    && previous.optString("selectedArtwork", "").equals(smbFolderHeroArtwork(folderPath));
            homePrefs().edit().putString(smbFolderMetadataKey(folderPath), new JSONObject()
                    .put("tmdbId", details.tmdbId)
                    .put("mediaType", details.tmdbMediaType)
                    .put("title", details.title)
                    .put("originalLanguage", details.originalLanguage == null ? "" : details.originalLanguage)
                    .put("year", details.date)
                    .put("genres", details.genres == null ? "" : details.genres)
                    .put("runtime", details.runtime == null ? "" : details.runtime)
                    .put("logo", details.logo == null ? "" : details.logo)
                    .put("titleLogoPolicyVersion", TITLE_LOGO_POLICY_VERSION)
                    .put("backdrop", details.backdrop == null ? "" : details.backdrop)
                    .put("actors", folderCastNames(details.cast))
                    .put("castDetails", folderCastDetails(details.cast))
                    .put("peoplePolicyVersion", HomeMediaRules.TMDB_PEOPLE_POLICY_VERSION)
                    .put("director", details.director == null ? "" : details.director)
                    .put("creditsLoaded", details.creditsLoaded)
                    .put("metadataLanguage", "fr-FR")
                    .put("validated_match_v3", true)
                    .put("manuallySelected", manual)
                    .put("selectedArtwork", manual ? previous.optString("selectedArtwork", "") : "")
                    .put("overview", details.overview.trim())
                    .toString()).apply();
        } catch (Exception ignored) { }
    }
    private String smbParentFolderPath(String filePath) {
        if (filePath == null) return "";
        String value = filePath.replaceAll("/+$", "");
        int separator = value.lastIndexOf('/');
        return separator > 0 ? value.substring(0, separator) + "/" : "";
    }
    private boolean isSeriesFolderPath(String folderPath) {
        if (folderPath == null) return false;
        String normalized = Normalizer.normalize(Uri.decode(folderPath), Normalizer.Form.NFD)
                .replaceAll("\\p{M}", "").toLowerCase(Locale.ROOT).replace('\\', '/');
        return normalized.contains("/videos/") || normalized.contains("/video/")
                || normalized.endsWith("/videos") || normalized.endsWith("/video");
    }
    private void saveSmbGroupArtwork(String folderPath, String artworkUrl) {
        if (folderPath == null || artworkUrl == null || artworkUrl.isEmpty()) return;
        homePrefs().edit().putString(smbFolderArtworkKey(folderPath), artworkUrl).apply();
    }
    private ImageView resolveArtworkView(View anchor) {
        if (anchor == null) return null;
        Object tag = anchor.getTag();
        if (tag instanceof ImageView) return (ImageView) tag;
        Object keyedTag = anchor.getTag(CONTINUE_WATCHING_HERO_TAG);
        if (keyedTag instanceof ImageView) return (ImageView) keyedTag;
        if (anchor instanceof ImageView) return (ImageView) anchor;
        if (anchor instanceof ViewGroup) {
            ViewGroup group = (ViewGroup) anchor;
            for (int index = 0; index < group.getChildCount(); index++) {
                ImageView image = resolveArtworkView(group.getChildAt(index));
                if (image != null) return image;
            }
        }
        return null;
    }

