                    if (heroSelection) {
                        panel.addView(rail, new LinearLayout.LayoutParams(-1, dp(140)));
                        View firstChoice = choices.getChildAt(0);
                        if (firstChoice != null) firstChoice.requestFocus();
                    } else addArtworkOrientationTabs(panel, choices, rail, portraitArtwork);
