    private void showFileMenu(View anchor, boolean folder, View.OnClickListener open, View.OnClickListener restartFromBeginning, View.OnClickListener export, View.OnClickListener copy, View.OnClickListener cut, View.OnClickListener paste, View.OnClickListener wallpaper, View.OnClickListener changeArtwork, View.OnClickListener placeOnHome, View.OnClickListener rename, View.OnClickListener delete, View.OnClickListener removeFromList, String deleteLabel) {
        LinearLayout menu = new LinearLayout(this); menu.setOrientation(LinearLayout.VERTICAL); menu.setPadding(0, 0, 0, 0); menu.setBackground(lightMenuBg());
        View openRow = popupRow(R.drawable.ic_menu_open, "Ouvrir");
        View restartRow = restartFromBeginning == null ? null : popupRow(removeFromList == null ? R.drawable.ic_reset_arrow : R.drawable.ic_refresh, removeFromList == null ? "Reprendre du début" : "Reprendre au début");
        View exportRow = popupRow(R.drawable.ic_export_zip, "Exporter en ZIP");
        View copyRow = popupRow(R.drawable.ic_menu_copy, "Copier");
        View cutRow = popupRow(R.drawable.ic_menu_cut, "Couper");
        View pasteRow = null;
        if (folder) {
            String pasteLabel = "Coller (vide)";
            if (hasClipboardItems()) pasteLabel = clipboardCut ? "Coller (déplacer)" : "Coller (copier)";
            pasteRow = popupRow(R.drawable.ic_menu_paste, pasteLabel);
            pasteRow.setAlpha(hasClipboardItems() ? 1f : .45f);
        }
        View wallpaperRow = null; if (wallpaper != null) wallpaperRow = popupRow(R.drawable.ic_menu_wallpaper, "Définir comme fond d’écran");
        View artworkRow = changeArtwork == null ? null : popupRow(R.drawable.ic_menu_wallpaper, "Changer de vignette");
        View placeRow = popupRow(R.drawable.ic_menu_home_add, "Placer sur l'écran d'accueil", true);
        View selectRow = popupRow(R.drawable.ic_menu_select_multiple, "Sélectionner plusieurs");
        View renameRow = popupRow(R.drawable.ic_menu_rename, "Renommer");
        View removeRow = removeFromList == null ? null : popupRow(R.drawable.ic_menu_delete, "Supprimer de la liste");
        View deleteRow = popupRow(R.drawable.ic_menu_delete, deleteLabel);
        ArrayList<View> order = new ArrayList<>(); order.add(openRow); if (restartRow != null) order.add(restartRow); order.add(exportRow); order.add(copyRow); order.add(cutRow); if (pasteRow != null) order.add(pasteRow); if (wallpaperRow != null) order.add(wallpaperRow); if (artworkRow != null) order.add(artworkRow); order.add(placeRow); order.add(selectRow); order.add(renameRow); if (removeRow != null) order.add(removeRow); order.add(deleteRow);
        // Let the popup wrap the actual row heights. The former fixed-height
        // calculation left unused background space below the last action.
        View popupContent = menu;
        if (removeRow != null) {
            ScrollView scroll = new ScrollView(this); scroll.setVerticalScrollBarEnabled(false); scroll.setFocusable(false);
            scroll.addView(menu, new ScrollView.LayoutParams(-1, -2)); popupContent = scroll;
        }
        int popupWidth = dp(removeRow == null ? 278 : 330);
        PopupWindow popup = new PopupWindow(popupContent, popupWidth, -2, true); popup.setBackgroundDrawable(lightMenuBg()); popup.setOutsideTouchable(true); popup.setElevation(dp(12)); trackPopup(popup);
        for (View row : order) menu.addView(row);
        if (removeRow != null) {
            menu.measure(View.MeasureSpec.makeMeasureSpec(popupWidth, View.MeasureSpec.EXACTLY), View.MeasureSpec.makeMeasureSpec(0, View.MeasureSpec.UNSPECIFIED));
            popup.setHeight(Math.min(menu.getMeasuredHeight(), getResources().getDisplayMetrics().heightPixels - dp(64)));
        }
        finalizePopupMenu(menu);
        openRow.setOnClickListener(v -> { popup.dismiss(); open.onClick(v); });
        if (restartRow != null) restartRow.setOnClickListener(v -> { popup.dismiss(); restartFromBeginning.onClick(v); });
        exportRow.setOnClickListener(v -> { popup.dismiss(); export.onClick(v); });
        copyRow.setOnClickListener(v -> { popup.dismiss(); copy.onClick(v); });
        cutRow.setOnClickListener(v -> { popup.dismiss(); cut.onClick(v); });
        if (pasteRow != null) pasteRow.setOnClickListener(v -> { if (hasClipboardItems()) { popup.dismiss(); paste.onClick(v); } });
        if (wallpaperRow != null) wallpaperRow.setOnClickListener(v -> { popup.dismiss(); wallpaper.onClick(v); });
        if (artworkRow != null) artworkRow.setOnClickListener(v -> { popup.dismiss(); changeArtwork.onClick(v); });
        placeRow.setOnClickListener(v -> { popup.dismiss(); placeOnHome.onClick(v); });
        selectRow.setOnClickListener(v -> { multiClipboard.clear(); copy.onClick(v); popup.dismiss(); if (fileClipboard != null) beginMultiSelection(fileClipboard); });
        renameRow.setOnClickListener(v -> { popup.dismiss(); rename.onClick(v); });
        if (removeRow != null) removeRow.setOnClickListener(v -> { popup.dismiss(); removeFromList.onClick(v); });
        deleteRow.setOnClickListener(v -> { popup.dismiss(); delete.onClick(v); });
        if (removeRow == null) {
            for (int i = 0; i < order.size(); i++) {
                View current = order.get(i);
                View previous = i > 0 ? order.get(i - 1) : current;
                View next = i < order.size() - 1 ? order.get(i + 1) : current;
                current.setNextFocusUpId(previous.getId());
                current.setNextFocusDownId(next.getId());
            }
        }
        showPopupBelow(popup, anchor, 0, dp(4));
        if (removeRow != null && restartRow != null) restartRow.requestFocus(); else openRow.requestFocus();
    }
