    private View createHomeFileShortcuts() {
        Set<String> shortcuts = homeFileShortcuts();
        if (shortcuts.isEmpty()) return null;
        ArrayList<String> sorted = new ArrayList<>(shortcuts);
        Collections.sort(sorted, String::compareToIgnoreCase);
        LinearLayout section = new LinearLayout(this);
        section.setOrientation(LinearLayout.VERTICAL);
        section.setClipChildren(false);
        section.setClipToPadding(false);
        addHomeSectionTitle(section, "shortcuts", "Raccourcis", 10);
        LinearLayout rows = new LinearLayout(this);
        rows.setOrientation(LinearLayout.VERTICAL);
        rows.setClipChildren(false);
        rows.setClipToPadding(false);
        int rowCount = Math.min(homeSectionRows("shortcuts"), Math.max(1, sorted.size()));
        int perRow = Math.max(1, (int) Math.ceil(sorted.size() / (double) rowCount));
        LinearLayout row = null;
        for (int index = 0; index < sorted.size(); index++) {
            if (index % perRow == 0) {
                HorizontalScrollView scroll = new HorizontalScrollView(this);
                scroll.setHorizontalScrollBarEnabled(false);
                // The shortcut tile grows on focus. Keep a real vertical safety margin
                // as well as the horizontal one, otherwise the focus outline is cut at
                // the top edge of the HorizontalScrollView.
                scroll.setPadding(dp(12), dp(8), dp(12), dp(8));
                scroll.setClipChildren(false);
                scroll.setClipToPadding(false);
                row = new LinearLayout(this);
                row.setClipChildren(false);
                row.setClipToPadding(false);
                scroll.addView(row);
                rows.addView(scroll, new LinearLayout.LayoutParams(-1, dp(202)));
            }
            String uri = sorted.get(index);
            String name = homeFileShortcutName(uri);
            boolean directory = homeFileShortcutDirectory(uri);
            boolean video = !directory && isVideoFile(name);
            View tile = video
                    ? homeVideoShortcutTile(name, v -> openHomeShortcut(uri))
                    : homeShortcutTile(fileIcon(name, directory), name, "", v -> openHomeShortcut(uri));
            // Home shortcuts are vertical cards: use the movie poster rather
            // than the wide backdrop used by the file-browser rows.
            if (video) loadVideoArtwork((ImageView) tile.getTag(), name, false);
            tile.setTag(uri);
            if (index == 0) registerHomeRowMoveTrigger(tile, "shortcuts");
            tile.setOnLongClickListener(v -> { showHomeShortcutMenu(tile, uri); return true; });
            LinearLayout.LayoutParams params = new LinearLayout.LayoutParams(dp(112), dp(video ? 184 : 150));
            params.rightMargin = dp(18);
            row.addView(tile, params);
            wireHorizontalCardRowDpad(row);
        }
        section.addView(rows, new LinearLayout.LayoutParams(-1, dp(202 * rowCount)));
        wireHomeSectionVerticalDpad();
        return section;
    }
    private Set<String> homeFileShortcuts() {
        Set<String> shortcuts = homePrefs().getStringSet("home_file_shortcuts", null);
        return shortcuts == null ? new HashSet<>() : new HashSet<>(shortcuts);
    }
    private void addHomeFileShortcut(String uri) {
        Set<String> shortcuts = homeFileShortcuts();
        if (!shortcuts.contains(uri)) {
            shortcuts.add(uri);
            homePrefs().edit().putStringSet("home_file_shortcuts", shortcuts).apply();
            // A shortcut is expected on the other TV immediately; do not wait
            // for the generic debounced preferences synchronisation.
            syncHomeSettingsToNas();
            goHome();
        }
    }
    private void removeHomeFileShortcut(String uri) {
        Set<String> shortcuts = homeFileShortcuts();
        if (shortcuts.contains(uri)) {
            shortcuts.remove(uri);
            homePrefs().edit().putStringSet("home_file_shortcuts", shortcuts).apply();
            syncHomeSettingsToNas();
            goHome();
        }
    }
    private String homeFileShortcutName(String uri) {
        if (uri == null) return "Fichier";
        if (uri.startsWith("shizuku-file:") || uri.startsWith("shizuku-dir:"))
            return cleanFileName(new File(uri.substring(uri.indexOf(':') + 1)).getName());
        if (uri.startsWith("smb://")) {
            String trimmed = uri.endsWith("/") ? uri.substring(0, uri.length() - 1) : uri;
            int lastSlash = trimmed.lastIndexOf('/');
            return cleanFileName(lastSlash >= 0 ? trimmed.substring(lastSlash + 1) : trimmed);
        }
        Uri parsed = Uri.parse(uri);
        String path = parsed.getPath();
        if (path != null) return cleanFileName(new File(path).getName());
        return cleanFileName(uri);
    }
    private boolean homeFileShortcutDirectory(String uri) {
        if (uri == null) return false;
        if (uri.startsWith("shizuku-dir:")) return true;
        if (uri.startsWith("shizuku-file:")) return false;
        if (uri.startsWith("smb://")) return uri.endsWith("/");
        Uri parsed = Uri.parse(uri);
        String path = parsed.getPath();
        return path != null && new File(path).isDirectory();
    }
    private void deleteHomeFileShortcut(String uri) {
        removeHomeFileShortcut(uri);
        Toast.makeText(this, "Raccourci supprimé", Toast.LENGTH_SHORT).show();
    }
    private void openHomeShortcut(String uri) {
        try {
            if (uri.startsWith("shizuku-file:") || uri.startsWith("shizuku-dir:")) {
                String path = uri.substring(uri.indexOf(':') + 1);
                new Thread(() -> {
                    try {
                        ShizukuFiles.Entry entry = ShizukuFiles.stat(path);
                        runOnUiThread(() -> { if (entry.directory) openScreen(createShizukuBrowser(entry.path)); else openShizukuFile(entry); });
                    } catch (Exception error) {
                        runOnUiThread(() -> Toast.makeText(this, "Impossible d’ouvrir ce fichier Shizuku", Toast.LENGTH_LONG).show());
                    }
                }, "JojoHomeShizukuShortcut").start();
                return;
            }
            if (uri.startsWith("smb://")) {
                openSmbHomeShortcut(uri);
                return;
            }
            String path = uri;
            if (uri.startsWith("file://")) {
                Uri parsed = Uri.parse(uri);
                if (parsed.getPath() != null) path = parsed.getPath();
            }
            File file = new File(path);
            if (file.isDirectory()) openScreen(createLocalBrowser(file));
            else openLocalFile(file);
        } catch (Exception error) {
            Toast.makeText(this, "Impossible d'ouvrir le fichier", Toast.LENGTH_LONG).show();
        }
    }
    private void openSmbHomeShortcut(String uri) {
        final String user = homePrefs().getString("smb_user", "");
        final String password = homePrefs().getString("smb_password", "");
        new Thread(() -> {
            try {
                jcifs.CIFSContext context = smbContext(user, password);
                jcifs.smb.SmbFile file = new jcifs.smb.SmbFile(uri, context);
                if (file.isDirectory()) {
                    runOnUiThread(() -> openScreen(createFreeboxFolderMediaPage(uri, user, password)));
                } else {
                    // Files keep the normal SMB player flow.
                    openSmbEntry(file, context, user, password);
                }
            } catch (Exception error) {
                android.util.Log.e("JojoHomeSmb", "Échec d'ouverture d'un raccourci SMB", error);
                runOnUiThread(() -> Toast.makeText(this, "Impossible d'ouvrir ce raccourci SMB", Toast.LENGTH_LONG).show());
            }
        }, "JojoHomeShortcutSmb").start();
    }
    private void openSmbFolderHomeShortcut(String uri) {
        if (uri == null || uri.trim().isEmpty()) return;
        final String user = homePrefs().getString("smb_user", "");
        final String password = homePrefs().getString("smb_password", "");
        runOnUiThread(() -> openScreen(createFreeboxFolderMediaPage(uri, user, password)));
    }
