    private void exportHomeShortcutArchive(String uri) {
        try {
            if (uri.startsWith("shizuku-file:") || uri.startsWith("shizuku-dir:")) {
                String path = uri.substring(uri.indexOf(':') + 1);
                new Thread(() -> {
                    try {
                        ShizukuFiles.Entry entry = ShizukuFiles.stat(path);
                        runOnUiThread(() -> exportShizukuFileArchive(entry));
                    } catch (Exception error) {
                        runOnUiThread(() -> Toast.makeText(this, "Export ZIP impossible", Toast.LENGTH_LONG).show());
                    }
                }, "JojoHomeShizukuShortcutExport").start();
                return;
            }
            if (uri.startsWith("smb://")) {
                String user = homePrefs().getString("smb_user", "");
                String password = homePrefs().getString("smb_password", "");
                exportSmbFileArchive(new jcifs.smb.SmbFile(uri, smbContext(user, password)));
                return;
            }
            Uri parsed = Uri.parse(uri);
            exportLocalFileArchive(new File("file".equals(parsed.getScheme()) ? parsed.getPath() : uri));
        } catch (Exception error) {
            Toast.makeText(this, "Export ZIP impossible", Toast.LENGTH_LONG).show();
        }
    }
