    private String localFolderArtworkKey(File folder) {
        String path = folder == null ? "" : folder.getAbsolutePath();
        return "local_folder_thumbnail_artwork_" + Integer.toUnsignedString(path.hashCode(), 16);
    }
    private void loadLocalFolderArtwork(File folder, ImageView icon) {
        if (folder == null || icon == null) return;
        String artwork = homePrefs().getString(localFolderArtworkKey(folder), "").trim();
        if (artwork.isEmpty()) return;
        icon.setContentDescription("local-folder-artwork");
        icon.setPadding(0, 0, 0, 0);
        icon.setScaleType(ImageView.ScaleType.CENTER_CROP);
        icon.clearColorFilter();
        roundImage(icon, 7);
        loadArtwork(icon, artwork);
    }
    private File firstLocalVideoFile(File folder, int depth) {
        if (folder == null || depth > 6) return null;
        File[] children = folder.listFiles();
        if (children == null) return null;
        java.util.Arrays.sort(children, (left, right) -> left.getName().compareToIgnoreCase(right.getName()));
        for (File child : children) if (child.isFile() && isVideoFile(child.getName())) return child;
        for (File child : children) if (child.isDirectory()) {
            File video = firstLocalVideoFile(child, depth + 1);
            if (video != null) return video;
        }
        return null;
    }
