        boolean portraitArtwork = homeCategoryThumbnailPortrait(artworkCategory);
        LinearLayout panel = new LinearLayout(this); panel.setOrientation(LinearLayout.VERTICAL); panel.setPadding(dp(24), dp(20), dp(24), dp(18)); panel.setBackground(artworkPickerPanelBg());
        panel.addView(text("Changer de vignette", 21, white));
