    private void saveMiddleVideoFrameForLocalFolder(File folder, VideoFrameSource source, View anchor, PopupWindow popup) {
        if (popup != null && popup.isShowing()) popup.dismiss();
        new Thread(() -> {
            boolean acquired = false;
            try {
                videoFrameDecodeSemaphore.acquire(); acquired = true;
                Bitmap frame = null;
                for (float fraction : new float[] { 0.50f, 0.25f, 0.75f }) {
                    frame = videoFrameAt(source, fraction);
                    if (frame != null) break;
                }
                if (frame == null) throw new IOException("Frame vidéo indisponible");
                File saved = new File(getFilesDir(), "selected_local_folder_" + java.util.UUID.randomUUID() + ".jpg");
                try (FileOutputStream output = new FileOutputStream(saved)) {
                    if (!frame.compress(Bitmap.CompressFormat.JPEG, 90, output)) throw new IOException("Frame vidéo indisponible");
                }
                homePrefs().edit().putString(localFolderArtworkKey(folder), Uri.fromFile(saved).toString()).apply();
                Bitmap selected = frame;
                runOnUiThread(() -> {
                    ImageView image = resolveArtworkView(anchor);
                    if (image != null) { image.setContentDescription("local-folder-artwork"); image.setPadding(0, 0, 0, 0); image.clearColorFilter(); image.setScaleType(ImageView.ScaleType.CENTER_CROP); image.setImageBitmap(selected); }
                    if (anchor != null && anchor.isAttachedToWindow()) anchor.requestFocus();
                    Toast.makeText(this, "Frame vidéo enregistrée comme vignette", Toast.LENGTH_SHORT).show();
                });
            } catch (Exception error) { runOnUiThread(() -> Toast.makeText(this, "Impossible d’extraire une frame vidéo", Toast.LENGTH_LONG).show()); }
            finally { if (acquired) videoFrameDecodeSemaphore.release(); }
        }, "JojoHomeLocalFolderMiddleFrame").start();
    }
