    private void showSmbFileMenu(jcifs.smb.SmbFile file, jcifs.CIFSContext context,
                                 String user, String password, View anchor, boolean folder) {
        if (multiSelectMode) {
            FileClipboard item = new FileClipboard(file, context);
            if (!selectedForMulti(item)) { toggleMultiSelection(item, anchor); return; }
            ArrayList<FileClipboard> selected = new ArrayList<>(multiSelection);
            View originScreen = activeScreen;
            showMultiSelectionMenu(anchor, () -> new Thread(() -> {
                try {
                    for (FileClipboard entry : selected) {
                        if (entry.smb == null) continue;
                        deleteSmbTree(entry.smb, this);
                    }
                } catch (Exception error) {
                    runOnUiThread(() -> Toast.makeText(this, "Suppression impossible", Toast.LENGTH_LONG).show());
                } finally {
                    runOnUiThread(() -> {
                        if (activeScreen == originScreen) replaceScreen(createSmbBrowser(file.getParent(), user, password));
                    });
                }
            }).start(), () -> replaceScreen(createSmbBrowser(file.getParent(), user, password)));
            return;
        }
        if (!folder && isVideoFile(file.getName())) {
            showSmbVideoMenu(file, context, user, password, anchor);
            return;
        }
        View.OnClickListener wallpaper = !folder && isMediaFile(file.getName()) ? v -> new Thread(() -> { try { saveSmbWallpaper(file); runOnUiThread(() -> openScreen(createAppSettingsPage())); } catch (Exception error) { runOnUiThread(() -> Toast.makeText(this, "Fond d’écran impossible", Toast.LENGTH_LONG).show()); } }).start() : null;
        View.OnClickListener restart = !folder && isVideoFile(file.getName()) ? v -> { clearVideoResume(file.getPath()); openSmbEntry(file, context, user, password); } : null;
        showFileMenu(anchor, folder, v -> openSmbEntry(file, context, user, password), restart, v -> exportSmbFileArchive(file), v -> { multiClipboard.clear(); fileClipboard = new FileClipboard(file, context); clipboardCut = false; Toast.makeText(this, "Copié : " + cleanFileName(file.getName()), Toast.LENGTH_SHORT).show(); }, v -> { multiClipboard.clear(); fileClipboard = new FileClipboard(file, context); clipboardCut = true; Toast.makeText(this, "Couper : " + cleanFileName(file.getName()), Toast.LENGTH_SHORT).show(); }, v -> pasteIntoSmb(file, context, user, password), wallpaper, folder ? v -> showSmbFolderArtworkPicker(file, anchor) : null, v -> placeOnHomeSmb(file, context, user, password), v -> showRenamePopup(cleanFileName(file.getName()), name -> { jcifs.smb.SmbFile target = smbChild(new jcifs.smb.SmbFile(file.getParent(), context), name, context); if (target.exists()) throw new java.io.IOException(); file.renameTo(target); runOnUiThread(() -> replaceScreen(createSmbBrowser(file.getParent(), user, password))); }), v -> showDeleteConfirm(cleanFileName(file.getName()), () -> deleteSmb(file, context, user, password)));
    }
    private void pasteIntoLocal(File destination) {
        if (!destination.isDirectory() || !hasClipboardItems()) return;
        ArrayList<FileClipboard> items = clipboardItems();
        final boolean move = clipboardCut;
        new Thread(() -> { try { for (FileClipboard item : items) {
                if (item.local != null) {
                    if (move) moveLocalToLocal(item.local, destination);
                    else copyLocalToLocal(item.local, destination);
                } else if (item.smb != null) {
                    if (move) {
                        copySmbToLocal(item.smb, destination);
                        deleteSmbTree(item.smb);
                    } else copySmbToLocal(item.smb, destination);
                } else if (item.shizukuPath != null) {
                    if (move) {
                        copyShizukuToLocal(item.shizukuPath, item.shizukuDirectory, destination);
                        ShizukuFiles.delete(item.shizukuPath);
                    } else copyShizukuToLocal(item.shizukuPath, item.shizukuDirectory, destination);
                }
            }
            if (move) clearClipboard();
            runOnUiThread(() -> { Toast.makeText(this, items.size() > 1 ? "Collage terminé : " + items.size() + " éléments" : "Collage terminé", Toast.LENGTH_SHORT).show(); replaceScreen(createLocalBrowser(destination)); }); } catch (Exception error) { runOnUiThread(() -> Toast.makeText(this, "Collage impossible", Toast.LENGTH_LONG).show()); } }).start();
    }
    private void pasteIntoSmb(jcifs.smb.SmbFile destination, jcifs.CIFSContext context, String user, String password) {
        if (!hasClipboardItems()) return;
        ArrayList<FileClipboard> items = clipboardItems();
        final boolean move = clipboardCut;
        new Thread(() -> {
            try {
                for (FileClipboard item : items) {
                    if (item.local != null) {
                        copyLocalToSmb(item.local, destination, context);
                        if (move) deleteLocalTree(item.local);
                    } else if (item.smb != null) {
                        if (move) {
                            copySmbToSmb(item.smb, destination, context);
                            deleteSmbTree(item.smb);
                        } else copySmbToSmb(item.smb, destination, context);
                    } else if (item.shizukuPath != null) {
                        if (move) {
                            copyShizukuToSmb(item.shizukuPath, item.shizukuDirectory, destination, context);
                            ShizukuFiles.delete(item.shizukuPath);
                        } else copyShizukuToSmb(item.shizukuPath, item.shizukuDirectory, destination, context);
                    }
                }
                if (move) clearClipboard();
                runOnUiThread(() -> {
                    Toast.makeText(this, items.size() > 1 ? "Collage terminé : " + items.size() + " éléments" : "Collage terminé", Toast.LENGTH_SHORT).show();
                    replaceScreen(createSmbBrowser(destination.getCanonicalPath(), user, password));
                });
            } catch (Exception error) {
                runOnUiThread(() -> Toast.makeText(this, "Collage impossible", Toast.LENGTH_LONG).show());
            }
        }).start();
    }
    private void pasteIntoShizuku(String destinationPath) {
        if (!hasClipboardItems()) return;
        ArrayList<FileClipboard> items = clipboardItems();
        final boolean move = clipboardCut;
        new Thread(() -> {
            try {
                ShizukuFiles.list(destinationPath);
                for (FileClipboard item : items) {
                    if (item.shizukuPath != null) {
                        if (item.shizukuDirectory && isSameOrChildPath(item.shizukuPath, destinationPath))
                            throw new IOException("Impossible de coller un dossier dans lui-même");
                        String target = uniqueShizukuChild(destinationPath, item.name());
                        if (move) ShizukuFiles.movePath(item.shizukuPath, target);
                        else ShizukuFiles.copyPath(item.shizukuPath, target);
                    } else if (item.local != null) {
                        if (item.local.isDirectory() && isSameOrChildPath(item.local.getAbsolutePath(), destinationPath))
                            throw new IOException("Impossible de coller un dossier dans lui-même");
                        copyLocalToShizuku(item.local, destinationPath);
                        if (move) deleteLocalTree(item.local);
                    } else if (item.smb != null) {
                        copySmbToShizuku(item.smb, destinationPath);
                        if (move) deleteSmbTree(item.smb);
                    }
                }
                if (move) clearClipboard();
                runOnUiThread(() -> {
                    Toast.makeText(this, items.size() > 1 ? "Collage terminé : " + items.size() + " éléments" : "Collage terminé", Toast.LENGTH_SHORT).show();
                    replaceScreen(createShizukuBrowser(destinationPath));
                });
            } catch (Exception error) {
                runOnUiThread(() -> Toast.makeText(this, "Collage impossible", Toast.LENGTH_LONG).show());
            }
        }).start();
    }
    private File uniqueLocalChild(File parent, String name) { File target = new File(parent, name); int index = 1; while (target.exists()) target = new File(parent, name + " (" + index++ + ")"); return target; }
    private jcifs.smb.SmbFile smbChild(jcifs.smb.SmbFile parent, String name, jcifs.CIFSContext context) throws java.net.MalformedURLException { String path = parent.getCanonicalPath(); if (!path.endsWith("/")) path += "/"; return new jcifs.smb.SmbFile(path + name, context); }
    private jcifs.smb.SmbFile uniqueSmbChild(jcifs.smb.SmbFile parent, String name, jcifs.CIFSContext context) throws Exception { jcifs.smb.SmbFile target = smbChild(parent, name, context); int index = 1; while (target.exists()) target = smbChild(parent, name + " (" + index++ + ")", context); return target; }
    private void copyLocalToLocal(File source, File parent) throws Exception { File target = uniqueLocalChild(parent, source.getName()); if (source.isDirectory()) { if (!target.mkdirs()) throw new java.io.IOException(); File[] children = source.listFiles(); if (children != null) for (File child : children) copyLocalToLocal(child, target); } else copyFile(new FileInputStream(source), new java.io.FileOutputStream(target)); }
    private void copySmbToLocal(jcifs.smb.SmbFile source, File parent) throws Exception { File target = uniqueLocalChild(parent, cleanFileName(source.getName())); if (source.isDirectory()) { if (!target.mkdirs()) throw new java.io.IOException(); for (jcifs.smb.SmbFile child : source.listFiles()) copySmbToLocal(child, target); } else copyFile(new jcifs.smb.SmbFileInputStream(source), new java.io.FileOutputStream(target)); }
    private void copyLocalToSmb(File source, jcifs.smb.SmbFile parent, jcifs.CIFSContext context) throws Exception { jcifs.smb.SmbFile target = uniqueSmbChild(parent, source.getName(), context); if (source.isDirectory()) { target.mkdir(); File[] children = source.listFiles(); if (children != null) for (File child : children) copyLocalToSmb(child, target, context); } else copyFile(new FileInputStream(source), new jcifs.smb.SmbFileOutputStream(target)); }
    private void copySmbToSmb(jcifs.smb.SmbFile source, jcifs.smb.SmbFile parent, jcifs.CIFSContext context) throws Exception { jcifs.smb.SmbFile target = uniqueSmbChild(parent, cleanFileName(source.getName()), context); if (source.isDirectory()) { target.mkdir(); for (jcifs.smb.SmbFile child : source.listFiles()) copySmbToSmb(child, target, context); } else copyFile(new jcifs.smb.SmbFileInputStream(source), new jcifs.smb.SmbFileOutputStream(target)); }
    private String uniqueShizukuChild(String parent, String name) throws Exception {
        if (name == null || name.isEmpty() || name.equals(".") || name.equals("..") || name.contains("/") || name.contains("\\"))
            throw new IOException("Nom de fichier invalide");
        String base = parent.replaceAll("/+$", "") + "/" + name;
        String target = base;
        int suffix = 1;
        while (ShizukuFiles.exists(target)) target = base + " (" + suffix++ + ")";
        return target;
    }
    private boolean isSameOrChildPath(String source, String destination) {
        String from = source == null ? "" : source.replaceAll("/+$", "");
        String to = destination == null ? "" : destination.replaceAll("/+$", "");
        return !from.isEmpty() && (to.equals(from) || to.startsWith(from + "/"));
    }
    private void copyShizukuToLocal(String sourcePath, boolean directory, File parent) throws Exception {
        String name = new File(sourcePath).getName();
        File target = uniqueLocalChild(parent, name);
        if (directory) {
            if (!target.mkdirs()) throw new IOException("Création du dossier impossible");
            for (ShizukuFiles.Entry child : ShizukuFiles.list(sourcePath)) copyShizukuToLocal(child.path, child.directory, target);
        } else ShizukuFiles.copyToFile(sourcePath, target);
    }
    private void copyShizukuToSmb(String sourcePath, boolean directory, jcifs.smb.SmbFile parent,
                                  jcifs.CIFSContext context) throws Exception {
        String name = new File(sourcePath).getName();
        jcifs.smb.SmbFile target = uniqueSmbChild(parent, name, context);
        if (directory) {
            target.mkdir();
            for (ShizukuFiles.Entry child : ShizukuFiles.list(sourcePath)) copyShizukuToSmb(child.path, child.directory, target, context);
        } else try (OutputStream output = new jcifs.smb.SmbFileOutputStream(target)) {
            ShizukuFiles.copyToStream(sourcePath, output);
        }
    }
    private void copyLocalToShizuku(File source, String parent) throws Exception {
        String target = uniqueShizukuChild(parent, source.getName());
        if (source.isDirectory()) {
            ShizukuFiles.makeDirectory(target);
            File[] children = source.listFiles();
            if (children == null && source.exists()) throw new IOException("Lecture du dossier refusée");
            if (children != null) for (File child : children) copyLocalToShizuku(child, target);
        } else try (InputStream input = new FileInputStream(source)) {
            ShizukuFiles.copyFromStream(input, target);
        }
    }
    private void copySmbToShizuku(jcifs.smb.SmbFile source, String parent) throws Exception {
        String name = cleanFileName(source.getName());
        String target = uniqueShizukuChild(parent, name);
        if (source.isDirectory()) {
            ShizukuFiles.makeDirectory(target);
            for (jcifs.smb.SmbFile child : source.listFiles()) copySmbToShizuku(child, target);
        } else try (InputStream input = new jcifs.smb.SmbFileInputStream(source)) {
            ShizukuFiles.copyFromStream(input, target);
        }
    }
    private void moveLocalToLocal(File source, File parent) throws Exception { File target = uniqueLocalChild(parent, source.getName()); if (!source.renameTo(target)) { copyLocalToLocal(source, parent); deleteLocalTree(source); } }
    private void moveSmbToSmb(jcifs.smb.SmbFile source, jcifs.smb.SmbFile parent, jcifs.CIFSContext context) throws Exception {
        jcifs.smb.SmbFile target = uniqueSmbChild(parent, cleanFileName(source.getName()), context);
        copySmbToSmb(source, parent, context);
        deleteSmbTree(source);
    }
    private void copyFile(java.io.InputStream input, java.io.OutputStream output) throws java.io.IOException { try (java.io.InputStream in = input; java.io.OutputStream out = output) { byte[] buffer = new byte[32768]; int count; while ((count = in.read(buffer)) != -1) out.write(buffer, 0, count); } }
    private void deleteLocal(File file) {
        if (Build.VERSION.SDK_INT <= 29 && checkSelfPermission(Manifest.permission.WRITE_EXTERNAL_STORAGE) != PackageManager.PERMISSION_GRANTED) {
            pendingLocalDelete = file;
            Toast.makeText(this, "Autorisez Jojo Home à modifier les fichiers du stockage", Toast.LENGTH_LONG).show();
            requestPermissions(new String[] { Manifest.permission.WRITE_EXTERNAL_STORAGE }, REQUEST_STORAGE_WRITE);
            return;
        }
        if (Build.VERSION.SDK_INT >= 30 && !hasSharedStorageAccess()) {
            pendingLocalDelete = file;
            Toast.makeText(this, "Autorisez l’accès complet au stockage pour supprimer ce fichier", Toast.LENGTH_LONG).show();
            requestSharedStorageAccess();
            return;
        }
        deleteLocalInBackground(file);
    }
    private void deleteLocalInBackground(File file) {
        new Thread(() -> {
            try {
                if (file.isFile() && isVideoFile(file.getName())) clearVideoResume(file.getAbsolutePath());
                deleteLocalTree(file);
                runOnUiThread(() -> replaceScreen(createLocalBrowser(file.getParentFile())));
            } catch (Exception error) {
                runOnUiThread(() -> {
                    if (Build.VERSION.SDK_INT <= 29 && checkSelfPermission(Manifest.permission.WRITE_EXTERNAL_STORAGE) != PackageManager.PERMISSION_GRANTED) {
                        pendingLocalDelete = file;
                        Toast.makeText(this, "Autorisez Jojo Home à modifier les fichiers du stockage", Toast.LENGTH_LONG).show();
                        requestPermissions(new String[] { Manifest.permission.WRITE_EXTERNAL_STORAGE }, REQUEST_STORAGE_WRITE);
                    } else if (Build.VERSION.SDK_INT >= 30 && !hasSharedStorageAccess()) {
                        pendingLocalDelete = file;
                        Toast.makeText(this, "Autorisez l’accès complet au stockage pour supprimer ce fichier", Toast.LENGTH_LONG).show();
                        requestSharedStorageAccess();
                    } else if (Build.VERSION.SDK_INT >= 30 && file.isFile() && requestMediaStoreDelete(file)) {
                        // Android affiche sa confirmation système de suppression.
                    } else {
                        Toast.makeText(this, "Suppression impossible : " + file.getName() + " · vérifiez l’autorisation Stockage", Toast.LENGTH_LONG).show();
                    }
                });
            }
        }).start();
    }
    private void deleteLocalTree(File file) throws java.io.IOException {
        deleteLocalTreeDirect(file);
    }
    private void deleteLocalTreeDirect(File file) throws java.io.IOException {
        if (file.isDirectory()) {
            File[] children = file.listFiles();
            if (children == null && file.exists()) throw new java.io.IOException("Lecture du dossier refusée");
            if (children != null) for (File child : children) deleteLocalTreeDirect(child);
        }
        if (!file.delete() && file.exists()) throw new java.io.IOException("Suppression refusée");
    }
    private boolean requestMediaStoreDelete(File file) {
        if (Build.VERSION.SDK_INT < 30 || file == null || !file.isFile()) return false;
        Uri collection = MediaStore.Files.getContentUri("external");
        String[] projection = { MediaStore.Files.FileColumns._ID };
        String selection = MediaStore.Files.FileColumns.DATA + "=?";
        try (Cursor cursor = getContentResolver().query(collection, projection, selection, new String[] { file.getAbsolutePath() }, null)) {
            if (cursor == null || !cursor.moveToFirst()) return false;
            Uri target = ContentUris.withAppendedId(collection, cursor.getLong(0));
            PendingIntent request = MediaStore.createDeleteRequest(getContentResolver(), Collections.singletonList(target));
            pendingLocalDelete = file;
            pendingMediaStoreDelete = true;
            startIntentSenderForResult(request.getIntentSender(), REQUEST_MEDIASTORE_DELETE, null, 0, 0, 0);
            return true;
        } catch (Exception ignored) {
            return false;
        }
    }
    private void deleteSmb(jcifs.smb.SmbFile file, jcifs.CIFSContext context, String user, String password) {
        View originScreen = activeScreen;
        new Thread(() -> {
            try {
                deleteSmbTree(file, this);
                runOnUiThread(() -> {
                    if (activeScreen == originScreen) replaceScreen(createSmbBrowser(file.getParent(), user, password));
                });
            } catch (Exception error) {
                runOnUiThread(() -> Toast.makeText(this, "Suppression impossible : "
                        + error.getMessage(), Toast.LENGTH_LONG).show());
            }
        }).start();
    }

    public static void deleteSmbTree(jcifs.smb.SmbFile file) throws Exception {
        deleteSmbTree(file, null);
    }

    public static void deleteSmbTree(jcifs.smb.SmbFile file, Context context) throws Exception {
        boolean directory = file.getName().endsWith("/");
        MainActivity home = context instanceof MainActivity ? (MainActivity) context : null;
        String signature = "";
        long expectedSize = -1L;
        String phase = "attributes";
        String deletionMethod = "smb";
        try {
            directory = file.isDirectory();
            if (directory) {
                phase = "children";
                for (jcifs.smb.SmbFile child : file.listFiles()) deleteSmbTree(child, context);
            } else {
                if (home != null && home.isVideoFile(file.getName())) signature = home.freeboxFileSignature(file);
                // Remember the size while SMB is readable; it is optional for the API fallback.
                if (context != null) try { expectedSize = file.length(); } catch (jcifs.smb.SmbException ignored) { }
                phase = "release";
                releaseSmbVideoForDeletion(file.getPath());
            }
            phase = "delete";
            file.delete();
            phase = "confirm";
            if (file.exists()) throw new IOException("La Freebox a conservé le fichier après la suppression SMB.");
        } catch (jcifs.smb.SmbException error) {
            android.util.Log.w("JojoHomeSmbDelete", "DELETE_FAILED path=" + comparableSmbPath(file.getPath()).hashCode()
                    + " phase=" + phase + " status=0x" + Integer.toHexString(error.getNtStatus()));
            int status = error.getNtStatus();
            if (!directory && context != null && (status == jcifs.smb.NtStatus.NT_STATUS_ACCESS_DENIED
                    || status == jcifs.smb.NtStatus.NT_STATUS_SHARING_VIOLATION
                    || status == jcifs.smb.NtStatus.NT_STATUS_CANNOT_DELETE)) {
                releaseSmbVideoForDeletion(file.getPath());
                android.util.Log.i("JojoHomeSmbDelete", "DELETE_FALLBACK path=" + comparableSmbPath(file.getPath()).hashCode());
                try {
                    com.nuvio.tv.playercompat.FreeboxResumeDeletionService.deleteSmbViaFreeboxOs(
                            context.getApplicationContext(), file.getPath(), expectedSize);
                } catch (Exception fallbackError) {
                    android.util.Log.w("JojoHomeSmbDelete", "DELETE_FALLBACK_FAILED path="
                            + comparableSmbPath(file.getPath()).hashCode()
                            + " error=" + fallbackError.getClass().getSimpleName());
                    throw fallbackError;
                }
                deletionMethod = "freebox-os";
            } else {
                throw error;
            }
        }
        android.util.Log.i("JojoHomeSmbDelete", "DELETE_CONFIRMED path=" + comparableSmbPath(file.getPath()).hashCode()
                + " via=" + deletionMethod);
        // Run for every confirmed leaf, including episodes in a deleted folder.
        if (!directory && home != null && home.isVideoFile(file.getName())) home.onSmbVideoDeleted(file.getPath(), signature);
    }
    private static class SmbVideoProxy implements Runnable {
        private final jcifs.smb.SmbFile source;
        private final ServerSocket server;
        private volatile boolean running = true;
        private final java.util.Set<Socket> clients = new java.util.HashSet<>();
        private final java.util.Set<Thread> workers = new java.util.HashSet<>();

        SmbVideoProxy(jcifs.smb.SmbFile source, ServerSocket server) {
            this.source = source;
            this.server = server;
        }

        @Override public void run() {
            while (running) {
                try {
                    Socket client = server.accept();
                    android.util.Log.i("JojoHomeFreeboxTrace", "PROXY_CLIENT accepted source=" + source.getPath());
                    // ExoPlayer can keep the initial range request open while
                    // asking for a second range. Handling requests serially
                    // makes the player appear to buffer every few seconds.
                    Thread clientThread = new Thread(() -> {
                        try (Socket connected = client) { handleClient(connected); }
                        catch (Exception error) { if (running) android.util.Log.e("JojoHomeFreeboxTrace", "PROXY_CLIENT_ERROR", error); }
                        finally {
                            synchronized (SmbVideoProxy.this) {
                                clients.remove(client);
                                workers.remove(Thread.currentThread());
                                SmbVideoProxy.this.notifyAll();
                                if (!running && workers.isEmpty()) ACTIVE_SMB_VIDEO_PROXIES.values().remove(SmbVideoProxy.this);
                            }
                        }
                    }, "JojoHomeSmbVideoClient");
                    synchronized (this) {
                        if (!running) {
                            client.close();
                            continue;
                        }
                        clients.add(client);
                        workers.add(clientThread);
                        clientThread.start();
                    }
                } catch (Exception error) {
                    if (running) android.util.Log.e("JojoHomeFreeboxTrace", "PROXY_ACCEPT_ERROR", error);
                }
            }
        }

        private void handleClient(Socket client) throws Exception {
            client.setTcpNoDelay(true);
            client.setReceiveBufferSize(256 * 1024);
            client.setSendBufferSize(256 * 1024);
            try (BufferedInputStream in = new BufferedInputStream(client.getInputStream(), 256 * 1024);
                 BufferedOutputStream out = new BufferedOutputStream(client.getOutputStream(), 256 * 1024);
                 BufferedReader reader = new BufferedReader(new InputStreamReader(in))) {
                String line = reader.readLine();
                if (line == null || !line.startsWith("GET /video")) return;
                long rangeStart = 0;
                long rangeEnd = -1;
                long contentLength = source.getContentLengthLong();
                while (line != null && !line.isEmpty()) {
                    if (line.toLowerCase(Locale.ROOT).startsWith("range:")) {
                        String rangeValue = line.substring(line.indexOf(':') + 1).trim();
                        if (rangeValue.startsWith("bytes=")) {
                            String[] parts = rangeValue.substring(6).split("-");
                            if (parts.length > 0 && !parts[0].isEmpty()) {
                                rangeStart = Long.parseLong(parts[0]);
                            }
                            if (parts.length > 1 && !parts[1].isEmpty()) {
                                rangeEnd = Long.parseLong(parts[1]);
                            }
                        }
                    }
                    line = reader.readLine();
                }
                if (rangeEnd < 0) rangeEnd = contentLength - 1;
                if (rangeStart < 0) rangeStart = 0;
                android.util.Log.i("JojoHomeFreeboxTrace", "PROXY_RANGE start=" + rangeStart + " end=" + rangeEnd + " length=" + contentLength);
                if (rangeStart >= contentLength) {
                    String response = "HTTP/1.1 416 Requested Range Not Satisfiable\r\n" +
                            "Content-Range: bytes */" + contentLength + "\r\n" +
                            "Connection: close\r\n" +
                            "\r\n";
                    out.write(response.getBytes("UTF-8"));
                    android.util.Log.w("JojoHomeFreeboxTrace", "PROXY_RANGE_416 start=" + rangeStart + " length=" + contentLength);
                    return;
                }
                if (rangeEnd >= contentLength) rangeEnd = contentLength - 1;
                long chunkLength = rangeEnd - rangeStart + 1;
                // Seek directly on SMB for every HTTP range. Reopening an
                // SmbFileInputStream and calling skip(rangeStart) made a seek
                // near the end of a large NAS file replay all preceding bytes,
                // which caused ExoPlayer to rebuffer every few seconds.
                try (jcifs.smb.SmbRandomAccessFile sourceStream = new jcifs.smb.SmbRandomAccessFile(source, "r")) {
                    sourceStream.seek(rangeStart);
                    String response = (rangeStart > 0 || rangeEnd < contentLength - 1) ?
                            "HTTP/1.1 206 Partial Content\r\n" : "HTTP/1.1 200 OK\r\n";
                    response += "Content-Type: video/*\r\n" +
                            "Connection: close\r\n" +
                            "Accept-Ranges: bytes\r\n" +
                            "Content-Length: " + chunkLength + "\r\n";
                    if (rangeStart > 0 || rangeEnd < contentLength - 1) {
                        response += "Content-Range: bytes " + rangeStart + "-" + rangeEnd + "/" + contentLength + "\r\n";
                    }
                    response += "\r\n";
                    out.write(response.getBytes("UTF-8"));
                    byte[] buffer = new byte[256 * 1024];
                    long remaining = chunkLength;
                    int count;
                    while (remaining > 0 && running && (count = sourceStream.read(buffer, 0, (int) Math.min(buffer.length, remaining))) != -1) {
                        out.write(buffer, 0, count);
                        remaining -= count;
                    }
                    out.flush();
                    android.util.Log.i("JojoHomeFreeboxTrace", "PROXY_RANGE_DONE start=" + rangeStart + " bytes=" + chunkLength);
                }
            }
        }

        public synchronized void stop() {
            running = false;
            try { server.close(); } catch (Exception ignored) {}
            // Closing only the listening socket leaves existing HTTP readers
            // (and their SMB handles) blocked after the player has exited.
            for (Socket client : clients) {
                try { client.close(); } catch (Exception ignored) {}
            }
            if (workers.isEmpty()) ACTIVE_SMB_VIDEO_PROXIES.values().remove(this);
        }

        private synchronized void awaitStopped() throws Exception {
            long deadline = System.nanoTime() + java.util.concurrent.TimeUnit.SECONDS.toNanos(8);
            while (!workers.isEmpty()) {
                long remaining = deadline - System.nanoTime();
                if (remaining <= 0) throw new IOException("La vidéo est encore utilisée par le lecteur. Réessayez dans quelques secondes.");
                java.util.concurrent.TimeUnit.NANOSECONDS.timedWait(this, remaining);
            }
        }
    }

    private void installSmbApk(jcifs.smb.SmbFile source) throws java.io.IOException {
        String safeName = cleanFileName(source.getName()).replaceAll("[^a-zA-Z0-9._-]", "_");
        File target = new File(getCacheDir(), "install_" + safeName);
        File temporary = new File(getCacheDir(), "install_" + safeName + ".part");
        final int transferBufferSize = 256 * 1024;
        final String displayName = cleanFileName(source.getName());
        showApkInstallProgress(displayName);
        final long totalBytes = source.length();
        updateApkInstallProgress(0, totalBytes, displayName);
        for (int attempt = 0; attempt < 2; attempt++) {
            long copiedBytes = 0;
            int lastPercent = -1;
            try {
                try (java.io.InputStream input = new java.io.BufferedInputStream(new jcifs.smb.SmbFileInputStream(source), transferBufferSize);
                     java.io.OutputStream output = new java.io.BufferedOutputStream(new java.io.FileOutputStream(temporary), transferBufferSize)) {
                    byte[] buffer = new byte[transferBufferSize];
                    int count;
                    while ((count = input.read(buffer)) != -1) {
                        output.write(buffer, 0, count);
                        copiedBytes += count;
                        if (totalBytes > 0) {
                            int percent = (int) ((copiedBytes * 100L) / totalBytes);
                            if (percent != lastPercent) {
                                lastPercent = percent;
                                updateApkInstallProgress(copiedBytes, totalBytes, displayName);
                            }
                        }
                    }
                    output.flush();
                }
                if (copiedBytes <= 0 || temporary.length() != copiedBytes
                        || (totalBytes > 0 && copiedBytes != totalBytes)) {
                    throw new java.io.IOException("Copie APK incomplète : " + copiedBytes + "/" + totalBytes + " octets");
                }
                if (target.exists() && !target.delete()) {
                    throw new java.io.IOException("Impossible de remplacer l’APK temporaire existant");
                }
                if (!temporary.renameTo(target)) {
                    throw new java.io.IOException("Impossible de finaliser l’APK téléchargé");
                }
                updateApkInstallProgress(copiedBytes, copiedBytes, displayName);
                runOnUiThread(() -> installApk(target));
                return;
            } catch (java.io.IOException error) {
                temporary.delete();
                if (attempt == 1) throw error;
                android.util.Log.w("JojoHomeInstall", "Copie SMB APK incomplète, nouvelle tentative", error);
                updateApkInstallProgress(0, totalBytes, displayName);
            }
        }
    }
    private void saveSmbAppIcon(jcifs.smb.SmbFile source) throws java.io.IOException { if (pendingAppIconPackage == null) return; String packageName = pendingAppIconPackage; File target = new File(getFilesDir(), "app_icon_" + packageName.replaceAll("[^a-zA-Z0-9._-]", "_") + ".png"); try (java.io.InputStream input = new jcifs.smb.SmbFileInputStream(source); java.io.FileOutputStream output = new java.io.FileOutputStream(target)) { byte[] buffer = new byte[32 * 1024]; int count; while ((count = input.read(buffer)) != -1) output.write(buffer, 0, count); } homePrefs().edit().putString("app_icon_" + packageName, target.getAbsolutePath()).putBoolean("app_icon_local_override_" + packageName, true).remove("app_icon_online_" + packageName).apply(); markHomeAssetsChangedAndSync(); }
    private void saveSmbWallpaper(jcifs.smb.SmbFile source) throws java.io.IOException {
        String path = source.getName().toLowerCase(Locale.ROOT);
        boolean video = path.endsWith(".mp4") || path.endsWith(".mkv") || path.endsWith(".webm");
        File target = new File(getFilesDir(), video ? "personal_wallpaper_video" : "personal_wallpaper_image");
        File temporary = new File(getFilesDir(), target.getName() + ".part");
        byte[] buffer = new byte[32 * 1024];
        try (java.io.InputStream input = new jcifs.smb.SmbFileInputStream(source);
             java.io.FileOutputStream output = new java.io.FileOutputStream(temporary)) {
            int count;
            while ((count = input.read(buffer)) != -1) output.write(buffer, 0, count);
            output.getFD().sync();
        }
        if (target.exists() && !target.delete()) throw new java.io.IOException("Impossible de remplacer le fond précédent");
        if (!temporary.renameTo(target)) throw new java.io.IOException("Impossible de finaliser la copie SMB");
        homePrefs().edit().putString("wallpaper_uri", Uri.fromFile(target).toString()).putBoolean("wallpaper_video", video).putBoolean("dynamic_wallpaper", false).apply();
        markHomeAssetsChangedAndSync();
    }
    private List<MediaFile> loadMediaFiles() {
        ArrayList<MediaFile> result = new ArrayList<>(); Uri collection = MediaStore.Files.getContentUri("external"); String[] columns = { MediaStore.Files.FileColumns._ID, MediaStore.Files.FileColumns.DISPLAY_NAME, MediaStore.Files.FileColumns.MIME_TYPE, MediaStore.Files.FileColumns.RELATIVE_PATH };
        String selection = MediaStore.Files.FileColumns.MEDIA_TYPE + "=? OR " + MediaStore.Files.FileColumns.MEDIA_TYPE + "=?"; String[] values = { String.valueOf(MediaStore.Files.FileColumns.MEDIA_TYPE_IMAGE), String.valueOf(MediaStore.Files.FileColumns.MEDIA_TYPE_VIDEO) };
        try (Cursor cursor = getContentResolver().query(collection, columns, selection, values, MediaStore.Files.FileColumns.DATE_MODIFIED + " DESC LIMIT 250")) { if (cursor != null) while (cursor.moveToNext()) { long id = cursor.getLong(0); String name = cursor.getString(1), mime = cursor.getString(2), path = cursor.getString(3); result.add(new MediaFile(ContentUris.withAppendedId(collection, id), name == null ? "Média" : name, (mime != null && mime.startsWith("video/") ? "Vidéo" : "Image") + (path == null ? "" : " · " + path))); } } catch (Exception ignored) { }
        return result;
    }
