    private void savePersonalWallpaper(Uri source) throws java.io.IOException {
        String type = getContentResolver().getType(source); String path = source.toString().toLowerCase(Locale.ROOT); boolean video = (type != null && type.startsWith("video/")) || path.endsWith(".mp4") || path.endsWith(".mkv") || path.endsWith(".webm");
        File target = new File(getFilesDir(), video ? "personal_wallpaper_video" : "personal_wallpaper_image"); File temporary = new File(getFilesDir(), target.getName() + ".part"); byte[] buffer = new byte[32 * 1024];
        try (java.io.InputStream input = "file".equals(source.getScheme()) ? new FileInputStream(new File(source.getPath())) : getContentResolver().openInputStream(source); java.io.FileOutputStream output = new java.io.FileOutputStream(temporary)) {
            if (input == null) throw new java.io.IOException("Image indisponible"); int count; while ((count = input.read(buffer)) != -1) output.write(buffer, 0, count); output.getFD().sync();
        }
        if (target.exists() && !target.delete()) throw new java.io.IOException("Impossible de remplacer le fond précédent"); if (!temporary.renameTo(target)) throw new java.io.IOException("Impossible de finaliser la copie");
        homePrefs().edit().putString("wallpaper_uri", Uri.fromFile(target).toString()).putBoolean("wallpaper_video", video).putBoolean("dynamic_wallpaper", false).apply(); markHomeAssetsChangedAndSync();
    }
    private static final int WALLPAPER_MAX_PIXELS = 1_200_000;
    private Bitmap decodeWallpaperBitmap(Uri uri) throws java.io.IOException {
        BitmapFactory.Options bounds = new BitmapFactory.Options();
        bounds.inJustDecodeBounds = true;
        try (InputStream input = "file".equals(uri.getScheme()) ? new FileInputStream(new File(uri.getPath())) : getContentResolver().openInputStream(uri)) {
            if (input == null) throw new java.io.IOException("Fond d’écran indisponible");
            BitmapFactory.decodeStream(input, null, bounds);
        }
        if (bounds.outWidth <= 0 || bounds.outHeight <= 0) throw new java.io.IOException("Image de fond invalide");
        int sample = 1;
        while ((bounds.outWidth / sample) * (long) (bounds.outHeight / sample) > WALLPAPER_MAX_PIXELS) sample *= 2;
        BitmapFactory.Options options = new BitmapFactory.Options();
        options.inSampleSize = sample;
        options.inPreferredConfig = Bitmap.Config.RGB_565;
        try (InputStream input = "file".equals(uri.getScheme()) ? new FileInputStream(new File(uri.getPath())) : getContentResolver().openInputStream(uri)) {
            if (input == null) throw new java.io.IOException("Fond d’écran indisponible");
            return BitmapFactory.decodeStream(input, null, options);
        }
    }
    private void applyPersonalWallpaper(FrameLayout shell) {
        String rawUri = homePrefs().getString("wallpaper_uri", ""); if (rawUri.isEmpty()) return;
        try {
            Uri uri = Uri.parse(rawUri);
            if (homePrefs().getBoolean("wallpaper_video", false)) {
                VideoView video = new VideoView(this); video.setVideoURI(uri); video.setOnPreparedListener(player -> { player.setLooping(true); player.setVolume(0f, 0f); video.start(); }); video.setOnErrorListener((player, what, extra) -> { android.util.Log.w("JojoHomeWallpaper", "Fond vidéo illisible : " + rawUri + " (" + what + ", " + extra + ")"); homePrefs().edit().remove("wallpaper_uri").remove("wallpaper_video").apply(); markHomeAssetsChangedAndSync(); if (video.getParent() instanceof ViewGroup) ((ViewGroup) video.getParent()).removeView(video); return true; }); shell.addView(video, new FrameLayout.LayoutParams(-1, -1));
                return;
            }
            ImageView image = new ImageView(this); image.setScaleType(ImageView.ScaleType.CENTER_CROP); shell.addView(image, new FrameLayout.LayoutParams(-1, -1));
            Bitmap cached;
            synchronized (wallpaperBitmapLock) {
                if (wallpaperBitmapUri != null && !rawUri.equals(wallpaperBitmapUri)) { wallpaperBitmapUri = null; wallpaperBitmap = null; }
                cached = rawUri.equals(wallpaperBitmapUri) ? wallpaperBitmap : null;
                if (cached == null && rawUri.equals(wallpaperLoadingUri)) return;
                if (cached == null) wallpaperLoadingUri = rawUri;
            }
            if (cached != null) { image.setImageBitmap(cached); return; }
            new Thread(() -> {
                Bitmap decoded = null;
                try { decoded = decodeWallpaperBitmap(uri); } catch (Exception | OutOfMemoryError ignored) { }
                final Bitmap result = decoded;
                runOnUiThread(() -> {
                    synchronized (wallpaperBitmapLock) {
                        if (rawUri.equals(wallpaperLoadingUri)) wallpaperLoadingUri = null;
                        if (result != null && rawUri.equals(homePrefs().getString("wallpaper_uri", ""))) { wallpaperBitmapUri = rawUri; wallpaperBitmap = result; }
                    }
                    if (result != null && image.getParent() == shell && rawUri.equals(homePrefs().getString("wallpaper_uri", ""))) image.setImageBitmap(result);
                });
            }, "JojoHomeWallpaper").start();
        } catch (Exception | OutOfMemoryError ignored) { homePrefs().edit().remove("wallpaper_uri").apply(); }
    }
    private Set<String> contentApps() {
        Set<String> selected = homePrefs().getStringSet("content_apps", null);
        if (selected == null) {
            Set<String> defaults = new HashSet<>();
            for (android.content.pm.ResolveInfo info : videoApps()) defaults.add(info.activityInfo.packageName);
            if (defaults.isEmpty()) defaults.add("com.jojo.tv");
            return defaults;
        }
        return new HashSet<>(selected);
    }
    private View createContentAppsPage() {
        useDarkSurfaceTextPalette();
        FrameLayout page = createSettingsShell("Contenu des applications", "Activez les applications dont les reprises et les contenus apparaissent sur l’accueil.");
        LinearLayout content = (LinearLayout) page.getTag();
        Set<String> enabled = contentApps();
        GridLayout grid = new GridLayout(this);
        int screenWidthDp = Math.round(getResources().getDisplayMetrics().widthPixels / getResources().getDisplayMetrics().density);
        int contentWidthDp = screenWidthDp - Math.round(2f * safeEdgeInset() / getResources().getDisplayMetrics().density) - 248;
        int columns = Math.max(1, Math.min(6, contentWidthDp / (iconTileWidth() + 28)));
        grid.setColumnCount(columns);
        grid.setUseDefaultMargins(false);
        grid.setAlignmentMode(GridLayout.ALIGN_MARGINS);
        grid.setClipToPadding(false);
        grid.setClipChildren(false);
        grid.setPadding(0, 0, 0, dp(4));
        ArrayList<View> tiles = new ArrayList<>();
        for (android.content.pm.ResolveInfo info : videoApps()) {
            View tile = contentAppTile(info, enabled.contains(info.activityInfo.packageName));
            tile.setId(View.generateViewId());
            GridLayout.LayoutParams params = new GridLayout.LayoutParams();
            params.width = dp(iconTileWidth() + 8);
            params.height = dp(appBannerHeight() + 32);
            params.setMargins(dp(10), dp(10), dp(10), dp(10));
            grid.addView(tile, params);
            tiles.add(tile);
        }
        ScrollView scroll = new ScrollView(this);
        scroll.setFillViewport(true);
        scroll.addView(grid, new ScrollView.LayoutParams(-1, -2));
        scroll.setVerticalScrollBarEnabled(false);
        content.addView(scroll, new LinearLayout.LayoutParams(-1, 0, 1f));
        if (tiles.isEmpty()) grid.addView(text("Aucune application vidéo compatible installée.", 16, SettingsPresentation.secondaryTextColor()));
        finishSettingsPage(page, grid);
        for (int index = 0; index < tiles.size(); index++) {
            View tile = tiles.get(index);
            if (index % columns > 0) tile.setNextFocusLeftId(tiles.get(index - 1).getId());
            tile.setNextFocusRightId(index % columns < columns - 1 && index + 1 < tiles.size() ? tiles.get(index + 1).getId() : tile.getId());
            if (index >= columns) tile.setNextFocusUpId(tiles.get(index - columns).getId());
            tile.setNextFocusDownId(index + columns < tiles.size() ? tiles.get(index + columns).getId() : tile.getId());
        }
        return page;
    }
    private List<android.content.pm.ResolveInfo> videoApps() {
        List<android.content.pm.ResolveInfo> result = new ArrayList<>();
        for (android.content.pm.ResolveInfo info : allLaunchableApps()) {
            String packageName = info.activityInfo.packageName.toLowerCase(Locale.ROOT);
            String label = homeAppLabel(info).toLowerCase(Locale.ROOT);
            boolean systemPackage = (info.activityInfo.applicationInfo.flags & ApplicationInfo.FLAG_SYSTEM) != 0
                    && (info.activityInfo.applicationInfo.flags & ApplicationInfo.FLAG_UPDATED_SYSTEM_APP) == 0;
            boolean likelyVideoName = label.contains("vidéo") || label.contains("video")
                    || label.contains("tv") || label.contains("iptv") || label.contains("stream")
                    || label.contains("player") || label.contains("media");
            // Many TV streamers (including Nuvio) are not tagged with Android's
            // CATEGORY_VIDEO and do not accept generic video/* intents. Their
            // foreground media-playback permission is their reliable public
            // declaration that they play video/audio for the user.
            boolean declaredMediaPlayback = declaresMediaPlaybackCapability(info.activityInfo.packageName);
            if (packageName.equals("com.jojo.tv")
                    || packageName.equals("com.jojo.tv.debug")
                    || packageName.equals("org.smarttube.beta")
                    || packageName.equals("org.smarttube")
                    || isVideoCategory(info.activityInfo.applicationInfo)
                    || packageName.contains("smarttube")
                    || packageName.contains("netflix")
                    || packageName.contains("kodi")
                    || packageName.contains("tivimate")
                    || packageName.contains("canal")
                    || packageName.contains("mycanal")
                    || NotificationResumeRules.isFreeTvPackage(packageName)
                    || packageName.contains("primevideo")
                    || packageName.contains("disney")
                    || packageName.contains("molotov")
                    || packageName.contains("youtube")
                    || NotificationResumeRules.isTizenTubePackage(packageName)
                    || packageName.contains("plex")
                    || packageName.contains("vlc")
                    // New players do not always set CATEGORY_VIDEO. Prefer
                    // their own advertised video intent, then a conservative
                    // name check for non-system applications.
                    || handlesVideoIntent(info.activityInfo.packageName)
                    || (!systemPackage && declaredMediaPlayback)
                    || (!systemPackage && likelyVideoName)) {
                result.add(info);
            }
        }
        return result;
    }
    private boolean handlesVideoIntent(String packageName) {
        try {
            Intent viewVideo = new Intent(Intent.ACTION_VIEW).setType("video/*").setPackage(packageName);
            return !getPackageManager().queryIntentActivities(viewVideo, 0).isEmpty();
        } catch (Exception ignored) {
            return false;
        }
    }
    private boolean declaresMediaPlaybackCapability(String packageName) {
        try {
            android.content.pm.PackageInfo info = getPackageManager().getPackageInfo(packageName, PackageManager.GET_PERMISSIONS);
            if (info.requestedPermissions == null) return false;
            for (String permission : info.requestedPermissions) {
                if ("android.permission.FOREGROUND_SERVICE_MEDIA_PLAYBACK".equals(permission)
                        || "android.permission.MEDIA_CONTENT_CONTROL".equals(permission)) return true;
            }
        } catch (Exception ignored) { }
        return false;
    }
    private boolean isVideoCategory(android.content.pm.ApplicationInfo applicationInfo) { return Build.VERSION.SDK_INT >= 26 && applicationInfo != null && applicationInfo.category == ApplicationInfo.CATEGORY_VIDEO; }
    private View contentAppTile(android.content.pm.ResolveInfo info, boolean enabled) {
        FrameLayout tile = new FrameLayout(this);
        tile.setTag("content_app_" + info.activityInfo.packageName);
        tile.setBackground(settingsSurfaceBackground(false, false));
        tile.setPadding(dp(4), dp(4), dp(4), dp(4));
        tile.setFocusable(true);
        tile.setContentDescription(info.loadLabel(getPackageManager()));
        String appLabel = homeAppLabel(info);
        TextView focusedTitle = text(appLabel, 13, SettingsPresentation.textColor());
        focusedTitle.setGravity(Gravity.CENTER);
        focusedTitle.setSingleLine(true);
        focusedTitle.setEllipsize(TextUtils.TruncateAt.END);
        tile.setOnFocusChangeListener((v, focused) -> {
            tile.setBackground(settingsSurfaceBackground(focused, false));
            focusedTitle.setTextColor(focused ? contrastingFolderThemeTextColor() : SettingsPresentation.textColor());
            tile.animate().scaleX(focused ? 1.06f : 1f).scaleY(focused ? 1.06f : 1f).setDuration(120).start();
        });

        String packageName = info.activityInfo.packageName;
        android.graphics.drawable.Drawable activityBanner = info.activityInfo.loadBanner(getPackageManager());
        android.graphics.drawable.Drawable applicationBanner = info.activityInfo.applicationInfo.loadBanner(getPackageManager());
        boolean officialCanalPlus = AppTileRules.usesOfficialCanalPlusBanner(packageName);
        android.graphics.drawable.Drawable banner = officialCanalPlus ? officialCanalPlusBanner()
                : (AppTileRules.usesApplicationBannerBeforeActivityBanner() && applicationBanner != null ? applicationBanner : activityBanner);
        android.graphics.drawable.Drawable customIcon = appIconDrawable(packageName);
        String onlineIconId = onlineAppIconId(packageName);
        boolean smartTube = isSmartTube(packageName);
        boolean centeredFallbackIcon = AppTileRules.usesCenteredFallbackIcon(banner != null, customIcon != null || !onlineIconId.isEmpty());
        android.graphics.drawable.Drawable rawSource = customIcon != null ? customIcon
                : (smartTube ? info.loadIcon(getPackageManager()) : (banner != null ? banner : info.loadIcon(getPackageManager())));
        int fallbackTileColor = centeredFallbackIcon ? AppTileRules.fallbackTileColor(packageName) : Color.TRANSPARENT;
        android.graphics.drawable.Drawable source = rawSource;

        FrameLayout iconHolder = new FrameLayout(this);
        iconHolder.setClipToPadding(false);
        iconHolder.setClipChildren(false);

        ImageView icon = new AppIconImageView(this);
        icon.setBackground(smartTube ? smartTubeBg()
                : (fallbackTileColor != Color.TRANSPARENT ? new android.graphics.drawable.ColorDrawable(fallbackTileColor) : new android.graphics.drawable.ColorDrawable(Color.TRANSPARENT)));
        icon.setImageDrawable(source);
        if (!onlineIconId.isEmpty()) OnlineAppIconLoader.load(icon, onlineIconId);
        icon.setScaleType(ImageView.ScaleType.CENTER_INSIDE);
        icon.setPadding(0, 0, 0, 0);
        iconHolder.addView(icon, new FrameLayout.LayoutParams(-1, -1));

        if (enabled) {
            TextView check = text("✓", 14, contrastingFolderThemeTextColor());
            check.setTypeface(null, Typeface.BOLD);
            FrameLayout.LayoutParams checkParams = new FrameLayout.LayoutParams(dp(18), dp(18), Gravity.END | Gravity.TOP);
            checkParams.setMargins(0, dp(3), dp(3), 0);
            check.setBackground(new android.graphics.drawable.GradientDrawable() {{
                setColor(folderButtonThemeColor());
                setShape(GradientDrawable.OVAL);
            }});
            check.setGravity(Gravity.CENTER);
            iconHolder.addView(check, checkParams);
        }

        tile.addView(iconHolder, new FrameLayout.LayoutParams(dp(iconTileWidth()), dp(appBannerHeight()), Gravity.TOP | Gravity.CENTER_HORIZONTAL));
        FrameLayout.LayoutParams titleParams = new FrameLayout.LayoutParams(-1, dp(22), Gravity.BOTTOM | Gravity.CENTER_HORIZONTAL);
        titleParams.setMargins(dp(2), 0, dp(2), 0);
        tile.addView(focusedTitle, titleParams);
        tile.setOnClickListener(v -> {
            Set<String> selected = contentApps();
            if (selected.contains(info.activityInfo.packageName)) selected.remove(info.activityInfo.packageName);
            else selected.add(info.activityInfo.packageName);
            homePrefs().edit().putStringSet("content_apps", selected).apply();
            pendingSettingsFocus = "content_app_" + info.activityInfo.packageName;
            replaceScreen(createContentAppsPage());
        });
        tile.setOnLongClickListener(v -> { showAppMenu(info, tile); return true; });
        return tile;
    }
    /** Prevent Android's focus search from using the next vertical section as a horizontal overflow. */
    private boolean keepHorizontalFocus(View view, int keyCode, KeyEvent event) {
        if (event.getAction() != KeyEvent.ACTION_DOWN || event.getRepeatCount() != 0
                || (keyCode != KeyEvent.KEYCODE_DPAD_LEFT && keyCode != KeyEvent.KEYCODE_DPAD_RIGHT)) return false;
        if (!(view.getParent() instanceof ViewGroup)) return false;
        ViewGroup row = (ViewGroup) view.getParent();
        int position = row.indexOfChild(view);
        if (keyCode == KeyEvent.KEYCODE_DPAD_LEFT && position == 0) {
            int target = view.getNextFocusLeftId();
            return target == View.NO_ID || target == view.getId();
        }
        if (keyCode == KeyEvent.KEYCODE_DPAD_RIGHT && position == row.getChildCount() - 1) {
            int target = view.getNextFocusRightId();
            return target == View.NO_ID || target == view.getId();
        }
        return false;
    }
    private void openPackage(String packageName, String label) {
        if (getPackageName().equals(packageName)) {
            goHome();
            return;
        }
        Intent intent = getPackageManager().getLeanbackLaunchIntentForPackage(packageName);
        if (intent == null) intent = getPackageManager().getLaunchIntentForPackage(packageName);
        if (intent != null) {
            noteSmartTubeLaunch(packageName);
            startActivity(intent);
        } else Toast.makeText(this, label + " indisponible", Toast.LENGTH_SHORT).show();
    }
